private struct AllProjectsCreativeResetSummary: Hashable {
    var projectCount: Int
    var archivedItemCount: Int
    var archiveDirectoryCount: Int

    var statusText: String {
        let projectLabel = "\(projectCount) project\(projectCount == 1 ? "" : "s")"
        let archiveLabel = archivedItemCount == 0
            ? "no prior creative files archived"
            : "archived \(archivedItemCount) creative item\(archivedItemCount == 1 ? "" : "s")"
        return "Updated \(projectLabel); \(archiveLabel); media analysis preserved"
    }
}

private struct AllProjectsCreativeResetMarker: Codable {
    var schemaVersion = allProjectsCreativeResetMarkerSchemaVersion
    var completedAt: String
    var projectCount: Int
    var archivedItemCount: Int
    var archiveDirectoryCount: Int
}

struct AestheticAnalysisHealth: Equatable {
    var enabledCount = 0
    var savedObservationCount = 0
    var freshObservationCount = 0
    var staleObservationCount = 0
    var missingObservationCount = 0
    var modifiedObservationCount = 0

    var hasWarning: Bool {
        staleObservationCount > 0 || missingObservationCount > 0 || modifiedObservationCount > 0
    }

    var warningTitle: String {
        if modifiedObservationCount > 0 {
            return "Media has changed since analysis"
        }
        if staleObservationCount > 0 {
            return "Media analysis is out of date"
        }
        return "Some media has not been analyzed"
    }

    var warningDetail: String {
        var parts: [String] = []
        if modifiedObservationCount > 0 {
            parts.append("\(modifiedObservationCount) modified")
        }
        if staleObservationCount > 0 {
            parts.append("\(staleObservationCount) old-schema")
        }
        if missingObservationCount > 0 {
            parts.append("\(missingObservationCount) missing")
        }
        let summary = parts.isEmpty ? "Analysis is incomplete" : parts.joined(separator: ", ")
        return "\(summary) across \(enabledCount) enabled media item\(enabledCount == 1 ? "" : "s"). AESTHETIC can continue, but Analyze Media will improve direction quality."
    }
}

struct InitialDraftLensHeroProgress: Equatable, Sendable {
    var imageId: String = ""
    var lensTitle: String = ""
    var providerLabel: String = ""
    var status: String = "queued"
}

struct InitialDraftLensGenerationProgress: Equatable, Sendable {
    var title: String = ""
    var detail: String = ""
    var status: String = "idle"
    var completedStepCount: Int = 0
    var totalStepCount: Int = 0
    var lensTitles: [String] = []
    var heroStatuses: [String] = []
    var heroRows: [InitialDraftLensHeroProgress] = []

    static let idle = InitialDraftLensGenerationProgress()

    var isActive: Bool {
        totalStepCount > 0 && !title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    var isFailed: Bool {
        status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "failed"
    }

    var fractionCompleted: Double {
        guard totalStepCount > 0 else { return 0 }
        return min(max(Double(completedStepCount) / Double(totalStepCount), 0), 1)
    }
}

struct SceneStorySchemaPreview: Equatable, Sendable {
    var title: String = ""
    var json: String = ""

    static let empty = SceneStorySchemaPreview()

    var isVisible: Bool {
        !json.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
}

