private enum LensHeroImageProvider: String, Sendable {
    case openAI = "openai"
    case stability = "stability"
    case civitaiWan27 = "civitai"
    case fal = "fal"

    var label: String {
        switch self {
        case .openAI: "OpenAI"
        case .stability: "Stability"
        case .civitaiWan27: "WAN 2.7"
        case .fal: "FAL"
        }
    }

    var model: String {
        switch self {
        case .openAI: "gpt-image-2"
        case .stability: StabilityAIClient.ultraModel
        case .civitaiWan27: "wan.v2.7.text-to-image"
        case .fal: "fal"
        }
    }

    var imageIndex: Int {
        switch self {
        case .openAI: 0
        case .stability: 1
        case .civitaiWan27: 2
        case .fal: 3
        }
    }

    var promptInstructions: String {
        switch self {
        case .openAI:
            """
            OpenAI gpt-image-2 prompts should be direct, specific, and visually rich. Describe the subject, environment, composition, mood, lighting, camera or rendering treatment, materials, colors, and any exact constraints. The model follows natural language well, supports detailed production-quality visuals, and benefits from clear accuracy boundaries when the image must preserve a real project world. Avoid unsupported transparent-background instructions for gpt-image-2.
            """
        case .stability:
            """
            Stability Stable Image Ultra prompts should clearly define what to generate with strong visual descriptors: subject, important elements, colors, lighting, composition, theme, style, mood, and medium. Keep the positive prompt focused on desired visual content and use negative_prompt for concise exclusions such as artifacts, incorrect anatomy, extra text, logos, unwanted styles, or terms the Lens says to avoid.
            """
        case .civitaiWan27:
            """
            Civitai WAN 2.7 prompts should be self-contained text-to-image requests. Keep the style in text as a concise one-line visual direction and avoid relying on image attachments.
            """
        case .fal:
            """
            FAL image prompts should be model-aware, concrete, and parameter-clean. Describe the visible subject, layout, material, lighting, and mood without including output dimensions, aspect ratios, crop instructions, seed, CFG, sampler, or provider parameter syntax. When a style image is attached, keep the text focused on subject and composition and rely on the attachment for rendering style.
            """
        }
    }

}

private extension LensHeroImageProvider {
    /// Thin bridge for call sites that only know the provider: delegates to
    /// the registry stack's data-driven recipe when one maps; keeps the legacy
    /// inline recipe only for unmapped providers (stability).
    func renderRecipeSnapshot(
        mediaPlan: LensMediaPlan?,
        isCharacterStudy: Bool,
        hasStyleReferences: Bool,
        seed: Int? = nil,
        stack: RenderStack? = nil,
        sourceImageCount: Int = 0,
        usesCompositeImage: Bool = false
    ) -> LensRenderRecipeSnapshot {
        let registry = RenderStackRegistry.shared
        let resolved: RenderStack? = stack ?? {
            switch self {
            case .openAI: return registry.stack(id: RenderStackID.openAIBase)
            case .civitaiWan27: return registry.stack(id: RenderStackID.wan)
            case .fal, .stability: return nil
            }
        }()
        if let resolved {
            return resolved.renderRecipeSnapshot(
                mediaPlan: mediaPlan,
                styleMode: .describeStyleInPrompt,
                isCharacterStudy: isCharacterStudy,
                hasStyleReferences: hasStyleReferences,
                seed: seed,
                imageSizeOverride: stack == nil ? mediaPlan?.normalized().imageSize : nil,
                sourceImageCount: sourceImageCount,
                usesCompositeImage: usesCompositeImage
            )
        }
        let plan = mediaPlan?.normalized()
        let outputFormat = self == .openAI && isCharacterStudy ? "png" : "jpeg"
        var parameters: [LensRenderRecipeParameter] = [
            LensRenderRecipeParameter(key: "output_format", value: outputFormat)
        ]
        if self == .stability {
            parameters.append(contentsOf: [
                LensRenderRecipeParameter(key: "aspect_ratio", value: plan?.stabilityAspectRatio ?? "1:1"),
                LensRenderRecipeParameter(key: "quality", value: "ultra")
            ])
        }
        var capabilities = ["textToImage"]
        if isCharacterStudy {
            capabilities.append("identityPreservation")
        }
        return LensRenderRecipeSnapshot(
            label: label,
            provider: rawValue,
            model: model,
            stackId: nil,
            parameters: parameters,
            capabilities: capabilities
        ).normalized()
    }
}

extension RenderStack {
    /// The low-level execution bucket for this stack's kind.
    fileprivate var heroProvider: LensHeroImageProvider {
        switch kind {
        case .openai: .openAI
        case .civitai: .civitaiWan27
        case .fal: .fal
        case .stability: .stability
        }
    }
}

private struct LensHeroGenerationJob: Sendable {
    var lensId: String
    var imageId: String
    var provider: LensHeroImageProvider
    var stack: RenderStack? = nil
    var styleMode: LensRenderStyleMode = .none
    var debugParametersJSON: String = ""
    var promptImageReferenceMode: Bool = false
    /// Original references represented by the provider attachment. Stability can
    /// transmit one native image, so this can exceed attachments.count when the
    /// transmitted image is a labeled composite.
    var sourceImageCount: Int = 0
    var usesCompositeImage: Bool = false
    var skipPromptEnrichment: Bool = false
    var prompt: String
    var sourcePrompt: String
    var negativePrompt: String
    /// Ordered attachment plan (styles by weight, characters, continuity). Attachment
    /// order, filenames, and the prompt manifest all come from this one plan.
    var attachments: [LensBlendAttachmentEntry] = []
    /// Verbatim single-style directive prepended to the prompt BEFORE the enriched
    /// description ("In the style of the attached image, generate the following:").
    var promptPreamble: String = ""
    /// Verbatim manifest describing the non-style attachments; appended to the prompt
    /// AFTER LLM enrichment so filenames and order can never be rewritten.
    var attachmentManifest: String = ""
    /// One-line description of the attached style (from the catalog's style-reference
    /// analysis), injected verbatim beside the style image — never enriched. Empty when
    /// no style image is attached.
    var styleSummary: String = ""
    /// Verbatim "Mood influences" block built from the user's selected moodboard
    /// analysis lines; appended AFTER the (possibly enriched) scene text and BEFORE the
    /// attachment manifest so enrichment can never rewrite or delete the influences.
    var moodInfluenceBlock: String = ""
    /// Verbatim medium-preset block (FILMED / ANIMATED / ILLUSTRATED / PAINTED);
    /// rides outside enrichment like the mood block. Empty when no preset chosen.
    var mediumBlock: String = ""
    /// The manifest split for the Responses path: the dynamic attachment lines stay in
    /// the user prompt while the static style-only policy joins the system instructions.
    var attachmentManifestEntries: String = ""
    var attachmentStylePolicy: String = ""
    /// OpenAI image size ("1024x1024", "1536x1024", "1024x1536") from the lens media plan.
    var imageSize: String = "1024x1024"
    /// Stability aspect ratio ("1:1", "3:2", "2:3") from the lens media plan.
    var stabilityAspectRatio: String = "1:1"
    /// Per-render Stability reference fidelity (0 ≈ identical to the input
    /// image); nil = the stack's declared strength.
    var stabilityStrength: Double? = nil
    /// Structured Lens media plan used by provider-specific parameter builders.
    var mediaPlan: LensMediaPlan = LensMediaPlan()
    /// Character studies keep an isolated-study intent and PNG output so a future
    /// provider that supports alpha can use it without changing the job shape.
    var transparentBackground: Bool = false
    var civitaiSeed: Int? = nil
    /// Reorients a CivitAI stack's declared canvas for this job (roster
    /// character studies render portrait/square, never the FRAMES 16:9
    /// policy). Both or neither; nil keeps the stack's own size.
    var civitaiWidthOverride: Int? = nil
    var civitaiHeightOverride: Int? = nil
    /// Reference sheets are deliberately multi-panel: the single-frame guard that
    /// every other render appends must stay out of their prompts.
    var allowsMultiPanelLayout: Bool = false
    /// Per-job Stability aspect that outranks the stack's declared canvas (portrait
    /// sheets on a stack whose YAML says 16:9).
    var stabilityAspectRatioOverride: String? = nil
    /// Operation geometry and its immutable source. Zoom Out uses these directly
    /// instead of disguising an outpaint as a style-reference render.
    var reframe: LensReframeSpec? = nil
    var reframeSourcePath: String = ""
    var outputURL: URL
    var projectId: String
    var runId: String
    var workflowName: String = "lenses"

    /// Which rewrite the enrichment step needs, from what this job actually
    /// transmits. Style scrubbing outranks subject references verbatim as
    /// before — an attached style image is the sole rendering authority, and
    /// style words left in the text override it. What changed is the third
    /// case: references that carry the SUBJECT used to fall through to the
    /// text-only rewrite, whose "no other context, complete and
    /// self-contained" premise is false whenever they ride, so it invented
    /// scenery that contradicted them.
    ///
    /// Transmission is read from the attachment plan itself, not just the
    /// `promptImageReferenceMode` flag: only two of the seven job builders
    /// ever set the flag, and a forgotten flag must degrade to the honest
    /// mode, never to the self-contained rewrite beside riding references.
    /// (The stored flag keeps its separate FAL payload meaning — which
    /// references ride the request — untouched.)
    var enrichmentReferenceMode: ImagePromptReferenceMode {
        imagePromptReferenceMode(
            styleMode: styleMode,
            promptImageReferenceMode: promptImageReferenceMode || !attachments.isEmpty,
            hasStyleAttachment: attachments.contains(where: \.isStyle),
            subjectReferenceCount: attachments.filter { !$0.isStyle }.count
        )
    }
}

private struct LensHeroGenerationOutcome: Sendable {
    var lensId: String
    var imageId: String
    var provider: LensHeroImageProvider
    var status: String
    var imagePath: String
    var prompt: String
    var sourcePrompt: String
    var negativePrompt: String
    var promptEnrichmentModel: String
    var promptEnrichmentResponseId: String
    var promptEnrichmentTraceId: String
    var promptEnrichmentSummary: String
    var requestId: String
    var traceId: String
    var errorMessage: String
    var generatedAt: String
    var updatedAt: String
    var renderRecipe: LensRenderRecipeSnapshot?
}

/// Hard single-image directive woven into every final render prompt — some
/// models (notably nano-banana) otherwise author collages or panel grids when
/// a prompt implies sequence. Positive-prompt only: FAL and OpenAI image APIs
/// accept no negative prompt.
let lensSingleFrameGuard = "Render exactly one single continuous image filling the whole frame. Never a collage, grid, storyboard, diptych, triptych, split frame, multi-panel layout, or contact sheet."

/// The Responses image path splits the request into system-role instructions and
/// a content-only user prompt; the persisted row echoes this exact join so the
/// stored prompt never overstates what the provider received.
func lensResponsesTransmittedPrompt(instructions: String, userPrompt: String) -> String {
    [instructions, userPrompt]
        .filter { !$0.isEmpty }
        .joined(separator: "\n\n")
}

/// Content half of the Responses request, mirroring `finalPrompt`'s segment order
/// with the static directives (preamble, style policy) removed to the system role.
/// The single-frame guard is baked in, not a parameter: every final render prompt
/// carries it, and this path — where composite reference sheets ride as input
/// images and subject-only renders have no style policy — must not be the
/// exception. Ratified (responses-wire-block-parity).
func lensResponsesUserPrompt(
    styleSummaryLine: String,
    enhancedPrompt: String,
    mediumBlock: String,
    moodInfluenceBlock: String,
    manifestEntries: String,
    includeSingleFrameGuard: Bool = true
) -> String {
    [styleSummaryLine, enhancedPrompt, mediumBlock.trimmed, moodInfluenceBlock.trimmed, includeSingleFrameGuard ? lensSingleFrameGuard : "", manifestEntries.trimmed]
        .filter { !$0.isEmpty }
        .joined(separator: "\n\n")
}

private enum LensHeroImageRunner {
    static func generate(
        job: LensHeroGenerationJob,
        openAIClient: OpenAIClient?,
        stabilityClient: StabilityAIClient?,
        civitaiImageProvider: CivitAIWANImageProvider? = nil,
        falImageClient: FALImageClient? = nil
    ) async -> LensHeroGenerationOutcome {
        let startedAt = Date()
        // Stored prompts may carry @Name roster-mention tokens (planner- or
        // creator-authored). The render text is token-stripped; outcomes echo the
        // stored text so completion never erases the authored mentions.
        let storedSourcePrompt = job.sourcePrompt.trimmed.isEmpty ? job.prompt : job.sourcePrompt
        let sourcePrompt = RosterMentionResolver.strippingMentionTokens(storedSourcePrompt)
        let imageModel = job.stack?.model ?? job.provider.model
        let providerInstructions = job.stack?.promptInstructions.nilIfEmpty ?? job.provider.promptInstructions
        do {
            if job.provider == .civitaiWan27 {
                let civitaiSource = [sourcePrompt, job.mediumBlock.trimmed, job.moodInfluenceBlock.trimmed, job.allowsMultiPanelLayout ? "" : lensSingleFrameGuard]
                    .filter { !$0.isEmpty }
                    .joined(separator: "\n\n")
                let finalPrompt = civitaiWANPrompt(sourcePrompt: civitaiSource, styleSummary: job.styleSummary)
                let result = try await generateImageData(
                    job: job,
                    prompt: finalPrompt,
                    enhancedPrompt: sourcePrompt,
                    styleSummaryLine: job.styleSummary,
                    negativePrompt: job.negativePrompt,
                    openAIClient: openAIClient,
                    stabilityClient: stabilityClient,
                    civitaiImageProvider: civitaiImageProvider,
                    falImageClient: falImageClient
                )
                try Task.checkCancellation()
                try result.imageData.write(to: job.outputURL, options: [.atomic])
                let generatedAt = DateFormats.now()
                let durationMs = Int(Date().timeIntervalSince(startedAt) * 1000)
                print("[lens_hero_image] completed provider=\(job.provider.rawValue) image_id=\(job.imageId) duration_ms=\(durationMs) request_id=\(result.requestId)")
                return LensHeroGenerationOutcome(
                    lensId: job.lensId,
                    imageId: job.imageId,
                    provider: job.provider,
                    status: "ready",
                    imagePath: job.outputURL.path,
                    prompt: result.transmittedPrompt ?? finalPrompt,
                    sourcePrompt: storedSourcePrompt,
                    negativePrompt: job.negativePrompt,
                    promptEnrichmentModel: "",
                    promptEnrichmentResponseId: "",
                    promptEnrichmentTraceId: "",
                    promptEnrichmentSummary: "",
                    requestId: result.requestId,
                    traceId: result.traceId,
                    errorMessage: "",
                    generatedAt: generatedAt,
                    updatedAt: generatedAt,
                    renderRecipe: nil
                )
            }
            if job.skipPromptEnrichment {
                let styleSummaryLine: String
                if job.styleSummary.trimmed.isEmpty {
                    styleSummaryLine = ""
                } else if job.styleMode == .describeStyleInPrompt {
                    styleSummaryLine = "Style direction: \(job.styleSummary.trimmed)"
                } else {
                    styleSummaryLine = "The attached style in one line: \(job.styleSummary.trimmed)"
                }
                let finalPrompt = [job.promptPreamble.trimmed, styleSummaryLine, sourcePrompt, job.mediumBlock.trimmed, job.moodInfluenceBlock.trimmed, job.allowsMultiPanelLayout ? "" : lensSingleFrameGuard, job.attachmentManifest.trimmed]
                    .filter { !$0.isEmpty }
                    .joined(separator: "\n\n")
                let result = try await generateImageData(
                    job: job,
                    prompt: finalPrompt,
                    enhancedPrompt: sourcePrompt,
                    styleSummaryLine: styleSummaryLine,
                    negativePrompt: job.negativePrompt,
                    openAIClient: openAIClient,
                    stabilityClient: stabilityClient,
                    civitaiImageProvider: civitaiImageProvider,
                    falImageClient: falImageClient
                )
                try Task.checkCancellation()
                try result.imageData.write(to: job.outputURL, options: [.atomic])
                let generatedAt = DateFormats.now()
                let durationMs = Int(Date().timeIntervalSince(startedAt) * 1000)
                print("[lens_hero_image] completed provider=\(job.provider.rawValue) image_id=\(job.imageId) duration_ms=\(durationMs) request_id=\(result.requestId)")
                return LensHeroGenerationOutcome(
                    lensId: job.lensId,
                    imageId: job.imageId,
                    provider: job.provider,
                    status: "ready",
                    imagePath: job.outputURL.path,
                    prompt: result.transmittedPrompt ?? finalPrompt,
                    sourcePrompt: storedSourcePrompt,
                    negativePrompt: job.negativePrompt,
                    promptEnrichmentModel: "",
                    promptEnrichmentResponseId: "",
                    promptEnrichmentTraceId: "",
                    promptEnrichmentSummary: "",
                    requestId: result.requestId,
                    traceId: result.traceId,
                    errorMessage: "",
                    generatedAt: generatedAt,
                    updatedAt: generatedAt,
                    renderRecipe: result.renderRecipe
                )
            }
            guard let openAIClient else {
                throw ScreenGraphError.credentials("OPENAI_API_KEY is required for \(job.provider.label) prompt enrichment.")
            }
            print("[lens_hero_prompt_enrichment] starting provider=\(job.provider.rawValue) image_id=\(job.imageId) model=\(imageModel)")
            let enrichment = try await openAIClient.enhanceImagePrompt(
                originalPrompt: sourcePrompt,
                provider: job.provider.label,
                imageModel: imageModel,
                providerInstructions: providerInstructions,
                referenceMode: job.enrichmentReferenceMode,
                projectId: job.projectId,
                runId: "\(job.runId)_prompt",
                traceGroupId: job.runId,
                traceWorkflowName: job.workflowName,
                traceWorkflowStep: "lens_hero_prompt_enrichment",
                traceArtifactType: "lens_hero",
                traceArtifactId: job.runId
            )
            try Task.checkCancellation()
            let enhancedPrompt = enrichment.enhancedPrompt.trimmed
            // The style directive, one-line style summary, and attachment manifest wrap
            // the enriched text verbatim: the scene description may be rewritten freely,
            // but the single-style instruction, the disciplined style line, and the
            // filenames/order must exactly mirror the payload. The style line rides
            // OUTSIDE enrichment so style-scrub mode can never delete it.
            let styleSummaryLine: String
            if job.styleSummary.trimmed.isEmpty {
                styleSummaryLine = ""
            } else if job.styleMode == .describeStyleInPrompt {
                styleSummaryLine = "Style direction: \(job.styleSummary.trimmed)"
            } else {
                styleSummaryLine = "The attached style in one line: \(job.styleSummary.trimmed)"
            }
            let finalPrompt = [job.promptPreamble.trimmed, styleSummaryLine, enhancedPrompt, job.mediumBlock.trimmed, job.moodInfluenceBlock.trimmed, job.allowsMultiPanelLayout ? "" : lensSingleFrameGuard, job.attachmentManifest.trimmed]
                .filter { !$0.isEmpty }
                .joined(separator: "\n\n")
            let negativePrompt = job.provider == .stability ? enrichment.negativePrompt.trimmed : ""
            print("[lens_hero_prompt_enrichment] completed provider=\(job.provider.rawValue) image_id=\(job.imageId) response_id=\(enrichment.responseId)")
            let result = try await generateImageData(
                job: job,
                prompt: finalPrompt,
                enhancedPrompt: enhancedPrompt,
                styleSummaryLine: styleSummaryLine,
                negativePrompt: negativePrompt,
                openAIClient: openAIClient,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider,
                falImageClient: falImageClient
            )
            try Task.checkCancellation()
            try result.imageData.write(to: job.outputURL, options: [.atomic])
            let generatedAt = DateFormats.now()
            let durationMs = Int(Date().timeIntervalSince(startedAt) * 1000)
            print("[lens_hero_image] completed provider=\(job.provider.rawValue) image_id=\(job.imageId) duration_ms=\(durationMs) request_id=\(result.requestId)")
            return LensHeroGenerationOutcome(
                lensId: job.lensId,
                imageId: job.imageId,
                provider: job.provider,
                status: "ready",
                imagePath: job.outputURL.path,
                prompt: result.transmittedPrompt ?? finalPrompt,
                sourcePrompt: storedSourcePrompt,
                negativePrompt: negativePrompt,
                promptEnrichmentModel: enrichment.model,
                promptEnrichmentResponseId: enrichment.responseId,
                promptEnrichmentTraceId: enrichment.traceId,
                promptEnrichmentSummary: enrichment.changeSummary,
                requestId: result.requestId,
                traceId: result.traceId,
                errorMessage: "",
                generatedAt: generatedAt,
                updatedAt: generatedAt,
                renderRecipe: result.renderRecipe
            )
        } catch {
            let failedAt = DateFormats.now()
            let status = Task.isCancelled || error is CancellationError ? "cancelled" : "failed"
            let durationMs = Int(Date().timeIntervalSince(startedAt) * 1000)
            let workflowFailure = error as? CivitAIWorkflowFailure
            let falFailure = error as? FALWorkflowFailure
            print("[lens_hero_image] error provider=\(job.provider.rawValue) image_id=\(job.imageId) status=\(status) duration_ms=\(durationMs) message=\"\(error.localizedDescription)\"")
            return LensHeroGenerationOutcome(
                lensId: job.lensId,
                imageId: job.imageId,
                provider: job.provider,
                status: status,
                imagePath: "",
                prompt: job.prompt,
                sourcePrompt: storedSourcePrompt,
                negativePrompt: job.negativePrompt,
                promptEnrichmentModel: "",
                promptEnrichmentResponseId: "",
                promptEnrichmentTraceId: "",
                promptEnrichmentSummary: "",
                requestId: workflowFailure?.jobId ?? falFailure?.jobId ?? "",
                traceId: workflowFailure?.traceId ?? falFailure?.traceId ?? "",
                errorMessage: workflowFailure?.localizedDescription ?? falFailure?.localizedDescription ?? error.localizedDescription,
                generatedAt: "",
                updatedAt: failedAt,
                renderRecipe: nil
            )
        }
    }

    private static func civitaiWANPrompt(sourcePrompt: String, styleSummary: String) -> String {
        let styleLine = styleSummary.trimmed.isEmpty ? "" : "Style: \(styleSummary.trimmed)"
        let prompt = [styleLine, sourcePrompt.trimmed]
            .filter { !$0.isEmpty }
            .joined(separator: "\n\n")
        return providerPromptLimited(prompt, maxCharacters: 1_800)
    }

    private static func providerPromptLimited(_ prompt: String, maxCharacters: Int) -> String {
        let cleaned = prompt
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
            .split(separator: "\n", omittingEmptySubsequences: false)
            .map { String($0).trimmed }
            .joined(separator: "\n")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard cleaned.count > maxCharacters else { return cleaned }
        var prefix = String(cleaned.prefix(maxCharacters))
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if let boundary = prefix.lastIndex(where: { $0 == "." || $0 == ";" || $0 == "," || $0 == "\n" }),
           prefix.distance(from: prefix.startIndex, to: boundary) > maxCharacters / 2 {
            prefix = String(prefix[..<boundary])
                .trimmingCharacters(in: .whitespacesAndNewlines)
        } else if let boundary = prefix.lastIndex(where: { $0 == " " || $0 == "\n" }),
                  prefix.distance(from: prefix.startIndex, to: boundary) > maxCharacters / 2 {
            prefix = String(prefix[..<boundary])
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
        return prefix
    }

    private static func generateImageData(
        job: LensHeroGenerationJob,
        prompt: String,
        enhancedPrompt: String,
        styleSummaryLine: String,
        negativePrompt: String,
        openAIClient: OpenAIClient?,
        stabilityClient: StabilityAIClient?,
        civitaiImageProvider: CivitAIWANImageProvider?,
        falImageClient: FALImageClient?
    ) async throws -> (imageData: Data, requestId: String, traceId: String, renderRecipe: LensRenderRecipeSnapshot?, transmittedPrompt: String?) {
        if let reframe = job.reframe?.normalized(), reframe.isZoomOut {
            return try await generateZoomOutImageData(
                job: job,
                spec: reframe,
                prompt: prompt,
                openAIClient: openAIClient,
                falImageClient: falImageClient
            )
        }
        switch job.provider {
        case .openAI:
            guard let openAIClient else {
                throw ScreenGraphError.credentials("OPENAI_API_KEY is required for OpenAI Scene Plan generation.")
            }
            // Keep alpha-capable output for isolated studies, but do not request
            // provider-side transparency from current OpenAI image models.
            let outputFormat = job.transparentBackground ? "png" : "jpeg"
            let background = ""
            if !job.attachments.isEmpty {
                let sources = try await attachmentEditSources(job.attachments)
                guard !sources.isEmpty else {
                    throw ScreenGraphError.capture("No verified reference images were available for Scene Plan generation.")
                }
                let providerPrompt = providerAttachmentText(
                    prompt,
                    entries: job.attachments,
                    sources: sources
                )
                if ResponsesImageAPISettings.isEnabled() {
                    // Static instructions (the single-style directive and the style-only
                    // policy) move to the system role; the user prompt carries this job's
                    // content in finalPrompt's order — style summary, scene, medium, mood
                    // influences, the single-frame guard, and the dynamic attachment lines.
                    let instructions = [job.promptPreamble.trimmed, job.attachmentStylePolicy.trimmed]
                        .filter { !$0.isEmpty }
                        .joined(separator: "\n\n")
                    let providerManifestEntries = providerAttachmentText(
                        job.attachmentManifestEntries,
                        entries: job.attachments,
                        sources: sources
                    )
                    let userPrompt = lensResponsesUserPrompt(
                        styleSummaryLine: styleSummaryLine,
                        enhancedPrompt: enhancedPrompt,
                        mediumBlock: job.mediumBlock,
                        moodInfluenceBlock: job.moodInfluenceBlock,
                        manifestEntries: providerManifestEntries,
                        includeSingleFrameGuard: !job.allowsMultiPanelLayout
                    )
                    // The split still differs from the composed finalPrompt (system-role
                    // instructions, entry lines without the policy) — persist the
                    // transmitted text.
                    let transmittedPrompt = lensResponsesTransmittedPrompt(
                        instructions: instructions,
                        userPrompt: userPrompt
                    )
                    let result = try await openAIClient.generateImageViaResponses(
                        prompt: userPrompt,
                        instructions: instructions,
                        sources: sources,
                        imageModel: job.provider.model,
                        size: job.imageSize,
                        quality: "medium",
                        outputFormat: outputFormat,
                        background: background,
                        projectId: job.projectId,
                        runId: job.runId,
                        traceWorkflowName: job.workflowName,
                        traceWorkflowStep: "lens_hero_image_responses",
                        traceArtifactType: "lens_hero",
                        traceArtifactId: job.runId
                    )
                    return (result.imageData, result.requestId, result.traceId, nil, transmittedPrompt)
                }
                let result = try await openAIClient.generateImageEdit(
                    prompt: providerPrompt,
                    sources: sources,
                    model: job.provider.model,
                    size: job.imageSize,
                    quality: "medium",
                    outputFormat: outputFormat,
                    background: background,
                    projectId: job.projectId,
                    runId: job.runId,
                    traceWorkflowName: job.workflowName,
                    traceWorkflowStep: "lens_hero_image_reference",
                    traceArtifactType: "lens_hero",
                    traceArtifactId: job.runId
                )
                return (result.imageData, result.requestId, result.traceId, nil, providerPrompt)
            }
            let result = try await openAIClient.generateProofImage(
                prompt: prompt,
                model: job.provider.model,
                size: job.imageSize,
                quality: "medium",
                outputFormat: outputFormat,
                outputCompression: 70,
                background: background,
                projectId: job.projectId,
                runId: job.runId,
                traceOperation: "lens_hero",
                traceWorkflowName: job.workflowName,
                traceWorkflowStep: "lens_hero",
                traceArtifactType: "lens_hero",
                traceArtifactId: job.runId
            )
            // Proof path sends `prompt` verbatim — the composed text is faithful.
            return (result.imageData, result.requestId, result.traceId, nil, nil)
        case .stability:
            guard let stabilityClient else {
                throw ScreenGraphError.credentials("STABILITY_AI_API_KEY is required to generate Stability AI frames.")
            }
            let sourceEntries = Array(job.attachments.prefix(1))
            let sources = try await attachmentEditSources(sourceEntries)
            // Never silently degrade to text-to-image while the prompt still
            // carries the reference manifest (mirrors the OpenAI guard).
            if !sourceEntries.isEmpty, sources.isEmpty {
                throw ScreenGraphError.capture("No verified reference images were available for Scene Plan generation.")
            }
            let source = sources.first
            let providerPrompt = providerAttachmentText(prompt, entries: sourceEntries, sources: sources)
            let stabilityPrompt = providerPromptLimited(providerPrompt, maxCharacters: job.stack?.promptLimit ?? 10_000)
            let result = try await stabilityClient.generateLensHero(
                prompt: stabilityPrompt,
                negativePrompt: negativePrompt,
                aspectRatio: job.stabilityAspectRatioOverride ?? job.stack?.stabilityAspectRatio ?? job.stabilityAspectRatio,
                outputFormat: job.stack?.outputFormat ?? "jpeg",
                source: source,
                // Reference fidelity: the per-render override wins, else the
                // stack's declared strength, else Stability's prompt-leaning
                // default (0 ≈ identical to the input image).
                strength: job.stabilityStrength ?? job.stack?.stabilityStrength ?? 0.65,
                projectId: job.projectId,
                runId: job.runId,
                traceWorkflowName: job.workflowName
            )
            let recipe = job.stack?.renderRecipeSnapshot(
                mediaPlan: job.mediaPlan,
                styleMode: job.styleMode,
                sourceImageCount: job.sourceImageCount,
                usesCompositeImage: job.usesCompositeImage
            )
            return (result.imageData, result.requestId, result.traceId, recipe, stabilityPrompt)
        case .civitaiWan27:
            guard let civitaiImageProvider else {
                throw ScreenGraphError.credentials("CivitAI image provider is unavailable.")
            }
            let result = try await civitaiImageProvider.generateImage(from: CivitAIWANImageRequest(
                artifactId: job.imageId,
                prompt: prompt,
                negativePrompt: negativePrompt,
                seed: job.civitaiSeed,
                stack: job.stack ?? RenderStackRegistry.shared.stack(id: RenderStackID.wan) ?? RenderStackRegistry.shared.fallback,
                widthOverride: job.civitaiWidthOverride,
                heightOverride: job.civitaiHeightOverride,
                traceGroupId: job.runId
            ))
            // CivitAI sends `prompt` verbatim — the composed text is faithful.
            return (result.imageData, result.providerJobId, result.traceId, nil, nil)
        case .fal:
            guard let falImageClient else {
                throw ScreenGraphError.credentials("FAL_API_KEY or FAL_KEY is required to generate FAL frames.")
            }
            guard let stack = job.stack, stack.isFAL else {
                throw ScreenGraphError.capture("FAL Scene Plan generation requires a FAL render stack.")
            }
            let styleReferences: [FALImageReference]
            let referenceEntries: [LensBlendAttachmentEntry]
            let sources: [OpenAIImageEditSource]
            if job.styleMode == .attachStyleImage {
                // The declared per-model slot count (not the provider kind)
                // decides how many references ride the request.
                let slotLimit = max(stack.nativePromptImageLimit ?? 1, 1)
                referenceEntries = job.promptImageReferenceMode
                    ? Array(job.attachments.prefix(slotLimit))
                    : Array(job.attachments.filter(\.isStyle).prefix(slotLimit))
                sources = try await attachmentEditSources(referenceEntries)
                guard !sources.isEmpty else {
                    throw ScreenGraphError.capture("No verified reference image was available for FAL image attachment.")
                }
                styleReferences = sources.map { source in
                    FALImageReference(
                        data: source.data,
                        mimeType: source.mimeType,
                        fileName: source.fileName,
                        role: source.role.isEmpty ? (job.promptImageReferenceMode ? "prompt_image" : "style") : source.role,
                        title: source.title
                    )
                }
            } else {
                referenceEntries = []
                sources = []
                styleReferences = []
            }
            let providerPrompt = providerAttachmentText(prompt, entries: referenceEntries, sources: sources)
            let result = try await falImageClient.generateImage(from: FALImageGenerationRequest(
                artifactId: job.imageId,
                stack: stack,
                prompt: providerPrompt,
                mediaPlan: job.mediaPlan,
                styleMode: job.styleMode,
                styleReferences: styleReferences,
                debugParametersJSON: job.debugParametersJSON,
                projectId: job.projectId,
                runId: job.runId,
                traceGroupId: job.runId,
                workflowName: job.workflowName
            ))
            let recipe = stack.renderRecipeSnapshot(
                mediaPlan: job.mediaPlan,
                styleMode: job.styleMode,
                debugParametersJSON: job.debugParametersJSON,
                generatedParameters: result.parameters
            )
            // FAL receives the composed prompt (attachment filenames normalized);
            // the client's character bound is recorded in the inference trace.
            return (result.imageData, result.providerJobId, result.traceId, recipe, nil)
        }
    }

    fileprivate struct ZoomOutSource {
        var image: CGImage
        var data: Data
        var width: Int
        var height: Int
    }

    fileprivate struct OpenAIZoomOutInput {
        var source: OpenAIImageEditSource
        var mask: OpenAIImageEditSource
        var plan: LensZoomOutGeometry.CanvasPlan
        var geometry: LensZoomOutGeometry.ProviderGeometry
    }

    private struct FALZoomOutInput {
        var source: ZoomOutSource
        var expandLeft: Int
        var expandRight: Int
        var expandTop: Int
        var expandBottom: Int
    }

    private static func generateZoomOutImageData(
        job: LensHeroGenerationJob,
        spec: LensReframeSpec,
        prompt: String,
        openAIClient: OpenAIClient?,
        falImageClient: FALImageClient?
    ) async throws -> (imageData: Data, requestId: String, traceId: String, renderRecipe: LensRenderRecipeSnapshot?, transmittedPrompt: String?) {
        guard let stack = job.stack, stack.supportsReframe(mode: LensReframeSpec.zoomOutMode) else {
            throw ScreenGraphError.capture("Zoom Out requires an executable outpaint render stack.")
        }
        let source = try zoomOutSource(path: job.reframeSourcePath)
        let providerResult: (data: Data, requestId: String, traceId: String, recipe: LensRenderRecipeSnapshot?, transmittedPrompt: String?)
        let providerGeometry: LensZoomOutGeometry.ProviderGeometry

        switch job.provider {
        case .openAI:
            guard let openAIClient else {
                throw ScreenGraphError.credentials("OPENAI_API_KEY is required for OpenAI Zoom Out.")
            }
            let prepared = try openAIZoomOutInput(source: source, spec: spec)
            // The continuation preamble is injected at this client boundary, so
            // the wire text differs from the composed prompt — persist it.
            let wirePrompt = LensZoomOutPrompt.openAIWirePrompt(operatorPrompt: prompt)
            let result = try await openAIClient.generateImageEdit(
                prompt: wirePrompt,
                sources: [prepared.source],
                mask: prepared.mask,
                model: stack.model,
                size: prepared.plan.sizeString,
                quality: "medium",
                outputFormat: "png",
                projectId: job.projectId,
                runId: job.runId,
                traceWorkflowName: job.workflowName,
                traceWorkflowStep: "reframe_zoom_out_openai",
                traceArtifactType: "lens_hero",
                traceArtifactId: job.imageId
            )
            let recipe = stack.renderRecipeSnapshot(
                mediaPlan: job.mediaPlan,
                styleMode: .none,
                generatedParameters: [
                    LensRenderRecipeParameter(key: "operation", value: "zoom_out"),
                    LensRenderRecipeParameter(key: "output_format", value: "png"),
                    LensRenderRecipeParameter(key: "image_size", value: prepared.plan.sizeString),
                    LensRenderRecipeParameter(key: "quality", value: "medium"),
                    LensRenderRecipeParameter(key: "source_scale", value: "\(spec.zoomOutSourceScale)", valueType: "number"),
                    LensRenderRecipeParameter(key: "source_fidelity", value: "provider_native")
                ],
                imageSizeOverride: prepared.plan.sizeString,
                sourceImageCount: 1
            )
            providerResult = (result.imageData, result.requestId, result.traceId, recipe, wirePrompt)
            providerGeometry = prepared.geometry
        case .fal:
            guard let falImageClient else {
                throw ScreenGraphError.credentials("FAL_API_KEY or FAL_KEY is required for FAL Zoom Out.")
            }
            let prepared = try falZoomOutInput(source: source, spec: spec)
            let sourceReference = FALImageReference(
                data: prepared.source.data,
                mimeType: "image/png",
                fileName: "zoom-out-source.png",
                role: "reframe_source",
                title: "Source frame"
            )
            // FAL Outpaint appends the prompt to its own base outpaint
            // instruction and treats it as content, so only the operator's
            // zoom-out body rides — never the style line, single-frame guard,
            // or the runner's other instruction blocks.
            let falOperatorPrompt = RosterMentionResolver.strippingMentionTokens(
                job.sourcePrompt.trimmed.isEmpty ? job.prompt : job.sourcePrompt
            )
            let result = try await falImageClient.generateImage(from: FALImageGenerationRequest(
                artifactId: job.imageId,
                stack: stack,
                prompt: falOperatorPrompt,
                mediaPlan: job.mediaPlan,
                styleMode: .none,
                outpaintInput: FALImageOutpaintInput(
                    source: sourceReference,
                    expandLeft: prepared.expandLeft,
                    expandRight: prepared.expandRight,
                    expandTop: prepared.expandTop,
                    expandBottom: prepared.expandBottom
                ),
                debugParametersJSON: job.debugParametersJSON,
                projectId: job.projectId,
                runId: job.runId,
                traceGroupId: job.runId,
                workflowName: job.workflowName
            ))
            let generatedParameters = result.parameters + [
                LensRenderRecipeParameter(key: "operation", value: "zoom_out"),
                LensRenderRecipeParameter(key: "source_scale", value: "\(spec.zoomOutSourceScale)", valueType: "number"),
                LensRenderRecipeParameter(key: "provider_source_width", value: "\(prepared.source.width)", valueType: "number"),
                LensRenderRecipeParameter(key: "provider_source_height", value: "\(prepared.source.height)", valueType: "number"),
                LensRenderRecipeParameter(key: "source_fidelity", value: "provider_native")
            ]
            let recipe = stack.renderRecipeSnapshot(
                mediaPlan: job.mediaPlan,
                styleMode: .none,
                debugParametersJSON: job.debugParametersJSON,
                generatedParameters: generatedParameters
            )
            // Only the operator body rides the FAL outpaint wire (never the
            // style line or instruction blocks) — persist that body, not the
            // composed prompt that claims otherwise.
            providerResult = (result.imageData, result.providerJobId, result.traceId, recipe, falOperatorPrompt)
            providerGeometry = LensZoomOutGeometry.ProviderGeometry(
                canvasWidth: prepared.expandLeft + prepared.source.width + prepared.expandRight,
                canvasHeight: prepared.expandTop + prepared.source.height + prepared.expandBottom,
                sourceRegion: CGRect(
                    x: prepared.expandLeft,
                    y: prepared.expandTop,
                    width: prepared.source.width,
                    height: prepared.source.height
                )
            )
        default:
            throw ScreenGraphError.capture("\(stack.label) cannot execute Zoom Out.")
        }

        let sourceRect = LensZoomOutGeometry.normalizedSourceRect(spec)
        let finalOutput = try zoomOutProviderComposite(
            generatedData: providerResult.data,
            source: source,
            spec: spec,
            geometry: providerGeometry
        )
        await InferenceTraceStore.shared.enrich(
            traceId: providerResult.traceId,
            parsedOutputJSON: inferenceTraceJSONString([
                "operation": "reframe_zoom_out",
                "source_fidelity": "provider_native",
                "composite": finalOutput.composite,
                "perimeter_match": finalOutput.perimeterMatch,
                "source_sha256": sha256Hex(source.data),
                "source_width": source.width,
                "source_height": source.height,
                "source_rect": [
                    "x": sourceRect.minX,
                    "y": sourceRect.minY,
                    "width": sourceRect.width,
                    "height": sourceRect.height
                ],
                "final_sha256": sha256Hex(finalOutput.data),
                "final_bytes": finalOutput.data.count
            ])
        )
        return (finalOutput.data, providerResult.requestId, providerResult.traceId, providerResult.recipe, providerResult.transmittedPrompt)
    }

    fileprivate static func zoomOutSource(path: String) throws -> ZoomOutSource {
        let normalizedPath = path.trimmed
        guard !normalizedPath.isEmpty else {
            throw ScreenGraphError.capture("Zoom Out source path is missing.")
        }
        let data = try Data(contentsOf: URL(fileURLWithPath: normalizedPath))
        guard let imageSource = CGImageSourceCreateWithData(data as CFData, nil),
              let image = CGImageSourceCreateImageAtIndex(imageSource, 0, nil) else {
            throw ScreenGraphError.capture("Could not decode the Zoom Out source image.")
        }
        return ZoomOutSource(image: image, data: data, width: image.width, height: image.height)
    }

    /// Builds the outpaint upload on a canvas the provider can actually
    /// return (`plan.sizeString` is requested explicitly). Planning in the
    /// provider's own pixel space is what lets the final composite honor the
    /// chosen source placement and scale; a source-dims canvas with
    /// `size: "auto"` cannot be aligned afterwards.
    private static func openAIZoomOutInput(
        source: ZoomOutSource,
        spec: LensReframeSpec
    ) throws -> OpenAIZoomOutInput {
        guard let plan = LensZoomOutGeometry.canvasPlan(
            sourceWidth: source.width,
            sourceHeight: source.height,
            spec: spec
        ) else {
            throw ScreenGraphError.capture("Could not plan the OpenAI Zoom Out canvas.")
        }
        return try openAIOutpaintInput(source: source, plan: plan)
    }

    /// Builds the transparent-canvas + white-rect-mask upload pair for any
    /// planned outpaint placement. Zoom Out and terrain growth share this;
    /// only the plan differs.
    fileprivate static func openAIOutpaintInput(
        source: ZoomOutSource,
        plan: LensZoomOutGeometry.CanvasPlan
    ) throws -> OpenAIZoomOutInput {
        let width = plan.canvasWidth
        let height = plan.canvasHeight
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        guard let sourceContext = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ), let maskContext = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create the OpenAI Zoom Out canvas.")
        }
        let sourceRect = plan.sourceDrawRect
        sourceContext.clear(CGRect(x: 0, y: 0, width: width, height: height))
        sourceContext.interpolationQuality = .high
        sourceContext.draw(source.image, in: sourceRect)
        maskContext.clear(CGRect(x: 0, y: 0, width: width, height: height))
        maskContext.setFillColor(CGColor(gray: 1, alpha: 1))
        maskContext.fill(sourceRect)
        guard let sourceCanvas = sourceContext.makeImage(),
              let mask = maskContext.makeImage() else {
            throw ScreenGraphError.capture("Could not render the OpenAI Zoom Out source and mask.")
        }
        return OpenAIZoomOutInput(
            source: OpenAIImageEditSource(
                data: try pngData(from: sourceCanvas),
                mimeType: "image/png",
                fileName: "zoom-out-source.png",
                label: "locked-source",
                role: "reframe_source",
                title: "Source frame"
            ),
            mask: OpenAIImageEditSource(
                data: try pngData(from: mask),
                mimeType: "image/png",
                fileName: "zoom-out-mask.png",
                label: "outpaint-mask",
                role: "mask",
                title: "Transparent perimeter generation mask"
            ),
            plan: plan,
            geometry: LensZoomOutGeometry.providerGeometry(for: plan)
        )
    }

    /// Fits the provider source to FAL's 700-pixel per-edge contract while
    /// preserving the requested normalized source rectangle. Independent
    /// margin clamping would move or resize the source relative to the result.
    private static func falZoomOutInput(
        source: ZoomOutSource,
        spec: LensReframeSpec
    ) throws -> FALZoomOutInput {
        let sourceRect = LensZoomOutGeometry.normalizedSourceRect(spec)
        let sourceScale = Double(sourceRect.width)
        guard sourceScale > 0 else {
            throw ScreenGraphError.capture("Zoom Out source scale must be greater than zero.")
        }
        let leftRatio = Double(sourceRect.minX) / sourceScale
        let rightRatio = Double(1 - sourceRect.maxX) / sourceScale
        let topRatio = Double(sourceRect.minY) / sourceScale
        let bottomRatio = Double(1 - sourceRect.maxY) / sourceScale
        // Leave one pixel of rounding headroom under the documented 700 maximum.
        let safeEdgeLimit = 699.0
        let horizontalRatio = max(leftRatio, rightRatio)
        let verticalRatio = max(topRatio, bottomRatio)
        let widthLimit = horizontalRatio > 0 ? safeEdgeLimit / horizontalRatio : Double(source.width)
        let heightLimit = verticalRatio > 0 ? safeEdgeLimit / verticalRatio : Double(source.height)
        let longestEdgeScale = min(1, 1024.0 / Double(max(source.width, source.height)))
        let geometryScale = min(
            1,
            widthLimit / Double(source.width),
            heightLimit / Double(source.height)
        )
        let inputScale = min(longestEdgeScale, geometryScale)
        guard inputScale > 0 else {
            throw ScreenGraphError.capture("Could not fit Zoom Out geometry within FAL's expansion limits.")
        }
        let width = max(1, Int(floor(Double(source.width) * inputScale)))
        let height = max(1, Int(floor(Double(source.height) * inputScale)))
        let preparedSource: ZoomOutSource
        if width == source.width, height == source.height {
            preparedSource = ZoomOutSource(
                image: source.image,
                data: try pngData(from: source.image),
                width: source.width,
                height: source.height
            )
        } else {
            let rendered = try renderImage(source.image, width: width, height: height, alpha: true)
            preparedSource = ZoomOutSource(
                image: rendered,
                data: try pngData(from: rendered),
                width: width,
                height: height
            )
        }
        let outputWidth = max(width, Int((Double(width) / sourceScale).rounded()))
        let outputHeight = max(height, Int((Double(height) / sourceScale).rounded()))
        let expandLeft = max(0, Int((Double(sourceRect.minX) * Double(outputWidth)).rounded()))
        let expandTop = max(0, Int((Double(sourceRect.minY) * Double(outputHeight)).rounded()))
        let expandRight = max(0, outputWidth - width - expandLeft)
        let expandBottom = max(0, outputHeight - height - expandTop)
        let expansions = [expandLeft, expandRight, expandTop, expandBottom]
        guard expansions.allSatisfy({ $0 <= 700 }) else {
            throw ScreenGraphError.capture("Could not preserve Zoom Out placement within FAL's 700-pixel edge limit.")
        }
        return FALZoomOutInput(
            source: preparedSource,
            expandLeft: expandLeft,
            expandRight: expandRight,
            expandTop: expandTop,
            expandBottom: expandBottom
        )
    }

    /// Normalizes the provider result to the source's aspect and dimensions.
    /// The provider's pixels are the final pixels: FAL preserves the source
    /// region natively and gpt-image re-renders it coherently with its
    /// perimeter, so nothing is stamped over the result — the aligned mapping
    /// only guarantees the wider frame honors the chosen placement and scale,
    /// and the exposure match pulls the whole layer toward the original.
    private static func zoomOutProviderComposite(
        generatedData: Data,
        source: ZoomOutSource,
        spec: LensReframeSpec,
        geometry: LensZoomOutGeometry.ProviderGeometry?
    ) throws -> (data: Data, composite: String, perimeterMatch: String) {
        guard let generatedSource = CGImageSourceCreateWithData(generatedData as CFData, nil),
              let generated = CGImageSourceCreateImageAtIndex(generatedSource, 0, nil) else {
            throw ScreenGraphError.capture("Could not decode the generated Zoom Out image.")
        }
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        guard let context = CGContext(
            data: nil,
            width: source.width,
            height: source.height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create the Zoom Out output canvas.")
        }
        let canvas = CGRect(x: 0, y: 0, width: source.width, height: source.height)
        context.setFillColor(CGColor(gray: 0, alpha: 1))
        context.fill(canvas)
        context.interpolationQuality = .high
        let sourceTargetRect = pixelRect(
            LensZoomOutGeometry.normalizedSourceRect(spec),
            width: source.width,
            height: source.height
        )
        let composite: String
        var perimeterMatch = "unavailable"
        if let geometry, let drawRect = LensZoomOutGeometry.alignedDrawRect(
            generatedWidth: generated.width,
            generatedHeight: generated.height,
            geometry: geometry,
            sourceTargetRect: sourceTargetRect,
            outputWidth: source.width,
            outputHeight: source.height
        ) {
            // The provider's own rendition of the source region reveals its
            // global exposure drift; pull the whole layer toward the original
            // so the child render stays tonally consistent with its parent.
            var generatedLayer = generated
            if let providerRegion = LensZoomOutGeometry.scaledSourceRegion(
                generatedWidth: generated.width,
                generatedHeight: generated.height,
                geometry: geometry
            ) {
                let match = LensZoomOutColorMatch.harmonizedPerimeter(
                    generated: generated,
                    providerSourceRegion: providerRegion,
                    original: source.image
                )
                if let corrected = match.image {
                    generatedLayer = corrected
                }
                perimeterMatch = match.detail
            }
            context.saveGState()
            context.clip(to: canvas)
            context.draw(generatedLayer, in: drawRect)
            context.restoreGState()
            composite = "aligned"
        } else {
            drawAspectFill(generated, in: canvas, context: context)
            composite = "aspect_fill_fallback"
        }
        guard let finalImage = context.makeImage() else {
            throw ScreenGraphError.capture("Could not render the Zoom Out image.")
        }
        return (try pngData(from: finalImage), composite, perimeterMatch)
    }

    /// Maps the provider result into the grown canvas, harmonizes exposure
    /// against the original, then re-stamps the ORIGINAL canvas pixels over
    /// the prior-content rect with a feathered alpha edge toward the new
    /// terrain. This deliberately reverses the zoom-out "provider pixels are
    /// final" law for THIS surface only: the map is a persistent document
    /// that is repeatedly re-submitted and cropped, so N growth passes must
    /// not N-times re-render (and drift) the seeded world. A result that
    /// cannot be aligned is refused — an aspect-fill fallback would silently
    /// shift every pin's geography.
    fileprivate static func terrainGrowthComposite(
        generatedData: Data,
        source: ZoomOutSource,
        plan: TerrainGrowthPlan
    ) throws -> (data: Data, composite: String, perimeterMatch: String) {
        guard let generatedSource = CGImageSourceCreateWithData(generatedData as CFData, nil),
              let generated = CGImageSourceCreateImageAtIndex(generatedSource, 0, nil) else {
            throw ScreenGraphError.capture("Could not decode the generated terrain image.")
        }
        let width = plan.newCanvasWidth
        let height = plan.newCanvasHeight
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create the terrain output canvas.")
        }
        let canvas = CGRect(x: 0, y: 0, width: width, height: height)
        context.setFillColor(CGColor(gray: 0, alpha: 1))
        context.fill(canvas)
        context.interpolationQuality = .high
        let stampRect = pixelRect(plan.priorContentRect, width: width, height: height)
        let geometry = LensZoomOutGeometry.providerGeometry(for: plan.providerPlan)
        guard let drawRect = LensZoomOutGeometry.alignedDrawRect(
            generatedWidth: generated.width,
            generatedHeight: generated.height,
            geometry: geometry,
            sourceTargetRect: stampRect,
            outputWidth: width,
            outputHeight: height
        ) else {
            throw ScreenGraphError.capture("The provider result could not be aligned to the map — nothing was committed.")
        }
        var generatedLayer = generated
        var perimeterMatch = "unavailable"
        if let providerRegion = LensZoomOutGeometry.scaledSourceRegion(
            generatedWidth: generated.width,
            generatedHeight: generated.height,
            geometry: geometry
        ) {
            let match = LensZoomOutColorMatch.harmonizedPerimeter(
                generated: generated,
                providerSourceRegion: providerRegion,
                original: source.image
            )
            if let corrected = match.image {
                generatedLayer = corrected
            }
            perimeterMatch = match.detail
        }
        context.saveGState()
        context.clip(to: canvas)
        context.draw(generatedLayer, in: drawRect)
        context.restoreGState()
        // Re-stamp the original at native resolution with feathered edges
        // toward the newly generated terrain (hard on canvas-boundary edges).
        let stampWidth = max(1, Int(stampRect.width.rounded()))
        let stampHeight = max(1, Int(stampRect.height.rounded()))
        guard let stampContext = CGContext(
            data: nil,
            width: stampWidth,
            height: stampHeight,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create the terrain stamp canvas.")
        }
        stampContext.interpolationQuality = .high
        stampContext.draw(source.image, in: CGRect(x: 0, y: 0, width: stampWidth, height: stampHeight))
        let edges = TerrainMapGeometry.stampFeatherEdges(priorContentRect: plan.priorContentRect)
        let feather = TerrainMapGeometry.stampFeatherWidth(
            stampSize: CGSize(width: stampWidth, height: stampHeight)
        )
        if feather > 0 {
            let fade = CGGradient(
                colorsSpace: colorSpace,
                colors: [
                    CGColor(gray: 1, alpha: 0),
                    CGColor(gray: 1, alpha: 1)
                ] as CFArray,
                locations: [0, 1]
            )
            if let fade {
                stampContext.setBlendMode(.destinationIn)
                // Stamp-local CG coordinates (bottom-left origin): the
                // top-left-normalized "top" edge is the CG maxY side.
                var bands: [(band: CGRect, start: CGPoint, end: CGPoint)] = []
                if edges.left {
                    bands.append((
                        CGRect(x: 0, y: 0, width: feather, height: CGFloat(stampHeight)),
                        CGPoint(x: 0, y: 0),
                        CGPoint(x: feather, y: 0)
                    ))
                }
                if edges.right {
                    bands.append((
                        CGRect(x: CGFloat(stampWidth) - feather, y: 0, width: feather, height: CGFloat(stampHeight)),
                        CGPoint(x: CGFloat(stampWidth), y: 0),
                        CGPoint(x: CGFloat(stampWidth) - feather, y: 0)
                    ))
                }
                if edges.top {
                    bands.append((
                        CGRect(x: 0, y: CGFloat(stampHeight) - feather, width: CGFloat(stampWidth), height: feather),
                        CGPoint(x: 0, y: CGFloat(stampHeight)),
                        CGPoint(x: 0, y: CGFloat(stampHeight) - feather)
                    ))
                }
                if edges.bottom {
                    bands.append((
                        CGRect(x: 0, y: 0, width: CGFloat(stampWidth), height: feather),
                        CGPoint(x: 0, y: 0),
                        CGPoint(x: 0, y: feather)
                    ))
                }
                for band in bands {
                    stampContext.saveGState()
                    stampContext.clip(to: band.band)
                    stampContext.drawLinearGradient(fade, start: band.start, end: band.end, options: [])
                    stampContext.restoreGState()
                }
            }
        }
        guard let stampImage = stampContext.makeImage() else {
            throw ScreenGraphError.capture("Could not render the terrain stamp.")
        }
        context.draw(stampImage, in: stampRect)
        guard let finalImage = context.makeImage() else {
            throw ScreenGraphError.capture("Could not render the grown terrain map.")
        }
        return (try pngData(from: finalImage), "aligned_source_stamped", perimeterMatch)
    }

    private static func renderImage(
        _ image: CGImage,
        width: Int,
        height: Int,
        alpha: Bool
    ) throws -> CGImage {
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        let alphaInfo = alpha ? CGImageAlphaInfo.premultipliedLast : CGImageAlphaInfo.noneSkipLast
        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: alphaInfo.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create a bounded Zoom Out source.")
        }
        context.interpolationQuality = .high
        context.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))
        guard let rendered = context.makeImage() else {
            throw ScreenGraphError.capture("Could not render a bounded Zoom Out source.")
        }
        return rendered
    }

    private static func pixelRect(_ normalizedRect: CGRect, width: Int, height: Int) -> CGRect {
        CGRect(
            x: normalizedRect.minX * CGFloat(width),
            y: (1 - normalizedRect.maxY) * CGFloat(height),
            width: normalizedRect.width * CGFloat(width),
            height: normalizedRect.height * CGFloat(height)
        )
    }

    private static func drawAspectFill(_ image: CGImage, in rect: CGRect, context: CGContext) {
        let scale = max(rect.width / CGFloat(image.width), rect.height / CGFloat(image.height))
        let size = CGSize(width: CGFloat(image.width) * scale, height: CGFloat(image.height) * scale)
        let drawRect = CGRect(
            x: rect.midX - size.width / 2,
            y: rect.midY - size.height / 2,
            width: size.width,
            height: size.height
        )
        context.saveGState()
        context.clip(to: rect)
        context.draw(image, in: drawRect)
        context.restoreGState()
    }

    private static func providerAttachmentText(
        _ value: String,
        entries: [LensBlendAttachmentEntry],
        sources: [OpenAIImageEditSource]
    ) -> String {
        zip(entries, sources).reduce(value) { text, pair in
            let (entry, source) = pair
            guard entry.attachmentFilename != source.fileName else { return text }
            return text.replacingOccurrences(of: entry.attachmentFilename, with: source.fileName)
        }
    }

    /// Materializes the attachment plan into provider-ready sources, preserving the
    /// plan's exact order. Style entries download through the sha-verified SREF cache;
    /// local entries are content-validated rather than trusted by extension. Unsupported
    /// ImageIO-decodable formats such as HEIC become sRGB JPEGs before a paid request.
    private static func attachmentEditSources(_ entries: [LensBlendAttachmentEntry]) async throws -> [OpenAIImageEditSource] {
        var sources: [OpenAIImageEditSource] = []
        var styleFailures: [String] = []
        let styleCount = entries.filter(\.isStyle).count
        for (index, entry) in entries.enumerated() {
            if let reference = entry.reference {
                do {
                    let cachedURL = try await SREFReferenceImageCache.shared.cachedFileURL(for: reference)
                    let data = try Data(contentsOf: cachedURL)
                    guard sha256Hex(data) == reference.sha256 else {
                        throw ScreenGraphError.capture("Cached style reference failed SHA-256 verification.")
                    }
                    let ready = try providerReadyImage(from: data)
                    let filename = providerAttachmentFilename(
                        entry.attachmentFilename,
                        fileExtension: ready.fileExtension
                    )
                    logProviderReadyAttachment(ready, index: index, role: entry.role.rawValue, inputBytes: data.count)
                    sources.append(OpenAIImageEditSource(
                        data: ready.data,
                        mimeType: ready.mimeType,
                        fileName: filename,
                        label: entry.role == .primary ? "primary-\(entry.sharePercent)pct" : "\(entry.role.rawValue)-\(entry.sharePercent)pct",
                        role: entry.role.rawValue,
                        sharePercent: entry.sharePercent,
                        title: reference.title
                    ))
                } catch {
                    styleFailures.append("\(reference.title): \(error.localizedDescription)")
                    print("[lens_hero_image] style_reference error item_id=\(reference.itemId) message=\"\(error.localizedDescription)\"")
                }
            } else if let url = entry.localURL {
                let data: Data
                do {
                    data = try Data(contentsOf: url)
                } catch {
                    throw ScreenGraphError.capture(
                        "Attachment \(entry.attachmentFilename) could not be read: \(error.localizedDescription)"
                    )
                }
                let ready: ProviderReadyImage
                do {
                    ready = try providerReadyImage(from: data)
                } catch {
                    throw ScreenGraphError.capture(
                        "Attachment \(entry.attachmentFilename) is not a valid provider image: \(error.localizedDescription)"
                    )
                }
                let filename = providerAttachmentFilename(
                    entry.attachmentFilename,
                    fileExtension: ready.fileExtension
                )
                logProviderReadyAttachment(ready, index: index, role: entry.role.rawValue, inputBytes: data.count)
                sources.append(OpenAIImageEditSource(
                    data: ready.data,
                    mimeType: ready.mimeType,
                    fileName: filename,
                    label: entry.role.rawValue,
                    role: entry.role.rawValue,
                    sharePercent: 0,
                    title: entry.characterName ?? entry.caption ?? ""
                ))
            }
        }
        if styleCount > 0, !sources.contains(where: { $0.role == LensBlendAttachmentEntry.Role.primary.rawValue || $0.role == LensBlendAttachmentEntry.Role.accent.rawValue }) {
            throw ScreenGraphError.capture(styleFailures.first ?? "No verified style reference images were available.")
        }
        return sources
    }

    private static func providerAttachmentFilename(_ filename: String, fileExtension: String) -> String {
        let base = URL(fileURLWithPath: filename).deletingPathExtension().lastPathComponent
        return "\(base.trimmed.isEmpty ? "source" : base).\(fileExtension)"
    }

    private static func logProviderReadyAttachment(
        _ ready: ProviderReadyImage,
        index: Int,
        role: String,
        inputBytes: Int
    ) {
        print(
            "[lens_hero_image] attachment_ready index=\(index + 1) role=\(role) source_type=\(ready.sourceTypeIdentifier) output_mime=\(ready.mimeType) converted=\(ready.wasConverted) input_bytes=\(inputBytes) output_bytes=\(ready.data.count) width=\(ready.width) height=\(ready.height)"
        )
    }
}

enum ScreenAreaRecordingPhase: String, Equatable {
    case idle
    case needsPermission
    case selecting
    case starting
    case recording
    case finalizing
    case failed
}

/// A cross-tab hand-off: the Media surface asks the Scenes workbench to open
/// the Frame Creator for a lens with these library images pre-attached in its
/// reference well. The workbench consumes and clears it.
struct FrameCreatorSeedRequest: Equatable {
    let lensId: String
    let mediaIds: [String]
    let requestedAt: Date
}

/// A cross-tab hand-off: Media's Creations section asks the Scenes workbench
/// to land on a lens and (when imageId is set) open that take's magnified
/// preview. The workbench consumes and clears it.
struct WorkbenchFocusRequest: Equatable {
    let lensId: String
    let imageId: String
    let requestedAt: Date
}

