    var activeSceneFreshness: StoryArtifactFreshness {
        let context = currentSceneSourceContext()
        let acceptedStory = context.sourceArtifactType == .projectStory ? projectStory : .empty(projectId: currentProject?.projectId ?? "")
        return sceneWorkspace.freshness(activeBoard: context.board, acceptedStory: acceptedStory)
    }

    var storyAudioFreshness: StoryArtifactFreshness {
        guard hasCurrentStoryAudioTrack || hasEditableStoryAudioDraft else { return .missing }
        let sourceBoardId = storyAudioTrack.sourceBeatBoardId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !sourceBoardId.isEmpty, sourceBoardId != storyBeatBoard.beatBoardId {
            return .stale
        }
        let sourceStoryId = storyAudioTrack.sourceProjectStoryId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !sourceStoryId.isEmpty, sourceStoryId != projectStory.acceptedStoryId {
            return .stale
        }
        let sourceFingerprint = storyAudioTrack.sourceBoardFingerprint?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !sourceFingerprint.isEmpty, sourceFingerprint != storyBeatBoard.inputFingerprint.stableId {
            return .stale
        }
        return .fresh
    }

