    }

    var canGenerateStorylinesV2: Bool {
        isGoalV2Ready && !readyLenses.isEmpty && !currentStoryScopeItems.isEmpty
    }

    var canGenerateInitialDraftLenses: Bool {
        initialDraftLensGenerationBlockers.isEmpty
    }

    var currentLensContextGoalFingerprint: String {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion else {
            return ""
        }
        return lensContextFingerprint(projectId: project.projectId, version: version)
    }

    var hasFreshLensContextForActiveGoal: Bool {
        guard let version = projectGoalV2.activeVersion else { return false }
        return lensContext.isReady(
            forGoalVersionId: version.versionId,
            goalFingerprint: currentLensContextGoalFingerprint
        )
    }

    var canRetryLensContextRetrieval: Bool {
        currentProject != nil
            && projectGoalV2.isReady
            && !isRetrievingLensContext
            && !hasFreshLensContextForActiveGoal
    }

    var canGenerateSceneStories: Bool {
        sceneStoryGenerationBlockers.isEmpty
    }

    var hasHydratedGoalCast: Bool {
        !goalCast.articulatedAt.trimmed.isEmpty && !isArticulatingGoalCast
    }

    var hasSceneStoryProviderConfiguration: Bool {
        StoryInferenceService.isConfigured
    }

    var hasVisibleStoryLibraryEntries: Bool {
        storyLibrary.entries.contains(where: { !isRemovedStoryEntry($0) })
    }

    var hasStoryGenerationAttemptForActiveGoal: Bool {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion else {
            return false
        }
        let fingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        return storyGenerationSessions.contains { $0.goalFingerprint == fingerprint }
    }

    var sceneStoryGenerationBlockers: [String] {
        var blockers: [String] = []
        if currentProject == nil {
            blockers.append("Create or select a project first.")
        }
        if !projectGoalV2.isReady {
            blockers.append("Save a Goal first.")
        }
        if projectGoalV2.isReady {
            if isRetrievingLensContext {
                blockers.append("Frame Context retrieval is still running.")
            } else if !hasFreshLensContextForActiveGoal {
                switch lensContext.status {
                case .failed:
                    blockers.append("Frame Context retrieval failed. Retry Frame Context before generating SceneStories.")
                case .ready:
                    blockers.append("Frame Context is stale. Retry Frame Context before generating SceneStories.")
                case .missing:
                    blockers.append("Retrieve Frame Context before generating SceneStories.")
                }
            }
        }
        if readyLenses.isEmpty {
            blockers.append("Enable the Scene Plan.")
        }
        if goalCast.articulatedAt.trimmed.isEmpty {
            blockers.append(isArticulatingGoalCast ? "Character hydration is still running." : "Hydrate the Goal cast first.")
        } else if isArticulatingGoalCast {
            blockers.append("Character hydration is still running.")
        }
        if !hasSceneStoryProviderConfiguration {
            switch StoryInferenceMode.resolved() {
            case .direct:
                blockers.append("Configure an OpenAI-compatible key for Story Inference (OPENAI_API_KEY, optional OPENAI_BASE_URL).")
            case .hosted:
                blockers.append("Configure the hosted Story provider endpoint and token, or switch Story Inference to Direct.")
            }
        }
        if isGeneratingSceneStories {
            blockers.append("SceneStory generation is already running.")
        }
        return blockers
    }

    var initialStoryAutomationStatus: String {
        if isGeneratingSceneStories {
            return "Automatically creating the first three Stories."
        }
        if hasVisibleStoryLibraryEntries {
            return "Initial Stories are ready."
        }
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion else {
            return "Define and save the Story intent to begin."
        }
        let fingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        if let session = storyGenerationSessions.first(where: {
            $0.generationOrigin == .goalConversationAutomatic && $0.goalFingerprint == fingerprint
        }) {
            switch session.status {
            case "complete":
                return "The automatic first batch already ran. Generate manually to add another batch."
            case "partial":
                return "The automatic batch completed partially. Retry manually when ready."
            case "failed", "cancelled":
                return "Automatic Story generation did not finish. Retry manually when ready."
            default:
                return "Automatic Story generation was interrupted. Retry manually when ready."
            }
        }
        if storyGenerationSessions.contains(where: { $0.goalFingerprint == fingerprint }) {
            return "A Story batch was already attempted for this Goal. Retry manually when ready."
        }
        if let blocker = sceneStoryGenerationBlockers.first(where: {
            $0 != "SceneStory generation is already running."
        }) {
            return blocker
        }
        return "Ready — the first three Stories will start automatically."
    }

    var lensGenerationBlockers: [String] {
        var blockers: [String] = []
        if currentProject == nil {
            blockers.append("Create or select a project first.")
        }
        if !projectGoalV2.isReady {
            blockers.append("Save a Goal first.")
        }
        if projectGoalV2.isReady {
            if isRetrievingLensContext {
                blockers.append("Frame Context retrieval is still running.")
            } else if !hasFreshLensContextForActiveGoal {
                switch lensContext.status {
                case .failed:
                    blockers.append("Frame Context retrieval failed. Retry Frame Context before planning Frames.")
                case .ready:
                    blockers.append("Frame Context is stale. Retry Frame Context before planning Frames.")
                case .missing:
                    blockers.append("Retrieve Frame Context before planning Frames.")
                }
            } else if lensContext.response?.styleCandidates.isEmpty ?? true {
                blockers.append("Frame Context has no style candidates yet. Retry Frame Context to search the style catalog.")
            }
        }
        if isGeneratingInitialDraftLenses {
            blockers.append("Scene Plan generation is already running.")
        }
        if isReplanningLensFromStory {
            blockers.append("Frame refresh is already running.")
        }
        return blockers
    }

    var initialDraftLensGenerationBlockers: [String] {
        var blockers: [String] = []
        if currentProject == nil {
            blockers.append("Create or select a project first.")
        }
        if !projectLenses.lenses.isEmpty {
            blockers.append("This project already has planned Frames.")
        }
        if !projectGoalV2.isReady {
            blockers.append("Save a Goal first.")
        }
        if projectGoalV2.isReady {
            if isRetrievingLensContext {
                blockers.append("Frame Context retrieval is still running.")
            } else if !hasFreshLensContextForActiveGoal {
                switch lensContext.status {
                case .failed:
                    blockers.append("Frame Context retrieval failed. Retry Frame Context before planning Frames.")
                case .ready:
                    blockers.append("Frame Context is stale. Retry Frame Context before planning Frames.")
                case .missing:
                    blockers.append("Retrieve Frame Context before planning Frames.")
                }
            }
        }
        if totalEnabledContentCount < requiredAnalyzedEnabledContentCountForAesthetic {
            blockers.append("Enable at least \(requiredAnalyzedEnabledContentCountForAesthetic) media items.")
        }
        if analyzedEnabledContentCount < requiredAnalyzedEnabledContentCountForAesthetic {
            blockers.append("Analyze at least \(requiredAnalyzedEnabledContentCountForAesthetic) enabled media items.")
        }
        if isGeneratingInitialDraftLenses {
            blockers.append("Scene Plan generation is already running.")
        }
        return blockers
    }

    var creativeIncompatibilityMessage: String {
        let reasons = creativeSchemaState.reasons
        guard !reasons.isEmpty else { return "" }
        return "Update this project to use current Goal and Frames. Media and media analysis stay in place."
    }

    var storyStaleSummary: String {
        let statuses = [
            storySignalsFreshness == .stale || storySignalsFreshness == .legacy ? "Signals" : "",
            storyDirectionFreshness == .stale || storyDirectionFreshness == .legacy ? "Directions" : "",
            storyBeatBoardFreshness == .stale || storyBeatBoardFreshness == .legacy ? "Beat Board" : ""
        ].filter { !$0.isEmpty }
        guard !statuses.isEmpty else { return "" }
        return "\(statuses.joined(separator: ", ")) out of date"
    }

    var storylinesStaleSummary: String {
        if storyDirectionFreshness == .stale || storyDirectionFreshness == .legacy {
            return "Storylines need refresh"
        }
        if storySignalsFreshness == .stale || storySignalsFreshness == .legacy {
