    }

    var requiredAnalyzedEnabledContentCountForAesthetic: Int {
        10
    }

    var hasMinimumEnabledContentForAesthetic: Bool {
        totalEnabledContentCount >= requiredAnalyzedEnabledContentCountForAesthetic
    }

    var analyzedAestheticMediaObservationsById: [String: ImageObservationResult] {
        var observations: [String: ImageObservationResult] = [:]
        for item in enabledContentItems {
            guard let observation = mediaObservationsById[item.mediaId] else { continue }
            observations[item.mediaId] = observation
        }
        return observations
    }

    var analyzedEnabledContentCount: Int {
        aestheticAnalysisHealth.savedObservationCount
    }

    var freshAnalyzedEnabledContentCount: Int {
        aestheticAnalysisHealth.freshObservationCount
    }

    var totalEnabledContentCount: Int {
        enabledContentItems.count
    }

    var isAestheticReadyToRun: Bool {
        projectGoal.isReadyForAesthetic
            && hasMinimumEnabledContentForAesthetic
            && analyzedEnabledContentCount >= requiredAnalyzedEnabledContentCountForAesthetic
    }

    var aestheticAnalysisHealth: AestheticAnalysisHealth {
        var health = AestheticAnalysisHealth(enabledCount: enabledContentItems.count)
        for item in enabledContentItems {
            guard let observation = mediaObservationsById[item.mediaId] else {
                health.missingObservationCount += 1
                continue
            }
            health.savedObservationCount += 1
            if isAestheticObservationModifiedSinceAnalysis(item: item, observation: observation) {
                health.modifiedObservationCount += 1
            }
            if observation.isCurrentAestheticObservationVersion {
                health.freshObservationCount += 1
            } else {
                health.staleObservationCount += 1
            }
        }
        return health
    }

    private func isAestheticObservationModifiedSinceAnalysis(
        item: MediaItemRecord,
        observation: ImageObservationResult
    ) -> Bool {
        let currentInputPath = FileManager.default.fileExists(atPath: item.thumbnailPath) ? item.thumbnailPath : item.path
        if !observation.visionInputSha256.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard let data = try? Data(contentsOf: URL(fileURLWithPath: currentInputPath)) else {
                return true
            }
            return sha256Hex(data) != observation.visionInputSha256
        }
        return !item.modifiedAt.isEmpty
            && !observation.createdAt.isEmpty
            && item.modifiedAt > observation.createdAt
    }

    var canAnalyzeEnabledMedia: Bool {
        currentProject != nil && !enabledContentItems.isEmpty && !isScanning && !isAnalyzingMedia
    }

    var canAnalyzeUnanalyzedEnabledMedia: Bool {
        currentProject != nil && !unanalyzedEnabledContentItems.isEmpty && !isScanning && !isAnalyzingMedia
    }

    var canRecordScreenArea: Bool {
        currentProject != nil
            && !isScanning
            && !isAnalyzingMedia
            && (
