    }

    var isScreenAreaRecordingBusy: Bool {
        screenAreaRecordingPhase != .idle && screenAreaRecordingPhase != .failed
    }

    private func allProjectsCreativeResetMarkerURL() -> URL {
        litScenesApplicationSupportDirectory()
            .appendingPathComponent("maintenance", isDirectory: true)
            .appendingPathComponent(allProjectsCreativeResetMarkerFileName)
    }

    private func runAllProjectsCreativeResetIfNeeded(_ projects: [ProjectRecord]) throws -> AllProjectsCreativeResetSummary? {
        let markerURL = allProjectsCreativeResetMarkerURL()
        guard !FileManager.default.fileExists(atPath: markerURL.path) else { return nil }

        var archivedItemCount = 0
        var archiveDirectoryCount = 0
        for project in projects {
            let result = try contextStore.resetCreativeData(for: project)
            archivedItemCount += result.archivedPaths.count
            if result.archiveDirectory != nil {
                archiveDirectoryCount += 1
            }
        }

        let marker = AllProjectsCreativeResetMarker(
            completedAt: DateFormats.now(),
            projectCount: projects.count,
            archivedItemCount: archivedItemCount,
            archiveDirectoryCount: archiveDirectoryCount
        )
        try ensureDirectory(markerURL.deletingLastPathComponent())
        try JSONCoding.prettyEncoder.encode(marker).write(to: markerURL, options: [.atomic])
        return AllProjectsCreativeResetSummary(
            projectCount: projects.count,
            archivedItemCount: archivedItemCount,
            archiveDirectoryCount: archiveDirectoryCount
        )
    }

    func reloadProjects(selecting projectId: String? = nil) {
        do {
            var loadedProjects = try projectLibrary.listProjects()
            let resetSummary = try runAllProjectsCreativeResetIfNeeded(loadedProjects)
            if resetSummary != nil {
                loadedProjects = try projectLibrary.listProjects()
            }
            projects = loadedProjects
            bootstrapMediaAnalysisMemory(from: loadedProjects)
            let selectedId = projectId ?? currentProject?.projectId
            if let selectedId, let project = projects.first(where: { $0.projectId == selectedId }) {
                load(project: project)
                if let resetSummary {
                    scanStatus = resetSummary.statusText
                }
            } else if let project = projects.first {
                load(project: project)
                if let resetSummary {
                    scanStatus = resetSummary.statusText
