    @discardableResult
    func createProject(named name: String) -> Bool {
        do {
            let project = try projectLibrary.createProject(named: name)
            try contextStore.saveStoryWorld(.empty(projectId: project.projectId), for: project)
            try contextStore.saveSourceContext([], for: project)
            try contextStore.saveVisionUIPreferences(.empty(projectId: project.projectId), for: project)
            try contextStore.bootstrapCreativeV2Data(for: project)
            try contextStore.saveStoryWorkspace(.empty(projectId: project.projectId), for: project)
            try contextStore.saveProjectArchiveMeaning(.empty(projectId: project.projectId), for: project)
            try contextStore.saveMediaObservations([:], for: project)
            reloadProjects(selecting: project.projectId)
            scanStatus = "Created \(project.name)"
            return true
        } catch {
            lastError = error.localizedDescription
            return false
        }
    }

    @discardableResult
    func renameCurrentProject(to name: String) -> Bool {
        guard let project = currentProject else {
            scanStatus = "Create or select a project first"
            return false
        }
        do {
            let updated = try projectLibrary.renameProject(project, to: name)
            currentProject = updated
            if let index = projects.firstIndex(where: { $0.projectId == updated.projectId }) {
                projects[index] = updated
            }
            scanStatus = "Renamed \(updated.name)"
            return true
        } catch {
            lastError = error.localizedDescription
            return false
        }
    }

    func selectProject(_ project: ProjectRecord) {
        guard !isScanning else {
            scanStatus = "Finish the current scan before switching projects"
            return
        }
        guard !isAnalyzingMedia else {
            mediaAnalysisStatus = "Finish media analysis before switching projects"
            return
        }
        // Refuse while a paid video op is in flight: load(project:) would
        // leave the render Task running and spending, with its persists then
        // refused by the identity law and the old project's doc stuck on
        // "generating" until the next load reconciles it. Every switch path
        // (sidebar, recorder) gets this guard — it used to live only on the
        // retired SCENES v2 cross-project hop.
        guard activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty else {
            scanStatus = "A video render is in flight — switching projects would abandon it. Let it finish first."
            return
        }
        stopVideoPlayback()
        load(project: project)
    }

    @discardableResult
    func resetCurrentProjectCreativeData() -> Bool {
        guard let project = currentProject else {
            lastError = "Create or select a project first"
            return false
        }
        do {
            let result = try contextStore.resetCreativeData(for: project)
            creativeResetArchivePath = result.archiveDirectory ?? ""
            load(project: project)
            scanStatus = result.archivedPaths.isEmpty
                ? "Creative data reset"
                : "Creative data reset; archived \(result.archivedPaths.count) item\(result.archivedPaths.count == 1 ? "" : "s")"
            return true
        } catch {
            lastError = error.localizedDescription
            return false
        }
    }

    @discardableResult
    func commitGoalV2Brief(
        _ brief: ProjectGoalBriefV2,
        changeSummary: String = "Updated Goal.",
        model: String = "local-edit"
    ) -> Bool {
        guard let project = currentProject else {
            goalStatus = "Create or select a project first"
            return false
        }
        var updated = projectGoalV2
        if updated.projectId.isEmpty {
            updated.projectId = project.projectId
        }
        let normalizedEntities = uniqueRequiredGoalEntities(brief.requiredEntities)
        var normalizedBrief = brief.normalized()
        normalizedBrief.requiredEntities = normalizedEntities.entities
        let now = DateFormats.now()
        updated.appendVersion(
            brief: normalizedBrief,
            changeSummary: changeSummary,
            model: model,
            now: now,
            validationWarnings: normalizedEntities.warnings
        )
        saveGoalV2(updated, for: project, status: updated.isReady ? "Goal ready" : "Goal draft saved")
        return lastError.isEmpty
    }

    @discardableResult
    func restoreGoalV2Version(_ version: ProjectGoalBriefVersionV2) -> Bool {
        guard let project = currentProject else {
            goalStatus = "Create or select a project first"
            return false
        }
        var updated = projectGoalV2
        guard updated.versions.contains(where: { $0.versionId == version.versionId }) else {
            goalStatus = "Goal version no longer available"
            return false
        }
        updated.restore(versionId: version.versionId, now: DateFormats.now())
        saveGoalV2(updated, for: project, status: updated.isReady ? "Goal version restored" : "Goal draft restored")
        return lastError.isEmpty
    }

    func sendGoalV2InterviewMessage(text rawText: String, mediaIds rawMediaIds: [String] = []) async {
        guard let project = currentProject else {
            goalStatus = "Create or select a project first"
            return
        }
        let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
        let mediaIds = normalizedExistingMediaIds(rawMediaIds)
        guard !text.isEmpty || !mediaIds.isEmpty else {
            goalStatus = "Write a message or attach an image first"
            return
        }
        guard !isInterviewingGoal else { return }

        let submittedText = text.isEmpty ? "Attached image." : text
        isInterviewingGoal = true
        lastError = ""
        goalStatus = "Goal interview running"

        let userMessageTime = DateFormats.now()
        var workingGoal = projectGoalV2
        if workingGoal.projectId.isEmpty {
            workingGoal.projectId = project.projectId
        }
        workingGoal.appendMessage(role: .user, text: submittedText, mediaIds: mediaIds, now: userMessageTime)

        do {
            try contextStore.saveProjectGoalV2(workingGoal, for: project)
            projectGoalV2 = workingGoal
            touchCurrentProject()

            let client = try OpenAIClient.fromEnvironment()
            let visionInputs = try goalVisionInputs(mediaIds: mediaIds)
            let now = DateFormats.now()
            let context = ProjectGoalInterviewV3Context(
                projectId: project.projectId,
                projectName: project.name,
                currentBriefJSON: currentGoalBriefV2JSON(from: workingGoal.activeBrief),
                recentMessagesSummary: goalV2MessagesSummary(from: workingGoal),
                selectedMediaSummary: selectedGoalMediaSummary(mediaIds: mediaIds),
                mediaArchiveSummary: goalMediaArchiveSummary(),
                moodboardAnalysisContext: goalMoodboardAnalysisContext(),
                meaningChoiceContextJSON: try meaningChoiceContextJSON(),
                currentCastSummary: goalCast.interviewContextSummary,
                userMessage: submittedText,
                generatedAt: now
            )
            let result = try await client.interviewProjectGoalV3(context: context, visionInputs: visionInputs)
            guard currentProject?.projectId == project.projectId else {
                isInterviewingGoal = false
                return
            }

            var updated = workingGoal
            let assistantText = result.assistantMessage.trimmingCharacters(in: .whitespacesAndNewlines)
            updated.appendMessage(
                role: .assistant,
                text: assistantText.isEmpty ? "I updated the Goal." : assistantText,
                mediaIds: [],
                now: DateFormats.now()
            )
            let sanitized = sanitizeInterviewRequiredEntities(
                brief: result.brief,
                currentBrief: workingGoal.activeBrief,
                userMessages: workingGoal.messages
            )
            // Apply cast patches before saveGoalV2 queues the refresh chain, so the
            // auto-articulation hook deterministically sees chat-created members.
            applyChatCastUpdates(result.castUpdates, latestUserMessage: submittedText, turnMediaIds: mediaIds, for: project)
            updated.appendVersion(
                brief: sanitized.brief,
                changeSummary: result.changeSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    ? "Updated Goal from the latest interview turn."
                    : result.changeSummary,
                model: result.model,
                now: DateFormats.now(),
                validationWarnings: sanitized.warnings
            )
            saveGoalV2(updated, for: project, status: updated.isReady ? "Goal ready" : "Goal updated")
        } catch {
            guard currentProject?.projectId == project.projectId else {
                isInterviewingGoal = false
                return
            }
            lastError = goalInterviewFailureMessage(for: error)
            goalStatus = goalInterviewFailureStatus(for: error)
        }

        isInterviewingGoal = false
    }

    func retryLensContextRetrieval() {
        lensContextRetrievalTask?.cancel()
        lensContextRetrievalTask = Task {
            await refreshLensContextForActiveGoal()
        }
    }

    func refreshLensContextForActiveGoal() async {
        guard let project = currentProject else {
            lensContextStatus = "Create or select a project first"
            return
        }
        guard let version = projectGoalV2.activeVersion, version.brief.isReady else {
            lensContextStatus = "Save a Goal first"
            return
        }
        if version.brief.styleTermRefs.isEmpty {
            let committed = await ensureGoalStyleTaxonomyRefs()
            if committed {
                return
            }
        }
        // Cast articulation runs fire-and-forget in parallel: it never commits a brief
        // version (its document is separate), and awaiting it here would stall Frame
        // Context retrieval behind a second LLM call.
        if goalCast.articulatedAt.isEmpty {
            goalCastArticulationTask = Task { [weak self] in
                await self?.ensureGoalCastArticulation()
            }
        }
        let goalFingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        let retrievalKey = "\(project.projectId):\(version.versionId):\(goalFingerprint)"
        let request = LensContextResolveRequest(
            projectId: project.projectId,
            goalFingerprint: goalFingerprint,
            meaningNodeRefs: version.brief.meaningNodeRefs,
            aestheticTermRefs: version.brief.aestheticTermRefs,
            styleTermRefs: version.brief.styleTermRefs,
            limits: LensContextResolveLimits(
                meaningEdgeNeighbors: 24,
                meaningEvidence: 16,
                perNodeEvidence: 2,
                aestheticCandidates: 8,
                styleCandidates: 45
            )
        )

        isRetrievingLensContext = true
        activeLensContextRetrievalKey = retrievalKey
        lensContextStatus = "Retrieving Frame Context"
        print("[lens_context_retrieval] starting project_id=\(project.projectId) goal_version_id=\(version.versionId)")
        defer {
            if activeLensContextRetrievalKey == retrievalKey {
                isRetrievingLensContext = false
                activeLensContextRetrievalKey = ""
                lensContextRetrievalTask = nil
                syncLensContextStatus()
            }
        }

        do {
            let client = try StoryInferenceService.fromEnvironment()
            let response = try await client.resolve(request)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId,
                  projectGoalV2.activeVersion?.versionId == version.versionId,
                  currentLensContextGoalFingerprint == goalFingerprint,
                  activeLensContextRetrievalKey == retrievalKey else {
                return
            }
            let document = ProjectLensContextDocument.ready(
                projectId: project.projectId,
                goalVersionId: version.versionId,
                goalFingerprint: goalFingerprint,
                request: request,
                response: response
            )
            try contextStore.saveLensContext(document, for: project)
            lensContext = document
            touchCurrentProject()
            print(
                "[lens_context_retrieval] completed project_id=\(project.projectId) goal_version_id=\(version.versionId) meaning_nodes=\(response.selectedMeaningNodes.count) edge_neighbors=\(response.meaningEdgeNeighbors.count) evidence=\(response.meaningEvidence.count) aesthetic_candidates=\(response.aestheticCandidates.count) style_candidates=\(response.styleCandidates.count)"
            )
            queueFramePlanningAfterLensContext(projectId: project.projectId, goalVersionId: version.versionId)
            queueInitialFrameFormsAfterLensContext(
                projectId: project.projectId,
                goalVersionId: version.versionId,
                goalFingerprint: goalFingerprint
            )
            queueInitialStoryGenerationIfEligible()
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return
            }
            guard currentProject?.projectId == project.projectId,
                  projectGoalV2.activeVersion?.versionId == version.versionId,
                  currentLensContextGoalFingerprint == goalFingerprint,
                  activeLensContextRetrievalKey == retrievalKey else {
                return
            }
            let document = ProjectLensContextDocument.failed(
                projectId: project.projectId,
                goalVersionId: version.versionId,
                goalFingerprint: goalFingerprint,
                request: request,
                message: error.localizedDescription
            )
            do {
                try contextStore.saveLensContext(document, for: project)
                lensContext = document
                touchCurrentProject()
            } catch {
                lastError = error.localizedDescription
            }
            print("[lens_context_retrieval] error: \(error.localizedDescription) project_id=\(project.projectId) goal_version_id=\(version.versionId)")
        }
    }

    private func queuedLensHeroImages(
        lensId: String,
        routeKey: String,
        recipe: ProjectAestheticDirectionRecipe?,
        sourceAestheticIds: [String],
        sourceReferenceIds: [String] = [],
        mediaPlan: LensMediaPlan? = nil,
        styleAuthorities: [LensStyleAuthoritySnapshot] = [],
        sourceDependencies: [LensRenderSourceDependency] = [],
        imageKind: String = "",
        areaId: String = "",
        sceneId: String = "",
        areaImageId: String = "",
        homeSceneImageId: String = "",
        prompt: String,
        now: String = DateFormats.now()
    ) -> [ProjectLensHeroImage] {
        // Character studies are isolated PNG concept studies, which only the OpenAI
        // path currently handles — never queue a Stability variant for a character route.
        let isCharacterRoute = LensConceptCategory.category(forRouteKey: routeKey) == .characters
        let providers: [LensHeroImageProvider] = (sourceReferenceIds.isEmpty && !isCharacterRoute) ? [.openAI, .stability] : [.openAI]
        let subject = generatedTakeSubject(routeKey: routeKey, prompt: prompt)
        let styleSourceDependencies = generatedTakeStyleSourceDependencies(
            styleAuthorities: styleAuthorities,
            sourceReferenceIds: sourceReferenceIds
        )
        let dependencies = sourceDependencies + styleSourceDependencies
        return providers.map { provider in
            if let recipe {
                var image = ProjectLensHeroImage.queued(
                    lensId: lensId,
                    routeKey: routeKey,
                    recipe: recipe,
                    prompt: prompt,
                    provider: provider.rawValue,
                    model: provider.model,
                    imageIndex: provider.imageIndex,
                    label: provider.label,
                    imageKind: imageKind,
                    areaId: areaId,
                    sceneId: sceneId,
                    areaImageId: areaImageId,
                    homeSceneImageId: homeSceneImageId,
                    now: now
                )
                image.subject = subject
                image.styleAuthorities = styleAuthorities
                image.renderRecipe = provider.renderRecipeSnapshot(
                    mediaPlan: mediaPlan,
                    isCharacterStudy: isCharacterRoute,
                    hasStyleReferences: !sourceReferenceIds.isEmpty || !styleAuthorities.isEmpty
                )
                image.sourceDependencies = dependencies
                return image.normalized()
            }
            return ProjectLensHeroImage(
                imageId: "lens_hero_\(shortHash("\(lensId):\(routeKey):\(provider.rawValue):\(now)", length: 14))",
                imageIndex: provider.imageIndex,
                label: provider.label,
                provider: provider.rawValue,
                model: provider.model,
                imagePath: "",
                prompt: prompt,
                sourcePrompt: prompt,
                negativePrompt: "",
                promptEnrichmentModel: "",
                promptEnrichmentResponseId: "",
                promptEnrichmentTraceId: "",
                promptEnrichmentSummary: "",
                status: "queued",
                requestId: "",
                traceId: "",
                errorMessage: "",
                sourceRouteKey: routeKey,
                sourceRecipeId: nil,
                sourceRecipeVersion: nil,
                sourceAestheticIds: sourceAestheticIds,
                subject: subject,
                styleAuthorities: styleAuthorities,
                renderRecipe: provider.renderRecipeSnapshot(
                    mediaPlan: mediaPlan,
                    isCharacterStudy: isCharacterRoute,
                    hasStyleReferences: !sourceReferenceIds.isEmpty || !styleAuthorities.isEmpty
                ),
                sourceDependencies: dependencies,
                imageKind: imageKind,
                areaId: areaId,
                sceneId: sceneId,
                areaImageId: areaImageId,
                homeSceneImageId: homeSceneImageId,
                generatedAt: "",
                updatedAt: now
            ).normalized()
        }
    }

    private func generatedTakeSubject(routeKey: String, prompt: String) -> LensGeneratedSubject {
        switch LensConceptCategory.category(forRouteKey: routeKey) {
        case .characters:
            return LensGeneratedSubject(
                kind: .character,
                description: prompt,
                canonRoleCandidate: .actor,
                stageEligibility: LensStageEligibility(canBecomeActor: true)
            ).normalized()
        case .objects:
            return LensGeneratedSubject(
                kind: .object,
                description: prompt,
                canonRoleCandidate: .prop,
                stageEligibility: LensStageEligibility(canBecomeProp: true)
            ).normalized()
        case .areas, .scenery, .legacy:
            return LensGeneratedSubject(
                kind: .scene,
                description: prompt,
                canonRoleCandidate: .plate,
                stageEligibility: LensStageEligibility(canBecomePlate: true)
            ).normalized()
        }
    }

    private func generatedTakeStyleSourceDependencies(
        styleAuthorities: [LensStyleAuthoritySnapshot],
        sourceReferenceIds: [String]
    ) -> [LensRenderSourceDependency] {
        let authorityDependencies = styleAuthorities.enumerated().map { index, authority in
            LensRenderSourceDependency(
                dependencyId: "",
                kind: "externalImport",
                sourceId: authority.sourceReferenceId.isEmpty ? authority.referenceId : authority.sourceReferenceId,
                required: true,
                role: "style_source",
                label: authority.title,
                imagePathOrUrl: authority.imageUrl.isEmpty ? authority.imagePath : authority.imageUrl
            ).normalized(order: index)
        }
        if !authorityDependencies.isEmpty {
            return authorityDependencies
        }
        return uniqueNonEmpty(sourceReferenceIds).enumerated().map { index, rawValue in
            if let reference = SREFStyleImageReference.decodeSourceReferenceId(rawValue) {
                return LensRenderSourceDependency(
                    dependencyId: "",
                    kind: "externalImport",
                    sourceId: reference.sourceReferenceId,
                    required: true,
                    role: "style_source",
                    label: reference.title,
                    imagePathOrUrl: reference.url
                ).normalized(order: index)
            }
            return LensRenderSourceDependency(
                dependencyId: "",
                kind: "externalImport",
                sourceId: rawValue,
                required: true,
                role: "style_source",
                label: "",
                imagePathOrUrl: ""
            ).normalized(order: index)
        }
    }

    private func lensNewTakeRouteKey(
        category: LensConceptCategory,
        lensId: String,
        templateImageId: String,
        stack: RenderStack,
        prompt: String,
        now: String
    ) -> String {
        let suffix = shortHash("\(lensId):\(templateImageId):\(stack.id):\(prompt):\(now)", length: 10)
        switch category {
        case .characters:
            return "lens_media_character_custom_\(suffix)"
        case .objects:
            return "lens_media_object_custom_\(suffix)"
        case .areas, .scenery:
            return "lens_media_scenery_custom_\(suffix)"
        case .legacy:
            return "lens_media_custom_\(suffix)"
        }
    }

    private func lensNewTakeLabel(
        category: LensConceptCategory,
        sourceImage: ProjectLensHeroImage?,
        explicitLabel: String,
        stack: RenderStack
    ) -> String {
        let base: String
        if !explicitLabel.trimmed.isEmpty {
            base = explicitLabel.trimmed
        } else {
            // Character/object labels carry the subject name in the second segment
            // ("Character · Mara Vale") — keep it so custom takes stay attributable.
            let segments = (sourceImage?.label ?? "").components(separatedBy: " · ").map(\.trimmed).filter { !$0.isEmpty }
            let keepCount = category == .characters || category == .objects ? 2 : 1
            let sourceTitle = segments.prefix(keepCount).joined(separator: " · ")
            if !sourceTitle.isEmpty {
                base = sourceTitle
            } else if sourceImage == nil {
                switch category {
                case .characters:
                    base = "New Character Frame"
                case .objects:
                    base = "New Object Frame"
                case .areas, .scenery:
                    base = "New Scenery Frame"
                case .legacy:
                    base = "New Frame"
                }
            } else {
                switch category {
                case .characters:
                    base = "Custom Character Take"
                case .objects:
                    base = "Custom Object Take"
                case .areas, .scenery:
                    base = "Custom Scenery Take"
                case .legacy:
                    base = "Custom Scene Plan Take"
                }
            }
        }
        return uniqueNonEmpty([base, stack.label]).joined(separator: " · ")
    }

    private func lensPromptImageAttachments(for request: LensNewTakeRenderRequest) -> [LensPromptImageAttachment] {
        var attachments: [LensPromptImageAttachment] = []
        if let single = request.promptImageAttachment?.normalized(), !single.imagePath.isEmpty {
            attachments.append(single)
        }
        attachments.append(contentsOf: (request.promptImageAttachments ?? [])
            .map { $0.normalized() }
            .filter { !$0.imagePath.isEmpty })

        var seen: Set<String> = []
        return attachments.filter { attachment in
            let key = uniqueNonEmpty([attachment.attachmentId, attachment.source.rawValue, attachment.sourceId, attachment.imagePath]).joined(separator: "|")
            guard !seen.contains(key) else { return false }
            seen.insert(key)
            return true
        }
    }

    private func lensPromptImageAttachmentPlan(
        _ attachment: LensPromptImageAttachment,
        descriptorOverride: String? = nil
    ) -> LensBlendAttachmentPlan {
        lensPromptImageAttachmentPlan([attachment], descriptorOverrides: [descriptorOverride ?? ""])
    }

    private func lensPromptImageAttachmentPlan(
        _ attachments: [LensPromptImageAttachment],
        descriptorOverrides: [String] = []
    ) -> LensBlendAttachmentPlan {
        let entries = attachments.enumerated().map { index, attachment in
            lensPromptImageAttachmentEntry(
                attachment,
                index: index,
                descriptorOverride: descriptorOverrides.indices.contains(index) ? descriptorOverrides[index] : ""
            )
        }
        return LensBlendAttachmentPlan(
            entries: entries,
            warnings: [],
            styleSummaryText: ""
        )
    }

    private func lensPromptImageAttachmentEntry(
        _ attachment: LensPromptImageAttachment,
        index: Int,
        descriptorOverride: String
    ) -> LensBlendAttachmentEntry {
        let normalized = attachment.normalized()
        let url = URL(fileURLWithPath: normalized.imagePath)
        let ext = url.pathExtension.trimmed.isEmpty ? "png" : url.pathExtension.lowercased()
        let label = normalized.label.isEmpty ? "selected prompt image" : normalized.label
        // Descriptor precedence: explicit override (reframe) > the attachment's own
        // detail (e.g. @mention character-reference language) > the generic default.
        let descriptor = descriptorOverride.trimmed.nilIfEmpty
            ?? normalized.detail.trimmed.nilIfEmpty
            ?? "PROMPT image reference — use this image as visual source context for the requested generation. It can guide subject, structure, layout, mood, or material cues, but the written prompt remains the primary instruction."
        return LensBlendAttachmentEntry(
            role: .promptImage,
            roleIndex: index + 1,
            sharePercent: 0,
            reference: nil,
            localURL: url,
            characterName: nil,
            caption: label,
            attachmentFilename: "prompt-image-\(index + 1).\(ext)",
            promptDescriptor: descriptor
        )
    }

    private func reframeAttachmentDescriptors(for spec: LensReframeSpec, attachmentCount: Int) -> [String] {
        if attachmentCount == 1 {
            return [LensReframeComposer.compositeAttachmentDescriptor(spec: spec)]
        }
        if attachmentCount >= 3 {
            return [
                LensReframeComposer.fullFrameAttachmentDescriptor(spec: spec),
                LensReframeComposer.focusCropAttachmentDescriptor(spec: spec),
                LensReframeComposer.cameraMapAttachmentDescriptor(spec: spec)
            ]
        }
        return [
            LensReframeComposer.fullFrameAttachmentDescriptor(spec: spec),
            LensReframeComposer.focusCropAttachmentDescriptor(spec: spec)
        ]
    }

    private func lensPromptImageDependency(_ attachment: LensPromptImageAttachment) -> LensRenderSourceDependency {
        let normalized = attachment.normalized()
        return LensRenderSourceDependency(
            dependencyId: "",
            kind: normalized.source.rawValue,
            sourceId: normalized.sourceId,
            required: true,
            role: "prompt_image_source",
            label: normalized.label,
            imagePathOrUrl: normalized.imagePath
        ).normalized(order: 0)
    }

    private func generatedTakeStyleAuthorities(
        lens: ProjectLens,
        catalog: StyleBrowseCatalog?
    ) -> [LensStyleAuthoritySnapshot] {
        let ingredientReferences = uniqueNonEmpty(lens.body.styleIngredients.flatMap(\.sourceReferenceIds))
            .compactMap { SREFStyleImageReference.decodeSourceReferenceId($0) }
        if let treatment = lens.body.styleTreatment?.normalized(), !treatment.isEmpty {
            let shares = treatment.blendShares()
            return treatment.slots.enumerated().compactMap { index, slot in
                let style = catalog?.style(withId: slot.styleId)
                let reference = ingredientReferences.first { $0.itemId == slot.styleId }
                    ?? style?.styleImageReference(catalogVersion: catalog?.version ?? treatment.catalogVersion)
                let title = reference?.title ?? style?.displayLabel ?? slot.label
                let source = generatedTakeStyleAuthoritySource(reference: reference)
                return LensStyleAuthoritySnapshot(
                    authorityId: "",
                    role: index == 0 ? "primary" : "accent",
                    source: source,
                    referenceId: slot.styleId,
                    sourceReferenceId: reference?.sourceReferenceId ?? "",
                    title: title,
                    imageUrl: reference?.url ?? slot.url,
                    imagePath: "",
                    oneLineStyleSummary: style?.styleSummaryLine ?? "",
                    weight: shares.indices.contains(index) ? shares[index] : slot.weight
                ).normalized(order: index)
            }
        }
        return ingredientReferences.enumerated().map { index, reference in
            let style = catalog?.style(withId: reference.itemId)
            return LensStyleAuthoritySnapshot(
                authorityId: "",
                role: index == 0 ? "primary" : "accent",
                source: generatedTakeStyleAuthoritySource(reference: reference),
                referenceId: reference.itemId,
                sourceReferenceId: reference.sourceReferenceId,
                title: reference.title,
                imageUrl: reference.url,
                imagePath: "",
                oneLineStyleSummary: style?.styleSummaryLine ?? "",
                weight: nil
            ).normalized(order: index)
        }
    }

    private func generatedTakeStyleAuthoritySource(reference: SREFStyleImageReference?) -> LensStyleAuthoritySource {
        guard let reference else { return .unknown }
        return reference.catalogKind == "style_browse_catalog" ? .styleCatalog : .sref
    }

    private func lensHeroGenerationJobs(
        for lenses: [ProjectLens],
        project: ProjectRecord,
        proofRunId: String,
        catalog: StyleBrowseCatalog?
    ) -> [LensHeroGenerationJob] {
        lenses.flatMap { theme -> [LensHeroGenerationJob] in
            let cast = lensCompositeCast(for: theme)
            return theme.sortedHeroImages.compactMap { heroImage -> LensHeroGenerationJob? in
                guard heroImage.status == "queued" || heroImage.status == "generating" else { return nil }
                let provider = LensHeroImageProvider(rawValue: heroImage.provider) ?? .openAI
                let isCharacterStudy = LensConceptCategory.category(for: heroImage) == .characters
                // Per-frame character scope: a study attaches its own character's refs;
                // every other frame attaches none.
                let characterScopeId = isCharacterStudy
                    ? lensResolvedTakeCharacterId(for: heroImage, lens: theme, cast: cast)
                    : ""
                let plan = lensBlendAttachmentPlan(
                    lens: theme,
                    catalog: catalog,
                    characterScopeId: characterScopeId,
                    continuityURLs: []
                )
                let fileName = "\(proofRunId)_\(safeIdentifier(theme.lensId))_\(safeIdentifier(heroImage.imageId)).\(isCharacterStudy ? "png" : "jpg")"
                return LensHeroGenerationJob(
                    lensId: theme.lensId,
                    imageId: heroImage.imageId,
                    provider: provider,
                    skipPromptEnrichment: heroImage.promptEnrichmentDisabled,
                    prompt: heroImage.prompt,
                    sourcePrompt: heroImage.sourcePrompt.trimmed.isEmpty ? heroImage.prompt : heroImage.sourcePrompt,
                    negativePrompt: heroImage.negativePrompt,
                    attachments: provider == .openAI ? plan.entries : [],
                    promptPreamble: provider == .openAI ? plan.promptPreamble : "",
                    attachmentManifest: provider == .openAI ? plan.manifestText : "",
                    styleSummary: provider == .openAI ? plan.styleSummaryText : "",
                    attachmentManifestEntries: provider == .openAI ? plan.manifestEntryLinesText : "",
                    attachmentStylePolicy: provider == .openAI ? plan.manifestPolicyText : "",
                    imageSize: theme.body.resolvedMediaPlan.imageSize,
                    stabilityAspectRatio: theme.body.resolvedMediaPlan.stabilityAspectRatio,
                    stabilityStrength: heroImage.stabilityStrength,
                    mediaPlan: theme.body.resolvedMediaPlan,
                    transparentBackground: isCharacterStudy,
                    outputURL: contextStore.aestheticProofDirectory(for: project).appendingPathComponent(fileName),
                    projectId: project.projectId,
                    runId: heroImage.imageId
                )
            }
        }
    }

    @discardableResult
    private func saveLensHeroImageOutcome(
        _ outcome: LensHeroGenerationOutcome,
        project: ProjectRecord,
        status: String,
        changeSummary: String,
        appendVersion: Bool = true
    ) -> Bool {
        guard currentProject?.projectId == project.projectId else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let lensIndex = themes.firstIndex(where: { $0.lensId == outcome.lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = themes[lensIndex].sortedHeroImages
        guard let heroIndex = heroImages.firstIndex(where: { $0.imageId == outcome.imageId }) else {
            aestheticStatus = "Frame not found"
            return false
        }
        let outcomeRequestId = outcome.requestId.trimmed.nilIfEmpty ?? "-"
        if outcome.status == "ready" {
            logGeneration(
                kind: "image.completed",
                message: "Frame image ready lens_id=\(outcome.lensId) image_id=\(outcome.imageId) provider=\(outcome.provider.rawValue) request_id=\(outcomeRequestId)"
            )
        } else {
            logGeneration(
                kind: "image.error",
                message: "Frame image \(outcome.status) lens_id=\(outcome.lensId) image_id=\(outcome.imageId) provider=\(outcome.provider.rawValue): \(shortSummaryText(outcome.errorMessage, limit: 200))"
            )
        }
        // The single image funnel: every generated frame lands here, so the
        // ledger row lives here too. No reachable image rate — unpriced, the
        // recipe's provider price note rides along. Cancels never ledger.
        if outcome.status == "ready" || outcome.status == "failed" {
            recordSpend(SpendLedgerEntry(
                kind: "image",
                provider: outcome.provider.rawValue,
                model: outcome.renderRecipe?.model ?? "",
                requestId: outcome.requestId.trimmed,
                traceId: outcome.traceId,
                contextLabel: heroImages[heroIndex].label.trimmed.nilIfEmpty ?? "Frame",
                imageId: outcome.imageId,
                unit: "images",
                unitCount: 1,
                estimatedUSD: outcome.status == "ready"
                    ? estimatedImageUSD(endpointId: outcome.renderRecipe?.model ?? "", outputPath: outcome.imagePath)
                    : nil,
                pricingNote: ledgerPricingNote(
                    endpointId: outcome.renderRecipe?.model ?? "",
                    fallback: outcome.renderRecipe?.parameters.first { $0.key == "provider_price_note" }?.value ?? ""
                ),
                status: outcome.status == "ready" ? "completed" : "failed_unknown_charge"
            ))
        }
        heroImages[heroIndex].status = outcome.status
        heroImages[heroIndex].imagePath = outcome.imagePath
        heroImages[heroIndex].prompt = outcome.prompt
        heroImages[heroIndex].sourcePrompt = outcome.sourcePrompt
        heroImages[heroIndex].negativePrompt = outcome.negativePrompt
        heroImages[heroIndex].promptEnrichmentModel = outcome.promptEnrichmentModel
        heroImages[heroIndex].promptEnrichmentResponseId = outcome.promptEnrichmentResponseId
        heroImages[heroIndex].promptEnrichmentTraceId = outcome.promptEnrichmentTraceId
        heroImages[heroIndex].promptEnrichmentSummary = outcome.promptEnrichmentSummary
        heroImages[heroIndex].requestId = outcome.requestId
        heroImages[heroIndex].traceId = outcome.traceId
        heroImages[heroIndex].errorMessage = outcome.errorMessage
        heroImages[heroIndex].generatedAt = outcome.generatedAt
        heroImages[heroIndex].updatedAt = outcome.updatedAt
        if let renderRecipe = outcome.renderRecipe?.normalized() {
            heroImages[heroIndex].renderRecipe = renderRecipe
            heroImages[heroIndex].model = renderRecipe.model
        }
        if outcome.status == "ready", !outcome.imagePath.trimmed.isEmpty {
            heroImages = lensHeroImages(heroImages, lensId: outcome.lensId, activating: outcome.imageId)
        }
        themes[lensIndex].heroImages = heroImages
        themes[lensIndex].heroImage = themes[lensIndex].primaryHeroImage
        themes[lensIndex] = lensWithRefreshedInitialDraftGenerationState(
            themes[lensIndex],
            fallbackError: outcome.errorMessage
        )
        themes[lensIndex].updatedAt = DateFormats.now()
        themes[lensIndex] = themes[lensIndex].normalized()
        if appendVersion {
            updated.appendVersion(
                lenses: themes,
                scratchDrafts: updated.scratchDrafts,
                selectedLensId: updated.selectedLensId ?? outcome.lensId,
                selectedScratchId: nil,
                changeSummary: changeSummary,
                model: "local-edit",
                now: DateFormats.now()
            )
        } else {
            updated.updateActiveVersion(lenses: themes, now: DateFormats.now())
        }
        return saveLensSet(updated, for: project, status: status)
    }

    private func lensHeroImages(
        _ heroImages: [ProjectLensHeroImage],
        lensId: String,
        activating imageId: String
    ) -> [ProjectLensHeroImage] {
        let normalizedLens = ProjectLens(lensId: lensId, heroImages: heroImages).normalized()
        var values = normalizedLens.heroImages
        guard let selectedIndex = values.firstIndex(where: { $0.imageId == imageId }),
              let groupId = values[selectedIndex].renderVersion?.renderVersionGroupId.trimmed.nilIfEmpty else {
            return values
        }
        for index in values.indices where values[index].renderVersion?.renderVersionGroupId == groupId {
            let isSelected = values[index].imageId == imageId
            values[index].renderVersion?.isActive = isSelected
        }
        return ProjectLens(lensId: lensId, heroImages: values).normalized().heroImages
    }

    private func lensWithRefreshedInitialDraftGenerationState(
        _ theme: ProjectLens,
        fallbackError: String = ""
    ) -> ProjectLens {
        var updated = theme
        guard !updated.generationRunId.trimmed.isEmpty else { return updated }
        let heroImages = updated.sortedHeroImages
        guard !heroImages.isEmpty else { return updated }
        let statuses = Set(heroImages.map { $0.status.trimmed.lowercased() })
        if statuses.contains("queued") || statuses.contains("generating") {
            updated.generationPhase = "hero_generating"
            updated.generationError = ""
            return updated
        }
        let readyCount = heroImages.filter { $0.status == "ready" && !$0.imagePath.trimmed.isEmpty }.count
        let firstError = heroImages
            .map(\.errorMessage)
            .first { !$0.trimmed.isEmpty }?
            .trimmed ?? fallbackError.trimmed
        if readyCount == heroImages.count {
            updated.generationPhase = "complete"
            updated.generationError = ""
        } else if readyCount > 0 {
            updated.generationPhase = "hero_partial"
            updated.generationError = firstError
        } else if statuses.contains("failed") || statuses.contains("cancelled") || statuses.contains("canceled") {
            updated.generationPhase = "hero_failed"
            updated.generationError = firstError
        }
        return updated
    }

    private func lensesByReplacing(existing: [ProjectLens], replacements: [ProjectLens]) -> [ProjectLens] {
        var output = existing
        for replacement in replacements {
            if let index = output.firstIndex(where: { $0.lensId == replacement.lensId }) {
                output[index] = replacement
            } else {
                output.append(replacement)
            }
        }
        return output
    }

    struct LensTrioRepairedSlice {
        var slice: LensTrioSliceResponse
        var primaryIndex: Int
        var accentIndexes: [Int]
        var profile: LensTrioBlendProfile
    }

    /// Resolves the trio's slate indexes into valid, collection-diverse selections, repairing
    /// out-of-range, duplicate, or collection-colliding picks from the top of the slate.
    func repairedLensTrioSelections(
        _ trio: LensTrioResponse,
        candidates: [LensContextStyleCandidate]
    ) -> (slices: [LensTrioRepairedSlice], warnings: [String]) {
        var warnings: [String] = []
        var usedPrimaries: Set<Int> = []
        var usedPrimaryCollections: Set<String> = []

        func isValid(_ index: Int) -> Bool {
            index >= 0 && index < candidates.count
        }

        func nextSlatePrimary(excluding accents: [Int]) -> Int? {
            candidates.indices.first { index in
                !usedPrimaries.contains(index)
                    && !accents.contains(index)
                    && !usedPrimaryCollections.contains(candidates[index].collectionKey)
            }
        }

        var repaired: [LensTrioRepairedSlice] = []
        for slice in trio.lenses.prefix(3) {
            var accents = slice.accentStyleIndexes.filter(isValid)
            var primary = slice.primaryStyleIndex

            if !isValid(primary) || usedPrimaries.contains(primary) {
                warnings.append("primary index \(primary) invalid or reused; refilled from slate")
                primary = -1
            }
            if primary >= 0, usedPrimaryCollections.contains(candidates[primary].collectionKey) {
                if let swapIndex = accents.firstIndex(where: { candidate in
                    !usedPrimaries.contains(candidate)
                        && !usedPrimaryCollections.contains(candidates[candidate].collectionKey)
                }) {
                    let promoted = accents.remove(at: swapIndex)
                    accents.insert(primary, at: 0)
                    warnings.append("primary collection collision; promoted accent [\(promoted)]")
                    primary = promoted
                } else {
                    warnings.append("primary collection collision; refilled from slate")
                    accents.insert(primary, at: 0)
                    primary = -1
                }
            }
            if primary < 0 {
                guard let replacement = nextSlatePrimary(excluding: accents) else { continue }
                primary = replacement
            }

            var cleanAccents: [Int] = []
            for accent in accents where accent != primary && !cleanAccents.contains(accent) {
                cleanAccents.append(accent)
                if cleanAccents.count == 2 { break }
            }
            if cleanAccents.count < 2 {
                for index in candidates.indices where index != primary && !cleanAccents.contains(index) && !usedPrimaries.contains(index) {
                    cleanAccents.append(index)
                    if cleanAccents.count == 2 { break }
                }
                warnings.append("accents refilled from slate for slice \(slice.sliceTitle)")
            }

            usedPrimaries.insert(primary)
            usedPrimaryCollections.insert(candidates[primary].collectionKey)
            repaired.append(LensTrioRepairedSlice(
                slice: slice,
                primaryIndex: primary,
                accentIndexes: cleanAccents,
                profile: LensTrioBlendProfile(rawValue: slice.blendProfile) ?? .dominant
            ))
        }
        return (repaired, warnings)
    }

    private func lensTrioTreatment(
        repaired: LensTrioRepairedSlice,
        candidates: [LensContextStyleCandidate],
        catalogVersion: String,
        now: String
    ) -> LensStyleTreatment {
        let weights = repaired.profile.weights
        func slot(_ index: Int, weight: Int) -> LensStyleTreatmentSlot {
            let candidate = candidates[index]
            return LensStyleTreatmentSlot(
                styleId: candidate.styleId,
                label: candidate.displayLabel,
                collection: candidate.collectionKey,
                hueHex: candidate.hueHex,
                url: candidate.imageUrl,
                weight: weight
            )
        }
        var accents: [LensStyleTreatmentSlot] = []
        if repaired.accentIndexes.count > 0 {
            accents.append(slot(repaired.accentIndexes[0], weight: weights.accentOne))
        }
        if repaired.accentIndexes.count > 1 {
            accents.append(slot(repaired.accentIndexes[1], weight: weights.accentTwo))
        }
        return LensStyleTreatment(
            catalogVersion: catalogVersion,
            primary: slot(repaired.primaryIndex, weight: weights.primary),
            accents: accents,
            updatedAt: now
        ).normalized()
    }

    @discardableResult
    func planLens() async -> Bool {
        guard projectLenses.lenses.isEmpty else {
            aestheticStatus = "SCENES already planned"
            return false
        }
        return await generateLens(renderAfterPlanning: false)
    }

    @discardableResult
    func generateLens() async -> Bool {
        guard projectLenses.lenses.isEmpty else {
            aestheticStatus = "SCENES already planned"
            return false
        }
        return await generateLens(renderAfterPlanning: true)
