    // MARK: - Frame plan composition and refresh

    /// The composition call shared by the first plan and every Story-driven refresh:
    /// grounds the context (brief, meaning graph, Story Input observations, roster and
    /// story cast), waits for an in-flight cast articulation so the world casts real
    /// names, validates the spread rule with one corrected retry, then repairs
    /// deterministically. Text-only: no ledger row, no pause guard.
    private func composeValidatedLensPlan(
        project: ProjectRecord,
        brief: ProjectGoalBriefV2,
        client: OpenAIClient,
        slateLines: [String],
        meaningContext: String
    ) async throws -> OpenAILensCompositionResult {
        if isArticulatingGoalCast, let task = goalCastArticulationTask {
            await task.value
        }
        var context = LensTrioContext(
            projectId: project.projectId,
            projectName: project.name,
            goalSummary: goalBriefV2StyleSummary(brief),
            meaningContext: meaningContext,
            slateLines: slateLines,
            rosterCharacterLines: lensPlanningCharacterLines(),
            mediaObservationLines: lensPlanningMediaObservationLines(lensPlanningObservationEntries())
        )
        var result = try await client.generateLensComposition(context: context)
        guard let error = LensCompositionSpread.validationError(areas: result.composition.lens.areas) else {
            return result
        }
        print("[lens_plan] spread_invalid retry=1 detail=\(error)")
        context.validationError = error
        result = try await client.generateLensComposition(context: context)
        if let secondError = LensCompositionSpread.validationError(areas: result.composition.lens.areas) {
            print("[lens_plan] spread_repaired detail=\(secondError)")
            result.composition.lens.areas = LensCompositionSpread.repaired(areas: result.composition.lens.areas)
        }
        return result
    }

    /// Roster characters first, then story-cast members the roster has not synced yet.
    private func lensPlanningCharacterLines() -> [String] {
        let rosterLines = projectCharacters.characters.map { character in
            var line = character.descriptionPrompt.isEmpty
                ? "- \(character.name)"
                : "- \(character.name) — \(character.descriptionPrompt)"
            if let gist = goalCastIdentityGist(forCharacter: character) {
                line += " | identity: \(gist)"
            }
            return line
        }
        let castLines = lensPlanningGoalCastLines(
            goalCast: goalCast,
            excludingNames: projectCharacters.characters.map(\.name)
        )
        return rosterLines + castLines
    }

    private func lensPlanningObservationEntries() -> [(filename: String, observation: ImageObservationResult)] {
        enabledContentItems
            .filter { $0.kind == .image }
            .compactMap { item in
                guard let observation = mediaObservationsById[item.mediaId] else { return nil }
                return (item.filename, observation)
            }
    }

    /// Whether the single plan still describes the active Story.
    var currentFramePlanStaleness: FramePlanStaleness {
        guard let lens = projectLenses.lenses.first,
              projectGoalV2.isReady,
              projectGoalV2.activeVersion != nil else { return .fresh }
        return framePlanStaleness(
            storedFingerprint: lens.body.planGoalFingerprint,
            activeFingerprint: currentLensContextGoalFingerprint
        )
    }

    var isFramePlanStale: Bool { currentFramePlanStaleness != .fresh }

    var currentFramePlanRefreshDecision: FramePlanRefreshDecision {
        guard let lens = projectLenses.lenses.first else { return .none }
        let rows = lens.heroImages(mediaVersion: lens.mediaVersionIds.last ?? "")
        return framePlanRefreshDecision(
            staleness: currentFramePlanStaleness,
            purePlanCount: rows.filter(\.isPurePlan).count,
            renderedCount: rows.filter { $0.status == "ready" && !$0.imagePath.trimmed.isEmpty }.count
        )
    }

    enum LensReplanTrigger {
        case storyChanged
        case manual
        case planMore
    }

    func refreshFramePlanFromStory() async -> Bool {
        await replanLensFromStory(trigger: .manual)
    }

    func planMoreFramesFromStory() async -> Bool {
        await replanLensFromStory(trigger: .planMore)
    }

    /// Re-composes the world from the current Story and folds it into the single plan:
    /// never-started suggestions are replaced in place, rendered and attempted frames stay
    /// verbatim (`.planMore` keeps everything and only appends). The merge runs against
    /// LIVE state after the text call, under the hero exclusive hold only for merge+save.
    @discardableResult
    func replanLensFromStory(trigger: LensReplanTrigger) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard let startingLens = projectLenses.lenses.first else {
            aestheticStatus = "Plan Frames first"
            return false
        }
        guard let version = projectGoalV2.activeVersion, version.brief.isReady else {
            aestheticStatus = "Save a Story first"
            return false
        }
        guard hasFreshLensContextForActiveGoal, !isRetrievingLensContext else {
            aestheticStatus = "Frame Context is still catching up with the Story"
            return false
        }
        guard !isGeneratingInitialDraftLenses, !isReplanningLensFromStory else {
            aestheticStatus = "A Frame plan is already running"
            return false
        }
        guard let contextResponse = lensContext.response, !contextResponse.styleCandidates.isEmpty else {
            aestheticStatus = "Frame Context has no style candidates"
            return false
        }
        let candidates = contextResponse.styleCandidates
        isReplanningLensFromStory = true
        lensPlanRefreshProgress = LensPlanRefreshProgress(
            title: "Refreshing Frame suggestions",
            detail: "Re-reading the Story and composing four moments across it.",
            status: "running"
        )
        aestheticStatus = "Refreshing Frame suggestions from the current Story"
        defer { isReplanningLensFromStory = false }

        do {
            let client = try OpenAIClient.fromEnvironment()
            let slateLines = candidates.enumerated().map { index, candidate in
                let moods = candidate.moods.prefix(3).joined(separator: "/")
                return "[\(index)] \(candidate.displayLabel) — \(candidate.collectionName.isEmpty ? candidate.collectionKey : candidate.collectionName) (\(candidate.collectionKey)) · \(moods) · \(candidate.hueName) · \(candidate.medium) — \(candidate.caption)"
            }
            let result = try await composeValidatedLensPlan(
                project: project,
                brief: version.brief,
                client: client,
                slateLines: slateLines,
                meaningContext: lensContextPromptJSON()
            )
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId,
                  projectGoalV2.activeVersion?.versionId == version.versionId,
                  let liveLens = projectLenses.lenses.first(where: { $0.lensId == startingLens.lensId }) else {
                lensPlanRefreshProgress = .idle
                return false
            }
            let slice = result.composition.lens
            let now = DateFormats.now()
            var rosterDraft = projectCharacters
            rosterDraft.projectId = project.projectId
            let rosterCountBefore = rosterDraft.characters.count
            var placesDraft = projectPlaces
            placesDraft.projectId = project.projectId
            let newestVersionId = liveLens.mediaVersionIds.last ?? ""
            let versionRows = liveLens.heroImages(mediaVersion: newestVersionId)
            // Sheet-driven suggestions survive a Story refresh: their anchor is a
            // character that still exists, and a Story chat turn must never make
            // them vanish.
            let keptFrames = trigger == .planMore ? versionRows : versionRows.filter { !$0.isPurePlan || $0.isSheetSuggestion }
            let newAreas = lensPlacesFromComposition(slice.areas, placesDraft: &placesDraft, now: now) ?? []
            let newCast = lensCastMembersFromComposition(slice.castMembers, rosterDraft: &rosterDraft, now: now)
            let dressing = uniqueNonEmpty(slice.setDressing + slice.setDressingImagePrompts)
            var candidate = liveLens
            candidate.body = liveLens.body.replannedWorld(
                areas: newAreas,
                castMembers: newCast,
                objectConcepts: slice.objectConcepts.isEmpty ? nil : slice.objectConcepts,
                setDressing: dressing.isEmpty ? nil : dressing,
                keptFrames: keptFrames,
                planGoalVersionId: version.versionId,
                planGoalFingerprint: currentLensContextGoalFingerprint
            ).normalized()
            let browseCatalog = try? await StyleBrowseCatalogRuntime.shared.loadCatalog()
            let styleReferenceIds = uniqueNonEmpty(candidate.body.styleIngredients.flatMap(\.sourceReferenceIds))
            let styleAuthorities = generatedTakeStyleAuthorities(lens: candidate, catalog: browseCatalog)
            let fresh = queuedLensConceptImages(
                lens: candidate,
                versionId: newestVersionId,
                mediaSummaries: aestheticMediaSummaryPackets(limit: 20),
                styleReferenceIds: styleReferenceIds,
                styleAuthorities: styleAuthorities,
                includeAreaImages: false
            )
            try Task.checkCancellation()
            // The catalog load awaited: read the lens once more right before the hold.
            guard currentProject?.projectId == project.projectId,
                  let latestLens = projectLenses.lenses.first(where: { $0.lensId == startingLens.lensId }) else {
                lensPlanRefreshProgress = .idle
                return false
            }
            beginLensHeroExclusiveHold(lensId: latestLens.lensId)
            defer { endLensHeroExclusiveHold() }
            let outcome = LensPlanMerge.merged(
                existing: latestLens.heroImages,
                fresh: fresh,
                mediaVersionId: newestVersionId,
                mode: trigger == .planMore ? .appendOnly : .replacePurePlans,
                now: now
            )
            var merged = latestLens
            merged.body = candidate.body
            merged.heroImages = outcome.heroImages
            merged.heroImage = merged.primaryHeroImage
            merged.updatedAt = now
            merged = merged.normalized()
            var updated = projectLenses
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            let replacedCount = outcome.replacedImageIds.count
            let appendedCount = outcome.appendedImageIds.count
            updated.appendVersion(
                lenses: lensesByReplacing(existing: updated.lenses, replacements: [merged]),
                scratchDrafts: updated.scratchDrafts,
                selectedLensId: merged.lensId,
                selectedScratchId: nil,
                changeSummary: "Refreshed the Scene Plan from the current Story: \(replacedCount) planned Frames replaced, \(appendedCount) added.",
                model: result.model,
                now: now
            )
            let statusLine = "Refreshed \(replacedCount + appendedCount) Frame suggestions from the current Story"
            guard saveLensSet(updated, for: project, status: statusLine) else {
                lensPlanRefreshProgress = LensPlanRefreshProgress(title: "Frame refresh failed", detail: lastError, status: "failed")
                return false
            }
            if rosterDraft.characters.count > rosterCountBefore {
                _ = saveProjectCharacters(rosterDraft, for: project, status: statusLine)
            }
            let oldPlaceIds = Set((latestLens.body.areas ?? []).map(\.placeId).filter { !$0.isEmpty })
            let survivingPlaceIds = Set((merged.body.areas ?? []).map(\.placeId).filter { !$0.isEmpty })
            let pinnedPlaceIds = Set(terrainMap.pins.map(\.placeId))
            let pruned = prunedProjectPlaces(
                placesDraft,
                retiredPlaceIds: oldPlaceIds.subtracting(survivingPlaceIds),
                referencedPlaceIds: survivingPlaceIds.union(pinnedPlaceIds),
                now: now
            )
            if pruned != projectPlaces {
                _ = saveProjectPlaces(pruned, for: project, status: statusLine)
            }
            reconcileLensCastFromTakes(lensId: merged.lensId)
            lensPlanRefreshProgress = .idle
            aestheticStatus = statusLine
            print("[frame_plan] refreshed project_id=\(project.projectId) trigger=\(trigger) replaced=\(replacedCount) appended=\(appendedCount) dropped=\(outcome.droppedImageIds.count)")
            return true
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                lensPlanRefreshProgress = .idle
                return false
            }
            lastError = error.localizedDescription
            lensPlanRefreshProgress = LensPlanRefreshProgress(title: "Frame refresh failed", detail: error.localizedDescription, status: "failed")
            aestheticStatus = "Frame refresh failed — Refresh suggestions to retry"
            return false
        }
    }

    @discardableResult
    private func generateLens(renderAfterPlanning: Bool) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        let blockers = lensGenerationBlockers
        guard blockers.isEmpty else {
            aestheticStatus = blockers.first ?? "The Scene Plan is not ready to generate"
            return false
        }
        guard let contextResponse = lensContext.response, !contextResponse.styleCandidates.isEmpty else {
            aestheticStatus = "Frame Context has no style candidates"
            return false
        }
        guard !isGeneratingInitialDraftLenses else { return false }

        let candidates = contextResponse.styleCandidates
        let totalStepCount = 6
        var progressLensTitles: [String] = []
        var heroRows: [InitialDraftLensHeroProgress] = []
        isGeneratingInitialDraftLenses = true
        lastError = ""
        aestheticStatus = "Composing the Scene Plan"
        initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
            title: "Reading your goal",
            detail: "Reading the Goal and \(candidates.count) matched styles.",
            status: "running",
            completedStepCount: 0,
            totalStepCount: totalStepCount
        )
        defer {
            isGeneratingInitialDraftLenses = false
        }

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let brief = projectGoalV2.activeBrief
            let goalBrief = goalBriefForInitialLensGeneration(from: brief)
            let mediaSummaries = aestheticMediaSummaryPackets(limit: 20)
            let runStartedAt = DateFormats.now()
            let generationRunId = "lens_gen_\(shortHash("\(project.projectId):\(runStartedAt)", length: 14))"
            let client = try OpenAIClient.fromEnvironment()

            let slateLines = candidates.enumerated().map { index, candidate in
                let moods = candidate.moods.prefix(3).joined(separator: "/")
                return "[\(index)] \(candidate.displayLabel) — \(candidate.collectionName.isEmpty ? candidate.collectionKey : candidate.collectionName) (\(candidate.collectionKey)) · \(moods) · \(candidate.hueName) · \(candidate.medium) — \(candidate.caption)"
            }
            let meaningContext = lensContextPromptJSON()

            aestheticStatus = "Composing the Scene Plan"
            initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                title: "Composing the Scene Plan",
                detail: "One inference composes the Scene Plan, its media prompts, and its style casting.",
                status: "running",
                completedStepCount: 1,
                totalStepCount: totalStepCount
            )
            let compositionResult = try await composeValidatedLensPlan(
                project: project,
                brief: brief,
                client: client,
                slateLines: slateLines,
                meaningContext: meaningContext
            )
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return false }

            let (repairedSlices, repairWarnings) = repairedLensTrioSelections(
                LensTrioResponse(lenses: [compositionResult.composition.lens]),
                candidates: candidates
            )
            if !repairWarnings.isEmpty {
                print("[lens_gen] repairs=\(repairWarnings.count) details=\(repairWarnings.joined(separator: " | "))")
            }
            guard repairedSlices.count == 1 else {
                throw ScreenGraphError.openAI("The Scene Plan composition response did not resolve into a usable Scene Plan.")
            }

            let browseCatalog = try? await StyleBrowseCatalogRuntime.shared.loadCatalog()
            if browseCatalog?.isUsable != true {
                print("[lens_gen] style browse catalog unavailable; media will be prompt-only")
            }

            let now = DateFormats.now()
            var generatedLenses: [ProjectLens] = []
            let planGoalVersionId = projectGoalV2.activeVersion?.versionId ?? ""
            let planGoalFingerprint = currentLensContextGoalFingerprint
            // Goal cast members become roster characters from birth: one draft threads
            // through every slice (so two slices naming "Kellan" share one entry) and
            // saves once for the whole gesture, before the lenses' studies queue.
            var rosterDraft = projectCharacters
            rosterDraft.projectId = project.projectId
            let rosterCountBeforeSlices = rosterDraft.characters.count
            // Composition areas become roster places the same way: one draft threads
            // through every slice and saves once for the whole gesture.
            var placesDraft = projectPlaces
            placesDraft.projectId = project.projectId
            let placeCountBeforeSlices = placesDraft.places.count
            for (sliceIndex, repaired) in repairedSlices.enumerated() {
                let slice = repaired.slice
                let treatment = lensTrioTreatment(
                    repaired: repaired,
                    candidates: candidates,
                    catalogVersion: contextResponse.schemaVersion,
                    now: now
                )
                let sourceLabels = uniqueNonEmpty(
                    [slice.title] + treatment.slots.map(\.label)
                )
                var startingFramePlan = slice.suggestedMediaPlan?.mediaPlan ?? LensMediaPlan()
                // Every frame is its own moment: the journey sequence is retired for new plans.
                startingFramePlan.mode = "collection"
                startingFramePlan.sequenceBeats = []
                startingFramePlan.compositeCount = 4
                startingFramePlan.characterCount = 1
                startingFramePlan.castObjectCount = 1
                var styleIngredients: [LensStyleIngredient] = []
                if let browseCatalog, browseCatalog.isUsable {
                    let slotIndexes = [repaired.primaryIndex] + repaired.accentIndexes
                    for (slotOrder, slotIndex) in slotIndexes.enumerated() {
                        let candidate = candidates[slotIndex]
                        guard let style = browseCatalog.style(withId: candidate.styleId),
                              let reference = style.styleImageReference(catalogVersion: browseCatalog.version) else {
                            continue
                        }
                        styleIngredients.append(.styleCatalogReference(
                            style: style,
                            reference: reference,
                            roleLabel: slotOrder == 0 ? "Primary style" : "Accent style",
                            collectionName: candidate.collectionName.isEmpty ? candidate.collectionKey : candidate.collectionName,
                            order: slotOrder + 1,
                            now: now
                        ))
                    }
                }
                var body = LensBody(
                    title: slice.title,
                    claim: slice.claim,
                    userNotes: "",
                    visualSummary: slice.visualSummary,
                    resolvedVisualLanguage: LensResolvedVisualLanguage(
                        look: slice.look,
                        palette: uniqueNonEmpty(slice.palette),
                        materials: uniqueNonEmpty(slice.materials),
                        productTreatment: [],
                        motifs: uniqueNonEmpty(slice.motifs),
                        composition: uniqueNonEmpty(slice.composition),
                        pacingEnergy: uniqueNonEmpty(slice.pacingEnergy),
                        avoid: lensLiteralVisualAvoidTerms(slice.avoid)
                    ),
                    colorPalette: [],
                    styleIngredients: styleIngredients,
                    paletteTerms: uniqueNonEmpty(slice.palette),
                    motifTerms: uniqueNonEmpty(slice.motifs),
                    textureMaterialTerms: uniqueNonEmpty(slice.materials),
                    compositionTerms: uniqueNonEmpty(slice.composition),
                    pacingEnergyTerms: uniqueNonEmpty(slice.pacingEnergy),
                    mustPreserve: uniqueNonEmpty(slice.mustPreserve),
                    mustAvoid: lensLiteralVisualAvoidTerms(slice.mustAvoid),
                    referenceMediaIds: [],
                    openQuestions: [],
                    readinessSummary: "Scene Plan composed from the Goal and catalog styles. Retune the treatment in Style Studio if the blend should shift.",
                    derivedVirtues: [],
                    styleTreatment: treatment,
                    goalSliceTitle: slice.sliceTitle,
                    goalSliceIntent: slice.sliceIntent,
                    characterImagePrompts: uniqueNonEmpty(slice.characterImagePrompts),
                    sceneImagePrompts: uniqueNonEmpty(slice.sceneImagePrompts),
                    objectImagePrompts: uniqueNonEmpty(slice.objectImagePrompts),
                    mediaPlan: startingFramePlan.normalized(),
                    setDressingImagePrompts: {
                        let dressing = uniqueNonEmpty(slice.setDressing + slice.setDressingImagePrompts)
                        return dressing.isEmpty ? nil : dressing
                    }(),
                    castMembers: lensCastMembersFromComposition(slice.castMembers, rosterDraft: &rosterDraft, now: now),
                    sceneSettings: slice.sceneSettings.isEmpty ? nil : slice.sceneSettings,
                    areas: lensPlacesFromComposition(slice.areas, placesDraft: &placesDraft, now: now),
                    objectConcepts: slice.objectConcepts.isEmpty ? nil : slice.objectConcepts,
                    planGoalVersionId: planGoalVersionId,
                    planGoalFingerprint: planGoalFingerprint
                ).sanitizedForGeneratedDraft(sourceLabels: sourceLabels)
                // Cast members matching the project roster by name auto-select so their
                // studies queue on the first render (references attach per-frame).
                if let members = body.castMembers {
                    let linkedIds = members.compactMap(\.characterId)
                    if !linkedIds.isEmpty {
                        var plan = body.resolvedMediaPlan
                        plan.selectedCharacterIds = linkedIds
                        body.mediaPlan = plan.normalized()
                    }
                }
                var lens = ProjectLens(
                    lensId: "lens_\(shortHash("\(project.projectId):lens:\(sliceIndex):\(now)", length: 12))",
                    status: .ready,
                    enabled: true,
                    body: body,
                    heroImage: nil,
                    heroImages: [],
                    relationSummary: .empty,
                    createdAt: now,
                    updatedAt: now
                )
                lens.generationRunId = generationRunId
                lens.generationPhase = "hero_queued"
                lens.generationError = ""
                generatedLenses.append(lens.normalized())
            }

            if rosterDraft.characters.count > rosterCountBeforeSlices {
                let added = rosterDraft.characters.dropFirst(rosterCountBeforeSlices).map(\.name)
                _ = saveProjectCharacters(
                    rosterDraft,
                    for: project,
                    status: "Added goal cast to roster: \(added.joined(separator: ", "))"
                )
            }

            if placesDraft.places.count > placeCountBeforeSlices {
                let added = placesDraft.places.dropFirst(placeCountBeforeSlices).map(\.name)
                _ = saveProjectPlaces(
                    placesDraft,
                    for: project,
                    status: "Added places to roster: \(added.joined(separator: ", "))"
                )
            }

            let lensTitles = generatedLenses.map { lens in
                lens.body.title.trimmed.isEmpty ? "Scene Plan" : lens.body.title
            }
            progressLensTitles = lensTitles
            _ = progressLensTitles

            for index in generatedLenses.indices {
                try Task.checkCancellation()
                guard currentProject?.projectId == project.projectId else { return false }
                let styleReferenceIds = uniqueNonEmpty(
                    generatedLenses[index].body.styleIngredients.flatMap(\.sourceReferenceIds)
                )
                let styleAuthorities = generatedTakeStyleAuthorities(
                    lens: generatedLenses[index],
                    catalog: browseCatalog
                )
                var lensMediaImages = queuedLensConceptImages(
                    lens: generatedLenses[index],
                    versionId: "",
                    mediaSummaries: mediaSummaries,
                    styleReferenceIds: styleReferenceIds,
                    styleAuthorities: styleAuthorities,
                    includeAreaImages: false
                )
                if lensMediaImages.isEmpty {
                    let prompt = lensHeroPrompt(
                        theme: generatedLenses[index],
                        goalBrief: goalBrief,
                        mediaSummaries: mediaSummaries
                    )
                    lensMediaImages = queuedLensHeroImages(
                        lensId: generatedLenses[index].lensId,
                        routeKey: "lens_media_hero",
                        recipe: nil,
                        sourceAestheticIds: [],
                        sourceReferenceIds: styleReferenceIds,
                        mediaPlan: generatedLenses[index].body.resolvedMediaPlan,
                        styleAuthorities: styleAuthorities,
                        prompt: prompt,
                        now: DateFormats.now()
                    )
                }
                generatedLenses[index].heroImages = lensMediaImages
                generatedLenses[index].heroImage = generatedLenses[index].primaryHeroImage
                generatedLenses[index].generationPhase = "hero_queued"
                generatedLenses[index].updatedAt = DateFormats.now()
                generatedLenses[index] = generatedLenses[index].normalized()
                heroRows.append(contentsOf: lensMediaImages.map {
                    InitialDraftLensHeroProgress(
                        imageId: $0.imageId,
                        lensTitle: lensTitles[index],
                        providerLabel: $0.label.trimmed.isEmpty ? $0.provider.capitalized : $0.label,
                        status: $0.status
                    )
                })
            }

            guard currentProject?.projectId == project.projectId else { return false }
            var updated = projectLenses
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                title: "Saving the Scene Plan",
                detail: "Persisting the Scene Plan before its media renders.",
                status: "running",
                completedStepCount: 2,
                totalStepCount: totalStepCount,
                lensTitles: lensTitles,
                heroRows: heroRows
            )
            updated.appendVersion(
                lenses: lensesByReplacing(existing: updated.lenses, replacements: generatedLenses),
                scratchDrafts: updated.scratchDrafts,
                selectedLensId: generatedLenses.first?.lensId,
                selectedScratchId: nil,
                changeSummary: "Generated the Scene Plan from the Goal, cast from the style catalog.",
                model: compositionResult.model,
                now: DateFormats.now()
            )
            guard saveLensSet(
                updated,
                for: project,
                status: renderAfterPlanning ? "Generated Scene; media rendering queued" : "Planned Scene frames"
            ) else {
                return false
            }

            if !renderAfterPlanning {
                aestheticStatus = "Planned Scene frames"
                initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                    title: "Planned Scene frames",
                    detail: "\(heroRows.count) take slot\(heroRows.count == 1 ? "" : "s") ready to render.",
                    status: "complete",
                    completedStepCount: 3,
                    totalStepCount: totalStepCount,
                    lensTitles: lensTitles,
                    heroRows: heroRows
                )
                print("[lens_plan] completed project_id=\(project.projectId) run_id=\(generationRunId) queued=\(heroRows.count)")
                return true
            }

            // Sequential media chain: the scene renders first, then the character with the
            // rendered scene attached as a continuity reference, then the object with both.
            let stabilityClient = try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let generatedLens = generatedLenses[0]
            let orderedMedia = generatedLens.sortedHeroImages.filter { $0.status == "queued" }
            let fallbackCatalog = await styleBrowseCatalogForAttachmentFallback()
            var chainReferences: [LensConceptChainEntry] = []
            var completedHeroSlots = 0
            var readyHeroSlots = 0
            var lastSlotErrorMessage = ""
            aestheticStatus = "Rendering Scene Plan media"

            for heroImage in orderedMedia {
                try Task.checkCancellation()
                try await waitWhileGenerationPaused()
                guard currentProject?.projectId == project.projectId else { return false }
                let mediaLabel = heroImage.label.trimmed.isEmpty ? heroImage.provider.capitalized : heroImage.label
                initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                    title: "Rendering \(mediaLabel)",
                    detail: "\(readyHeroSlots)/\(orderedMedia.count) Scene Plan media ready.",
                    status: "running",
                    completedStepCount: min(2 + completedHeroSlots, totalStepCount),
                    totalStepCount: totalStepCount,
                    lensTitles: lensTitles,
                    heroRows: heroRows
                )
                let provider = LensHeroImageProvider(rawValue: heroImage.provider) ?? .openAI
                let isCharacterStudy = LensConceptCategory.category(for: heroImage) == .characters
                let fileName = "\(generationRunId)_\(safeIdentifier(generatedLens.lensId))_\(safeIdentifier(heroImage.imageId)).\(isCharacterStudy ? "png" : "jpg")"
                let assignedStyleId = heroImage.sourceAestheticIds.first
                let continuityURLs = lensConceptContinuityURLs(
                    assignedStyleId: assignedStyleId,
                    chain: chainReferences
                )
                let characterScopeId = isCharacterStudy
                    ? lensResolvedTakeCharacterId(for: heroImage, lens: generatedLens, cast: lensCompositeCast(for: generatedLens))
                    : ""
                let plan = provider == .openAI
                    ? lensBlendAttachmentPlan(
                        lens: generatedLens,
                        catalog: fallbackCatalog,
                        assignedStyleId: assignedStyleId,
                        characterScopeId: characterScopeId,
                        continuityURLs: continuityURLs
                    )
                    : LensBlendAttachmentPlan()
                let job = LensHeroGenerationJob(
                    lensId: generatedLens.lensId,
                    imageId: heroImage.imageId,
                    provider: provider,
                    skipPromptEnrichment: heroImage.promptEnrichmentDisabled,
                    prompt: heroImage.prompt,
                    sourcePrompt: heroImage.sourcePrompt.trimmed.isEmpty ? heroImage.prompt : heroImage.sourcePrompt,
                    negativePrompt: heroImage.negativePrompt,
                    attachments: plan.entries,
                    promptPreamble: plan.promptPreamble,
                    attachmentManifest: plan.manifestText,
                    styleSummary: plan.styleSummaryText,
                    attachmentManifestEntries: plan.manifestEntryLinesText,
                    attachmentStylePolicy: plan.manifestPolicyText,
                    imageSize: generatedLens.body.resolvedMediaPlan.imageSize,
                    stabilityAspectRatio: generatedLens.body.resolvedMediaPlan.stabilityAspectRatio,
                    stabilityStrength: heroImage.stabilityStrength,
                    mediaPlan: generatedLens.body.resolvedMediaPlan,
                    transparentBackground: isCharacterStudy,
                    outputURL: contextStore.aestheticProofDirectory(for: project).appendingPathComponent(fileName),
                    projectId: project.projectId,
                    runId: heroImage.imageId
                )
                let outcome = await LensHeroImageRunner.generate(
                    job: job,
                    openAIClient: client,
                    stabilityClient: stabilityClient
                )
                guard currentProject?.projectId == project.projectId else { return false }
                completedHeroSlots += 1
                if outcome.status == "ready" {
                    readyHeroSlots += 1
                    chainReferences.append(LensConceptChainEntry(
                        styleId: heroImage.sourceAestheticIds.first ?? "",
                        category: LensConceptCategory.category(for: heroImage),
                        url: URL(fileURLWithPath: outcome.imagePath)
                    ))
                } else if outcome.status == "failed" {
                    lastSlotErrorMessage = outcome.errorMessage
                }
                if let rowIndex = heroRows.firstIndex(where: { $0.imageId == outcome.imageId }) {
                    heroRows[rowIndex].status = outcome.status
                }
                let statusVerb = outcome.status == "ready" ? "ready" : outcome.status
                _ = saveLensHeroImageOutcome(
                    outcome,
                    project: project,
                    status: "Generated Scene Plan; \(readyHeroSlots)/\(orderedMedia.count) media ready",
                    changeSummary: "\(mediaLabel) Scene Plan media \(statusVerb).",
                    appendVersion: false
                )
                initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                    title: "\(mediaLabel) media \(statusVerb)",
                    detail: "\(readyHeroSlots)/\(orderedMedia.count) Scene Plan media ready.",
                    status: "running",
                    completedStepCount: min(2 + completedHeroSlots, totalStepCount),
                    totalStepCount: totalStepCount,
                    lensTitles: lensTitles,
                    heroRows: heroRows
                )
            }

            guard currentProject?.projectId == project.projectId else { return false }
            if !lastSlotErrorMessage.isEmpty {
                lastError = lastSlotErrorMessage
            }
            let finalStatus = readyHeroSlots == orderedMedia.count
                ? "Generated Scene Plan"
                : "Generated Scene Plan; \(readyHeroSlots)/\(orderedMedia.count) media ready"
            aestheticStatus = finalStatus
            initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                title: "Generated Scene Plan",
                detail: "\(readyHeroSlots)/\(orderedMedia.count) Scene Plan media ready.",
                status: readyHeroSlots == orderedMedia.count ? "complete" : "partial",
                completedStepCount: totalStepCount,
                totalStepCount: totalStepCount,
                lensTitles: lensTitles,
                heroRows: heroRows
            )
            print("[lens_gen] completed project_id=\(project.projectId) run_id=\(generationRunId) media_ready=\(readyHeroSlots)/\(orderedMedia.count)")
            return true
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return false
            }
            lastError = error.localizedDescription
            aestheticStatus = "Scene Plan generation failed"
            initialDraftLensGenerationProgress = InitialDraftLensGenerationProgress(
                title: "Scene Plan generation failed",
                detail: error.localizedDescription,
                status: "failed",
                completedStepCount: 0,
                totalStepCount: totalStepCount,
                lensTitles: progressLensTitles,
                heroRows: heroRows
            )
            return false
        }
    }

    /// Pauses or resumes every generation chain. Pausing is cooperative: the in-flight
    /// render finishes and saves, then each sequential loop parks at its loop-top check
    /// until resumed. A parked loop keeps its isGenerating* flag true, which blocks new
    /// runs from starting and keeps the interrupted-media reconciler away from frames
    /// that are legitimately waiting in "queued". Single-shot entry points refuse to
    /// start while paused instead of parking.
    /// PAUSE GOVERNS SPEND: every paid entry point refuses (or parks) while
    /// paused — shot renders, join bridges, Shot/Clip Looks and their
    /// retries, narration TTS, and every sequential generation loop. Free
    /// local work (reverse/reel/ambient bakes, retimes, trims) continues.
    /// The pause is cooperative: an in-flight provider call finishes and
    /// saves; loops park at their loop-top check until resumed.
    func setGenerationPaused(_ paused: Bool) {
        guard isGenerationPaused != paused else { return }
        isGenerationPaused = paused
        print("[generation_pause] \(paused ? "paused" : "resumed")")
    }

    /// Parks a sequential generation loop while paused. Cancellation still interrupts
    /// immediately, so Stop and project-switch semantics are unchanged while parked.
    private func waitWhileGenerationPaused() async throws {
        while isGenerationPaused {
            try Task.checkCancellation()
            try await Task.sleep(nanoseconds: 250_000_000)
        }
    }

    @discardableResult
    func renderLensMedia(lensId: String, scope: LensMediaRenderScope) async -> Bool {
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let targets = lens.sortedHeroImages
            .filter { image in
                scope.includes(LensConceptCategory.category(for: image))
                    && image.status != "ready"
                    && image.status != "generating"
            }
            .sorted { $0.imageIndex < $1.imageIndex }
        guard !targets.isEmpty else {
            aestheticStatus = "No \(scope.label.lowercased()) takes are waiting to render"
            return false
        }

        var rendered = 0
        for image in targets {
            guard currentProject != nil else { return false }
            if await renderLensHeroImage(lensId: lensId, imageId: image.imageId) {
                rendered += 1
            }
        }
        aestheticStatus = rendered == targets.count
            ? "Rendered \(scope.label)"
            : "Rendered \(rendered)/\(targets.count) \(scope.label.lowercased()) takes"
        return rendered > 0
    }

    @discardableResult
    func renderLensHeroImage(
        lensId: String,
        imageId: String,
        stack: RenderStack = RenderStackRegistry.shared.fallback
    ) async -> Bool {
        await retryLensHeroImage(lensId: lensId, imageId: imageId, stack: stack)
    }

    @discardableResult
    func startLensHeroImageSiblingRender(
        lensId: String,
        imageId: String,
        request rawRequest: LensTakeRenderRequest
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        if let reason = lensHeroTakeStartBlockReason {
            aestheticStatus = reason
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var renderRequest = rawRequest.normalized()
        let stack = renderRequest.stack
        let supportsAttachment = stack.styleImageAttachSupported
        if renderRequest.styleMode == .attachStyleImage, !supportsAttachment {
            aestheticStatus = "\(stack.label) does not support prompt-aware style image attachments"
            lastError = aestheticStatus
            return false
        }
        if stack.isFAL {
            let validationError = FALImageClient.validateDebugParameters(
                renderRequest.debugParametersJSON,
                stack: stack,
                styleMode: renderRequest.styleMode
            )
            if !validationError.isEmpty {
                aestheticStatus = "FAL debug parameters are invalid"
                lastError = validationError
                return false
            }
        }
        var heroImages = lens.sortedHeroImages
        guard let sourceIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Frame not found"
            return false
        }
        let sourceImage = heroImages[sourceIndex].normalized()
        if renderRequest.styleMode == .attachStyleImage, sourceImage.styleAuthorities.isEmpty {
            aestheticStatus = "No style image is available for this take"
            lastError = aestheticStatus
            return false
        }
        if sourceImage.styleAuthorities.isEmpty {
            renderRequest.styleMode = .none
        }
        let provider: LensHeroImageProvider = stack.heroProvider
        let now = DateFormats.now()
        let sourceCategory = LensConceptCategory.category(for: sourceImage)
        let isCharacterStudy = sourceCategory == .characters
        let civitaiSeed = provider == .civitaiWan27 ? Int.random(in: 1...Int(Int32.max)) : nil
        let siblingImageId = "lens_hero_\(shortHash("\(project.projectId):\(lensId):\(imageId):\(stack.id):\(renderRequest.styleMode.rawValue):\(now)", length: 14))"
        let styleAuthorities = renderRequest.styleMode == .none ? [] : sourceImage.styleAuthorities
        let sourceAestheticIds = renderRequest.styleMode == .none ? [] : sourceImage.sourceAestheticIds
        let dependencies = renderRequest.styleMode == .none
            ? sourceImage.sourceDependencies.filter { $0.role != "style_source" }
            : sourceImage.sourceDependencies
        let renderRecipe: LensRenderRecipeSnapshot
        if stack.isFAL {
            renderRecipe = stack.renderRecipeSnapshot(
                mediaPlan: lens.body.resolvedMediaPlan,
                styleMode: renderRequest.styleMode,
                debugParametersJSON: renderRequest.debugParametersJSON
            )
        } else {
            renderRecipe = provider.renderRecipeSnapshot(
                mediaPlan: lens.body.resolvedMediaPlan,
                isCharacterStudy: isCharacterStudy,
                hasStyleReferences: renderRequest.styleMode == .attachStyleImage && !styleAuthorities.isEmpty,
                seed: civitaiSeed,
                stack: stack,
                sourceImageCount: renderRequest.styleMode == .attachStyleImage ? 1 : 0
            )
        }
        var sibling = ProjectLensHeroImage(
            imageId: siblingImageId,
            imageIndex: (heroImages.map(\.imageIndex).max() ?? sourceImage.imageIndex) + 1,
            label: uniqueNonEmpty([sourceImage.label, stack.label]).joined(separator: " · "),
            provider: provider.rawValue,
            model: renderRecipe.model,
            imagePath: "",
            prompt: sourceImage.sourcePrompt.trimmed.isEmpty ? sourceImage.prompt : sourceImage.sourcePrompt,
            sourcePrompt: sourceImage.sourcePrompt.trimmed.isEmpty ? sourceImage.prompt : sourceImage.sourcePrompt,
            negativePrompt: "",
            status: "generating",
            sourceRouteKey: sourceImage.sourceRouteKey,
            sourceRecipeId: sourceImage.sourceRecipeId,
            sourceRecipeVersion: sourceImage.sourceRecipeVersion,
            sourceAestheticIds: sourceAestheticIds,
            subject: sourceImage.subject,
            styleAuthorities: styleAuthorities,
            renderRecipe: renderRecipe,
            sourceDependencies: dependencies,
            imageKind: sourceImage.imageKind,
            characterId: sourceImage.characterId,
            areaId: sourceImage.areaId,
            sceneId: sourceImage.sceneId,
            areaImageId: sourceImage.areaImageId,
            homeSceneImageId: sourceImage.homeSceneImageId,
            taxonomyEnabled: sourceImage.taxonomyEnabled,
            kept: nil,
            generatedAt: "",
            updatedAt: now
        ).normalized()
        // Retries route through the sibling path — a verbatim frame's sibling
        // stays verbatim (the job below reads this same flag).
        sibling.promptEnrichmentDisabled = sourceImage.promptEnrichmentDisabled
        sibling.stabilityStrength = sourceImage.stabilityStrength
        heroImages.append(sibling)

        guard registerLensHeroTakeOperation(imageId: siblingImageId, lensId: lensId) else {
            return false
        }
        defer { unregisterLensHeroTakeOperation(imageId: siblingImageId) }

        let statusPrefix = "Starting \(stack.label) Scene Plan sibling"
        aestheticStatus = statusPrefix
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: statusPrefix,
            changeSummary: "Started \(stack.label) sibling render."
        ) else {
            return false
        }
        inheritStageMembership(fromImageId: sourceImage.imageId, toImageId: siblingImageId)

        let runId = "lens_sibling_\(shortHash("\(project.projectId):\(lensId):\(siblingImageId):\(now)", length: 14))"
        let outputExtension = (provider == .openAI && isCharacterStudy) || stack.usesPNGOutput ? "png" : "jpg"
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(runId)_\(safeIdentifier(lensId))_\(safeIdentifier(siblingImageId)).\(outputExtension)")
        let retryVersionId = ProjectLens.mediaVersionId(fromRouteKey: sourceImage.sourceRouteKey)
        let assignedStyleId = sourceImage.sourceAestheticIds.first
        let retryChain: [LensConceptChainEntry] = sourceImage.sourceRouteKey.hasPrefix("lens_media_")
            ? lens.heroImages(mediaVersion: retryVersionId)
                .filter { $0.status == "ready" && $0.imageIndex < sourceImage.imageIndex && !$0.imagePath.trimmed.isEmpty }
                .sorted { $0.imageIndex < $1.imageIndex }
                .map {
                    LensConceptChainEntry(
                        styleId: $0.sourceAestheticIds.first ?? "",
                        category: LensConceptCategory.category(for: $0),
                        url: URL(fileURLWithPath: $0.imagePath)
                    )
                }
            : []
        let continuityURLs = lensConceptContinuityURLs(assignedStyleId: assignedStyleId, chain: retryChain)
        let styleCatalog = await styleBrowseCatalogForAttachmentFallback()
        let renderLens = lensApplyingTakeStyleOverride(lens, image: sourceImage)
        let usesAttachmentPlan = renderRequest.styleMode == .attachStyleImage && (provider == .openAI || provider == .fal || provider == .stability)
        let siblingCharacterScopeId = isCharacterStudy
            ? lensResolvedTakeCharacterId(for: sourceImage, lens: lens, cast: lensCompositeCast(for: lens))
            : ""
        let plan = usesAttachmentPlan
            ? lensBlendAttachmentPlan(
                lens: renderLens,
                catalog: styleCatalog,
                assignedStyleId: sourceImage.sourceAestheticIds.first,
                characterScopeId: siblingCharacterScopeId,
                continuityURLs: provider == .fal ? [] : continuityURLs
            )
            : LensBlendAttachmentPlan()
        let attachmentEntries = provider == .fal || provider == .stability ? plan.styleEntries : plan.entries
        let styleSummary: String
        if renderRequest.styleMode == .describeStyleInPrompt {
            styleSummary = takeStyleSummary(sourceImage)
        } else if renderRequest.styleMode == .attachStyleImage, provider == .openAI || provider == .stability {
            styleSummary = plan.styleSummaryText
        } else {
            styleSummary = ""
        }
        let job = LensHeroGenerationJob(
            lensId: lensId,
            imageId: siblingImageId,
            provider: provider,
            stack: stack,
            styleMode: renderRequest.styleMode,
            debugParametersJSON: renderRequest.debugParametersJSON,
            sourceImageCount: renderRequest.styleMode == .attachStyleImage ? attachmentEntries.count : 0,
            skipPromptEnrichment: sibling.promptEnrichmentDisabled,
            prompt: sibling.prompt,
            sourcePrompt: sibling.sourcePrompt,
            negativePrompt: sibling.negativePrompt,
            attachments: attachmentEntries,
            promptPreamble: renderRequest.styleMode == .attachStyleImage ? plan.promptPreamble : "",
            attachmentManifest: provider == .fal || provider == .stability ? "" : plan.manifestText,
            styleSummary: styleSummary,
            attachmentManifestEntries: provider == .fal || provider == .stability ? "" : plan.manifestEntryLinesText,
            attachmentStylePolicy: provider == .fal || provider == .stability ? "" : plan.manifestPolicyText,
            imageSize: stack.imageSize ?? lens.body.resolvedMediaPlan.imageSize,
            stabilityAspectRatio: stack.isStability ? stack.stabilityAspectRatio : lens.body.resolvedMediaPlan.stabilityAspectRatio,
            stabilityStrength: sibling.stabilityStrength,
            mediaPlan: lens.body.resolvedMediaPlan,
            transparentBackground: isCharacterStudy,
            civitaiSeed: civitaiSeed,
            outputURL: outputURL,
            projectId: project.projectId,
            runId: siblingImageId
        )

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let needsOpenAIClient = provider == .openAI
                || ((provider == .fal || provider == .stability) && !job.skipPromptEnrichment)
            let client = needsOpenAIClient ? try OpenAIClient.fromEnvironment() : nil
            let stabilityClient = provider == .stability
                ? try StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
                : try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let civitaiImageProvider = provider == .civitaiWan27
                ? CivitAIWANImageProvider(credentialStore: videoCredentialStore)
                : nil
            let falImageClient = provider == .fal
                ? FALImageClient(credentialStore: videoCredentialStore)
                : nil
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider,
                falImageClient: falImageClient
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let status = outcome.status == "ready"
                ? "\(stack.label) Scene Plan sibling ready"
                : "\(stack.label) Scene Plan sibling \(outcome.status)"
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: status,
                changeSummary: "\(stack.label) sibling render \(outcome.status).",
                appendVersion: false
            )
            aestheticStatus = status
            if outcome.status == "failed" {
                lastError = outcome.errorMessage
            }
            return outcome.status == "ready"
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let failedAt = DateFormats.now()
            let status = (Task.isCancelled || isCancellationLikeError(error)) ? "cancelled" : "failed"
            let outcome = LensHeroGenerationOutcome(
                lensId: lensId,
                imageId: siblingImageId,
                provider: provider,
                status: status,
                imagePath: "",
                prompt: sibling.prompt,
                sourcePrompt: sibling.sourcePrompt,
                negativePrompt: sibling.negativePrompt,
                promptEnrichmentModel: "",
                promptEnrichmentResponseId: "",
                promptEnrichmentTraceId: "",
                promptEnrichmentSummary: "",
                requestId: "",
                traceId: "",
                errorMessage: error.localizedDescription,
                generatedAt: "",
                updatedAt: failedAt,
                renderRecipe: nil
            )
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: "\(stack.label) Scene Plan sibling \(status)",
                changeSummary: "\(stack.label) sibling render \(status).",
                appendVersion: false
            )
            lastError = error.localizedDescription
            aestheticStatus = "\(stack.label) Scene Plan sibling \(status)"
            return false
        }
    }

    /// The in-place fulfillment row: identity fields (id, board slot, label, route
    /// key, planner subject, home scene, kept) come from the planned row; everything
    /// else — prompt payload, style, recipe, dependencies, status — from the freshly
    /// built take. Internal for tests.
    func lensPlanFulfilledTake(
        planned: ProjectLensHeroImage,
        rendered: ProjectLensHeroImage
    ) -> ProjectLensHeroImage {
        var value = rendered
        value.imageId = planned.imageId
        value.imageIndex = planned.imageIndex
        value.label = planned.label
        value.sourceRouteKey = planned.sourceRouteKey
        value.subject = planned.subject ?? rendered.subject
        value.homeSceneImageId = planned.homeSceneImageId
        value.kept = planned.kept
        value.suggestedForCharacterId = planned.suggestedForCharacterId
        value.suggestedAt = planned.suggestedAt
        return value.normalized()
    }

    /// Renders a custom take. With a template, the take derives from it (prompt seed
    /// happens modal-side; taxonomy/style/version inherit here). With a nil template
    /// this is a BLANK frame: `blankCategory` supplies the section identity and
    /// `versionId` the media-version board the user was viewing.
    func startLensHeroNewTakeRender(
        lensId: String,
        templateImageId: String?,
        blankCategory: LensConceptCategory? = nil,
        versionId: String = "",
        request: LensNewTakeRenderRequest,
        onRowCreated: ((String) -> Void)? = nil
    ) async -> Bool {
        await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: templateImageId,
            blankCategory: blankCategory,
            versionId: versionId,
            request: request,
            fulfillsPlannedTemplate: false,
            onRowCreated: onRowCreated
        )
    }

    /// Spawns a frame from a placed clip's moment (the Inspector's deck): the
    /// blank-frame path with the seed still riding the request's attachments.
    /// When the seed asks for shot placement, the generating row is inserted
    /// beside the clip THE MOMENT it exists — the NOT-READY cell is the
    /// planned cell, and it fulfills in place when the render lands.
    @discardableResult
    func startClipMomentRender(
        seed: ClipMomentSeed,
        lensId: String,
        versionId: String,
        request: LensNewTakeRenderRequest
    ) async -> Bool {
        await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: nil,
            blankCategory: .scenery,
            versionId: versionId,
            request: request,
            fulfillsPlannedTemplate: false,
            onRowCreated: { [weak self] imageId in
                guard let self, seed.placeIntoShot else { return }
                self.placeSpawnedFrame(seed: seed, imageId: imageId)
            }
        )
    }

    /// Renders a blank frame gathered for a STAGE: the generating row joins
    /// the stage's palette the moment it exists (the pool card carries the
    /// shimmer/failed states), and — from a cut rail's "+" — also lands at
    /// the end of that cut as a planned entry that fulfills in place.
    @discardableResult
    func startStageFrameRender(
        stageId: String,
        appendToCutId: String? = nil,
        lensId: String,
        versionId: String,
        request: LensNewTakeRenderRequest
    ) async -> Bool {
        await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: nil,
            blankCategory: .scenery,
            versionId: versionId,
            request: request,
            fulfillsPlannedTemplate: false,
            onRowCreated: { [weak self] imageId in
                guard let self else { return }
                self.addStageFrameInput(stageId: stageId, frameImageId: imageId)
                if let cutId = appendToCutId,
                   let cut = self.shotTimeline.shots.first(where: { $0.shotId == cutId }) {
                    // The cut may have rendered while this frame generated —
                    // a frozen strip must not gain a late entry UNLESS the
                    // suffix tail is open (appends are inherently tail-side).
                    if self.isCutStructureFrozen(shotId: cutId),
                       self.cutSuffixTailStartIndex(shotId: cutId) == nil {
                        self.aestheticStatus = "The cut rendered while this frame was generating — it joined the stage palette instead"
                    } else {
                        self.insertShotFrame(shotId: cutId, frameImageId: imageId, at: cut.entries.count)
                    }
                }
            }
        )
    }

    /// Renders a Frame directly into the flat workspace. The generated row is
    /// already visible in Source Material; an optional Shot placement is made
    /// as soon as the row exists so queued and failed state stays inspectable.
    @discardableResult
    func startShotFrameRender(
        appendToShotId: String? = nil,
        lensId: String,
        versionId: String,
        request: LensNewTakeRenderRequest
    ) async -> Bool {
        var createdImageId = ""
        var initialPlacementPersisted = appendToShotId == nil
        let rendered = await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: nil,
            blankCategory: .scenery,
            versionId: versionId,
            request: request,
            fulfillsPlannedTemplate: false,
            onRowCreated: { [weak self] imageId in
                guard let self else { return }
                createdImageId = imageId
                initialPlacementPersisted = self.placeShotScopedGeneratedFrame(
                    imageId: imageId,
                    shotId: appendToShotId
                )
            }
        )
        // A Shot-scoped command has two durable outputs. Retry the placement
        // after the provider lifecycle only when the initial timeline write
        // did not persist. If it did persist and the operator removed the
        // queued/failed entry while generation ran, never resurrect it here.
        if !initialPlacementPersisted, !createdImageId.isEmpty {
            _ = placeShotScopedGeneratedFrame(
                imageId: createdImageId,
                shotId: appendToShotId
            )
        }
        return rendered
    }

    /// Idempotently completes the placement half of `New Frame for this
    /// Shot…`. The generated Frame remains independently visible in Source
    /// Material on every refusal; rendered-prefix/tail rules stay canonical.
    @discardableResult
    private func placeShotScopedGeneratedFrame(imageId: String, shotId: String?) -> Bool {
        guard let shotId = shotId?.trimmed.nilIfEmpty else { return true }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else {
            aestheticStatus = "The originating Shot no longer exists — the Frame remains in Source Material"
            return false
        }
        if shot.entries.contains(where: { $0.frameImageId == imageId }) {
            return true
        }
        if isCutStructureFrozen(shotId: shotId), cutSuffixTailStartIndex(shotId: shotId) == nil {
            aestheticStatus = "The Shot became fully rendered before the Frame could be placed — the Frame remains in Source Material"
            return false
        }
        let placed = insertShotFrame(
            shotId: shotId,
            frameImageId: imageId,
            at: shot.entries.count
        )
        if placed {
            let destinationName = shot.name.trimmed.nilIfEmpty ?? "the originating Shot"
            aestheticStatus = "Frame added to " + destinationName
        } else {
            aestheticStatus = "The Frame was created, but its Shot placement could not be saved"
        }
        return placed
    }

    /// Places a modal-born transform child (reframe / variation / restyle)
    /// beside its source strip cell THE MOMENT the generating row exists —
    /// the punch-in placement law, single-entry: the anchor entry must still
    /// exist and still hold the parent frame; a missing anchor or a
    /// freeze-law refusal degrades to a tail append; a fully locked strip
    /// leaves the child in the pool and says so. `insertShotFrame` runs the
    /// freeze law itself, so this never re-derives the lock.
    func placeTransformChildBesideSource(
        cutId: String,
        sourceEntryId: String,
        parentImageId: String,
        imageId: String
    ) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == cutId }) else {
            aestheticStatus = "The result renders in Source Material — its Scene no longer exists"
            return
        }
        let anchorIndex = shot.entries.firstIndex {
            $0.entryId == sourceEntryId && $0.frameImageId == parentImageId
        }
        if let anchorIndex,
           insertShotFrame(shotId: cutId, frameImageId: imageId, at: anchorIndex + 1) {
            return
        }
        if insertShotFrame(shotId: cutId, frameImageId: imageId, at: shot.entries.count) {
            aestheticStatus = "The result renders at the Scene's end — the strip before the rendered tail is locked"
            return
        }
        aestheticStatus = "The result renders in Source Material — this Scene's strip is locked"
    }

    /// Inserts a just-spawned frame's entry beside its seed clip (before for
    /// precede, after for continue/transform). A vanished shot or entry is
    /// tolerated — the frame still lives on the board.
    private func placeSpawnedFrame(seed: ClipMomentSeed, imageId: String) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == seed.shotId }),
              let clipIndex = shot.entries.firstIndex(where: { $0.entryId == seed.entryId }) else {
            return
        }
        let index = seed.intent == .precede ? clipIndex : clipIndex + 1
        insertShotFrame(shotId: seed.shotId, frameImageId: imageId, at: index)
    }

    /// Captures a clip moment as a QUIET working still (curation-rejected
    /// `video_frame` — displayed nowhere, scan-preserved) for use as a render
    /// seed attachment. The moodboard "Capture Still" flow stays separate.
    func captureClipSeedStill(mediaId: String, timestampSeconds: Double) async -> MediaItemRecord? {
        guard let project = currentProject else { return nil }
        guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video else {
            return nil
        }
        do {
            let source = sources.first { $0.sourceId == media.sourceId }
            let frame = try await store.captureFrame(
                from: media,
                source: source,
                for: project,
                at: timestampSeconds
            )
            guard currentProject?.projectId == project.projectId else { return nil }

            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            updatedItemsById[frame.mediaId] = frame
            let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
            try store.saveInventory(updatedItems, for: project)

            var updatedCuration = curationById
            if updatedCuration[frame.mediaId] == nil {
                var curation = MediaCurationRecord(mediaId: frame.mediaId)
                curation.rejected = true
                curation.updatedAt = DateFormats.now()
                updatedCuration[frame.mediaId] = curation
                try store.saveCuration(updatedCuration, for: project)
            }

            items = updatedItems
            curationById = updatedCuration
            return frame
        } catch {
            lastError = error.localizedDescription
            return nil
        }
    }

    /// Prepares exactly one open-ended extension beside a placed clip and
    /// returns the render-plan row to review. Reopening an already-valid
    /// extension is a read-only action; a dirty Inspector range, a missing
    /// marker, a skipped marker, or legacy adjacent duplicates are repaired
    /// together as one undoable picture edit.
    @discardableResult
    func prepareShotExtension(
        shotId: String,
        afterEntryId: String,
        startSeconds: Double?,
        endSeconds: Double?
    ) -> ShotExtensionPreparation? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let sourceIndex = shot.entries.firstIndex(where: { $0.entryId == afterEntryId }),
              shot.entries[sourceIndex].isClip,
              let media = items.first(where: { $0.mediaId == shot.entries[sourceIndex].clipMediaId }) else {
            aestheticStatus = "The source footage is no longer available"
            return nil
        }

        let sourceEntry = shot.entries[sourceIndex]
        let assetDuration = max(media.durationSeconds ?? 0, 0)
        let rangedEntry = sourceEntry.settingClipRange(
            startSeconds: startSeconds,
            endSeconds: endSeconds,
            assetDurationSeconds: assetDuration
        )
        let resolvedStart = rangedEntry.clipStartSeconds ?? 0
        let resolvedEnd = rangedEntry.clipEndSeconds ?? assetDuration
        guard assetDuration <= 0 || resolvedEnd - resolvedStart >= VideoTrimRange.minimumTrimSeconds else {
            aestheticStatus = "Clip range must be at least \(String(format: "%.1f", VideoTrimRange.minimumTrimSeconds))s"
            return nil
        }

        let existingIndex = sourceIndex + 1
        let existingExtension = shot.entries.indices.contains(existingIndex)
            && shot.entries[existingIndex].isAIExtension
        var duplicateCount = 0
        if existingExtension {
            var cursor = existingIndex + 1
            while shot.entries.indices.contains(cursor), shot.entries[cursor].isAIExtension {
                duplicateCount += 1
                cursor += 1
            }
        }
        let rangeChanged = rangedEntry != sourceEntry
        let needsUnskip = existingExtension && shot.entries[existingIndex].isSkipped
        let needsMutation = rangeChanged || !existingExtension || needsUnskip || duplicateCount > 0

        if needsMutation {
            let firstMutatedIndex = rangeChanged ? sourceIndex : existingIndex
            guard frozenCutPermits(shotId: shotId, tailPredicate: { firstMutatedIndex >= $0 }) else {
                // A rendered Shot may still review the extension it already
                // owns; it simply cannot rewrite that historical structure.
                guard existingExtension, !rangeChanged else { return nil }
                return ShotExtensionPreparation(
                    shotId: shotId,
                    sourceEntryId: afterEntryId,
                    extensionEntryId: shot.entries[existingIndex].entryId,
                    segmentPlacementKey: shotPlacementSegmentKey(
                        startEntryId: afterEntryId,
                        endEntryId: shot.entries[existingIndex].entryId,
                        legacyStartId: "",
                        legacyEndId: ""
                    ),
                    pictureEdit: nil,
                    reusedExisting: true
                )
            }
        }

        let shedKeys = rangeChanged ? shotClipRangeShedKeys(entry: sourceEntry) : []
        let edit = needsMutation
            ? commitShotPictureEdit(shotId: shotId, status: nil) { current, now in
                guard current.entries.contains(where: { $0.entryId == afterEntryId }) else {
                    return nil
                }
                var updated = current
                if rangeChanged {
                    for cutId in current.cutList.segmentCuts
                        .filter({ shedKeys.contains($0.segmentKey) })
                        .map(\.id) {
                        if let next = self.shotRemovingRazorCut(
                            updated,
                            shotId: shotId,
                            cutId: cutId,
                            now: now
                        ) {
                            updated = next
                        }
                    }
                    guard let rangedIndex = updated.entries.firstIndex(where: { $0.entryId == afterEntryId }) else {
                        return nil
                    }
                    updated.entries[rangedIndex] = rangedEntry
                }

                guard let anchorIndex = updated.entries.firstIndex(where: { $0.entryId == afterEntryId }) else {
                    return nil
                }
                let extensionIndex = anchorIndex + 1
                if updated.entries.indices.contains(extensionIndex),
                   updated.entries[extensionIndex].isAIExtension {
                    updated.entries[extensionIndex].isSkipped = false
                    while updated.entries.indices.contains(extensionIndex + 1),
                          updated.entries[extensionIndex + 1].isAIExtension {
                        updated.entries.remove(at: extensionIndex + 1)
                    }
                } else {
                    updated = updated.insertingExtensionEntry(at: extensionIndex, now: now)
                }
                updated.updatedAt = now
                return updated
            }
            : nil

        guard let preparedShot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let preparedSourceIndex = preparedShot.entries.firstIndex(where: { $0.entryId == afterEntryId }),
              preparedShot.entries.indices.contains(preparedSourceIndex + 1),
              preparedShot.entries[preparedSourceIndex + 1].isAIExtension else {
            aestheticStatus = "Could not prepare the AI extension"
            return nil
        }
        let extensionEntry = preparedShot.entries[preparedSourceIndex + 1]
        aestheticStatus = existingExtension
            ? "AI extension ready for review"
            : "AI extension planned — review prompt, continuity, and cost"
        return ShotExtensionPreparation(
            shotId: shotId,
            sourceEntryId: afterEntryId,
            extensionEntryId: extensionEntry.entryId,
            segmentPlacementKey: shotPlacementSegmentKey(
                startEntryId: afterEntryId,
                endEntryId: extensionEntry.entryId,
                legacyStartId: "",
                legacyEndId: ""
            ),
            pictureEdit: edit,
            reusedExisting: existingExtension
        )
    }

    /// Inserts an AI lead-in entry at the cut's front: an end-anchored
    /// generated segment that arrives on the first material's start frame
    /// (prompt editable in the Re-render panel).
    func insertShotLeadIn(shotId: String) {
        guard let project = currentProject else { return }
        guard !isCutStructureFrozen(shotId: shotId) else { return refuseFrozenCutEdit() }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              !shot.entries.isEmpty,
              !(shot.entries.first?.isAIExtension ?? false) else {
            return
        }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.insertingExtensionEntry(at: 0, now: now)
            },
            for: project
        )
        aestheticStatus = "AI lead-in added — edit its prompt in Re-render"
    }

    /// Fulfills a planned frame IN PLACE: the planned row itself transitions
    /// queued → generating → ready/failed. Same imageId, imageIndex, label,
    /// routeKey (board slot), imageKind, characterId, areaId, sceneId — no
    /// sibling row, no ghost planned card left behind.
    func startLensHeroPlanFulfillmentRender(
        lensId: String,
        plannedImageId: String,
        request: LensNewTakeRenderRequest
    ) async -> Bool {
        await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: plannedImageId,
            blankCategory: nil,
            versionId: "",
            request: request,
            fulfillsPlannedTemplate: true
        )
    }

    private func startLensHeroTakeRender(
        lensId: String,
        templateImageId: String?,
        blankCategory: LensConceptCategory?,
        versionId: String,
        request rawRequest: LensNewTakeRenderRequest,
        fulfillsPlannedTemplate: Bool,
        // Sequential drivers (the zoom-out chain) hold isGeneratingLensHero
        // themselves across passes and park on pause between them, so the
        // single-shot gate and flag management here must stand down.
        gateOwnedByCaller: Bool = false,
        onRowCreated: ((String) -> Void)? = nil
    ) async -> Bool {
        let takeNoun = fulfillsPlannedTemplate ? "planned frame" : "new take"
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        if !gateOwnedByCaller, let reason = lensHeroTakeStartBlockReason {
            aestheticStatus = reason
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var renderRequest = rawRequest.normalized()
        guard !renderRequest.prompt.isEmpty else {
            aestheticStatus = "Prompt is required for a \(takeNoun)"
            lastError = aestheticStatus
            return false
        }
        let stack = renderRequest.stack
        if let reframe = renderRequest.reframe?.normalized(),
           !stack.supportsReframe(mode: reframe.mode) {
            aestheticStatus = "\(stack.label) does not support \(reframe.modeLabel)"
            lastError = aestheticStatus
            return false
        }
        let promptAttachments = lensPromptImageAttachments(for: renderRequest)
        if !promptAttachments.isEmpty {
            if !stack.reframeCapable {
                aestheticStatus = "\(stack.label) does not support prompt image attachments yet"
                lastError = aestheticStatus
                return false
            }
            // Belt-and-suspenders behind the Frame Creator plan (which already
            // drops over-limit references): the declared per-model slot count
            // is the law, not the provider kind.
            if stack.isFAL, let limit = stack.nativePromptImageLimit, promptAttachments.count > limit {
                aestheticStatus = limit == 1
                    ? "\(stack.label) accepts one prompt image attachment; reframe must use a composite reference for FAL."
                    : "\(stack.label) accepts \(limit) prompt image attachments — \(promptAttachments.count) were planned."
                lastError = aestheticStatus
                return false
            }
            // OpenAI executes the style image and prompt references TOGETHER
            // (combiningStyleAndPromptReferences below — style first, refs
            // after, one manifest). Other providers have one image-input set:
            // references fill it, so their style image demotes to prose.
            if renderRequest.styleMode == .attachStyleImage, stack.heroProvider != .openAI {
                renderRequest.styleMode = .describeStyleInPrompt
            }
        }
        let supportsAttachment = stack.styleImageAttachSupported
        if promptAttachments.isEmpty, renderRequest.styleMode == .attachStyleImage, !supportsAttachment {
            aestheticStatus = "\(stack.label) does not support prompt-aware style image attachments"
            lastError = aestheticStatus
            return false
        }
        for promptAttachment in promptAttachments {
            guard !promptAttachment.imagePath.isEmpty,
                  FileManager.default.fileExists(atPath: promptAttachment.imagePath) else {
                aestheticStatus = "Selected prompt image is missing on disk"
                lastError = aestheticStatus
                return false
            }
        }
        let heroImages = lens.sortedHeroImages
        let sourceImage: ProjectLensHeroImage?
        if let templateImageId {
            guard let found = heroImages.first(where: { $0.imageId == templateImageId }) else {
                aestheticStatus = "Take template not found"
                return false
            }
            sourceImage = found.normalized()
        } else {
            guard blankCategory != nil else {
                aestheticStatus = "A blank frame needs a category"
                return false
            }
            sourceImage = nil
        }
        let fulfilledPlan: ProjectLensHeroImage?
        if fulfillsPlannedTemplate {
            guard let plan = sourceImage, plan.isPlanFulfillmentCandidate else {
                aestheticStatus = "This frame has already rendered — start a variation instead"
                lastError = aestheticStatus
                return false
            }
            fulfilledPlan = plan
        } else {
            fulfilledPlan = nil
        }
        let styleCatalog = await styleBrowseCatalogForAttachmentFallback()
        let selectedStyle = renderRequest.styleOverrideSlot.flatMap {
            generatedTakeStyleSelection(
                slot: $0,
                catalog: styleCatalog,
                fallbackCatalogVersion: renderRequest.styleOverrideCatalogVersion
            )
        }
        let hasStyleReference = selectedStyle != nil || !(sourceImage?.styleAuthorities.isEmpty ?? true)
        if promptAttachments.isEmpty, renderRequest.styleMode == .attachStyleImage, !hasStyleReference {
            aestheticStatus = "No style image is available for this take"
            lastError = aestheticStatus
            return false
        }
        if !hasStyleReference {
            renderRequest.styleMode = .none
        }
        let providerStyleMode: LensRenderStyleMode = stack.isFAL && !promptAttachments.isEmpty ? .attachStyleImage : renderRequest.styleMode
        if stack.isFAL {
            let validationError = FALImageClient.validateDebugParameters(
                renderRequest.debugParametersJSON,
                stack: stack,
                styleMode: providerStyleMode
            )
            if !validationError.isEmpty {
                aestheticStatus = "FAL debug parameters are invalid"
                lastError = validationError
                return false
            }
        }
        let provider: LensHeroImageProvider = stack.heroProvider
        let now = DateFormats.now()
        let category = sourceImage.map(LensConceptCategory.category(for:)) ?? blankCategory ?? .scenery
        let newRouteKey: String
        if let fulfilledPlan {
            // In-place fulfillment keeps the planned row's board slot verbatim.
            newRouteKey = fulfilledPlan.sourceRouteKey
        } else {
            var routeKey = lensNewTakeRouteKey(
                category: category,
                lensId: lensId,
                templateImageId: templateImageId ?? "blank",
                stack: stack,
                prompt: renderRequest.prompt,
                now: now
            )
            // Every custom take lands on the media-version board it was created from:
            // derived takes (including reframes) inherit the template's version; blank
            // frames stamp the version the user was viewing.
            // An EXPLICIT board wins over the template's route: a variation
            // made while viewing board V2 of a V1-opened frame must land on
            // V2, where the operator is looking — inheriting the template's
            // board rendered it invisibly. Empty keeps the historical
            // template-route inheritance (reframes, lineage takes).
            let boardVersionId = versionId.trimmed.nilIfEmpty
                ?? sourceImage.map { ProjectLens.mediaVersionId(fromRouteKey: $0.sourceRouteKey) }
                ?? ""
            if !boardVersionId.isEmpty {
                routeKey += "@\(boardVersionId)"
            }
            newRouteKey = routeKey
        }
        let isCharacterStudy = category == .characters
        let inheritedHomeSceneImageId = sourceImage.flatMap { source in
            source.homeSceneImageId.nilIfEmpty ?? (category == .scenery ? source.imageId : "")
        } ?? ""
        let newTakeHomeSceneImageId = renderRequest.reframe == nil
            ? (sourceImage?.homeSceneImageId ?? "")
            : inheritedHomeSceneImageId
        let civitaiSeed = provider == .civitaiWan27 ? Int.random(in: 1...Int(Int32.max)) : nil
        let newImageId = fulfilledPlan?.imageId
            ?? "lens_hero_\(shortHash("\(project.projectId):\(lensId):\(newRouteKey):\(stack.id):\(now)", length: 14))"
        let usesCompositePromptImage = stack.isStability && promptAttachments.count > 1
        let providerPromptAttachments: [LensPromptImageAttachment]
        if usesCompositePromptImage {
            let compositeURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("stability_reference_\(safeIdentifier(newImageId)).jpg")
            let cells = promptAttachments.compactMap { attachment -> (image: NSImage, caption: String)? in
                guard let image = NSImage(contentsOfFile: attachment.imagePath) else { return nil }
                let caption = attachment.label.trimmed.isEmpty ? attachment.detail : attachment.label
                return (image, caption)
            }
            guard cells.count == promptAttachments.count,
                  let jpeg = RenderReferenceComposite.renderJPEG(title: "Frame references", cells: cells) else {
                aestheticStatus = "Could not compose the Stability reference input"
                lastError = aestheticStatus
                return false
            }
            do {
                try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                try jpeg.write(to: compositeURL, options: [.atomic])
            } catch {
                aestheticStatus = "Could not save the Stability reference input"
                lastError = error.localizedDescription
                return false
            }
            let sourceLines = promptAttachments.enumerated().map { index, attachment in
                let label = attachment.label.trimmed.isEmpty ? "Reference \(index + 1)" : attachment.label
                let detail = attachment.detail.trimmed
                return detail.isEmpty ? "\(index + 1). \(label)" : "\(index + 1). \(label) — \(detail)"
            }
            providerPromptAttachments = [
                LensPromptImageAttachment(
                    attachmentId: "stability_composite_\(newImageId)",
                    source: .moodboardImage,
                    sourceId: "stability_composite_\(newImageId)",
                    label: "Labeled composite · \(promptAttachments.count) references",
                    detail: "COMPOSITE REFERENCE INPUT. Read each labeled cell as a separate source; render one continuous final frame, not a collage.\n" + sourceLines.joined(separator: "\n"),
                    imagePath: compositeURL.path
                ).normalized()
            ]
        } else {
            providerPromptAttachments = promptAttachments
        }
        let nonStyleDependencies = sourceImage?.sourceDependencies.filter { $0.normalized().role != "style_source" } ?? []
        let styleAuthorities: [LensStyleAuthoritySnapshot]
        let sourceAestheticIds: [String]
        let sourceRecipeVersion: String?
        let renderLens: ProjectLens
        if renderRequest.styleMode == .none {
            styleAuthorities = []
            sourceAestheticIds = []
            sourceRecipeVersion = sourceImage?.sourceRecipeVersion
            renderLens = lens
        } else if let selectedStyle {
            styleAuthorities = [selectedStyle.authority]
            sourceAestheticIds = [selectedStyle.authority.referenceId].filter { !$0.isEmpty }
            sourceRecipeVersion = selectedStyle.catalogVersion.trimmed.nilIfEmpty ?? sourceImage?.sourceRecipeVersion
            renderLens = lensApplyingStyleSlotOverride(lens, slot: selectedStyle.slot, catalogVersion: selectedStyle.catalogVersion)
        } else if let sourceImage {
            styleAuthorities = sourceImage.styleAuthorities
            sourceAestheticIds = sourceImage.sourceAestheticIds
            sourceRecipeVersion = sourceImage.sourceRecipeVersion
            renderLens = lensApplyingTakeStyleOverride(lens, image: sourceImage)
        } else {
            // Unreachable: a blank take with no style override was already forced to
            // .none by the hasStyleReference check above.
            styleAuthorities = []
            sourceAestheticIds = []
            sourceRecipeVersion = nil
            renderLens = lens
        }
        var dependencies: [LensRenderSourceDependency]
        if renderRequest.styleMode == .none {
            dependencies = nonStyleDependencies
        } else if selectedStyle == nil {
            dependencies = sourceImage?.sourceDependencies ?? []
        } else {
            dependencies = nonStyleDependencies + generatedTakeStyleSourceDependencies(
                styleAuthorities: styleAuthorities,
                sourceReferenceIds: styleAuthorities.map(\.sourceReferenceId)
            )
        }
        for promptAttachment in promptAttachments {
            dependencies.append(lensPromptImageDependency(promptAttachment))
        }
        if renderRequest.reframe != nil, let sourceImage {
            dependencies.append(LensRenderSourceDependency(
                dependencyId: "",
                kind: LensPromptImageAttachmentSource.lensRenderVersion.rawValue,
                sourceId: sourceImage.imageId,
                required: true,
                role: "reframe_parent",
                label: sourceImage.label,
                imagePathOrUrl: sourceImage.imagePath
            ).normalized(order: dependencies.count))
            if let focusCropPath = renderRequest.reframeFocusCropPath?.trimmed.nilIfEmpty {
                dependencies.append(LensRenderSourceDependency(
                    dependencyId: "",
                    kind: LensPromptImageAttachmentSource.lensRenderVersion.rawValue,
                    sourceId: "\(sourceImage.imageId):focus_crop",
                    required: true,
                    role: "reframe_focus_crop",
                    label: "Focus crop",
                    imagePathOrUrl: focusCropPath
                ).normalized(order: dependencies.count))
            }
            if let cameraMapPath = renderRequest.reframeCameraMapPath?.trimmed.nilIfEmpty {
                dependencies.append(LensRenderSourceDependency(
                    dependencyId: "",
                    kind: LensPromptImageAttachmentSource.lensRenderVersion.rawValue,
                    sourceId: "\(sourceImage.imageId):camera_map",
                    required: false,
                    role: "reframe_camera_map",
                    label: "Camera map",
                    imagePathOrUrl: cameraMapPath
                ).normalized(order: dependencies.count))
            }
        }
        let renderRecipe: LensRenderRecipeSnapshot
        if stack.isFAL {
            renderRecipe = stack.renderRecipeSnapshot(
                mediaPlan: lens.body.resolvedMediaPlan,
                styleMode: providerStyleMode,
                debugParametersJSON: renderRequest.debugParametersJSON
            )
        } else {
            renderRecipe = provider.renderRecipeSnapshot(
                mediaPlan: lens.body.resolvedMediaPlan,
                isCharacterStudy: isCharacterStudy,
                hasStyleReferences: (renderRequest.styleMode == .attachStyleImage && !styleAuthorities.isEmpty) || !promptAttachments.isEmpty,
                seed: civitaiSeed,
                stack: stack,
                sourceImageCount: promptAttachments.isEmpty && renderRequest.styleMode == .attachStyleImage ? 1 : promptAttachments.count,
                usesCompositeImage: usesCompositePromptImage
            )
        }
        let label = lensNewTakeLabel(
            category: category,
            sourceImage: sourceImage,
            explicitLabel: renderRequest.label,
            stack: stack
        )
        // Stamp the RESOLVED character id (not just the template's raw stamp) so
        // implicit casting and grouping can attribute this take even when the template
        // predates characterId stamping and resolves by label.
        let newTakeCharacterId = isCharacterStudy
            ? (sourceImage.map { lensResolvedTakeCharacterId(for: $0, lens: lens, cast: lensCompositeCast(for: lens)) } ?? "")
            : (sourceImage?.characterId ?? "")
        var newTake = ProjectLensHeroImage(
            imageId: newImageId,
            imageIndex: (heroImages.map(\.imageIndex).max() ?? sourceImage?.imageIndex ?? -1) + 1,
            label: label,
            provider: provider.rawValue,
            model: renderRecipe.model,
            imagePath: "",
            prompt: renderRequest.prompt,
            sourcePrompt: renderRequest.authoredPrompt ?? renderRequest.prompt,
            negativePrompt: "",
            status: "generating",
            sourceRouteKey: newRouteKey,
            sourceRecipeId: sourceImage?.sourceRecipeId,
            sourceRecipeVersion: sourceRecipeVersion,
            sourceAestheticIds: sourceAestheticIds,
            subject: generatedTakeSubject(routeKey: newRouteKey, prompt: renderRequest.prompt),
            styleAuthorities: styleAuthorities,
            renderRecipe: renderRecipe,
            sourceDependencies: dependencies,
            reframe: renderRequest.reframe,
            imageKind: sourceImage?.imageKind ?? category.taxonomyImageKind,
            characterId: newTakeCharacterId,
            areaId: sourceImage?.areaId ?? "",
            sceneId: sourceImage?.sceneId ?? "",
            areaImageId: sourceImage?.areaImageId ?? "",
            homeSceneImageId: newTakeHomeSceneImageId,
            taxonomyEnabled: sourceImage?.taxonomyEnabled ?? true,
            kept: nil,
            generatedAt: "",
            updatedAt: now
        ).normalized()
        // The per-frame verbatim choice persists on the row so retries and
        // siblings stay verbatim.
        newTake.promptEnrichmentDisabled = renderRequest.promptEnrichmentDisabled == true
        newTake.stabilityStrength = renderRequest.stabilityStrength
        if !gateOwnedByCaller {
            // The authoritative lane claim. The top-of-function check was a
            // cheap early refusal; awaits ran since (style catalog), so claim
            // here — synchronously with the live re-read and row save below.
            guard registerLensHeroTakeOperation(imageId: newImageId, lensId: lensId) else {
                return false
            }
        }
        defer {
            if !gateOwnedByCaller {
                unregisterLensHeroTakeOperation(imageId: newImageId)
            }
        }

        let statusPrefix = "Starting \(stack.label) Scene \(takeNoun)"
        aestheticStatus = statusPrefix
        guard let liveLens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var liveHeroImages = liveLens.sortedHeroImages
        if let sourceImage,
           !liveHeroImages.contains(where: { $0.imageId == sourceImage.imageId }) {
            aestheticStatus = "Take template not found"
            lastError = aestheticStatus
            return false
        }
        if let fulfilledPlan {
            guard let planIndex = liveHeroImages.firstIndex(where: { $0.imageId == fulfilledPlan.imageId }),
                  liveHeroImages[planIndex].isPlanFulfillmentCandidate else {
                aestheticStatus = "This frame has already rendered — start a variation instead"
                lastError = aestheticStatus
                return false
            }
            newTake = lensPlanFulfilledTake(planned: liveHeroImages[planIndex], rendered: newTake)
            liveHeroImages[planIndex] = newTake
        } else {
            guard !liveHeroImages.contains(where: { $0.imageId == newTake.imageId }) else {
                aestheticStatus = "Could not create a unique Frame render"
                lastError = aestheticStatus
                return false
            }
            newTake.imageIndex = (liveHeroImages.map(\.imageIndex).max() ?? -1) + 1
            newTake = newTake.normalized()
            liveHeroImages.append(newTake)
        }
        guard saveLensHeroImages(
            liveHeroImages,
            lensId: lensId,
            project: project,
            status: statusPrefix,
            changeSummary: "Started \(stack.label) \(takeNoun) render."
        ) else {
            return false
        }
        // The generating row now exists — callers that place it somewhere
        // (e.g. a planned cell beside a clip) can act before the render lands.
        onRowCreated?(newImageId)
        if let sourceImage {
            // Variations, group takes, reframes, and zoom-out passes inherit
            // their source's stage membership (newTake.imageId survives plan
            // fulfillment; newImageId would not).
            inheritStageMembership(fromImageId: sourceImage.imageId, toImageId: newTake.imageId)
        }

        let runId = "lens_new_take_\(shortHash("\(project.projectId):\(lensId):\(newImageId):\(now)", length: 14))"
        let outputExtension = renderRequest.reframe?.normalized().isZoomOut == true
            || (provider == .openAI && isCharacterStudy)
            || stack.usesPNGOutput
            ? "png"
            : "jpg"
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(runId)_\(safeIdentifier(lensId))_\(safeIdentifier(newImageId)).\(outputExtension)")
        let promptAttachmentPlan = providerPromptAttachments.isEmpty
            ? nil
            : lensPromptImageAttachmentPlan(
                providerPromptAttachments,
                descriptorOverrides: renderRequest.reframe.map { reframeAttachmentDescriptors(for: $0, attachmentCount: providerPromptAttachments.count) } ?? []
            )
        let usesStyleAttachmentPlan = renderRequest.styleMode == .attachStyleImage && (provider == .openAI || provider == .fal || provider == .stability)
        let stylePlan = usesStyleAttachmentPlan
            ? lensBlendAttachmentPlan(
                lens: renderLens,
                catalog: styleCatalog,
                assignedStyleId: sourceAestheticIds.first,
                // Explicit prompt attachments already carry their referenced subjects;
                // avoid re-attaching the study's implicit character references.
                characterScopeId: promptAttachments.isEmpty ? newTake.characterId : nil,
                continuityURLs: []
            )
            : LensBlendAttachmentPlan()
        let openAIPlan: LensBlendAttachmentPlan
        if provider == .openAI, let promptAttachmentPlan {
            openAIPlan = LensBlendAttachmentPlan.combiningStyleAndPromptReferences(
                stylePlan: stylePlan,
                promptPlan: promptAttachmentPlan
            )
        } else if provider == .openAI {
            openAIPlan = stylePlan
        } else {
            openAIPlan = LensBlendAttachmentPlan()
        }
        let attachmentEntries: [LensBlendAttachmentEntry]
        if provider == .openAI {
            attachmentEntries = openAIPlan.entries
        } else if let promptAttachmentPlan {
            attachmentEntries = promptAttachmentPlan.entries
        } else if provider == .fal || provider == .stability {
            attachmentEntries = stylePlan.styleEntries
        } else {
            attachmentEntries = stylePlan.entries
        }
        let attachmentManifest: String
        let attachmentManifestEntries: String
        let attachmentStylePolicy: String
        if provider == .openAI {
            attachmentManifest = openAIPlan.manifestText
            attachmentManifestEntries = openAIPlan.manifestEntryLinesText
            attachmentStylePolicy = openAIPlan.manifestPolicyText
        } else if let promptAttachmentPlan {
            attachmentManifest = promptAttachmentPlan.manifestText
            attachmentManifestEntries = promptAttachmentPlan.manifestEntryLinesText
            attachmentStylePolicy = ""
        } else if provider == .fal || provider == .stability {
            attachmentManifest = ""
            attachmentManifestEntries = ""
            attachmentStylePolicy = ""
        } else {
            attachmentManifest = stylePlan.manifestText
            attachmentManifestEntries = stylePlan.manifestEntryLinesText
            attachmentStylePolicy = stylePlan.manifestPolicyText
        }
        let styleSummary: String
        if renderRequest.styleMode == .describeStyleInPrompt {
            styleSummary = takeStyleSummary(styleAuthorities: styleAuthorities, preferredStyleId: sourceAestheticIds.first)
        } else if renderRequest.styleMode == .attachStyleImage, provider == .openAI || provider == .stability {
            styleSummary = stylePlan.styleSummaryText
        } else {
            styleSummary = ""
        }
        // Mood influences ride in the job only: the persisted take prompt/sourcePrompt
        // stay the user's text so future takes seeded from this one never inherit them.
        let moodLines = (renderRequest.moodInfluences ?? []).map(\.line).filter { !$0.isEmpty }
        let moodInfluenceBlock = moodLines.isEmpty
            ? ""
            : "Mood influences (from the project moodboard):\n" + moodLines.map { "- \($0)" }.joined(separator: "\n")
        let mediumBlock = renderRequest.mediumPreset?.promptBlock ?? ""
        let job = LensHeroGenerationJob(
            lensId: lensId,
            imageId: newImageId,
            provider: provider,
            stack: stack,
            styleMode: providerStyleMode,
            debugParametersJSON: renderRequest.debugParametersJSON,
            promptImageReferenceMode: !promptAttachments.isEmpty,
            sourceImageCount: provider == .openAI
                ? attachmentEntries.count
                : (promptAttachments.isEmpty && renderRequest.styleMode == .attachStyleImage ? attachmentEntries.count : promptAttachments.count),
            usesCompositeImage: usesCompositePromptImage,
            // Verbatim mode: the operator's per-frame choice OR a reframe
            // (which never enriches, by design) — same skip branch.
            skipPromptEnrichment: renderRequest.reframe != nil || renderRequest.promptEnrichmentDisabled == true,
            prompt: newTake.prompt,
            sourcePrompt: newTake.sourcePrompt,
            negativePrompt: newTake.negativePrompt,
            attachments: attachmentEntries,
            promptPreamble: provider == .openAI ? openAIPlan.promptPreamble : (promptAttachments.isEmpty && renderRequest.styleMode == .attachStyleImage ? stylePlan.promptPreamble : ""),
            attachmentManifest: attachmentManifest,
            styleSummary: styleSummary,
            moodInfluenceBlock: moodInfluenceBlock,
            mediumBlock: mediumBlock,
            attachmentManifestEntries: attachmentManifestEntries,
            attachmentStylePolicy: attachmentStylePolicy,
            imageSize: stack.imageSize ?? lens.body.resolvedMediaPlan.imageSize,
            stabilityAspectRatio: stack.isStability ? stack.stabilityAspectRatio : lens.body.resolvedMediaPlan.stabilityAspectRatio,
            stabilityStrength: renderRequest.stabilityStrength,
            mediaPlan: lens.body.resolvedMediaPlan,
            transparentBackground: isCharacterStudy,
            civitaiSeed: civitaiSeed,
            reframe: renderRequest.reframe,
            reframeSourcePath: renderRequest.reframe == nil ? "" : (sourceImage?.imagePath ?? ""),
            outputURL: outputURL,
            projectId: project.projectId,
            runId: newImageId,
            workflowName: renderRequest.reframe == nil ? "lenses" : "reframe"
        )

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let needsOpenAIClient = provider == .openAI
                || ((provider == .fal || provider == .stability) && !job.skipPromptEnrichment)
            let client = needsOpenAIClient ? try OpenAIClient.fromEnvironment() : nil
            let stabilityClient = provider == .stability
                ? try StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
                : try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let civitaiImageProvider = provider == .civitaiWan27
                ? CivitAIWANImageProvider(credentialStore: videoCredentialStore)
                : nil
            let falImageClient = provider == .fal
                ? FALImageClient(credentialStore: videoCredentialStore)
                : nil
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider,
                falImageClient: falImageClient
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let status = outcome.status == "ready"
                ? "\(stack.label) Scene \(takeNoun) ready"
                : "\(stack.label) Scene \(takeNoun) \(outcome.status)"
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: status,
                changeSummary: "\(stack.label) \(takeNoun) render \(outcome.status).",
                appendVersion: false
            )
            aestheticStatus = status
            if outcome.status == "failed" {
                lastError = outcome.errorMessage
            }
            return outcome.status == "ready"
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let failedAt = DateFormats.now()
            let status = (Task.isCancelled || isCancellationLikeError(error)) ? "cancelled" : "failed"
            let outcome = LensHeroGenerationOutcome(
                lensId: lensId,
                imageId: newImageId,
                provider: provider,
                status: status,
                imagePath: "",
                prompt: newTake.prompt,
                sourcePrompt: newTake.sourcePrompt,
                negativePrompt: newTake.negativePrompt,
                promptEnrichmentModel: "",
                promptEnrichmentResponseId: "",
                promptEnrichmentTraceId: "",
                promptEnrichmentSummary: "",
                requestId: "",
                traceId: "",
                errorMessage: error.localizedDescription,
                generatedAt: "",
                updatedAt: failedAt,
                renderRecipe: nil
            )
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: "\(stack.label) Scene \(takeNoun) \(status)",
                changeSummary: "\(stack.label) \(takeNoun) render \(status).",
                appendVersion: false
            )
            lastError = error.localizedDescription
            aestheticStatus = "\(stack.label) Scene \(takeNoun) \(status)"
            return false
        }
    }

    /// Starts a reframe render - a Zoom or Viewpoint child take derived
    /// from an existing ready render — by wrapping the standard new-take path with the
    /// reframe prompt, the mode-specific source attachment, and lineage metadata.
    @discardableResult
    func startLensHeroReframeRender(
        lensId: String,
        parentImageId: String,
        spec rawSpec: LensReframeSpec,
        stack: RenderStack,
        promptBody: String = "",
        onRowCreated: ((String) -> Void)? = nil
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard lensHeroReframeBlockReason.isEmpty else {
            aestheticStatus = lensHeroReframeBlockReason
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        guard let parent = lens.sortedHeroImages.first(where: { $0.imageId == parentImageId })?.normalized() else {
            aestheticStatus = "Reframe source render not found"
            return false
        }
        guard parent.status == "ready", !parent.imagePath.isEmpty,
              FileManager.default.fileExists(atPath: parent.imagePath) else {
            aestheticStatus = "Reframe needs a ready source render on disk"
            lastError = aestheticStatus
            return false
        }
        var spec = rawSpec.normalized()
        spec.parentImageId = parent.imageId
        spec.parentRenderVersionId = parent.renderVersion?.renderVersionId ?? ""
        guard stack.supportsReframe(mode: spec.mode) else {
            aestheticStatus = "\(stack.label) does not support \(spec.modeLabel)"
            lastError = aestheticStatus
            return false
        }
        let operationId = "lens_reframe_\(UUID().uuidString.lowercased())"
        activeLensHeroReframeOperationIds.insert(operationId)
        refreshLensHeroBusyState()
        defer {
            activeLensHeroReframeOperationIds.remove(operationId)
            refreshLensHeroBusyState()
        }
        if spec.isZoomOut,
           LensZoomOutGeometry.zoomOutPassCount(totalScale: spec.zoomOutSourceScale) > 1 {
            // The chain deliberately does NOT receive `onRowCreated` — it
            // mints one frame per pass with its own internal row capture, and
            // the only placement caller (punch-in) refuses zoom-out specs.
            return await startLensHeroZoomOutChainRender(
                lensId: lensId,
                parent: parent,
                spec: spec,
                stack: stack,
                promptBody: promptBody
            )
        }
        let now = DateFormats.now()
        let cropURL: URL?
        if spec.isZoomOut {
            cropURL = nil
        } else {
            let url = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("lens_reframe_\(shortHash("\(lensId):\(parent.imageId):\(spec.centerX):\(spec.centerY):\(now)", length: 14))_focus_crop.png")
            do {
                try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                try writeLensReframeCrop(sourcePath: parent.imagePath, spec: spec, to: url)
                cropURL = url
            } catch {
                aestheticStatus = "Could not crop the reframe focus region"
                lastError = error.localizedDescription
                return false
            }
        }
        // THE CONVENTION LAW: viewpoint rides a drawn top-down camera map.
        // The map is an aid, never a blocker — on any failure the render
        // proceeds without it, and the spec flips `includeCameraMap` false
        // so every descriptor downstream stays truthful.
        var cameraMapURL: URL?
        if spec.isViewpoint, spec.includeCameraMap {
            let url = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("lens_reframe_\(shortHash("\(lensId):\(parent.imageId):\(spec.centerX):\(spec.centerY):\(now):camera_map", length: 14))_camera_map.png")
            if let data = renderLensViewpointSchematicPNG(plan: lensViewpointSchematicPlan(spec: spec)) {
                do {
                    try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                    try data.write(to: url)
                    cameraMapURL = url
                } catch {
                    cameraMapURL = nil
                }
            }
            if cameraMapURL == nil {
                spec.includeCameraMap = false
            }
        }
        let attachments: [LensPromptImageAttachment]
        if spec.isZoomOut {
            attachments = []
        } else if stack.isFAL, let cropURL {
            let compositeURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("lens_reframe_\(shortHash("\(lensId):\(parent.imageId):\(spec.centerX):\(spec.centerY):\(now):composite", length: 14))_composite.png")
            do {
                try writeLensReframeComposite(
                    parentPath: parent.imagePath,
                    cropPath: cropURL.path,
                    cameraMapPath: cameraMapURL?.path,
                    to: compositeURL
                )
            } catch {
                aestheticStatus = "Could not compose the reframe reference image"
                lastError = error.localizedDescription
                return false
            }
            attachments = [
                LensPromptImageAttachment(
                    attachmentId: "reframe_composite_\(parent.imageId)",
                    source: .lensRenderVersion,
                    sourceId: parent.imageId,
                    label: "\(spec.modeLabel) composite source",
                    detail: "Full source frame and focus crop composite",
                    imagePath: compositeURL.path
                ).normalized()
            ]
        } else if let cropURL {
            var built = [
                LensPromptImageAttachment(
                    attachmentId: "reframe_parent_\(parent.imageId)",
                    source: .lensRenderVersion,
                    sourceId: parent.imageId,
                    label: "\(spec.modeLabel) full source",
                    detail: "Full source frame",
                    imagePath: parent.imagePath
                ).normalized(),
                LensPromptImageAttachment(
                    attachmentId: "reframe_focus_crop_\(parent.imageId)",
                    source: .lensRenderVersion,
                    sourceId: "\(parent.imageId):focus_crop",
                    label: "\(spec.modeLabel) focus crop",
                    detail: "Focus region crop",
                    imagePath: cropURL.path
                ).normalized()
            ]
            if let cameraMapURL {
                built.append(LensPromptImageAttachment(
                    attachmentId: "reframe_camera_map_\(parent.imageId)",
                    source: .lensRenderVersion,
                    sourceId: "\(parent.imageId):camera_map",
                    label: "\(spec.modeLabel) camera map",
                    detail: LensReframeComposer.cameraMapAttachmentDescriptor(spec: spec),
                    imagePath: cameraMapURL.path
                ).normalized())
            }
            attachments = built
        } else {
            attachments = []
        }
        let request = LensNewTakeRenderRequest(
            stack: stack,
            styleMode: .describeStyleInPrompt,
            prompt: LensReframeComposer.prompt(
                spec: spec,
                parent: parent,
                model: stack.reframePromptModel,
                promptSettings: projectPromptSettings,
                promptBody: promptBody
            ),
            label: "Reframe · \(spec.modeLabel)",
            debugParametersJSON: "",
            promptImageAttachments: attachments,
            reframe: spec,
            reframeFocusCropPath: cropURL?.path,
            reframeCameraMapPath: cameraMapURL?.path
        )
        return await startLensHeroTakeRender(
            lensId: lensId,
            templateImageId: parent.imageId,
            blankCategory: nil,
            versionId: "",
            request: request,
            fulfillsPlannedTemplate: false,
            gateOwnedByCaller: true,
            onRowCreated: onRowCreated
        )
    }

    /// THE PUNCH-IN EXCURSION: one gesture from a frame at a known cut
    /// placement starts a reframe child render AND — the moment the
    /// generating row exists — inserts the there-and-back pair
    /// [child, source-again] immediately after the anchor entry, in one
    /// picture transaction. The two new adjacent pairs then earn the
    /// lineage-derived push-in/pull-out prompt defaults with no override
    /// rows written. Undo (registered by the caller from `onPlaced`) removes
    /// the two entries only; the child render keeps running and lands on the
    /// lens board like any reframe — harmless and re-insertable.
    @discardableResult
    func startPunchInExcursion(
        cutId: String,
        afterEntryId: String,
        lensId: String,
        parentImageId: String,
        spec: LensReframeSpec,
        stack: RenderStack,
        promptBody: String = "",
        onPlaced: ((ShotPunchInPlacement) -> Void)? = nil
    ) async -> Bool {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == cutId }),
              let anchorIndex = shot.entries.firstIndex(where: { $0.entryId == afterEntryId }) else {
            aestheticStatus = "Punch-in needs its cut placement — the frame moved out of the cut"
            return false
        }
        guard shot.entries[anchorIndex].frameImageId == parentImageId else {
            aestheticStatus = "Punch-in needs the frame it was aimed at — the cut entry changed"
            return false
        }
        guard !spec.normalized().isZoomOut else {
            aestheticStatus = "Punch-in dives INTO the frame — zoom out from the frame detail instead"
            return false
        }
        // Courtesy refusal BEFORE money is spent; re-checked at placement
        // time against the render-mid-flight race.
        guard frozenCutPermits(shotId: cutId, tailPredicate: { anchorIndex + 1 >= $0 }) else {
            return false
        }
        return await startLensHeroReframeRender(
            lensId: lensId,
            parentImageId: parentImageId,
            spec: spec,
            stack: stack,
            promptBody: promptBody,
            onRowCreated: { [weak self] childImageId in
                self?.placePunchInExcursion(
                    cutId: cutId,
                    afterEntryId: afterEntryId,
                    childImageId: childImageId,
                    onPlaced: onPlaced
                )
            }
        )
    }

    /// Lands the punch-in pair beside its anchor the moment the generating
    /// child row exists (the `placeSpawnedFrame` timing). A vanished cut or
    /// anchor, or a cut that rendered mid-flight, is tolerated — the child
    /// still lives on the lens board.
    private func placePunchInExcursion(
        cutId: String,
        afterEntryId: String,
        childImageId: String,
        onPlaced: ((ShotPunchInPlacement) -> Void)?
    ) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == cutId }),
              let anchorIndex = shot.entries.firstIndex(where: { $0.entryId == afterEntryId }) else {
            return
        }
        guard frozenCutPermits(shotId: cutId, tailPredicate: { anchorIndex + 1 >= $0 }) else {
            aestheticStatus = "The cut rendered while the punch-in started — the reframe joined the Scene Plan instead"
            return
        }
        var minted: (child: String, ret: String)?
        let edit = commitShotPictureEdit(
            shotId: cutId,
            status: "Punch-in placed — the reframe renders in place"
        ) { current, now in
            guard let result = current.insertingPunchInExcursion(
                afterEntryId: afterEntryId,
                childImageId: childImageId,
                now: now
            ) else { return nil }
            minted = (result.childEntryId, result.returnEntryId)
            return result.shot
        }
        if let edit, let minted {
            onPlaced?(ShotPunchInPlacement(
                childImageId: childImageId,
                childEntryId: minted.child,
                returnEntryId: minted.ret,
                edit: edit
            ))
        }
    }

    /// Runs a deep Zoom Out as a chain of standard single-pass Zoom Out takes,
    /// each persisted as its own frame whose parent is the previous pass. A
    /// per-pass source scale ≥ 0.60 keeps every pass inside the provider
    /// expansion caps at full resolution and bounds per-pass invention, which
    /// is what stops motif duplication and hallucinated scenes at deep
    /// pullbacks. Mirrors the sequential-chain conventions of
    /// `regenerateLensMedia`: one reframe-lane hold, pause parking between
    /// passes, and per-pass outcome reconciliation (a mid-chain failure keeps
    /// the completed frames). Other explicit reframes may run beside it.
    private func startLensHeroZoomOutChainRender(
        lensId: String,
        parent initialParent: ProjectLensHeroImage,
        spec: LensReframeSpec,
        stack: RenderStack,
        promptBody: String
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        let passRects = LensZoomOutGeometry.zoomOutPassRects(spec: spec)
        guard passRects.count > 1 else { return false }

        var currentParent = initialParent
        for (index, passRect) in passRects.enumerated() {
            do {
                try Task.checkCancellation()
                try await waitWhileGenerationPaused()
            } catch {
                aestheticStatus = "Zoom Out chain cancelled after \(index) of \(passRects.count) frames"
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            var passSpec = LensReframeSpec(
                mode: LensReframeSpec.zoomOutMode,
                centerX: Double(passRect.midX),
                centerY: Double(passRect.midY),
                normalizedWidth: Double(passRect.width),
                normalizedHeight: Double(passRect.height),
                fidelity: spec.fidelity
            ).normalized()
            passSpec.parentImageId = currentParent.imageId
            passSpec.parentRenderVersionId = currentParent.renderVersion?.renderVersionId ?? ""
            let request = LensNewTakeRenderRequest(
                stack: stack,
                styleMode: .describeStyleInPrompt,
                prompt: LensReframeComposer.prompt(
                    spec: passSpec,
                    parent: currentParent,
                    model: stack.reframePromptModel,
                    promptSettings: projectPromptSettings,
                    promptBody: promptBody
                ),
                label: "Reframe · Zoom Out · \(index + 1)/\(passRects.count)",
                debugParametersJSON: "",
                promptImageAttachments: [],
                reframe: passSpec,
                reframeFocusCropPath: nil
            )
            var childImageId = ""
            let passReady = await startLensHeroTakeRender(
                lensId: lensId,
                templateImageId: currentParent.imageId,
                blankCategory: nil,
                versionId: "",
                request: request,
                fulfillsPlannedTemplate: false,
                gateOwnedByCaller: true,
                onRowCreated: { childImageId = $0 }
            )
            guard passReady,
                  let child = projectLenses.lenses
                      .first(where: { $0.lensId == lensId })?
                      .heroImages.first(where: { $0.imageId == childImageId })?
                      .normalized(),
                  child.status == "ready", !child.imagePath.isEmpty else {
                aestheticStatus = "Zoom Out chain stopped at frame \(index + 1) of \(passRects.count) — completed frames are kept"
                return false
            }
            currentParent = child
        }
        aestheticStatus = "Zoom Out chain complete — \(passRects.count) frames"
        return true
    }

    /// The optional character candidates a Viewpoint reframe can use for camera
    /// embodiment, with stable ids preserved so the chosen context is recorded in the reframe spec. Precedence mirrors
    /// lensCompositeCast: roster characters, then lens cast members, then legacy prompts.
    func lensReframeCastCandidates(for lens: ProjectLens) -> [LensReframeCastCandidate] {
        let plan = lens.body.resolvedMediaPlan
        let rosterCast = plan.selectedCharacterIds.compactMap { characterId -> LensReframeCastCandidate? in
            guard let character = projectCharacters.character(withId: characterId) else { return nil }
            return LensReframeCastCandidate(
                id: characterId,
                name: character.name,
                prompt: character.descriptionPrompt.isEmpty ? character.name : character.descriptionPrompt,
                signatureProps: character.signatureProps,
                environmentAffinity: character.environmentAffinity
            )
        }
        if !rosterCast.isEmpty {
            return rosterCast
        }
        if let members = lens.body.castMembers, !members.isEmpty {
            return members.prefix(plan.characterCount).map { member in
                LensReframeCastCandidate(
                    id: member.characterId ?? member.castId,
                    name: member.name,
                    prompt: member.descriptionPrompt.isEmpty ? member.name : member.descriptionPrompt,
                    signatureProps: member.signatureProps,
                    environmentAffinity: member.environmentAffinity
                )
            }
        }
        return (lens.body.characterImagePrompts ?? []).prefix(plan.characterCount).enumerated().map { index, prompt in
            LensReframeCastCandidate(
                id: "character_prompt_\(index)",
                name: "Character \(index + 1)",
                prompt: prompt,
                signatureProps: [],
                environmentAffinity: ""
            )
        }
    }

    /// Writes the reframe context crop, reading pixel dimensions from image
    /// metadata (never NSImage points) so retina scale can't skew the region.
    private func writeLensReframeCrop(sourcePath: String, spec: LensReframeSpec, to url: URL) throws {
        let sourceURL = URL(fileURLWithPath: sourcePath)
        guard let imageSource = CGImageSourceCreateWithURL(sourceURL as CFURL, nil),
              let properties = CGImageSourceCopyPropertiesAtIndex(imageSource, 0, nil) as? [CFString: Any],
              let pixelWidth = (properties[kCGImagePropertyPixelWidth] as? NSNumber)?.doubleValue,
              let pixelHeight = (properties[kCGImagePropertyPixelHeight] as? NSNumber)?.doubleValue,
              let image = CGImageSourceCreateImageAtIndex(imageSource, 0, nil) else {
            throw ScreenGraphError.capture("Could not read the reframe source image at \(sourcePath)")
        }
        let cropRect = lensReframeCropRect(
            imagePixelSize: CGSize(width: pixelWidth, height: pixelHeight),
            spec: spec
        )
        // Tilted selections are extracted straightened, so every provider
        // receives the crop already "right side up".
        guard !cropRect.isEmpty,
              let cropped = lensReframeExtractCrop(
                  from: image,
                  cropRect: cropRect,
                  rotationDegrees: spec.rotationDegrees
              ) else {
            throw ScreenGraphError.capture("Could not crop the reframe focus region")
        }
        guard let destination = CGImageDestinationCreateWithURL(url as CFURL, UTType.png.identifier as CFString, 1, nil) else {
            throw ScreenGraphError.invalidImageDestination
        }
        CGImageDestinationAddImage(destination, cropped, nil)
        guard CGImageDestinationFinalize(destination) else {
            throw ScreenGraphError.capture("Could not write the reframe crop to \(url.path)")
        }
    }

    /// Two panels (parent | crop), or three when a viewpoint camera map
    /// rides along: the right column splits into crop (upper) and map
    /// (lower), keeping the parent panel at full height — the composite
    /// descriptor's panel language mirrors this layout exactly.
    private func writeLensReframeComposite(
        parentPath: String,
        cropPath: String,
        cameraMapPath: String? = nil,
        to url: URL
    ) throws {
        let parent = try loadReframeCompositeImage(path: parentPath, label: "parent")
        let crop = try loadReframeCompositeImage(path: cropPath, label: "crop")
        let cameraMap = try cameraMapPath.map { try loadReframeCompositeImage(path: $0, label: "camera map") }
        let canvasWidth = 1536
        let canvasHeight = 1024
        let canvasSize = CGSize(width: canvasWidth, height: canvasHeight)
        let gutter: CGFloat = 20
        let margin: CGFloat = 28
        let parentPanel = CGRect(x: margin, y: margin, width: 1000 - margin * 2, height: canvasSize.height - margin * 2)
        let rightColumn = CGRect(x: 1000 + gutter, y: margin, width: canvasSize.width - 1000 - gutter - margin, height: canvasSize.height - margin * 2)
        let cropPanel: CGRect
        let mapPanel: CGRect?
        if cameraMap != nil {
            let halfHeight = (rightColumn.height - gutter) / 2
            cropPanel = CGRect(x: rightColumn.minX, y: rightColumn.minY, width: rightColumn.width, height: halfHeight)
            mapPanel = CGRect(x: rightColumn.minX, y: rightColumn.minY + halfHeight + gutter, width: rightColumn.width, height: halfHeight)
        } else {
            cropPanel = rightColumn
            mapPanel = nil
        }
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        guard let context = CGContext(
            data: nil,
            width: canvasWidth,
            height: canvasHeight,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create the reframe composite canvas.")
        }
        context.setFillColor(CGColor(red: 0.055, green: 0.055, blue: 0.055, alpha: 1))
        context.fill(CGRect(origin: .zero, size: canvasSize))
        context.setFillColor(CGColor(red: 0.12, green: 0.12, blue: 0.12, alpha: 1))
        context.fill(parentPanel)
        context.fill(cropPanel)
        if let mapPanel { context.fill(mapPanel) }
        context.interpolationQuality = .high
        drawAspectFit(parent, in: parentPanel.insetBy(dx: 10, dy: 10), context: context)
        drawAspectFit(crop, in: cropPanel.insetBy(dx: 10, dy: 10), context: context)
        if let cameraMap, let mapPanel {
            drawAspectFit(cameraMap, in: mapPanel.insetBy(dx: 10, dy: 10), context: context)
        }

        guard let composite = context.makeImage() else {
            throw ScreenGraphError.capture("Could not render the reframe composite image.")
        }
        try ensureDirectory(url.deletingLastPathComponent())
        _ = try writePNG(composite, to: url)
    }

    private func loadReframeCompositeImage(path: String, label: String) throws -> CGImage {
        let sourceURL = URL(fileURLWithPath: path)
        guard let imageSource = CGImageSourceCreateWithURL(sourceURL as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(imageSource, 0, nil) else {
            throw ScreenGraphError.capture("Could not read the reframe \(label) image at \(path)")
        }
        return image
    }

    private func drawAspectFit(_ image: CGImage, in rect: CGRect, context: CGContext) {
        let size = CGSize(width: image.width, height: image.height)
        guard size.width > 0, size.height > 0, rect.width > 0, rect.height > 0 else { return }
        let scale = min(rect.width / size.width, rect.height / size.height)
        let targetSize = CGSize(width: size.width * scale, height: size.height * scale)
        let target = CGRect(
            x: rect.midX - targetSize.width / 2,
            y: rect.midY - targetSize.height / 2,
            width: targetSize.width,
            height: targetSize.height
        )
        context.draw(image, in: target)
    }

    func lensHeroMotionStartBlockReason(lensId: String, imageId: String) -> String? {
        guard currentProject != nil else { return "Create or select a project first" }
        guard !isGenerationPaused else { return "Generation is paused — resume to animate this Frame" }
        if isAnimatingLensArtifact {
            return activeLensMotionImageId == imageId
                ? "This Frame is already animating"
                : "Another Frame animation is already running"
        }
        guard !isGeneratingLensHero, !isGeneratingInitialDraftLenses else {
            return "Scene Plan rendering is already running"
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            return "Scene Plan not found"
        }
        guard let image = lens.sortedHeroImages.first(where: { $0.imageId == imageId })?.normalized() else {
            return "Frame not found"
        }
        guard image.status == "ready", !image.imagePath.trimmed.isEmpty else {
            return "Render the Frame before animating it"
        }
        guard FileManager.default.fileExists(atPath: image.imagePath) else {
            return "Frame image is missing on disk"
        }
        guard videoCredentialStore.credentialStatus(for: .civitai).isConfigured else {
            return "Add a CivitAI API key in App Settings to animate this Frame"
        }
        return nil
    }

    @discardableResult
    func animateLensHeroImageWithWAN25(lensId: String, imageId: String) async -> Bool {
        if let blockReason = lensHeroMotionStartBlockReason(lensId: lensId, imageId: imageId) {
            aestheticStatus = blockReason
            return false
        }
        guard let project = currentProject,
              let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lens.sortedHeroImages
        guard let heroIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Frame not found"
            return false
        }
        let image = heroImages[heroIndex].normalized()

        let now = DateFormats.now()
        let motionRunId = "lensmotion_\(shortHash("\(project.projectId):\(lensId):\(imageId):\(now)", length: 18))"
        let prompt = lensWAN25MotionPrompt(lens: lens, image: image)
        var running = image
        running.motionArtifact = LensMotionArtifact(
            provider: "civitai",
            model: VideoModelSelection.civitaiWanV25ImageToVideo.providerModelId,
            status: "generating",
            videoPath: image.motionArtifact?.videoPath ?? "",
            prompt: prompt,
            requestId: "",
            traceId: "",
            errorMessage: "",
            generatedAt: "",
            updatedAt: now
        ).normalized()
        heroImages[heroIndex] = running.normalized()

        guard saveLensHeroMotionImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Animating frame with WAN 2.5"
        ) else {
            return false
        }

        isAnimatingLensArtifact = true
        activeLensMotionImageId = imageId
        defer {
            isAnimatingLensArtifact = false
            activeLensMotionImageId = ""
        }
        aestheticStatus = "Animating frame with WAN 2.5"

        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("lens_motion_\(shortHash("\(project.projectId):\(lensId):\(imageId):\(now)", length: 14))_wan25.mp4")
        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let provider = CivitAIWANVideoProvider(credentialStore: videoCredentialStore)
            logGeneration(
                kind: "video.start",
                message: "Frame motion (WAN 2.5) lens_id=\(lensId) image_id=\(imageId)"
            )
            let motionStartedAt = Date()
            let result = try await provider.generateClip(from: VideoClipRequest(
                chainId: motionRunId,
                segmentId: imageId,
                modelSelection: .civitaiWanV25ImageToVideo,
                prompt: prompt,
                negativePrompt: "text artifacts, captions, logos, extra limbs, warped anatomy, hard cuts, flicker, melting faces",
                durationSeconds: 5,
                outputProfile: .standard(.landscape16x9, fitPolicy: .fitWithBlurFill),
                startFrameURL: URL(fileURLWithPath: image.imagePath),
                targetEndFrameURL: nil,
                outputURL: outputURL,
                projectId: project.projectId,
                runId: motionRunId,
                traceGroupId: motionRunId,
                workflowName: "lens_frame_motion",
                artifactType: "lens_motion"
            ))
            let motionDurationMs = Int(Date().timeIntervalSince(motionStartedAt) * 1000)
            logGeneration(
                kind: "video.completed",
                message: "Frame motion ready lens_id=\(lensId) image_id=\(imageId) duration_ms=\(motionDurationMs) request_id=\(result.providerJobId.trimmed.nilIfEmpty ?? "-")"
            )
            guard currentProject?.projectId == project.projectId else { return false }
            var readyImages = heroImages
            readyImages[heroIndex].motionArtifact = LensMotionArtifact(
                provider: "civitai",
                model: result.responseSnapshot["model"] ?? VideoModelSelection.civitaiWanV25ImageToVideo.providerModelId,
                status: "ready",
                videoPath: result.outputURL.path,
                prompt: prompt,
                requestId: result.providerJobId,
                traceId: result.traceId,
                errorMessage: "",
                generatedAt: DateFormats.now(),
                updatedAt: DateFormats.now()
            ).normalized()
            if saveLensHeroMotionImages(
                readyImages,
                lensId: lensId,
                project: project,
                status: "WAN 2.5 frame motion ready"
            ) {
                aestheticStatus = "WAN 2.5 frame motion ready"
                return true
            }
            return false
        } catch {
            logGeneration(
                kind: "video.error",
                message: "Frame motion failed lens_id=\(lensId) image_id=\(imageId): \(shortSummaryText(error.localizedDescription, limit: 200))"
            )
            guard currentProject?.projectId == project.projectId else { return false }
            var failedImages = heroImages
            failedImages[heroIndex].motionArtifact = LensMotionArtifact(
                provider: "civitai",
                model: VideoModelSelection.civitaiWanV25ImageToVideo.providerModelId,
                status: "failed",
                videoPath: image.motionArtifact?.videoPath ?? "",
                prompt: prompt,
                requestId: "",
                traceId: "",
                errorMessage: error.localizedDescription,
                generatedAt: "",
                updatedAt: DateFormats.now()
            ).normalized()
            _ = saveLensHeroMotionImages(
                failedImages,
                lensId: lensId,
                project: project,
                status: "WAN 2.5 frame motion failed"
            )
            aestheticStatus = "WAN 2.5 frame motion failed"
            lastError = error.localizedDescription
            return false
        }
    }

    /// Narrates a ready Lens take: OpenAI drafts a short voice-over script from the
    /// take's world, ElevenLabs speaks it, and the result attaches to the row as a
    /// narration artifact (one narration per row; regenerating replaces it).
    @discardableResult
    func startLensHeroNarration(lensId: String, imageId: String, voicePresetId: String) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGeneratingLensNarration else {
            aestheticStatus = "Narration is already running"
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lens.sortedHeroImages
        guard let heroIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Frame not found"
            return false
        }
        let image = heroImages[heroIndex].normalized()
        guard image.status == "ready", !image.imagePath.trimmed.isEmpty else {
            aestheticStatus = "Render the take before narrating it"
            return false
        }
        guard ElevenLabsSettingsStore.hasResolvedAPIKey() else {
            aestheticStatus = "Add an ElevenLabs API key in App Settings before narrating"
            lastError = aestheticStatus
            return false
        }
        let voiceOption = StoryAudioVoiceCatalog.option(
            for: voicePresetId,
            customVoiceId: ElevenLabsSettingsStore.resolvedCustomVoiceId()
        )
        guard let resolvedVoiceId = voiceOption.voiceId?.trimmed.nilIfEmpty else {
            aestheticStatus = "Select Archer/Lucy or configure Custom Voice ID before narrating"
            lastError = aestheticStatus
            return false
        }
        let speechModelId = ElevenLabsSpeechModels.defaultModelId

        let now = DateFormats.now()
        var running = image
        running.narrationArtifact = LensNarrationArtifact(
            model: speechModelId,
            status: "generating",
            audioPath: image.narrationArtifact?.audioPath ?? "",
            script: image.narrationArtifact?.script ?? "",
            voicePresetId: voiceOption.id,
            voiceName: voiceOption.name,
            voiceId: resolvedVoiceId,
            updatedAt: now
        ).normalized()
        heroImages[heroIndex] = running.normalized()

        isGeneratingLensNarration = true
        defer { isGeneratingLensNarration = false }
        aestheticStatus = "Narrating take"
        guard saveLensHeroMotionImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Narrating take"
        ) else {
            return false
        }

        let runId = "lens_narration_\(shortHash("\(project.projectId):\(lensId):\(imageId):\(now)", length: 14))"
        do {
            let openAIClient = try OpenAIClient.fromEnvironment()
            let scriptPrompt = LensNarrationComposer.scriptPrompt(
                lensTitle: lens.body.title,
                subjectSummary: image.subject?.description ?? "",
                imagePrompt: RosterMentionResolver.strippingMentionTokens(
                    image.sourcePrompt.trimmed.isEmpty ? image.prompt : image.sourcePrompt
                )
            )
            aestheticStatus = "Writing narration"
            let draft = try await openAIClient.draftLensNarration(
                prompt: scriptPrompt,
                projectId: project.projectId,
                runId: runId
            )
            guard currentProject?.projectId == project.projectId else { return false }

            aestheticStatus = "Voicing narration"
            let elevenClient = ElevenLabsClient(apiKey: try ElevenLabsSettingsStore.resolvedAPIKeyOrThrow())
            let speech = try await elevenClient.createSpeech(
                voiceId: resolvedVoiceId,
                text: draft.script,
                modelId: speechModelId,
                projectId: project.projectId,
                runId: runId
            )
            guard currentProject?.projectId == project.projectId else { return false }

            recordSpend(SpendLedgerEntry(
                kind: "narration_tts",
                provider: "elevenlabs_tts",
                model: speechModelId,
                requestId: speech.requestId,
                contextLabel: image.label.trimmed.nilIfEmpty ?? "Frame narration",
                imageId: imageId,
                unit: "characters",
                unitCount: Double(speech.characterCount) ?? 0,
                estimatedCredits: Double(speech.characterCost),
                pricingNote: "elevenlabs character-cost header"
            ))
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let audioURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("\(runId)_\(safeIdentifier(imageId))_narration.mp3")
            try speech.data.write(to: audioURL, options: [.atomic])
            let duration = await lensNarrationDuration(url: audioURL)

            var readyImages = heroImages
            readyImages[heroIndex].narrationArtifact = LensNarrationArtifact(
                model: speechModelId,
                status: "ready",
                audioPath: audioURL.path,
                script: draft.script,
                voicePresetId: voiceOption.id,
                voiceName: voiceOption.name,
                voiceId: resolvedVoiceId,
                durationSeconds: duration,
                scriptResponseId: draft.responseId,
                requestId: speech.requestId,
                traceId: draft.traceId,
                errorMessage: "",
                generatedAt: DateFormats.now(),
                updatedAt: DateFormats.now()
            ).normalized()
            if saveLensHeroMotionImages(
                readyImages,
                lensId: lensId,
                project: project,
                status: "Narration ready"
            ) {
                aestheticStatus = "Narration ready"
                return true
            }
            return false
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            var failedImages = heroImages
            failedImages[heroIndex].narrationArtifact = LensNarrationArtifact(
                model: speechModelId,
                status: "failed",
                audioPath: image.narrationArtifact?.audioPath ?? "",
                script: image.narrationArtifact?.script ?? "",
                voicePresetId: voiceOption.id,
                voiceName: voiceOption.name,
                voiceId: resolvedVoiceId,
                errorMessage: error.localizedDescription,
                updatedAt: DateFormats.now()
            ).normalized()
            _ = saveLensHeroMotionImages(
                failedImages,
                lensId: lensId,
                project: project,
                status: "Narration failed"
            )
            aestheticStatus = "Narration failed"
            lastError = error.localizedDescription
            return false
        }
    }

    private func lensNarrationDuration(url: URL) async -> Double {
        let asset = AVURLAsset(url: url)
        guard let duration = try? await asset.load(.duration) else { return 0 }
        let seconds = duration.seconds
        return seconds.isFinite ? max(0, seconds) : 0
    }

    /// Re-renders a Lens's media chain (scene, then character, then object) as a NEW media
    /// version using the stored media prompts. When `updatedTreatment` is provided (draft
    /// slider weights), it is committed onto the Lens body in the SAME version write that
    /// queues the media, so one gesture produces exactly one creative version. Prior media
    /// versions are kept; new images carry an "@versionId" sourceRouteKey suffix and the
    /// blend's recipeText in sourceRecipeVersion for provenance.
    @discardableResult
    func regenerateLensMedia(
        lensId: String,
        updatedTreatment: LensStyleTreatment? = nil,
        updatedPlan: LensMediaPlan? = nil,
        updatedAnchor: LensCanonicalAnchor?? = nil
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGeneratingLensHero, !isGeneratingInitialDraftLenses else {
            aestheticStatus = "Scene Plan media generation is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard var lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        if let updatedTreatment {
            lens.body.styleTreatment = updatedTreatment.normalized()
        }
        if let updatedPlan {
            let normalizedPlan = updatedPlan.normalized()
            lens.body.mediaPlan = normalizedPlan
            // Keep the legacy field coherent for older readers.
            lens.body.compositeCharacterCount = min(3, normalizedPlan.characterCount)
        }
        if let updatedAnchor {
            lens.body.canonicalAnchor = updatedAnchor?.normalized()
        }
        guard lens.body.hasRenderableMediaSources else {
            aestheticStatus = "This Scene Plan has no scene to render — regenerate the Scene Plan to author its world"
            return false
        }
        guard let treatment = lens.body.styleTreatment, !treatment.isEmpty else {
            aestheticStatus = "This Scene Plan has no style treatment"
            return false
        }

        beginLensHeroExclusiveHold(lensId: lensId)
        defer { endLensHeroExclusiveHold() }

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let client = try OpenAIClient.fromEnvironment()
            let stabilityClient = try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let mediaSummaries = aestheticMediaSummaryPackets(limit: 20)
            let now = DateFormats.now()
            let versionId = shortHash("\(lensId):\(now)", length: 8)
            let runId = "lens_media_v_\(versionId)"
            let styleReferenceIds = uniqueNonEmpty(lens.body.styleIngredients.flatMap(\.sourceReferenceIds))
            let fallbackCatalog = await styleBrowseCatalogForAttachmentFallback()
            let styleAuthorities = generatedTakeStyleAuthorities(lens: lens, catalog: fallbackCatalog)

            let newImages = queuedLensConceptImages(
                lens: lens,
                versionId: versionId,
                mediaSummaries: mediaSummaries,
                styleReferenceIds: styleReferenceIds,
                styleAuthorities: styleAuthorities
            )
            guard !newImages.isEmpty else {
                aestheticStatus = "No Scene Plan media could be queued"
                return false
            }
            let planChanged = updatedPlan != nil || updatedAnchor != nil
            let changeSummary: String
            if updatedTreatment != nil && planChanged {
                changeSummary = "Regenerated media with blend \(treatment.weightSummary) and an updated media plan."
            } else if updatedTreatment != nil {
                changeSummary = "Regenerated media with blend \(treatment.weightSummary)."
            } else if planChanged {
                changeSummary = "Regenerated media with an updated media plan."
            } else {
                changeSummary = "Regenerated media with the saved blend."
            }
            guard queueLensMediaVersion(
                lens: lens,
                newImages: newImages,
                project: project,
                status: "Regenerating Scene Plan media",
                changeSummary: changeSummary
            ) else {
                return false
            }

            var chainReferences: [LensConceptChainEntry] = []
            var readySlots = 0
            for heroImage in newImages {
                try Task.checkCancellation()
                try await waitWhileGenerationPaused()
                guard currentProject?.projectId == project.projectId else { return false }
                let mediaLabel = heroImage.label.trimmed.isEmpty ? heroImage.provider.capitalized : heroImage.label
                aestheticStatus = "Rendering \(mediaLabel)"
                let provider = LensHeroImageProvider(rawValue: heroImage.provider) ?? .openAI
                let isCharacterStudy = LensConceptCategory.category(for: heroImage) == .characters
                let fileName = "\(runId)_\(safeIdentifier(lensId))_\(safeIdentifier(heroImage.imageId)).\(isCharacterStudy ? "png" : "jpg")"
                let assignedStyleId = heroImage.sourceAestheticIds.first
                // World continuity flows only between same-style SCENERY frames, capped
                // at two: studies neither receive study continuity nor provide any.
                let continuityURLs = lensConceptContinuityURLs(
                    assignedStyleId: assignedStyleId,
                    chain: chainReferences
                )
                let characterScopeId = isCharacterStudy
                    ? lensResolvedTakeCharacterId(for: heroImage, lens: lens, cast: lensCompositeCast(for: lens))
                    : ""
                let plan = provider == .openAI
                    ? lensBlendAttachmentPlan(
                        lens: lens,
                        catalog: fallbackCatalog,
                        assignedStyleId: assignedStyleId,
                        characterScopeId: characterScopeId,
                        continuityURLs: continuityURLs
                    )
                    : LensBlendAttachmentPlan()
                let job = LensHeroGenerationJob(
                    lensId: lensId,
                    imageId: heroImage.imageId,
                    provider: provider,
                    skipPromptEnrichment: heroImage.promptEnrichmentDisabled,
                    prompt: heroImage.prompt,
                    sourcePrompt: heroImage.sourcePrompt.trimmed.isEmpty ? heroImage.prompt : heroImage.sourcePrompt,
                    negativePrompt: heroImage.negativePrompt,
                    attachments: plan.entries,
                    promptPreamble: plan.promptPreamble,
                    attachmentManifest: plan.manifestText,
                    styleSummary: plan.styleSummaryText,
                    attachmentManifestEntries: plan.manifestEntryLinesText,
                    attachmentStylePolicy: plan.manifestPolicyText,
                    imageSize: lens.body.resolvedMediaPlan.imageSize,
                    stabilityAspectRatio: lens.body.resolvedMediaPlan.stabilityAspectRatio,
                    stabilityStrength: heroImage.stabilityStrength,
                    mediaPlan: lens.body.resolvedMediaPlan,
                    transparentBackground: isCharacterStudy,
                    outputURL: contextStore.aestheticProofDirectory(for: project).appendingPathComponent(fileName),
                    projectId: project.projectId,
                    runId: heroImage.imageId
                )
                let outcome = await LensHeroImageRunner.generate(
                    job: job,
                    openAIClient: client,
                    stabilityClient: stabilityClient
                )
                guard currentProject?.projectId == project.projectId else { return false }
                if outcome.status == "ready" {
                    readySlots += 1
                    chainReferences.append(LensConceptChainEntry(
                        styleId: heroImage.sourceAestheticIds.first ?? "",
                        category: LensConceptCategory.category(for: heroImage),
                        url: URL(fileURLWithPath: outcome.imagePath)
                    ))
                } else if outcome.status == "failed" {
                    lastError = outcome.errorMessage
                }
                let statusVerb = outcome.status == "ready" ? "ready" : outcome.status
                _ = saveLensHeroImageOutcome(
                    outcome,
                    project: project,
                    status: "Regenerated \(readySlots)/\(newImages.count) Scene Plan media",
                    changeSummary: "\(mediaLabel) Scene Plan media \(statusVerb).",
                    appendVersion: false
                )
            }

            aestheticStatus = readySlots == newImages.count
                ? "Regenerated Scene Plan media"
                : "Regenerated Scene Plan media; \(readySlots)/\(newImages.count) ready"
            print("[lens_media_regen] completed lens_id=\(lensId) version=\(versionId) ready=\(readySlots)/\(newImages.count)")
            return true
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return false
            }
            lastError = error.localizedDescription
            aestheticStatus = "Scene Plan media regeneration failed"
            return false
        }
    }

    @discardableResult
    func commitLensScratch(
        scratchId: String,
        body: LensBody,
        changeSummary: String = "Updated scratch draft."
    ) -> Bool {
        guard let project = currentProject else { return false }
        var updated = projectLenses
        var scratchDrafts = updated.scratchDrafts
        guard let index = scratchDrafts.firstIndex(where: { $0.scratchId == scratchId }) else {
            aestheticStatus = "Draft not found"
            return false
        }
        let now = DateFormats.now()
        scratchDrafts[index].body = body.normalized()
        scratchDrafts[index].updatedAt = now
        updated.appendVersion(
            lenses: updated.lenses,
            scratchDrafts: scratchDrafts,
            selectedLensId: nil,
            selectedScratchId: scratchId,
            changeSummary: changeSummary,
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: "Draft saved")
    }

    @discardableResult
    func commitLensBody(
        lensId: String,
        body: LensBody,
        changeSummary: String = "Updated Scene Plan."
    ) -> Bool {
        guard let project = currentProject else { return false }
        var updated = lensSetWithRefreshedRelations(projectLenses, for: project)
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        themes[index].body = body.normalized()
        themes[index].updatedAt = now
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lensId,
            selectedScratchId: nil,
            changeSummary: changeSummary,
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: "Scene Plan saved")
    }

    @discardableResult
    func setReferenceMediaForLensScratch(mediaId: String, scratchId: String, enabled: Bool) -> Bool {
        guard let scratch = projectLenses.scratchDrafts.first(where: { $0.scratchId == scratchId }) else {
            aestheticStatus = "Create a scratch draft first"
            return false
        }
        if enabled {
            guard enabledContentItems.contains(where: { $0.mediaId == mediaId }) else {
                aestheticStatus = "Enabled media item not found"
                return false
            }
        }
        var body = scratch.body
        if enabled {
            body.referenceMediaIds = uniqueNonEmpty(body.referenceMediaIds + [mediaId])
        } else {
            body.referenceMediaIds.removeAll { $0 == mediaId }
        }
        return commitLensScratch(
            scratchId: scratch.scratchId,
            body: body,
            changeSummary: enabled ? "Added Scene Plan media anchor." : "Removed Scene Plan media anchor."
        )
    }

    @discardableResult
    func setSREFStyleReferenceForLensScratch(
        _ reference: SREFStyleImageReference,
        scratchId: String,
        enabled: Bool
    ) -> Bool {
        guard let scratch = projectLenses.scratchDrafts.first(where: { $0.scratchId == scratchId }) else {
            aestheticStatus = "Create a scratch draft first"
            return false
        }
        let normalized = reference.normalized()
        var body = scratch.body
        if enabled {
            let alreadySelected = body.styleIngredients.contains { ingredient in
                ingredient.sourceReferenceIds.compactMap(SREFStyleImageReference.decodeSourceReferenceId).contains {
                    $0.id == normalized.id
                }
            }
            if !alreadySelected {
                let nextOrder = (body.styleIngredients.map(\.order).max() ?? 0) + 1
                body.styleIngredients.append(.srefStyleReference(normalized, order: nextOrder))
            }
        } else {
            body.styleIngredients = body.styleIngredients.compactMap { ingredient in
                var updated = ingredient
                updated.sourceReferenceIds.removeAll { rawValue in
                    SREFStyleImageReference.decodeSourceReferenceId(rawValue)?.id == normalized.id
                }
                if ingredient.role == "style_reference", updated.sourceReferenceIds.isEmpty {
                    return nil
                }
                return updated
            }
        }
        return commitLensScratch(
            scratchId: scratch.scratchId,
            body: body,
            changeSummary: enabled ? "Added SREF style reference." : "Removed SREF style reference."
        )
    }

    @discardableResult
    func setStyleTreatmentForLensScratch(_ treatment: LensStyleTreatment?, scratchId: String) async -> Bool {
        guard let scratch = projectLenses.scratchDrafts.first(where: { $0.scratchId == scratchId }) else {
            aestheticStatus = "Create a scratch draft first"
            return false
        }
        var body = scratch.body
        body.styleTreatment = treatment?.normalized()
        body.styleIngredients = await styleIngredientsResynced(body.styleIngredients, treatment: body.styleTreatment)
        return commitLensScratch(
            scratchId: scratch.scratchId,
            body: body,
            changeSummary: treatment?.isEmpty == false ? "Updated style treatment." : "Cleared style treatment."
        )
    }

    @discardableResult
    func setStyleTreatmentForLens(_ treatment: LensStyleTreatment?, lensId: String) async -> Bool {
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var body = lens.body
        body.styleTreatment = treatment?.normalized()
        body.styleIngredients = await styleIngredientsResynced(body.styleIngredients, treatment: body.styleTreatment)
        return commitLensBody(
            lensId: lensId,
            body: body,
            changeSummary: treatment?.isEmpty == false ? "Updated style treatment." : "Cleared style treatment."
        )
    }

    // MARK: - Project character roster

    @discardableResult
    func createCharacter(name: String, descriptionPrompt: String = "") -> ProjectCharacter? {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return nil
        }
        let trimmedName = name.trimmed
        guard projectCharacters.nameIsAvailable(trimmedName) else {
            aestheticStatus = trimmedName.isEmpty ? "Character name cannot be empty" : "A character named \"\(trimmedName)\" already exists"
            return nil
        }
        let now = DateFormats.now()
        let character = ProjectCharacter(
            characterId: "character_\(shortHash("\(project.projectId):\(trimmedName):\(now)", length: 12))",
            name: trimmedName,
            descriptionPrompt: descriptionPrompt,
            updatedAt: now
        ).normalized()
        var updated = projectCharacters
        updated.projectId = project.projectId
        updated.characters.append(character)
        updated.updatedAt = now
        guard saveProjectCharacters(updated, for: project, status: "Created character \(trimmedName)") else { return nil }
        return character
    }

    @discardableResult
    func renameCharacter(characterId: String, name: String, descriptionPrompt: String? = nil) -> Bool {
        guard let project = currentProject else { return false }
        guard var character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        let trimmedName = name.trimmed
        guard projectCharacters.nameIsAvailable(trimmedName, excludingCharacterId: characterId) else {
            aestheticStatus = trimmedName.isEmpty ? "Character name cannot be empty" : "A character named \"\(trimmedName)\" already exists"
            return false
        }
        character.name = trimmedName
        if let descriptionPrompt {
            character.descriptionPrompt = descriptionPrompt
        }
        character.updatedAt = DateFormats.now()
        var updated = projectCharacters
        updated.characters = updated.characters.map { $0.characterId == characterId ? character.normalized() : $0 }
        updated.updatedAt = character.updatedAt
        return saveProjectCharacters(updated, for: project, status: "Updated character \(trimmedName)")
    }

    /// Replaces a character's ordered reference media (drag-organized in the roster UI).
    @discardableResult
    func setCharacterReferenceMedia(characterId: String, mediaIds: [String]) -> Bool {
        guard let project = currentProject else { return false }
        guard var character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        let knownMediaIds = Set(items.map(\.mediaId))
        character.referenceMediaIds = uniqueNonEmpty(mediaIds).filter { knownMediaIds.contains($0) }
        character.updatedAt = DateFormats.now()
        var updated = projectCharacters
        updated.characters = updated.characters.map { $0.characterId == characterId ? character.normalized() : $0 }
        updated.updatedAt = character.updatedAt
        guard saveProjectCharacters(updated, for: project, status: "Updated \(character.name) references") else { return false }
        refreshCharacterCompositeSheetIfPresent(characterId: characterId)
        return true
    }

    /// Sets (or clears, with an empty label) the label on one of a character's
    /// reference images ("young Ava"). Labels on the leading attached references also
    /// ride the render manifest so generation knows what each image shows.
    @discardableResult
    func setCharacterReferenceLabel(characterId: String, mediaId: String, label: String) -> Bool {
        guard let project = currentProject else { return false }
        guard var character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        guard character.referenceMediaIds.contains(mediaId) else {
            aestheticStatus = "That image is not a \(character.name) reference"
            return false
        }
        let trimmed = label.trimmed
        if trimmed.isEmpty {
            character.referenceLabels.removeValue(forKey: mediaId)
        } else {
            character.referenceLabels[mediaId] = trimmed
        }
        character.updatedAt = DateFormats.now()
        var updated = projectCharacters
        updated.characters = updated.characters.map { $0.characterId == characterId ? character.normalized() : $0 }
        updated.updatedAt = character.updatedAt
        guard saveProjectCharacters(
            updated,
            for: project,
            status: trimmed.isEmpty ? "Cleared a \(character.name) reference label" : "Labeled \(character.name) reference \"\(trimmed)\""
        ) else { return false }
        refreshCharacterCompositeSheetIfPresent(characterId: characterId)
        return true
    }

    /// Read-only: the active-version lenses deleteCharacter would unlink (cast-member
    /// links and media-plan selections). Drives the roster delete confirmation.
    func lensesCastingCharacter(characterId: String) -> [ProjectLens] {
        projectLenses.lenses.filter { lens in
            let inCast = lens.body.castMembers?.contains { $0.characterId == characterId } ?? false
            let inPlan = lens.body.mediaPlan?.selectedCharacterIds.contains(characterId) ?? false
            return inCast || inPlan
        }
    }

    /// Deletes a roster character and unlinks it from every Lens that cast it (cast
    /// members keep their name and description; only the roster link clears).
    @discardableResult
    func deleteCharacter(characterId: String) -> Bool {
        guard let project = currentProject else { return false }
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        let now = DateFormats.now()
        var updated = projectCharacters
        updated.characters.removeAll { $0.characterId == characterId }
        updated.updatedAt = now
        guard saveProjectCharacters(updated, for: project, status: "Deleted character \(character.name)") else { return false }
        characterRenderNotes.removeValue(forKey: characterId)
        // Symmetry with the goal cast: a surviving member with this character's
        // id (or name) would re-create the roster row on the next sync.
        let castRemoval = goalCast.removingMember(linkedTo: characterId, name: character.name)
        if castRemoval.removed != nil {
            _ = saveGoalCast(castRemoval.document, for: project, status: "Deleted character \(character.name)")
        }

        var lensSet = projectLenses
        var changedLenses = false
        let unlinked = lensSet.lenses.map { lens -> ProjectLens in
            var value = lens
            var body = value.body
            var changed = false
            if let members = body.castMembers, members.contains(where: { $0.characterId == characterId }) {
                body.castMembers = members.map { member in
                    var updatedMember = member
                    if updatedMember.characterId == characterId {
                        updatedMember.characterId = nil
                        changed = true
                    }
                    return updatedMember
                }
            }
            if var plan = body.mediaPlan, plan.selectedCharacterIds.contains(characterId) {
                plan.selectedCharacterIds.removeAll { $0 == characterId }
                body.mediaPlan = plan
                changed = true
            }
            // A deleted character's unrendered suggestions are intentions for no
            // one: rows and scenes go with it (a scene left behind would be
            // re-minted as a fresh plan row on the next append-only merge).
            let orphanRows = value.heroImages.filter { $0.suggestedForCharacterId == characterId && $0.isPlanFulfillmentCandidate }
            if !orphanRows.isEmpty {
                let orphanIds = Set(orphanRows.map(\.imageId))
                let orphanSceneIds = Set(orphanRows.map(\.sceneId).filter { !$0.isEmpty })
                value.heroImages.removeAll { orphanIds.contains($0.imageId) }
                value.heroImage = value.primaryHeroImage
                if !orphanSceneIds.isEmpty, let areas = body.areas {
                    body.areas = areas
                        .map { area in
                            var trimmed = area
                            trimmed.scenes.removeAll { orphanSceneIds.contains($0.sceneId) }
                            return trimmed
                        }
                        .filter { !$0.scenes.isEmpty }
                }
                changed = true
            }
            if changed {
                value.body = body.normalized()
                value.updatedAt = now
                changedLenses = true
            }
            return value
        }
        if changedLenses {
            lensSet.updateActiveVersion(lenses: unlinked, now: now)
            _ = saveLensSet(lensSet, for: project, status: "Removed \(character.name) from Scene Plan casts")
        }
        return true
    }

    @discardableResult
    private func saveProjectCharacters(_ document: ProjectCharacterSetDocument, for project: ProjectRecord, status: String) -> Bool {
        do {
            var normalized = document.normalized()
            if normalized.projectId.isEmpty {
                normalized.projectId = project.projectId
            }
            try contextStore.saveProjectCharacters(normalized, for: project)
            projectCharacters = normalized
            aestheticStatus = status
            lastError = ""
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save characters"
            return false
        }
    }

    // MARK: - Character sheets

    @discardableResult
    private func saveProjectCharacterChats(_ document: ProjectCharacterChatDocument, for project: ProjectRecord) -> Bool {
        do {
            var normalized = document.normalized()
            if normalized.projectId.isEmpty {
                normalized.projectId = project.projectId
            }
            try contextStore.saveProjectCharacterChats(normalized, for: project)
            projectCharacterChats = normalized
            lastError = ""
            return true
        } catch {
            lastError = error.localizedDescription
            characterChatStatus = "Could not save the character conversation"
            return false
        }
    }

    /// Every generated sheet for a character, newest first.
    func characterSheetItems(characterId: String) -> [MediaItemRecord] {
        items.filter { $0.isCharacterSheet && $0.sourceMediaId == characterId }
            .sorted { $0.scannedAt > $1.scannedAt }
    }

    /// The sheet that anchors a character's identity, when one is on record and on disk
    /// in the inventory.
    func activeCharacterSheetItem(for characterId: String) -> MediaItemRecord? {
        guard let character = projectCharacters.character(withId: characterId),
              let sheetId = character.activeSheetMediaId else { return nil }
        return items.first { $0.mediaId == sheetId && $0.isCharacterSheet }
    }

    /// True when at least one roster character anchors on a sheet in the inventory.
    var hasAnyCharacterSheet: Bool {
        let sheetIds = Set(items.filter(\.isCharacterSheet).map(\.mediaId))
        guard !sheetIds.isEmpty else { return false }
        return projectCharacters.characters.contains { character in
            guard let sheetId = character.activeSheetMediaId else { return false }
            return sheetIds.contains(sheetId)
        }
    }

    /// The images a SHEET render attaches on this stack: the active sheet first
    /// (continuity), then the leading source images within the stack's capacity.
    func characterSheetRenderPicks(for character: ProjectCharacter, stack: RenderStack) -> [CharacterSheetRenderPick] {
        let sources = character.referenceMediaIds.compactMap { mediaId in
            items.first { $0.mediaId == mediaId }
        }
        return RosterCharacterRenderPrompt.sheetRenderPicks(
            activeSheet: activeCharacterSheetItem(for: character.characterId),
            sources: sources,
            referenceLabels: character.referenceLabels,
            capacity: characterSheetReferenceCapacity(for: stack)
        )
    }

    /// Stability folds every reference into one composite; a sheet's panels stay
    /// legible only with a few cells beside it.
    static let characterSheetCompositeCellBudget = 4

    private func characterSheetReferenceCapacity(for stack: RenderStack) -> Int {
        let capacity = stack.frameReferenceCapacity
        return capacity == .compositeSheet ? Self.characterSheetCompositeCellBudget : capacity.planningCap
    }

    func characterSheetFill(for character: ProjectCharacter, attachesReferences: Bool) -> CharacterSheetPrompt.Fill {
        let identity = goalCastMember(forCharacterId: character.characterId, name: character.name)?.activeIdentity
        let story = identity.map {
            CharacterSheetPrompt.StoryIdentityLines(
                essence: $0.essence,
                publicFunction: $0.publicFunction,
                desire: $0.desire,
                signature: $0.signature
            )
        }
        return CharacterSheetPrompt.Fill(
            name: character.name,
            visualDescription: character.descriptionPrompt,
            signatureProps: character.signatureProps,
            storyIdentity: story,
            sheetDirectives: character.sheetDirectives,
            attachesReferences: attachesReferences
        )
    }

    /// The prompt the identity composes for a sheet render on this stack (no prompt
    /// transform), before any hand edit.
    func composedCharacterSheetPrompt(for character: ProjectCharacter, stack: RenderStack) -> String {
        let template = projectPromptSettings.characterSheetTemplate(
            model: stack.isFAL ? stack.reframePromptModel : stack.model
        )
        let attaches = !characterSheetRenderPicks(for: character, stack: stack).isEmpty
        return CharacterSheetPrompt.render(
            template: template.body,
            fill: characterSheetFill(for: character, attachesReferences: attaches)
        )
    }

    /// Composed text, hand edit, drift, and currency in one place.
    func characterSheetPromptState(for character: ProjectCharacter, stack: RenderStack) -> CharacterSheetPromptState {
        CharacterSheetPromptState.resolve(
            composed: composedCharacterSheetPrompt(for: character, stack: stack),
            override: character.sheetPromptOverride,
            overrideBaseHash: character.sheetPromptOverrideBaseHash,
            activeSheetMediaId: character.activeSheetMediaId,
            activeSheetPromptHash: character.activeSheetPromptHash
        )
    }

    /// The exact prompt a sheet render on this stack transmits: the hand edit when
    /// one exists, else the composed prompt.
    func renderedCharacterSheetPrompt(for character: ProjectCharacter, stack: RenderStack) -> String {
        characterSheetPromptState(for: character, stack: stack).effective
    }

    /// False when the character's prompt moved past the sheet it currently anchors on.
    func characterSheetPromptIsCurrent(for character: ProjectCharacter, stack: RenderStack) -> Bool {
        characterSheetPromptState(for: character, stack: stack).isCurrent
    }

    /// The stack a character's sheets and studies render on: its own pick while the
    /// registry still offers it, else the default.
    func resolvedCharacterSheetStack(for character: ProjectCharacter) -> RenderStack? {
        let stacks = RenderStackRegistry.shared.stacks()
        if let stackId = character.sheetStackId, let stack = stacks.first(where: { $0.id == stackId }) {
            return stack
        }
        return defaultCharacterSheetStack()
    }

    @discardableResult
    func setCharacterSheetStack(characterId: String, stackId: String) -> Bool {
        guard let stack = RenderStackRegistry.shared.stacks().first(where: { $0.id == stackId }) else {
            aestheticStatus = "That render stack is not available"
            return false
        }
        let name = projectCharacters.character(withId: characterId)?.name ?? "Character"
        return updateCharacter(characterId: characterId, status: "\(name)'s sheets render on \(stack.label)") {
            $0.sheetStackId = stack.id
        }
    }

    /// EDIT: the operator's text replaces the composed prompt until reset. Text equal
    /// to the composition is no edit; empty text clears the edit.
    @discardableResult
    func setCharacterSheetPromptOverride(characterId: String, text: String) -> Bool {
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        let trimmed = text.trimmed
        guard !trimmed.isEmpty else { return clearCharacterSheetPromptOverride(characterId: characterId) }
        if trimmed == character.sheetPromptOverride { return true }
        guard let stack = resolvedCharacterSheetStack(for: character) else {
            aestheticStatus = "No render stack is available"
            return false
        }
        let composed = composedCharacterSheetPrompt(for: character, stack: stack)
        if trimmed == composed.trimmed { return clearCharacterSheetPromptOverride(characterId: characterId) }
        return updateCharacter(characterId: characterId, status: "\(character.name)'s sheet prompt is hand-edited — render to see it") {
            $0.sheetPromptOverride = trimmed
            $0.sheetPromptOverrideBaseHash = CharacterSheetPrompt.promptHash(composed)
        }
    }

    /// RESET TO COMPOSED: the prompt follows the identity again.
    @discardableResult
    func clearCharacterSheetPromptOverride(characterId: String, status: String? = nil) -> Bool {
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        guard character.hasSheetPromptOverride else { return true }
        return updateCharacter(characterId: characterId, status: status ?? "\(character.name)'s sheet prompt follows the identity again") {
            $0.sheetPromptOverride = nil
            $0.sheetPromptOverrideBaseHash = ""
        }
    }

    /// The single mutation path for a character's sheet-side fields.
    @discardableResult
    private func updateCharacter(
        characterId: String,
        status: String,
        mutate: (inout ProjectCharacter) -> Void
    ) -> Bool {
        guard let project = currentProject else { return false }
        guard var character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        mutate(&character)
        character.updatedAt = DateFormats.now()
        var updated = projectCharacters
        updated.characters = updated.characters.map { $0.characterId == characterId ? character.normalized() : $0 }
        updated.updatedAt = character.updatedAt
        return saveProjectCharacters(updated, for: project, status: status)
    }

    /// USE THIS VERSION: the chosen sheet becomes the identity anchor.
    @discardableResult
    func setActiveCharacterSheet(characterId: String, mediaId: String) -> Bool {
        guard let sheet = items.first(where: { $0.mediaId == mediaId }),
              sheet.isCharacterSheet,
              sheet.sourceMediaId == characterId else {
            aestheticStatus = "That image is not one of this character's sheets"
            return false
        }
        let name = projectCharacters.character(withId: characterId)?.name ?? "Character"
        let newestSheetId = characterSheetItems(characterId: characterId).first?.mediaId
        return updateCharacter(characterId: characterId, status: "\(name) now anchors on this sheet") {
            // Rows from before per-sheet hashes kept one hash, always the last render's.
            if $0.sheetPromptHashes.isEmpty, !$0.activeSheetPromptHash.isEmpty, let newestSheetId {
                $0.sheetPromptHashes[newestSheetId] = $0.activeSheetPromptHash
            }
            $0.activateSheet(mediaId: sheet.mediaId)
        }
    }

    @discardableResult
    func setCharacterSheetDirectives(characterId: String, _ directives: [String]) -> Bool {
        updateCharacter(characterId: characterId, status: "Updated sheet directives") {
            $0.sheetDirectives = directives
        }
    }

    @discardableResult
    func setCharacterSignatureProps(characterId: String, _ props: [String]) -> Bool {
        updateCharacter(characterId: characterId, status: "Updated signature props") {
            $0.signatureProps = props
        }
    }

    @discardableResult
    func setCharacterAutoRenderSheet(characterId: String, enabled: Bool) -> Bool {
        updateCharacter(
            characterId: characterId,
            status: enabled ? "Each message renders a new sheet" : "Sheet renders on request"
        ) {
            $0.autoRenderSheetAfterChat = enabled
        }
    }

    // MARK: - Character conversation

    /// Story Inputs that look like this character, for one-click adoption as sources.
    func suggestedSourceImages(for characterId: String) -> [MediaItemRecord] {
        guard let character = projectCharacters.character(withId: characterId) else { return [] }
        let candidates = enabledContentItems.compactMap { item -> CharacterMediaCandidate? in
            guard item.kind == .image, let observation = mediaObservationsById[item.mediaId] else { return nil }
            return CharacterMediaCandidate(
                mediaId: item.mediaId,
                peopleVisible: observation.peopleVisible,
                caption: observation.plainCaption,
                literalDescription: observation.literalDescription,
                roles: observation.peopleRolesVisible
            )
        }
        let ids = characterSourceImageSuggestions(
            name: character.name,
            description: character.descriptionPrompt,
            candidates: candidates,
            excluding: Set(character.referenceMediaIds).union(claimedSourceMediaIds(excludingCharacterId: characterId))
        )
        return ids.compactMap { id in items.first { $0.mediaId == id } }
    }

    /// THE ONE-PHOTO-ONE-CHARACTER LAW's ledger: every source image some other
    /// roster character already holds. Automatic assignment (casting, source
    /// suggestions) never hands these out again; the operator's own picks may.
    func claimedSourceMediaIds(excludingCharacterId characterId: String) -> Set<String> {
        Set(projectCharacters.characters
            .filter { $0.characterId != characterId }
            .flatMap(\.referenceMediaIds))
    }

    /// Why a stack cannot render a sheet right now, in words — nil when it can. Sheets
    /// ship the template verbatim, so only the provider's own key gates them.
    func renderStackCredentialBlocker(for stack: RenderStack) -> String? {
        let configured = videoProviderCredentialStatuses
            .first { $0.provider == stack.credentialProvider }?.isConfigured == true
        return configured ? nil : "Add a \(stack.credentialProvider.label) key in App Settings."
    }

    /// The stack a sheet renders on when the operator picked none: Nano Banana 2
    /// while FAL is configured, then the Frame default order (`characterSheetDefaultStack`).
    func defaultCharacterSheetStack() -> RenderStack? {
        characterSheetDefaultStack(stacks: RenderStackRegistry.shared.stacks()) {
            renderStackCredentialBlocker(for: $0) == nil
        }
    }

    /// A character holds at most this many unrendered sheet-driven suggestions.
    static let characterFrameSuggestionCap = 3

    /// Unrendered sheet-driven suggestions this character already holds in the
    /// newest media version.
    func unrenderedSuggestionCount(forCharacterId characterId: String) -> Int {
        guard let lens = projectLenses.lenses.first else { return 0 }
        return lens.heroImages(mediaVersion: lens.mediaVersionIds.last ?? "")
            .filter { $0.isPlanFulfillmentCandidate && $0.suggestedForCharacterId == characterId }
            .count
    }

    private var characterFrameSuggestionAttempts: Set<String> = []
    private var characterFrameSuggestionSweepTask: Task<Void, Never>?

    func characterSuggestionIdentity(for characterId: String) -> CharacterSuggestionIdentity? {
        guard let character = projectCharacters.character(withId: characterId) else { return nil }
        return LitScenes.characterSuggestionIdentity(character: character, items: items)
    }

    func characterIsSuggestable(_ characterId: String) -> Bool {
        characterSuggestionIdentity(for: characterId)?.isSuggestable == true
    }

    /// Roster order.
    var suggestableCharacterIds: [String] {
        projectCharacters.characters.map(\.characterId).filter(characterIsSuggestable)
    }

    /// nil when a suggestion call may run now; else the quiet reason.
    var characterFrameSuggestionBlockReason: String? {
        guard currentProject != nil else { return "Create or select a project first" }
        guard projectLenses.lenses.first != nil else { return "Plan Frames first" }
        guard projectGoalV2.activeVersion?.brief.isReady == true else { return "Save a Story first" }
        if isGeneratingInitialDraftLenses { return "Planning Frames…" }
        if isReplanningLensFromStory { return "Refreshing the plan from the Story…" }
        return nil
    }

    private func recordCharacterFrameSuggestionAttempt(characterId: String) {
        guard let projectId = currentProject?.projectId,
              let identity = characterSuggestionIdentity(for: characterId) else { return }
        characterFrameSuggestionAttempts.insert(characterFrameSuggestionAttemptKey(projectId: projectId, identity: identity))
    }

    /// THE ENSURE PASS (SCENES v2 appears): every suggestable character holding
    /// zero unrendered suggestions gets one automatic text-only call per session
    /// per identity fingerprint — a new sheet or a changed source set earns one
    /// more. Sequential (the hero hold and the API), engine-owned so a tab switch
    /// never cancels it, quiet on every guard. The key is recorded before the
    /// call: a failure consumes the automatic attempt and SUGGEST FRAMES is the
    /// explicit retry.
    func ensureCharacterFrameSuggestions() {
        guard characterFrameSuggestionSweepTask == nil,
              characterFrameSuggestionBlockReason == nil,
              let projectId = currentProject?.projectId else { return }
        let due = suggestableCharacterIds.filter { id in
            guard let identity = characterSuggestionIdentity(for: id) else { return false }
            return unrenderedSuggestionCount(forCharacterId: id) == 0
                && !suggestingCharacterIds.contains(id)
                && !characterFrameSuggestionAttempts.contains(characterFrameSuggestionAttemptKey(projectId: projectId, identity: identity))
        }
        guard !due.isEmpty else { return }
        characterFrameSuggestionSweepTask = Task { @MainActor [weak self] in
            defer { self?.characterFrameSuggestionSweepTask = nil }
            for id in due {
                guard let self, self.currentProject?.projectId == projectId else { return }
                self.recordCharacterFrameSuggestionAttempt(characterId: id)
                await self.suggestFramesForCharacter(characterId: id)
            }
        }
    }

    /// SUGGEST FRAMES / MORE SUGGESTIONS: explicit, ignores the session memory,
    /// every suggestable character under the cap, sequential. Returns the number
    /// of Frames appended.
    @discardableResult
    func suggestFramesForAllSuggestableCharacters() async -> Int {
        if let reason = characterFrameSuggestionBlockReason {
            aestheticStatus = reason
            return 0
        }
        let ids = suggestableCharacterIds
        guard !ids.isEmpty else {
            aestheticStatus = "No characters with reference images yet — add one in CHARACTERS"
            return 0
        }
        var appended = 0
        for id in ids where unrenderedSuggestionCount(forCharacterId: id) < Self.characterFrameSuggestionCap {
            let before = unrenderedSuggestionCount(forCharacterId: id)
            recordCharacterFrameSuggestionAttempt(characterId: id)
            if await suggestFramesForCharacter(characterId: id) {
                appended += max(0, unrenderedSuggestionCount(forCharacterId: id) - before)
            }
        }
        return appended
    }

    /// THE CHARACTER → SUGGESTIONS LAW: a character with a sheet or source images
    /// mints two NEW planned Frames — dramatic MOMENTS in which the character acts —
    /// through a text/vision call (no ledger row, no pause guard) merged
    /// append-only into the newest media version under the hero hold, exactly like
    /// a Story-driven refresh, capped at three unrendered suggestions per
    /// character. Rows are scene rows (places stay coherent) whose prompt the
    /// character-moment composer writes. Every guard is quiet; the CHARACTERS note
    /// and the SCENES section carry the outcome.
    @discardableResult
    func suggestFramesForCharacter(characterId: String) async -> Bool {
        guard let project = currentProject,
              let character = projectCharacters.character(withId: characterId),
              let identity = characterSuggestionIdentity(for: characterId), identity.isSuggestable,
              let startingLens = projectLenses.lenses.first,
              let version = projectGoalV2.activeVersion, version.brief.isReady,
              !isGeneratingInitialDraftLenses, !isReplanningLensFromStory,
              !suggestingCharacterIds.contains(characterId) else { return false }
        let held = unrenderedSuggestionCount(forCharacterId: characterId)
        guard held < Self.characterFrameSuggestionCap else {
            print("[frame_suggestions] skipped cap character_id=\(characterId) held=\(held)")
            return false
        }
        suggestingCharacterIds.insert(characterId)
        defer { suggestingCharacterIds.remove(characterId) }
        if characterRenderNotes[characterId]?.lane == .suggestions {
            characterRenderNotes.removeValue(forKey: characterId)
        }
        let name = character.name
        aestheticStatus = "Suggesting Frames for \(name)"
        do {
            let client = try OpenAIClient.fromEnvironment()
            let liveBody = startingLens.body.normalized()
            let areas = (liveBody.areas ?? []).filter(\.enabled)
            var visionInputs: [OpenAIVisionImageInput] = []
            if let visionMediaId = identity.visionMediaId,
               let inputs = try? goalVisionInputs(mediaIds: [visionMediaId], limit: 1) {
                visionInputs = inputs
            }
            let context = CharacterFrameSuggestionContext(
                projectId: project.projectId,
                projectName: project.name,
                characterId: characterId,
                characterName: name,
                characterAppearance: character.descriptionPrompt,
                characterIdentityGist: goalCastIdentityGist(forCharacter: character) ?? "",
                otherCharacterLines: lensPlanningCharacterLines().filter { !$0.hasPrefix("- \(name)") },
                goalSummary: goalBriefV2StyleSummary(version.brief),
                existingAreaLines: areas.map { "- area_id=\($0.areaId) · \($0.title) · \($0.setting.condensed)" },
                existingSceneLines: areas.flatMap { area in
                    area.scenes.map { scene in
                        let beat = scene.storyBeat.isEmpty ? "none" : scene.storyBeat
                        let cast = scene.cast.isEmpty ? "none" : scene.cast.map(\.name).joined(separator: ", ")
                        return "- \(scene.title) · beat=\(beat) · area_id=\(area.areaId) · cast=\(cast)"
                    }
                },
                mediaObservationLines: lensPlanningMediaObservationLines(lensPlanningObservationEntries()),
                sourceImageLines: selectedGoalMediaSummary(mediaIds: Array(character.referenceMediaIds.prefix(8))),
                attachedIdentityImage: visionInputs.isEmpty ? .none : identity.identityImageKind
            )
            let result = try await client.suggestCharacterFrames(context: context, visionInputs: visionInputs)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId,
                  let liveLens = projectLenses.lenses.first(where: { $0.lensId == startingLens.lensId }) else { return false }
            let now = DateFormats.now()
            let validCastNames = uniqueNonEmpty(projectCharacters.characters.map(\.name) + goalCast.members.map(\.name))
            let appended = liveLens.body.appendingSuggestedScenes(
                result.response.scenes,
                characterName: name,
                validCastNames: validCastNames,
                salt: "\(characterId):\(now)"
            )
            guard !appended.newSceneIds.isEmpty else {
                aestheticStatus = "No usable Frame suggestions for \(name)"
                characterRenderNotes[characterId] = CharacterRenderNote(
                    lane: .suggestions,
                    message: "Frame suggestions came back empty — SUGGEST FRAMES in SCENES tries again."
                )
                return false
            }
            // Roster-link only the areas this call minted (an existing area keeps
            // its place; re-stamping every area by title could duplicate a renamed
            // place).
            var placesDraft = projectPlaces
            placesDraft.projectId = project.projectId
            var body = appended.body
            let unlinked = (body.areas ?? []).filter { $0.placeId.isEmpty }
            if !unlinked.isEmpty, let linked = lensPlacesFromComposition(unlinked, placesDraft: &placesDraft, now: now) {
                let placeIdsByAreaId = Dictionary(linked.map { ($0.areaId, $0.placeId) }, uniquingKeysWith: { first, _ in first })
                body.areas = (body.areas ?? []).map { area in
                    var value = area
                    if value.placeId.isEmpty, let placeId = placeIdsByAreaId[value.areaId] { value.placeId = placeId }
                    return value
                }
            }
            var candidate = liveLens
            candidate.body = body.normalized()
            let newestVersionId = liveLens.mediaVersionIds.last ?? ""
            let browseCatalog = try? await StyleBrowseCatalogRuntime.shared.loadCatalog()
            let styleReferenceIds = uniqueNonEmpty(candidate.body.styleIngredients.flatMap(\.sourceReferenceIds))
            let styleAuthorities = generatedTakeStyleAuthorities(lens: candidate, catalog: browseCatalog)
            let newSceneIds = Set(appended.newSceneIds)
            let scenesById = Dictionary(
                (candidate.body.areas ?? []).flatMap(\.scenes).map { ($0.sceneId, $0) },
                uniquingKeysWith: { first, _ in first }
            )
            let closingLines = lensConceptClosingLines(theme: candidate, plan: candidate.body.resolvedMediaPlan)
            let aspect = candidate.body.resolvedMediaPlan.aspect
            // The scene rows keep their taxonomy, route key, style, and recipe;
            // only the words change: a moment, never an environment plate.
            let fresh = queuedLensConceptImages(
                lens: candidate,
                versionId: newestVersionId,
                mediaSummaries: [],
                styleReferenceIds: styleReferenceIds,
                styleAuthorities: styleAuthorities,
                includeAreaImages: false
            )
            .filter { newSceneIds.contains($0.sceneId) }
            .map { row -> ProjectLensHeroImage in
                var value = row
                if let scene = scenesById[row.sceneId] {
                    let copy = CharacterMomentFramePrompt.compose(
                        characterName: name,
                        scene: scene,
                        moment: appended.momentsBySceneId[row.sceneId] ?? "",
                        validCastNames: validCastNames,
                        aspect: aspect,
                        closingLines: closingLines
                    )
                    value.prompt = copy.sourcePrompt
                    value.sourcePrompt = copy.sourcePrompt
                    value.label = copy.label
                    value.subject?.description = copy.sourcePrompt
                }
                value.suggestedForCharacterId = characterId
                value.suggestedAt = now
                return value.normalized()
            }
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId,
                  let latestLens = projectLenses.lenses.first(where: { $0.lensId == startingLens.lensId }) else { return false }
            beginLensHeroExclusiveHold(lensId: latestLens.lensId)
            defer { endLensHeroExclusiveHold() }
            let outcome = LensPlanMerge.merged(
                existing: latestLens.heroImages,
                fresh: fresh,
                mediaVersionId: newestVersionId,
                mode: .appendOnly,
                now: now
            )
            var merged = latestLens
            merged.body = candidate.body
            merged.heroImages = outcome.heroImages
            merged.heroImage = merged.primaryHeroImage
            merged.updatedAt = now
            merged = merged.normalized()
            var updated = projectLenses
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            let count = outcome.appendedImageIds.count
            updated.appendVersion(
                lenses: lensesByReplacing(existing: updated.lenses, replacements: [merged]),
                scratchDrafts: updated.scratchDrafts,
                selectedLensId: merged.lensId,
                selectedScratchId: nil,
                changeSummary: "Suggested \(count) Frames for \(name).",
                model: result.model,
                now: now
            )
            let statusLine = "Suggested \(count) Frame\(count == 1 ? "" : "s") for \(name)"
            guard saveLensSet(updated, for: project, status: statusLine) else {
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .suggestions, message: "Frame suggestions failed — \(lastError)")
                return false
            }
            if placesDraft != projectPlaces {
                _ = saveProjectPlaces(placesDraft, for: project, status: statusLine)
            }
            _ = reconcileLensCastFromTakes(lensId: merged.lensId)
            characterRenderNotes[characterId] = CharacterRenderNote(
                lane: .suggestions,
                message: "\(count) Frame\(count == 1 ? "" : "s") suggested in SCENES",
                suggestedFrameCount: count
            )
            aestheticStatus = statusLine
            print("[frame_suggestions] appended=\(count) character_id=\(characterId) project_id=\(project.projectId)")
            return count > 0
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) { return false }
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "Frame suggestions for \(name) failed"
            characterRenderNotes[characterId] = CharacterRenderNote(lane: .suggestions, message: "Frame suggestions failed — \(error.localizedDescription)")
            print("[frame_suggestions] failed character_id=\(characterId) error=\(error.localizedDescription)")
            return false
        }
    }

    /// The stack a one-click Frame render uses when the operator picked none:
    /// OpenAI first, then any credentialed stack, else the first stack (its
    /// blocker explains the refusal) — `frameDefaultStack`.
    func defaultFrameStack() -> RenderStack? {
        frameDefaultStack(stacks: RenderStackRegistry.shared.stacks()) {
            renderStackCredentialBlocker(for: $0) == nil
        }
    }

    /// ONE explicit paid gesture: renders a planned row in place with the plan's
    /// defaults — what the Frame Creator would submit for `.plannedFrame`
    /// untouched, plus the plan's style slot (`LensPlannedFrameDefaults`). Every
    /// refusal lands in `aestheticStatus` in words; false means nothing started.
    @discardableResult
    func renderPlannedFrameWithDefaults(lensId: String, imageId: String) async -> Bool {
        guard currentProject != nil else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        guard let planned = lens.heroImages.first(where: { $0.imageId == imageId }) else {
            aestheticStatus = "That Frame is no longer in the plan"
            return false
        }
        guard planned.isPlanFulfillmentCandidate else {
            aestheticStatus = "This Frame has already rendered — start a variation instead"
            return false
        }
        if let reason = lensHeroTakeStartBlockReason {
            aestheticStatus = reason
            return false
        }
        guard let stack = defaultFrameStack() else {
            aestheticStatus = "Add an API key in App Settings to render"
            return false
        }
        if let blocker = renderStackCredentialBlocker(for: stack) {
            aestheticStatus = blocker
            return false
        }
        let request = LensPlannedFrameDefaults.request(
            planned: planned,
            lens: lens,
            stack: stack,
            styleSlot: lensTakeStyleSlot(for: planned, treatment: lens.body.styleTreatment),
            styleCatalogVersion: lens.body.styleTreatment?.catalogVersion ?? "",
            mentionEntries: frameCreatorMentionEntries(for: lens),
            mentionItems: items.filter { $0.kind == .image }
        )
        return await startLensHeroPlanFulfillmentRender(lensId: lensId, plannedImageId: imageId, request: request)
    }

    // MARK: - Identity draft (one-click casting)

    /// Whether a render for this character drafts the identity first.
    func characterIdentityDraftDecision(for character: ProjectCharacter) -> CharacterIdentityDraftDecision {
        let identity = goalCastMember(forCharacterId: character.characterId, name: character.name)?.activeIdentity
        let hasCastIdentity = identity.map {
            !$0.essence.isEmpty || !$0.publicFunction.isEmpty || !$0.desire.isEmpty || !$0.signature.isEmpty
        } ?? false
        let unlabeled = character.referenceMediaIds.filter { (character.referenceLabels[$0] ?? "").trimmed.isEmpty }.count
        return CharacterIdentityDraft.decision(
            hasAppearance: !character.descriptionPrompt.trimmed.isEmpty,
            hasCastIdentity: hasCastIdentity,
            hasSignatureProps: !character.signatureProps.isEmpty,
            sourceCount: character.referenceMediaIds.count,
            unlabeledSourceCount: unlabeled,
            lastDraftFailed: characterRenderNotes[character.characterId]?.lane == .draft
        )
    }

    /// Casts one character from the story: the Goal, the other characters, and the
    /// source images shape the BLANK parts of the identity — never the written ones —
    /// and the result becomes a cast take, the roster's appearance and props, source
    /// labels, and a turn in the character's conversation. Text-only with vision: no
    /// ledger row, no pause guard. `blanks` overrides the gate (REDRAFT passes all).
    @discardableResult
    func draftCharacterIdentity(characterId: String, blanks requestedBlanks: Set<CharacterIdentityBlank>? = nil) async -> Bool {
        guard let project = currentProject else {
            characterChatStatus = "Create or select a project first"
            return false
        }
        guard let character = projectCharacters.character(withId: characterId) else {
            characterChatStatus = "Character not found"
            return false
        }
        guard !draftingCharacterIds.contains(characterId) else { return false }
        let blanks: Set<CharacterIdentityBlank>
        if let requestedBlanks {
            blanks = requestedBlanks
        } else if case .draft(let decided) = characterIdentityDraftDecision(for: character) {
            blanks = decided
        } else {
            return true
        }
        if characterRenderNotes[characterId]?.lane == .draft {
            characterRenderNotes.removeValue(forKey: characterId)
        }
        draftingCharacterIds.insert(characterId)
        defer { draftingCharacterIds.remove(characterId) }
        lastError = ""
        characterChatStatus = "Casting \(character.name) from the story"
        do {
            let client = try OpenAIClient.fromEnvironment()
            let context = characterIdentityDraftContext(for: character, blanks: blanks, project: project)
            let visionInputs = try goalVisionInputs(mediaIds: Array(character.referenceMediaIds.prefix(6)))
            let result = try await client.draftCharacterIdentity(context: context, visionInputs: visionInputs)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return false }
            applyCharacterIdentityDraft(result.response, to: characterId, blanks: blanks, project: project)
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let reason = goalInterviewDidTimeout(error) ? "the model timed out" : error.localizedDescription
            lastError = error.localizedDescription
            characterRenderNotes[characterId] = CharacterRenderNote(lane: .draft, message: "Identity draft failed: \(reason)")
            characterChatStatus = "Identity draft failed for \(character.name)"
            return false
        }
    }

    private func characterIdentityDraftContext(
        for character: ProjectCharacter,
        blanks: Set<CharacterIdentityBlank>,
        project: ProjectRecord
    ) -> CharacterIdentityDraftContext {
        let brief = projectGoalV2.activeVersion?.brief
        let member = goalCastMember(forCharacterId: character.characterId, name: character.name)
        var keepLines: [String] = []
        if !blanks.contains(.appearance), !character.descriptionPrompt.trimmed.isEmpty {
            keepLines.append("appearance: \(character.descriptionPrompt.trimmed)")
        }
        if !blanks.contains(.props), !character.signatureProps.isEmpty {
            keepLines.append("signature props: \(character.signatureProps.joined(separator: "; "))")
        }
        if !blanks.contains(.storyIdentity), let identity = member?.activeIdentity {
            var parts: [String] = []
            if !identity.essence.isEmpty { parts.append(identity.essence) }
            if let gist = identity.gist { parts.append(gist) }
            if !parts.isEmpty { keepLines.append("story identity: \(parts.joined(separator: " | "))") }
        }
        let otherCharacterLines = projectCharacters.characters
            .filter { $0.characterId != character.characterId }
            .map { other -> String in
                var line = other.descriptionPrompt.isEmpty ? "- \(other.name)" : "- \(other.name) — \(other.descriptionPrompt)"
                if let gist = goalCastIdentityGist(forCharacter: other) { line += " | identity: \(gist)" }
                return line
            }
        let lowerName = character.name.trimmed.lowercased()
        return CharacterIdentityDraftContext(
            projectId: project.projectId,
            projectName: project.name,
            characterName: character.name,
            blanks: blanks,
            keepLines: keepLines,
            goalSummary: brief.map { goalBriefV2StyleSummary($0) } ?? "",
            requiredEntityLines: brief?.requiredEntities.map { entity in
                entity.role.trimmed.isEmpty ? "- \(entity.name) [required]" : "- \(entity.name) (\(entity.role)) [required]"
            } ?? [],
            castLines: goalCast.members
                .filter { $0.characterId != character.characterId && $0.name.trimmed.lowercased() != lowerName }
                .map(\.contextSummaryLine),
            otherCharacterLines: otherCharacterLines,
            moodboardLines: goalMoodboardAnalysisContext(),
            sourceImageLines: selectedGoalMediaSummary(mediaIds: Array(character.referenceMediaIds.prefix(8))),
            sourceCount: character.referenceMediaIds.count
        )
    }

    private func applyCharacterIdentityDraft(
        _ response: CharacterIdentityDraftResponse,
        to characterId: String,
        blanks: Set<CharacterIdentityBlank>,
        project: ProjectRecord
    ) {
        guard let character = projectCharacters.character(withId: characterId) else { return }
        let now = DateFormats.now()
        let lowerName = character.name.trimmed.lowercased()
        var document = goalCast
        if document.projectId.isEmpty { document.projectId = project.projectId }
        let existingIndex = document.members.firstIndex { member in
            (!member.characterId.isEmpty && member.characterId == characterId)
                || member.name.trimmed.lowercased() == lowerName
        }
        var member: GoalCastMember
        if let existingIndex {
            member = document.members[existingIndex]
        } else {
            let role = projectGoalV2.activeVersion?.brief.requiredEntities
                .first { $0.name.trimmed.lowercased() == lowerName }?.role ?? ""
            member = GoalCastMember(
                memberId: "castmember_\(shortHash("\(project.projectId):\(character.name):\(now)", length: 12))",
                name: character.name,
                roleLabel: role,
                updatedAt: now
            )
        }
        member.characterId = characterId
        let merged = CharacterIdentityDraft.mergedIdentity(
            prior: member.activeIdentity,
            emitted: response.identity,
            blanks: blanks,
            pinned: member.pinnedDimensionSet
        )
        member.appendTake(GoalCastTake.minted(origin: "draft", identity: merged, now: now), now: now)
        if let existingIndex {
            document.members[existingIndex] = member
        } else {
            // Newest first in the STORY cast list.
            document.members.insert(member, at: 0)
        }

        // The sync is the single writer of appearance and props from a cast identity;
        // whatever was already written comes back afterwards untouched.
        let priorDescription = character.descriptionPrompt
        let priorProps = character.signatureProps
        syncGoalCastMembersToRoster([member.memberId], in: &document, for: project)
        saveGoalCast(document, for: project, status: "Cast \(character.name) from the story")

        let props = Array(uniqueNonEmpty(response.signatureProps).prefix(3))
        let environment = response.environmentAffinity.trimmed
        let notes = response.sourceImageNotes
        updateCharacter(characterId: characterId, status: "Cast \(character.name) from the story") { updated in
            if !blanks.contains(.appearance) { updated.descriptionPrompt = priorDescription }
            if blanks.contains(.props) {
                if !props.isEmpty { updated.signatureProps = props }
            } else {
                updated.signatureProps = priorProps
            }
            if updated.environmentAffinity.trimmed.isEmpty, !environment.isEmpty {
                updated.environmentAffinity = environment
            }
            if blanks.contains(.sourceLabels) {
                for note in notes {
                    let label = note.label.trimmed
                    guard !label.isEmpty,
                          updated.referenceMediaIds.contains(note.mediaId),
                          (updated.referenceLabels[note.mediaId] ?? "").trimmed.isEmpty else { continue }
                    updated.referenceLabels[note.mediaId] = label
                }
            }
        }

        var lines: [String] = []
        let castingNote = response.castingNote.trimmed
        lines.append(castingNote.isEmpty ? "Cast \(character.name) from the story." : castingNote)
        if let refreshed = projectCharacters.character(withId: characterId) {
            if blanks.contains(.appearance), !refreshed.descriptionPrompt.isEmpty {
                lines.append("Appearance: \(refreshed.descriptionPrompt)")
            }
            if blanks.contains(.props), !refreshed.signatureProps.isEmpty {
                lines.append("Always with them: \(refreshed.signatureProps.joined(separator: "; "))")
            }
        }
        if blanks.contains(.storyIdentity) {
            if !merged.essence.isEmpty { lines.append("Story identity: \(merged.essence)") }
            if let gist = merged.gist { lines.append(gist) }
        }
        var chats = projectCharacterChats
        if chats.projectId.isEmpty { chats.projectId = project.projectId }
        chats.appendTurn(characterId: characterId, role: .assistant, text: lines.joined(separator: "\n"), now: DateFormats.now())
        _ = saveProjectCharacterChats(chats, for: project)
        characterChatStatus = "Cast \(character.name) from the story"
    }

    // MARK: - Character source intake

    /// THE SOURCE INTAKE LAW: a character source is project-owned bytes identified
    /// by content — copied under the library, deduplicated by sha256 against the
    /// inventory (legacy rows of the same size hashed lazily), a Story Input, and
    /// analyzed automatically without ever blocking the character.
    func intakeCharacterSourceFiles(_ urls: [URL]) async -> [MediaItemRecord] {
        guard let project = currentProject else {
            characterChatStatus = "Create or select a project first"
            return []
        }
        let imageURLs = urls.filter { url in
            guard let type = UTType(filenameExtension: url.pathExtension) else { return false }
            return type.conforms(to: .image)
        }
        guard !imageURLs.isEmpty else {
            characterChatStatus = "Paste or upload image files"
            return []
        }
        var intake: [MediaItemRecord] = []
        var reused = 0
        for url in imageURLs {
            let standardizedURL = url.standardizedFileURL
            characterChatStatus = "Adding \(standardizedURL.lastPathComponent)"
            guard let data = try? Data(contentsOf: standardizedURL) else { continue }
            let outcome = await intakeCharacterSource(data: data, filename: standardizedURL.lastPathComponent, project: project)
            guard let item = outcome.item else { continue }
            if outcome.reused { reused += 1 }
            intake.append(item)
        }
        characterChatStatus = CharacterSourceIntake.intakeStatus(added: intake.count - reused, reused: reused)
        queueCharacterSourceAnalysis(intake.map(\.mediaId))
        if !intake.isEmpty { touchCurrentProject() }
        return intake
    }

    /// Pasted image bytes take the same road after the pasteboard normalization.
    func intakeCharacterSourceData(_ data: Data) async -> MediaItemRecord? {
        guard let project = currentProject else {
            characterChatStatus = "Create or select a project first"
            return nil
        }
        do {
            let normalized = try normalizedJPEGData(from: data)
            let outcome = await intakeCharacterSource(data: normalized.data, filename: "Pasted image.jpg", project: project)
            guard let item = outcome.item else {
                characterChatStatus = "Could not add the pasted image"
                return nil
            }
            characterChatStatus = outcome.reused ? "Already in media — reused the pasted image" : "Added the pasted image as a source"
            queueCharacterSourceAnalysis([item.mediaId])
            touchCurrentProject()
            return item
        } catch {
            lastError = error.localizedDescription
            characterChatStatus = "Could not add the pasted image"
            return nil
        }
    }

    /// Images already in the project (ADD FROM MEDIA, chat-attached library items)
    /// only need their analysis.
    func ensureCharacterSourcesAnalyzed(mediaIds: [String]) {
        let pending = mediaIds.filter { id in
            items.contains { $0.mediaId == id && $0.kind == .image }
                && mediaObservationsById[id]?.isCurrentAestheticObservationVersion != true
        }
        queueCharacterSourceAnalysis(pending)
    }

    func characterSourceAnalysisState(for mediaId: String) -> CharacterSourceAnalysisState {
        CharacterSourceIntake.analysisState(
            hasCurrentObservation: mediaObservationsById[mediaId]?.isCurrentAestheticObservationVersion == true,
            isQueued: queuedSourceAnalysisIds.contains(mediaId),
            isAnalyzing: analyzingMediaIds.contains(mediaId),
            hasCredential: isOpenAICredentialConfigured
        )
    }

    private func intakeCharacterSource(
        data: Data,
        filename: String,
        project: ProjectRecord
    ) async -> (item: MediaItemRecord?, reused: Bool) {
        let sha = sha256Hex(data)
        switch CharacterSourceIntake.plan(sha256: sha, byteCount: data.count, items: items) {
        case .reuse(let mediaId):
            return (items.first { $0.mediaId == mediaId }, true)
        case .hashCandidates(let candidateIds):
            if let match = backfillContentHashes(candidateIds: candidateIds, matching: sha, project: project) {
                return (match, true)
            }
        case .copy:
            break
        }
        do {
            let url = try store.copyCharacterSource(
                data: data,
                sha256: sha,
                fileExtension: (filename as NSString).pathExtension,
                for: project
            )
            let item = await archiveGeneratedMedia(
                fileURL: url,
                project: project,
                mediaId: CharacterSourceIntake.mediaId(projectId: project.projectId, sha256: sha),
                derivativeKind: MediaItemRecord.characterSourceDerivativeKind,
                sourceMediaId: nil,
                filename: filename,
                tags: ["character-source"],
                notes: "Character source image, copied into the project.",
                rejectedByDefault: false
            )
            return (item, false)
        } catch {
            lastError = error.localizedDescription
            characterChatStatus = "Could not copy \(filename) into the project"
            return (nil, false)
        }
    }

    /// Hashes same-size legacy rows on demand and remembers the answer; returns the
    /// row whose bytes match.
    private func backfillContentHashes(candidateIds: [String], matching sha: String, project: ProjectRecord) -> MediaItemRecord? {
        var updated = items
        var match: MediaItemRecord?
        var changed = false
        for candidateId in candidateIds {
            guard let index = updated.firstIndex(where: { $0.mediaId == candidateId }),
                  let data = try? Data(contentsOf: URL(fileURLWithPath: updated[index].path)) else { continue }
            updated[index].contentSha256 = sha256Hex(data)
            changed = true
            if updated[index].contentSha256 == sha, match == nil {
                match = updated[index]
            }
        }
        if changed, (try? store.saveInventory(updated, for: project)) != nil {
            items = updated
        }
        return match
    }

    private func queueCharacterSourceAnalysis(_ mediaIds: [String]) {
        for mediaId in mediaIds where !characterSourceAnalysisQueue.contains(mediaId) {
            characterSourceAnalysisQueue.append(mediaId)
        }
        queuedSourceAnalysisIds = Set(characterSourceAnalysisQueue)
        drainCharacterSourceAnalysisQueue()
    }

    /// One pass for everything queued, whenever the analysis lane is free and a key
    /// exists; the pass reuses cached analyses across projects on its own.
    private func drainCharacterSourceAnalysisQueue() {
        guard let project = currentProject else { return }
        let runnable = CharacterSourceIntake.drainDecision(
            queued: characterSourceAnalysisQueue,
            isAnalyzingMedia: isAnalyzingMedia,
            isScanning: isScanning,
            hasCredential: isOpenAICredentialConfigured
        )
        guard !runnable.isEmpty else { return }
        characterSourceAnalysisQueue.removeAll { runnable.contains($0) }
        queuedSourceAnalysisIds = Set(characterSourceAnalysisQueue)
        let batch = runnable.compactMap { id in items.first { $0.mediaId == id && $0.kind == .image } }
            .filter { mediaObservationsById[$0.mediaId]?.isCurrentAestheticObservationVersion != true }
        guard !batch.isEmpty else { return }
        Task { [weak self] in
            await self?.analyzeMediaItems(
                batch,
                project: project,
                startMessage: "Analyzing \(batch.count) character source image\(batch.count == 1 ? "" : "s").",
                usesSingleItemStatus: batch.count == 1
            )
        }
    }

    /// UPLOAD FILES on the casting desk: chosen files go through the intake law.
    func chooseCharacterSourceImages() async -> [MediaItemRecord] {
        guard currentProject != nil else {
            characterChatStatus = "Create or select a project first"
            return []
        }
        let panel = NSOpenPanel()
        panel.title = "Upload Source Images"
        panel.message = "Choose one or more images of this character. They are copied into the project."
        panel.prompt = "Upload"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.canCreateDirectories = false
        panel.allowedContentTypes = [.image]
        guard panel.runModal() == .OK else { return [] }
        return await intakeCharacterSourceFiles(panel.urls)
    }

    func chooseCharacterChatImageAttachments() async -> [MediaItemRecord] {
        guard currentProject != nil else {
            characterChatStatus = "Create or select a project first"
            return []
        }
        let panel = NSOpenPanel()
        panel.title = "Attach Images"
        panel.message = "Choose one or more images of this character. They are copied into the project."
        panel.prompt = "Attach"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.canCreateDirectories = false
