    }

    func importCharacterChatImageData(_ data: Data) async -> MediaItemRecord? {
        await intakeCharacterSourceData(data)
    }

    /// One turn of a character's conversation: attached images become source images,
    /// the model revises the appearance line, props, and the complete directive list
    /// (text-only, no ledger row), and — when the character renders after each message
    /// and something changed — a new sheet renders as its own paid version.
    func sendCharacterChatMessage(
        characterId: String,
        text rawText: String,
        mediaIds rawMediaIds: [String] = [],
        stack: RenderStack? = nil
    ) async {
        guard let project = currentProject else {
            characterChatStatus = "Create or select a project first"
            return
        }
        guard let character = projectCharacters.character(withId: characterId) else {
            characterChatStatus = "Character not found"
            return
        }
        let text = rawText.trimmed
        let mediaIds = normalizedExistingMediaIds(rawMediaIds)
        guard !text.isEmpty || !mediaIds.isEmpty else {
            characterChatStatus = "Write a message or attach an image first"
            return
        }
        guard !refiningCharacterIds.contains(characterId) else { return }
        refiningCharacterIds.insert(characterId)
        defer { refiningCharacterIds.remove(characterId) }
        lastError = ""
        characterChatStatus = "Refining \(character.name)"

        // The gesture is the association: attached images join the source images.
        if !mediaIds.isEmpty {
            _ = setCharacterReferenceMedia(characterId: characterId, mediaIds: character.referenceMediaIds + mediaIds)
            ensureCharacterSourcesAnalyzed(mediaIds: mediaIds)
        }
        let submittedText = text.isEmpty ? "Attached image." : text
        var chats = projectCharacterChats
        if chats.projectId.isEmpty {
            chats.projectId = project.projectId
        }
        chats.appendTurn(characterId: characterId, role: .user, text: submittedText, mediaIds: mediaIds, now: DateFormats.now())
        guard saveProjectCharacterChats(chats, for: project) else { return }
        touchCurrentProject()

        let renderStack = stack ?? resolvedCharacterSheetStack(for: character)
        do {
            let client = try OpenAIClient.fromEnvironment()
            let current = projectCharacters.character(withId: characterId) ?? character
            let activeSheet = activeCharacterSheetItem(for: characterId)
            let promptState = renderStack.map { characterSheetPromptState(for: current, stack: $0) }
            let renderedPrompt = promptState?.effective ?? ""
            let identity = goalCastMember(forCharacterId: characterId, name: current.name)?.activeIdentity
            let identityLines = identity.map { identity in
                [("who they are", identity.essence), ("role", identity.publicFunction), ("wants", identity.desire), ("tell", identity.signature)]
                    .filter { !$0.1.trimmed.isEmpty }
                    .map { "\($0.0): \($0.1.trimmed)" }
                    .joined(separator: "; ")
            } ?? ""
            let sourceIds = Array(current.referenceMediaIds.prefix(8))
            let visionIds = uniqueNonEmpty([activeSheet?.mediaId].compactMap { $0 } + mediaIds + sourceIds)
            let visionInputs = try goalVisionInputs(mediaIds: Array(visionIds.prefix(6)))
            let recent = (chats.thread(for: characterId)?.turns ?? [])
                .suffix(12)
                .map { "\($0.role == .user ? "User" : "Assistant"): \($0.text)" }
                .joined(separator: "\n")
            let context = CharacterSheetRefineContext(
                projectId: project.projectId,
                projectName: project.name,
                characterName: current.name,
                visualDescription: current.descriptionPrompt,
                signatureProps: current.signatureProps,
                storyIdentityLines: identityLines,
                currentDirectives: current.sheetDirectives,
                renderedSheetPrompt: renderedPrompt,
                sourceImageLines: selectedGoalMediaSummary(mediaIds: sourceIds),
                hasActiveSheet: activeSheet != nil,
                recentTurnsSummary: recent,
                userMessage: submittedText,
                generatedAt: DateFormats.now(),
                promptIsHandEdited: promptState?.isHandEdited ?? false
            )
            let result = try await client.refineCharacterSheet(context: context, visionInputs: visionInputs)
            guard currentProject?.projectId == project.projectId else { return }
            let response = result.response

            var changed = false
            let description = response.visualDescription.trimmed
            if !description.isEmpty, description != current.descriptionPrompt {
                changed = renameCharacter(characterId: characterId, name: current.name, descriptionPrompt: description) || changed
            }
            let props = uniqueNonEmpty(response.signatureProps)
            if !props.isEmpty, props != current.signatureProps {
                changed = setCharacterSignatureProps(characterId: characterId, props) || changed
            }
            let directives = uniqueNonEmpty(response.sheetDirectives)
            if directives != current.sheetDirectives {
                changed = setCharacterSheetDirectives(characterId: characterId, directives) || changed
            }
            for note in response.sourceImageNotes where !note.label.trimmed.isEmpty {
                guard let latest = projectCharacters.character(withId: characterId),
                      latest.referenceMediaIds.contains(note.mediaId),
                      (latest.referenceLabels[note.mediaId] ?? "").isEmpty else { continue }
                _ = setCharacterReferenceLabel(characterId: characterId, mediaId: note.mediaId, label: note.label.trimmed)
            }

            var reply = response.assistantMessage.trimmed.isEmpty ? "Noted." : response.assistantMessage.trimmed
            if !response.changeSummary.trimmed.isEmpty {
                reply += "\n\n" + response.changeSummary.trimmed
            }
            var updatedChats = projectCharacterChats
            updatedChats.appendTurn(characterId: characterId, role: .assistant, text: reply, now: DateFormats.now())
            _ = saveProjectCharacterChats(updatedChats, for: project)

            let latest = projectCharacters.character(withId: characterId)
            let decision = CharacterChatAutoRender.decision(
                name: current.name,
                changed: changed,
                rendersAfterChat: latest?.rendersSheetAfterChat ?? true,
                hasOverride: latest?.hasSheetPromptOverride ?? false,
                hasStack: renderStack != nil,
                stackBlocker: renderStack.flatMap { renderStackCredentialBlocker(for: $0) },
                isBusy: isGeneratingCharacterSheet || isGeneratingCharacterRender
            )
            characterChatStatus = decision.status
            guard case .render = decision, let renderStack else { return }
            // The conversation turn is done; the render is its own paid gesture.
            refiningCharacterIds.remove(characterId)
            _ = await startCharacterSheetRender(characterId: characterId, stack: renderStack)
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            lastError = goalInterviewFailureMessage(for: error)
            characterChatStatus = goalInterviewFailureStatus(for: error)
        }
    }

    // MARK: - Project object roster

    @discardableResult
    func createObject(name: String, descriptionPrompt: String = "") -> ProjectObject? {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return nil
        }
        let trimmedName = name.trimmed
        guard projectObjects.nameIsAvailable(trimmedName) else {
            aestheticStatus = trimmedName.isEmpty ? "Object name cannot be empty" : "An object named \"\(trimmedName)\" already exists"
            return nil
        }
        let now = DateFormats.now()
        let object = ProjectObject(
            objectId: "object_\(shortHash("\(project.projectId):\(trimmedName):\(now)", length: 12))",
            name: trimmedName,
            descriptionPrompt: descriptionPrompt,
            updatedAt: now
        ).normalized()
        var updated = projectObjects
        updated.projectId = project.projectId
        updated.objects.append(object)
        updated.updatedAt = now
        guard saveProjectObjects(updated, for: project, status: "Created object \(trimmedName)") else { return nil }
        return object
    }

    @discardableResult
    func renameObject(objectId: String, name: String, descriptionPrompt: String? = nil) -> Bool {
        guard let project = currentProject else { return false }
        guard var object = projectObjects.object(withId: objectId) else {
            aestheticStatus = "Object not found"
            return false
        }
        let trimmedName = name.trimmed
        guard projectObjects.nameIsAvailable(trimmedName, excludingObjectId: objectId) else {
            aestheticStatus = trimmedName.isEmpty ? "Object name cannot be empty" : "An object named \"\(trimmedName)\" already exists"
            return false
        }
        object.name = trimmedName
        if let descriptionPrompt {
            object.descriptionPrompt = descriptionPrompt
        }
        object.updatedAt = DateFormats.now()
        var updated = projectObjects
        updated.objects = updated.objects.map { $0.objectId == objectId ? object.normalized() : $0 }
        updated.updatedAt = object.updatedAt
        return saveProjectObjects(updated, for: project, status: "Updated object \(trimmedName)")
    }

    /// Replaces an object's ordered reference media (organized in the roster UI).
    @discardableResult
    func setObjectReferenceMedia(objectId: String, mediaIds: [String]) -> Bool {
        guard let project = currentProject else { return false }
        guard var object = projectObjects.object(withId: objectId) else {
            aestheticStatus = "Object not found"
            return false
        }
        let knownMediaIds = Set(items.map(\.mediaId))
        object.referenceMediaIds = uniqueNonEmpty(mediaIds).filter { knownMediaIds.contains($0) }
        object.updatedAt = DateFormats.now()
        var updated = projectObjects
        updated.objects = updated.objects.map { $0.objectId == objectId ? object.normalized() : $0 }
        updated.updatedAt = object.updatedAt
        guard saveProjectObjects(updated, for: project, status: "Updated \(object.name) references") else { return false }
        refreshObjectCompositeSheetIfPresent(objectId: objectId)
        return true
    }

    /// Sets (or clears, with an empty label) the organizational label on one of an
    /// object's reference images.
    @discardableResult
    func setObjectReferenceLabel(objectId: String, mediaId: String, label: String) -> Bool {
        guard let project = currentProject else { return false }
        guard var object = projectObjects.object(withId: objectId) else {
            aestheticStatus = "Object not found"
            return false
        }
        guard object.referenceMediaIds.contains(mediaId) else {
            aestheticStatus = "That image is not a \(object.name) reference"
            return false
        }
        let trimmed = label.trimmed
        if trimmed.isEmpty {
            object.referenceLabels.removeValue(forKey: mediaId)
        } else {
            object.referenceLabels[mediaId] = trimmed
        }
        object.updatedAt = DateFormats.now()
        var updated = projectObjects
        updated.objects = updated.objects.map { $0.objectId == objectId ? object.normalized() : $0 }
        updated.updatedAt = object.updatedAt
        guard saveProjectObjects(
            updated,
            for: project,
            status: trimmed.isEmpty ? "Cleared a \(object.name) reference label" : "Labeled \(object.name) reference \"\(trimmed)\""
        ) else { return false }
        refreshObjectCompositeSheetIfPresent(objectId: objectId)
        return true
    }

    // MARK: - Roster composite reference sheets

    /// Guards the sheet-refresh hooks against re-entering while a build is already
    /// appending/labeling the sheet it just produced.
    private var compositeSheetRebuildsInFlight: Set<String> = []
    /// Single-flight guard for the project sheet set: refresh triggers fire
    /// from saveLensSet, so a build that itself archives media must never
    /// recurse into another build.
    private var projectSheetBuildInFlight = false

    /// Builds (or rebuilds) a character's composite reference sheet — up to 4 of their
    /// references on one labeled contact sheet — imported as derived media and appended
    /// to their references. One sheet per character: deterministic mediaId + stable
    /// file path, so rebuilds update the image in place and keep any slot position.
    @discardableResult
    func buildCharacterCompositeSheet(characterId: String) async -> MediaItemRecord? {
        guard let project = currentProject else { return nil }
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return nil
        }
        let rebuildKey = "character:\(characterId)"
        compositeSheetRebuildsInFlight.insert(rebuildKey)
        defer { compositeSheetRebuildsInFlight.remove(rebuildKey) }
        guard let item = await buildRosterCompositeSheetMedia(
            project: project,
            entryId: characterId,
            name: character.name,
            referenceMediaIds: character.referenceMediaIds,
            referenceLabels: character.referenceLabels
        ) else { return nil }
        if let current = projectCharacters.character(withId: characterId), !current.referenceMediaIds.contains(item.mediaId) {
            _ = setCharacterReferenceMedia(characterId: characterId, mediaIds: current.referenceMediaIds + [item.mediaId])
            _ = setCharacterReferenceLabel(characterId: characterId, mediaId: item.mediaId, label: "reference sheet")
        }
        aestheticStatus = "Built \(character.name)'s reference sheet"
        return item
    }

    /// Object counterpart of buildCharacterCompositeSheet.
    @discardableResult
    func buildObjectCompositeSheet(objectId: String) async -> MediaItemRecord? {
        guard let project = currentProject else { return nil }
        guard let object = projectObjects.object(withId: objectId) else {
            aestheticStatus = "Object not found"
            return nil
        }
        let rebuildKey = "object:\(objectId)"
        compositeSheetRebuildsInFlight.insert(rebuildKey)
        defer { compositeSheetRebuildsInFlight.remove(rebuildKey) }
        guard let item = await buildRosterCompositeSheetMedia(
            project: project,
            entryId: objectId,
            name: object.name,
            referenceMediaIds: object.referenceMediaIds,
            referenceLabels: object.referenceLabels
        ) else { return nil }
        if let current = projectObjects.object(withId: objectId), !current.referenceMediaIds.contains(item.mediaId) {
            _ = setObjectReferenceMedia(objectId: objectId, mediaIds: current.referenceMediaIds + [item.mediaId])
            _ = setObjectReferenceLabel(objectId: objectId, mediaId: item.mediaId, label: "reference sheet")
        }
        aestheticStatus = "Built \(object.name)'s reference sheet"
        return item
    }

    /// The roster entry's existing composite sheet, if one is among its references.
    func rosterCompositeSheetItem(referenceMediaIds: [String]) -> MediaItemRecord? {
        referenceMediaIds
            .compactMap { mediaId in items.first { $0.mediaId == mediaId } }
            .first { $0.isRosterCompositeSheet && FileManager.default.fileExists(atPath: $0.path) }
    }

    /// The references eligible as sheet panels: on-disk images, excluding the sheet
    /// itself (a sheet never composes into itself).
    func rosterCompositeSheetSourceCount(referenceMediaIds: [String]) -> Int {
        referenceMediaIds
            .compactMap { mediaId in items.first { $0.mediaId == mediaId } }
            .filter { $0.kind == .image && !$0.isRosterCompositeSheet && FileManager.default.fileExists(atPath: $0.path) }
            .count
    }

    private func buildRosterCompositeSheetMedia(
        project: ProjectRecord,
        entryId: String,
        name: String,
        referenceMediaIds: [String],
        referenceLabels: [String: String]
    ) async -> MediaItemRecord? {
        let sources = referenceMediaIds
            .compactMap { mediaId in items.first { $0.mediaId == mediaId } }
            .filter { $0.kind == .image && !$0.isRosterCompositeSheet && FileManager.default.fileExists(atPath: $0.path) }
            .prefix(RosterCompositeSheet.maxCells)
        guard sources.count >= 2 else {
            aestheticStatus = "Add at least 2 reference images to build \(name)'s sheet"
            return nil
        }
        let cells = sources.compactMap { item -> (image: NSImage, caption: String)? in
            guard let image = NSImage(contentsOfFile: item.path) else { return nil }
            return (image, referenceLabels[item.mediaId] ?? "")
        }
        guard cells.count >= 2, let png = RosterCompositeSheet.renderPNG(title: name, cells: cells) else {
            aestheticStatus = "Could not compose \(name)'s reference sheet"
            return nil
        }
        do {
            let directory = contextStore.aestheticProofDirectory(for: project)
            try ensureDirectory(directory)
            let fileURL = directory.appendingPathComponent("roster_sheet_\(safeIdentifier(entryId)).png")
            try png.write(to: fileURL)
            return await archiveGeneratedMedia(
                fileURL: fileURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):roster_sheet:\(entryId)", length: 20))",
                derivativeKind: MediaItemRecord.rosterCompositeSheetDerivativeKind,
                sourceMediaId: entryId,
                filename: generatedMediaArchiveFilename(base: "\(name) Reference Sheet", path: fileURL.path, fallbackExtension: "png"),
                tags: ["generated", "roster-sheet"],
                notes: "Composite reference sheet built from \(name)'s references.",
                rejectedByDefault: true
            )
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save \(name)'s reference sheet"
            return nil
        }
    }

    /// Keeps an existing sheet current: when an entry's references or labels change
    /// and a sheet is already among them, rebuild its image in place (same mediaId and
    /// path — no roster write, so no save loop).
    private func refreshCharacterCompositeSheetIfPresent(characterId: String) {
        guard !compositeSheetRebuildsInFlight.contains("character:\(characterId)") else { return }
        guard let character = projectCharacters.character(withId: characterId),
              rosterCompositeSheetItem(referenceMediaIds: character.referenceMediaIds) != nil,
              rosterCompositeSheetSourceCount(referenceMediaIds: character.referenceMediaIds) >= 2 else { return }
        Task { @MainActor [weak self] in
            _ = await self?.buildCharacterCompositeSheet(characterId: characterId)
        }
    }

    private func refreshObjectCompositeSheetIfPresent(objectId: String) {
        guard !compositeSheetRebuildsInFlight.contains("object:\(objectId)") else { return }
        guard let object = projectObjects.object(withId: objectId),
              rosterCompositeSheetItem(referenceMediaIds: object.referenceMediaIds) != nil,
              rosterCompositeSheetSourceCount(referenceMediaIds: object.referenceMediaIds) >= 2 else { return }
        Task { @MainActor [weak self] in
            _ = await self?.buildObjectCompositeSheet(objectId: objectId)
        }
    }

    // MARK: - Project sheets

    /// Builds (or rebuilds in place) the project's defining sheet set — Cover /
    /// Style / Cast / Frames composites plus the JSON re-composition manifest.
    /// Stable file paths and deterministic mediaIds make rebuilds overwrite;
    /// sheets whose inputs are empty are skipped. No provider calls — every
    /// panel is drawn locally from what the project already holds.
    @discardableResult
    func buildProjectSheets() async -> [MediaItemRecord] {
        guard let project = currentProject else { return [] }
        guard !projectSheetBuildInFlight else { return [] }
        projectSheetBuildInFlight = true
        defer { projectSheetBuildInFlight = false }

        let lens = projectLenses.lenses.first
        let body = lens?.body.normalized()
        let storyEntry = storyLibrary.preferredEntry
        let storySignature = storyEntry.flatMap { entry in
            storySignatures.first { $0.storySignatureId == entry.storySignatureId }
                ?? (entry.projectStoryId.trimmed.isEmpty
                    ? nil
                    : storySignatures.first { $0.projectStoryId == entry.projectStoryId })
        }
        let storyTitle = storyEntry.map { entry in
            entry.title.trimmed.isEmpty ? (storySignature?.title ?? "") : entry.title
        } ?? ""

        var archived: [MediaItemRecord] = []
        var manifest = ProjectSheetManifest()
        manifest.projectId = project.projectId
        manifest.projectTitle = project.name
        manifest.generatedAt = DateFormats.now()
        manifest.storyTitle = storyTitle
        manifest.storyPremise = storySignature?.premise ?? ""

        if let body {
            manifest.claim = body.claim
            manifest.visualSummary = body.visualSummary
            manifest.motifTerms = body.motifTerms
            manifest.textureMaterialTerms = body.textureMaterialTerms
            manifest.compositionTerms = body.compositionTerms
            manifest.pacingEnergyTerms = body.pacingEnergyTerms
            manifest.mustPreserve = body.mustPreserve
            manifest.mustAvoid = body.mustAvoid
            manifest.goalSliceTitle = body.goalSliceTitle ?? ""
            manifest.paletteSwatches = uniqueLensColorSwatches(body.colorPalette).map {
                ProjectSheetManifest.PaletteSwatch(name: $0.name, hex: $0.hex)
            }
            manifest.styleIngredients = body.styleIngredients.filter(\.enabled).map {
                ProjectSheetManifest.StyleIngredientRef(ingredientId: $0.ingredientId, title: $0.title, role: $0.role)
            }
        }
        manifest.cast = projectCharacters.characters.map {
            ProjectSheetManifest.CastRef(characterId: $0.characterId, name: $0.name, referenceMediaIds: $0.referenceMediaIds)
        }

        // COVER — text-led: claim, look, terms, palette, story/slice footer.
        if let body, body.hasDraftContent {
            var cover = ProjectSheet.CoverContent()
            cover.projectTitle = project.name
            cover.claim = body.claim
            cover.visualSummary = body.visualSummary
            cover.termLines = [
                ("Motifs", body.motifTerms),
                ("Texture", body.textureMaterialTerms),
                ("Composition", body.compositionTerms),
                ("Pacing", body.pacingEnergyTerms)
            ]
            cover.palette = uniqueLensColorSwatches(body.colorPalette).map { ($0.name, $0.hex) }
            cover.storyTitle = storyTitle
            cover.goalSliceTitle = body.goalSliceTitle ?? ""
            if let png = ProjectSheet.renderCoverPNG(content: cover),
               let item = await archiveProjectSheetPNG(png, kind: .cover, project: project) {
                archived.append(item)
            }
        }

        // STYLE — the style anchors actually stamped on this project's frames.
        if let lens {
            var seenStyleKeys: Set<String> = []
            var styleCells: [(image: NSImage, caption: String)] = []
            for authority in lens.sortedHeroImages.flatMap(\.styleAuthorities) {
                let path = authority.imagePath.trimmed
                guard !path.isEmpty, FileManager.default.fileExists(atPath: path) else { continue }
                let key = authority.title.trimmed.isEmpty ? path : authority.title.trimmed
                guard !seenStyleKeys.contains(key) else { continue }
                guard let image = NSImage(contentsOfFile: path) else { continue }
                seenStyleKeys.insert(key)
                styleCells.append((image, authority.title))
                if styleCells.count >= ProjectSheet.maxGridCells { break }
            }
            if let item = await buildProjectGridSheet(project: project, kind: .style, cells: styleCells) {
                archived.append(item)
            }
        }

        // CAST — one panel per roster character: its composite sheet when one
        // exists, else the leading on-disk reference.
        var castCells: [(image: NSImage, caption: String)] = []
        for character in projectCharacters.characters {
            let sourceItem = rosterCompositeSheetItem(referenceMediaIds: character.referenceMediaIds)
                ?? character.referenceMediaIds
                    .compactMap { mediaId in items.first { $0.mediaId == mediaId } }
                    .first { $0.kind == .image && FileManager.default.fileExists(atPath: $0.path) }
            guard let sourceItem, let image = NSImage(contentsOfFile: sourceItem.path) else { continue }
            castCells.append((image, character.name))
            if castCells.count >= ProjectSheet.maxGridCells { break }
        }
        if let item = await buildProjectGridSheet(project: project, kind: .cast, cells: castCells) {
            archived.append(item)
        }

        // FRAMES — the newest media version's ready renders (fall back to any
        // ready frame so an older-version project still gets a sheet).
        if let lens {
            let newestVersion = lens.mediaVersionIds.last ?? ""
            // Adopted photos are sources, not renders — they never sit on the sheet.
            var frameImages = lens.heroImages(mediaVersion: newestVersion)
                .filter { $0.status == "ready" && !$0.imagePath.trimmed.isEmpty && !$0.isAdoptedPhoto }
            if frameImages.isEmpty {
                frameImages = lens.readyHeroImages.filter { !$0.isAdoptedPhoto }
            }
            var frameCells: [(image: NSImage, caption: String)] = []
            for frame in frameImages {
                guard FileManager.default.fileExists(atPath: frame.imagePath),
                      let image = NSImage(contentsOfFile: frame.imagePath) else { continue }
                frameCells.append((image, frame.label))
                if frameCells.count >= ProjectSheet.maxGridCells { break }
            }
            manifest.frames = frameImages.map {
                ProjectSheetManifest.FrameRef(imageId: $0.imageId, label: $0.label, sourcePrompt: $0.sourcePrompt)
            }
            if let item = await buildProjectGridSheet(project: project, kind: .frames, cells: frameCells) {
                archived.append(item)
            }
        }

        guard !archived.isEmpty else {
            aestheticStatus = "Nothing to compose into project sheets yet"
            return []
        }

        manifest.sheets = archived.map { item in
            ProjectSheetManifest.SheetRef(
                kind: projectSheetKind(forMediaId: item.mediaId, project: project)?.rawValue ?? "",
                mediaId: item.mediaId,
                filename: URL(fileURLWithPath: item.path).lastPathComponent
            )
        }
        do {
            let directory = contextStore.aestheticProofDirectory(for: project)
            try ensureDirectory(directory)
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            try encoder.encode(manifest).write(to: directory.appendingPathComponent("project_sheet_manifest.json"))
        } catch {
            lastError = "Project sheet manifest save failed: \(error.localizedDescription)"
        }
        aestheticStatus = "Built \(archived.count) project sheet\(archived.count == 1 ? "" : "s")"
        return archived
    }

    /// Rebuilds the sheet set in place, but only when one already exists — the
    /// set is opt-in via its first explicit build, then stays current as the
    /// Scene Plan and its renders evolve (fired from saveLensSet).
    func refreshProjectSheetsIfPresent() {
        guard !projectSheetBuildInFlight else { return }
        guard currentProject != nil else { return }
        guard items.contains(where: { $0.isProjectSheet }) else { return }
        Task { @MainActor [weak self] in
            _ = await self?.buildProjectSheets()
        }
    }

    var hasProjectSheets: Bool {
        items.contains { $0.isProjectSheet }
    }

    func projectSheetItems() -> [MediaItemRecord] {
        ProjectSheet.Kind.allCases.compactMap { kind in
            guard let project = currentProject else { return nil }
            let mediaId = projectSheetMediaId(kind: kind, project: project)
            return items.first { $0.mediaId == mediaId && FileManager.default.fileExists(atPath: $0.path) }
        }
    }

    private func projectSheetMediaId(kind: ProjectSheet.Kind, project: ProjectRecord) -> String {
        "genmedia_\(shortHash("\(project.projectId):project_sheet:\(kind.rawValue)", length: 20))"
    }

    private func projectSheetKind(forMediaId mediaId: String, project: ProjectRecord) -> ProjectSheet.Kind? {
        ProjectSheet.Kind.allCases.first { projectSheetMediaId(kind: $0, project: project) == mediaId }
    }

    private func buildProjectGridSheet(
        project: ProjectRecord,
        kind: ProjectSheet.Kind,
        cells: [(image: NSImage, caption: String)]
    ) async -> MediaItemRecord? {
        guard !cells.isEmpty,
              let png = ProjectSheet.renderGridPNG(kind: kind, title: project.name, cells: cells) else { return nil }
        return await archiveProjectSheetPNG(png, kind: kind, project: project)
    }

    private func archiveProjectSheetPNG(_ png: Data, kind: ProjectSheet.Kind, project: ProjectRecord) async -> MediaItemRecord? {
        do {
            let directory = contextStore.aestheticProofDirectory(for: project)
            try ensureDirectory(directory)
            let fileURL = directory.appendingPathComponent("project_sheet_\(kind.rawValue).png")
            try png.write(to: fileURL)
            return await archiveGeneratedMedia(
                fileURL: fileURL,
                project: project,
                mediaId: projectSheetMediaId(kind: kind, project: project),
                derivativeKind: MediaItemRecord.projectSheetDerivativeKind,
                sourceMediaId: nil,
                filename: generatedMediaArchiveFilename(base: "\(project.name) \(kind.displayName)", path: fileURL.path, fallbackExtension: "png"),
                tags: ["generated", "project-sheet"],
                notes: "\(kind.displayName): part of the project's defining sheet set.",
                rejectedByDefault: true
            )
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save the \(kind.displayName)"
            return nil
        }
    }

    /// Deletes a roster object. Objects have no lens links, so this is a plain removal.
    @discardableResult
    func deleteObject(objectId: String) -> Bool {
        guard let project = currentProject else { return false }
        guard let object = projectObjects.object(withId: objectId) else {
            aestheticStatus = "Object not found"
            return false
        }
        var updated = projectObjects
        updated.objects.removeAll { $0.objectId == objectId }
        updated.updatedAt = DateFormats.now()
        return saveProjectObjects(updated, for: project, status: "Deleted object \(object.name)")
    }

    @discardableResult
    private func saveProjectObjects(_ document: ProjectObjectSetDocument, for project: ProjectRecord, status: String) -> Bool {
        do {
            let normalized = document.normalized()
            try contextStore.saveProjectObjects(normalized, for: project)
            projectObjects = normalized
            aestheticStatus = status
            lastError = ""
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save objects"
            return false
        }
    }

    // MARK: - Project place roster

    @discardableResult
    func createPlace(name: String, descriptionPrompt: String = "") -> ProjectPlace? {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return nil
        }
        let trimmedName = name.trimmed
        guard projectPlaces.nameIsAvailable(trimmedName) else {
            aestheticStatus = trimmedName.isEmpty ? "Place name cannot be empty" : "A place named \"\(trimmedName)\" already exists"
            return nil
        }
        let now = DateFormats.now()
        let place = ProjectPlace(
            placeId: "place_\(shortHash("\(project.projectId):\(trimmedName):\(now)", length: 12))",
            name: trimmedName,
            descriptionPrompt: descriptionPrompt,
            updatedAt: now
        ).normalized()
        var updated = projectPlaces
        updated.projectId = project.projectId
        updated.places.append(place)
        updated.updatedAt = now
        guard saveProjectPlaces(updated, for: project, status: "Created place \(trimmedName)") else { return nil }
        return place
    }

    @discardableResult
    func renamePlace(placeId: String, name: String, descriptionPrompt: String? = nil) -> Bool {
        guard let project = currentProject else { return false }
        guard var place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "Place not found"
            return false
        }
        let trimmedName = name.trimmed
        guard projectPlaces.nameIsAvailable(trimmedName, excludingPlaceId: placeId) else {
            aestheticStatus = trimmedName.isEmpty ? "Place name cannot be empty" : "A place named \"\(trimmedName)\" already exists"
            return false
        }
        place.name = trimmedName
        if let descriptionPrompt {
            place.descriptionPrompt = descriptionPrompt
        }
        place.updatedAt = DateFormats.now()
        var updated = projectPlaces
        updated.places = updated.places.map { $0.placeId == placeId ? place.normalized() : $0 }
        updated.updatedAt = place.updatedAt
        return saveProjectPlaces(updated, for: project, status: "Updated place \(trimmedName)")
    }

    /// Replaces a place's ordered reference media (organized in the roster UI).
    @discardableResult
    func setPlaceReferenceMedia(placeId: String, mediaIds: [String]) -> Bool {
        guard let project = currentProject else { return false }
        guard var place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "Place not found"
            return false
        }
        let knownMediaIds = Set(items.map(\.mediaId))
        place.referenceMediaIds = uniqueNonEmpty(mediaIds).filter { knownMediaIds.contains($0) }
        place.updatedAt = DateFormats.now()
        var updated = projectPlaces
        updated.places = updated.places.map { $0.placeId == placeId ? place.normalized() : $0 }
        updated.updatedAt = place.updatedAt
        guard saveProjectPlaces(updated, for: project, status: "Updated \(place.name) references") else { return false }
        refreshPlaceCompositeSheetIfPresent(placeId: placeId)
        return true
    }

    /// Sets (or clears, with an empty label) the organizational label on one of a
    /// place's reference images.
    @discardableResult
    func setPlaceReferenceLabel(placeId: String, mediaId: String, label: String) -> Bool {
        guard let project = currentProject else { return false }
        guard var place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "Place not found"
            return false
        }
        guard place.referenceMediaIds.contains(mediaId) else {
            aestheticStatus = "That image is not a \(place.name) reference"
            return false
        }
        let trimmed = label.trimmed
        if trimmed.isEmpty {
            place.referenceLabels.removeValue(forKey: mediaId)
        } else {
            place.referenceLabels[mediaId] = trimmed
        }
        place.updatedAt = DateFormats.now()
        var updated = projectPlaces
        updated.places = updated.places.map { $0.placeId == placeId ? place.normalized() : $0 }
        updated.updatedAt = place.updatedAt
        guard saveProjectPlaces(
            updated,
            for: project,
            status: trimmed.isEmpty ? "Cleared a \(place.name) reference label" : "Labeled \(place.name) reference \"\(trimmed)\""
        ) else { return false }
        refreshPlaceCompositeSheetIfPresent(placeId: placeId)
        return true
    }

    /// Place counterpart of buildCharacterCompositeSheet.
    @discardableResult
    func buildPlaceCompositeSheet(placeId: String) async -> MediaItemRecord? {
        guard let project = currentProject else { return nil }
        guard let place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "Place not found"
            return nil
        }
        let rebuildKey = "place:\(placeId)"
        compositeSheetRebuildsInFlight.insert(rebuildKey)
        defer { compositeSheetRebuildsInFlight.remove(rebuildKey) }
        guard let item = await buildRosterCompositeSheetMedia(
            project: project,
            entryId: placeId,
            name: place.name,
            referenceMediaIds: place.referenceMediaIds,
            referenceLabels: place.referenceLabels
        ) else { return nil }
        if let current = projectPlaces.place(withId: placeId), !current.referenceMediaIds.contains(item.mediaId) {
            _ = setPlaceReferenceMedia(placeId: placeId, mediaIds: current.referenceMediaIds + [item.mediaId])
            _ = setPlaceReferenceLabel(placeId: placeId, mediaId: item.mediaId, label: "reference sheet")
        }
        aestheticStatus = "Built \(place.name)'s reference sheet"
        return item
    }

    private func refreshPlaceCompositeSheetIfPresent(placeId: String) {
        guard !compositeSheetRebuildsInFlight.contains("place:\(placeId)") else { return }
        guard let place = projectPlaces.place(withId: placeId),
              rosterCompositeSheetItem(referenceMediaIds: place.referenceMediaIds) != nil,
              rosterCompositeSheetSourceCount(referenceMediaIds: place.referenceMediaIds) >= 2 else { return }
        Task { @MainActor [weak self] in
            _ = await self?.buildPlaceCompositeSheet(placeId: placeId)
        }
    }

    /// Deletes a roster place. The lens keeps its areas; only the roster entry (and
    /// its reference organization) goes away.
    @discardableResult
    func deletePlace(placeId: String) -> Bool {
        guard let project = currentProject else { return false }
        guard let place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "Place not found"
            return false
        }
        var updated = projectPlaces
        updated.places.removeAll { $0.placeId == placeId }
        updated.updatedAt = DateFormats.now()
        return saveProjectPlaces(updated, for: project, status: "Deleted place \(place.name)")
    }

    @discardableResult
    private func saveProjectPlaces(_ document: ProjectPlaceSetDocument, for project: ProjectRecord, status: String) -> Bool {
        do {
            let normalized = document.normalized()
            try contextStore.saveProjectPlaces(normalized, for: project)
            projectPlaces = normalized
            aestheticStatus = status
            lastError = ""
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save places"
            return false
        }
    }

    // MARK: - Terrain map

    /// The single start law for terrain growth. nil = a pass may start; the
    /// UI binds the string to disabled-with-help buttons.
    var terrainMapGrowStartBlockReason: String? {
        if isGenerationPaused { return "Generation is paused — resume to grow the map" }
        if isGeneratingTerrainSeed { return "The seed map is still rendering" }
        if isGrowingTerrainMap { return "A growth pass is already running" }
        if !terrainMap.isSeeded { return "Seed the map first" }
        return nil
    }

    /// The current map canvas as a live Library item, or nil when the map is
    /// unseeded OR its media has been deleted from the Library — the repair
    /// state the view surfaces (the document is never silently cleared).
    var terrainMapCanvasItem: MediaItemRecord? {
        guard terrainMap.isSeeded else { return nil }
        guard let item = items.first(where: { $0.mediaId == terrainMap.currentMediaId }),
              FileManager.default.fileExists(atPath: item.path) else {
            return nil
        }
        return item
    }

    /// The one write funnel for the terrain map document: normalizes, prunes
    /// pins whose place left the roster (normalization can't see the places
    /// document; the funnel can), persists, publishes.
    @discardableResult
    private func saveTerrainMap(_ document: TerrainMapDocument, for project: ProjectRecord, status: String) -> Bool {
        do {
            var normalized = document.normalized()
            let knownPlaceIds = Set(projectPlaces.places.map(\.placeId))
            normalized.pins = normalized.pins.filter { knownPlaceIds.contains($0.placeId) }
            normalized.updatedAt = DateFormats.now()
            try contextStore.saveTerrainMap(normalized, for: project)
            terrainMap = normalized
            aestheticStatus = status
            lastError = ""
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save the world map"
            return false
        }
    }

    @discardableResult
    func setTerrainMapGrowthPrompt(_ prompt: String) -> Bool {
        guard let project = currentProject else { return false }
        var document = terrainMap
        document.growthPrompt = prompt.trimmed
        return saveTerrainMap(document, for: project, status: "World map prompt saved")
    }

    /// Upserts a pin, preserving an existing pin's region and descriptor.
    @discardableResult
    func setTerrainMapPin(placeId: String, x: Double, y: Double) -> Bool {
        guard let project = currentProject else { return false }
        guard let place = projectPlaces.place(withId: placeId) else {
            aestheticStatus = "That place is no longer in the roster"
            return false
        }
        var document = terrainMap
        if var pin = document.pin(forPlaceId: placeId) {
            pin.x = x
            pin.y = y
            pin.updatedAt = DateFormats.now()
            document.pins = document.pins.map { $0.placeId == placeId ? pin : $0 }
        } else {
            document.pins.append(TerrainMapPin(placeId: placeId, x: x, y: y))
        }
        guard saveTerrainMap(document, for: project, status: "Pinned \(place.name) on the world map") else { return false }
        Task { @MainActor [weak self] in
            _ = await self?.refreshTerrainMapRegionCrop(placeId: placeId)
        }
        return true
    }

    @discardableResult
    func setTerrainMapPinRegion(placeId: String, width: Double, height: Double) -> Bool {
        guard let project = currentProject else { return false }
        guard var pin = terrainMap.pin(forPlaceId: placeId) else { return false }
        pin.regionWidth = width
        pin.regionHeight = height
        pin.updatedAt = DateFormats.now()
        var document = terrainMap
        document.pins = document.pins.map { $0.placeId == placeId ? pin : $0 }
        guard saveTerrainMap(document, for: project, status: "World map region updated") else { return false }
        Task { @MainActor [weak self] in
            _ = await self?.refreshTerrainMapRegionCrop(placeId: placeId)
        }
        return true
    }

    @discardableResult
    func setTerrainMapPinDescriptor(placeId: String, descriptor: String) -> Bool {
        guard let project = currentProject else { return false }
        guard var pin = terrainMap.pin(forPlaceId: placeId) else { return false }
        pin.descriptor = descriptor
        pin.updatedAt = DateFormats.now()
        var document = terrainMap
        document.pins = document.pins.map { $0.placeId == placeId ? pin : $0 }
        guard saveTerrainMap(document, for: project, status: "World map note saved") else { return false }
        Task { @MainActor [weak self] in
            _ = await self?.refreshTerrainMapRegionCrop(placeId: placeId)
        }
        return true
    }

    @discardableResult
    func removeTerrainMapPin(placeId: String) -> Bool {
        guard let project = currentProject else { return false }
        var document = terrainMap
        document.pins.removeAll { $0.placeId == placeId }
        guard saveTerrainMap(document, for: project, status: "Pin removed from the world map") else { return false }
        stripTerrainRegionReferences(forPlaceIds: [placeId])
        return true
    }

    /// Seeds (or re-seeds) the map from an existing Library image. Re-seeding
    /// starts a new world: pins clear (their geography no longer exists), the
    /// growth prompt survives, and the UI confirms before calling this.
    @discardableResult
    func seedTerrainMapFromMedia(mediaId: String) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGrowingTerrainMap, !isGeneratingTerrainSeed else {
            aestheticStatus = "The world map is busy"
            return false
        }
        guard let item = items.first(where: { $0.mediaId == mediaId }), item.kind == .image,
              !item.path.trimmed.isEmpty,
              FileManager.default.fileExists(atPath: item.path) else {
            aestheticStatus = "This image is unavailable to seed the map"
            return false
        }
        do {
            let source = try LensHeroImageRunner.zoomOutSource(path: item.path)
            try ensureDirectory(contextStore.terrainMapDirectory(for: project))
            let now = DateFormats.now()
            let runId = "terrain_seed_\(shortHash("\(project.projectId):\(item.mediaId):\(now)", length: 14))"
            let outputURL = contextStore.terrainMapDirectory(for: project).appendingPathComponent("\(runId).png")
            try pngData(from: source.image).write(to: outputURL)
            guard let archived = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):terrain_map:\(runId)", length: 20))",
                derivativeKind: MediaItemRecord.terrainMapDerivativeKind,
                sourceMediaId: item.mediaId,
                filename: generatedMediaArchiveFilename(base: "World Map", path: outputURL.path, fallbackExtension: "png"),
                tags: ["generated", "terrain-map"],
                notes: "Terrain map seeded from \(item.filename).",
                rejectedByDefault: false
            ) else {
                aestheticStatus = "Could not archive the world map"
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            // A new world invalidates every old region crop; leaving them
            // would quietly keep feeding renders dead geography.
            stripTerrainRegionReferences(forPlaceIds: terrainMap.pins.map(\.placeId))
            var document = TerrainMapDocument.empty(projectId: project.projectId)
            document.growthPrompt = terrainMap.growthPrompt
            document.currentMediaId = archived.mediaId
            document.canvasWidth = source.width
            document.canvasHeight = source.height
            document.revisions = [TerrainMapRevision(
                revisionId: "",
                mediaId: archived.mediaId,
                operation: TerrainMapRevision.seedOperation,
                canvasWidth: source.width,
                canvasHeight: source.height,
                at: now
            )]
            return saveTerrainMap(document, for: project, status: "World map seeded")
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "Could not seed the world map"
            return false
        }
    }

    /// Generates a fresh top-down seed map from a prompt (the media-restyle
    /// skeleton minus the attachment), then commits it like a media seed.
    @discardableResult
    func generateTerrainSeed(prompt rawPrompt: String) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGrowingTerrainMap, !isGeneratingTerrainSeed else {
            aestheticStatus = "The world map is busy"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard let stack = terrainFillStack else {
            aestheticStatus = "Terrain fill needs an OpenAI outpaint-capable render stack"
            return false
        }
        let provider = stack.heroProvider
        let now = DateFormats.now()
        let runId = "terrain_seed_\(shortHash("\(project.projectId):\(now)", length: 14))"
        let outputURL = contextStore.terrainMapDirectory(for: project).appendingPathComponent("\(runId).png")
        // The fixed top-down preamble is the law for this surface; enrichment
        // could rewrite it, so the composed prompt rides as-is.
        let wirePrompt = TerrainMapPrompt.seedWirePrompt(operatorPrompt: rawPrompt)
        let job = LensHeroGenerationJob(
            lensId: "",
            imageId: runId,
            provider: provider,
            stack: stack,
            styleMode: .none,
            promptImageReferenceMode: false,
            sourceImageCount: 0,
            usesCompositeImage: false,
            skipPromptEnrichment: true,
            prompt: wirePrompt,
            sourcePrompt: wirePrompt,
            negativePrompt: "",
            attachments: [],
            attachmentManifest: "",
            attachmentManifestEntries: "",
            imageSize: LensMediaPlan().imageSize,
            stabilityAspectRatio: LensMediaPlan().stabilityAspectRatio,
            mediaPlan: LensMediaPlan(),
            transparentBackground: false,
            civitaiSeed: nil,
            outputURL: outputURL,
            projectId: project.projectId,
            runId: runId,
            workflowName: "terrain_map_seed"
        )

        isGeneratingTerrainSeed = true
        defer { isGeneratingTerrainSeed = false }
        aestheticStatus = "Rendering the seed map — \(stack.label)"

        do {
            try ensureDirectory(contextStore.terrainMapDirectory(for: project))
            let client = try OpenAIClient.fromEnvironment()
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore),
                civitaiImageProvider: nil,
                falImageClient: nil
            )
            guard currentProject?.projectId == project.projectId else { return false }
            // This path bypasses the frame funnel, so the ledger row lives
            // here — unpriced-never-$0, cancels never ledger.
            if outcome.status == "ready" || outcome.status == "failed" {
                recordSpend(SpendLedgerEntry(
                    kind: "image",
                    provider: outcome.provider.rawValue,
                    model: outcome.renderRecipe?.model ?? "",
                    requestId: outcome.requestId.trimmed,
                    traceId: outcome.traceId,
                    contextLabel: "World map seed",
                    imageId: runId,
                    unit: "images",
                    unitCount: 1,
                    pricingNote: outcome.renderRecipe?.parameters
                        .first { $0.key == "provider_price_note" }?.value ?? "",
                    status: outcome.status == "ready" ? "completed" : "failed_unknown_charge"
                ))
            }
            guard outcome.status == "ready" else {
                lastError = outcome.errorMessage
                aestheticStatus = "Seed map \(outcome.status)"
                return false
            }
            let rendered = try LensHeroImageRunner.zoomOutSource(path: outputURL.path)
            guard let archived = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):terrain_map:\(runId)", length: 20))",
                derivativeKind: MediaItemRecord.terrainMapDerivativeKind,
                sourceMediaId: nil,
                filename: generatedMediaArchiveFilename(base: "World Map", path: outputURL.path, fallbackExtension: "png"),
                tags: ["generated", "terrain-map"],
                notes: "Terrain map seeded from a prompt.",
                rejectedByDefault: false
            ) else {
                aestheticStatus = "Could not archive the world map"
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            // A new world invalidates every old region crop; leaving them
            // would quietly keep feeding renders dead geography.
            stripTerrainRegionReferences(forPlaceIds: terrainMap.pins.map(\.placeId))
            var document = TerrainMapDocument.empty(projectId: project.projectId)
            document.growthPrompt = terrainMap.growthPrompt
            document.currentMediaId = archived.mediaId
            document.canvasWidth = rendered.width
            document.canvasHeight = rendered.height
            document.revisions = [TerrainMapRevision(
                revisionId: "",
                mediaId: archived.mediaId,
                operation: TerrainMapRevision.seedOperation,
                canvasWidth: rendered.width,
                canvasHeight: rendered.height,
                at: now
            )]
            return saveTerrainMap(document, for: project, status: "World map seeded")
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "Seed map failed"
            return false
        }
    }

    /// One growth pass: masked outpaint of the chosen edge on the current
    /// canvas, seam-harmonized, with the original pixels re-stamped so N
    /// passes never N-times re-render the seeded world. OpenAI-only: the FAL
    /// outpaint path is recorded broken (bad images despite 200s + a silent
    /// 1024px downscale), so terrain never rides it.
    @discardableResult
    func growTerrainMap(direction: TerrainGrowthDirection) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        if let reason = terrainMapGrowStartBlockReason {
            aestheticStatus = reason
            return false
        }
        guard let canvasItem = terrainMapCanvasItem else {
            aestheticStatus = "The map canvas is missing from the Library — re-seed or revert"
            return false
        }
        guard let stack = terrainFillStack else {
            aestheticStatus = "Terrain fill needs an OpenAI outpaint-capable render stack"
            return false
        }

        isGrowingTerrainMap = true
        defer { isGrowingTerrainMap = false }
        aestheticStatus = "Growing the world map — \(direction.label.lowercased())"

        do {
            let source = try LensHeroImageRunner.zoomOutSource(path: canvasItem.path)
            guard let plan = TerrainMapGeometry.growthPlan(
                canvasWidth: source.width,
                canvasHeight: source.height,
                direction: direction
            ) else {
                aestheticStatus = "The map is at its \(TerrainMapGeometry.maxCanvasLongEdge)px ceiling on that side"
                return false
            }
            let prepared = try LensHeroImageRunner.openAIOutpaintInput(source: source, plan: plan.providerPlan)
            let wirePrompt = TerrainMapPrompt.openAIWirePrompt(operatorPrompt: terrainMap.growthPrompt)
            let now = DateFormats.now()
            let runId = "terrain_grow_\(shortHash("\(project.projectId):\(terrainMap.currentMediaId):\(now)", length: 14))"
            let revisionId = "terrainrev_\(shortHash("\(runId)", length: 12))"
            try ensureDirectory(contextStore.terrainMapDirectory(for: project))
            let client = try OpenAIClient.fromEnvironment()
            let result: OpenAIImageGenerationResult
            do {
                result = try await client.generateImageEdit(
                    prompt: wirePrompt,
                    sources: [prepared.source],
                    mask: prepared.mask,
                    model: stack.model,
                    size: prepared.plan.sizeString,
                    quality: "medium",
                    outputFormat: "png",
                    projectId: project.projectId,
                    runId: runId,
                    traceWorkflowName: "terrain_map",
                    traceWorkflowStep: "terrain_grow_openai",
                    traceArtifactType: "terrain_map",
                    traceArtifactId: revisionId
                )
            } catch {
                // A thrown edit has no request id; the charge is unknowable.
                recordSpend(SpendLedgerEntry(
                    kind: "image",
                    provider: "openai",
                    model: stack.model,
                    requestId: "",
                    traceId: "",
                    contextLabel: "World map growth",
                    imageId: runId,
                    unit: "images",
                    unitCount: 1,
                    pricingNote: stack.priceNote,
                    status: "failed_unknown_charge"
                ))
                throw error
            }
            recordSpend(SpendLedgerEntry(
                kind: "image",
                provider: "openai",
                model: stack.model,
                requestId: result.requestId.trimmed,
                traceId: result.traceId,
                contextLabel: "World map growth",
                imageId: runId,
                unit: "images",
                unitCount: 1,
                pricingNote: stack.priceNote,
                status: "completed"
            ))
            let composed = try LensHeroImageRunner.terrainGrowthComposite(
                generatedData: result.imageData,
                source: source,
                plan: plan
            )
            await InferenceTraceStore.shared.enrich(
                traceId: result.traceId,
                parsedOutputJSON: inferenceTraceJSONString([
                    "operation": "terrain_grow",
                    "direction": direction.rawValue,
                    "composite": composed.composite,
                    "perimeter_match": composed.perimeterMatch,
                    "prior_content_rect": [
                        "x": plan.priorContentRect.minX,
                        "y": plan.priorContentRect.minY,
                        "width": plan.priorContentRect.width,
                        "height": plan.priorContentRect.height
                    ],
                    "new_canvas_width": plan.newCanvasWidth,
                    "new_canvas_height": plan.newCanvasHeight
                ])
            )
            let outputURL = contextStore.terrainMapDirectory(for: project).appendingPathComponent("\(runId).png")
            try composed.data.write(to: outputURL)
            guard let archived = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):terrain_map:\(runId)", length: 20))",
                derivativeKind: MediaItemRecord.terrainMapDerivativeKind,
                sourceMediaId: terrainMap.currentMediaId,
                filename: generatedMediaArchiveFilename(base: "World Map", path: outputURL.path, fallbackExtension: "png"),
                tags: ["generated", "terrain-map"],
                notes: "World map grown \(direction.label.lowercased()).",
                rejectedByDefault: false
            ) else {
                aestheticStatus = "Could not archive the grown map"
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            var document = terrainMap
            let pinsBeforeGrowth = document.pins
            document.currentMediaId = archived.mediaId
            document.canvasWidth = plan.newCanvasWidth
            document.canvasHeight = plan.newCanvasHeight
            document.pins = pinsBeforeGrowth.map {
                TerrainMapGeometry.remappedPin($0, throughPriorContentRect: plan.priorContentRect)
            }
            document.revisions.append(TerrainMapRevision(
                revisionId: revisionId,
                mediaId: archived.mediaId,
                operation: TerrainMapRevision.growOperation,
                direction: direction.rawValue,
                canvasWidth: plan.newCanvasWidth,
                canvasHeight: plan.newCanvasHeight,
                priorContentRectX: plan.priorContentRect.minX,
                priorContentRectY: plan.priorContentRect.minY,
                priorContentRectWidth: plan.priorContentRect.width,
                priorContentRectHeight: plan.priorContentRect.height,
                pinsSnapshot: pinsBeforeGrowth,
                at: now
            ))
            guard saveTerrainMap(document, for: project, status: "World map grew \(direction.label.lowercased())") else {
                return false
            }
            refreshTerrainMapRegionReferences()
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "World map growth failed"
            return false
        }
    }

    /// One-step revert of the newest growth pass: repoints at the previous
    /// canvas (already archived media) and restores the pins exactly as they
    /// stood before that growth, from the revision's snapshot.
    @discardableResult
    func revertTerrainMapLastGrowth() -> Bool {
        guard let project = currentProject else { return false }
        guard !isGrowingTerrainMap, !isGeneratingTerrainSeed else {
            aestheticStatus = "The world map is busy"
            return false
        }
        guard terrainMap.revisions.count >= 2,
              let last = terrainMap.revisions.last,
              last.operation == TerrainMapRevision.growOperation else {
            aestheticStatus = "There is no growth pass to revert"
            return false
        }
        let previous = terrainMap.revisions[terrainMap.revisions.count - 2]
        guard let item = items.first(where: { $0.mediaId == previous.mediaId }),
              FileManager.default.fileExists(atPath: item.path) else {
            aestheticStatus = "The previous map canvas is no longer in the Library"
            return false
        }
        var document = terrainMap
        document.revisions.removeLast()
        document.currentMediaId = previous.mediaId
        document.canvasWidth = previous.canvasWidth
        document.canvasHeight = previous.canvasHeight
        document.pins = last.pinsSnapshot
        guard saveTerrainMap(document, for: project, status: "Reverted the last growth") else { return false }
        refreshTerrainMapRegionReferences()
        return true
    }

    /// The one stack terrain fill runs on: OpenAI's outpaint-capable stack.
    private var terrainFillStack: RenderStack? {
        renderStacks.first {
            $0.heroProvider == .openAI && $0.supportsReframe(mode: LensReframeSpec.zoomOutMode)
        }
    }

    /// The deterministic media id for a place's map-region crop: one id per
    /// (project, place), so every refresh upserts the same Library item (the
    /// project-sheet precedent) instead of accumulating stale crops.
    static func terrainRegionMediaId(projectId: String, placeId: String) -> String {
        "genmedia_\(shortHash("\(projectId):terrain_region:\(placeId)", length: 20))"
    }

    /// Rebuilds one pinned place's map-region crop and rides it into the
    /// place's reference media — appended at the END (operator ordering is
    /// meaningful) under the "world map region" label, which also refreshes
    /// the place's composite sheet. Free and local: zero provider calls.
    /// This is how the map feeds generation: the crop travels everywhere
    /// place references already travel (@mentions, composite sheets).
    @discardableResult
    func refreshTerrainMapRegionCrop(placeId: String) async -> Bool {
        guard let project = currentProject else { return false }
        guard let pin = terrainMap.pin(forPlaceId: placeId),
              let place = projectPlaces.place(withId: placeId),
              let canvasItem = terrainMapCanvasItem else {
            return false
        }
        do {
            let source = try LensHeroImageRunner.zoomOutSource(path: canvasItem.path)
            guard let regionRect = TerrainMapGeometry.regionPixelRect(
                pin: pin,
                canvasWidth: source.width,
                canvasHeight: source.height
            ), let cropped = source.image.cropping(to: regionRect) else {
                return false
            }
            try ensureDirectory(contextStore.terrainMapDirectory(for: project))
            let mediaId = Self.terrainRegionMediaId(projectId: project.projectId, placeId: placeId)
            let outputURL = contextStore.terrainMapDirectory(for: project)
                .appendingPathComponent("region_\(safeIdentifier(placeId)).png")
            try pngData(from: cropped).write(to: outputURL)
            let descriptorNote = TerrainMapPrompt.regionReferenceDescriptor(
                placeName: place.name,
                descriptor: pin.descriptor
            )
            guard let archived = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: mediaId,
                derivativeKind: MediaItemRecord.terrainMapRegionDerivativeKind,
                sourceMediaId: terrainMap.currentMediaId,
                filename: generatedMediaArchiveFilename(
                    base: "\(place.name) World Map Region",
                    path: outputURL.path,
                    fallbackExtension: "png"
                ),
                tags: ["generated", "terrain-map-region"],
                notes: descriptorNote,
                rejectedByDefault: false
            ) else {
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            // The archive funnel only writes notes when they are empty; a
            // moved pin or edited note must stay current here.
            updateCuration(mediaId: archived.mediaId) { $0.notes = descriptorNote }
            if let current = projectPlaces.place(withId: placeId),
               !current.referenceMediaIds.contains(archived.mediaId) {
                _ = setPlaceReferenceMedia(
                    placeId: placeId,
                    mediaIds: current.referenceMediaIds + [archived.mediaId]
                )
                _ = setPlaceReferenceLabel(
                    placeId: placeId,
                    mediaId: archived.mediaId,
                    label: "world map region"
                )
            } else {
                // Same id, new bytes: the sheet still needs a rebuild.
                refreshPlaceCompositeSheetIfPresent(placeId: placeId)
            }
            return true
        } catch {
            lastError = error.localizedDescription
            return false
        }
    }

    /// Refreshes every pinned place's region crop — after a growth commit
    /// (all geography moved), a pin edit, or a revert.
    func refreshTerrainMapRegionReferences() {
        let placeIds = terrainMap.pins.map(\.placeId)
        guard !placeIds.isEmpty, terrainMapCanvasItem != nil else { return }
        Task { @MainActor [weak self] in
            for placeId in placeIds {
                _ = await self?.refreshTerrainMapRegionCrop(placeId: placeId)
            }
        }
    }

    /// Removes the map-region crop from the given places' references (the
    /// pin is gone or the world was re-seeded — a stale crop would quietly
    /// keep feeding renders dead geography).
    private func stripTerrainRegionReferences(forPlaceIds placeIds: [String]) {
        guard let project = currentProject else { return }
        for placeId in placeIds {
            guard let place = projectPlaces.place(withId: placeId) else { continue }
            let cropId = Self.terrainRegionMediaId(projectId: project.projectId, placeId: placeId)
            guard place.referenceMediaIds.contains(cropId) else { continue }
            _ = setPlaceReferenceMedia(
                placeId: placeId,
                mediaIds: place.referenceMediaIds.filter { $0 != cropId }
            )
        }
    }

    // MARK: - Roster reference image sources

    /// The Frame Creator's mention vocabulary for one Scene. Current roster names
    /// remain canonical; names retained in structured Scene/Goal cast records become
    /// aliases for the same stable character id. This keeps planned prompts attached
    /// after a rename without rewriting historical creative artifacts. An alias that
    /// collides with any current roster name or points at multiple ids is omitted —
    /// attaching no reference is safer than attaching the wrong person.
    func frameCreatorMentionEntries(for lens: ProjectLens) -> [RosterMentionResolver.Entry] {
        let currentNames = Set(
            (
                projectCharacters.characters.map(\.name)
                    + projectObjects.objects.map(\.name)
                    + projectPlaces.places.map(\.name)
            )
            .map { $0.trimmed.lowercased() }
            .filter { !$0.isEmpty }
        )
        let characterIds = Set(projectCharacters.characters.map(\.characterId))
        var aliasOwners: [String: Set<String>] = [:]
        var aliasDisplayNames: [String: String] = [:]

        func claimAlias(characterId: String, name: String) {
            let trimmedId = characterId.trimmed
            let trimmedName = name.trimmed
            let key = trimmedName.lowercased()
            guard characterIds.contains(trimmedId), !key.isEmpty else { return }
            aliasOwners[key, default: []].insert(trimmedId)
            if aliasDisplayNames[key] == nil {
                aliasDisplayNames[key] = trimmedName
            }
        }

        for member in lens.body.castMembers ?? [] {
            claimAlias(characterId: member.characterId ?? "", name: member.name)
        }
        for member in goalCast.members {
            claimAlias(characterId: member.characterId, name: member.name)
        }

        let characterEntries = projectCharacters.characters.map { character in
            let aliases = aliasOwners.keys.sorted().compactMap { key -> String? in
                guard aliasOwners[key] == Set([character.characterId]),
                      !currentNames.contains(key),
                      key != character.name.trimmed.lowercased() else {
                    return nil
                }
                return aliasDisplayNames[key]
            }
            return RosterMentionResolver.Entry(
                id: character.characterId,
                name: character.name,
                kind: .character,
                aliases: aliases,
                referenceMediaIds: character.referenceMediaIds,
                referenceLabels: character.referenceLabels,
                activeSheetMediaId: character.activeSheetMediaId ?? ""
            )
        }
        let objectEntries = projectObjects.objects.map {
            RosterMentionResolver.Entry(
                id: $0.objectId,
                name: $0.name,
                kind: .object,
                referenceMediaIds: $0.referenceMediaIds,
                referenceLabels: $0.referenceLabels
            )
        }
        let placeEntries = projectPlaces.places.map {
            RosterMentionResolver.Entry(
                id: $0.placeId,
                name: $0.name,
                kind: .place,
                referenceMediaIds: $0.referenceMediaIds,
                referenceLabels: $0.referenceLabels
            )
        }
        return characterEntries + objectEntries + placeEntries
    }

    /// Opens an image picker and imports the chosen files as project media, returning
    /// the records so the roster can append their ids to a character/object bucket.
    func chooseRosterReferenceImages() async -> [MediaItemRecord] {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return []
        }

        let panel = NSOpenPanel()
        panel.title = "Upload Reference Images"
        panel.message = "Choose one or more images to use as reference media."
        panel.prompt = "Upload"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.canCreateDirectories = false
        panel.allowedContentTypes = [.image]

        guard panel.runModal() == .OK else { return [] }
        return await importGoalChatImageFiles(panel.urls, project: project)
    }

    /// Frame Creator's "Upload…": import image files from disk and hand the
    /// records straight back for attaching as references. Mirrors the roster
    /// upload; status rides the aesthetic line, not the Goal chat's.
    func chooseFrameReferenceImages() async -> [MediaItemRecord] {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return []
        }

        let panel = NSOpenPanel()
        panel.title = "Upload Reference Images"
        panel.message = "Choose one or more images to attach as references."
        panel.prompt = "Upload"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.canCreateDirectories = false
        panel.allowedContentTypes = [.image]

        guard panel.runModal() == .OK else { return [] }
        return await importGoalChatImageFiles(panel.urls, project: project, statusTarget: .aesthetic)
    }

    /// The RAW adoption row for one Media photo — disabled rows included, so the
    /// deterministic imageId is never minted twice. Placement and opening resolve
    /// through `adoptedPhotoFrame` instead. Provider + model are the identity
    /// law: a render that inherited the photo's dependency is not the photo.
    func mediaImageFrame(lensId: String, mediaId: String) -> ProjectLensHeroImage? {
        projectLenses.lenses
            .first { $0.lensId == lensId }?
            .heroImages
            .first { $0.adoptedPhotoMediaId == mediaId }
    }

    /// The placeable adoption of one Media photo: enabled rows only. Every
    /// placement path and the pool's open gesture resolve here; a deleted
    /// adoption stays invisible until its next use re-enables it.
    func adoptedPhotoFrame(lensId: String, mediaId: String) -> ProjectLensHeroImage? {
        guard let frame = mediaImageFrame(lensId: lensId, mediaId: mediaId), !frame.disabled else {
            return nil
        }
        return frame
    }

    /// Adopts a Media photo's actual pixels as a ready scenery Frame for the
    /// established Backlot → Stage → Cut workflow. No inference runs. The Frame
    /// owns a copy so hiding, moving, or later losing the source Media item does
    /// not invalidate an authored video input; the source dependency preserves
    /// where it came from.
    @discardableResult
    func addMediaImageAsFrame(_ item: MediaItemRecord, lensId: String) -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard item.kind == .image else {
            aestheticStatus = "Only photos can be added as Frames"
            return false
        }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        if let existing = mediaImageFrame(lensId: lensId, mediaId: item.mediaId) {
            guard existing.disabled else {
                aestheticStatus = "\(item.filename) is already a Frame"
                return true
            }
            // A deleted adoption comes back on its next use: the imageId is
            // deterministic, so re-enabling the row is the only correct repair.
            var heroImages = lens.sortedHeroImages
            guard let index = heroImages.firstIndex(where: { $0.imageId == existing.imageId }) else {
                aestheticStatus = "Could not restore \(item.filename) as a Frame"
                return false
            }
            heroImages[index].disabled = false
            heroImages[index].updatedAt = DateFormats.now()
            return saveLensHeroImages(
                heroImages,
                lensId: lensId,
                project: project,
                status: "Restored \(existing.label.trimmed.nilIfEmpty ?? item.filename) as a Frame",
                changeSummary: "Restored a Media photo's Frame."
            )
        }

        let sourcePath = item.path.trimmed
        guard !sourcePath.isEmpty, FileManager.default.fileExists(atPath: sourcePath) else {
            aestheticStatus = "The source photo is unavailable"
            return false
        }

        let sourceURL = URL(fileURLWithPath: sourcePath)
        let imageId = "lens_hero_\(shortHash("\(project.projectId):\(lensId):media_frame:\(item.mediaId)", length: 14))"
        let copyStem = "mediaframe_\(shortHash(imageId, length: 12))"
        let sourceExtension = sourceURL.pathExtension.trimmed.lowercased()
        let copyName = sourceExtension.isEmpty ? copyStem : "\(copyStem).\(sourceExtension)"
        let copyURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent(copyName)
        let copiedNow: Bool
        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            if FileManager.default.fileExists(atPath: copyURL.path) {
                copiedNow = false
            } else {
                try FileManager.default.copyItem(at: sourceURL, to: copyURL)
                copiedNow = true
            }
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not copy the photo into Frames"
            return false
        }

        let now = DateFormats.now()
        let label = sourceURL.deletingPathExtension().lastPathComponent.trimmed.nilIfEmpty
            ?? item.filename.trimmed.nilIfEmpty
            ?? "Photo"
        let prompt = mediaObservationsById[item.mediaId]?.plainCaption.trimmed.nilIfEmpty
            ?? curation(for: item).notes.trimmed.nilIfEmpty
            ?? label
        let versionId = lens.mediaVersionIds.last ?? ""
        let routeBase = "media_frame_\(shortHash(item.mediaId, length: 12))"
        let routeKey = versionId.isEmpty ? routeBase : "\(routeBase)@\(versionId)"
        var heroImages = lens.sortedHeroImages
        var frame = ProjectLensHeroImage(
            imageId: imageId,
            imageIndex: (heroImages.map(\.imageIndex).max() ?? -1) + 1,
            label: label,
            provider: ProjectLensHeroImage.adoptedPhotoProvider,
            model: ProjectLensHeroImage.adoptedPhotoModel,
            imagePath: copyURL.path,
            prompt: prompt,
            sourcePrompt: prompt,
            status: "ready",
            sourceRouteKey: routeKey,
            sourceDependencies: [
                LensRenderSourceDependency(
                    dependencyId: "",
                    kind: "media_item",
                    sourceId: item.mediaId,
                    required: true,
                    role: ProjectLensHeroImage.sourcePhotoDependencyRole,
                    label: item.filename,
                    imagePathOrUrl: sourcePath
                ).normalized(order: 0)
            ],
            imageKind: LensImageTaxonomyKind.sceneImage,
            generatedAt: now,
            updatedAt: now
        )
        frame.promptEnrichmentDisabled = true
        heroImages.append(frame.normalized())
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Added \(label) as a Frame",
            changeSummary: "Added a Media photo as a Frame."
        ) else {
            if copiedNow {
                try? FileManager.default.removeItem(at: copyURL)
            }
            return false
        }
        return true
    }

    /// The pool's open gesture and every Restyle-from-Media: the enabled adoption
    /// when one exists (silently), else adopt — re-enabling a deleted row or
    /// minting a fresh one — and hand the row back. nil means the refusal is
    /// already on the status line.
    @discardableResult
    func adoptMediaImageAsFrame(mediaId: String, lensId: String) -> ProjectLensHeroImage? {
        if let existing = adoptedPhotoFrame(lensId: lensId, mediaId: mediaId) {
            return existing
        }
        guard let item = items.first(where: { $0.mediaId == mediaId }) else {
            aestheticStatus = "That media item no longer exists"
            return nil
        }
        guard addMediaImageAsFrame(item, lensId: lensId) else { return nil }
        return adoptedPhotoFrame(lensId: lensId, mediaId: mediaId)
    }

    /// Adopts a generated lens frame as a first-class media item so it can serve as a
    /// roster reference. The deterministic mediaId keys on the frame's imageId, so
    /// re-selecting the same frame updates one record instead of duplicating it.
    /// Archived rejected-by-default: adopted frames stay out of the moodboard tray and
    /// the aesthetic-analysis queue. The image FILE is copied (the Frame Duplicate
    /// law): a reference must survive its source frame's trash, and a shared path
    /// would collapse the twins anywhere media dedupes by file. The copy destination
    /// is deterministic, so re-adopting reuses it.
    @discardableResult
    func archiveHeroFrameAsReference(_ hero: ProjectLensHeroImage) async -> MediaItemRecord? {
        guard let project = currentProject else { return nil }
        let path = hero.imagePath.trimmed
        guard !path.isEmpty else { return nil }
        let label = hero.label.trimmed
        let mediaId = "genmedia_\(shortHash("\(project.projectId):frame_reference:\(hero.imageId)", length: 20))"
        let sourceURL = URL(fileURLWithPath: path)
        let copyURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("ref_\(shortHash(mediaId, length: 12))_\(sourceURL.lastPathComponent)")
        if !FileManager.default.fileExists(atPath: copyURL.path) {
            do {
                try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                try FileManager.default.copyItem(at: sourceURL, to: copyURL)
            } catch {
                lastError = error.localizedDescription
                return nil
            }
        }
        return await archiveGeneratedMedia(
            fileURL: copyURL,
            project: project,
            mediaId: mediaId,
            derivativeKind: MediaItemRecord.frameReferenceDerivativeKind,
            sourceMediaId: hero.imageId,
            filename: generatedMediaArchiveFilename(
                base: label.isEmpty ? "Generated Frame" : label,
                path: copyURL.path,
                fallbackExtension: "png"
            ),
            tags: ["generated", "frame-reference"],
            notes: "Generated frame adopted as a roster reference (file copied — survives the source frame's trash).",
            rejectedByDefault: true
        )
    }

    /// Renders a NEW image of a roster character from the manage-character modal and
    /// appends it to their reference pool. Lens-free: no style treatment, no hero-image
    /// row — the written prompt (enriched at render) plus the character's own leading
    /// references as identity anchors are the whole recipe. Zero references render from
    /// text alone; the first accepted render then anchors the next one.
    @discardableResult
    func startCharacterReferenceRender(
        characterId: String,
        prompt rawPrompt: String,
        shot: RosterCharacterRenderPrompt.Shot,
        stack: RenderStack,
        references: CharacterStudyReferences? = nil
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGeneratingCharacterRender else {
            aestheticStatus = "A character reference render is already running"
            return false
        }
        guard !isGeneratingCharacterSheet else {
            aestheticStatus = "A character render is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        let trimmedPrompt = rawPrompt.trimmed
        guard !trimmedPrompt.isEmpty else {
            aestheticStatus = "Prompt is required to render a reference"
            lastError = aestheticStatus
            return false
        }

        characterRenderNotes.removeValue(forKey: characterId)
        let attachments: [LensPromptImageAttachment]
        if let references {
            // The STUDIO chose the references (sources and/or the active sheet) and
            // how to treat them; the study plan trims them to the stack's capacity.
            let activeSheetId = activeCharacterSheetItem(for: characterId)?.mediaId
            let offered = references.mediaIds.compactMap { mediaId -> CharacterStudyReference? in
                guard let item = items.first(where: { $0.mediaId == mediaId }) else { return nil }
                return CharacterStudyReference(
                    item: item,
                    label: character.referenceLabels[mediaId] ?? "",
                    isSheet: mediaId == activeSheetId
                )
            }
            let plan = CharacterStudyPrompt.plan(
                name: character.name,
                references: offered,
                look: references.look,
                capacity: stack.frameReferenceCapacity.planningCap,
                isStability: stack.isStability
            )
            attachments = plan.attachments.map { attachment in
                LensPromptImageAttachment(
                    source: .moodboardImage,
                    sourceId: attachment.mediaId,
                    label: attachment.label,
                    detail: attachment.detail,
                    imagePath: attachment.imagePath
                ).normalized()
            }
        } else {
            let referenced = character.referenceMediaIds.compactMap { mediaId in
                items.first { $0.mediaId == mediaId }
            }
            let picks = stack.reframeCapable
                ? RosterCharacterRenderPrompt.identityAnchorPicks(
                    referenced: referenced,
                    referenceLabels: character.referenceLabels,
                    capOne: stack.isFAL
                )
                : []
            attachments = picks.map { pick in
                LensPromptImageAttachment(
                    source: .moodboardImage,
                    sourceId: pick.item.mediaId,
                    label: pick.isSheet ? "\(character.name) — reference sheet" : character.name,
                    detail: RosterMentionResolver.characterStudyAttachmentDescriptor(
                        name: character.name,
                        label: pick.label,
                        isCompositeSheet: pick.isSheet
                    ),
                    imagePath: pick.item.path
                ).normalized()
            }
        }
        let provider = stack.heroProvider
        let now = DateFormats.now()
        let runId = "roster_char_render_\(shortHash("\(project.projectId):\(characterId):\(now)", length: 14))"
        let usesCompositeImage = stack.isStability && attachments.count > 1
        let providerAttachments: [LensPromptImageAttachment]
        if usesCompositeImage {
            let compositeURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("stability_reference_\(safeIdentifier(runId)).jpg")
            let cells = attachments.compactMap { attachment -> (image: NSImage, caption: String)? in
                guard let image = NSImage(contentsOfFile: attachment.imagePath) else { return nil }
                return (image, attachment.label)
            }
            guard cells.count == attachments.count,
                  let jpeg = RenderReferenceComposite.renderJPEG(title: "\(character.name) identity", cells: cells) else {
                aestheticStatus = "Could not compose \(character.name)'s Stability reference input"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .study, message: aestheticStatus)
                return false
            }
            do {
                try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                try jpeg.write(to: compositeURL, options: [.atomic])
            } catch {
                lastError = error.localizedDescription
                aestheticStatus = "Could not save \(character.name)'s Stability reference input"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .study, message: aestheticStatus)
                return false
            }
            providerAttachments = [
                LensPromptImageAttachment(
                    attachmentId: "stability_composite_\(runId)",
                    source: .moodboardImage,
                    sourceId: characterId,
                    label: "\(character.name) · labeled identity sheet",
                    detail: "COMPOSITE IDENTITY REFERENCE. Each labeled cell shows the same character. Preserve their shared identity while rendering one continuous final image, not a collage.",
                    imagePath: compositeURL.path
                ).normalized()
            ]
        } else {
            providerAttachments = attachments
        }
        let attachmentPlan = providerAttachments.isEmpty ? nil : lensPromptImageAttachmentPlan(providerAttachments)
        let outputExtension = provider == .openAI || stack.usesPNGOutput ? "png" : "jpg"
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(runId)_\(safeIdentifier(characterId)).\(outputExtension)")
        var mediaPlan = LensMediaPlan()
        mediaPlan.aspect = shot.aspect
        mediaPlan = mediaPlan.normalized()
        let job = LensHeroGenerationJob(
            lensId: "",
            imageId: runId,
            provider: provider,
            stack: stack,
            // FAL carries the identity image through its single reference slot,
            // which its client keys on .attachStyleImage + promptImageReferenceMode.
            styleMode: stack.isFAL && !attachments.isEmpty ? .attachStyleImage : .none,
            promptImageReferenceMode: !attachments.isEmpty,
            sourceImageCount: attachments.count,
            usesCompositeImage: usesCompositeImage,
            skipPromptEnrichment: false,
            prompt: trimmedPrompt,
            sourcePrompt: trimmedPrompt,
            negativePrompt: "",
            attachments: attachmentPlan?.entries ?? [],
            attachmentManifest: attachmentPlan?.manifestText ?? "",
            attachmentManifestEntries: attachmentPlan?.manifestEntryLinesText ?? "",
            // The shot preset decides the size here, never the stack: the
            // stack's landscape canvas is the FRAMES 16:9 policy — not the
            // roster's. OpenAI reads job.imageSize; CivitAI reorients its own
            // declared canvas through the override pair.
            imageSize: shot.openAIImageSize,
            stabilityAspectRatio: stack.isStability ? stack.stabilityAspectRatio : mediaPlan.stabilityAspectRatio,
            mediaPlan: mediaPlan,
            transparentBackground: true,
            civitaiSeed: provider == .civitaiWan27 ? Int.random(in: 1...Int(Int32.max)) : nil,
            civitaiWidthOverride: stack.civitaiDeclaredSize.map { shot.civitaiSize(declared: $0).width },
            civitaiHeightOverride: stack.civitaiDeclaredSize.map { shot.civitaiSize(declared: $0).height },
            outputURL: outputURL,
            projectId: project.projectId,
            runId: runId,
            workflowName: "roster_character_render"
        )

        isGeneratingCharacterRender = true
        activeCharacterRenderCharacterId = characterId
        defer {
            isGeneratingCharacterRender = false
            activeCharacterRenderCharacterId = ""
        }
        aestheticStatus = "Rendering \(character.name) reference — \(stack.label)"

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let needsOpenAIClient = provider == .openAI
                || ((provider == .fal || provider == .stability) && !job.skipPromptEnrichment)
            let client = needsOpenAIClient ? try OpenAIClient.fromEnvironment() : nil
            let stabilityClient = provider == .stability
                ? try StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
                : try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let civitaiImageProvider = provider == .civitaiWan27
                ? CivitAIWANImageProvider(credentialStore: videoCredentialStore)
                : nil
            let falImageClient = provider == .fal
                ? FALImageClient(credentialStore: videoCredentialStore)
                : nil
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider,
                falImageClient: falImageClient
            )
            guard currentProject?.projectId == project.projectId else { return false }
            // This lane bypasses the frame funnel, so its ledger row lives here —
            // unpriced-never-$0, the recipe's provider price note rides along.
            if outcome.status == "ready" || outcome.status == "failed" {
                recordSpend(SpendLedgerEntry(
                    kind: "image",
                    provider: outcome.provider.rawValue,
                    model: outcome.renderRecipe?.model ?? "",
                    requestId: outcome.requestId.trimmed,
                    traceId: outcome.traceId,
                    contextLabel: "\(character.name) reference study",
                    imageId: runId,
                    unit: "images",
                    unitCount: 1,
                    estimatedUSD: outcome.status == "ready"
                        ? estimatedImageUSD(endpointId: outcome.renderRecipe?.model ?? "", outputPath: outputURL.path)
                        : nil,
                    pricingNote: ledgerPricingNote(
                        endpointId: outcome.renderRecipe?.model ?? "",
                        fallback: outcome.renderRecipe?.parameters.first { $0.key == "provider_price_note" }?.value ?? ""
                    ),
                    status: outcome.status == "ready" ? "completed" : "failed_unknown_charge"
                ))
            }
            guard outcome.status == "ready" else {
                lastError = outcome.errorMessage
                aestheticStatus = "\(character.name) reference \(outcome.status)"
                characterRenderNotes[characterId] = CharacterRenderNote(
                    lane: .study,
                    message: outcome.errorMessage.trimmed.nilIfEmpty ?? "\(stack.label) returned \(outcome.status)"
                )
                return false
            }
            guard let item = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):roster_character_render:\(runId)", length: 20))",
                derivativeKind: MediaItemRecord.rosterCharacterRenderDerivativeKind,
                sourceMediaId: characterId,
                filename: generatedMediaArchiveFilename(
                    base: "\(character.name) \(shot.label.capitalized) Reference",
                    path: outputURL.path,
                    fallbackExtension: outputExtension
                ),
                tags: ["generated", "roster-reference", "character-render"],
                notes: "Generated \(character.name) reference from the roster.",
                rejectedByDefault: true
            ) else {
                aestheticStatus = "Could not archive \(character.name)'s reference render"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .study, message: aestheticStatus)
                return false
            }
            guard let current = projectCharacters.character(withId: characterId) else { return false }
            guard setCharacterReferenceMedia(
                characterId: characterId,
                mediaIds: current.referenceMediaIds + [item.mediaId]
            ) else { return false }
            aestheticStatus = "\(character.name) reference ready — added to their reference pool"
            characterRenderNotes.removeValue(forKey: characterId)
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "\(character.name) reference render failed"
            characterRenderNotes[characterId] = CharacterRenderNote(lane: .study, message: error.localizedDescription)
            return false
        }
    }

    /// Renders a character's reference sheet: the Settings template filled from the
    /// roster identity and the story cast, transmitted verbatim (no prompt transform),
    /// portrait, multi-panel by design, anchored on the active sheet or the source
    /// images. The result lands as character-sheet media and becomes the identity
    /// anchor for every later render of that character.
    @discardableResult
    func startCharacterSheetRender(characterId: String, stack requestedStack: RenderStack? = nil) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGeneratingCharacterSheet, !isGeneratingCharacterRender else {
            aestheticStatus = "A character render is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard var character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        guard !draftingCharacterIds.contains(characterId) else {
            aestheticStatus = "\(character.name) is being cast from the story"
            return false
        }
        guard let stack = requestedStack ?? resolvedCharacterSheetStack(for: character) else {
            aestheticStatus = "Add an API key in App Settings to render"
            return false
        }
        // One click, two steps: a blank identity is drafted from the story first; a
        // failed draft stops here, before anything is spent.
        let draftDecision = characterIdentityDraftDecision(for: character)
        characterRenderNotes.removeValue(forKey: characterId)
        if case .draft = draftDecision {
            guard await draftCharacterIdentity(characterId: characterId) else { return false }
            guard currentProject?.projectId == project.projectId,
                  !isGeneratingCharacterSheet, !isGeneratingCharacterRender,
                  let refreshed = projectCharacters.character(withId: characterId) else { return false }
            character = refreshed
        }

        let picks = characterSheetRenderPicks(for: character, stack: stack)
        let prompt = renderedCharacterSheetPrompt(for: character, stack: stack)
        let promptHash = CharacterSheetPrompt.promptHash(prompt)
        let attachesSheet = picks.contains(where: \.isSheet)
        let attachments = picks.map { pick -> LensPromptImageAttachment in
            let label: String
            let detail: String
            if pick.isSheet {
                label = "\(character.name) — reference sheet"
                detail = RosterMentionResolver.characterStudyAttachmentDescriptor(
                    name: character.name,
                    label: pick.label,
                    isCompositeSheet: false,
                    isCharacterSheet: true
                )
            } else {
                label = pick.label.isEmpty
                    ? "\(character.name) — source image"
                    : "\(character.name) — source image: \(pick.label)"
                detail = RosterMentionResolver.characterSheetSourceDescriptor(
                    name: character.name,
                    label: pick.label,
                    hasSheet: attachesSheet
                )
            }
            return LensPromptImageAttachment(
                source: .moodboardImage,
                sourceId: pick.item.mediaId,
                label: label,
                detail: detail,
                imagePath: pick.item.path
            ).normalized()
        }
        let provider = stack.heroProvider
        let now = DateFormats.now()
        let runId = "character_sheet_\(shortHash("\(project.projectId):\(characterId):\(now)", length: 14))"
        let usesCompositeImage = stack.isStability && attachments.count > 1
        let providerAttachments: [LensPromptImageAttachment]
        if usesCompositeImage {
            let compositeURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("stability_reference_\(safeIdentifier(runId)).jpg")
            let cells = attachments.compactMap { attachment -> (image: NSImage, caption: String)? in
                guard let image = NSImage(contentsOfFile: attachment.imagePath) else { return nil }
                return (image, attachment.label)
            }
            guard cells.count == attachments.count,
                  let jpeg = RenderReferenceComposite.renderJPEG(title: "\(character.name) identity", cells: cells) else {
                aestheticStatus = "Could not compose \(character.name)'s Stability reference input"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .sheet, message: aestheticStatus)
                return false
            }
            do {
                try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
                try jpeg.write(to: compositeURL, options: [.atomic])
            } catch {
                lastError = error.localizedDescription
                aestheticStatus = "Could not save \(character.name)'s Stability reference input"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .sheet, message: aestheticStatus)
                return false
            }
            providerAttachments = [
                LensPromptImageAttachment(
                    attachmentId: "stability_composite_\(runId)",
                    source: .moodboardImage,
                    sourceId: characterId,
                    label: "\(character.name) · labeled identity sheet",
                    detail: "COMPOSITE IDENTITY REFERENCE. Each labeled cell shows the same character. Preserve their shared identity in every panel of the sheet.",
                    imagePath: compositeURL.path
                ).normalized()
            ]
        } else {
            providerAttachments = attachments
        }
        let attachmentPlan = providerAttachments.isEmpty ? nil : lensPromptImageAttachmentPlan(providerAttachments)
        let outputExtension = provider == .openAI || stack.usesPNGOutput ? "png" : "jpg"
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(runId)_\(safeIdentifier(characterId)).\(outputExtension)")
        var mediaPlan = LensMediaPlan()
        mediaPlan.aspect = "portrait"
        mediaPlan = mediaPlan.normalized()
        let styleMode: LensRenderStyleMode = stack.isFAL && !attachments.isEmpty ? .attachStyleImage : .none
        let tallShot = RosterCharacterRenderPrompt.Shot.fullFigure
        let job = LensHeroGenerationJob(
            lensId: "",
            imageId: runId,
            provider: provider,
            stack: stack,
            styleMode: styleMode,
            debugParametersJSON: CharacterSheetPrompt.falParameterOverrides(stack: stack, styleMode: styleMode),
            promptImageReferenceMode: !attachments.isEmpty,
            sourceImageCount: attachments.count,
            usesCompositeImage: usesCompositeImage,
            // The template is the operator's exact text: no prompt transform.
            skipPromptEnrichment: true,
            prompt: prompt,
            sourcePrompt: prompt,
            negativePrompt: "",
            attachments: attachmentPlan?.entries ?? [],
            attachmentManifest: attachmentPlan?.manifestText ?? "",
            attachmentManifestEntries: attachmentPlan?.manifestEntryLinesText ?? "",
            imageSize: "1024x1536",
            stabilityAspectRatio: "2:3",
            mediaPlan: mediaPlan,
            transparentBackground: false,
            civitaiSeed: provider == .civitaiWan27 ? Int.random(in: 1...Int(Int32.max)) : nil,
            civitaiWidthOverride: stack.civitaiDeclaredSize.map { tallShot.civitaiSize(declared: $0).width },
            civitaiHeightOverride: stack.civitaiDeclaredSize.map { tallShot.civitaiSize(declared: $0).height },
            allowsMultiPanelLayout: true,
            stabilityAspectRatioOverride: stack.isStability ? "2:3" : nil,
            outputURL: outputURL,
            projectId: project.projectId,
            runId: runId,
            workflowName: "character_sheet"
        )

        isGeneratingCharacterSheet = true
        activeCharacterSheetCharacterId = characterId
        defer {
            isGeneratingCharacterSheet = false
            activeCharacterSheetCharacterId = ""
        }
        aestheticStatus = "Rendering \(character.name)'s character sheet — \(stack.label)"

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let client = provider == .openAI ? try OpenAIClient.fromEnvironment() : nil
            let stabilityClient = provider == .stability
                ? try StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
                : try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let civitaiImageProvider = provider == .civitaiWan27
                ? CivitAIWANImageProvider(credentialStore: videoCredentialStore)
                : nil
            let falImageClient = provider == .fal
                ? FALImageClient(credentialStore: videoCredentialStore)
                : nil
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider,
                falImageClient: falImageClient
            )
            guard currentProject?.projectId == project.projectId else { return false }
            // Bypasses the frame funnel, so the ledger row lives here —
            // unpriced-never-$0, the recipe's provider price note rides along.
            if outcome.status == "ready" || outcome.status == "failed" {
                recordSpend(SpendLedgerEntry(
                    kind: "image",
                    provider: outcome.provider.rawValue,
                    model: outcome.renderRecipe?.model ?? "",
                    requestId: outcome.requestId.trimmed,
                    traceId: outcome.traceId,
                    contextLabel: "\(character.name) character sheet",
                    imageId: runId,
                    unit: "images",
                    unitCount: 1,
                    estimatedUSD: outcome.status == "ready"
                        ? estimatedImageUSD(endpointId: outcome.renderRecipe?.model ?? "", outputPath: outputURL.path)
                        : nil,
                    pricingNote: ledgerPricingNote(
                        endpointId: outcome.renderRecipe?.model ?? "",
                        fallback: outcome.renderRecipe?.parameters.first { $0.key == "provider_price_note" }?.value ?? ""
                    ),
                    status: outcome.status == "ready" ? "completed" : "failed_unknown_charge"
                ))
            }
            guard outcome.status == "ready" else {
                lastError = outcome.errorMessage
                aestheticStatus = "\(character.name)'s character sheet \(outcome.status)"
                characterRenderNotes[characterId] = CharacterRenderNote(
                    lane: .sheet,
                    message: outcome.errorMessage.trimmed.nilIfEmpty ?? "\(stack.label) returned \(outcome.status)"
                )
                return false
            }
            guard let item = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):character_sheet:\(runId)", length: 20))",
                derivativeKind: MediaItemRecord.characterSheetDerivativeKind,
                sourceMediaId: characterId,
                filename: generatedMediaArchiveFilename(
                    base: "\(character.name) Character Sheet",
                    path: outputURL.path,
                    fallbackExtension: outputExtension
                ),
                tags: ["generated", "roster-reference", "character-sheet"],
                notes: "Generated \(character.name)'s character reference sheet.",
                rejectedByDefault: true
            ) else {
                aestheticStatus = "Could not archive \(character.name)'s character sheet"
                characterRenderNotes[characterId] = CharacterRenderNote(lane: .sheet, message: aestheticStatus)
                return false
            }
            characterRenderNotes.removeValue(forKey: characterId)
            let recorded = updateCharacter(characterId: characterId, status: "\(character.name)'s character sheet ready") {
                $0.recordRenderedSheet(mediaId: item.mediaId, promptHash: promptHash)
            }
            if recorded {
                // THE SHEET → SUGGESTIONS hook — unstructured on purpose: the
                // sheet lane returns (its defer clears the flags) before this
                // body runs; suggestions are text-only and never awaited here.
                Task { @MainActor [weak self] in
                    self?.recordCharacterFrameSuggestionAttempt(characterId: characterId)
                    await self?.suggestFramesForCharacter(characterId: characterId)
                }
            }
            return recorded
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            lastError = error.localizedDescription
            aestheticStatus = "\(character.name)'s character sheet render failed"
            characterRenderNotes[characterId] = CharacterRenderNote(lane: .sheet, message: error.localizedDescription)
            return false
        }
    }

    /// Rewrites browse-catalog `style_reference` ingredients to mirror the treatment slots
    /// so persisted provenance matches what generation attaches. SREF-card, media, and
    /// custom ingredients are left untouched. Generation does not depend on this (the
    /// attachment plan resolves slots itself); this keeps the stored Lens truthful.
    private func styleIngredientsResynced(
        _ ingredients: [LensStyleIngredient],
        treatment: LensStyleTreatment?
    ) async -> [LensStyleIngredient] {
        func isBrowseCatalogStyleIngredient(_ ingredient: LensStyleIngredient) -> Bool {
            guard ingredient.role == "style_reference", !ingredient.sourceReferenceIds.isEmpty else { return false }
            let decoded = ingredient.sourceReferenceIds.compactMap { SREFStyleImageReference.decodeSourceReferenceId($0) }
            return !decoded.isEmpty && decoded.allSatisfy { $0.catalogKind == "style_browse_catalog" }
        }

        let kept = ingredients.filter { !isBrowseCatalogStyleIngredient($0) }
        let replaced = ingredients.filter { isBrowseCatalogStyleIngredient($0) }
        guard let treatment, !treatment.isEmpty else { return kept }

        let catalog = try? await StyleBrowseCatalogRuntime.shared.loadCatalog()
        let now = DateFormats.now()
        var nextOrder = (kept.map(\.order).max() ?? 0) + 1
        var resynced: [LensStyleIngredient] = []
        for (index, slot) in treatment.slots.enumerated() {
            let roleLabel = index == 0 ? "Primary style" : "Accent style"
            if let catalog, catalog.isUsable,
               let style = catalog.style(withId: slot.styleId),
               let reference = style.styleImageReference(catalogVersion: catalog.version) {
                let collectionName = catalog.collections.first { $0.key == style.collection }?.name ?? slot.collection
                resynced.append(.styleCatalogReference(
                    style: style,
                    reference: reference,
                    roleLabel: roleLabel,
                    collectionName: collectionName,
                    order: nextOrder,
                    now: now
                ))
                nextOrder += 1
            } else if let existing = replaced.first(where: { ingredient in
                ingredient.sourceReferenceIds
                    .compactMap { SREFStyleImageReference.decodeSourceReferenceId($0) }
                    .contains { $0.itemId == slot.styleId }
            }) {
                var carried = existing
                carried.order = nextOrder
                carried.updatedAt = now
                resynced.append(carried)
                nextOrder += 1
            } else {
                print("[lens_treatment_resync] no reference for style_id=\(slot.styleId); ingredient omitted")
            }
        }
        return kept + resynced
    }

    @discardableResult
    func saveActiveScratchAsNewLens() -> Bool {
        guard let scratch = activeLensScratch else {
            aestheticStatus = "Create a scratch draft first"
            return false
        }
        return saveLensScratchAsNewLens(scratchId: scratch.scratchId) != nil
    }

    @discardableResult
    func saveLensScratchAsNewLens(scratchId: String) -> String? {
        guard let project = currentProject else { return nil }
        guard let scratch = projectLenses.scratchDrafts.first(where: { $0.scratchId == scratchId }) else {
            aestheticStatus = "Create a scratch draft first"
            return nil
        }
        let body = scratch.body.normalized()
        guard body.hasDraftContent else {
            aestheticStatus = "Add an aesthetic, title, note, or visual detail before saving"
            return nil
        }
        var updated = projectLenses
        let now = DateFormats.now()
        let theme = ProjectLens(
            lensId: "lens_\(shortHash("\(project.projectId):\(body.title):\(now)", length: 12))",
            status: .ready,
            enabled: true,
            body: body,
            relationSummary: .empty,
            createdAt: now,
            updatedAt: now
        )
        updated.appendVersion(
            lenses: updated.lenses + [theme],
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: theme.lensId,
            selectedScratchId: nil,
            changeSummary: "Saved scratch as new Scene Plan.",
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: "Saved as new Scene Plan") ? theme.lensId : nil
    }

    @discardableResult
    func generateLensHero(lensId: String) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard !isGeneratingLensHero else {
            aestheticStatus = "Frame generation already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard let theme = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }

        beginLensHeroWholeLensFlow(lensId: lensId)
        defer { endLensHeroWholeLensFlow() }

        let startedAt = DateFormats.now()
        let goalBrief = goalBriefForInitialLensGeneration(from: projectGoalV2.activeBrief)
        let mediaSummaries = aestheticMediaSummaryPackets(limit: 20)
        let prompt = lensHeroPrompt(theme: theme, goalBrief: goalBrief, mediaSummaries: mediaSummaries)
        let routeKey = "manual_lens_\(safeIdentifier(lensId))"
        let styleAuthorities = generatedTakeStyleAuthorities(lens: theme, catalog: nil)
        let heroImages = queuedLensHeroImages(
            lensId: lensId,
            routeKey: routeKey,
            recipe: nil,
            sourceAestheticIds: lensHeroSourceAestheticIds(theme),
            sourceReferenceIds: lensHeroSourceReferenceIds(theme),
            mediaPlan: theme.body.resolvedMediaPlan,
            styleAuthorities: styleAuthorities,
            prompt: prompt,
            now: startedAt
        ).map { image -> ProjectLensHeroImage in
            var value = image
            value.status = "generating"
            value.updatedAt = startedAt
            return value.normalized()
        }

        aestheticStatus = "Generating frames"
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Generating frames",
            changeSummary: "Started OpenAI and Stability frame generation."
        ) else {
            return false
        }

        let claimedHeroImageIds = heroImages.map(\.imageId)
        for imageId in claimedHeroImageIds {
            registerLensHeroWholeLensRowClaim(imageId: imageId)
        }
        defer {
            for imageId in claimedHeroImageIds {
                unregisterLensHeroTakeOperation(imageId: imageId)
            }
        }

        let proofRunId = "lens_manual_\(shortHash("\(project.projectId):\(lensId):\(startedAt)", length: 14))"

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let client = try OpenAIClient.fromEnvironment()
            let stabilityClient = try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            var manualLens = theme
            manualLens.heroImages = heroImages
            manualLens.heroImage = manualLens.primaryHeroImage
            let jobs = lensHeroGenerationJobs(for: [manualLens.normalized()], project: project, proofRunId: proofRunId, catalog: await styleBrowseCatalogForAttachmentFallback())
            var readyHeroSlots = 0
            var completedHeroSlots = 0
            var lastSlotErrorMessage = ""
            await withTaskGroup(of: LensHeroGenerationOutcome.self) { group in
                for job in jobs {
                    group.addTask {
                        await LensHeroImageRunner.generate(
                            job: job,
                            openAIClient: client,
                            stabilityClient: stabilityClient
                        )
                    }
                }
                for await outcome in group {
                    guard currentProject?.projectId == project.projectId else { continue }
                    completedHeroSlots += 1
                    if outcome.status == "ready" {
                        readyHeroSlots += 1
                    } else if outcome.status == "failed" {
                        lastSlotErrorMessage = outcome.errorMessage
                    }
                    let providerLabel = outcome.provider.label
                    let statusVerb = outcome.status == "ready" ? "ready" : outcome.status
                    _ = saveLensHeroImageOutcome(
                        outcome,
                        project: project,
                        status: "Frames \(readyHeroSlots)/\(jobs.count) ready",
                        changeSummary: "\(providerLabel) frame \(statusVerb)."
                    )
                    aestheticStatus = "Frames \(readyHeroSlots)/\(jobs.count) ready"
                }
            }
            guard currentProject?.projectId == project.projectId else { return false }
            if !lastSlotErrorMessage.isEmpty {
                lastError = lastSlotErrorMessage
            }
            if readyHeroSlots == jobs.count {
                aestheticStatus = "Frames ready"
            } else if readyHeroSlots > 0 {
                aestheticStatus = "Frames partially ready"
            } else if completedHeroSlots > 0 {
                aestheticStatus = "Frame generation failed"
            }
            return readyHeroSlots > 0
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let status = (Task.isCancelled || isCancellationLikeError(error)) ? "cancelled" : "failed"
            if Task.isCancelled || isCancellationLikeError(error) {
                aestheticStatus = "Frame generation cancelled"
            } else if case ScreenGraphError.missingAPIKey = error {
                aestheticStatus = "OPENAI_API_KEY is required to generate frames"
                lastError = error.localizedDescription
            } else {
                aestheticStatus = "Frame generation failed"
                lastError = error.localizedDescription
            }
            _ = markLensHeroImagesFailed(
                imageIds: claimedHeroImageIds,
                lensId: lensId,
                project: project,
                rowStatus: status,
                errorMessage: error.localizedDescription,
                status: aestheticStatus,
                changeSummary: "Frame generation \(status)."
            )
            return false
        }
    }

    @discardableResult
    func retryLensHeroImage(
        lensId: String,
        imageId: String,
        stack: RenderStack? = nil
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        if let reason = lensHeroTakeStartBlockReason {
            aestheticStatus = reason
            return false
        }
        guard let theme = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        if let stack, stack.isFAL || stack.isStability {
            return await startLensHeroImageSiblingRender(
                lensId: lensId,
                imageId: imageId,
                request: LensTakeRenderRequest(stack: stack, styleMode: .describeStyleInPrompt)
            )
        }
        var heroImages = theme.sortedHeroImages
        guard let heroIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Frame not found"
            return false
        }
        let existingImage = heroImages[heroIndex].normalized()
        if existingImage.status != "queued", existingImage.status != "generating" {
            let retryStack = stack ?? lensRenderStack(for: existingImage)
            return await startLensHeroImageSiblingRender(
                lensId: lensId,
                imageId: imageId,
                request: LensTakeRenderRequest(
                    stack: retryStack,
                    styleMode: lensRenderStyleMode(for: existingImage, stack: retryStack)
                )
            )
        }
        let provider: LensHeroImageProvider = stack?.heroProvider
            ?? LensHeroImageProvider(rawValue: existingImage.provider)
            ?? .openAI
        let actionLabel = existingImage.status == "queued" ? "Rendering" : "Retrying"
        let now = DateFormats.now()
        let retryIsCharacterStudy = LensConceptCategory.category(for: existingImage) == .characters
        let civitaiSeed = provider == .civitaiWan27 ? Int.random(in: 1...Int(Int32.max)) : nil
        var retryImage = existingImage
        retryImage.provider = provider.rawValue
        retryImage.model = provider.model
        retryImage.status = "generating"
        retryImage.imagePath = ""
        retryImage.requestId = ""
        retryImage.traceId = ""
        retryImage.errorMessage = ""
        retryImage.generatedAt = ""
        retryImage.prompt = retryImage.sourcePrompt.trimmed.isEmpty ? retryImage.prompt : retryImage.sourcePrompt
        retryImage.sourcePrompt = retryImage.sourcePrompt.trimmed.isEmpty ? retryImage.prompt : retryImage.sourcePrompt
        retryImage.negativePrompt = ""
        retryImage.promptEnrichmentModel = ""
        retryImage.promptEnrichmentResponseId = ""
        retryImage.promptEnrichmentTraceId = ""
        retryImage.promptEnrichmentSummary = ""
        retryImage.renderRecipe = provider.renderRecipeSnapshot(
            mediaPlan: theme.body.resolvedMediaPlan,
            isCharacterStudy: retryIsCharacterStudy,
            hasStyleReferences: provider == .openAI && !retryImage.styleAuthorities.isEmpty,
            seed: civitaiSeed
        )
        retryImage.updatedAt = now
        heroImages[heroIndex] = retryImage.normalized()

        // In-place retries claim the ROW's own id — a second retry of the
        // same stuck row refuses at the lane, not by racing the first.
        guard registerLensHeroTakeOperation(imageId: imageId, lensId: lensId) else {
            return false
        }
        defer { unregisterLensHeroTakeOperation(imageId: imageId) }

        aestheticStatus = "\(actionLabel) \(provider.label) frame"
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "\(actionLabel) \(provider.label) frame",
            changeSummary: "\(actionLabel) \(provider.label) frame."
        ) else {
            return false
        }

        let proofRunId = "lens_retry_\(shortHash("\(project.projectId):\(lensId):\(imageId):\(now)", length: 14))"
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(proofRunId)_\(safeIdentifier(lensId))_\(safeIdentifier(imageId)).\(provider == .openAI && retryIsCharacterStudy ? "png" : "jpg")")
        // A retried chain image regains the continuity its siblings already rendered:
        // ready images of the same media version with a lower composite index.
        let retryVersionId = ProjectLens.mediaVersionId(fromRouteKey: existingImage.sourceRouteKey)
        let retryAssignedStyleId = existingImage.sourceAestheticIds.first
        let retryChain: [LensConceptChainEntry] = existingImage.sourceRouteKey.hasPrefix("lens_media_")
            ? theme.heroImages(mediaVersion: retryVersionId)
                .filter { $0.status == "ready" && $0.imageIndex < existingImage.imageIndex && !$0.imagePath.trimmed.isEmpty }
                .sorted { $0.imageIndex < $1.imageIndex }
                .map {
                    LensConceptChainEntry(
                        styleId: $0.sourceAestheticIds.first ?? "",
                        category: LensConceptCategory.category(for: $0),
                        url: URL(fileURLWithPath: $0.imagePath)
                    )
                }
            : []
        let continuityURLs = lensConceptContinuityURLs(assignedStyleId: retryAssignedStyleId, chain: retryChain)
        let styleCatalog = await styleBrowseCatalogForAttachmentFallback()
        let renderLens = lensApplyingTakeStyleOverride(theme, image: existingImage)
        let retryCharacterScopeId = retryIsCharacterStudy
            ? lensResolvedTakeCharacterId(for: existingImage, lens: theme, cast: lensCompositeCast(for: theme))
            : ""
        let plan = provider == .openAI
            ? lensBlendAttachmentPlan(
                lens: renderLens,
                catalog: styleCatalog,
                assignedStyleId: existingImage.sourceAestheticIds.first,
                characterScopeId: retryCharacterScopeId,
                continuityURLs: continuityURLs
            )
            : LensBlendAttachmentPlan()
        let styleSummary = provider == .civitaiWan27
            ? takeStyleSummary(existingImage)
            : plan.styleSummaryText
        let job = LensHeroGenerationJob(
            lensId: lensId,
            imageId: imageId,
            provider: provider,
            skipPromptEnrichment: retryImage.promptEnrichmentDisabled,
            prompt: retryImage.prompt,
            sourcePrompt: retryImage.sourcePrompt,
            negativePrompt: retryImage.negativePrompt,
            attachments: plan.entries,
            promptPreamble: plan.promptPreamble,
            attachmentManifest: plan.manifestText,
            styleSummary: styleSummary,
            attachmentManifestEntries: plan.manifestEntryLinesText,
            attachmentStylePolicy: plan.manifestPolicyText,
            imageSize: stack?.imageSize ?? theme.body.resolvedMediaPlan.imageSize,
            stabilityAspectRatio: theme.body.resolvedMediaPlan.stabilityAspectRatio,
            stabilityStrength: retryImage.stabilityStrength,
            mediaPlan: theme.body.resolvedMediaPlan,
            transparentBackground: retryIsCharacterStudy,
            civitaiSeed: civitaiSeed,
            outputURL: outputURL,
            projectId: project.projectId,
            runId: imageId
        )

        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let client = provider == .civitaiWan27 ? nil : try OpenAIClient.fromEnvironment()
            let stabilityClient = try? StabilityAIClient.fromEnvironment(credentialStore: videoCredentialStore)
            let civitaiImageProvider = provider == .civitaiWan27
                ? CivitAIWANImageProvider(credentialStore: videoCredentialStore)
                : nil
            let outcome = await LensHeroImageRunner.generate(
                job: job,
                openAIClient: client,
                stabilityClient: stabilityClient,
                civitaiImageProvider: civitaiImageProvider
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let status = outcome.status == "ready"
                ? "\(provider.label) frame ready"
                : "\(provider.label) frame \(outcome.status)"
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: status,
                changeSummary: "\(provider.label) frame \(actionLabel.lowercased()) \(outcome.status)."
            )
            aestheticStatus = status
            if outcome.status == "failed" {
                lastError = outcome.errorMessage
            }
            return outcome.status == "ready"
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let failedAt = DateFormats.now()
            let status = (Task.isCancelled || isCancellationLikeError(error)) ? "cancelled" : "failed"
            let outcome = LensHeroGenerationOutcome(
                lensId: lensId,
                imageId: imageId,
                provider: provider,
                status: status,
                imagePath: "",
                prompt: retryImage.prompt,
                sourcePrompt: retryImage.sourcePrompt,
                negativePrompt: retryImage.negativePrompt,
                promptEnrichmentModel: "",
                promptEnrichmentResponseId: "",
                promptEnrichmentTraceId: "",
                promptEnrichmentSummary: "",
                requestId: "",
                traceId: "",
                errorMessage: error.localizedDescription,
                generatedAt: "",
                updatedAt: failedAt
            )
            _ = saveLensHeroImageOutcome(
                outcome,
                project: project,
                status: "\(provider.label) frame \(status)",
                changeSummary: "\(provider.label) frame retry \(status)."
            )
            aestheticStatus = "\(provider.label) frame \(status)"
            lastError = error.localizedDescription
            return false
        }
    }

    private func lensRenderStack(for image: ProjectLensHeroImage) -> RenderStack {
        let registry = RenderStackRegistry.shared
        // The persisted recipe stackId is authoritative when the registry
        // still knows it (user-defined stacks recover the same way).
        if let stack = registry.stack(stackId: image.renderRecipe?.normalized().stackId ?? "") {
            return stack
        }
        // Legacy records with no stackId: recover by provider/model heuristics.
        let provider = image.provider.trimmed.lowercased()
        let model = image.model.trimmed.lowercased()
        func known(_ id: String) -> RenderStack? { registry.stack(id: id) }
        if provider == "civitai" {
            // Prefer the model marker so a Realistic Portrait re-render keeps
            // its stack instead of silently falling back to WAN.
            if model.contains("flux") || model.contains("klein") || model.contains("portrait"),
               let portrait = known(RenderStackID.realisticPortrait) {
                return portrait
            }
            return known(RenderStackID.wan) ?? registry.fallback
        }
        if provider == "fal" {
            if model.contains("nano-banana"), let nano = known(RenderStackID.falNanoBanana2) { return nano }
            if model.contains("flux-2"), let flux2 = known(RenderStackID.falFlux2Pro) { return flux2 }
            return known(RenderStackID.falFluxSchnell) ?? registry.fallback
        }
        if provider == "stability" {
            return known(RenderStackID.stabilityUltra) ?? registry.fallback
        }
        return registry.fallback
    }

    private func lensRenderStyleMode(for image: ProjectLensHeroImage, stack: RenderStack) -> LensRenderStyleMode {
        guard !image.styleAuthorities.isEmpty else { return .none }
        let capabilities = Set(image.renderRecipe?.normalized().capabilities.map { $0.trimmed } ?? [])
        if capabilities.contains("styleImageReference"), stack.styleImageAttachSupported {
            return .attachStyleImage
        }
        return .describeStyleInPrompt
    }

    /// One creative version for one regeneration gesture: commits the (possibly updated) lens
    /// body and appends the queued media images in a single appendVersion.
    private func queueLensMediaVersion(
        lens: ProjectLens,
        newImages: [ProjectLensHeroImage],
        project: ProjectRecord,
        status: String,
        changeSummary: String
    ) -> Bool {
        guard currentProject?.projectId == project.projectId else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lens.lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        var next = lens
        next.heroImages = lens.heroImages + newImages.map { $0.normalized() }
        next.heroImage = next.primaryHeroImage
        next.updatedAt = now
        themes[index] = next.normalized()
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lens.lensId,
            selectedScratchId: nil,
            changeSummary: changeSummary,
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: status)
    }

    private func saveLensHeroImages(
        _ heroImages: [ProjectLensHeroImage],
        lensId: String,
        project: ProjectRecord,
        status: String,
        changeSummary: String
    ) -> Bool {
        guard currentProject?.projectId == project.projectId else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        themes[index].heroImages = heroImages.map { $0.normalized() }
        themes[index].heroImage = themes[index].primaryHeroImage
        themes[index] = lensWithRefreshedInitialDraftGenerationState(themes[index])
        themes[index].updatedAt = now
        themes[index] = themes[index].normalized()
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lensId,
            selectedScratchId: nil,
            changeSummary: changeSummary,
            model: "local-edit",
            now: now
        )
        let saved = saveLensSet(updated, for: project, status: status)
        // Implicit casting: every hero-image mutation funnels through here, so this is
        // where the derived scene cast stays in step with the takes (no-op when
        // unchanged; commitLensBody never re-enters this save path).
        if saved { reconcileLensCastFromTakes(lensId: lensId) }
        return saved
    }

    /// Marks just the given rows failed/cancelled against LIVE state — the
    /// whole-lens catch path must not bulk-save its stale start array, which
    /// would clobber rows other flows appended while it awaited. No ledger
    /// entry: this path only fires before any render completed.
    private func markLensHeroImagesFailed(
        imageIds: [String],
        lensId: String,
        project: ProjectRecord,
        rowStatus: String,
        errorMessage: String,
        status: String,
        changeSummary: String
    ) -> Bool {
        guard currentProject?.projectId == project.projectId else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        var heroImages = themes[index].sortedHeroImages
        for rowIndex in heroImages.indices where imageIds.contains(heroImages[rowIndex].imageId) {
            heroImages[rowIndex].status = rowStatus
            heroImages[rowIndex].errorMessage = errorMessage
            heroImages[rowIndex].updatedAt = now
        }
        themes[index].heroImages = heroImages
        themes[index].heroImage = themes[index].primaryHeroImage
        themes[index] = lensWithRefreshedInitialDraftGenerationState(themes[index], fallbackError: errorMessage)
        themes[index].updatedAt = now
        themes[index] = themes[index].normalized()
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lensId,
            selectedScratchId: nil,
            changeSummary: changeSummary,
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: status)
    }

    private func saveLensHeroMotionImages(
        _ heroImages: [ProjectLensHeroImage],
        lensId: String,
        project: ProjectRecord,
        status: String
    ) -> Bool {
        guard currentProject?.projectId == project.projectId else { return false }
        var updated = projectLenses
        var lenses = updated.lenses
        guard let index = lenses.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        lenses[index].heroImages = heroImages.map { $0.normalized() }
        lenses[index].heroImage = lenses[index].primaryHeroImage
        lenses[index].updatedAt = now
        lenses[index] = lenses[index].normalized()
        updated.updateActiveVersion(lenses: lenses, now: now)
        return saveLensSet(updated, for: project, status: status)
    }

    @discardableResult
    func setLensHeroImageActiveVersion(lensId: String, imageId: String) -> Bool {
        guard let project = currentProject else { return false }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let normalizedLens = lens.normalized()
        var heroImages = normalizedLens.heroImages
        guard let imageIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Scene Plan version not found"
            return false
        }
        let image = heroImages[imageIndex].normalized()
        guard image.status == "ready", !image.imagePath.trimmed.isEmpty else {
            aestheticStatus = "Render this version before making it active"
            return false
        }
        guard FileManager.default.fileExists(atPath: image.imagePath) else {
            aestheticStatus = "Active version image is missing on disk"
            return false
        }
        guard image.renderVersion?.renderVersionGroupId.trimmed.nilIfEmpty != nil else {
            aestheticStatus = "This version cannot be grouped yet"
            return false
        }

        heroImages = lensHeroImages(heroImages, lensId: lensId, activating: imageId)
        var updated = projectLenses
        var lenses = updated.lenses
        guard let lensIndex = lenses.firstIndex(where: { $0.lensId == lensId }) else { return false }
        let now = DateFormats.now()
        lenses[lensIndex].heroImages = heroImages
        lenses[lensIndex].heroImage = lenses[lensIndex].primaryHeroImage
        lenses[lensIndex].updatedAt = now
        lenses[lensIndex] = lenses[lensIndex].normalized()
        updated.updateActiveVersion(lenses: lenses, now: now)
        aestheticStatus = "Made active version"
        return saveLensSet(updated, for: project, status: "Made active version")
    }

    /// Marks a concept image as kept (adopted) or not. Adoption is curation, not a
    /// creative change: it saves without appending a new creative version.
    @discardableResult
    func setLensHeroImageKept(lensId: String, imageId: String, kept: Bool) -> Bool {
        guard let project = currentProject else { return false }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lens.heroImages
        guard let index = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Concept image not found"
            return false
        }
        heroImages[index].kept = kept ? true : nil
        heroImages[index].updatedAt = DateFormats.now()
        var updated = projectLenses
        var themes = updated.lenses
        guard let lensIndex = themes.firstIndex(where: { $0.lensId == lensId }) else { return false }
        themes[lensIndex].heroImages = heroImages.map { $0.normalized() }
        themes[lensIndex].heroImage = themes[lensIndex].primaryHeroImage
        themes[lensIndex].updatedAt = DateFormats.now()
        updated.updateActiveVersion(lenses: themes, now: DateFormats.now())
        return saveLensSet(updated, for: project, status: kept ? "Kept concept" : "Unkept concept")
    }

    /// Soft-deletes a render: it disappears from every board, version list, and
    /// downstream use, but stays persisted on disk so it can be recovered. Never a
    /// hard delete. Operates on the raw hero image array so hidden renders are kept.
    @discardableResult
    func disableLensHeroImage(lensId: String, imageId: String) -> Bool {
        guard let project = currentProject else { return false }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lens.heroImages
        guard let index = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Render not found"
            return false
        }
        guard !heroImages[index].disabled else { return true }
        let wasCharacterTake = LensConceptCategory.category(for: heroImages[index]) == .characters
        heroImages[index].disabled = true
        // A hidden render must not stay the active version of its group; the board
        // falls back to the next visible sibling on its own.
        heroImages[index].renderVersion?.isActive = false
        heroImages[index].updatedAt = DateFormats.now()
        var updated = projectLenses
        var themes = updated.lenses
        guard let lensIndex = themes.firstIndex(where: { $0.lensId == lensId }) else { return false }
        themes[lensIndex].heroImages = heroImages.map { $0.normalized() }
        themes[lensIndex].heroImage = themes[lensIndex].primaryHeroImage
        themes[lensIndex].updatedAt = DateFormats.now()
        updated.updateActiveVersion(lenses: themes, now: DateFormats.now())
        let saved = saveLensSet(updated, for: project, status: "Disabled render")
        // This path bypasses saveLensHeroImages, so keep the derived cast in step here:
        // hiding a character's last take takes them out of the scene.
        if saved, wasCharacterTake { reconcileLensCastFromTakes(lensId: lensId) }
        return saved
    }

    /// Distills archive media summaries to visual facts an image model can use:
    /// captions and visible objects only — no identifiers, file paths, or dimensions.
    private func lensHeroArchiveGlimpses(_ mediaSummaries: [String], limit: Int = 4) -> [String] {
        mediaSummaries.prefix(limit).compactMap { summary in
            var caption = ""
            var objects = ""
            for segment in summary.components(separatedBy: " | ") {
                if segment.hasPrefix("caption=") {
                    caption = String(segment.dropFirst("caption=".count)).trimmed
                } else if segment.hasPrefix("objects=") {
                    objects = String(segment.dropFirst("objects=".count)).trimmed
                }
            }
            if caption.isEmpty && objects.isEmpty {
                return nil
            }
            if objects.isEmpty {
                return caption
            }
            return caption.isEmpty ? "visible: \(objects)" : "\(caption) (visible: \(objects))"
        }
    }

    /// Shared opener for concept images: one subject, one frame. Output shape is
    /// provider-parameterized, so aspect/resolution never belongs in prompt text.
    private func lensConceptOpener(kind: String, plan: LensMediaPlan) -> String {
        switch plan.aspect {
        case "landscape":
            return "Create one wide cinematic \(kind)."
        case "portrait":
            return "Create one tall vertical \(kind)."
        default:
            return "Create one square \(kind)."
        }
    }

    /// Shared closing rules for concept images: guardrail avoids and the readable-text
    /// policy. When a style image attaches, no style language ships in text (the lens's
    /// own mustAvoid guardrails are subject-level and stay).
    private func lensConceptClosingLines(theme: ProjectLens, plan: LensMediaPlan, isolatedStudy: Bool = false) -> [String] {
        var lines: [String] = []
        let promptSafe = PromptSafeLensSnapshot.from(lens: theme)
        let styleBacked = theme.body.styleTreatment?.isEmpty == false
            || !lensHeroSourceReferenceIds(theme).isEmpty
        var avoid = promptSafe.mustAvoid
        if !styleBacked {
            avoid = uniqueNonEmpty(avoid + promptSafe.resolvedVisualLanguage.avoid)
            let lookLines = uniqueNonEmpty([promptSafe.claim, promptSafe.visualSummary, promptSafe.resolvedVisualLanguage.look])
            if !lookLines.isEmpty {
                lines.append("Visual style: \(lookLines.joined(separator: " "))")
            }
        }
        let avoidTerms = uniqueNonEmpty(avoid).prefixArray(12)
        if !avoidTerms.isEmpty {
            lines.append("Strictly avoid: \(avoidTerms.joined(separator: ", ")).")
        }
        if plan.allowReadableText {
            if isolatedStudy {
                // Isolated studies must not be invited to paint signage —
                // environmental text implies walls, posts, and scenery.
                lines.append("Readable text may appear only on the subject itself — garment print, gear labels, worn markings — kept plausible and partial.")
            } else {
                lines.append("Environmental text is welcome where the world implies it — signs, labels, inscriptions, markings — in the condition the world is in, kept plausible and partial; no long legible paragraphs.")
            }
        } else {
            lines.append("Do not render readable text; any typography stays graphic and minimal.")
        }
        return lines
    }

    /// Environment concept: one place of this world, assembled from structured setting
    /// fields (prose fallback for legacy lenses), carrying the set dressing. Unpopulated
    /// unless the scene casts characters — those enter as @Name mention lines that the
    /// Frame Creator resolves into attached roster references.
    func lensSceneryConceptPrompt(
        setting: LensSceneSetting?,
        prosePrompt: String,
        sceneCast: [LensSceneCastEntry] = [],
        setDressingPrompts: [String],
        beatLabel: String,
        sceneryIndex: Int,
        sceneryCount: Int,
        theme: ProjectLens
    ) -> String {
        let plan = theme.body.resolvedMediaPlan
        var lines: [String] = [lensConceptOpener(kind: "environment concept image", plan: plan)]
        if plan.isSequence, sceneryCount > 1 {
            lines.append("This place is stop \(sceneryIndex + 1) of \(sceneryCount) along one continuous journey\(beatLabel.isEmpty ? "" : " — the \(beatLabel) beat").")
        } else if !plan.isSequence, !beatLabel.isEmpty {
            lines.append("This place is one distinct moment of the story — its \(beatLabel) beat — not a step in a sequence.")
        }
        lines.append("")
        if let setting, !setting.isEmpty {
            var placeLine = "The place: \(setting.locationName)"
            if !setting.locationType.isEmpty {
                placeLine += " — \(setting.locationType)"
            }
            placeLine += "."
            lines.append(placeLine)
            if !setting.timeOfDay.isEmpty {
                lines.append("Time: \(setting.timeOfDay).")
            }
            if !setting.weather.isEmpty {
                lines.append("Weather: \(setting.weather).")
            }
            if !setting.spatialLayout.isEmpty {
                lines.append("Spatial layout: \(setting.spatialLayout).")
            }
            if !setting.foregroundDetails.isEmpty {
                lines.append("In the foreground: \(setting.foregroundDetails.joined(separator: "; ")).")
            }
            if !setting.backgroundDetails.isEmpty {
                lines.append("In the background: \(setting.backgroundDetails.joined(separator: "; ")).")
            }
            if !setting.notableFeatures.isEmpty {
                lines.append("Notable features: \(setting.notableFeatures.joined(separator: "; ")).")
            }
        } else {
            lines.append("The place: \(prosePrompt.trimmed)")
        }
        if !setDressingPrompts.isEmpty {
            lines.append("Ambient set dressing, part of this environment and in no one's hands:")
            for prompt in setDressingPrompts {
                lines.append("- \(prompt.trimmed)")
            }
        }
        let castNames = uniqueNonEmpty(
            lensCompositeCast(for: theme).map(\.name) + projectCharacters.characters.map(\.name)
        )
        if let castLine = LensSceneCastPrompt.mentionLine(cast: sceneCast, validNames: castNames) {
            lines.append(castLine)
            lines.append("No one else is present; any other figures are distant and incidental.")
        } else {
            lines.append("The place is unpopulated; any figures are distant and incidental.")
        }
        if let anchor = theme.body.canonicalAnchor, !anchor.isEmpty {
            let caption = anchor.caption.trimmed.isEmpty ? "canonical subject" : anchor.caption.trimmed
            if anchor.placement == "recurring-background" {
                lines.append("The \(caption) recurs in this environment: present and recognizable, but never dominating the composition.")
            } else {
                lines.append("Feature the \(caption) prominently in this environment; it is a subject, not a decoration.")
            }
        }
        lines.append(contentsOf: lensConceptClosingLines(theme: theme, plan: plan))
        return lines.filter { !$0.isEmpty }.joined(separator: "\n")
    }

    /// Character concept study: one named figure, full body, prominent, rendered as a
    /// clean isolated cut-out. The prompt must not describe any environment or backdrop:
    /// setting language would fight the isolated-study intent and paint scenery around
    /// the figure.
    func lensCharacterConceptPrompt(
        name: String,
        descriptionPrompt: String,
        signatureProps: [String],
        environmentAffinity: String,
        settings: [LensSceneSetting],
        anchorProse: String,
        theme: ProjectLens,
        mediaSummaries: [String]
    ) -> String {
        let plan = theme.body.resolvedMediaPlan
        var lines: [String] = [lensConceptOpener(kind: "character concept study", plan: plan)]
        lines.append("")
        let subject = name.trimmed.isEmpty ? "the character" : "\"\(name.trimmed)\""
        lines.append("The subject: \(subject) — \(descriptionPrompt.trimmed)")
        if !signatureProps.isEmpty {
            lines.append("Always with them: \(uniqueNonEmpty(signatureProps).joined(separator: "; ")).")
        }
        lines.append("Show the full figure head to toe, prominent in the frame. One figure only — no lineup, no panels.")
        lines.append("The figure stands alone as a clean isolated character study: no environment, no floor plane, no backdrop, no cast scenery — only the figure, their clothing, and what they carry.")
        let glimpses = lensHeroArchiveGlimpses(mediaSummaries, limit: 3)
        if !glimpses.isEmpty {
            lines.append("The real creature or figure this world grew from, for subject grounding: \(glimpses.joined(separator: "; ")).")
        }
        lines.append(contentsOf: lensConceptClosingLines(theme: theme, plan: plan, isolatedStudy: true))
        return lines.filter { !$0.isEmpty }.joined(separator: "\n")
    }

    /// Object concept study: one prop, prominent and in-situ, assembled from structured
    /// fields (prose fallback), with material, condition, and a clear sense of scale.
    func lensObjectConceptPrompt(
        concept: LensObjectConcept?,
        prosePrompt: String,
        anchorSetting: LensSceneSetting?,
        anchorProse: String,
        theme: ProjectLens
    ) -> String {
        let plan = theme.body.resolvedMediaPlan
        var lines: [String] = [lensConceptOpener(kind: "prop concept study", plan: plan)]
        lines.append("")
        if let concept, !concept.isEmpty {
            var subjectLine = "The subject: \(concept.name)"
            let facts = uniqueNonEmpty([concept.type, concept.material, concept.condition])
            if !facts.isEmpty {
                subjectLine += " — \(facts.joined(separator: ", "))"
            }
            subjectLine += "."
            lines.append(subjectLine)
            if !concept.distinguishingFeatures.isEmpty {
                lines.append("Distinguishing features: \(concept.distinguishingFeatures.joined(separator: "; ")).")
            }
            if !concept.locationInScene.isEmpty {
                lines.append("It lives here: \(concept.locationInScene).")
            }
        } else {
            lines.append("The subject: \(prosePrompt.trimmed)")
        }
        lines.append("Show it prominent, resting on or against this world's own surfaces, with honest wear and a clear sense of scale — never a sterile catalog shot.")
        // A concept with its own locationInScene is already sited; adding the anchor's
        // surroundings would contradict it.
        if concept?.locationInScene.trimmed.isEmpty != false {
            let backdrop = anchorSetting?.condensed.nilIfEmpty ?? anchorProse.trimmed.nilIfEmpty
            if let backdrop {
                lines.append("The surroundings, kept secondary: \(backdrop).")
            }
        }
        lines.append(contentsOf: lensConceptClosingLines(theme: theme, plan: plan))
        return lines.filter { !$0.isEmpty }.joined(separator: "\n")
    }

    /// Maps composition-inferred cast members onto LensCastMember values, linking EVERY
    /// member to a project roster character: exact (case-insensitive) name matches
    /// reuse the existing entry (including ones created for an earlier slice in the
    /// same run, via the shared draft), and unmatched names create one in the passed
    /// roster draft — Goal cast members are roster-linked from birth, so their studies
    /// stamp characterIds and their sidebar cards group correctly. The caller saves
    /// the draft once per gesture.
    func lensCastMembersFromComposition(
        _ members: [LensTrioCastMemberResponse],
        rosterDraft: inout ProjectCharacterSetDocument,
        now: String
    ) -> [LensCastMember]? {
        let mapped = members.compactMap { member -> LensCastMember? in
            let name = member.name.trimmed
            guard !name.isEmpty else { return nil }
            let characterId: String
            if let existing = rosterDraft.characters.first(where: { $0.name.trimmed.lowercased() == name.lowercased() }) {
                characterId = existing.characterId
            } else {
                let character = ProjectCharacter(
                    characterId: "character_\(shortHash("\(rosterDraft.projectId):\(name):\(now)", length: 12))",
                    name: name,
                    descriptionPrompt: member.description,
                    updatedAt: now
                ).normalized()
                rosterDraft.characters.append(character)
                rosterDraft.updatedAt = now
                characterId = character.characterId
            }
            return LensCastMember(
                castId: "cast_\(shortHash("\(name):\(now)", length: 12))",
                name: name,
                descriptionPrompt: member.description,
                characterId: characterId,
                signatureProps: member.signatureProps,
                environmentAffinity: member.environmentAffinity
            ).normalized()
        }
        return mapped.isEmpty ? nil : mapped
    }

    /// Place counterpart of lensCastMembersFromComposition: the composition's areas
    /// ARE the scene's proposed places, so each area is roster-linked from birth —
    /// exact (case-insensitive) title matches reuse the existing ProjectPlace
    /// (including ones created for an earlier slice via the shared draft), and
    /// unmatched titles create one in the passed draft. The caller saves the draft
    /// once per gesture. Returns the areas with `placeId` stamped (nil when empty,
    /// matching the lens body's optional field).
    func lensPlacesFromComposition(
        _ areas: [LensArea],
        placesDraft: inout ProjectPlaceSetDocument,
        now: String
    ) -> [LensArea]? {
        let mapped = areas.enumerated().map { index, area -> LensArea in
            var stamped = area.normalized(order: index)
            let name = stamped.title.trimmed
            guard !name.isEmpty else { return stamped }
            if let existing = placesDraft.places.first(where: { $0.name.trimmed.lowercased() == name.lowercased() }) {
                stamped.placeId = existing.placeId
            } else {
                let place = ProjectPlace(
                    placeId: "place_\(shortHash("\(placesDraft.projectId):\(name):\(now)", length: 12))",
                    name: name,
                    descriptionPrompt: stamped.prosePrompt.trimmed.nilIfEmpty ?? stamped.setting.condensed,
                    updatedAt: now
                ).normalized()
                placesDraft.places.append(place)
                placesDraft.updatedAt = now
                stamped.placeId = place.placeId
            }
            return stamped
        }
        return mapped.isEmpty ? nil : mapped
    }

    /// The stable named cast for a Lens's concept studies, by precedence: roster
    /// characters selected on the media plan, then the lens's own cast members, then the
    /// legacy unnamed prompt pool. `characterId` is the roster link when one exists
    /// (empty for unlinked cast members and legacy prompts) and is stamped onto queued
    /// character takes so the UI can group takes by character.
    func lensCompositeCast(for lens: ProjectLens) -> [(name: String, prompt: String, signatureProps: [String], environmentAffinity: String, characterId: String)] {
        let plan = lens.body.resolvedMediaPlan
        let rosterCast = plan.selectedCharacterIds.compactMap { characterId -> (name: String, prompt: String, signatureProps: [String], environmentAffinity: String, characterId: String)? in
            guard let character = projectCharacters.character(withId: characterId) else { return nil }
            return (
                character.name,
                character.descriptionPrompt.isEmpty ? character.name : character.descriptionPrompt,
                character.signatureProps,
                character.environmentAffinity,
                character.characterId
            )
        }
        if !rosterCast.isEmpty {
            return rosterCast
        }
        if let members = lens.body.castMembers, !members.isEmpty {
            return members.prefix(plan.characterCount).map {
                ($0.name, $0.descriptionPrompt.isEmpty ? $0.name : $0.descriptionPrompt, $0.signatureProps, $0.environmentAffinity, $0.characterId ?? "")
            }
        }
        return (lens.body.characterImagePrompts ?? []).prefix(plan.characterCount).map { ("", $0, [], "", "") }
    }

    /// Resolves the character a take portrays: the stamped characterId when present,
    /// else a label-segment name match against the roster and the lens cast. Empty
    /// when the take cannot be attributed — it then stays visible in the residual
    /// "Other character takes" group. (The old route-key ordinal fallback is gone:
    /// under implicit casting the derived cast order no longer matches the planning
    /// order, so ordinal indexing attributed legacy takes to the wrong character.)
    private func lensResolvedTakeCharacterId(
        for take: ProjectLensHeroImage,
        lens: ProjectLens,
        cast: [(name: String, prompt: String, signatureProps: [String], environmentAffinity: String, characterId: String)]
    ) -> String {
        if !take.characterId.isEmpty { return take.characterId }
        let segments = take.label.components(separatedBy: " · ").map { $0.trimmed.lowercased() }.filter { !$0.isEmpty }
        for segment in segments {
            if let character = projectCharacters.characters.first(where: { $0.name.lowercased() == segment }) {
                return character.characterId
            }
            if let member = (lens.body.castMembers ?? []).first(where: { $0.name.trimmed.lowercased() == segment }),
               let characterId = member.characterId, !characterId.isEmpty {
                return characterId
            }
        }
        return ""
    }

    /// Identity-first grouping of a media version's character takes, roster-complete so
    /// every project character always has a card: in-scene characters first (implicit
    /// casting — in scene = has a take in the NEWEST version), then other characters
    /// with takes in the displayed version, then the rest of the roster in roster
    /// order. Takes that cannot be attributed to anyone (legacy, pre-stamping) are not
    /// displayed — every current creation path stamps a roster-linked characterId, so
    /// unattributable character takes are abandoned data by locked decision.
    func lensCharacterTakeGroups(lens: ProjectLens, versionId: String) -> [LensIdentityTakeGroup] {
        let takes = lens.heroImages(mediaVersion: versionId).filter { LensConceptCategory.category(for: $0) == .characters }
        let cast = lensCompositeCast(for: lens)

        // Membership follows the newest version's takes even while an older version is
        // displayed: browsing history never changes who is in the scene.
        let newestVersionId = lens.mediaVersionIds.last ?? versionId
        let newestTakes = newestVersionId == versionId
            ? takes
            : lens.heroImages(mediaVersion: newestVersionId).filter { LensConceptCategory.category(for: $0) == .characters }
        var inSceneIds: [String] = []
        for take in newestTakes {
            let characterId = lensResolvedTakeCharacterId(for: take, lens: lens, cast: cast)
            if !characterId.isEmpty, !inSceneIds.contains(characterId) { inSceneIds.append(characterId) }
        }

        var takesByCharacter: [String: [ProjectLensHeroImage]] = [:]
        var resolvedOrder: [String] = []
        for take in takes {
            let characterId = lensResolvedTakeCharacterId(for: take, lens: lens, cast: cast)
            guard !characterId.isEmpty else { continue }
            takesByCharacter[characterId, default: []].append(take)
            if !resolvedOrder.contains(characterId) { resolvedOrder.append(characterId) }
        }

        var groups: [LensIdentityTakeGroup] = []
        var seen = Set<String>()
        func appendGroup(characterId: String) {
            guard !characterId.isEmpty, seen.insert(characterId).inserted else { return }
            let character = projectCharacters.character(withId: characterId)
            let member = (lens.body.castMembers ?? []).first { $0.characterId == characterId }
            groups.append(LensIdentityTakeGroup(
                id: characterId,
                displayName: character?.name ?? member?.name ?? "Character",
                characterId: characterId,
                referenceMediaIds: character?.referenceMediaIds ?? [],
                descriptionPrompt: character?.descriptionPrompt ?? member?.descriptionPrompt ?? "",
                membership: inSceneIds.contains(characterId) ? .cast : .notCast,
                takes: (takesByCharacter[characterId] ?? []).sorted { $0.imageIndex < $1.imageIndex }
            ))
        }
        for characterId in inSceneIds { appendGroup(characterId: characterId) }
        for characterId in resolvedOrder { appendGroup(characterId: characterId) }
        for character in projectCharacters.characters { appendGroup(characterId: character.characterId) }
        return groups
    }

    /// Objects counterpart of lensCharacterTakeGroups, keyed on the lens's object
    /// concepts by name (roster objects supply thumbnails/descriptions when a name
    /// matches). Roster objects with no concept and no takes here trail as notCast
    /// groups, mirroring the character roster rows. Takes whose label matches no
    /// known object land in a residual group.
    func lensObjectTakeGroups(lens: ProjectLens, versionId: String) -> [LensIdentityTakeGroup] {
        let takes = lens.heroImages(mediaVersion: versionId).filter { LensConceptCategory.category(for: $0) == .objects }
        let concepts = (lens.body.objectConcepts ?? []).map { $0.normalized() }.filter { !$0.isEmpty }

        func rosterObject(named name: String) -> ProjectObject? {
            projectObjects.objects.first { $0.name.lowercased() == name.lowercased() }
        }
        func resolvedName(for take: ProjectLensHeroImage) -> String {
            let segments = take.label.components(separatedBy: " · ").map(\.trimmed).filter { !$0.isEmpty }
            for segment in segments {
                if concepts.contains(where: { $0.name.lowercased() == segment.lowercased() }) { return segment }
                if let object = rosterObject(named: segment) { return object.name }
            }
            return ""
        }

        var takesByName: [String: [ProjectLensHeroImage]] = [:]
        var residual: [ProjectLensHeroImage] = []
        var resolvedOrder: [String] = []
        for take in takes {
            let name = resolvedName(for: take)
            if name.isEmpty {
                residual.append(take)
            } else {
                let key = name.lowercased()
                takesByName[key, default: []].append(take)
                if !resolvedOrder.contains(key) { resolvedOrder.append(key) }
            }
        }

        var groups: [LensIdentityTakeGroup] = []
        var seen = Set<String>()
        func appendGroup(name: String) {
            let key = name.trimmed.lowercased()
            guard !key.isEmpty, seen.insert(key).inserted else { return }
            let object = rosterObject(named: name)
            let concept = concepts.first { $0.name.lowercased() == key }
            let groupTakes = (takesByName[key] ?? []).sorted { $0.imageIndex < $1.imageIndex }
            groups.append(LensIdentityTakeGroup(
                id: "object_\(key)",
                displayName: object?.name ?? concept?.name ?? name,
                characterId: "",
                objectId: object?.objectId ?? "",
                referenceMediaIds: object?.referenceMediaIds ?? [],
                descriptionPrompt: object?.descriptionPrompt ?? concept?.material ?? "",
                membership: (concept != nil || !groupTakes.isEmpty) ? .cast : .notCast,
                takes: groupTakes
            ))
        }
        for concept in concepts { appendGroup(name: concept.name) }
        for key in resolvedOrder { appendGroup(name: takesByName[key]?.first.map { resolvedName(for: $0) } ?? key) }
        for object in projectObjects.objects { appendGroup(name: object.name) }
        if !residual.isEmpty {
            groups.append(LensIdentityTakeGroup(
                id: "residual_objects",
                displayName: "Other object takes",
                characterId: "",
                referenceMediaIds: [],
                descriptionPrompt: "",
                membership: .unlabeled,
                takes: residual.sorted { $0.imageIndex < $1.imageIndex }
            ))
        }
        return groups
    }

    /// Place-first grouping of the scene's frames: one group per lens area, roster-
    /// linked via the area's placeId (name-matched for legacy areas), carrying that
    /// place's scenery frames on the displayed version. Roster places with no area
    /// here trail with no frames, and frames owned by no area land in a residual
    /// group — grouping never hides work.
    func lensPlaceFrameGroups(lens: ProjectLens, versionId: String) -> [LensPlaceFrameGroup] {
        let frames = lens.heroImages(mediaVersion: versionId).filter { LensConceptCategory.category(for: $0) == .scenery }
        let areas = (lens.body.areas ?? []).enumerated().map { $0.element.normalized(order: $0.offset) }.filter { !$0.isEmpty }
        var framesByArea: [String: [ProjectLensHeroImage]] = [:]
        var residual: [ProjectLensHeroImage] = []
        let knownAreaIds = Set(areas.map(\.areaId))
        for frame in frames {
            if !frame.areaId.isEmpty, knownAreaIds.contains(frame.areaId) {
                framesByArea[frame.areaId, default: []].append(frame)
            } else {
                residual.append(frame)
            }
        }
        var groups: [LensPlaceFrameGroup] = []
        var seenPlaceIds = Set<String>()
        for area in areas {
            let place = resolvedPlace(for: area)
            if let place { seenPlaceIds.insert(place.placeId) }
            groups.append(LensPlaceFrameGroup(
                id: place?.placeId ?? "area_\(area.areaId)",
                placeId: place?.placeId ?? "",
                areaId: area.areaId,
                displayName: place?.name ?? area.title,
                descriptionPrompt: place?.descriptionPrompt ?? (area.prosePrompt.trimmed.nilIfEmpty ?? area.setting.condensed),
                referenceMediaIds: place?.referenceMediaIds ?? [],
                frames: (framesByArea[area.areaId] ?? []).sorted { $0.imageIndex < $1.imageIndex }
            ))
        }
        for place in projectPlaces.places where !seenPlaceIds.contains(place.placeId) {
            groups.append(LensPlaceFrameGroup(
                id: place.placeId,
                placeId: place.placeId,
                areaId: "",
                displayName: place.name,
                descriptionPrompt: place.descriptionPrompt,
                referenceMediaIds: place.referenceMediaIds,
                frames: []
            ))
        }
        if !residual.isEmpty {
            groups.append(LensPlaceFrameGroup(
                id: "residual_scenery",
                placeId: "",
                areaId: "",
                displayName: "Other frames",
                descriptionPrompt: "",
                referenceMediaIds: [],
                frames: residual.sorted { $0.imageIndex < $1.imageIndex }
            ))
        }
        return groups
    }

    /// The roster place an area resolves to: the stamped placeId when linked,
    /// else an exact case-insensitive title match (legacy lenses composed before
    /// places existed).
    private func resolvedPlace(for area: LensArea) -> ProjectPlace? {
        projectPlaces.place(withId: area.placeId)
            ?? projectPlaces.places.first { $0.name.trimmed.lowercased() == area.title.trimmed.lowercased() }
    }

    /// Place captions for the FRAMES strip, keyed by the lens area that owns each
    /// scenery frame. Empty when the lens has no areas (the strip stays flat).
    func lensPlaceCaptionsByAreaId(lens: ProjectLens) -> [String: String] {
        var captions: [String: String] = [:]
        for (index, raw) in (lens.body.areas ?? []).enumerated() {
            let area = raw.normalized(order: index)
            guard !area.areaId.isEmpty else { continue }
            let name = (resolvedPlace(for: area)?.name ?? area.title).trimmed
            guard !name.isEmpty else { continue }
            captions[area.areaId] = name
        }
        return captions
    }

    /// Plans one character study in the newest media version. Under implicit casting
    /// this gesture IS casting: the scene cast is derived from the version's takes
    /// (reconciled on save), so planning a study puts the character in the scene.
    @discardableResult
    func planLensCharacterStudy(lensId: String, characterId: String) async -> Bool {
        guard let project = currentProject,
              let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        guard let character = projectCharacters.character(withId: characterId) else {
            aestheticStatus = "Character not found"
            return false
        }
        guard let versionId = lens.mediaVersionIds.last else {
            aestheticStatus = "Generate this scene's media first — planned studies live in a media version."
            return false
        }
        let cast = lensCompositeCast(for: lens)
        let versionTakes = lens.heroImages(mediaVersion: versionId).filter { LensConceptCategory.category(for: $0) == .characters }
        let represented = versionTakes.map { lensResolvedTakeCharacterId(for: $0, lens: lens, cast: cast) }
        guard !represented.contains(characterId) else {
            aestheticStatus = "\(character.name) already has a take in this version"
            return true
        }
        let member = (
            name: character.name,
            prompt: character.descriptionPrompt.isEmpty ? character.name : character.descriptionPrompt,
            signatureProps: character.signatureProps,
            environmentAffinity: character.environmentAffinity,
            characterId: character.characterId
        )
        var heroImages = lens.heroImages
        let queued = await queuedCharacterStudyTakes(
            lens: lens,
            versionId: versionId,
            versionTakes: versionTakes,
            existingHeroImages: heroImages,
            members: [member]
        )
        guard !queued.isEmpty else { return false }
        heroImages.append(contentsOf: queued)
        let summary = "Planned a study for \(character.name) — \(character.name) is now in this scene."
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Planned character study",
            changeSummary: summary
        ) else { return false }
        aestheticStatus = summary
        return true
    }

    /// Drops a planned (never-started) character study. Under implicit casting this is
    /// the un-cast gesture for a character whose studies haven't rendered; rendered
    /// takes are soft-disabled through the preview instead.
    @discardableResult
    func removePlannedLensCharacterTake(lensId: String, imageId: String) -> Bool {
        guard let project = currentProject,
              let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lens.heroImages
        guard let index = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Take not found"
            return false
        }
        guard heroImages[index].isPurePlan else {
            aestheticStatus = "Only planned takes can be removed — rendered takes are hidden from their preview"
            return false
        }
        let cast = lensCompositeCast(for: lens)
        let removedCharacterId = lensResolvedTakeCharacterId(for: heroImages[index], lens: lens, cast: cast)
        let name = projectCharacters.character(withId: removedCharacterId)?.name
        let removed = heroImages[index]
        heroImages.remove(at: index)
        let summary = name.map { "Dropped the planned study for \($0)." } ?? "Dropped a planned study."
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Dropped planned study",
            changeSummary: summary
        ) else { return false }
        // A dropped character suggestion takes its scene along: a scene left
        // behind would be re-minted as a plain plan row on the next merge.
        if removed.isSheetSuggestion, !removed.sceneId.isEmpty,
           let live = projectLenses.lenses.first(where: { $0.lensId == lensId }),
           let areas = live.body.areas, areas.contains(where: { $0.scenes.contains { $0.sceneId == removed.sceneId } }) {
            var body = live.body
            body.areas = areas
                .map { area in
                    var trimmed = area
                    trimmed.scenes.removeAll { $0.sceneId == removed.sceneId }
                    return trimmed
                }
                .filter { !$0.scenes.isEmpty }
            _ = commitLensBody(lensId: lensId, body: body, changeSummary: "Dropped a suggested moment and its scene.")
        }
        let stillCast = projectLenses.lenses.first(where: { $0.lensId == lensId })?
            .body.resolvedMediaPlan.selectedCharacterIds.contains(removedCharacterId) ?? false
        if let name, !removedCharacterId.isEmpty, !stillCast {
            aestheticStatus = "Dropped the planned study for \(name) — no longer in this scene."
        } else {
            aestheticStatus = summary
        }
        return true
    }

    /// Implicit casting: derives the scene cast from the NEWEST media version's takes
    /// (first-appearance order, roster-linked only; disabled takes never count) and
    /// commits a lens body version only when the cast actually changed. Hooked into the
    /// hero-image save paths so the persisted cast always follows the takes. The cast
    /// feeds prompts and reframe candidates; render attachments are per-frame scoped.
    @discardableResult
    func reconcileLensCastFromTakes(lensId: String) -> Bool {
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else { return false }
        guard let versionId = lens.mediaVersionIds.last else { return true }
        let cast = lensCompositeCast(for: lens)
        let takes = lens.heroImages(mediaVersion: versionId).filter { LensConceptCategory.category(for: $0) == .characters }
        let derived = LensCastDerivation.derivedCharacterIds(
            resolvedIds: takes.map { lensResolvedTakeCharacterId(for: $0, lens: lens, cast: cast) },
            knownIds: Set(projectCharacters.characters.map(\.characterId))
        )
        var body = lens.body
        var plan = body.resolvedMediaPlan
        guard derived != plan.selectedCharacterIds else { return true }
        plan.selectedCharacterIds = derived
        plan.characterCount = max(plan.characterCount, derived.count)
        body.mediaPlan = plan
        let names = derived.compactMap { projectCharacters.character(withId: $0)?.name }
        let summary = names.isEmpty
            ? "Scene cast follows its takes: no one is in this scene yet."
            : "Scene cast follows its takes: \(names.joined(separator: ", "))."
        return commitLensBody(lensId: lensId, body: body, changeSummary: summary)
    }

    /// Builds queued character-study takes for the given roster members, continuing the
    /// version's `lens_media_character_N` ordinal sequence and stamping each take with
    /// its characterId so implicit casting and grouping can attribute it.
    private func queuedCharacterStudyTakes(
        lens: ProjectLens,
        versionId: String,
        versionTakes: [ProjectLensHeroImage],
        existingHeroImages: [ProjectLensHeroImage],
        members: [(name: String, prompt: String, signatureProps: [String], environmentAffinity: String, characterId: String)]
    ) async -> [ProjectLensHeroImage] {
        guard !members.isEmpty else { return [] }
        let body = lens.body.normalized()
        let plan = body.resolvedMediaPlan
        let primarySlot = body.styleTreatment?.normalized().slots.first
        let styleReferenceIds = uniqueNonEmpty(body.styleIngredients.flatMap(\.sourceReferenceIds))
        let catalog = await styleBrowseCatalogForAttachmentFallback()
        let styleAuthorities = generatedTakeStyleAuthorities(lens: lens, catalog: catalog)
        let mediaSummaries = aestheticMediaSummaryPackets(limit: 20)
        let areas = (body.areas ?? []).map { $0.normalized() }.filter { $0.enabled && !$0.scenes.isEmpty }
        let studySettings = areas.flatMap { area in [area.setting] + area.scenes.map(\.setting) }.filter { !$0.isEmpty }
        let anchorProse = areas.first?.prosePrompt ?? ""
        let versionSuffix = versionId.isEmpty ? "" : "@\(versionId)"
        let now = DateFormats.now()
        var nextOrdinal = (versionTakes.compactMap { take -> Int? in
            let base = take.sourceRouteKey.split(separator: "@").first.map(String.init) ?? ""
            guard base.hasPrefix("lens_media_character_") else { return nil }
            return Int(base.dropFirst("lens_media_character_".count).prefix { $0.isNumber })
        }.max() ?? 0) + 1
        var nextImageIndex = (existingHeroImages.map(\.imageIndex).max() ?? 0) + 1

        var result: [ProjectLensHeroImage] = []
        for member in members {
            let prompt = lensCharacterConceptPrompt(
                name: member.name,
                descriptionPrompt: member.prompt,
                signatureProps: member.signatureProps,
                environmentAffinity: member.environmentAffinity,
                settings: studySettings,
                anchorProse: anchorProse,
                theme: lens,
                mediaSummaries: mediaSummaries
            )
            var queued = queuedLensHeroImages(
                lensId: lens.lensId,
                routeKey: "lens_media_character_\(nextOrdinal)\(versionSuffix)",
                recipe: nil,
                sourceAestheticIds: primarySlot.map { [$0.styleId] } ?? [],
                sourceReferenceIds: styleReferenceIds,
                mediaPlan: plan,
                styleAuthorities: styleAuthorities,
                imageKind: LensImageTaxonomyKind.characterImage,
                prompt: prompt,
                now: now
            )
            for index in queued.indices {
                queued[index].label = member.name.trimmed.isEmpty ? "Character \(nextOrdinal)" : "Character · \(member.name)"
                queued[index].imageIndex = nextImageIndex
                queued[index].characterId = member.characterId
                queued[index].sourceRecipeVersion = lensMediaProvenance(lens: lens, plan: plan)
                queued[index].sourceRecipeId = body.styleTreatment?.snapshotIdentifier
                queued[index] = queued[index].normalized()
            }
            result.append(contentsOf: queued)
            nextOrdinal += 1
            nextImageIndex += 1
        }
        return result
    }

    /// Queues the Lens's concept board: one Area image per broad environment, child Scene
    /// images under each Area, then character and object studies. Every generated image
    /// stores explicit Area/Scene taxonomy metadata so the UI does not rely on route keys.
    func queuedLensConceptImages(
        lens: ProjectLens,
        versionId: String,
        mediaSummaries: [String],
        styleReferenceIds: [String],
        styleAuthorities: [LensStyleAuthoritySnapshot] = [],
        // Areas are a flat, imageless grouping now: the scenes are the frames. No
        // establishing "area" render is queued, so the default area has no image.
        includeAreaImages: Bool = false
    ) -> [ProjectLensHeroImage] {
        let normalizedLens = lens.normalized()
        let body = normalizedLens.body.normalized()
        let plan = body.resolvedMediaPlan
        let areas = (body.areas ?? [])
            .map { $0.normalized() }
            .filter { $0.enabled && !$0.scenes.isEmpty }
        guard !areas.isEmpty else { return [] }
        let primarySlot = body.styleTreatment?.normalized().slots.first
        let setDressingPool = body.setDressingImagePrompts ?? []
        let versionSuffix = versionId.isEmpty ? "" : "@\(versionId)"
        let now = DateFormats.now()
        let sceneTotal = max(1, areas.reduce(0) { $0 + $1.scenes.filter(\.enabled).count })
        let studySettings = areas.flatMap { area in
            [area.setting] + area.scenes.map(\.setting)
        }.filter { !$0.isEmpty }
        let anchorSetting = areas.first?.setting
        let anchorProse = areas.first?.prosePrompt ?? ""

        var dressingCursor = 0
        func takeDressing() -> [String] {
            let count = min(plan.setDressingCount, setDressingPool.count)
            guard count > 0 else { return [] }
            return (0..<count).map { _ in
                defer { dressingCursor += 1 }
                return setDressingPool[dressingCursor % setDressingPool.count]
            }
        }

        var images: [ProjectLensHeroImage] = []
        var frameIndex = 0
        let selfHomeSceneImageId = "__self_home_scene_image_id__"
        @discardableResult
        func append(
            routeKey: String,
            label: String,
            prompt: String,
            styleId: String?,
            imageKind: String,
            characterId: String = "",
            areaId: String = "",
            sceneId: String = "",
            areaImageId: String = "",
            homeSceneImageId: String = ""
        ) -> [ProjectLensHeroImage] {
            var queued = queuedLensHeroImages(
                lensId: normalizedLens.lensId,
                routeKey: routeKey,
                recipe: nil,
                sourceAestheticIds: styleId.map { [$0] } ?? [],
                sourceReferenceIds: styleReferenceIds,
                mediaPlan: plan,
                styleAuthorities: styleAuthorities,
                imageKind: imageKind,
                areaId: areaId,
                sceneId: sceneId,
                areaImageId: areaImageId,
                homeSceneImageId: homeSceneImageId == selfHomeSceneImageId ? "" : homeSceneImageId,
                prompt: prompt,
                now: now
            )
            for index in queued.indices {
                queued[index].label = label
                queued[index].imageIndex = frameIndex
                queued[index].characterId = characterId
                queued[index].sourceRecipeVersion = lensMediaProvenance(lens: normalizedLens, plan: plan)
                queued[index].sourceRecipeId = body.styleTreatment?.snapshotIdentifier
                if homeSceneImageId == selfHomeSceneImageId {
                    queued[index].homeSceneImageId = queued[index].imageId
                }
                queued[index] = queued[index].normalized()
            }
            images.append(contentsOf: queued)
            frameIndex += 1
            return queued
        }

        var sceneOrdinal = 0
        for (areaIndex, area) in areas.enumerated() {
            let areaTitle = area.title.nilIfEmpty ?? anchorTitle(area.setting, fallback: "Area \(areaIndex + 1)")
            let areaQueued = includeAreaImages
                ? append(
                    routeKey: "lens_media_area_\(areaIndex + 1)\(versionSuffix)",
                    label: "Area · \(areaTitle)",
                    prompt: lensSceneryConceptPrompt(
                        setting: area.setting,
                        prosePrompt: area.prosePrompt,
                        setDressingPrompts: takeDressing(),
                        beatLabel: "",
                        sceneryIndex: areaIndex,
                        sceneryCount: areas.count,
                        theme: normalizedLens
                    ),
                    styleId: primarySlot?.styleId,
                    imageKind: LensImageTaxonomyKind.areaImage,
                    areaId: area.areaId
                )
                : []
            let areaImageId = areaQueued.first?.imageId ?? ""
            for (sceneIndex, scene) in area.scenes.filter(\.enabled).enumerated() {
                // Sequence plans keep their journey beats; collection plans carry the
                // scene's own story beat (empty on plans composed before beats existed).
                let beat = plan.isSequence ? plan.beatLabel(forCompositeIndex: sceneOrdinal) : scene.storyBeat
                let title = scene.title.nilIfEmpty ?? scene.setting.title.nilIfEmpty ?? "Scene \(sceneIndex + 1)"
                append(
                    routeKey: "lens_media_area_\(areaIndex + 1)_scene_\(sceneIndex + 1)\(versionSuffix)",
                    label: !beat.isEmpty ? "\(title) · \(beat)" : title,
                    prompt: lensSceneryConceptPrompt(
                        setting: scene.setting,
                        prosePrompt: scene.prosePrompt,
                        sceneCast: scene.cast,
                        setDressingPrompts: takeDressing(),
                        beatLabel: beat,
                        sceneryIndex: sceneOrdinal,
                        sceneryCount: sceneTotal,
                        theme: normalizedLens
                    ),
                    styleId: primarySlot?.styleId,
                    imageKind: LensImageTaxonomyKind.sceneImage,
                    areaId: area.areaId,
                    sceneId: scene.sceneId,
                    areaImageId: areaImageId,
                    homeSceneImageId: selfHomeSceneImageId
                )
                sceneOrdinal += 1
            }
        }

        // Character studies, primary style.
        let cast = lensCompositeCast(for: normalizedLens).prefix(max(0, plan.characterCount))
        for (castIndex, member) in cast.enumerated() {
            append(
                routeKey: "lens_media_character_\(castIndex + 1)\(versionSuffix)",
                label: member.name.trimmed.isEmpty ? "Character \(castIndex + 1)" : "Character · \(member.name)",
                prompt: lensCharacterConceptPrompt(
                    name: member.name,
                    descriptionPrompt: member.prompt,
                    signatureProps: member.signatureProps,
                    environmentAffinity: member.environmentAffinity,
                    settings: studySettings,
                    anchorProse: anchorProse,
                    theme: normalizedLens,
                    mediaSummaries: mediaSummaries
                ),
                styleId: primarySlot?.styleId,
                imageKind: LensImageTaxonomyKind.characterImage,
                characterId: member.characterId
            )
        }

        // Object studies, primary style.
        let concepts = body.objectConcepts ?? []
        let objectProse = body.objectImagePrompts ?? []
        let objectTotal = min(max(concepts.count, objectProse.count), max(0, plan.castObjectCount))
        if objectTotal > 0 {
            for objectIndex in 0..<objectTotal {
                let concept = concepts.indices.contains(objectIndex) ? concepts[objectIndex] : nil
                let fallback = objectProse.indices.contains(objectIndex) ? objectProse[objectIndex] : ""
                let title = concept?.name.nilIfEmpty ?? "Object \(objectIndex + 1)"
                append(
                    routeKey: "lens_media_object_\(objectIndex + 1)\(versionSuffix)",
                    label: "Object · \(title)",
                    prompt: lensObjectConceptPrompt(
                        concept: concept,
                        prosePrompt: fallback,
                        anchorSetting: anchorSetting,
                        anchorProse: anchorProse,
                        theme: normalizedLens
                    ),
                    styleId: primarySlot?.styleId,
                    imageKind: LensImageTaxonomyKind.objectImage
                )
            }
        }
        return images
    }

    private func anchorTitle(_ setting: LensSceneSetting?, fallback: String) -> String {
        setting?.title.nilIfEmpty ?? fallback
    }


    /// Compact provenance stamped on each media version's images: the blend recipe plus
    /// the plan facts that shaped the render ("60% A · 25% B | seq · 3:2 · 2C+1O · rich").
    private func lensMediaProvenance(lens: ProjectLens, plan: LensMediaPlan) -> String? {
        var parts: [String] = []
        if plan.isSequence { parts.append("seq") }
        if plan.aspect != "square" { parts.append(plan.stabilityAspectRatio) }
        parts.append("\(plan.characterCount)C+\(plan.castObjectCount)O")
        if lens.body.setDressingImagePrompts?.isEmpty == false, plan.setDressingCount > 0 {
            parts.append("dressing \(plan.setDressingDensity)")
        }
        if plan.allowReadableText { parts.append("text ok") }
        let planSummary = parts.joined(separator: " · ")
        guard let recipe = lens.body.styleTreatment?.recipeText, !recipe.isEmpty else {
            return planSummary.isEmpty ? nil : planSummary
        }
        return planSummary.isEmpty ? recipe : "\(recipe) | \(planSummary)"
    }

    /// Flips media images stranded in active generation (app crash, kill, network drop
    /// mid-run) to failed so retry affordances appear. Planned queued rows are not
    /// failures; they simply have not started yet.
    static func lensesWithInterruptedMediaReconciled(_ lenses: [ProjectLens], now: String) -> (lenses: [ProjectLens], changedCount: Int) {
        var changedCount = 0
        let reconciled = lenses.map { lens -> ProjectLens in
            var updated = lens
            var changed = false
            updated.heroImages = updated.heroImages.map { image in
                guard image.status == "generating" else { return image }
                var repaired = image
                repaired.status = "failed"
                repaired.errorMessage = "Rendering was interrupted for this media."
                repaired.updatedAt = now
                changed = true
                return repaired
            }
            if changed {
                changedCount += 1
                if updated.generationPhase == "hero_generating" || updated.generationPhase == "hero_queued" {
                    updated.generationError = ""
                }
                updated.heroImage = updated.primaryHeroImage
                updated.updatedAt = now
                return updated.normalized()
            }
            return lens
        }
        return (reconciled, changedCount)
    }

    private func reconcileInterruptedLensMedia(for project: ProjectRecord) {
        guard !isGeneratingLensHero, !isGeneratingInitialDraftLenses else { return }
        let now = DateFormats.now()
        let (reconciled, changedCount) = Self.lensesWithInterruptedMediaReconciled(projectLenses.lenses, now: now)
        guard changedCount > 0 else { return }
        var updated = projectLenses
        updated.updateActiveVersion(lenses: reconciled, now: now)
        if saveLensSet(updated, for: project, status: "Recovered \(changedCount) Scene Plan\(changedCount == 1 ? "" : "es") with interrupted media") {
            print("[lens_media_reconcile] marked interrupted media failed lens_count=\(changedCount) project_id=\(project.projectId)")
        }
    }

    /// Self-contained source prompt for treatment-backed Lens heroes. Written for an image
    /// model with no other context: no product names, no identifiers, explicit reference-image
    /// usage, and the four-panel structure as a hard requirement.
    private func treatmentLensHeroPrompt(
        theme: ProjectLens,
        goalBrief: ProjectGoalBrief,
        mediaSummaries: [String]
    ) -> String {
        let promptSafe = PromptSafeLensSnapshot.from(lens: theme)
        let resolved = promptSafe.resolvedVisualLanguage
        var lines: [String] = []
        lines.append("Create one square image composed as exactly four equal panels in a 2x2 grid separated by thin margins. Each panel shows a DIFFERENT subject from the same story world: one panel a figure or creature moment, one a wider scenery or setting view, one an object or prop detail, one an atmosphere or texture study. All four panels share one unified visual style. The 2x2 four-panel layout is a hard requirement.")
        lines.append("")
        // Treatment-backed heroes attach a style image that alone governs rendering, so
        // the text carries subject matter only: motifs and composition are subjects and
        // spatial facts; look/palette/materials/energy language would override the image.
        let motifs = uniqueNonEmpty(resolved.motifs).prefixArray(8)
        if !motifs.isEmpty {
            lines.append("Motifs: \(motifs.joined(separator: ", "))")
        }
        let composition = uniqueNonEmpty(resolved.composition).prefixArray(8)
        if !composition.isEmpty {
            lines.append("Composition: \(composition.joined(separator: ", "))")
        }
        let avoid = uniqueNonEmpty(promptSafe.mustAvoid).prefixArray(10)
        if !avoid.isEmpty {
            lines.append("Strictly avoid: \(avoid.joined(separator: ", "))")
        }
        lines.append("")
        var worldLines: [String] = []
        if !goalBrief.goal.trimmed.isEmpty {
            worldLines.append(goalBrief.goal.trimmed)
        }
        if !goalBrief.storyPromise.trimmed.isEmpty {
            worldLines.append(goalBrief.storyPromise.trimmed)
        }
        if !worldLines.isEmpty {
            lines.append("Story world (draw all four subjects from this world): \(uniqueNonEmpty(worldLines).joined(separator: " "))")
        }
        let glimpses = lensHeroArchiveGlimpses(mediaSummaries)
        if !glimpses.isEmpty {
            lines.append("Real glimpses of this world, usable as subject grounding: \(glimpses.joined(separator: "; "))")
        }
        lines.append("Do not render readable paragraphs of text; any typography stays graphic and minimal.")
        return lines.filter { !$0.isEmpty || $0 == "" }.joined(separator: "\n")
    }

    private func lensHeroPrompt(
        theme: ProjectLens,
        goalBrief: ProjectGoalBrief,
        mediaSummaries: [String]
    ) -> String {
        if theme.body.styleTreatment?.isEmpty == false {
            return treatmentLensHeroPrompt(theme: theme, goalBrief: goalBrief, mediaSummaries: mediaSummaries)
        }
        let promptSafe = PromptSafeLensSnapshot.from(lens: theme)
        let resolved = promptSafe.resolvedVisualLanguage
        let visualSummary = uniqueNonEmpty([
            promptSafe.claim,
            promptSafe.visualSummary,
            resolved.look
        ]).joined(separator: " ")
        let treatmentNotes = uniqueNonEmpty(
            resolved.materials
                + resolved.productTreatment
                + resolved.composition
                + resolved.pacingEnergy
        ).joined(separator: ", ")
        let palette = uniqueNonEmpty(resolved.palette + resolved.motifs).joined(separator: ", ")
        let avoidTerms = uniqueNonEmpty(promptSafe.mustAvoid + resolved.avoid).joined(separator: ", ")
        let core = resolved.look.trimmed.isEmpty ? "project-local resolved visual treatment" : resolved.look
        let flavor = uniqueNonEmpty(resolved.materials + resolved.productTreatment + resolved.composition)
            .prefixArray(6)
            .joined(separator: ", ")

        let frameApplication = "one square hero image for a saved project Lens card, showing the project's source world through this manually assembled visual treatment"
        return aestheticCompositePrompt(from: AestheticCompositePromptFields(
            subjectCapsule: lensHeroProjectCapsule(goalBrief: goalBrief, mediaSummaries: mediaSummaries),
            directionLabel: "project-local visual treatment",
            core: core,
            flavor: flavor,
            visualSummary: visualSummary,
            treatmentNotes: treatmentNotes,
            palette: palette,
            frameApplication: frameApplication,
            avoidTerms: avoidTerms
        ))
    }

    private func lensWAN25MotionPrompt(lens: ProjectLens, image: ProjectLensHeroImage) -> String {
        let body = lens.body.normalized()
        let resolved = body.resolvedVisualLanguageForSceneStory
        let styleSummary = image.styleAuthorities
            .map { $0.normalized().oneLineStyleSummary }
            .first { !$0.isEmpty } ?? ""
        let subject = image.subject?.normalized()
        let subjectLine = uniqueNonEmpty([
            subject?.kind.rawValue ?? "",
            subject?.description ?? "",
            image.label
        ]).joined(separator: " · ")
        var lines: [String] = []
        lines.append("Animate this rendered frame as a short cinematic motion study.")
        lines.append("Preserve the source image composition, character/object identity, visual style, palette, and framing. Do not invent a new scene.")
        if !body.title.isEmpty {
            lines.append("Lens: \(body.title)")
        }
        if !body.claim.isEmpty {
            lines.append("Dramatic claim: \(body.claim)")
        }
        if !subjectLine.isEmpty {
            lines.append("Artifact subject: \(subjectLine)")
        }
        let mood = uniqueNonEmpty(resolved.pacingEnergy + resolved.motifs + resolved.composition)
            .prefixArray(6)
            .joined(separator: ", ")
        if !mood.isEmpty {
            lines.append("Motion language: slow parallax, atmospheric drift, subtle camera presence, \(mood).")
        } else {
            lines.append("Motion language: slow parallax, atmospheric drift, subtle camera presence, no abrupt action.")
        }
        if !styleSummary.isEmpty {
            lines.append("Style authority: \(styleSummary)")
        } else if !resolved.look.isEmpty {
            lines.append("Style authority: \(resolved.look)")
        }
        lines.append("Keep it restrained: no cuts, no captions, no logos, no new major subjects, no sudden transformation.")
        return lines.joined(separator: "\n")
    }

    private func lensHeroProjectCapsule(goalBrief: ProjectGoalBrief, mediaSummaries: [String]) -> String {
        let intent = goalBrief.aestheticIntent.normalized()
        let motifs = uniqueNonEmpty(intent.motifHints).prefixArray(6)
        let moods = uniqueNonEmpty(intent.visualMood + intent.emotionalTargets)
            .filter { !motifs.contains($0) }
            .prefixArray(6)
        let palette = uniqueNonEmpty(intent.paletteHints)
            .filter { !motifs.contains($0) && !moods.contains($0) }
            .prefixArray(6)
        let glimpses = lensHeroArchiveGlimpses(mediaSummaries)
        var pieces = [
            goalBrief.storyPromise,
            goalBrief.goal
        ]
        if !motifs.isEmpty {
            pieces.append("motifs: \(motifs.joined(separator: ", "))")
        }
        if !moods.isEmpty {
            pieces.append("mood: \(moods.joined(separator: ", "))")
        }
        if !palette.isEmpty {
            pieces.append("palette: \(palette.joined(separator: ", "))")
        }
        if !glimpses.isEmpty {
            pieces.append("source world glimpses: \(glimpses.joined(separator: "; "))")
        }
        return pieces
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: "\n")
    }

    private func lensHeroSourceAestheticIds(_ theme: ProjectLens) -> [String] {
        uniqueNonEmpty(theme.body.styleIngredients.flatMap(\.referenceAestheticIds))
    }

    private func lensHeroSourceReferenceIds(_ theme: ProjectLens) -> [String] {
        uniqueNonEmpty(theme.body.styleIngredients.flatMap(\.sourceReferenceIds))
    }

    /// Attachment plan for one Lens media render: treatment-driven style entries (with
    /// catalog fallback when persisted ingredients are stale), the canonical subject
    /// anchor, per-frame character references, and continuity images from earlier
    /// renders in the same run. The plan is the only producer of attachments and of the
    /// prompt manifest that describes them.
    ///
    /// Characters are a per-frame concern: a character study attaches only ITS OWN
    /// character's references (characterScopeId), and every other frame attaches none —
    /// @mentions in the Frame Creator are how characters enter a specific frame.
    private func lensBlendAttachmentPlan(
        lens: ProjectLens,
        catalog: StyleBrowseCatalog?,
        assignedStyleId: String? = nil,
        characterScopeId: String? = nil,
        continuityURLs: [URL]
    ) -> LensBlendAttachmentPlan {
        let mediaPlan = lens.body.resolvedMediaPlan
        let plan = LensBlendAttachmentPlan.make(
            treatment: lens.body.styleTreatment,
            ingredients: lens.body.styleIngredients,
            catalog: catalog,
            assignedStyleId: assignedStyleId,
            subjectAnchor: lensCanonicalAnchorInput(for: lens),
            characterReferences: lensCharacterReferenceInputs(characterId: characterScopeId),
            continuityURLs: continuityURLs,
            sequenceContinuity: mediaPlan.isSequence
        )
        for warning in plan.warnings {
            print("[lens_blend_plan] warning lens_id=\(lens.lensId) message=\"\(warning)\"")
        }
        return plan
    }

    /// Resolves the lens's canonical anchor to a readable local image, or nil.
    private func lensCanonicalAnchorInput(for lens: ProjectLens) -> (caption: String, url: URL)? {
        guard let anchor = lens.body.canonicalAnchor, !anchor.isEmpty,
              let item = items.first(where: { $0.mediaId == anchor.mediaId }),
              item.kind == .image,
              FileManager.default.fileExists(atPath: item.path) else {
            return nil
        }
        return (anchor.caption.trimmed.isEmpty ? "canonical subject" : anchor.caption, URL(fileURLWithPath: item.path))
    }

    /// Resolves ONE roster character (the frame's character scope) to their leading
    /// (up to 2) local reference images. Nil/empty scope → no character references.
    private func lensCharacterReferenceInputs(characterId scopeId: String?) -> [LensBlendAttachmentPlan.CharacterReferenceInput] {
        guard let scopeId, !scopeId.isEmpty else { return [] }
        return [scopeId].compactMap { characterId in
            guard let character = projectCharacters.character(withId: characterId) else {
                print("[lens_blend_plan] scoped character missing character_id=\(characterId)")
                return nil
            }
            let attachments = character.referenceMediaIds
                .compactMap { mediaId -> (mediaId: String, item: MediaItemRecord)? in
                    guard let item = items.first(where: { $0.mediaId == mediaId }) else { return nil }
                    return (mediaId, item)
                }
                .filter { $0.item.kind == .image && FileManager.default.fileExists(atPath: $0.item.path) }
                .prefix(2)
            guard !attachments.isEmpty else {
                print("[lens_blend_plan] character has no usable reference media name=\"\(character.name)\"")
                return nil
            }
            return .init(
                name: character.name,
                urls: attachments.map { URL(fileURLWithPath: $0.item.path) },
                labels: attachments.map { character.referenceLabels[$0.mediaId] ?? "" }
            )
        }
    }

    /// Best-effort cached style catalog for slot→reference fallback resolution; a miss
    /// only disables the fallback, it never blocks generation.
    private func styleBrowseCatalogForAttachmentFallback() async -> StyleBrowseCatalog? {
        try? await StyleBrowseCatalogRuntime.shared.loadCatalog()
    }

    private func generatedTakeStyleSelection(
        slot rawSlot: LensStyleTreatmentSlot,
        catalog: StyleBrowseCatalog?,
        fallbackCatalogVersion: String
    ) -> (slot: LensStyleTreatmentSlot, authority: LensStyleAuthoritySnapshot, catalogVersion: String)? {
        let slot = rawSlot.normalized()
        guard !slot.styleId.isEmpty else { return nil }
        let style = catalog?.style(withId: slot.styleId)
        let catalogVersion = catalog?.version.trimmed.nilIfEmpty ?? fallbackCatalogVersion.trimmed
        let reference = style?.styleImageReference(catalogVersion: catalogVersion)
        let title = reference?.title
            ?? style?.displayLabel
            ?? slot.label.trimmed.nilIfEmpty
            ?? slot.styleId
        let imageUrl = reference?.url ?? style?.url ?? slot.url
        let authority = LensStyleAuthoritySnapshot(
            authorityId: "",
            role: "primary",
            source: generatedTakeStyleAuthoritySource(reference: reference),
            referenceId: slot.styleId,
            sourceReferenceId: reference?.sourceReferenceId ?? "",
            title: title,
            imageUrl: imageUrl,
            imagePath: "",
            oneLineStyleSummary: style?.styleSummaryLine ?? "",
            weight: 100
        ).normalized(order: 0)
        return (slot, authority, catalogVersion)
    }

    private func lensApplyingStyleSlotOverride(
        _ lens: ProjectLens,
        slot rawSlot: LensStyleTreatmentSlot,
        catalogVersion: String
    ) -> ProjectLens {
        let slot = rawSlot.normalized()
        guard !slot.styleId.isEmpty else { return lens }
        var copy = lens
        var body = copy.body
        body.styleTreatment = LensStyleTreatment(
            catalogVersion: catalogVersion,
            primary: slot,
            accents: [],
            updatedAt: DateFormats.now()
        ).normalized()
        body.styleIngredients = []
        copy.body = body.normalized()
        return copy.normalized()
    }

    private func lensApplyingTakeStyleOverride(_ lens: ProjectLens, image: ProjectLensHeroImage) -> ProjectLens {
        let preferredStyleId = image.sourceAestheticIds.first ?? ""
        let authority = image.styleAuthorities
            .map { $0.normalized() }
            .first { !$0.referenceId.isEmpty && $0.referenceId == preferredStyleId }
            ?? image.styleAuthorities.first?.normalized()
        guard let authority, !authority.referenceId.isEmpty else { return lens }
        let slot = LensStyleTreatmentSlot(
            styleId: authority.referenceId,
            label: authority.title,
            collection: "",
            hueHex: "",
            url: authority.imageUrl.isEmpty ? authority.imagePath : authority.imageUrl,
            weight: 100
        )
        var copy = lens
        var body = copy.body
        body.styleTreatment = LensStyleTreatment(
            catalogVersion: image.sourceRecipeVersion ?? lens.body.styleTreatment?.catalogVersion ?? "",
            primary: slot,
            accents: [],
            updatedAt: DateFormats.now()
        ).normalized()
        body.styleIngredients = []
        copy.body = body.normalized()
        return copy.normalized()
    }

    private func takeStyleSummary(_ image: ProjectLensHeroImage) -> String {
        takeStyleSummary(styleAuthorities: image.styleAuthorities, preferredStyleId: image.sourceAestheticIds.first)
    }

    private func takeStyleSummary(
        styleAuthorities: [LensStyleAuthoritySnapshot],
        preferredStyleId: String?
    ) -> String {
        let preferredStyleId = preferredStyleId ?? ""
        let authority = styleAuthorities
            .map { $0.normalized() }
            .first { !$0.referenceId.isEmpty && $0.referenceId == preferredStyleId }
            ?? styleAuthorities.first?.normalized()
        guard let authority else { return "" }
        return authority.oneLineStyleSummary.isEmpty ? authority.title : authority.oneLineStyleSummary
    }

    @discardableResult
    func setLensHeroImageStyle(
        lensId: String,
        imageId: String,
        slot: LensStyleTreatmentSlot,
        catalogVersion: String
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        var catalog = StyleBrowseCatalog.empty
        do {
            catalog = try await StyleBrowseCatalogRuntime.shared.loadCatalog()
        } catch {
            print("[lens_take_style] style catalog unavailable, falling back to selected slot metadata: \(error.localizedDescription)")
        }
        let style = catalog.style(withId: slot.styleId)
        let resolvedCatalogVersion = catalog.version.trimmed.isEmpty ? catalogVersion : catalog.version
        let reference = style?.styleImageReference(catalogVersion: resolvedCatalogVersion)
        let title = style?.displayLabel ?? slot.label
        let imageUrl = reference?.url ?? style?.url ?? slot.url
        let summary = style?.styleSummaryLine ?? ""
        let now = DateFormats.now()
        let authority = LensStyleAuthoritySnapshot(
            authorityId: "",
            role: "primary",
            source: .styleCatalog,
            referenceId: slot.styleId,
            sourceReferenceId: reference?.sourceReferenceId ?? "",
            title: title,
            imageUrl: imageUrl,
            imagePath: "",
            oneLineStyleSummary: summary,
            weight: 100
        ).normalized(order: 0)

        var updated = projectLenses
        var lenses = updated.lenses
        guard let lensIndex = lenses.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        var heroImages = lenses[lensIndex].heroImages
        guard let imageIndex = heroImages.firstIndex(where: { $0.imageId == imageId }) else {
            aestheticStatus = "Take not found"
            return false
        }
        var image = heroImages[imageIndex]
        let existingNonStyleDependencies = image.sourceDependencies
            .filter { $0.normalized().role != "style_source" }
        image.styleAuthorities = [authority]
        image.sourceAestheticIds = [slot.styleId]
        image.sourceRecipeVersion = resolvedCatalogVersion
        image.sourceDependencies = existingNonStyleDependencies + generatedTakeStyleSourceDependencies(
            styleAuthorities: [authority],
            sourceReferenceIds: reference.map { [$0.sourceReferenceId] } ?? []
        )
        image.updatedAt = now
        heroImages[imageIndex] = image.normalized()
        lenses[lensIndex].heroImages = heroImages
        lenses[lensIndex].heroImage = lenses[lensIndex].primaryHeroImage
        lenses[lensIndex].updatedAt = now
        lenses[lensIndex] = lenses[lensIndex].normalized()
        updated.updateActiveVersion(lenses: lenses, now: now)
        aestheticStatus = "Updated take style"
        return saveLensSet(updated, for: project, status: "Updated take style")
    }

    @discardableResult
    func setLensEnabled(lensId: String, enabled: Bool) -> Bool {
        guard let project = currentProject else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let now = DateFormats.now()
        themes[index].enabled = enabled
        themes[index].status = .ready
        themes[index].updatedAt = now
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lensId,
            selectedScratchId: nil,
            changeSummary: enabled ? "Enabled Scene Plan." : "Disabled Scene Plan.",
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: enabled ? "Scene Plan enabled" : "Scene Plan disabled")
    }

    @discardableResult
    func markLensReady(_ lensId: String) -> Bool {
        guard let project = currentProject else { return false }
        var updated = projectLenses
        var themes = updated.lenses
        guard let index = themes.firstIndex(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return false
        }
        let report = themes[index].body.readinessReport
        let now = DateFormats.now()
        themes[index].status = .ready
        themes[index].enabled = true
        themes[index].readyReadinessIssues = uniqueReadinessIssues(report.blockingIssues + report.warnings)
        themes[index].updatedAt = now
        let issueCount = themes[index].readyReadinessIssues.count
        updated.appendVersion(
            lenses: themes,
            scratchDrafts: updated.scratchDrafts,
            selectedLensId: lensId,
            selectedScratchId: nil,
            changeSummary: issueCount > 0 ? "Marked Scene Plan Ready with \(issueCount) warning\(issueCount == 1 ? "" : "s")." : "Marked Scene Plan Ready.",
            model: "local-edit",
            now: now
        )
        return saveLensSet(updated, for: project, status: "Scene Plan Ready")
    }

