        guard !isScanning else { return }
        guard !isAnalyzingMedia else {
            mediaAnalysisStatus = "Finish media analysis before adding media"
            return
        }

        let panel = NSOpenPanel()
        panel.title = "Add Media"
        panel.message = "Choose photos, videos, or audio files to add to this project."
