    func importGoalChatImageData(_ data: Data) async -> MediaItemRecord? {
        guard let project = currentProject else {
            goalStatus = "Create or select a project first"
            return nil
        }
        do {
            let normalized = try normalizedJPEGData(from: data)
            let sha = sha256Hex(normalized.data)
            if let existing = items.first(where: {
                $0.derivativeKind == MediaItemRecord.chatAttachmentDerivativeKind
                    && $0.mediaId == goalChatAttachmentMediaId(project: project, sha256: sha)
            }) {
                goalStatus = "Image already attached"
                return existing
            }

            let directory = store.chatAttachmentsDirectory(for: project)
            try ensureDirectory(directory)
            let filename = "goal_chat_\(String(sha.prefix(16))).jpg"
            let outputURL = directory.appendingPathComponent(filename)
            if !FileManager.default.fileExists(atPath: outputURL.path) {
                try normalized.data.write(to: outputURL, options: [.atomic])
            }
            let mediaId = goalChatAttachmentMediaId(project: project, sha256: sha)
            guard let item = await archiveGeneratedMedia(
                fileURL: outputURL,
                project: project,
                mediaId: mediaId,
                derivativeKind: MediaItemRecord.chatAttachmentDerivativeKind,
                sourceMediaId: nil,
                filename: filename,
                tags: ["goal-chat"],
                notes: "Pasted image attached to GOAL chat.",
                rejectedByDefault: false
            ) else {
                goalStatus = "Could not attach pasted image"
                return nil
            }
            goalStatus = "Attached pasted image"
            return item
        } catch {
            lastError = error.localizedDescription
            goalStatus = "Could not attach pasted image"
            return nil
        }
    }

    func beginScreenAreaRecordingSelection() {
        guard let project = currentProject else {
            scanStatus = "Create or select a project first"
            return
        }
        guard !isScanning else {
            scanStatus = "Finish scanning before recording"
            return
        }
        guard !isAnalyzingMedia else {
            mediaAnalysisStatus = "Finish media analysis before recording"
            return
        }
        guard screenAreaRecordingPhase == .idle
            || screenAreaRecordingPhase == .failed
            || screenAreaRecordingPhase == .needsPermission else { return }
        guard requestScreenRecordingPermissionIfNeeded() else { return }

        screenAreaRecordingPhase = .selecting
        screenAreaRecordingStatus = "Drag to select a screen area"
        scanStatus = "Select screen area"
        lastError = ""

        Task { [weak self] in
            guard let self else { return }
            do {
                let selection = try await ScreenAreaSelectionController().selectArea()
                await self.startScreenAreaRecording(selection: selection, project: project)
            } catch ScreenAreaSelectionError.cancelled {
                self.cancelScreenAreaRecordingSelection()
            } catch {
                self.failScreenAreaRecording(error)
            }
        }
    }

    func stopScreenAreaRecording() {
        guard screenAreaRecordingPhase == .recording else { return }
        screenAreaAutoStopTask?.cancel()
        screenAreaAutoStopTask = nil
        screenAreaRecordingPhase = .finalizing
        screenAreaRecordingStatus = "Saving screen recording"
        scanStatus = "Saving screen recording"

        Task { [weak self] in
            guard let self else { return }
            do {
                let result = try await self.screenAreaRecorder.stopRecording()
                await self.importScreenAreaRecording(result)
            } catch {
                self.failScreenAreaRecording(error)
            }
        }
    }

    func cancelScreenAreaRecording() {
        screenAreaAutoStopTask?.cancel()
        screenAreaAutoStopTask = nil
        Task { [weak self] in
            await self?.screenAreaRecorder.cancelRecording()
        }
        resetScreenAreaRecordingState()
        scanStatus = items.isEmpty ? "Add media or rescan" : "\(items.count) media item\(items.count == 1 ? "" : "s") indexed"
    }

    func beginCameraRecorder() {
        guard canOpenCameraRecorder else {
            cameraRecordingStatus = currentProject == nil ? "Create or select a project first." : "Finish the current Media task first."
            scanStatus = cameraRecordingStatus
            return
        }
        guard cameraRecordingPhase != .recording && cameraRecordingPhase != .finalizing else { return }
        prepareCameraRecorder()
    }

    func prepareCameraRecorder() {
        guard currentProject != nil else {
            cameraRecordingStatus = "Create or select a project first."
            return
        }
        guard cameraRecordingPhase != .recording && cameraRecordingPhase != .finalizing else { return }

        refreshCameraDevices()
        cameraRecordingPhase = .preparing
        cameraRecordingStatus = "Preparing camera preview"
        scanStatus = "Preparing camera"
        lastError = ""

        Task { [weak self] in
            guard let self else { return }
            guard await CameraRecorder.requestCameraAccess() else {
                self.cameraRecordingPhase = .needsCameraPermission
                self.cameraPreviewSession = nil
                self.cameraRecordingStatus = "macOS has not granted Camera access to LitScenes. Enable Camera in System Settings, then reopen the recorder."
                self.scanStatus = "Camera permission required"
                return
            }

            if self.cameraIncludeMicrophone {
                let microphoneGranted = await CameraRecorder.requestMicrophoneAccess()
                if !microphoneGranted {
                    self.cameraIncludeMicrophone = false
                    self.cameraRecordingStatus = "Microphone permission was not granted; recording video only."
                }
            }

            do {
                self.refreshCameraDevices()
                let settings = self.currentCameraRecordingSettings()
                try self.cameraRecorder.prepare(settings: settings)
                self.cameraPreviewSession = self.cameraRecorder.session
                self.cameraRecordingPhase = .ready
                if self.cameraRecordingStatus.isEmpty || self.cameraRecordingStatus == "Preparing camera preview" {
                    self.cameraRecordingStatus = "Camera ready"
                }
                self.scanStatus = "Camera ready"
            } catch {
                self.failCameraRecording(error)
            }
        }
    }

    func closeCameraRecorder() {
        guard cameraRecordingPhase != .recording && cameraRecordingPhase != .finalizing else {
            noteCameraRecorderWindowCloseBlocked()
            return
        }
        cameraRecorder.stopPreview()
        cameraPreviewSession = nil
        if cameraRecordingPhase != .needsCameraPermission {
            cameraRecordingPhase = .idle
        }
    }

    func noteCameraRecorderWindowCloseBlocked() {
        cameraRecordingStatus = "Stop or cancel the camera recording before closing this window."
    }

    func selectCameraVideoDevice(_ deviceId: String) {
        cameraSelectedVideoDeviceId = deviceId
        prepareCameraRecorder()
    }

    func selectCameraAudioDevice(_ deviceId: String) {
        cameraSelectedAudioDeviceId = deviceId
        CaptureAudioInputPreference.deviceId = deviceId
        if cameraIncludeMicrophone {
            prepareCameraRecorder()
        }
    }

    func setCameraIncludeMicrophone(_ includeMicrophone: Bool) {
        cameraIncludeMicrophone = includeMicrophone
        prepareCameraRecorder()
    }

    func setCameraCaptureFrames(_ captureFrames: Bool) {
        cameraCaptureFrames = captureFrames
    }

    func setCameraFrameRate(_ frameRate: Int) {
        cameraFrameRate = min(max(frameRate, 1), 10)
    }

    func setCameraFrameCapSeconds(_ seconds: Double) {
        cameraFrameCapSeconds = min(max(seconds, 1), 30)
    }

    func startCameraRecording() {
        guard let project = currentProject else {
            cameraRecordingStatus = "Create or select a project first."
            return
        }
        guard !isScanning else {
            cameraRecordingStatus = "Finish scanning before recording."
            return
        }
        guard !isAnalyzingMedia else {
            cameraRecordingStatus = "Finish media analysis before recording."
            return
        }

        Task { [weak self] in
            guard let self else { return }
            do {
                guard await CameraRecorder.requestCameraAccess() else {
                    self.cameraRecordingPhase = .needsCameraPermission
                    self.cameraPreviewSession = nil
                    self.cameraRecordingStatus = "macOS has not granted Camera access to LitScenes. Enable Camera in System Settings, then reopen the recorder."
                    self.scanStatus = "Camera permission required"
                    return
                }

                if self.cameraIncludeMicrophone {
                    let microphoneGranted = await CameraRecorder.requestMicrophoneAccess()
                    if !microphoneGranted {
                        self.cameraIncludeMicrophone = false
                        self.cameraRecordingStatus = "Microphone permission was not granted; recording video only."
                    }
                }

                self.refreshCameraDevices()
                let outputDirectory = self.store.cameraRecordingsDirectory(for: project)
                try ensureDirectory(outputDirectory)
                let outputURL = outputDirectory.appendingPathComponent("\(self.cameraRecordingFilename()).mp4")
                let settings = self.currentCameraRecordingSettings()
                try self.cameraRecorder.prepare(settings: settings)
                try self.cameraRecorder.startRecording(outputURL: outputURL, settings: settings)
                guard self.currentProject?.projectId == project.projectId else {
                    self.cameraRecorder.cancelRecording()
                    self.resetCameraRecordingState()
                    return
                }
                self.cameraRecordingProjectId = project.projectId
                self.cameraPreviewSession = self.cameraRecorder.session
                self.cameraRecordingStartedAt = Date()
                self.cameraRecordingPhase = .recording
                self.cameraRecordingStatus = settings.includeMicrophone ? "Recording camera and microphone" : "Recording camera"
                self.scanStatus = "Recording camera"
            } catch {
                self.failCameraRecording(error)
            }
        }
    }

    func stopCameraRecording() {
        guard cameraRecordingPhase == .recording else { return }
        cameraRecordingPhase = .finalizing
        cameraRecordingStatus = "Saving camera recording"
        scanStatus = "Saving camera recording"

        Task { [weak self] in
            guard let self else { return }
            do {
                let result = try await self.cameraRecorder.stopRecording()
                await self.importCameraRecording(result, expectedProjectId: self.cameraRecordingProjectId)
            } catch {
                self.failCameraRecording(error)
            }
        }
    }

    func cancelCameraRecording() {
        cameraRecorder.cancelRecording()
        resetCameraRecordingState()
        scanStatus = items.isEmpty ? "Add media or rescan" : "\(items.count) media item\(items.count == 1 ? "" : "s") indexed"
    }

