    func analyzeUnanalyzedEnabledMedia() async {
        guard let project = currentProject else {
            mediaAnalysisStatus = "Create or select a project first"
            return
        }
        guard !isScanning else {
            mediaAnalysisStatus = "Finish scanning before analysis"
            return
        }
        guard !isAnalyzingMedia else { return }

        let targetItems = unanalyzedEnabledContentItems
        guard !targetItems.isEmpty else {
            mediaAnalysisStatus = "All enabled content already has saved analysis"
            return
        }
        guard isOpenAICredentialConfigured else {
            mediaAnalysisStatus = Self.missingOpenAIKeyAnalysisStatus
            return
        }

        await analyzeMediaItems(
            targetItems,
            project: project,
            startMessage: "Starting analysis for \(targetItems.count) unanalyzed enabled content item\(targetItems.count == 1 ? "" : "s") in \(project.name).",
            usesSingleItemStatus: false
        )
    }

    func canAnalyzeMediaItem(_ item: MediaItemRecord) -> Bool {
        currentProject != nil
            && item.kind == .image
            && items.contains { $0.mediaId == item.mediaId }
            && !isScanning
            && !isAnalyzingMedia
    }

    func analyzeMediaItem(_ item: MediaItemRecord) async {
        guard let project = currentProject else {
            mediaAnalysisStatus = "Create or select a project first"
            return
        }
        guard !isScanning else {
            mediaAnalysisStatus = "Finish scanning before analysis"
            return
        }
        guard !isAnalyzingMedia else { return }
        guard item.kind == .image else {
            mediaAnalysisStatus = "Only image media can be analyzed"
            return
        }
        guard let currentItem = items.first(where: { $0.mediaId == item.mediaId }) else {
            mediaAnalysisStatus = "Media item is no longer in this project"
            return
        }
        guard isOpenAICredentialConfigured else {
            mediaAnalysisStatus = Self.missingOpenAIKeyAnalysisStatus
            return
        }

        await analyzeMediaItems(
            [currentItem],
            project: project,
            startMessage: "Starting analysis for \(currentItem.filename).",
            usesSingleItemStatus: true
        )
    }

    private func analyzeMediaItems(
        _ targetItems: [MediaItemRecord],
        project: ProjectRecord,
        startMessage: String,
        usesSingleItemStatus: Bool
    ) async {
        guard !targetItems.isEmpty else { return }

        isAnalyzingMedia = true
        analyzingMediaIds = Set(targetItems.map(\.mediaId))
        mediaAnalysisRunState = .running
        mediaAnalysisLogEntries = []
        resetMediaAnalysisCancelIntent()
        mediaAnalysisStatus = "Preparing media analysis"
        appendMediaAnalysisLog(
            kind: "start",
            message: startMessage
        )
        lastError = ""

        do {
            var updatedObservations = mediaObservationsById
            var analyzedCount = 0
            var cacheHitCount = 0
            var skippedCount = 0

            for (index, item) in targetItems.enumerated() {
                // Parked while the global pause is on; the cancel affordance still works
                // immediately, so a paused analysis run can be stopped without resuming.
                while isGenerationPaused, !mediaAnalysisCancelRequested {
                    try? await Task.sleep(nanoseconds: 250_000_000)
                }
                if mediaAnalysisCancelRequested {
                    finishCancelledMediaAnalysis(
                        analyzedCount: analyzedCount,
                        skippedCount: skippedCount,
                        savedObservationCount: updatedObservations.count
                    )
                    return
                }

                guard currentProject?.projectId == project.projectId else {
                    appendMediaAnalysisLog(kind: "error", message: "Stopped because the active project changed.")
                    mediaAnalysisRunState = .failed
                    mediaAnalysisStatus = "Media analysis stopped"
                    isAnalyzingMedia = false
                    analyzingMediaIds = []
                    resetMediaAnalysisCancelIntent()
                    return
                }

                let input = try mediaObservationInput(for: item)
                let memoryKey = MediaAnalysisMemoryKey.current(visionInputSha256: input.sha256)
                if let existing = updatedObservations[item.mediaId],
                   existing.visionInputSha256 == input.sha256,
                   existing.isCurrentAestheticObservationVersion {
                    skippedCount += 1
                    mediaAnalysisStatus = "Already analyzed \(index + 1)/\(targetItems.count)"
                    appendMediaAnalysisLog(
                        kind: "skip",
                        message: "Skipped \(index + 1)/\(targetItems.count): \(item.filename) already has an observation for this input."
                    )
                    continue
                }

                if let cachedObservation = cachedMediaObservation(for: memoryKey, item: item, index: index, total: targetItems.count)
                    ?? cachedMediaObservation(sourceSha256: item.contentSha256, item: item, index: index, total: targetItems.count) {
                    guard currentProject?.projectId == project.projectId else {
                        appendMediaAnalysisLog(kind: "error", message: "Stopped before linking cached analysis for \(item.filename) because the active project changed.")
                        mediaAnalysisRunState = .failed
                        mediaAnalysisStatus = "Media analysis stopped"
                        isAnalyzingMedia = false
                        analyzingMediaIds = []
                        resetMediaAnalysisCancelIntent()
                        return
                    }
                    let savedObservation = stampedMediaObservation(
                        cachedObservation,
                        item: item,
                        input: input,
                        model: cachedObservation.model,
                        generatedAt: cachedObservation.createdAt.isEmpty ? DateFormats.now() : cachedObservation.createdAt
                    )
                    updatedObservations[item.mediaId] = savedObservation
                    try contextStore.saveMediaObservations(updatedObservations, for: project)
                    mediaObservationsById = updatedObservations
                    cacheHitCount += 1
                    mediaAnalysisStatus = "Reused cached analysis \(index + 1)/\(targetItems.count)"
                    appendMediaAnalysisLog(
                        kind: "cache_hit",
                        message: "Reused cached analysis \(index + 1)/\(targetItems.count): \(item.filename)."
                    )
                    continue
                }

                mediaAnalysisStatus = "Analyzing \(index + 1)/\(targetItems.count): \(item.filename)"
                appendMediaAnalysisLog(
                    kind: "analyze",
                    message: "Analyzing \(index + 1)/\(targetItems.count): \(item.filename)."
                )
                let now = DateFormats.now()
                let context = MediaObservationGenerationContext(
                    projectId: project.projectId,
                    mediaId: item.mediaId,
                    visionInputSha256: input.sha256,
                    visionInputWidth: input.width,
                    visionInputHeight: input.height,
                    visionInputBytes: input.data.count,
                    generatedAt: now
                )
                let client = try OpenAIClient.fromEnvironment()
                let result = try await client.analyzeMedia(
                    imageData: input.data,
                    imageMimeType: input.mimeType,
                    context: context
                )
                guard currentProject?.projectId == project.projectId else {
                    appendMediaAnalysisLog(kind: "error", message: "Stopped before saving \(item.filename) because the active project changed.")
                    mediaAnalysisRunState = .failed
                    mediaAnalysisStatus = "Media analysis stopped"
                    isAnalyzingMedia = false
                    analyzingMediaIds = []
                    resetMediaAnalysisCancelIntent()
                    return
                }

                let savedObservation = stampedMediaObservation(
                    result.observation,
                    item: item,
                    input: input,
                    model: result.model,
                    generatedAt: now
                )
                updatedObservations[item.mediaId] = savedObservation
                try contextStore.saveMediaObservations(updatedObservations, for: project)
                mediaObservationsById = updatedObservations
                saveObservationToMediaAnalysisMemory(savedObservation, key: memoryKey, item: item, sourceSha256: item.contentSha256)
                analyzedCount += 1
                appendMediaAnalysisLog(
                    kind: "saved",
                    message: "Saved \(item.filename): \(mediaAnalysisObservationSummary(savedObservation))"
                )
            }

            if mediaAnalysisCancelRequested {
                finishCancelledMediaAnalysis(
                    analyzedCount: analyzedCount,
                    skippedCount: skippedCount,
                    savedObservationCount: updatedObservations.count
                )
                return
            }

            let currentCount = updatedObservations.values.filter(\.isCurrentAestheticObservationVersion).count
            mediaAnalysisStatus = completedMediaAnalysisStatus(
                targetItems: targetItems,
                analyzedCount: analyzedCount,
                cacheHitCount: cacheHitCount,
                skippedCount: skippedCount,
                currentCount: currentCount,
                usesSingleItemStatus: usesSingleItemStatus
            )
            appendMediaAnalysisLog(
                kind: "summary",
                message: "Summary: \(analyzedCount) analyzed, \(cacheHitCount) reused, \(skippedCount) skipped, \(updatedObservations.count) saved observation\(updatedObservations.count == 1 ? "" : "s")."
            )
            appendMediaAnalysisLog(kind: "complete", message: mediaAnalysisStatus)
            mediaAnalysisRunState = .succeeded
            touchCurrentProject()
        } catch {
            if isCancellationLikeError(error) || Task.isCancelled {
                mediaAnalysisStatus = "Media analysis cancelled"
                appendMediaAnalysisLog(kind: "cancelled", message: "Media analysis was cancelled before completion.")
                mediaAnalysisRunState = .cancelled
                isAnalyzingMedia = false
                analyzingMediaIds = []
                resetMediaAnalysisCancelIntent()
                return
            }
            lastError = error.localizedDescription
            mediaAnalysisStatus = "Media analysis failed"
            appendMediaAnalysisLog(kind: "error", message: error.localizedDescription)
            mediaAnalysisRunState = .failed
        }

        isAnalyzingMedia = false
        analyzingMediaIds = []
        resetMediaAnalysisCancelIntent()
        drainCharacterSourceAnalysisQueue()
    }

    private func completedMediaAnalysisStatus(
        targetItems: [MediaItemRecord],
        analyzedCount: Int,
        cacheHitCount: Int,
        skippedCount: Int,
        currentCount: Int,
        usesSingleItemStatus: Bool
    ) -> String {
        if usesSingleItemStatus, let item = targetItems.first {
            if analyzedCount > 0 {
                return "Analyzed \(item.filename)"
            }
            if cacheHitCount > 0 {
                return "Reused cached analysis for \(item.filename)"
            }
            return "\(item.filename) already analyzed"
        }
        if analyzedCount == 0, cacheHitCount == 0 {
            return "Enabled content already analyzed (\(currentCount) current)"
        }
        let analyzedPart = analyzedCount == 0 ? "" : "Analyzed \(analyzedCount) media item\(analyzedCount == 1 ? "" : "s")"
        let reusedPart = cacheHitCount == 0 ? "" : "reused \(cacheHitCount)"
        let skippedPart = skippedCount == 0 ? "" : "skipped \(skippedCount)"
        let summary = [analyzedPart, reusedPart, skippedPart]
            .filter { !$0.isEmpty }
            .joined(separator: ", ")
        return "\(summary) · \(currentCount) current"
    }

    func armMediaAnalysisCancel() {
        guard isAnalyzingMedia, mediaAnalysisRunState == .running else {
            resetMediaAnalysisCancelIntent()
            return
        }
        guard !mediaAnalysisCancelArmed else {
            confirmMediaAnalysisCancel()
            return
        }
        mediaAnalysisCancelArmed = true
        mediaAnalysisStatus = "Click one more to cancel"
        appendMediaAnalysisLog(
            kind: "cancel",
            message: "Cancel armed. Click one more time to stop after the current item saves."
        )
    }

    func confirmMediaAnalysisCancel() {
        guard isAnalyzingMedia, mediaAnalysisRunState == .running else {
            resetMediaAnalysisCancelIntent()
            return
        }
        guard !mediaAnalysisCancelRequested else {
            mediaAnalysisStatus = "Cancelling after current item saves"
            return
        }
        mediaAnalysisCancelArmed = true
        mediaAnalysisCancelRequested = true
        mediaAnalysisStatus = "Cancelling after current item saves"
        appendMediaAnalysisLog(
            kind: "cancelled",
            message: "Cancellation confirmed. The current item will finish and save before analysis stops."
        )
    }

    func curation(for item: MediaItemRecord) -> MediaCurationRecord {
        curationById[item.mediaId] ?? MediaCurationRecord(mediaId: item.mediaId)
    }

    func setRejected(_ mediaId: String, _ value: Bool) {
        updateCuration(mediaId: mediaId) { record in
            record.rejected = value
        }
        if value, playingMediaId == mediaId {
            stopVideoPlayback()
        }
    }

    func setTags(_ mediaId: String, _ rawValue: String) {
        let tags = rawValue
            .split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        updateCuration(mediaId: mediaId) { record in
            record.tags = Array(NSOrderedSet(array: tags).compactMap { $0 as? String })
        }
    }

    func setNotes(_ mediaId: String, _ value: String) {
        updateCuration(mediaId: mediaId) { record in
            record.notes = value
        }
    }

