    func revealInFinder(_ item: MediaItemRecord) {
        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: item.path)])
    }

    func mediaStorageStatus(for item: MediaItemRecord) -> MediaStorageStatus {
        guard FileManager.default.fileExists(atPath: item.path) else { return .missing }
        if item.derivativeKind?.trimmed.nilIfEmpty != nil {
            return .managed
        }
        if let source = sources.first(where: { $0.sourceId == item.sourceId }) {
            return source.resolvedStorageMode == .managed ? .managed : .linked
        }
        return .managed
    }

    func canMakeMediaManaged(_ item: MediaItemRecord) -> Bool {
        guard item.derivativeKind?.trimmed.nilIfEmpty == nil,
              mediaStorageStatus(for: item) == .linked,
              let source = sources.first(where: { $0.sourceId == item.sourceId }) else {
            return false
        }
        return source.resolvedSourceKind == .file
            && source.resolvedStorageMode == .linked
            && FileManager.default.fileExists(atPath: source.path)
    }

    func canRelinkMedia(_ item: MediaItemRecord) -> Bool {
        guard item.derivativeKind?.trimmed.nilIfEmpty == nil,
              mediaStorageStatus(for: item) == .missing,
              let source = sources.first(where: { $0.sourceId == item.sourceId }) else {
            return false
        }
        return source.resolvedSourceKind == .file
    }

    func makeMediaManaged(_ item: MediaItemRecord) {
        guard let source = sources.first(where: { $0.sourceId == item.sourceId }),
              source.resolvedSourceKind == .file,
              source.resolvedStorageMode == .linked,
              FileManager.default.fileExists(atPath: source.path) else {
            scanStatus = "Relink the original before making it managed"
            return
        }
        beginManagedConsolidation(sources: [source])
    }

    func relinkMedia(_ item: MediaItemRecord) {
        guard let project = currentProject,
              let source = sources.first(where: { $0.sourceId == item.sourceId }),
              source.resolvedSourceKind == .file else {
            scanStatus = "This media source cannot be relinked"
            return
        }
        guard !isScanning else { return }

        let panel = NSOpenPanel()
        panel.title = "Relink \(item.filename)"
        panel.message = "Choose the original or a replacement file. It will remain linked until you choose Make Managed."
        panel.prompt = "Relink"
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false
        switch item.kind {
        case .image:
            panel.allowedContentTypes = [.image]
        case .video:
            panel.allowedContentTypes = [.movie, .video]
        case .audio:
            panel.allowedContentTypes = [.audio]
        }
        guard panel.runModal() == .OK, let url = panel.url else { return }
        Task { [weak self] in
            await self?.relinkMedia(item, source: source, to: url, project: project)
        }
    }

    func revealVideoChainsDirectory() {
        guard let project = currentProject else { return }
        NSWorkspace.shared.activateFileViewerSelecting([contextStore.videoChainsDirectory(for: project)])
    }

    // MARK: - App Notices

    var diskUsageNeedsAttention: Bool {
        evaluateDiskUsageAttention(diskUsageNotice)
    }

    /// Launch-time hydration + first measurement. Called from the root view's
    /// `onAppear` rather than `init` so directly-constructed test engines never
    /// touch the real Application Support tree or walk the test runner's cwd.
    func bootstrapAppNoticesOnLaunch() {
        guard !hasBootstrappedAppNotices else { return }
        hasBootstrappedAppNotices = true
        diskUsageNotice = appNoticesStore.load().diskUsage
        Task { [weak self] in
            await self?.refreshDiskUsageNotice()
        }
    }

    func refreshDiskUsageNotice() async {
        guard !isMeasuringDiskUsage else { return }
        isMeasuringDiskUsage = true
        defer { isMeasuringDiskUsage = false }
        let readings = await Task.detached(priority: .utility) {
            DiskUsageScanner.measure(
                DiskUsageScanner.watchedLocations(workspaceRoot: DiskUsageScanner.defaultWorkspaceRoot())
            )
        }.value
        diskUsageNotice.locations = readings
        diskUsageNotice.measuredAt = DateFormats.now()
        persistAppNotices()
    }

    /// Measures the current project's growth. Read-only and detached, on the
    /// same pattern as the disk-usage scan — nothing here mutates the project,
    /// prunes takes, or archives anything; it exists so the next performance
    /// decision is aimed at a measured number instead of a hunch.
    func refreshProjectVitals() async {
        guard let project = currentProject, !isMeasuringProjectVitals else { return }
        isMeasuringProjectVitals = true
        defer { isMeasuringProjectVitals = false }
        let library = projectLibrary
        let known = projects
        let vitals = await Task.detached(priority: .utility) {
            // A registry row whose directory is gone is a broken picker entry.
            let dead = known.filter {
                !FileManager.default.fileExists(atPath: library.projectDirectory(for: $0).path)
            }.count
            return ProjectVitalsProbe.measure(
                project: project,
                projectLibrary: library,
                registryRowCount: known.count,
                registryDeadRowCount: dead
            )
        }.value
        guard currentProject?.projectId == vitals.projectId else { return }
        projectVitals = vitals
    }

    /// Opening the notices popover acknowledges the current readings — the
    /// badge dot clears and re-arms only on material growth (tunables).
    func acknowledgeDiskUsageNotice() {
        guard diskUsageNeedsAttention else { return }
        diskUsageNotice.acknowledgment = DiskUsageAcknowledgment(
            acknowledgedAt: DateFormats.now(),
            acknowledgedTotalBytes: diskUsageNotice.totalBytes,
            acknowledgedOverThresholdKeys: diskUsageOverThresholdKeys(diskUsageNotice)
        )
        persistAppNotices()
    }

    private func persistAppNotices() {
        do {
            try appNoticesStore.save(AppNoticesStateDocument(diskUsage: diskUsageNotice))
        } catch {
            lastError = error.localizedDescription
        }
    }

    func playVideo(_ item: MediaItemRecord) {
        guard item.kind == .video, !curation(for: item).rejected else { return }
        playingMediaId = item.mediaId
        videoPlaybackRequestId += 1
    }

    func isPlaying(_ item: MediaItemRecord) -> Bool {
        playingMediaId == item.mediaId
    }

    func stopVideoPlayback() {
        playingMediaId = nil
    }

    func extractedFrames(for videoMediaId: String) -> [MediaItemRecord] {
        sortedFrameItems(items.filter { $0.isExtractedVideoFrame && $0.sourceMediaId == videoMediaId })
    }

    func trims(for videoMediaId: String) -> [MediaItemRecord] {
        items
            .filter { $0.isVideoTrim && $0.sourceMediaId == videoMediaId }
            .sorted { ($0.sourceTimestampSeconds ?? 0) < ($1.sourceTimestampSeconds ?? 0) }
    }

    func clearStudioAutoOpenRequest() {
        studioAutoOpenVideo = nil
    }

    func frameExtractionState(for videoMediaId: String) -> VideoFrameExtractionState {
        if let state = frameExtractionByVideoId[videoMediaId] {
            return state
        }
        let frames = extractedFrames(for: videoMediaId)
        return frames.isEmpty
            ? VideoFrameExtractionState(status: "Not extracted")
            : VideoFrameExtractionState(completedCount: frames.count, totalCount: frames.count, status: "Frames ready")
    }

    func isFrameSelected(videoMediaId: String, frameMediaId: String) -> Bool {
        selectedFrameIdsByVideoId[videoMediaId]?.contains(frameMediaId) == true
    }

    func selectedFrameCount(for videoMediaId: String) -> Int {
        selectedFrameIdsByVideoId[videoMediaId]?.count ?? 0
    }

    func toggleFrameSelection(videoMediaId: String, frameMediaId: String) {
        guard items.contains(where: { $0.mediaId == frameMediaId && $0.sourceMediaId == videoMediaId }) else { return }
        var selected = selectedFrameIdsByVideoId[videoMediaId] ?? []
        if selected.contains(frameMediaId) {
            selected.remove(frameMediaId)
        } else {
            selected.insert(frameMediaId)
        }
        selectedFrameIdsByVideoId[videoMediaId] = selected
    }

    func clearFrameSelection(for videoMediaId: String) {
        selectedFrameIdsByVideoId[videoMediaId] = []
    }

    @discardableResult
    func enableContentItem(_ mediaId: String) -> Bool {
        guard let item = items.first(where: { $0.mediaId == mediaId }),
              item.canBeEnabledContent else {
            return false
        }
        setRejected(mediaId, false)
        // Promotion means "steers Story", which requires an observation — make
        // that true by construction. Quietly skips while a pass or scan runs;
        // the Frame Creator's auto-analyze covers any stragglers.
        if mediaObservationsById[mediaId] == nil, !isAnalyzingMedia, !isScanning {
            Task { await analyzeMediaItem(item) }
        }
        return true
    }

    func enableSelectedFrames(for videoMediaId: String) {
        let selectedIds = selectedFrameIdsByVideoId[videoMediaId] ?? []
        guard !selectedIds.isEmpty else { return }
        for mediaId in selectedIds {
            _ = enableContentItem(mediaId)
        }
        selectedFrameIdsByVideoId[videoMediaId] = []
        scanStatus = "Added \(selectedIds.count) frame\(selectedIds.count == 1 ? "" : "s") to enabled content"
    }

    func startFrameExtraction(for video: MediaItemRecord) {
        guard let project = currentProject else {
            scanStatus = "Create or select a project first"
            return
        }
        guard video.kind == .video else { return }
        guard frameExtractionByVideoId[video.mediaId]?.isExtracting != true else { return }

        let source = sources.first { $0.sourceId == video.sourceId }
        frameExtractionByVideoId[video.mediaId] = VideoFrameExtractionState(
            isExtracting: true,
            completedCount: 0,
            totalCount: 0,
            status: "Starting frame extraction"
        )
        scanStatus = "Extracting frames from \(video.filename)"

        Task { [weak self] in
            guard let self else { return }
            await self.extractFrames(from: video, source: source, project: project)
        }
    }

    func addFrameToMedia(from video: MediaItemRecord, timestampSeconds: Double) async {
        guard let project = currentProject else {
            scanStatus = "Create or select a project first"
            return
        }
        guard video.kind == .video else { return }
        guard !isAddingFrameToMedia else { return }

        isAddingFrameToMedia = true
        lastError = ""
        scanStatus = "Adding frame from \(video.filename)"

        do {
            let source = sources.first { $0.sourceId == video.sourceId }
            let frame = try await store.captureFrame(
                from: video,
                source: source,
                for: project,
                at: timestampSeconds
            )
            guard currentProject?.projectId == project.projectId else {
                isAddingFrameToMedia = false
                return
            }

            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            updatedItemsById[frame.mediaId] = frame
            let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
            try store.saveInventory(updatedItems, for: project)

            var updatedCuration = curationById
            var curation = updatedCuration[frame.mediaId] ?? MediaCurationRecord(mediaId: frame.mediaId)
            curation.rejected = false
            curation.updatedAt = DateFormats.now()
            updatedCuration[frame.mediaId] = curation
            try store.saveCuration(updatedCuration, for: project)

            items = updatedItems
            curationById = updatedCuration
            selectedItemId = frame.mediaId
            scanStatus = "Added frame at \(durationLabel(timestampSeconds)) to media"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not add frame"
        }

        isAddingFrameToMedia = false
    }

    @discardableResult
    func saveVideoTrim(from video: MediaItemRecord, startSeconds: Double, endSeconds: Double) async -> MediaItemRecord? {
        guard let project = currentProject else {
            scanStatus = "Create or select a project first"
            return nil
        }
        guard video.kind == .video else { return nil }
        guard !isSavingVideoTrim else { return nil }

        isSavingVideoTrim = true
        // This flag disables the only control that can clear it, so any exit
        // that skips the reset strands the Video Studio's Save button until
        // the app is relaunched. A stalled exporter did exactly that.
        defer { isSavingVideoTrim = false }
        lastError = ""
        scanStatus = "Saving cut from \(video.filename)"

        do {
            let source = sources.first { $0.sourceId == video.sourceId }
            let trim = try await store.trimVideo(
                from: video,
                source: source,
                for: project,
                startSeconds: startSeconds,
                endSeconds: endSeconds
            )
            guard currentProject?.projectId == project.projectId else {
                return nil
            }

            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            updatedItemsById[trim.mediaId] = trim
            let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
            try store.saveInventory(updatedItems, for: project)

            var updatedCuration = curationById
            var curation = updatedCuration[trim.mediaId] ?? MediaCurationRecord(mediaId: trim.mediaId)
            curation.rejected = false
            curation.updatedAt = DateFormats.now()
            updatedCuration[trim.mediaId] = curation
            try store.saveCuration(updatedCuration, for: project)

            items = updatedItems
            curationById = updatedCuration
            scanStatus = "Saved cut \(trim.durationSeconds.map { durationLabel($0) } ?? "") in Footage"
            touchCurrentProject()
            return trim
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not save cut"
            return nil
        }
    }

