    func sendGoalInterviewMessage(text rawText: String, mediaIds rawMediaIds: [String]) async {
        guard let project = currentProject else {
            goalStatus = "Create or select a project first"
            return
        }
        let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            goalStatus = "Write a message first"
            return
        }
        guard !isInterviewingGoal else { return }

        let mediaIds = normalizedExistingMediaIds(rawMediaIds)
        isInterviewingGoal = true
        lastError = ""
        goalStatus = "Goal interview running"

        let userMessageTime = DateFormats.now()
        var workingGoal = projectGoal
        if workingGoal.projectId.isEmpty {
            workingGoal.projectId = project.projectId
        }
        workingGoal.appendMessage(role: .user, text: text, mediaIds: mediaIds, now: userMessageTime)
        do {
            try contextStore.saveProjectGoal(workingGoal, for: project)
            projectGoal = workingGoal
            touchCurrentProject()

            let client = try OpenAIClient.fromEnvironment()
            let now = DateFormats.now()
            let context = ProjectGoalInterviewContext(
                projectId: project.projectId,
                projectName: project.name,
                currentBriefJSON: currentGoalBriefJSON(from: workingGoal.activeBrief),
                recentMessagesSummary: goalMessagesSummary(from: workingGoal),
                selectedMediaSummary: selectedGoalMediaSummary(mediaIds: mediaIds),
                mediaArchiveSummary: goalMediaArchiveSummary(),
                userMessage: text,
                generatedAt: now
            )
            let result = try await client.interviewProjectGoal(context: context)
            guard currentProject?.projectId == project.projectId else {
                isInterviewingGoal = false
                return
            }

            var updated = workingGoal
            let assistantText = result.assistantMessage.trimmingCharacters(in: .whitespacesAndNewlines)
            updated.appendMessage(
                role: .assistant,
                text: assistantText.isEmpty ? "I updated the Goal Brief." : assistantText,
                mediaIds: [],
                now: DateFormats.now()
            )
            updated.appendVersion(
                brief: result.brief,
                changeSummary: result.changeSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    ? "Updated Goal Brief from the latest interview turn."
                    : result.changeSummary,
                model: result.model,
                now: DateFormats.now()
            )
            saveGoalAndMirrors(updated, for: project, status: updated.isReadyForAesthetic ? "Goal ready" : "Goal updated")
        } catch {
            guard currentProject?.projectId == project.projectId else {
                isInterviewingGoal = false
                return
            }
            lastError = goalInterviewFailureMessage(for: error)
            goalStatus = goalInterviewFailureStatus(for: error)
        }

        isInterviewingGoal = false
    }

