    func setCharacterNames(_ value: String) {
        let names = value
            .split { $0 == "," || $0 == "\n" }
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        updateStoryWorld { storyWorld in
            var existingByName: [String: StoryCharacterRecord] = [:]
            for character in storyWorld.characters where existingByName[character.name.lowercased()] == nil {
                existingByName[character.name.lowercased()] = character
            }
            storyWorld.characters = names.map { name in
                if var existing = existingByName[name.lowercased()] {
                    existing.name = name
                    existing.updatedAt = DateFormats.now()
                    return existing
                }
                return StoryCharacterRecord.blank(name: name)
            }
        }
    }

