    func buildStorySignals() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        guard !isBuildingStorySignals else { return }

        let targetScope = ProjectStoryScope.enabledMedia
        let scopedItems = enabledStoryItems()
        guard !scopedItems.isEmpty else {
            storyStatus = "No enabled media"
            return
        }

        isBuildingStorySignals = true
        lastError = ""
        storyStatus = "Building Story Signals"

        do {
            let client = try OpenAIClient.fromEnvironment()
            let now = DateFormats.now()
            let fingerprint = currentStoryInputFingerprint
            let packet = storyPromptPacket(signals: StorySignalSet.empty(projectId: project.projectId))
            let context = StorySignalSetGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                signalSetId: "signals_\(shortHash("\(project.projectId):\(fingerprint.stableId):\(now)", length: 14))",
                scope: targetScope.rawValue,
                selectedMediaIds: scopedItems.map(\.mediaId),
                promptPacketJSON: encodedStoryPromptPacket(packet),
                inputFingerprint: fingerprint,
                generatedAt: now
            )
            let result = try await client.deriveStorySignalSet(context: context)
            guard currentProject?.projectId == project.projectId else {
                isBuildingStorySignals = false
                return
            }
            var signals = result.signalSet
            signals.projectId = project.projectId
            signals.scope = targetScope.rawValue
            signals.evidenceMediaIds = signals.evidenceMediaIds.filter { mediaId in
                scopedItems.contains { $0.mediaId == mediaId }
            }
            signals.confidence0To1 = min(max(signals.confidence0To1, 0), 1)
            signals.inputFingerprint = fingerprint
            signals.artifactStatus = .fresh
            signals.legacySourcePath = ""
            signals.legacyRawScope = ""
            signals.generatedAt = signals.generatedAt.isEmpty ? now : signals.generatedAt
            signals.updatedAt = DateFormats.now()

            var workspace = storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.selectedScope = targetScope
            workspace.selectedMediaIds = []
            workspace.currentStep = .signals
            workspace.status = "Story Signals ready"
            workspace.updatedAt = DateFormats.now()

            try contextStore.saveStorySignals(signals, for: project)
            try contextStore.saveStoryWorkspace(workspace, for: project)
            try recordStoryGenerationRun(
                artifactType: "story_signals",
                artifactId: signals.signalSetId,
                model: result.model,
                responseId: result.responseId,
                schemaVersion: signals.schemaVersion,
                inputFingerprint: fingerprint,
                promptPacket: packet,
                createdAt: now,
                for: project
            )
            storySignals = signals
            storyWorkspace = workspace
            storyStatus = "Story Signals ready"
            touchCurrentProject()
        } catch {
            let now = DateFormats.now()
            let fallback = localStorySignals(
                project: project,
                scopedItems: scopedItems,
                fingerprint: currentStoryInputFingerprint,
                generatedAt: now
            )
            do {
                try contextStore.saveStorySignals(fallback, for: project)
                storySignals = fallback
                storyStatus = storyProviderFallbackStatus("Local Story Signals ready", after: error)
                lastError = ""
            } catch {
                lastError = error.localizedDescription
                storyStatus = "Story Signals failed"
            }
        }

        isBuildingStorySignals = false
    }

