    func sendStorylineCreationMessage(text rawText: String) async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            storyStatus = "Write a Create Storyline message first"
            return
        }
        guard !isInterviewingStorylineCreation, !isGeneratingStoryline else { return }

        isInterviewingStorylineCreation = true
        defer { isInterviewingStorylineCreation = false }
        lastError = ""
        storyStatus = "Create Storyline chat running"

        let now = DateFormats.now()
        var working = storylineCreation
        if working.projectId.isEmpty {
            working.projectId = project.projectId
        }
        if working.draftSetup.projectId.isEmpty {
            working.draftSetup = storySetup
            working.draftSetup.projectId = project.projectId
        }
        working.appendMessage(role: .user, text: text, now: now)

        do {
            try contextStore.saveStorylineCreation(working, for: project)
            storylineCreation = working
            touchCurrentProject()

            let fingerprint = currentStoryInputFingerprint
            let signals = storySignals.freshness(against: fingerprint) == .fresh
                ? storySignals
                : localStorySignals(
                    project: project,
                    scopedItems: currentStoryScopeItems,
                    fingerprint: fingerprint,
                    generatedAt: now
                )
            let packet = storyPromptPacket(signals: signals, setup: working.draftSetup)
            let client = try OpenAIClient.fromEnvironment()
            let context = StorylineCreationInterviewContext(
                projectId: project.projectId,
                projectName: project.name,
                currentDraftJSON: encodedStorylineCreationDraft(working.draft),
                recentMessagesSummary: storylineCreationMessagesSummary(from: working),
                draftSetupJSON: encodedStorySetup(working.draftSetup),
                existingDirectionsJSON: encodedStoryDirections(storyDirectionSet.directions),
                promptPacketJSON: encodedStoryPromptPacket(packet),
                userMessage: text,
                generatedAt: now
            )
            let result = try await client.interviewStorylineCreation(context: context)
            guard currentProject?.projectId == project.projectId else { return }

            var updated = working
            let assistantText = result.assistantMessage.trimmingCharacters(in: .whitespacesAndNewlines)
            updated.appendMessage(
                role: .assistant,
                text: assistantText.isEmpty ? "I updated the Create Storyline draft." : assistantText,
                now: DateFormats.now()
            )
            updated.applyInterviewDraft(
                result.draft,
                status: result.draft.isReadyToGenerate ? "Ready to generate" : "Needs clarification",
                now: DateFormats.now()
            )
            try contextStore.saveStorylineCreation(updated, for: project)
            storylineCreation = updated
            storyStatus = updated.isReadyToGenerate ? "Create Storyline ready" : "Create Storyline needs clarification"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            lastError = error.localizedDescription
            storyStatus = "Create Storyline chat failed"
        }
    }

    func generateStorylineFromCreationDraft() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        guard !isGeneratingStoryline, !isGeneratingStoryDirections, !isBuildingStorySignals else { return }
        let scopedItems = currentStoryScopeItems
        guard !scopedItems.isEmpty else {
            storyStatus = "No enabled media"
            return
        }
        let creation = storylineCreation
        guard creation.isReadyToGenerate else {
            storyStatus = "Answer Create Storyline questions first"
            return
        }

        isGeneratingStoryline = true
        defer { isGeneratingStoryline = false }
        lastError = ""
        storyStatus = "Generating Storyline"

        let now = DateFormats.now()
        let fingerprint = currentStoryInputFingerprint
        let directionId = "dir_\(shortHash("\(project.projectId):single_storyline:\(fingerprint.stableId):\(now):\(creation.draft.storylineIntent)", length: 14))"
        let directionSetId = "directions_\(shortHash("\(project.projectId):single_storyline:\(fingerprint.stableId):\(now)", length: 14))"

        do {
            let client = try OpenAIClient.fromEnvironment()
            let signalsForDirections = try storySignalsForDirectionGeneration(
                project: project,
                scopedItems: scopedItems,
                fingerprint: fingerprint,
                generatedAt: now
            )
            guard currentProject?.projectId == project.projectId else { return }
            let packet = storyPromptPacket(signals: signalsForDirections, setup: creation.draftSetup)
            let context = StorySingleStorylineGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                expectedDirectionId: directionId,
                draftJSON: encodedStorylineCreationDraft(creation.draft),
                draftSetupJSON: encodedStorySetup(creation.draftSetup),
                existingDirectionsJSON: encodedStoryDirections(storyDirectionSet.directions),
                promptPacketJSON: encodedStoryPromptPacket(packet),
                inputFingerprint: fingerprint,
                generatedAt: now
            )
            let result = try await client.generateSingleStoryline(context: context)
            guard currentProject?.projectId == project.projectId else { return }
            let direction = normalizedSingleStoryDirection(
                result.direction,
                directionId: directionId,
                fingerprint: fingerprint,
                projectId: project.projectId
            )
            try persistGeneratedSingleStoryline(
                direction,
                directionSetId: directionSetId,
                fingerprint: fingerprint,
                generatedAt: now,
                generator: "openai",
                model: result.model,
                responseId: result.responseId,
                packet: packet,
                project: project,
                status: "Storyline added"
            )
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            let packet = storyPromptPacket(
                signals: localStorySignals(
                    project: project,
                    scopedItems: scopedItems,
                    fingerprint: fingerprint,
                    generatedAt: now
                ),
                setup: creation.draftSetup
            )
            let fallback = localSingleStoryDirection(
                project: project,
                creation: creation,
