                )
                lastError = ""
            } catch {
                lastError = error.localizedDescription
                storyStatus = "Storyline failed"
            }
        }
    }

    func generateStoryDirections() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard isGoalV2Ready else {
            storyStatus = "Complete Goal first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        guard !isGeneratingStoryDirections, !isBuildingStorySignals else { return }
        let scopedItems = currentStoryScopeItems
        guard !scopedItems.isEmpty else {
            storyStatus = "No enabled media"
            return
        }

        isGeneratingStoryDirections = true
        defer { isGeneratingStoryDirections = false }
        lastError = ""
        storyStatus = "Generating Storylines"

        let now = DateFormats.now()
        let fingerprint = currentStoryInputFingerprint

        do {
            let client = try OpenAIClient.fromEnvironment()
            let signalsForDirections = try storySignalsForDirectionGeneration(
                project: project,
                scopedItems: scopedItems,
                fingerprint: fingerprint,
                generatedAt: now
            )
            guard currentProject?.projectId == project.projectId else { return }
            let packet = storyPromptPacket(signals: signalsForDirections)
            let directionSetId = "directions_\(shortHash("\(project.projectId):\(fingerprint.stableId):\(now)", length: 14))"
            let context = StoryDirectionSetGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                directionSetId: directionSetId,
                promptPacketJSON: encodedStoryPromptPacket(packet),
                inputFingerprint: fingerprint,
                generatedAt: now
            )
            let result = try await client.generateStoryDirections(context: context)
            guard currentProject?.projectId == project.projectId else { return }
            var set = normalizedStoryDirectionSet(
                result.directionSet,
                project: project,
                directionSetId: directionSetId,
                fingerprint: fingerprint,
                setup: storySetup,
                generatedAt: now,
                generator: "openai",
                model: result.model,
                responseId: result.responseId
            )
            set = mergedStoryLensSet(set)
            set.storySetupSnapshot = storySetup
            try persistStoryDirectionSet(
                set,
                project: project,
                status: "Storylines ready"
            )
            try recordStoryGenerationRun(
                artifactType: "story_directions",
                artifactId: set.directionSetId,
                model: result.model,
                responseId: result.responseId,
                schemaVersion: set.schemaVersion,
                inputFingerprint: fingerprint,
                promptPacket: packet,
                createdAt: now,
                for: project
            )
            touchCurrentProject()
        } catch {
            var fallback = StoryLocalDraftFactory.directionSet(
                projectId: project.projectId,
                projectName: project.name,
                fingerprint: fingerprint,
                setup: storySetup,
                goalDigest: storyGoalDigest(),
                aestheticCues: storyAestheticCues(),
                patternMatches: storyPatternMatches(),
                generatedAt: now
            )
            fallback = mergedStoryLensSet(fallback)
            do {
                try persistStoryDirectionSet(
                    fallback,
                    project: project,
                    status: storyProviderFallbackStatus("Local Storylines ready", after: error)
                )
                lastError = ""
                touchCurrentProject()
            } catch {
                lastError = error.localizedDescription
                storyStatus = "Storylines failed"
            }
        }
    }

