    func setStoryDirectionEnabled(directionId: String, enabled: Bool) {
        guard let project = currentProject else { return }
        guard storyDirectionSet.directions.contains(where: { $0.directionId == directionId }) else { return }
        do {
            var set = storyDirectionSet
            set.directions = set.directions.map { direction in
                var updated = direction
                if updated.directionId == directionId {
                    updated.enabled = enabled
                }
                return updated
            }
            set.directions = StoryDirectionSet.storylineDisplayOrder(set.directions)
            set.candidateDirections = set.candidateDirections.map { direction in
                var updated = direction
                if updated.directionId == directionId {
                    updated.enabled = enabled
                }
                return updated
            }
            set.updatedAt = DateFormats.now()
            try contextStore.saveStoryDirectionSet(set, for: project)
            storyDirectionSet = set
            storyDirectionHistory = contextStore.loadStoryDirectionHistory(for: project)
            storyStatus = enabled ? "Storyline enabled" : "Storyline disabled"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Storyline toggle failed"
        }
    }

