            primaryDirectionId: directionId,
            sourceDirectionIds: [directionId],
            mode: mode
        )
    }

    private func expandStorylinesIntoBeats(
        primaryDirectionId: String,
        sourceDirectionIds: [String],
        mode: StoryBeatExpansionMode
    ) async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard let direction = storyDirectionSet.directions.first(where: { $0.directionId == primaryDirectionId }) else {
            storyStatus = "Choose a Storyline first"
            return
        }
        let sourceIds = uniqueNonEmpty(sourceDirectionIds).isEmpty
            ? [direction.directionId]
            : uniqueNonEmpty(sourceDirectionIds)
        guard !isGeneratingStoryBeatBoard else { return }

        if let existing = storyBeatBoards.first(where: {
            $0.parentDirectionSetId == storyDirectionSet.directionSetId
                && $0.primaryDirectionId == direction.directionId
                && $0.sourceDirectionIds == sourceIds
                && $0.freshness(against: currentStoryInputFingerprint) == .fresh
        }), mode == .openExisting {
            activateStoryBeatBoard(existing.beatBoardId)
            return
        }

        isGeneratingStoryBeatBoard = true
        activeStoryBeatBoardGenerationSourceIds = sourceIds
        activeStoryBeatBoardGenerationLabel = sourceIds.count == 1
            ? direction.title
            : "\(sourceIds.count) enabled Storylines"
        defer {
            isGeneratingStoryBeatBoard = false
            activeStoryBeatBoardGenerationSourceIds = []
            activeStoryBeatBoardGenerationLabel = ""
        }
        lastError = ""
        storyStatus = sourceIds.count == 1 ? "Expanding Storyline" : "Generating Beat Board from enabled Storylines"

        let now = DateFormats.now()
        let fingerprint = currentStoryInputFingerprint
        let boardId = "board_\(shortHash("\(project.projectId):\(direction.directionId):\(sourceIds.joined(separator: "|")):\(fingerprint.stableId):\(now)", length: 14))"
        let packet = storyPromptPacket(signals: storySignalsFreshness == .fresh ? storySignals : StorySignalSet.empty(projectId: project.projectId))
        let selectedDirections = sourceIds.compactMap { id in
            storyDirectionSet.directions.first { $0.directionId == id }
        }

        do {
            let client = try OpenAIClient.fromEnvironment()
            let context = StoryBeatBoardGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                beatBoardId: boardId,
                parentDirectionSetId: storyDirectionSet.directionSetId,
                parentDirectionId: direction.directionId,
                sourceDirectionIds: sourceIds,
                storySetupHash: fingerprint.storySetupHash,
                aestheticRecipeVersion: fingerprint.chosenRecipeVersion,
                promptPacketJSON: encodedStoryPromptPacket(packet),
                selectedDirectionJSON: selectedDirections.count <= 1 ? encodedStoryDirection(direction) : encodedStoryDirections(selectedDirections),
                inputFingerprint: fingerprint,
                generatedAt: now
            )
            let result = try await client.generateStoryBeatBoard(context: context)
            guard currentProject?.projectId == project.projectId else { return }
            let board = normalizedStoryBeatBoard(
                result.beatBoard,
                project: project,
                boardId: boardId,
                direction: direction,
                directionSetId: storyDirectionSet.directionSetId,
                sourceDirectionIds: sourceIds,
                fingerprint: fingerprint,
                generatedAt: now,
                generator: "openai",
                model: result.model,
                responseId: result.responseId
            )
            try persistStoryBeatBoard(
                board,
                project: project,
                status: "Story Beat Board ready"
            )
            try recordStoryGenerationRun(
                artifactType: "story_beat_board",
                artifactId: board.beatBoardId,
                model: result.model,
                responseId: result.responseId,
                schemaVersion: board.schemaVersion,
                inputFingerprint: fingerprint,
                promptPacket: packet,
                createdAt: now,
                for: project
            )
            touchCurrentProject()
        } catch {
            let fallback = StoryLocalDraftFactory.beatBoard(
                projectId: project.projectId,
                directionSetId: storyDirectionSet.directionSetId,
                direction: direction,
                fingerprint: fingerprint,
                setup: storySetup,
                aestheticCues: storyAestheticCues(),
                generatedAt: now
            )
            do {
                let board = normalizedStoryBeatBoard(
                    fallback,
                    project: project,
                    boardId: fallback.beatBoardId,
                    direction: direction,
                    directionSetId: storyDirectionSet.directionSetId,
                    sourceDirectionIds: sourceIds,
                    fingerprint: fingerprint,
                    generatedAt: now,
                    generator: "local_pattern_index",
                    model: "",
                    responseId: ""
                )
                try persistStoryBeatBoard(
                    board,
                    project: project,
                    status: storyProviderFallbackStatus("Local Story Beat Board ready", after: error)
                )
                lastError = ""
                touchCurrentProject()
            } catch {
                lastError = error.localizedDescription
                storyStatus = "Story Beat Board failed"
            }
        }
    }

    func openExistingBeatBoard(for directionId: String) {
        guard let existing = storyBeatBoards.first(where: {
            $0.parentDirectionSetId == storyDirectionSet.directionSetId
                && ($0.primaryDirectionId == directionId || $0.parentDirectionId == directionId || $0.sourceDirectionIds.contains(directionId))
        }) else {
            storyStatus = "No existing Beat Board for this Story direction"
            return
        }
        activateStoryBeatBoard(existing.beatBoardId)
    }

    func activateStoryBeatBoard(_ beatBoardId: String) {
        guard let project = currentProject else { return }
        guard let board = storyBeatBoards.first(where: { $0.beatBoardId == beatBoardId }) else { return }
        do {
            var workspace = storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.activeBeatBoardId = beatBoardId
            workspace.activeDirectionSetId = board.parentDirectionSetId
            workspace.activeDirectionId = board.primaryDirectionId.isEmpty ? board.parentDirectionId : board.primaryDirectionId
            workspace.previewDirectionId = workspace.previewDirectionId ?? workspace.activeDirectionId
            workspace.currentStep = .beats
            workspace.status = "Story Beat Board active"
            workspace.updatedAt = DateFormats.now()
            try contextStore.saveStoryWorkspace(workspace, for: project)
            storyBeatBoard = board
            storySequenceStrip = contextStore.loadStorySequenceStrip(for: project, beatBoardId: board.beatBoardId)
            storyWorkspace = workspace
            storyStatus = "Story Beat Board active"
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Story Beat Board activation failed"
        }
    }

    func setStoryBeatLocked(beatId: String, locked: Bool) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        guard let index = board.beats.firstIndex(where: { $0.beatId == beatId }) else { return }
        board.beats[index].locked = locked
        board.updatedAt = DateFormats.now()
        do {
            try persistStoryBeatBoard(board, project: project, status: "Story Beat updated")
        } catch {
            lastError = error.localizedDescription
        }
    }

    func moveStoryBeat(fromOffsets source: IndexSet, toOffset destination: Int) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        let movingIndexes = source.sorted()
        guard !movingIndexes.isEmpty else { return }
        let moving = movingIndexes.map { board.beats[$0] }
        for index in movingIndexes.reversed() {
            board.beats.remove(at: index)
        }
        let removedBeforeDestination = movingIndexes.filter { $0 < destination }.count
        let adjustedDestination = max(0, min(board.beats.count, destination - removedBeforeDestination))
        board.beats.insert(contentsOf: moving, at: adjustedDestination)
        board.beats = board.beats.enumerated().map { index, beat in
            var updated = beat
            updated.order = index + 1
            return updated
        }
        board.updatedAt = DateFormats.now()
        do {
            try persistStoryBeatBoard(board, project: project, status: "Story Beat order updated")
        } catch {
            lastError = error.localizedDescription
        }
    }

    var canUndoStoryBeatEdit: Bool {
        !storyBeatUndoStack.isEmpty
    }

    func undoLastStoryBeatEdit() {
        guard let project = currentProject,
              let previous = storyBeatUndoStack.popLast() else { return }
        storyBeatUndoDepth = storyBeatUndoStack.count
        do {
            try persistStoryBeatBoard(previous, project: project, status: "Story Beat edit undone")
            markSceneAssetsStale(beatIds: previous.beats.map(\.beatId), sequenceChanged: true)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func moveStoryBeat(beatId: String, placement: StoryBeatMovePlacement) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        let ordered = board.visibleBeats
        guard let currentVisibleIndex = ordered.firstIndex(where: { $0.beatId == beatId }) else { return }
        var reordered = ordered
        let beat = reordered.remove(at: currentVisibleIndex)
        let targetIndex: Int
        switch placement {
        case .earlier:
            targetIndex = max(0, currentVisibleIndex - 1)
        case .later:
            targetIndex = min(reordered.count, currentVisibleIndex + 1)
        case .start:
            targetIndex = 0
        case .end:
            targetIndex = reordered.count
        }
        reordered.insert(beat, at: targetIndex)
        let hidden = board.beats.filter(\.isDeleted)
        board.beats = renumberStoryBeats(reordered) + hidden
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat order updated")
            markSceneAssetsStale(beatIds: [], sequenceChanged: true)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func updateStoryBeat(_ beat: StoryBeatBoardBeat) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        guard let index = board.beats.firstIndex(where: { $0.beatId == beat.beatId }) else { return }
        guard !board.beats[index].locked else {
            storyStatus = "Locked beats cannot be edited"
            return
        }
        var updated = beat
        updated.validationWarnings = StoryValidation.beatWarnings(updated)
        updated.manualEditFields = uniqueNonEmpty(updated.manualEditFields + ["manual"])
        updated.revisionHistory = board.beats[index].revisionHistory
        updated.revisionHistory.append(revision(for: board.beats[index], operation: "manual_edit"))
        board.beats[index] = updated
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat updated")
            markSceneAssetsStale(beatIds: [beat.beatId], sequenceChanged: false)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func addStoryBeat(after beatId: String? = nil) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        let ordered = board.visibleBeats
        let insertIndex = beatId.flatMap { id in ordered.firstIndex { $0.beatId == id }.map { $0 + 1 } } ?? ordered.count
        let newOrder = insertIndex + 1
        let newBeat = blankStoryBeat(
            boardId: board.beatBoardId,
            order: newOrder,
            title: "New Beat"
        )
        var next = ordered
        next.insert(newBeat, at: min(max(insertIndex, 0), next.count))
        let hidden = board.beats.filter(\.isDeleted)
        board.beats = renumberStoryBeats(next) + hidden
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat added")
            markSceneAssetsStale(beatIds: [], sequenceChanged: true)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func duplicateStoryBeat(beatId: String) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        let ordered = board.visibleBeats
        guard let index = ordered.firstIndex(where: { $0.beatId == beatId }) else { return }
        var copy = ordered[index]
        copy.beatId = "beat_\(String(format: "%02d", index + 2))_\(shortHash("\(board.beatBoardId):duplicate:\(beatId):\(DateFormats.now())", length: 8))"
        copy.title = copy.title.isEmpty ? "Duplicate Beat" : "\(copy.title) Copy"
        copy.locked = false
        copy.revisionHistory = [revision(for: ordered[index], operation: "duplicate_source")]
        var next = ordered
        next.insert(copy, at: index + 1)
        let hidden = board.beats.filter(\.isDeleted)
        board.beats = renumberStoryBeats(next) + hidden
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat duplicated")
            markSceneAssetsStale(beatIds: [], sequenceChanged: true)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func softDeleteStoryBeat(beatId: String) {
        guard let project = currentProject else { return }
        var board = storyBeatBoard
        guard let index = board.beats.firstIndex(where: { $0.beatId == beatId }) else { return }
        guard !board.beats[index].locked else {
            storyStatus = "Locked beats cannot be deleted"
            return
        }
        board.beats[index].isDeleted = true
        board.beats[index].deletedAt = DateFormats.now()
        board.beats[index].revisionHistory.append(revision(for: board.beats[index], operation: "soft_delete"))
        let visible = renumberStoryBeats(board.visibleBeats)
        let hidden = board.beats.filter(\.isDeleted)
        board.beats = visible + hidden
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat deleted")
            markSceneAssetsStale(beatIds: [beatId], sequenceChanged: true)
        } catch {
            lastError = error.localizedDescription
        }
    }

    func setStoryBeatMediaAnchor(beatId: String, mediaId: String, role: StoryMediaAnchorRole, enabled: Bool) {
        guard let project = currentProject else { return }
        guard let item = items.first(where: { $0.mediaId == mediaId }) else { return }
        var board = storyBeatBoard
        guard let index = board.beats.firstIndex(where: { $0.beatId == beatId }) else { return }
        guard !board.beats[index].locked else {
            storyStatus = "Locked beats cannot be edited"
            return
        }
        var beat = board.beats[index]
        beat.revisionHistory.append(revision(for: beat, operation: "media_anchor"))
        if enabled {
            let anchor = mediaAnchor(for: item, role: role)
            beat.mediaAnchors.removeAll { $0.mediaId == mediaId && $0.role == role }
            beat.mediaAnchors.append(anchor)
        } else {
            beat.mediaAnchors.removeAll { $0.mediaId == mediaId && $0.role == role }
        }
        beat.sourceMediaIds = mediaIds(for: beat.mediaAnchors, role: .source)
        beat.avoidMediaIds = mediaIds(for: beat.mediaAnchors, role: .avoid)
        beat.referenceMediaIds = mediaIds(for: beat.mediaAnchors, role: .reference)
        beat.manualEditFields = uniqueNonEmpty(beat.manualEditFields + ["media_anchors"])
        board.beats[index] = beat
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat anchors updated")
            markSceneAssetsStale(beatIds: [beatId], sequenceChanged: false)
        } catch {
            lastError = error.localizedDescription
        }
    }

