    func replaceStoryBeatWithAlternatives(beatId: String) async {
        guard storyBeatBoard.visibleBeats.contains(where: { $0.beatId == beatId }) else { return }
        setStoryBeatOperation(beatId: beatId, phase: .replacing)
        storyBeatAlternativesByBeatId[beatId] = []
        do {
            var alternatives: [StoryBeatBoardBeat] = []
            for index in 1...3 {
                let editedBoard = try await storyBeatBoardEditResult(
                    beatId: beatId,
                    operation: "replace_selected_beat_alternative_\(index)",
                    intent: "Create alternative \(index) for the selected beat. Preserve board continuity and return the full board with that alternative applied.",
                    outputBeatBoardId: storyBeatBoard.beatBoardId
                )
                guard let candidate = editedBoard.beats.first(where: { $0.beatId == beatId }) else {
                    throw ScreenGraphError.openAI("Replacement alternative \(index) did not include the selected beat.")
                }
                alternatives.append(candidate)
            }
            storyBeatAlternativesByBeatId[beatId] = alternatives
            setStoryBeatOperation(beatId: beatId, phase: .idle)
            storyStatus = "Story Beat alternatives ready"
        } catch {
            setStoryBeatOperation(beatId: beatId, phase: .failed, errorMessage: error.localizedDescription)
            lastError = error.localizedDescription
            storyStatus = "Story Beat alternatives failed"
        }
    }

    func applyStoryBeatAlternative(beatId: String, alternativeIndex: Int) {
        guard let alternatives = storyBeatAlternativesByBeatId[beatId],
              alternatives.indices.contains(alternativeIndex) else { return }
        var alternative = alternatives[alternativeIndex]
        alternative.beatId = beatId
        updateStoryBeat(alternative)
        storyBeatAlternativesByBeatId[beatId] = nil
    }

    func insertStoryBeatAlternative(after beatId: String, alternativeIndex: Int) {
        guard let project = currentProject,
              let alternatives = storyBeatAlternativesByBeatId[beatId],
              alternatives.indices.contains(alternativeIndex) else { return }
        var board = storyBeatBoard
        let ordered = board.visibleBeats
        guard let sourceIndex = ordered.firstIndex(where: { $0.beatId == beatId }) else { return }
        var inserted = alternatives[alternativeIndex]
        inserted.beatId = "beat_\(String(format: "%02d", sourceIndex + 2))_\(shortHash("\(board.beatBoardId):insert:\(beatId):\(DateFormats.now())", length: 8))"
        inserted.locked = false
        inserted.revisionHistory.append(revision(for: ordered[sourceIndex], operation: "insert_alternative_source"))
        var next = ordered
        next.insert(inserted, at: sourceIndex + 1)
        let hidden = board.beats.filter(\.isDeleted)
        board.beats = renumberStoryBeats(next) + hidden
        board.updatedAt = DateFormats.now()
        do {
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(board, project: project, status: "Story Beat alternative inserted")
            markSceneAssetsStale(beatIds: [], sequenceChanged: true)
            storyBeatAlternativesByBeatId[beatId] = nil
        } catch {
            lastError = error.localizedDescription
        }
    }

    func branchStoryBeatAlternative(beatId: String, alternativeIndex: Int) {
        guard let project = currentProject,
              let alternatives = storyBeatAlternativesByBeatId[beatId],
              alternatives.indices.contains(alternativeIndex) else { return }
        var board = storyBeatBoard
        guard let index = board.beats.firstIndex(where: { $0.beatId == beatId }) else { return }
        var alternative = alternatives[alternativeIndex]
        alternative.beatId = beatId
        alternative.order = board.beats[index].order
        board.beatBoardId = "board_\(shortHash("\(project.projectId):branch:\(beatId):\(DateFormats.now())", length: 14))"
        board.title = board.title.isEmpty ? "Branched Beat Board" : "\(board.title) Branch"
        board.isActiveDraft = true
        board.generatedAt = DateFormats.now()
        board.updatedAt = DateFormats.now()
        board.beats[index] = alternative
        do {
            try persistStoryBeatBoard(board, project: project, status: "Story Beat alternative branched")
            storyBeatAlternativesByBeatId[beatId] = nil
        } catch {
            lastError = error.localizedDescription
        }
    }

    func acceptActiveProjectStory() {
        guard let project = currentProject else { return }
        guard storyBeatBoard.hasBeats else {
            storyStatus = "Generate a Beat Board first"
            return
        }
        let now = DateFormats.now()
        let acceptedDirection = storyDirectionSet.directions.first {
            $0.directionId == (storyBeatBoard.primaryDirectionId.isEmpty ? storyBeatBoard.parentDirectionId : storyBeatBoard.primaryDirectionId)
        } ?? storyDirectionSet.selectedDirection
        let accepted = ProjectStoryDocument.accepted(
            projectId: project.projectId,
            direction: acceptedDirection,
            board: storyBeatBoard,
            setup: storySetup,
            aestheticRecipe: projectAestheticBrief.chosenDirection,
            acceptedAt: now
        )
        do {
            try contextStore.saveProjectStory(accepted, for: project)
            var workspace = storyWorkspace
            workspace.acceptedStoryId = accepted.acceptedStoryId
            workspace.acceptedProjectStoryId = accepted.acceptedStoryId
            workspace.status = "Project Story accepted"
            workspace.updatedAt = now
            try contextStore.saveStoryWorkspace(workspace, for: project)
            projectStory = accepted
            storyWorkspace = workspace
            scenesUseDraftBoard = false
            ensureSceneWorkspaceForActiveContext(preferDraftBoard: false)
            storyStatus = "Project Story accepted"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Project Story acceptance failed"
        }
    }

    func useActiveDraftBoardForScenes() {
        scenesUseDraftBoard = true
        ensureSceneWorkspaceForActiveContext(preferDraftBoard: true)
    }

    func useAcceptedProjectStoryForScenes() {
        scenesUseDraftBoard = false
        ensureSceneWorkspaceForActiveContext(preferDraftBoard: false)
    }

    func ensureSceneWorkspaceForActiveContext(preferDraftBoard: Bool? = nil) {
        guard let project = currentProject else { return }
        let useDraft = preferDraftBoard ?? scenesUseDraftBoard
        let preferredBoard: StoryBeatBoard
        let sourceProjectStory: ProjectStoryDocument
        if !useDraft,
           projectStory.hasAcceptedStory,
           let acceptedBoard = storyBeatBoards.first(where: { $0.beatBoardId == projectStory.beatBoardId }) {
            preferredBoard = acceptedBoard
            sourceProjectStory = projectStory
        } else {
            preferredBoard = storyBeatBoard
            sourceProjectStory = .empty(projectId: project.projectId)
        }
        guard preferredBoard.hasBeats else {
            storyStatus = "Open Beats before Scenes"
            return
        }

        if sceneWorkspace.freshness(activeBoard: preferredBoard, acceptedStory: sourceProjectStory) == .fresh,
           sceneWorkspace.sourceBeatBoardId == preferredBoard.beatBoardId,
           sceneWorkspace.sourceArtifactType == (sourceProjectStory.hasAcceptedStory ? .projectStory : .beatBoard) {
            return
        }

        let now = DateFormats.now()
        var workspaceDocument = SceneWorkspaceDocument.forContext(
            projectId: project.projectId,
            projectStory: sourceProjectStory,
            beatBoard: preferredBoard,
            createdAt: now
        )
        if !sceneWorkspace.sceneWorkspaceId.isEmpty,
           sceneWorkspace.sourceBeatBoardId == preferredBoard.beatBoardId,
           sceneWorkspace.sourceProjectStoryId == sourceProjectStory.acceptedStoryId,
           sceneWorkspace.sourceArtifactType == workspaceDocument.sourceArtifactType {
            workspaceDocument.sceneWorkspaceId = sceneWorkspace.sceneWorkspaceId
            workspaceDocument.createdAt = sceneWorkspace.createdAt
            workspaceDocument.assetIds = sceneWorkspace.assetIds
        }

        do {
            try contextStore.saveSceneWorkspace(workspaceDocument, for: project)
            sceneWorkspace = workspaceDocument
            sceneWorkspaces = contextStore.loadSceneWorkspaces(for: project)
            var workspace = self.storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.activeSceneWorkspaceId = workspaceDocument.sceneWorkspaceId
            workspace.currentStep = .scenes
            workspace.status = "Scenes ready"
            workspace.updatedAt = DateFormats.now()
            try contextStore.saveStoryWorkspace(workspace, for: project)
            storyWorkspace = workspace
            sceneAssets = contextStore.loadSceneAssets(for: project)
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Scenes workspace failed"
        }
    }

    func ensureActiveVideoChainLoaded() {
        guard let project = currentProject, videoChain.chainId.isEmpty else { return }
        let loadedVideoChains = contextStore.loadVideoChainsWithDiagnostics(for: project)
        videoChains = loadedVideoChains.chains
        videoChainLoadIssues = loadedVideoChains.issues
        var workspace = storyWorkspace
        let restoredChain = activeLoadedVideoChain(
            workspace.activeVideoChainId,
            loadedStoryWorkspace: &workspace,
            project: project
        )
        storyWorkspace = workspace
        videoChain = restoredChain
        videoChainStatus = restoredVideoChainStatus(
            chain: restoredChain,
            issueCount: loadedVideoChains.issues.count
        )
    }

