    func sceneAssetForMatrix(beat: StoryBeatBoardBeat, layerType: SceneLayerType) -> SceneAssetDocument {
        let context = currentSceneSourceContext()
        let assetId = SceneAssetDocument.deterministicAssetId(
            sourceArtifactId: context.sourceArtifactId,
            beatId: beat.beatId,
            layerType: layerType
        )
        if var existing = sceneAssets.first(where: { $0.assetId == assetId }) {
            if layerType == .audio {
                existing = audioDecoratedSceneAsset(existing, beat: beat)
            }
            return existing
        }
        let draft = SceneAssetDocument.draft(
            projectId: currentProject?.projectId ?? "",
            sourceArtifactType: context.sourceArtifactType,
            sourceArtifactId: context.sourceArtifactId,
            sourceProjectStoryId: context.sourceProjectStoryId,
            beatBoard: context.board,
            beat: beat,
            layerType: layerType
        )
        return layerType == .audio ? audioDecoratedSceneAsset(draft, beat: beat) : draft
    }

    func prepareSceneLayersForActiveContext(refreshPrompts: Bool = false) async {
        guard let project = currentProject else { return }
        ensureSceneWorkspaceForActiveContext()
        let context = currentSceneSourceContext()
        guard !context.beats.isEmpty else {
            storyStatus = "No beats for Scenes"
            return
        }
        isPreparingSceneLayers = true
        defer { isPreparingSceneLayers = false }
        do {
            var updatedAssets = sceneAssets
            var workspace = sceneWorkspace
            for beat in context.beats {
                for layer in SceneLayerType.productionMatrixOrder {
                    let draft = SceneAssetDocument.draft(
                        projectId: project.projectId,
                        sourceArtifactType: context.sourceArtifactType,
                        sourceArtifactId: context.sourceArtifactId,
                        sourceProjectStoryId: context.sourceProjectStoryId,
                        beatBoard: context.board,
                        beat: beat,
                        layerType: layer
                    )
                    let asset = refreshedSceneAsset(existing: updatedAssets.first { $0.assetId == draft.assetId }, draft: draft, refreshPrompts: refreshPrompts)
                    try contextStore.saveSceneAsset(asset, for: project)
                    if let index = updatedAssets.firstIndex(where: { $0.assetId == asset.assetId }) {
                        updatedAssets[index] = asset
                    } else {
                        updatedAssets.append(asset)
                    }
                    if !workspace.assetIds.contains(asset.assetId) {
                        workspace.assetIds.append(asset.assetId)
                    }
                }
            }
            workspace.updatedAt = DateFormats.now()
            try contextStore.saveSceneWorkspace(workspace, for: project)
            sceneWorkspace = workspace
            sceneAssets = updatedAssets.sorted { $0.updatedAt > $1.updatedAt }
            sceneWorkspaces = contextStore.loadSceneWorkspaces(for: project)
            storyStatus = refreshPrompts ? "Scene prompts refreshed" : "Scene layers prepared"
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Scene layer preparation failed"
        }
    }

    func updateSceneAsset(
        assetId: String,
        prompt: String,
        negativePrompt: String,
        textOverlay: String,
        captionDraft: String
    ) {
        guard let project = currentProject else { return }
        var asset = sceneAssets.first(where: { $0.assetId == assetId })
        if asset == nil,
           let beat = activeSceneSourceBeats.first(where: { beat in SceneLayerType.productionMatrixOrder.contains { layer in SceneAssetDocument.deterministicAssetId(sourceArtifactId: currentSceneSourceContext().sourceArtifactId, beatId: beat.beatId, layerType: layer) == assetId } }) {
            let layer = SceneLayerType.productionMatrixOrder.first {
                SceneAssetDocument.deterministicAssetId(sourceArtifactId: currentSceneSourceContext().sourceArtifactId, beatId: beat.beatId, layerType: $0) == assetId
            } ?? .still
            asset = sceneAssetForMatrix(beat: beat, layerType: layer)
        }
        guard var updated = asset else { return }
        updated.prompt = prompt
        updated.negativePrompt = negativePrompt
        updated.textOverlay = textOverlay
        updated.captionDraft = captionDraft
        updated.isManuallyEdited = true
        updated.manualEditFields = uniqueNonEmpty(updated.manualEditFields + ["prompt", "negative_prompt", "text_overlay", "caption"])
        updated.status = .edited
        updated.updatedAt = DateFormats.now()
        do {
            try contextStore.saveSceneAsset(updated, for: project)
            if let index = sceneAssets.firstIndex(where: { $0.assetId == updated.assetId }) {
                sceneAssets[index] = updated
            } else {
                sceneAssets.append(updated)
            }
        } catch {
            lastError = error.localizedDescription
        }
    }

    func exportScenePromptsForActiveContext() async {
        guard let project = currentProject else { return }
        let context = currentSceneSourceContext()
        guard !context.beats.isEmpty else {
            scenePromptExportStatus = "No scene prompts to export"
            return
        }
        let now = DateFormats.now()
        let exportId = "\(now)_scene_prompts"
        let layers = context.beats.flatMap { beat in
            SceneLayerType.productionMatrixOrder.map { layer -> ScenePromptExportLayer in
                let asset = sceneAssetForMatrix(beat: beat, layerType: layer)
                return ScenePromptExportLayer(
                    layerId: asset.assetId,
                    beatId: beat.beatId,
                    layerType: layer,
                    status: asset.status,
                    prompt: asset.prompt,
                    negativePrompt: asset.negativePrompt,
                    textOverlay: asset.textOverlay,
                    captionDraft: asset.captionDraft,
                    sourceMediaIds: asset.sourceMediaIds,
                    avoidMediaIds: asset.avoidMediaIds,
                    referenceMediaIds: asset.referenceMediaIds,
                    isManuallyEdited: asset.isManuallyEdited,
                    manualEditFields: asset.manualEditFields,
                    promptTemplateVersion: asset.promptTemplateVersion,
                    sourceBeatFingerprint: asset.sourceBeatFingerprint,
                    sourceBoardFingerprint: asset.sourceBoardFingerprint
                )
            }
        }
        let document = ScenePromptExportDocument(
            projectId: project.projectId,
            exportId: exportId,
            exportedAt: now,
            sourceArtifactType: context.sourceArtifactType,
            sourceArtifactId: context.sourceArtifactId,
            sourceProjectStoryId: context.sourceProjectStoryId,
            sourceBeatBoardId: context.board.beatBoardId,
            sourceBoardFingerprint: context.board.inputFingerprint.stableId,
            layers: layers
        )
        let markdownURL = contextStore.scenePromptExportMarkdownURL(for: project, exportId: exportId)
        let jsonURL = contextStore.scenePromptExportJSONURL(for: project, exportId: exportId)
        do {
            let markdown = scenePromptMarkdown(document: document, beats: context.beats)
            let json = try JSONCoding.prettyEncoder.encode(document)
            try await Task.detached(priority: .utility) {
                try FileManager.default.createDirectory(at: markdownURL.deletingLastPathComponent(), withIntermediateDirectories: true)
                try markdown.write(to: markdownURL, atomically: true, encoding: .utf8)
                try json.write(to: jsonURL, options: [.atomic])
            }.value
            scenePromptExportStatus = "Exported scene prompts"
            storyStatus = "Scene prompts exported"
        } catch {
            lastError = error.localizedDescription
            scenePromptExportStatus = "Scene prompt export failed"
        }
    }

