    func saveProviderCredential(_ provider: LitScenesProviderCredential, value: String) throws {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            try removeProviderCredential(provider)
            return
        }
        var values = loadDotEnv(from: OpenAIKeyStore.savedKeyURL)
        for key in provider.keyCandidates where key != provider.primaryWritableKey {
            values.removeValue(forKey: key)
        }
        values[provider.primaryWritableKey] = trimmed
        try OpenAIKeyStore.saveCredentialValues(values)
        providerCredentialsRevision += 1
        refreshVideoChainAfterCredentialChange(status: "\(provider.label) credential saved")
        queueInitialStoryGenerationIfEligible()
    }

    func removeProviderCredential(_ provider: LitScenesProviderCredential) throws {
        var values = loadDotEnv(from: OpenAIKeyStore.savedKeyURL)
        for key in provider.keyCandidates {
            values.removeValue(forKey: key)
        }
        try OpenAIKeyStore.saveCredentialValues(values)
        providerCredentialsRevision += 1
        refreshVideoChainAfterCredentialChange(status: "\(provider.label) credential removed")
    }

