    private func queueInitialStoryGenerationIfEligible() {
        guard initialStoryGenerationTask == nil,
              initialStoryGenerationIsEligible else {
            return
        }
        initialStoryGenerationTask = Task { [weak self] in
            guard let self else { return }
            await Task.yield()
            guard self.initialStoryGenerationIsEligible else {
                self.initialStoryGenerationTask = nil
                return
            }
            await self.generateSceneStoriesForReadyLens(origin: .goalConversationAutomatic)
            self.initialStoryGenerationTask = nil
        }
    }

    private var initialStoryGenerationIsEligible: Bool {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion,
              version.brief.isReady,
              !isInterviewingGoal,
              hasHydratedGoalCast,
              hasFreshLensContextForActiveGoal,
              !readyLenses.isEmpty,
              hasSceneStoryProviderConfiguration,
              !isGeneratingSceneStories,
              !hasVisibleStoryLibraryEntries else {
            return false
        }
        let fingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        return !storyGenerationSessions.contains { $0.goalFingerprint == fingerprint }
    }

    func generateSceneStoriesForReadyLens(
        lensId: String? = nil,
        mode: StoryGenerationMode = .avoidOverlap,
        reference: StoryMemoryReference? = nil,
        requestedStoryCount: Int = SceneStoryGenerationSizing.defaultStoryBatchCount,
        requestedStartingDepth: StoryStartingDepth = .fourSceneArc,
        differenceMode: StoryDifferenceMode = .distinct,
        groundingMode: StoryGroundingMode = .balanced,
        origin: StoryGenerationOrigin = .manual
    ) async {
        guard let project = currentProject else {
            sceneStoryStatus = "Create or select a project first"
            return
        }
        guard let version = projectGoalV2.activeVersion, version.brief.isReady else {
            sceneStoryStatus = "Save a Goal first"
            return
        }
        let goalFingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        guard lensContext.isReady(forGoalVersionId: version.versionId, goalFingerprint: goalFingerprint),
              let lensContextResponse = lensContext.response else {
            sceneStoryStatus = "Retrieve Frame Context first"
            return
        }
        let requestedLensId = lensId?.trimmed ?? ""
        let selectedLensId = requestedLensId.isEmpty ? nil : requestedLensId
        guard let theme = selectedLensId.flatMap({ id in readyLenses.first { $0.lensId == id } }) ?? readyLenses.first else {
            sceneStoryStatus = "Mark a Scene Plan ready first"
            return
        }
        guard hasHydratedGoalCast else {
            sceneStoryStatus = isArticulatingGoalCast ? "Character hydration is still running" : "Hydrate the Goal cast first"
            return
        }
        guard hasSceneStoryProviderConfiguration else {
            sceneStoryStatus = "Configure the Story provider endpoint and token"
            return
        }

        let requestedCount = min(max(requestedStoryCount, 1), 6)
        let lensContextFingerprint = stableHash(lensContextResponse)
        let lensRefs = storyGenerationLensReferences(primaryLens: theme)
        let goalCastSnapshot = goalCast.members.map { SceneStoryGoalCastMemberSnapshot.from(member: $0) }
        let mediaAnchors = sceneStoryMediaAnchors(for: theme)
        let selectedMediaIds = uniqueNonEmpty(mediaAnchors.map(\.mediaId))
        let priorSignatures = selectedPriorStorySignatures(
            goalFingerprint: goalFingerprint,
            lensContextFingerprint: lensContextFingerprint,
            lensIds: lensRefs.map(\.lensId),
            limit: 12
        )
        var storyMemory = StoryMemoryRequest(
            mode: mode,
            priorStorySignatures: priorSignatures,
            positiveReferenceStory: mode == .moreLikeSelected ? reference : nil,
            branchParentStory: mode == .branchSelected ? reference : nil,
            reflowSelectedStory: mode == .reflowSelected ? reference : nil,
            preserveDimensions: storyMemoryPreserveDimensions(for: mode),
            varyDimensions: storyMemoryVaryDimensions(for: mode),
            avoidElements: storyMemoryAvoidElements(priorSignatures: priorSignatures, mode: mode)
        ).normalized(limit: 12)
        let generationBrief = sceneStoryGenerationBrief(
            goal: version.brief,
            theme: theme,
            generationMode: mode,
            differenceMode: differenceMode,
            groundingMode: groundingMode,
            storyMemory: storyMemory,
            hasMediaAnchors: !mediaAnchors.isEmpty
        )
        let referenceStories = [
            storyMemory.positiveReferenceStory,
            storyMemory.branchParentStory,
            storyMemory.reflowSelectedStory
        ].compactMap { $0 }
        let creativeContext = StoryGenerationCreativeContextSnapshot(
            goalVersionId: version.versionId,
            goalFingerprint: goalFingerprint,
            lensContextFingerprint: lensContextFingerprint,
            lensRefs: lensRefs,
            generationOrigin: origin,
            goalCast: goalCastSnapshot,
            mediaAnalysisFingerprint: stableHash(mediaObservationsById.keys.sorted(), length: 20),
            selectedMediaIds: selectedMediaIds,
            outputContextFingerprint: stableHash(projectOutputContext, length: 20),
            generationControls: [
                "mode": mode.rawValue,
                "requested_story_count": "\(requestedCount)",
                "requested_starting_depth": requestedStartingDepth.rawValue,
                "difference_mode": differenceMode.rawValue,
                "grounding_mode": groundingMode.rawValue,
                "origin": origin.rawValue
            ],
            priorStorySignatures: priorSignatures,
            referenceStories: referenceStories
        )
        var session = StoryGenerationSessionDocument.create(
            projectId: project.projectId,
            goalFingerprint: goalFingerprint,
            lensContextFingerprint: lensContextFingerprint,
            lensRefs: lensRefs,
            generationOrigin: origin,
            mode: mode,
            requestedStoryCount: requestedCount,
            requestedStartingDepth: requestedStartingDepth,
            differenceMode: differenceMode,
            groundingMode: groundingMode,
            creativeContext: creativeContext
        )
        let generationBatchId = storyUUIDIdentifier("story_generation_batch")
        let baseRequest = SceneStoryGenerateRequest(
            projectId: project.projectId,
            goalFingerprint: goalFingerprint,
            lensId: theme.lensId,
            lensContextFingerprint: lensContextFingerprint,
            generationSessionId: session.generationSessionId,
            generationBatchId: generationBatchId,
            batchSlot: 0,
            batchSize: requestedCount,
            lensRefs: lensRefs,
            generationOrigin: origin,
            goal: version.brief.normalized(),
            goalCast: goalCastSnapshot,
            lens: SceneStoryLensSnapshot.from(lens: theme),
            lensContext: lensContextResponse,
            mediaAnchors: mediaAnchors,
            outputProfile: sceneStoryOutputProfile(),
            storyCount: SceneStoryGenerationSizing.initialStoryCount,
            scenesPerStory: requestedStartingDepth.scenesPerStory,
            beatsPerScene: SceneStoryGenerationSizing.initialBeatsPerScene,
            generationMode: mode,
            requestedStartingDepth: requestedStartingDepth,
            differenceMode: differenceMode,
            groundingMode: groundingMode,
            storyMemory: storyMemory,
            generationIntent: StoryGenerationIntent(),
            storyGenerationBrief: generationBrief,
            toneConstraints: sceneStoryToneConstraints(goal: version.brief, theme: theme),
            operatorInstructions: []
        )

        isGeneratingSceneStories = true
        defer {
            isGeneratingSceneStories = false
        }
        do {
            try contextStore.saveStoryGenerationSession(session, for: project)
            mergeStoryGenerationSession(session)
        } catch {
            lastError = error.localizedDescription
            sceneStoryGenerationProgress = SceneStoryGenerationProgress(
                title: "Story Generation could not start",
                detail: "The generation session could not be saved, so no provider request was sent.",
                status: "failed",
                completedStepCount: 0,
                totalStepCount: 6,
                schemaPreview: sceneStorySchemaPreview(title: "Story Generation request", value: baseRequest)
            )
            sceneStoryStatus = "Story Generation could not start"
            print("[story_generation] error: session persistence failed project_id=\(project.projectId) origin=\(origin.rawValue) error=\(error.localizedDescription)")
            return
        }
        sceneStoryGenerationProgress = SceneStoryGenerationProgress(
            title: "Preparing creative context",
            detail: "Using the saved Goal, planned Frames, media understanding, and \(priorSignatures.count) prior Story signature\(priorSignatures.count == 1 ? "" : "s") to seek new territory.",
            status: "running",
            completedStepCount: 1,
            totalStepCount: 6,
            schemaPreview: sceneStorySchemaPreview(title: "Story Generation request", value: baseRequest)
        )
        sceneStoryStatus = "Creating \(requestedCount) Stories"
        print("[story_generation] starting project_id=\(project.projectId) session_id=\(session.generationSessionId) origin=\(origin.rawValue) lens_count=\(lensRefs.count) cast_count=\(goalCastSnapshot.count) requested_stories=\(requestedCount) prior_signatures=\(priorSignatures.count)")

        do {
            let client = try StoryInferenceService.fromEnvironment()
            var sameSessionSignatures: [StorySignatureDocument] = []
            var savedStoryTitles: [String] = []
            for slotIndex in session.slots.indices {
                try Task.checkCancellation()
                try await waitWhileGenerationPaused()
                let runIndex = slotIndex
                session.slots[slotIndex].status = .generating
                session.slots[slotIndex].startedAt = DateFormats.now()
                session.status = "running"
                try? contextStore.saveStoryGenerationSession(session, for: project)
                mergeStoryGenerationSession(session)
                var request = baseRequest
                storyMemory.priorStorySignatures = deduplicatedStorySignatures(
                    sameSessionSignatures + priorSignatures,
                    limit: 12
                )
                request.storyMemory = storyMemory.normalized(limit: 12)
                request.batchSlot = runIndex + 1
                request.batchSize = requestedCount
                request.generationIntent = sceneStoryGenerationIntent(
                    runIndex: runIndex,
                    generationMode: mode
                )
                request.operatorInstructions = sceneStoryGenerationInstructions(
                    runIndex: runIndex,
                    totalRunCount: requestedCount,
                    scenesPerStory: request.scenesPerStory,
                    beatsPerScene: request.beatsPerScene,
                    generationMode: mode,
                    priorStoryCount: request.storyMemory.priorStorySignatures.count,
                    hasMediaAnchors: !request.mediaAnchors.isEmpty,
                    hasSourcedSpeech: false
                )
                sceneStoryGenerationProgress = SceneStoryGenerationProgress(
                    title: "Creating Story \(runIndex + 1) of \(requestedCount)",
                    detail: "Considering \(request.storyMemory.priorStorySignatures.count) prior Story signature\(request.storyMemory.priorStorySignatures.count == 1 ? "" : "s") while keeping this Story structurally distinct.",
                    status: "running",
                    completedStepCount: 2 + min(runIndex, 3),
                    totalStepCount: 6,
                    storyTitles: savedStoryTitles,
                    schemaPreview: sceneStorySchemaPreview(title: "Story \(runIndex + 1) request", value: request)
                )
                sceneStoryStatus = "Creating Story \(runIndex + 1) of \(requestedCount)"

                do {
                    let initialSnapshot = try contextStore.saveStoryGenerationRequestSnapshot(
                        request,
                        for: project,
                        generationSessionId: session.generationSessionId,
                        slotIndex: runIndex + 1,
                        attemptIndex: 1
                    )
                    let initialAttempt = storyGenerationAttemptRecord(
                        request: request,
                        snapshot: initialSnapshot,
                        slotIndex: runIndex + 1,
                        attemptIndex: 1,
                        purpose: "creative_generation",
                        status: "started"
                    )
                    session.slots[slotIndex].requestSnapshotPath = initialSnapshot.relativePath
                    session.slots[slotIndex].requestFingerprint = initialSnapshot.fingerprint
                    session.slots[slotIndex].promptTemplateVersion = sceneStoryDesktopInstructionVersion
                    session.slots[slotIndex].operatorInstructionSnapshot = request.operatorInstructions
                    session.slots[slotIndex].storyMemorySignatureIds = request.storyMemory.priorStorySignatures.map(\.storySignatureId)
                    session.slots[slotIndex].attemptRecords.append(initialAttempt)
                    try? contextStore.saveStoryGenerationSession(session, for: project)
                    mergeStoryGenerationSession(session)

                    let result = try await generateNovelStorySet(
                        client: client,
                        request: request,
                        project: project,
                        session: session,
                        slotIndex: slotIndex,
                        priorSignatures: request.storyMemory.priorStorySignatures,
                        initialAttemptRecord: initialAttempt
                    )
                    try Task.checkCancellation()
                    guard currentProject?.projectId == project.projectId,
                          projectGoalV2.activeVersion?.versionId == version.versionId,
                          lensContext.isReady(forGoalVersionId: version.versionId, goalFingerprint: goalFingerprint) else {
                        return
                    }
                    let normalized = result.set.normalized()
                    guard let story = normalized.sceneStories.first?.normalized() else {
                        throw NSError(domain: "LitScenesSceneStory", code: 422, userInfo: [NSLocalizedDescriptionKey: "Story response did not contain a Story."])
                    }
                    let suggestionId = storyUUIDIdentifier("story_suggestion")
                    let now = DateFormats.now()
                    let version = initialProjectStoryVersion(
                        story: story,
                        sourceStorySuggestionId: suggestionId,
                        reason: "Generated Story",
                        now: now
                    )
                    var signature = makeStorySignature(
                        story: story,
                        project: project,
                        storySuggestionId: suggestionId,
                        sourceSceneStorySetId: normalized.sceneStorySetId,
                        sourceStoryId: story.storyId,
                        generationSessionId: session.generationSessionId,
                        goalFingerprint: goalFingerprint,
                        lensContextFingerprint: lensContextFingerprint,
                        lensIds: lensRefs.map(\.lensId),
                        editorialState: .kept,
                        productionState: .notStarted,
                        contextClass: .currentContext
                    )
                    signature = projectStorySignature(
                        signature,
                        version: version,
                        editorialState: .kept,
                        productionState: .notStarted,
                        now: now
                    )
                    try contextStore.saveSceneStorySet(normalized, for: project)
                    try contextStore.saveProjectStoryVersion(version, for: project)
                    try contextStore.saveStorySignature(signature, for: project)
                    mergeStorySignature(signature)
                    var libraryDocument = storyLibrary
                    if libraryDocument.projectId.isEmpty {
                        libraryDocument.projectId = project.projectId
                    }
                    libraryDocument.entries.append(ProjectStoryLibraryEntry(
                        storySuggestionId: suggestionId,
                        projectStoryId: version.projectStoryId,
                        sourceSceneStorySetId: normalized.sceneStorySetId,
                        sourceStoryId: story.storyId,
                        generationSessionId: session.generationSessionId,
                        editorialState: .kept,
                        productionState: .notStarted,
                        title: story.title,
                        lensIds: lensRefs.map(\.lensId),
                        currentVersionId: version.storyVersionId,
                        storySignatureId: signature.storySignatureId,
                        createdAt: now,
                        updatedAt: now
                    ).normalized())
                    if !hasVisibleActiveStory(in: libraryDocument) {
                        libraryDocument.activeStoryId = version.projectStoryId
                    }
                    libraryDocument.updatedAt = now
                    try contextStore.saveProjectStoryLibrary(libraryDocument, for: project)
                    storyLibrary = libraryDocument.normalized()
                    sceneStorySets.removeAll { $0.sceneStorySetId == normalized.sceneStorySetId }
                    sceneStorySets.insert(normalized, at: 0)
                    sceneStorySets.sort { $0.generatedAt > $1.generatedAt }

                    session.slots[slotIndex].status = .complete
                    session.slots[slotIndex].sourceSceneStorySetId = normalized.sceneStorySetId
                    session.slots[slotIndex].sourceStoryId = story.storyId
                    session.slots[slotIndex].storySuggestionId = suggestionId
                    session.slots[slotIndex].storySignatureId = signature.storySignatureId
                    session.slots[slotIndex].title = story.title
                    session.slots[slotIndex].completedAt = DateFormats.now()
                    session.slots[slotIndex].relatedVariantOfStoryId = result.relatedVariantOfStoryId
                    session.slots[slotIndex].relatedVariantReasons = result.relatedVariantReasons
                    if let acceptedAttempt = result.attemptRecords.last {
                        session.slots[slotIndex].requestSnapshotPath = acceptedAttempt.requestSnapshotPath
                        session.slots[slotIndex].requestFingerprint = acceptedAttempt.requestFingerprint
                        session.slots[slotIndex].promptTemplateVersion = acceptedAttempt.promptTemplateVersion
                        session.slots[slotIndex].operatorInstructionSnapshot = acceptedAttempt.operatorInstructionSnapshot
                        session.slots[slotIndex].storyMemorySignatureIds = acceptedAttempt.storyMemorySignatureIds
                        session.slots[slotIndex].openaiResponseId = acceptedAttempt.openaiResponseId
                        session.slots[slotIndex].hostedRequestId = acceptedAttempt.hostedRequestId
                    }
                    session.slots[slotIndex].attemptRecords = result.attemptRecords
                    session.sourceSetIds.append(normalized.sceneStorySetId)
                    session.resultStoryRefs.append(version.projectStoryId)
                    try? contextStore.saveStoryGenerationSession(session, for: project)
                    mergeStoryGenerationSession(session)
                    // Text inference spends real provider money (the user's own
                    // key in Direct mode); every completed Story lands a ledger
                    // row. Token counts come from the attempt provenance —
                    // honestly unpriced, never $0.
                    let storyTokens = result.usageTokens
                    if storyTokens > 0 {
                        recordSpend(SpendLedgerEntry(
                            kind: "story_inference",
                            provider: "openai",
                            model: normalized.model,
                            requestId: result.lastResponseId,
                            contextLabel: story.title.trimmed.nilIfEmpty ?? "Story \(runIndex + 1)",
                            unit: "tokens",
                            unitCount: Double(storyTokens),
                            pricingNote: StoryInferenceMode.resolved() == .direct
                                ? "Billed by your OpenAI-compatible provider."
                                : "Billed through LitScenes Hosted at the published markup.",
                            status: "completed"
                        ))
                    }
                    signature.contextClass = .sameSession
                    sameSessionSignatures = deduplicatedStorySignatures(
                        [signature] + sameSessionSignatures,
                        limit: requestedCount
                    )
                    savedStoryTitles.append(story.title)
                    touchCurrentProject()
                    print("[story_generation] completed_story project_id=\(project.projectId) session_id=\(session.generationSessionId) story_index=\(runIndex + 1)/\(requestedCount) set_id=\(normalized.sceneStorySetId) story_id=\(version.projectStoryId) suggestion_id=\(suggestionId)")
                } catch {
                    if Task.isCancelled || isCancellationLikeError(error) {
                        session.slots[slotIndex].status = .cancelled
                        session.slots[slotIndex].cancelledAt = DateFormats.now()
                    } else {
                        session.slots[slotIndex].status = .failed
                        session.slots[slotIndex].failedAt = DateFormats.now()
                        session.slots[slotIndex].errorMessage = error.localizedDescription
                    }
                    try? contextStore.saveStoryGenerationSession(session, for: project)
                    mergeStoryGenerationSession(session)
                    print("[story_generation] slot_error project_id=\(project.projectId) session_id=\(session.generationSessionId) story_index=\(runIndex + 1)/\(requestedCount) error=\"\(error.localizedDescription)\"")
                    if Task.isCancelled || isCancellationLikeError(error) {
                        break
                    }
                }
            }
            session.completedAt = DateFormats.now()
            if session.completedSlotCount == requestedCount {
                session.status = "complete"
            } else if session.completedSlotCount > 0 {
                session.status = "partial"
            } else if session.slots.contains(where: { $0.status == .cancelled }) {
                session.status = "cancelled"
            } else {
                session.status = "failed"
            }
            try? contextStore.saveStoryGenerationSession(session, for: project)
            mergeStoryGenerationSession(session)
            let failedIndexes = session.slots
                .filter { $0.status == .failed }
                .map { "Story \($0.index)" }
                .joined(separator: ", ")
            let finalTitle = "\(session.completedSlotCount) of \(requestedCount) \(requestedCount == 1 ? "Story" : "Stories") ready"
            let finalDetail = failedIndexes.isEmpty
                ? "The completed \(session.completedSlotCount == 1 ? "Story is" : "Stories are") saved."
                : "\(failedIndexes) timed out. The completed \(session.completedSlotCount == 1 ? "Story is" : "Stories are") saved."
            sceneStoryGenerationProgress = SceneStoryGenerationProgress(
                title: finalTitle,
                detail: finalDetail,
                status: session.status,
                completedStepCount: 6,
                totalStepCount: 6,
                storyTitles: savedStoryTitles,
                schemaPreview: sceneStoryGenerationProgress.schemaPreview
            )
            sceneStoryStatus = "\(session.completedSlotCount) of \(requestedCount) Stories ready"
            print("[story_generation] completed project_id=\(project.projectId) session_id=\(session.generationSessionId) completed_stories=\(session.completedSlotCount) failed_stories=\(session.failedSlotCount)")
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return
            }
            lastError = error.localizedDescription
            sceneStoryGenerationProgress = SceneStoryGenerationProgress(
                title: "Story Generation failed",
                detail: error.localizedDescription,
                status: "failed",
                completedStepCount: 0,
                totalStepCount: 6,
                schemaPreview: sceneStoryGenerationProgress.schemaPreview
            )
            sceneStoryStatus = "Story Generation failed"
            print("[story_generation] error: \(error.localizedDescription)")
        }
    }

    private func sceneStoryGenerationInstructions(
        runIndex: Int,
        totalRunCount: Int,
        scenesPerStory: Int,
        beatsPerScene: Int,
        generationMode: StoryGenerationMode,
        priorStoryCount: Int,
        hasMediaAnchors: Bool,
        hasSourcedSpeech: Bool
    ) -> [String] {
        let sceneCount = max(scenesPerStory, 1)
        let beatCount = max(beatsPerScene, 1)
        var instructions = [
            "Generate Story \(runIndex + 1) of \(totalRunCount) as a complete standalone Story.",
            "Use exactly one Story, \(sceneCount) Scene\(sceneCount == 1 ? "" : "s"), and \(beatCount) Beat\(beatCount == 1 ? "" : "s") per Scene.",
            "TERMINOLOGY: Use Story, Scene, and Beat. Never use Route or Narrative as a countable product object.",
            "Typed generation_intent contains optional architecture, Compass locks, structural exclusions, and Beat complexity limits. Treat explicit values as source of truth.",
            "Typed story_memory contains \(priorStoryCount) prior Story signature\(priorStoryCount == 1 ? "" : "s"). Treat them as structural novelty/reference context; do not ask for or repeat their full prose here.",
            "Each Scene must perform one clear dramatic job. Each Beat must contain one dominant action, one coherent camera behavior, and no more than two visible state changes.",
            "A Beat must visibly or audibly prove its emotional turn. Abstract intention, a slogan, a progress bar, applause, or a group gathering does not by itself count as proof."
        ]

        switch generationMode {
        case .avoidOverlap:
            instructions.append("STRUCTURAL NOVELTY: Avoid repeating the same causal mechanism, central visual image, and ending consequence from prior Stories.")
            instructions.append("Changing only a device, prop, graphic treatment, room, interface, or camera framing does not create a different Story.")
        case .moreLikeSelected:
            instructions.append("MORE LIKE THIS: Preserve only story_memory.preserve_dimensions and materially vary story_memory.vary_dimensions.")
        case .branchSelected:
            instructions.append("BRANCH: Similarity to the parent is expected. Preserve only requested parent constraints and change only requested branch dimensions.")
        case .reflowSelected:
            instructions.append("REFLOW: Preserve Story identity and locked/requested material. Improve unlocked emotional handoffs, visible proof, and continuity.")
        case .ignoreHistory:
            instructions.append("IGNORE HISTORY: Do not compare against prior Stories, but still produce one focused Story rather than a montage.")
        }

        if !hasMediaAnchors {
            instructions.append("GROUNDING: No media anchors are attached. Favor clearly conceptual, object-led, environmental, graphic, or staged-fiction approaches over faux-documentary testimony.")
        }
        if !hasSourcedSpeech {
            instructions.append("DIALOGUE: No sourced speech is attached. Any invented dialogue must be plain, culturally unmarked, and marked generated_plain or generated_placeholder.")
        }
        return instructions
    }

    private func sceneStoryGenerationIntent(runIndex _: Int, generationMode _: StoryGenerationMode) -> StoryGenerationIntent {
        let intent = StoryGenerationIntent(
            architectureFamily: .unspecified,
            compassLocks: [],
            avoidStructures: [],
            beatContract: BeatGenerationContract(maxMajorStateChanges: 2)
        )
        return intent.normalized()
    }

    private func sceneStoryGenerationBrief(
        goal: ProjectGoalBriefV2,
        theme: ProjectLens,
        generationMode: StoryGenerationMode,
        differenceMode: StoryDifferenceMode,
        groundingMode: StoryGroundingMode,
        storyMemory: StoryMemoryRequest,
        hasMediaAnchors: Bool
    ) -> SceneStoryGenerationBrief {
        let audienceEffect = uniqueNonEmpty([
            goal.desiredResponse,
            goal.viewerExperience,
            goal.audience,
            goal.goal
        ]).prefix(3).joined(separator: " ")
        let destinationText = uniqueNonEmpty([
            goal.desiredResponse,
            goal.viewerExperience,
            theme.body.claim,
            theme.body.visualSummary
        ]).first ?? ""
        let emotionalDestination = destinationText.isEmpty ? [] : [
            CompassLock(scope: .storyEnd, kind: .label, text: shortSummaryText(destinationText, limit: 96))
        ]
        return SceneStoryGenerationBrief(
            storyForm: sceneStoryForm(for: goal),
            audienceEffect: shortSummaryText(audienceEffect, limit: 240),
            emotionalStart: [],
            emotionalDestination: emotionalDestination,
            groundingPolicy: sceneStoryGroundingPolicy(groundingMode: groundingMode, hasMediaAnchors: hasMediaAnchors),
            noveltyPolicy: StoryNoveltyPolicy(
                minDifferingDimensions: 0,
                preserveDimensions: storyMemory.preserveDimensions,
                varyDimensions: storyMemory.varyDimensions,
                avoidElements: storyMemory.avoidElements
            ),
            tonePolicy: sceneStoryTonePolicy(goal: goal, theme: theme),
            evidencePolicy: sceneStoryEvidencePolicy(groundingMode: groundingMode)
        ).normalized()
    }

    private func sceneStoryForm(for goal: ProjectGoalBriefV2) -> StoryForm {
        switch goal.contentType {
        case .brand:
            return .dramaticArc
        case .product, .service:
            return .productDemo
        case .personalStory:
            return .documentaryPortrait
        case .documentary:
            return .documentaryPortrait
        case .narrative:
            return .dramaticArc
        case .ambient:
            return .ambientSequence
        case .experimental:
            return .abstractVisualPoem
        case nil:
            return .dramaticArc
        }
    }

    private func sceneStoryGroundingPolicy(groundingMode: StoryGroundingMode, hasMediaAnchors: Bool) -> String {
        switch groundingMode {
        case .mediaBound:
            return "Stay close to supplied media evidence; mark unsupported material as weak or invented."
        case .inventive:
            return "Invent visual material when useful, but disclose invented elements and avoid false factual claims."
        case .balanced:
            return hasMediaAnchors
                ? "Balance supplied media evidence with Goal and Lens interpretation."
                : "No media anchors were supplied; use Goal and Lens interpretation while disclosing invented material."
        }
    }

    private func sceneStoryEvidencePolicy(groundingMode: StoryGroundingMode) -> String {
        switch groundingMode {
        case .mediaBound:
            return "Factual claims require media, transcript, user, or Goal evidence; otherwise use visual metaphor or mark invented."
        case .inventive:
            return "Invented staging is allowed; real-world claims, testimony, names, and quotations still require supplied evidence."
        case .balanced:
            return "Distinguish media-supported, lens-supported, goal-inferred, invented, and weak evidence at Beat level."
        }
    }

    private func sceneStoryTonePolicy(goal: ProjectGoalBriefV2, theme: ProjectLens) -> String {
        let cues = uniqueNonEmpty(
            [goal.viewerExperience, goal.desiredResponse, theme.body.visualSummary, theme.body.claim]
                + goal.constraints
                + theme.body.mustPreserve
        )
        if cues.isEmpty {
            return "Use tone from the Goal and planned Frames; do not impose a global house style."
        }
        return "Use the Goal and enabled Lens tone cues: \(cues.prefix(6).joined(separator: "; "))."
    }

    private func sceneStoryToneConstraints(goal: ProjectGoalBriefV2, theme: ProjectLens) -> [String] {
        uniqueNonEmpty(goal.constraints + theme.body.mustAvoid + projectOutputContext.providerConstraints)
    }

    private func storyMemoryAvoidElements(priorSignatures: [StorySignatureDocument], mode: StoryGenerationMode) -> [String] {
        guard mode == .avoidOverlap else { return [] }
        return LitScenes.uniqueNonEmpty(
            priorSignatures.flatMap(storySignatureAvoidElements),
            limit: 32
        )
    }

    private func storyArchitectureFamily(for runIndex: Int) -> StoryArchitectureFamily {
        let families: [StoryArchitectureFamily] = [
            .embodiedChoice,
            .systemReconfiguration,
            .symbolicInversion,
            .investigationRevelation,
            .obstacleCountermove,
            .ritualDecision
        ]
        return families[runIndex % families.count]
    }

    private func sceneStorySchemaPreview<Value: Encodable>(title: String, value: Value) -> SceneStorySchemaPreview {
        guard let data = try? JSONCoding.prettyEncoder.encode(value),
              let json = String(data: data, encoding: .utf8) else {
            return .empty
        }
        return SceneStorySchemaPreview(title: title, json: json)
    }

    private func generateNovelStorySet(
        client: StoryInferenceService,
        request: SceneStoryGenerateRequest,
        project: ProjectRecord,
        session: StoryGenerationSessionDocument,
        slotIndex: Int,
        priorSignatures: [StorySignatureDocument],
        initialAttemptRecord: StoryGenerationAttemptRecord
    ) async throws -> (set: SceneStorySetDocument, relatedVariantOfStoryId: String, relatedVariantReasons: [String], attemptRecords: [StoryGenerationAttemptRecord], usageTokens: Int, lastResponseId: String) {
        let firstResult = try await client.generateSceneStorySet(request)
        let firstSet = firstResult.document.normalized()
        let firstTokens = firstResult.provenance.openaiAttempts.reduce(0) { $0 + $1.inputTokens + $1.outputTokens }
        let firstResponseId = firstResult.provenance.openaiAttempts.last?.responseId ?? ""
        var firstAttempt = initialAttemptRecord
        firstAttempt.status = "complete"
        firstAttempt.completedAt = DateFormats.now()
        firstAttempt.hostedRequestId = firstResult.hostedRequestId
        firstAttempt.openaiResponseId = firstResult.provenance.openaiAttempts.first?.responseId ?? ""
        firstAttempt.model = firstResult.provenance.openaiAttempts.first?.model ?? firstSet.model
        firstAttempt.promptTemplateVersion = firstResult.provenance.lambdaPromptVersion.isEmpty
            ? firstAttempt.promptTemplateVersion
            : firstResult.provenance.lambdaPromptVersion
        var attempts = [firstAttempt]
        guard request.generationMode == .avoidOverlap,
              let firstStory = firstSet.sceneStories.first?.normalized() else {
            return (firstSet, "", [], attempts, firstTokens, firstResponseId)
        }
        let firstSignature = makeStorySignature(
            story: firstStory,
            project: project,
            storySuggestionId: "candidate",
            sourceSceneStorySetId: firstSet.sceneStorySetId,
            sourceStoryId: firstStory.storyId,
            generationSessionId: session.generationSessionId,
            goalFingerprint: request.goalFingerprint,
            lensContextFingerprint: request.lensContextFingerprint,
            lensIds: request.lensRefs.map(\.lensId),
            editorialState: .suggestion,
            productionState: .notStarted,
            contextClass: .sameSession
        )
        guard let related = relatedStoryVariant(candidate: firstSignature, priorSignatures: priorSignatures) else {
            return (firstSet, "", [], attempts, firstTokens, firstResponseId)
        }
        var retryRequest = request
        var rejectedSignature = firstSignature.normalized()
        rejectedSignature.contextClass = .sameSession
        retryRequest.storyMemory.priorStorySignatures = deduplicatedStorySignatures(
            [rejectedSignature] + retryRequest.storyMemory.priorStorySignatures,
            limit: 12
        )
        retryRequest.storyMemory.avoidElements = uniqueNonEmpty(
            retryRequest.storyMemory.avoidElements + storySignatureAvoidElements(rejectedSignature)
        )
        retryRequest.operatorInstructions.append("""
        RETRY REQUIRED: The previous candidate was rejected as a related variant.
        Similarity reasons: \(related.reasons.joined(separator: "; ")).
        Do not revise or cosmetically restage the rejected candidate. Choose a different Story architecture family, primary acting force, causal engine, setting progression, primary meaning move, Compass destination or arc shape, and payoff mechanism.
        """)
        let retrySnapshot = try contextStore.saveStoryGenerationRequestSnapshot(
            retryRequest,
            for: project,
            generationSessionId: session.generationSessionId,
            slotIndex: slotIndex + 1,
            attemptIndex: 2
        )
        var retryAttempt = storyGenerationAttemptRecord(
            request: retryRequest,
            snapshot: retrySnapshot,
            slotIndex: slotIndex + 1,
            attemptIndex: 2,
            purpose: "novelty_retry",
            status: "started"
        )
        let retryResult = try await client.generateSceneStorySet(retryRequest)
        let retrySet = retryResult.document.normalized()
        let totalTokens = firstTokens + retryResult.provenance.openaiAttempts.reduce(0) { $0 + $1.inputTokens + $1.outputTokens }
        let retryResponseId = retryResult.provenance.openaiAttempts.last?.responseId ?? firstResponseId
        retryAttempt.status = "complete"
        retryAttempt.completedAt = DateFormats.now()
        retryAttempt.hostedRequestId = retryResult.hostedRequestId
        retryAttempt.openaiResponseId = retryResult.provenance.openaiAttempts.first?.responseId ?? ""
        retryAttempt.model = retryResult.provenance.openaiAttempts.first?.model ?? retrySet.model
        retryAttempt.promptTemplateVersion = retryResult.provenance.lambdaPromptVersion.isEmpty
            ? retryAttempt.promptTemplateVersion
            : retryResult.provenance.lambdaPromptVersion
        attempts.append(retryAttempt)
        guard let retryStory = retrySet.sceneStories.first?.normalized() else {
            return (retrySet, related.storyId, related.reasons, attempts, totalTokens, retryResponseId)
        }
        let retrySignature = makeStorySignature(
            story: retryStory,
            project: project,
            storySuggestionId: "candidate_retry",
            sourceSceneStorySetId: retrySet.sceneStorySetId,
            sourceStoryId: retryStory.storyId,
            generationSessionId: session.generationSessionId,
            goalFingerprint: request.goalFingerprint,
            lensContextFingerprint: request.lensContextFingerprint,
            lensIds: request.lensRefs.map(\.lensId),
            editorialState: .suggestion,
            productionState: .notStarted,
            contextClass: .sameSession
        )
        if let retryRelated = relatedStoryVariant(candidate: retrySignature, priorSignatures: priorSignatures + [rejectedSignature]) {
            return (retrySet, retryRelated.storyId, retryRelated.reasons, attempts, totalTokens, retryResponseId)
        }
        return (retrySet, "", [], attempts, totalTokens, retryResponseId)
    }

    private func storyGenerationAttemptRecord(
        request: SceneStoryGenerateRequest,
        snapshot: (relativePath: String, fingerprint: String),
        slotIndex: Int,
        attemptIndex: Int,
        purpose: String,
        status: String
    ) -> StoryGenerationAttemptRecord {
        StoryGenerationAttemptRecord(
            slotIndex: slotIndex,
            attemptIndex: attemptIndex,
            purpose: purpose,
            status: status,
            requestSnapshotPath: snapshot.relativePath,
            requestFingerprint: snapshot.fingerprint,
            promptTemplateVersion: sceneStoryDesktopInstructionVersion,
            operatorInstructionSnapshot: request.operatorInstructions,
            storyMemorySignatureIds: request.storyMemory.priorStorySignatures.map(\.storySignatureId),
            startedAt: DateFormats.now()
        )
    }

    private func deduplicatedStorySignatures(
        _ signatures: [StorySignatureDocument],
        limit: Int
    ) -> [StorySignatureDocument] {
        var seen: Set<String> = []
        var output: [StorySignatureDocument] = []
        for signature in signatures.map({ $0.normalized() }) {
            let key = storySignatureMemoryKey(signature)
            guard !key.isEmpty, !seen.contains(key) else { continue }
            output.append(signature)
            seen.insert(key)
            if output.count >= limit { break }
        }
        return output
    }

    private func storySignatureMemoryKey(_ signature: StorySignatureDocument) -> String {
        let contentParts = uniqueNonEmpty([
            signature.storyBlueprint.architectureFamily.rawValue,
            signature.storyBlueprint.causalEngine,
            signature.storyBlueprint.coreVisualImage,
            signature.storyBlueprint.payoffMechanism,
            signature.primarySetting,
            signature.coreVisualImage,
            signature.payoffOrEnding
        ])
        if !contentParts.isEmpty {
            return "content:\(stableHash(contentParts, length: 24))"
        }
        return uniqueNonEmpty([
            signature.sourceStoryId,
            signature.projectStoryId,
            signature.storySuggestionId,
            signature.storySignatureId
        ]).first ?? ""
    }

    private func storySignatureAvoidElements(_ signature: StorySignatureDocument) -> [String] {
        uniqueNonEmpty([
            signature.storyEngine,
            signature.primarySetting,
            signature.coreVisualImage,
            signature.primaryMeaningMove,
            signature.payoffOrEnding,
            signature.storyBlueprint.causalEngine,
            signature.storyBlueprint.payoffMechanism,
            signature.storyBlueprint.coreVisualImage
        ])
    }

    private func relatedStoryVariant(
        candidate: StorySignatureDocument,
        priorSignatures: [StorySignatureDocument]
    ) -> (storyId: String, reasons: [String])? {
        let candidate = candidate.normalized()
        for prior in priorSignatures.map({ $0.normalized() }) {
            var reasons: [String] = []
            if candidate.storyBlueprint.architectureFamily == prior.storyBlueprint.architectureFamily,
               candidate.storyBlueprint.architectureFamily != .unspecified {
                reasons.append("same architecture family")
            }
            if comparableStoryDimension(candidate.storyBlueprint.primaryActor, prior.storyBlueprint.primaryActor)
                || comparableStoryDimension(candidate.centralSubjectOrActor, prior.centralSubjectOrActor) {
                reasons.append("same primary actor")
            }
            if comparableStoryDimension(candidate.storyBlueprint.actingForce, prior.storyBlueprint.actingForce) {
                reasons.append("same acting force")
            }
            if comparableStoryDimension(candidate.storyBlueprint.causalEngine, prior.storyBlueprint.causalEngine)
                || comparableStoryDimension(candidate.storyEngine, prior.storyEngine) {
                reasons.append("same action engine")
            }
            if comparableSettingProgression(candidate.storyBlueprint.settingProgression, prior.storyBlueprint.settingProgression)
                || comparableStoryDimension(candidate.primarySetting, prior.primarySetting) {
                reasons.append("same setting progression")
            }
            if comparableStoryDimension(candidate.storyBlueprint.primaryMeaningMove, prior.storyBlueprint.primaryMeaningMove)
                || comparableStoryDimension(candidate.primaryMeaningMove, prior.primaryMeaningMove) {
                reasons.append("same primary meaning move")
            }
            if comparableStoryDimension(candidate.storyBlueprint.compassDestination, prior.storyBlueprint.compassDestination)
                || !Set(candidate.emotionalEndLabels.map(normalizedComparable)).intersection(Set(prior.emotionalEndLabels.map(normalizedComparable))).isEmpty {
                reasons.append("same emotional destination")
            }
            if comparableStoryDimension(candidate.storyBlueprint.payoffMechanism, prior.storyBlueprint.payoffMechanism)
                || comparableStoryDimension(candidate.payoffOrEnding, prior.payoffOrEnding) {
                reasons.append("same payoff mechanism")
            }
            if comparableStoryDimension(candidate.storyBlueprint.coreVisualImage, prior.storyBlueprint.coreVisualImage)
                || comparableStoryDimension(candidate.coreVisualImage, prior.coreVisualImage) {
                reasons.append("same core visual image")
            }
            let comparedDimensions = 8
            let differingDimensions = comparedDimensions - min(reasons.count, comparedDimensions)
            if differingDimensions < 4 {
                return (prior.projectStoryId.isEmpty ? prior.storySuggestionId : prior.projectStoryId, reasons)
            }
        }
        return nil
    }

    private func comparableStoryDimension(_ lhs: String, _ rhs: String) -> Bool {
        let left = normalizedComparable(lhs)
        let right = normalizedComparable(rhs)
        guard !left.isEmpty, !right.isEmpty else { return false }
        if left == right { return true }
        let leftTokens = Set(storyNoveltyAliasTokens(left))
        let rightTokens = Set(storyNoveltyAliasTokens(right))
        let overlap = leftTokens.intersection(rightTokens).count
        return overlap >= max(2, min(leftTokens.count, rightTokens.count) / 2)
    }

    private func comparableSettingProgression(_ lhs: [String], _ rhs: [String]) -> Bool {
        let left = lhs.map(normalizedComparable).filter { !$0.isEmpty }
        let right = rhs.map(normalizedComparable).filter { !$0.isEmpty }
        guard !left.isEmpty, !right.isEmpty else { return false }
        let leftTokens = Set(left.flatMap(storyNoveltyAliasTokens))
        let rightTokens = Set(right.flatMap(storyNoveltyAliasTokens))
        return leftTokens.intersection(rightTokens).count >= 2
    }

    private func normalizedComparable(_ value: String) -> String {
        value.lowercased()
            .replacingOccurrences(of: "[^a-z0-9 ]", with: " ", options: .regularExpression)
            .split(separator: " ")
            .joined(separator: " ")
            .trimmed
    }

    private func storyNoveltyAliasTokens(_ value: String) -> [String] {
        normalizedComparable(value)
            .split(separator: " ")
            .map(String.init)
            .map { token in
                if token.count > 4, token.hasSuffix("s") {
                    return String(token.dropLast())
                }
                return token
            }
    }

    private func storyGenerationLensReferences(primaryLens: ProjectLens) -> [StoryGenerationLensReference] {
        let activeLensVersionId = projectLenses.activeVersionId
        return [StoryGenerationLensReference.from(lens: primaryLens, lensVersionId: activeLensVersionId, role: "primary")]
    }

    private func selectedPriorStorySignatures(
        goalFingerprint: String,
        lensContextFingerprint: String,
        lensIds: [String],
        limit: Int
    ) -> [StorySignatureDocument] {
        let lensSet = Set(lensIds)
        let scored = storySignatures.map { signature -> (Int, StorySignatureDocument) in
            var normalized = signature.normalized()
            let sameGoal = normalized.goalFingerprint == goalFingerprint
            let sameLensContext = normalized.lensContextFingerprint == lensContextFingerprint
            let sharesLens = !Set(normalized.lensIds).intersection(lensSet).isEmpty
            if normalized.editorialState == .dismissed {
                normalized.contextClass = .dismissed
            } else if normalized.editorialState == .archived {
                normalized.contextClass = .archived
            } else if sameGoal && (sameLensContext || sharesLens) {
                normalized.contextClass = .currentContext
            } else {
                normalized.contextClass = .olderContext
            }
            let score: Int
            switch normalized.contextClass {
            case .currentContext: score = 0
            case .dismissed: score = 1
            case .archived: score = 3
            case .olderContext: score = 4
            case .sameSession: score = 0
            case .positiveReference: score = 0
            }
            return (score, normalized)
        }
        return Array(scored.sorted { lhs, rhs in
            if lhs.0 == rhs.0 {
                return lhs.1.updatedAt > rhs.1.updatedAt
            }
            return lhs.0 < rhs.0
        }.map(\.1).prefix(limit))
    }

    private func storyMemoryPreserveDimensions(for mode: StoryGenerationMode) -> [String] {
        switch mode {
        case .avoidOverlap:
            return ["project anchors", "success criteria", "tone", "audience destination"]
        case .moreLikeSelected:
            return ["emotional destination", "tonal posture", "visual credibility"]
        case .branchSelected:
            return ["selected parent constraints", "locked Story elements"]
        case .reflowSelected:
            return ["project Story identity", "locked Scenes", "locked Beats", "continuity"]
        default:
            return []
        }
    }

    private func storyMemoryVaryDimensions(for mode: StoryGenerationMode) -> [String] {
        switch mode {
        case .moreLikeSelected:
            return ["premise", "action engine", "staging", "Scene progression"]
        case .branchSelected:
            return ["chosen branch dimensions only"]
        case .avoidOverlap:
            return ["central dramatic question", "causal mechanism", "setting category", "central visual image", "ending consequence"]
        default:
            return []
        }
    }

    private func makeStorySignature(
        story: SceneStory,
        project: ProjectRecord,
        storySuggestionId: String,
        sourceSceneStorySetId: String,
        sourceStoryId: String,
        generationSessionId: String,
        goalFingerprint: String,
        lensContextFingerprint: String,
        lensIds: [String],
        editorialState: ProjectStoryEditorialState,
        productionState: ProjectStoryProductionState,
        contextClass: StoryMemoryContextClass
    ) -> StorySignatureDocument {
        let normalized = story.normalized()
        let scenes = normalized.scenes.sorted { $0.order < $1.order }
        let beats = scenes.flatMap { $0.sceneBeats.sorted { $0.order < $1.order } }
        let firstBeat = beats.first
        let finalBeat = beats.last
        let sceneFunctions = LitScenes.uniqueNonEmpty(scenes.map(\.sceneFunction))
        let beatActions = LitScenes.uniqueNonEmpty(beats.map(\.action), limit: 4)
        let primaryMeaningMove = scenes.map(\.primaryMeaningMove).first { !$0.trimmed.isEmpty }
            ?? normalized.meaningRelationSequence.map(\.naturalLanguage).first { !$0.trimmed.isEmpty }
            ?? normalized.meaningThesis
        let coreVisual = [
            firstBeat?.meaningProof,
            firstBeat?.promptSeed,
            normalized.visualWorld
        ]
        .compactMap { $0?.trimmed }
        .first { !$0.isEmpty } ?? ""
        let payoff = [
            finalBeat?.meaningProof,
            finalBeat?.action,
            scenes.last?.meaningFocus
        ]
        .compactMap { $0?.trimmed }
        .first { !$0.isEmpty } ?? ""
        return StorySignatureDocument(
            projectId: project.projectId,
            storySuggestionId: storySuggestionId,
            sourceSceneStorySetId: sourceSceneStorySetId,
            sourceStoryId: sourceStoryId,
            generationSessionId: generationSessionId,
            goalFingerprint: goalFingerprint,
            lensContextFingerprint: lensContextFingerprint,
            lensIds: lensIds,
            contextClass: contextClass,
            title: normalized.title,
            premise: normalized.premise,
            storyEngine: LitScenes.uniqueNonEmpty(sceneFunctions + beatActions, limit: 8).joined(separator: " -> "),
            centralSubjectOrActor: firstBeat?.subjects.joined(separator: ", ") ?? "",
            primarySetting: firstBeat?.setting.trimmed.isEmpty == false ? firstBeat?.setting ?? "" : scenes.first?.title ?? "",
            coreVisualImage: coreVisual,
            meaningThesis: normalized.meaningThesis,
            primaryMeaningMove: primaryMeaningMove,
            emotionalStartLabels: normalized.emotionalArc.start.labels,
            emotionalEndLabels: normalized.emotionalArc.end.labels,
            arcShape: normalized.emotionalArc.arcShape,
            sceneFunctionSequence: sceneFunctions,
            payoffOrEnding: payoff,
            storyBlueprint: normalized.storyBlueprint,
            editorialState: editorialState,
            productionState: productionState,
            createdAt: DateFormats.now(),
            updatedAt: DateFormats.now()
        ).normalized()
    }

    private func mergeStoryGenerationSession(_ session: StoryGenerationSessionDocument) {
        let normalized = session.normalized()
        storyGenerationSessions.removeAll { $0.generationSessionId == normalized.generationSessionId }
        storyGenerationSessions.insert(normalized, at: 0)
        storyGenerationSessions.sort { $0.startedAt > $1.startedAt }
    }

    private func mergeStorySignature(_ signature: StorySignatureDocument) {
        let normalized = signature.normalized()
        storySignatures.removeAll { $0.storySignatureId == normalized.storySignatureId }
        storySignatures.insert(normalized, at: 0)
        storySignatures.sort { $0.updatedAt > $1.updatedAt }
    }

    private func initialProjectStoryVersion(
        story: SceneStory,
        sourceStorySuggestionId: String,
        projectStoryId existingProjectStoryId: String = "",
        storyVersionId existingStoryVersionId: String = "",
        reason: String,
        now: String
    ) -> ProjectStoryVersionDocument {
        let normalizedStory = story.normalized()
        let projectStoryId = existingProjectStoryId.trimmed.isEmpty
            ? storyUUIDIdentifier("project_story")
            : existingProjectStoryId.trimmed
        let storyVersionId = existingStoryVersionId.trimmed.isEmpty
            ? storyUUIDIdentifier("story_version")
            : existingStoryVersionId.trimmed
        return ProjectStoryVersionDocument(
            storyVersionId: storyVersionId,
            projectStoryId: projectStoryId,
            sourceStorySuggestionId: sourceStorySuggestionId.trimmed,
            reason: reason.trimmed,
            story: normalizedStory,
            sceneRevisionIds: normalizedStory.scenes.map { _ in storyUUIDIdentifier("scene_revision") },
            beatRevisionIds: normalizedStory.scenes.flatMap(\.sceneBeats).map { _ in storyUUIDIdentifier("beat_revision") },
            createdAt: now,
            updatedAt: now
        )
    }

    private func projectStorySignature(
        _ signature: StorySignatureDocument,
        version: ProjectStoryVersionDocument,
        editorialState: ProjectStoryEditorialState,
        productionState: ProjectStoryProductionState,
        now: String
    ) -> StorySignatureDocument {
        var updated = signature.normalized()
        updated.projectStoryId = version.projectStoryId
        updated.storyVersionId = version.storyVersionId
        updated.editorialState = editorialState
        updated.productionState = productionState
        updated.updatedAt = now
        return updated.normalized()
    }

    private func isRemovedStoryEntry(_ entry: ProjectStoryLibraryEntry) -> Bool {
        entry.editorialState == .dismissed || entry.editorialState == .archived
    }

    private func hasVisibleActiveStory(in libraryDocument: ProjectStoryLibraryDocument) -> Bool {
        let activeStoryId = libraryDocument.activeStoryId.trimmed
        guard !activeStoryId.isEmpty else { return false }
        return libraryDocument.entries.contains { entry in
            entry.projectStoryId == activeStoryId && !isRemovedStoryEntry(entry)
        }
    }

    private func reconcileKeptDefaultStoryLibrary(for project: ProjectRecord) {
        var libraryDocument = storyLibrary.normalized()
        var hasActiveStory = hasVisibleActiveStory(in: libraryDocument)
        var didChange = false
        for index in libraryDocument.entries.indices {
            var entry = libraryDocument.entries[index].normalized()
            guard entry.editorialState == .suggestion else { continue }
            guard let story = storySnapshot(for: entry, project: project)?.normalized() else { continue }
            let now = DateFormats.now()
            let version = initialProjectStoryVersion(
                story: story,
                sourceStorySuggestionId: entry.storySuggestionId,
                projectStoryId: entry.projectStoryId,
                storyVersionId: entry.currentVersionId,
                reason: "Generated Story",
                now: now
            )
            do {
                try contextStore.saveProjectStoryVersion(version, for: project)
                entry.projectStoryId = version.projectStoryId
                entry.currentVersionId = version.storyVersionId
                entry.editorialState = .kept
                entry.updatedAt = now
                libraryDocument.entries[index] = entry
                if !hasActiveStory {
                    libraryDocument.activeStoryId = version.projectStoryId
                    hasActiveStory = true
                }
                if let signature = contextStore.loadStorySignature(for: project, storySignatureId: entry.storySignatureId) {
                    let updatedSignature = projectStorySignature(
                        signature,
                        version: version,
                        editorialState: .kept,
                        productionState: entry.productionState,
                        now: now
                    )
                    try contextStore.saveStorySignature(updatedSignature, for: project)
                    mergeStorySignature(updatedSignature)
                }
                didChange = true
            } catch {
                lastError = error.localizedDescription
                sceneStoryStatus = "Story Library upgrade failed"
            }
        }
        guard didChange else { return }
        libraryDocument.updatedAt = DateFormats.now()
        do {
            try contextStore.saveProjectStoryLibrary(libraryDocument, for: project)
            storyLibrary = libraryDocument.normalized()
        } catch {
            lastError = error.localizedDescription
            sceneStoryStatus = "Story Library upgrade failed"
        }
    }

    func selectStoryLibraryEntry(libraryEntryId: String) {
        guard let project = currentProject else { return }
        let requestId = storyActionRequestId()
        print("[scene_story_action] starting action=select_story request_id=\(requestId)")
        var libraryDocument = storyLibrary
        guard let entry = libraryDocument.entries.first(where: { $0.libraryEntryId == libraryEntryId.trimmed }),
              !entry.projectStoryId.trimmed.isEmpty,
              !isRemovedStoryEntry(entry) else {
            sceneStoryStatus = "Story selected"
            print("[scene_story_action] completed action=select_story request_id=\(requestId) status=no_active_project_story")
            return
        }
        libraryDocument.activeStoryId = entry.projectStoryId
        libraryDocument.updatedAt = DateFormats.now()
        do {
            try contextStore.saveProjectStoryLibrary(libraryDocument, for: project)
            storyLibrary = libraryDocument.normalized()
            sceneStoryStatus = "Active Story selected"
            print("[scene_story_action] completed action=select_story request_id=\(requestId) status=active_story_selected")
        } catch {
            lastError = error.localizedDescription
            sceneStoryStatus = "Story selection failed"
            print("[scene_story_action] error action=select_story request_id=\(requestId) error=\"\(error.localizedDescription)\"")
        }
    }

    func removeStoryLibraryEntry(libraryEntryId: String) {
        updateStoryLibraryEntry(
            libraryEntryId: libraryEntryId,
            actionName: "remove_story",
            successStatus: "Story removed"
        ) { entry, libraryDocument in
            entry.editorialState = .dismissed
            if !entry.projectStoryId.trimmed.isEmpty, libraryDocument.activeStoryId == entry.projectStoryId {
                libraryDocument.activeStoryId = ""
            }
        } updateSignature: { signature, _ in
            signature.editorialState = .dismissed
        }
    }

    func restoreStoryLibraryEntry(libraryEntryId: String) {
        updateStoryLibraryEntry(
            libraryEntryId: libraryEntryId,
            actionName: "restore_story",
            successStatus: "Story restored"
        ) { entry, libraryDocument in
            entry.editorialState = .kept
            if !entry.projectStoryId.trimmed.isEmpty {
                libraryDocument.activeStoryId = entry.projectStoryId
            }
        } updateSignature: { signature, entry in
            signature.editorialState = .kept
        }
    }

    private func updateStoryLibraryEntry(
        libraryEntryId: String,
        actionName: String,
        successStatus: String,
        updateEntry: (inout ProjectStoryLibraryEntry, inout ProjectStoryLibraryDocument) -> Void,
        updateSignature: (inout StorySignatureDocument, ProjectStoryLibraryEntry) -> Void
    ) {
        guard let project = currentProject else { return }
        let requestId = storyActionRequestId()
        print("[scene_story_action] starting action=\(actionName) request_id=\(requestId)")
        var libraryDocument = storyLibrary
        guard let index = libraryDocument.entries.firstIndex(where: { $0.libraryEntryId == libraryEntryId.trimmed }) else {
            sceneStoryStatus = "Story not found"
            print("[scene_story_action] completed action=\(actionName) request_id=\(requestId) status=not_found")
            return
        }
        var entry = libraryDocument.entries[index].normalized()
        updateEntry(&entry, &libraryDocument)
        entry.updatedAt = DateFormats.now()
        libraryDocument.entries[index] = entry
        libraryDocument.updatedAt = DateFormats.now()
        do {
            try contextStore.saveProjectStoryLibrary(libraryDocument, for: project)
            storyLibrary = libraryDocument.normalized()
            if let signature = contextStore.loadStorySignature(for: project, storySignatureId: entry.storySignatureId) {
                var updatedSignature = signature
                updateSignature(&updatedSignature, entry)
                updatedSignature.updatedAt = DateFormats.now()
                try contextStore.saveStorySignature(updatedSignature, for: project)
                mergeStorySignature(updatedSignature)
            }
            sceneStoryStatus = successStatus
            print("[scene_story_action] completed action=\(actionName) request_id=\(requestId) status=success")
        } catch {
            lastError = error.localizedDescription
            sceneStoryStatus = "\(successStatus) failed"
            print("[scene_story_action] error action=\(actionName) request_id=\(requestId) error=\"\(error.localizedDescription)\"")
        }
    }

    private func storyActionRequestId() -> String {
        "story_action_\(UUID().uuidString.lowercased())"
    }


    func sceneStorySnapshot(for entry: ProjectStoryLibraryEntry) -> SceneStory? {
        guard let project = currentProject else { return nil }
        return storySnapshot(for: entry, project: project)
    }

    private func storySnapshot(for entry: ProjectStoryLibraryEntry, project: ProjectRecord) -> SceneStory? {
        if !entry.projectStoryId.trimmed.isEmpty,
           !entry.currentVersionId.trimmed.isEmpty,
           let version = contextStore.loadProjectStoryVersion(
            for: project,
            projectStoryId: entry.projectStoryId,
            storyVersionId: entry.currentVersionId
           ) {
            return version.story.normalized()
        }
        guard !entry.sourceSceneStorySetId.trimmed.isEmpty,
              !entry.sourceStoryId.trimmed.isEmpty,
              let set = contextStore.loadSceneStorySet(for: project, sceneStorySetId: entry.sourceSceneStorySetId) else {
            return nil
        }
        return set.sceneStories.first { $0.storyId == entry.sourceStoryId }?.normalized()
    }

    func buildVideoPlanFromSceneStory(
        sceneStorySetId: String,
        storyId: String,
        preset: VideoChainPreset = .cinematicProof,
        providerSelection: VideoProviderSelection = .bestAvailable,
        modelSelection: VideoModelSelection = .auto
    ) {
        guard let project = currentProject else { return }
        let set = contextStore.loadSceneStorySet(for: project, sceneStorySetId: sceneStorySetId)
            ?? sceneStorySets.first { $0.sceneStorySetId == sceneStorySetId }
        guard let set,
              let story = set.sceneStories.first(where: { $0.storyId == storyId }) else {
            sceneStoryStatus = "Story not found"
            return
        }
        var chain = VideoChainDocument.draft(
            projectId: project.projectId,
            sceneStorySet: set,
            story: story,
            preset: preset,
            providerSelection: providerSelection,
            modelSelection: modelSelection
        )
        chain = preflightedVideoChain(chain)
        do {
            try persistVideoChain(chain, for: project)
            sceneStoryStatus = "SceneStory video plan built"
            videoChainStatus = "Video plan built"
            storyStatus = "Video Chain ready"
        } catch {
            lastError = error.localizedDescription
            sceneStoryStatus = "SceneStory video plan save failed"
            videoChainStatus = "Video plan save failed"
        }
    }

    func autoCreateSceneSoundArrangement(
        sceneStorySetId: String,
        storyId: String,
        soundId: String
    ) async {
        guard let project = currentProject else {
            sceneSoundArrangementStatus = "Create or select a project first"
            return
        }
        let set = contextStore.loadSceneStorySet(for: project, sceneStorySetId: sceneStorySetId)
            ?? sceneStorySets.first { $0.sceneStorySetId == sceneStorySetId }
        guard let set,
              let story = set.sceneStories.first(where: { $0.storyId == storyId })?.normalized() else {
            sceneSoundArrangementStatus = "Story not found"
            return
        }
        guard let sound = soundSceneAssets.first(where: { $0.soundId == soundId }) ?? selectedSoundSceneAsset else {
            sceneSoundArrangementStatus = "Select a sound file first"
            return
        }
        let scenes = story.scenes.sorted {
            if $0.order == $1.order {
                return $0.title.localizedStandardCompare($1.title) == .orderedAscending
            }
            return $0.order < $1.order
        }
        guard !scenes.isEmpty else {
            sceneSoundArrangementStatus = "Story has no Scenes"
            return
        }
        guard sound.durationSeconds >= Double(scenes.count) else {
            sceneSoundArrangementStatus = "Sound must be at least one second per scene"
            return
        }

        let projectId = project.projectId
        let now = DateFormats.now()
        let arrangementId = "scene_sound_arrangement_\(shortHash("\(projectId):\(set.sceneStorySetId):\(story.storyId):\(sound.soundId)", length: 14))"
        let segmentDuration = sound.durationSeconds / Double(scenes.count)
        let cards = scenes.enumerated().map { index, scene -> SceneSoundArrangementCard in
            let sceneOrder = index + 1
            let start = segmentDuration * Double(index)
            let duration = index == scenes.count - 1 ? max(0.1, sound.durationSeconds - start) : segmentDuration
            let beatIds = scene.sceneBeats.map(\.beatId)
            let planId = "sound_scene_plan_\(shortHash("\(projectId):\(sound.soundId):\(arrangementId):\(scene.sceneId)", length: 14))"
            let firstBeat = scene.sceneBeats.sorted { $0.order < $1.order }.first
            return SceneSoundArrangementCard(
                cardId: "scene_sound_card_\(shortHash("\(arrangementId):\(scene.sceneId):\(sceneOrder)", length: 14))",
                arrangementId: arrangementId,
                planId: planId,
                sceneId: scene.sceneId,
                sceneOrder: sceneOrder,
                beatIds: beatIds,
                startSeconds: start,
                durationSeconds: duration,
                title: scene.title.isEmpty ? "Scene \(sceneOrder)" : scene.title,
                setup: scene.sceneDescription,
                turn: firstBeat?.action ?? scene.meaningFocus,
                resolution: scene.meaningFocus,
                notes: [
                    "Story: \(story.title)",
                    "Scene ID: \(scene.sceneId)",
                    "Beats: \(beatIds.joined(separator: ", "))"
                ].filter { !$0.trimmed.isEmpty }.joined(separator: "\n"),
                createdAt: now,
                updatedAt: now
            )
        }
        let arrangement = SceneSoundArrangement(
            arrangementId: arrangementId,
            projectId: projectId,
            sceneStorySetId: set.sceneStorySetId,
            storyId: story.storyId,
            soundId: sound.soundId,
            title: "\(story.title.isEmpty ? "Story" : story.title) on \(sound.displayName)",
            activeVideoChainId: "",
            cards: cards,
            createdAt: now,
            updatedAt: now
        )

        isSavingSceneSoundArrangement = true
        sceneSoundArrangementStatus = "Arranging Story on sound"
        defer {
            if currentProject?.projectId == projectId {
                isSavingSceneSoundArrangement = false
            }
        }

        do {
            for card in cards {
                try await SoundSceneTimelineStore.shared.deleteSoundScenePlan(project: project, planId: card.planId)
            }
            for card in cards {
                let plan = SoundScenePlan(
                    planId: card.planId,
                    projectId: projectId,
                    soundId: sound.soundId,
                    startSeconds: card.startSeconds,
                    durationSeconds: card.durationSeconds,
                    title: card.title,
                    setup: card.setup,
                    turn: card.turn,
                    resolution: card.resolution,
                    notes: card.notes,
                    createdAt: card.createdAt,
                    updatedAt: card.updatedAt
                )
                _ = try await SoundSceneTimelineStore.shared.upsertSoundScenePlan(
                    plan,
                    project: project,
                    soundDurationSeconds: sound.durationSeconds
                )
            }
            let saved = try await SoundSceneTimelineStore.shared.upsertSceneSoundArrangement(arrangement, project: project)
            let plans = try await SoundSceneTimelineStore.shared.loadSoundScenePlans(project: project, soundId: sound.soundId)
            guard currentProject?.projectId == projectId else { return }
            selectedSoundSceneAssetId = sound.soundId
            soundScenePlans = plans
            mergeSceneSoundArrangement(saved)
            selectedSceneSoundArrangementId = saved.arrangementId
            soundSceneTimelineStatus = "\(plans.count) scene card\(plans.count == 1 ? "" : "s")"
            sceneSoundArrangementStatus = "Sound arrangement ready"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == projectId else { return }
            lastError = error.localizedDescription
            sceneSoundArrangementStatus = error.localizedDescription
        }
    }

