    private func sceneStoryMediaAnchors(for theme: ProjectLens) -> [SceneStoryMediaAnchor] {
        let referenceIds = Array(uniqueNonEmpty(theme.body.referenceMediaIds).prefix(12))
        guard !referenceIds.isEmpty else { return [] }
        let itemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
        return referenceIds.compactMap { mediaId in
            guard let item = itemsById[mediaId],
                  let observation = mediaObservationsById[mediaId] else {
                return nil
            }
            let summary = [
                observation.plainCaption,
                observation.literalDescription,
                observation.setting
            ]
            .map { $0.trimmed }
            .filter { !$0.isEmpty }
            .joined(separator: " ")
            let symbols = uniqueNonEmpty(
                observation.objects
                    + observation.motifCues
                    + observation.flagsSymbolsSignage.map(\.name)
            )
            let aestheticTerms = uniqueNonEmpty(
                observation.paletteTerms
                    + observation.materials
                    + observation.mood
                    + observation.compositionCues
                    + observation.energyCues
            )
            return SceneStoryMediaAnchor(
                mediaId: mediaId,
                frameId: observation.frameId,
                kind: item.derivativeKind ?? item.kind.rawValue,
                role: "reference",
                summary: summary,
                observedSymbols: symbols,
                aestheticTerms: aestheticTerms,
                negativeConstraints: observation.negativeConstraints,
                notes: observation.detailObservationNotes
            )
        }
    }

    private func sceneStoryOutputProfile() -> SceneStoryOutputProfile {
        let aspectRatio = projectOutputContext.aspectRatio.trimmed
        return SceneStoryOutputProfile(
            aspectRatio: aspectRatio.isEmpty ? "16:9" : aspectRatio,
            durationTargetSeconds: sceneStoryDurationTargetSeconds(),
            chainStrategy: "scene_to_segment",
            destination: projectOutputContext.destinationOrChannel,
            providerHint: projectOutputContext.providerConstraints.joined(separator: ", ")
        )
    }

    private func sceneStoryDurationTargetSeconds() -> Int {
        let digits = projectOutputContext.durationHint.map { character in
            character.isNumber ? character : " "
        }
        let value = String(digits)
            .split(separator: " ")
            .compactMap { Int($0) }
            .first
        return value ?? SceneStoryOutputProfile.default.durationTargetSeconds
    }

