    func isGeneratingVideoChainFrameSource(segmentId: String, role: String) -> Bool {
        generatingVideoChainFrameSourceKey == videoChainFrameSourceKey(segmentId: segmentId, role: role)
    }

    func videoFrameSourceCandidates(segmentId: String) -> [VideoFrameSourceCandidate] {
        guard let segment = videoChain.segments.first(where: { $0.segmentId == segmentId }) else { return [] }
        let context = currentSceneSourceContext()
        let sourceBeats = context.beats.filter { segment.sourceBeatIds.contains($0.beatId) }
        let orderedSegments = videoChain.segments.sorted { $0.order < $1.order }
        let segmentIndex = orderedSegments.firstIndex { $0.segmentId == segmentId }
        let nearbyBeatIds = [
            segmentIndex.flatMap { orderedSegments[safe: $0 - 1]?.sourceBeatIds } ?? [],
            segmentIndex.flatMap { orderedSegments[safe: $0 + 1]?.sourceBeatIds } ?? []
        ].flatMap { $0 }
        let nearbyBeats = context.beats.filter { nearbyBeatIds.contains($0.beatId) }

        var candidatesById: [String: VideoFrameSourceCandidate] = [:]
        var insertionOrder: [String] = []

        func upsert(item: MediaItemRecord, group: VideoFrameSourceCandidateGroup, labels: [String]) {
            guard item.canBeEnabledContent, !curation(for: item).rejected else { return }
            let candidate = videoFrameSourceCandidate(for: item, group: group, labels: labels)
            if var existing = candidatesById[item.mediaId] {
                if groupPriority(group) < groupPriority(existing.group) {
                    existing.group = group
                }
                existing.provenanceLabels = uniqueNonEmpty(existing.provenanceLabels + labels)
                candidatesById[item.mediaId] = existing
            } else {
                candidatesById[item.mediaId] = candidate
                insertionOrder.append(item.mediaId)
            }
        }

        let recommendedLabels = sourceMediaLabelsById(for: sourceBeats, prefix: "Clip \(segment.order)")
        for item in mediaItems(for: Array(recommendedLabels.keys)) {
            upsert(item: item, group: .recommended, labels: recommendedLabels[item.mediaId] ?? [])
        }

        let nearbyLabels = sourceMediaLabelsById(for: nearbyBeats, prefix: "Nearby")
        for item in mediaItems(for: Array(nearbyLabels.keys)) {
            upsert(item: item, group: .nearby, labels: nearbyLabels[item.mediaId] ?? [])
        }

        for item in currentStoryScopeItems {
            upsert(item: item, group: .allEnabled, labels: allEnabledCandidateLabels(for: item))
        }

        return insertionOrder
            .compactMap { candidatesById[$0] }
            .sorted {
                let lhsGroup = groupPriority($0.group)
                let rhsGroup = groupPriority($1.group)
                if lhsGroup != rhsGroup {
                    return lhsGroup < rhsGroup
                }
                return $0.filename.localizedStandardCompare($1.filename) == .orderedAscending
            }
    }

    func generateVideoChainFrameFromSource(segmentId: String, role: String, mediaId: String) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        guard !isGeneratingVideoChainFrameSource(segmentId: segmentId, role: role) else { return }
        let chainId = videoChain.chainId
        guard let item = items.first(where: { $0.mediaId == mediaId }) else {
            videoChainStatus = "Source media not found"
            return
        }
        guard item.canBeEnabledContent, !curation(for: item).rejected else {
            videoChainStatus = "Source media is disabled"
            return
        }
        guard let segment = videoChain.segments.first(where: { $0.segmentId == segmentId }) else { return }

        let generationKey = videoChainFrameSourceKey(segmentId: segmentId, role: role)
        generatingVideoChainFrameSourceKey = generationKey
        videoChainStatus = role == "start" ? "Generating start frame" : "Generating target end frame"
        lastError = ""
        defer { generatingVideoChainFrameSourceKey = "" }

        do {
            let input = try videoChainFrameSourceInput(
                for: item,
                project: project,
                chainId: chainId,
                segmentId: segmentId,
                role: role
            )
            let client = try OpenAIClient.fromEnvironment()
            let prompt = videoChainFrameEditPrompt(segment: segment, role: role, sourceItem: item)
            let result = try await client.generateImageEdit(
                prompt: prompt,
                sourceImageData: input.data,
                sourceImageMimeType: input.mimeType,
                sourceFilename: input.url.lastPathComponent,
                projectId: project.projectId,
                runId: "\(chainId):\(segmentId):\(role):\(mediaId)"
            )
            guard currentProject?.projectId == project.projectId, videoChain.chainId == chainId else { return }
            let now = DateFormats.now()
            let frameVersionId = "framever_\(shortHash("\(chainId):\(segmentId):\(role):\(mediaId):\(now)", length: 14))"
            let outputURL = try contextStore.saveGeneratedVideoChainKeyframe(
                data: result.imageData,
                for: project,
                chainId: chainId,
                segmentId: segmentId,
                role: role,
                mediaId: mediaId,
                createdAt: now
            )
            var chain = videoChain
            guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }) else { return }
            var version = VideoFrameVersionDocument(
                versionId: frameVersionId,
                versionNumber: nextVideoFrameVersionNumber(chain.segments[index], role: role),
                role: role,
                status: .ready,
                framePath: outputURL.path,
                sourceFramePath: input.url.path,
                sourceMediaId: mediaId,
                sourceFilename: item.filename,
                prompt: prompt,
                assistantNote: "Generated from \(item.filename)",
                modelId: result.model,
                providerRequestId: result.requestId,
                traceId: result.traceId,
                createdAt: now,
                updatedAt: now
            )
            await archiveGeneratedVideoChainFrameVersion(&version, chain: chain, segment: chain.segments[index], project: project)
            chain.segments[index].upsertFrameVersion(version, activate: true)
            chain.segments[index].updatedAt = now
            chain = preflightedVideoChain(chain)
            try persistVideoChain(chain, for: project)
            videoChainStatus = role == "start" ? "Generated start frame" : "Generated target end frame"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Source frame generation failed"
        }
    }

    func autoPickMissingVideoChainKeyframes() {
        guard !videoChain.chainId.isEmpty else { return }
        let needsTargetFrames = videoChain.requiresTargetEndFrames
        for segment in videoChain.segments {
            if segment.order == 1, !segment.startFrameSource.hasFrame {
                useSourceMediaForVideoChainFrame(segmentId: segment.segmentId, role: "start")
            }
            if needsTargetFrames, !segment.targetEndFrameSource.hasFrame {
                useSourceMediaForVideoChainFrame(segmentId: segment.segmentId, role: "target_end")
            }
        }
        videoChainStatus = "Auto-picked available keyframes"
    }

    func regenerateVideoChainFrameWithAssistant(segmentId: String, role: String, instruction: String) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        guard !isGeneratingVideoChainFrameSource(segmentId: segmentId, role: role) else { return }
        let cleanedInstruction = instruction.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanedInstruction.isEmpty else { return }
        let chainId = videoChain.chainId
        guard let segment = videoChain.segments.first(where: { $0.segmentId == segmentId }) else { return }
        let source = role == "start" ? segment.startFrameSource : segment.targetEndFrameSource
        let sourcePath = framePath(for: source)
        guard !sourcePath.isEmpty, FileManager.default.fileExists(atPath: sourcePath) else {
            videoChainStatus = role == "start" ? "Start frame is missing" : "Target end frame is missing"
            return
        }

        let generationKey = videoChainFrameSourceKey(segmentId: segmentId, role: role)
        generatingVideoChainFrameSourceKey = generationKey
        videoChainStatus = role == "start" ? "Regenerating start frame" : "Regenerating target end frame"
        lastError = ""
        defer { generatingVideoChainFrameSourceKey = "" }

        do {
            let inputURL = URL(fileURLWithPath: sourcePath)
            let input = try videoChainFrameSourceInput(
                for: inputURL,
                project: project,
                chainId: chainId,
                segmentId: segmentId,
                role: role
            )
            let prompt = videoChainFrameAssistantPrompt(
                segment: segment,
                role: role,
                instruction: cleanedInstruction,
                sourceNote: source.note
            )
            let client = try OpenAIClient.fromEnvironment()
            let result = try await client.generateImageEdit(
                prompt: prompt,
                sourceImageData: input.data,
                sourceImageMimeType: input.mimeType,
                sourceFilename: input.url.lastPathComponent,
                projectId: project.projectId,
                runId: "\(chainId):\(segmentId):\(role):assistant:\(DateFormats.now())"
            )
            guard currentProject?.projectId == project.projectId, videoChain.chainId == chainId else { return }
            let now = DateFormats.now()
            let frameVersionId = "framever_\(shortHash("\(chainId):\(segmentId):\(role):assistant:\(now)", length: 14))"
            let outputURL = try contextStore.saveGeneratedVideoChainKeyframe(
                data: result.imageData,
                for: project,
                chainId: chainId,
                segmentId: segmentId,
                role: role,
                mediaId: frameVersionId,
                createdAt: now
            )
            var chain = videoChain
            guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }) else { return }
            var version = VideoFrameVersionDocument(
                versionId: frameVersionId,
                versionNumber: nextVideoFrameVersionNumber(chain.segments[index], role: role),
                role: role,
                status: .ready,
                framePath: outputURL.path,
                sourceFramePath: input.url.path,
                sourceMediaId: source.mediaId,
                sourceFilename: input.url.lastPathComponent,
                prompt: prompt,
                assistantNote: cleanedInstruction,
                modelId: result.model,
                providerRequestId: result.requestId,
                traceId: result.traceId,
                createdAt: now,
                updatedAt: now
            )
            await archiveGeneratedVideoChainFrameVersion(&version, chain: chain, segment: chain.segments[index], project: project)
            chain.segments[index].frameChatMessages.append(
                VideoFrameChatMessageDocument(
                    messageId: "vfmsg_\(shortHash("\(segmentId):\(role):user:\(now):\(cleanedInstruction)", length: 14))",
                    role: .user,
                    frameRole: role,
                    text: cleanedInstruction,
                    createdAt: now
                )
            )
            chain.segments[index].frameChatMessages.append(
                VideoFrameChatMessageDocument(
                    messageId: "vfmsg_\(shortHash("\(segmentId):\(role):assistant:\(now):\(prompt)", length: 14))",
                    role: .assistant,
                    frameRole: role,
                    text: "Generated version \(version.versionNumber) using the current frame as visual provenance.",
                    linkedVersionId: frameVersionId,
                    createdAt: now
                )
            )
            chain.segments[index].upsertFrameVersion(version, activate: true)
            chain.segments[index].updatedAt = now
            chain = preflightedVideoChain(chain)
            try persistVideoChain(chain, for: project)
            videoChainStatus = role == "start" ? "Start frame regenerated" : "Target end frame regenerated"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = role == "start" ? "Start frame regeneration failed" : "Target end frame regeneration failed"
        }
    }

