            var version = VideoFrameVersionDocument(
                versionId: frameVersionId,
                versionNumber: nextVideoFrameVersionNumber(chain.segments[index], role: role),
                role: role,
                status: .ready,
                framePath: outputURL.path,
                sourceFramePath: input.url.path,
                sourceMediaId: segment.startFrameSource.mediaId,
                sourceFilename: input.url.lastPathComponent,
                prompt: prompt,
                assistantNote: "Generated end frame from start frame and story beat",
                modelId: result.model,
                providerRequestId: result.requestId,
                traceId: result.traceId,
                createdAt: now,
                updatedAt: now
            )
            await archiveGeneratedVideoChainFrameVersion(&version, chain: chain, segment: chain.segments[index], project: project)
            chain.segments[index].upsertFrameVersion(version, activate: true)
            chain.segments[index].frameChatMessages.append(
                VideoFrameChatMessageDocument(
                    messageId: "vfmsg_\(shortHash("\(segmentId):target_end:from_start:\(now)", length: 14))",
                    role: .assistant,
                    frameRole: role,
                    text: "Generated a target end frame from the active start frame and this clip's story beat.",
                    linkedVersionId: frameVersionId,
                    createdAt: now
                )
            )
            chain.segments[index].updatedAt = now
            chain = preflightedVideoChain(chain)
            try persistVideoChain(chain, for: project)
            videoChainStatus = "Generated target end frame"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Target end frame generation failed"
        }
    }

    func selectVideoChain(chainId: String) {
        guard let project = currentProject else { return }
        let chain = contextStore.loadVideoChain(for: project, chainId: chainId)
        videoChain = chain
        if !videoChains.contains(where: { $0.chainId == chain.chainId }) {
            videoChains.insert(chain, at: 0)
            videoChains.sort { $0.updatedAt > $1.updatedAt }
        }
        do {
            try persistActiveVideoChainSelection(chain.chainId, for: project)
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Video Chain selection save failed"
            return
        }
        videoChainStatus = chain.status == .ready ? "Video Chain ready" : "Loaded Video Chain"
    }

    func activateVideoChainSegmentVersion(segmentId: String, versionId: String) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        var chain = videoChain
        guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }),
              var version = chain.segments[index].versions.first(where: { $0.versionId == versionId }) else {
            return
        }
        await archiveGeneratedVideoChainSegmentVersion(&version, chain: chain, segment: chain.segments[index], project: project)
        await archiveGeneratedVideoChainActualEndFrame(&version, chain: chain, segment: chain.segments[index], project: project)
        chain.segments[index].upsertVersion(version, activate: true)
        if let seamIndex = chain.seams.firstIndex(where: { $0.fromSegmentId == segmentId }) {
            chain.seams[seamIndex].handoffFramePath = version.actualEndFramePath
            chain.seams[seamIndex].status = version.actualEndFramePath.isEmpty ? .stale : .ready
        }
        let hasDownstream = index < chain.segments.count - 1
        if hasDownstream {
            markVideoChainDownstreamStale(&chain, fromIndex: index)
            if let seamIndex = chain.seams.firstIndex(where: { $0.fromSegmentId == segmentId }) {
                chain.seams[seamIndex].handoffFramePath = version.actualEndFramePath
                chain.seams[seamIndex].status = .needsRechain
            }
            chain.status = .stale
            chain.stitchedOutputPath = ""
        }
        chain.updatedAt = DateFormats.now()
        do {
            if !hasDownstream {
                try await stitchReadyVideoChain(&chain, project: project, job: nil)
            }
            try persistVideoChain(chain, for: project)
            await exportVideoChainManifest(chain)
            videoChainStatus = hasDownstream ? "Clip version activated; downstream needs rechain" : "Clip version activated"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Clip version activated; stitch failed"
            try? persistVideoChain(chain, for: project)
        }
    }

    func activateVideoChainFrameVersion(segmentId: String, role: String, versionId: String) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        var chain = videoChain
        guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }),
              var version = chain.segments[index].frameVersions.first(where: { $0.versionId == versionId }) else {
            return
        }
        await archiveGeneratedVideoChainFrameVersion(&version, chain: chain, segment: chain.segments[index], project: project)
        chain.segments[index].upsertFrameVersion(version, activate: true)
        chain.segments[index].updatedAt = DateFormats.now()
        chain = preflightedVideoChain(chain)
        do {
            try persistVideoChain(chain, for: project)
            videoChainStatus = role == "start" ? "Start frame version activated" : "Target end frame version activated"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Frame version activation failed"
        }
    }

    func regenerateVideoChainSegment(segmentId: String, rechainDownstream: Bool) async {
        await generateVideoChain(regeneratingSegmentId: segmentId, rechainDownstream: rechainDownstream)
    }

    func retakeVideoChainSegment(
        segmentId: String,
        startSeconds: Double,
        durationSeconds: Double,
        instruction: String
    ) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        guard videoChain.selectedProviderId == .ltxDirect else {
            videoChainStatus = "Retake is available for LTX clips"
            return
        }
        guard !isGeneratingVideoChain else { return }
        var chain = videoChain
        guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }) else { return }
        let segment = chain.segments[index]
        let sourcePath = segment.activeVideoPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !sourcePath.isEmpty, FileManager.default.fileExists(atPath: sourcePath) else {
            videoChainStatus = "Retake needs an active clip"
            return
        }

        isGeneratingVideoChain = true
        videoChainStatus = "Retaking Clip \(segment.order)"
        defer { isGeneratingVideoChain = false }

        let now = DateFormats.now()
        let versionNumber = nextVideoSegmentVersionNumber(segment)
        let versionId = "clipver_\(shortHash("\(chain.chainId):\(segment.segmentId):retake:\(now)", length: 14))"
        let outputURL = contextStore.videoChainClipVersionURL(
            for: project,
            chainId: chain.chainId,
            segmentId: segment.segmentId,
            versionId: versionId,
            versionNumber: versionNumber
        )
        let modelSelection = chain.selectedModelId ?? VideoModelSelection.resolved(requested: chain.modelSelection, provider: .ltxDirect)
        let prompt = retakePrompt(basePrompt: segment.prompt, instruction: instruction)
        var version = VideoSegmentVersionDocument(
            versionId: versionId,
            versionNumber: versionNumber,
            status: .generating,
            providerId: .ltxDirect,
            modelId: modelSelection,
            videoOutputPath: outputURL.path,
            normalizedVideoOutputPath: outputURL.path,
            sourceVideoPath: sourcePath,
            retakeStartSeconds: max(0, startSeconds),
            retakeDurationSeconds: max(0.1, durationSeconds),
            startFramePath: segment.activeVersion?.startFramePath ?? framePath(for: segment.startFrameSource),
            targetEndFramePath: segment.activeVersion?.targetEndFramePath ?? framePath(for: segment.targetEndFrameSource),
            prompt: prompt,
            negativePrompt: segment.negativePrompt,
            motionDirective: segment.motionDirective,
            createdAt: now,
            updatedAt: now
        )
        chain.segments[index].upsertVersion(version, activate: false)
        do {
            try persistVideoChain(chain, for: project)
            let provider = LTXDirectVideoProvider(credentialStore: videoCredentialStore)
            logGeneration(
                kind: "video.start",
                message: "Clip retake (LTX) clip \(segment.order) chain=\(chain.chainId) model=\(modelSelection.rawValue)"
            )
            let retakeStartedAt = Date()
            let result = try await provider.generateRetake(
                from: VideoClipRetakeRequest(
                    chainId: chain.chainId,
                    segmentId: segment.segmentId,
                    modelSelection: modelSelection,
                    prompt: prompt,
                    outputProfile: chain.outputProfile,
                    sourceVideoURL: URL(fileURLWithPath: sourcePath),
                    startSeconds: max(0, startSeconds),
                    durationSeconds: max(0.1, durationSeconds),
                    outputURL: outputURL
                )
            )
            let finalFrameURL = contextStore.videoChainVersionKeyframesDirectory(
                for: project,
                chainId: chain.chainId,
                segmentId: segment.segmentId
            )
            .appendingPathComponent("v\(String(format: "%02d", versionNumber))_\(safeIdentifier(versionId))_actual_end.png")
            _ = try await VideoChainMedia.extractFinalFrame(videoURL: result.outputURL, outputURL: finalFrameURL)
            logGeneration(
                kind: "video.completed",
                message: "Clip retake ready clip \(segment.order) chain=\(chain.chainId) duration_ms=\(Int(Date().timeIntervalSince(retakeStartedAt) * 1000)) request_id=\(result.providerJobId.trimmed.nilIfEmpty ?? "-")"
            )
            version.status = .ready
            version.providerJobId = result.providerJobId
            version.providerOperation = result.providerOperation
            version.traceId = result.traceId
            version.providerNativeSize = result.providerNativeSize
            version.videoOutputPath = result.outputURL.path
            version.normalizedVideoOutputPath = result.outputURL.path
            version.actualEndFramePath = finalFrameURL.path
            version.updatedAt = DateFormats.now()
            await archiveGeneratedVideoChainSegmentVersion(&version, chain: chain, segment: chain.segments[index], project: project)
            await archiveGeneratedVideoChainActualEndFrame(&version, chain: chain, segment: chain.segments[index], project: project)
            chain.segments[index].upsertVersion(version, activate: true)
            pruneSegmentVersions(&chain.segments[index])
            let hasDownstream = index < chain.segments.count - 1
            markVideoChainDownstreamStale(&chain, fromIndex: index)
            if let seamIndex = chain.seams.firstIndex(where: { $0.fromSegmentId == segment.segmentId }) {
                chain.seams[seamIndex].handoffFramePath = finalFrameURL.path
                chain.seams[seamIndex].status = hasDownstream ? .needsRechain : .ready
            }
            if hasDownstream {
                chain.status = .stale
                chain.stitchedOutputPath = ""
            }
            chain.updatedAt = DateFormats.now()
            if !hasDownstream {
                try await stitchReadyVideoChain(&chain, project: project, job: nil)
            }
            try persistVideoChain(chain, for: project)
            await exportVideoChainManifest(chain)
            videoChainStatus = hasDownstream ? "Clip retake ready; downstream needs rechain" : "Clip retake ready"
        } catch {
            if !(Task.isCancelled || isCancellationLikeError(error)) {
                logGeneration(
                    kind: "video.error",
                    message: "Clip retake failed clip \(segment.order) chain=\(chain.chainId): \(shortSummaryText(error.localizedDescription, limit: 200))"
                )
            }
            version.status = .failed
            version.errorMessage = error.localizedDescription
            version.updatedAt = DateFormats.now()
            chain.segments[index].upsertVersion(version, activate: false)
            chain.status = .failed
            chain.updatedAt = DateFormats.now()
            try? persistVideoChain(chain, for: project)
            lastError = error.localizedDescription
            videoChainStatus = "Clip retake failed"
        }
    }

    func exportVideoChainManifest(_ chain: VideoChainDocument? = nil) async {
        guard let project = currentProject else { return }
        var chain = chain ?? videoChain
        guard !chain.chainId.isEmpty else { return }
        let jsonURL = contextStore.videoChainManifestJSONURL(for: project, chainId: chain.chainId)
        let markdownURL = contextStore.videoChainManifestMarkdownURL(for: project, chainId: chain.chainId)
        do {
            let json = try JSONCoding.prettyEncoder.encode(chain)
            let markdown = videoChainMarkdown(chain)
            try await Task.detached(priority: .utility) {
                try ensureDirectory(jsonURL.deletingLastPathComponent())
                try json.write(to: jsonURL, options: [.atomic])
                try markdown.write(to: markdownURL, atomically: true, encoding: .utf8)
            }.value
            chain.manifestJSONPath = jsonURL.path
            chain.manifestMarkdownPath = markdownURL.path
            try persistVideoChain(chain, for: project)
            videoChainStatus = "Video Chain manifest exported"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Video Chain manifest export failed"
        }
    }

    func generateActiveVideoChain() async {
        await generateVideoChain(regeneratingSegmentId: nil, rechainDownstream: false)
    }

    private func generateVideoChain(regeneratingSegmentId: String?, rechainDownstream: Bool) async {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        var chain = videoChain
        let preserveBoundaries = regeneratingSegmentId != nil && !rechainDownstream
        let regenerationIndex = regeneratingSegmentId.flatMap { segmentId in
            chain.segments.firstIndex { $0.segmentId == segmentId }
        }
        if let regenerationIndex {
            chain.segments[regenerationIndex].status = .stale
            chain.segments[regenerationIndex].updatedAt = DateFormats.now()
            if rechainDownstream {
                for downstreamIndex in chain.segments.indices where downstreamIndex > regenerationIndex && !chain.segments[downstreamIndex].locked {
                    chain.segments[downstreamIndex].status = .stale
                    chain.segments[downstreamIndex].downstreamStale = true
                    chain.segments[downstreamIndex].updatedAt = DateFormats.now()
                }
                for seamIndex in chain.seams.indices {
                    let fromIndex = chain.segments.firstIndex { $0.segmentId == chain.seams[seamIndex].fromSegmentId } ?? 0
                    if fromIndex >= regenerationIndex {
                        chain.seams[seamIndex].status = .needsRechain
                    }
                }
            }
        }
        chain = preflightedVideoChain(chain)
        let providerId = chain.selectedProviderId
        if providerId == .bestAvailable || providerId == .localPromptExport {
            chain.status = .readyForApproval
            try? persistVideoChain(chain, for: project)
            videoChainStatus = "Configure CivitAI, Kling, or LTX, or choose Existing Clips before generating video"
            return
        }
        if !chain.preflightBlockers.isEmpty {
            chain.status = chain.missingTargetEndFrameCount > 0 ? .needsKeyframes : .readyForApproval
            try? persistVideoChain(chain, for: project)
            videoChainStatus = chain.preflightBlockers.prefix(2).joined(separator: ", ")
            return
        }
        let generationIndices = chain.segments.indices.filter { index in
            shouldGenerateVideoSegment(
                chain.segments[index],
                index: index,
                regenerationIndex: regenerationIndex,
                rechainDownstream: rechainDownstream
            )
        }
        guard !generationIndices.isEmpty else {
            do {
                try await stitchReadyVideoChain(&chain, project: project, job: nil)
                try persistVideoChain(chain, for: project)
                await exportVideoChainManifest(chain)
                videoChainStatus = "Video Chain ready"
            } catch {
                lastError = error.localizedDescription
                videoChainStatus = "Video Chain stitch failed"
            }
            return
        }
        isGeneratingVideoChain = true
        defer { isGeneratingVideoChain = false }
        let registry = VideoProviderRegistry(credentialStore: videoCredentialStore)
        let provider = registry.provider(for: providerId)
        let jobVerb = regenerationIndex == nil ? "Generating Video Chain" : (rechainDownstream ? "Rechaining Video Chain" : "Regenerating Clip")
        var job = VideoGenerationJobDocument(
            jobId: "vjob_\(shortHash("\(chain.chainId):\(DateFormats.now())", length: 14))",
            chainId: chain.chainId,
            providerId: providerId,
            status: .queued,
            message: jobVerb,
            progressCompleted: 0,
            progressTotal: generationIndices.count
        )
        chain.jobs.append(job)
        chain.status = .generating
        chain.updatedAt = DateFormats.now()
        try? persistVideoChain(chain, for: project)

        var pendingVersionsBySegmentId: [String: VideoSegmentVersionDocument] = [:]
        do {
            for (completedCount, index) in generationIndices.enumerated() {
                if index > 0 && !preserveBoundaries {
                    let previous = chain.segments[index - 1]
                    guard !previous.actualEndFramePath.isEmpty else {
                        throw ScreenGraphError.capture("Clip \(chain.segments[index].order) is waiting for the previous final frame.")
                    }
                    chain.segments[index].startFrameSource = VideoFrameSourceDocument(
                        type: .previousSegmentEnd,
                        segmentId: previous.segmentId,
                        framePath: previous.actualEndFramePath,
                        normalizedFramePath: previous.actualEndFramePath,
                        note: "Clip \(previous.order) actual final frame"
                    )
                }
                job.status = .generating
                job.segmentId = chain.segments[index].segmentId
                job.stage = "generating_clip"
                job.message = "Generating Clip \(chain.segments[index].order)"
                job.progressCompleted = completedCount
                job.progressTotal = generationIndices.count
                chain.jobs[chain.jobs.count - 1] = job
                chain.segments[index].status = .generating
                try persistVideoChain(chain, for: project)

                let segment = chain.segments[index]
                let now = DateFormats.now()
                let versionNumber = nextVideoSegmentVersionNumber(segment)
                let versionId = "clipver_\(shortHash("\(chain.chainId):\(segment.segmentId):\(now)", length: 14))"
                let usesNativeExtend = providerId == .ltxDirect && index > 0 && !preserveBoundaries
                let startSource = preserveBoundaries
                    ? preservedVideoBoundarySource(for: segment, role: "start")
                    : segment.startFrameSource
                let targetSource = try targetSourceForVideoGeneration(
                    segment: segment,
                    preserveBoundaries: preserveBoundaries
                )
                let startURL = usesNativeExtend
                    ? nil
                    : (startSource.hasFrame
                        ? try normalizedFrameURL(
                            for: startSource,
                            chain: chain,
                            segment: segment,
                            role: "start",
                            project: project,
                            versionId: versionId
                        )
                        : nil)
                let targetURL = targetSource.hasFrame
                    ? try normalizedFrameURL(
                        for: targetSource,
                        chain: chain,
                        segment: segment,
                        role: "target_end",
                        project: project,
                        versionId: versionId
                    )
                    : nil
                let outputURL: URL
                if providerId == .localExistingClip, !segment.videoOutputPath.isEmpty {
                    outputURL = URL(fileURLWithPath: segment.activeVideoPath)
                } else {
                    outputURL = contextStore.videoChainClipVersionURL(
                        for: project,
                        chainId: chain.chainId,
                        segmentId: segment.segmentId,
                    versionId: versionId,
                    versionNumber: versionNumber
                )
                }
                let providerOutputURL = usesNativeExtend
                    ? contextStore.videoChainProviderOutputURL(
                        for: project,
                        chainId: chain.chainId,
                        segmentId: segment.segmentId,
                        versionId: versionId,
                        versionNumber: versionNumber,
                        operation: "extend"
                    )
                    : outputURL
                let modelSelection = chain.selectedModelId ?? VideoModelSelection.resolved(requested: chain.modelSelection, provider: providerId)
                let prompt = videoClipPrompt(
                    basePrompt: segment.prompt,
                    segment: segment,
                    isDownstream: index > 0,
                    usesNativeExtend: usesNativeExtend
                )
                let nativeExtendSource = usesNativeExtend
                    ? ltxNativeExtendSource(for: chain.segments[index - 1])
                    : nil
                var pendingVersion = VideoSegmentVersionDocument(
                    versionId: versionId,
                    versionNumber: versionNumber,
                    status: .generating,
                    providerId: providerId,
                    modelId: modelSelection,
                    videoOutputPath: outputURL.path,
                    normalizedVideoOutputPath: outputURL.path,
                    providerOutputPath: usesNativeExtend ? providerOutputURL.path : "",
                    sourceVideoPath: nativeExtendSource?.path ?? "",
                    extractedFromProviderOutput: usesNativeExtend,
                    extractionDurationSeconds: usesNativeExtend ? Double(segment.durationSeconds) : 0,
                    extendContextSeconds: usesNativeExtend ? ltxExtendContextSeconds(for: segment) : 0,
                    startFramePath: startURL?.path ?? framePath(for: startSource),
                    targetEndFramePath: targetURL?.path ?? "",
                    prompt: prompt,
                    negativePrompt: segment.negativePrompt,
                    motionDirective: segment.motionDirective,
                    createdAt: now,
                    updatedAt: now
                )
                pendingVersionsBySegmentId[segment.segmentId] = pendingVersion
                chain.segments[index].upsertVersion(pendingVersion, activate: false)
                try persistVideoChain(chain, for: project)

                logGeneration(
                    kind: "video.start",
                    message: "Video chain clip \(segment.order) chain=\(chain.chainId) provider=\(providerId.rawValue) model=\(modelSelection.rawValue)"
                )
                let clipStartedAt = Date()
                let result: VideoClipResult
                let generatedVideoURL: URL
                if usesNativeExtend {
                    guard let ltxProvider = provider as? LTXDirectVideoProvider else {
                        throw ScreenGraphError.capture("LTX native extend provider was unavailable.")
                    }
                    let sourceVideoPath = nativeExtendSource?.path ?? ""
                    guard !sourceVideoPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                          FileManager.default.fileExists(atPath: sourceVideoPath) else {
                        throw ScreenGraphError.capture("Clip \(segment.order) is waiting for the previous clip video before LTX extend.")
                    }
                    result = try await ltxProvider.generateExtension(
                        from: VideoClipExtendRequest(
                            chainId: chain.chainId,
                            segmentId: segment.segmentId,
                            modelSelection: modelSelection,
                            prompt: prompt,
                            durationSeconds: segment.durationSeconds,
                            contextSeconds: ltxExtendContextSeconds(for: segment),
                            sourceVideoURL: URL(fileURLWithPath: sourceVideoPath),
                            sourceKind: nativeExtendSource?.kind ?? "",
                            outputURL: providerOutputURL
                        )
                    )
                    _ = try await VideoChainMedia.extractTailSegment(
                        videoURL: result.outputURL,
                        outputURL: outputURL,
                        durationSeconds: Double(segment.durationSeconds)
                    )
                    let providerDuration = try await VideoChainMedia.videoDurationSeconds(videoURL: result.outputURL)
                    pendingVersion.extractionStartSeconds = max(0, providerDuration - Double(segment.durationSeconds))
                    generatedVideoURL = outputURL
                } else {
                    result = try await provider.generateClip(
                        from: VideoClipRequest(
                            chainId: chain.chainId,
                            segmentId: segment.segmentId,
                            modelSelection: modelSelection,
                            prompt: prompt,
                            negativePrompt: segment.negativePrompt,
                            durationSeconds: segment.durationSeconds,
                            outputProfile: chain.outputProfile,
                            startFrameURL: startURL,
                            targetEndFrameURL: targetURL,
                            outputURL: outputURL
                        )
                    )
                    generatedVideoURL = result.outputURL
                }
                let clipDurationMs = Int(Date().timeIntervalSince(clipStartedAt) * 1000)
                let clipJobId = result.providerJobId.trimmed.nilIfEmpty ?? result.providerVideoId.trimmed
                logGeneration(
                    kind: "video.completed",
                    message: "Video chain clip \(segment.order) chain=\(chain.chainId) duration_ms=\(clipDurationMs) request_id=\(clipJobId.isEmpty ? "-" : clipJobId)"
                )
                let finalFrameURL = contextStore.videoChainVersionKeyframesDirectory(
                    for: project,
                    chainId: chain.chainId,
                    segmentId: segment.segmentId
                )
                .appendingPathComponent("v\(String(format: "%02d", versionNumber))_\(safeIdentifier(versionId))_actual_end.png")
                _ = try await VideoChainMedia.extractFinalFrame(videoURL: generatedVideoURL, outputURL: finalFrameURL)
                pendingVersion.status = .ready
                pendingVersion.providerId = result.providerId
                pendingVersion.providerVideoId = result.providerVideoId
                pendingVersion.providerJobId = result.providerJobId
                pendingVersion.providerOperation = result.providerOperation
                pendingVersion.traceId = result.traceId
                pendingVersion.providerNativeSize = result.providerNativeSize
                pendingVersion.videoOutputPath = generatedVideoURL.path
                pendingVersion.normalizedVideoOutputPath = generatedVideoURL.path
                pendingVersion.providerOutputPath = usesNativeExtend ? result.outputURL.path : ""
                pendingVersion.actualEndFramePath = finalFrameURL.path
                pendingVersion.updatedAt = DateFormats.now()
                job.traceId = result.traceId
                chain.jobs[chain.jobs.count - 1] = job
                await archiveGeneratedVideoChainSegmentVersion(&pendingVersion, chain: chain, segment: chain.segments[index], project: project)
                await archiveGeneratedVideoChainActualEndFrame(&pendingVersion, chain: chain, segment: chain.segments[index], project: project)
                chain.segments[index].upsertVersion(pendingVersion, activate: true)
                pruneSegmentVersions(&chain.segments[index])
                chain.segments[index].downstreamStale = false
                if !preserveBoundaries,
                   let seamIndex = chain.seams.firstIndex(where: { $0.fromSegmentId == segment.segmentId }) {
                    chain.seams[seamIndex].handoffFramePath = finalFrameURL.path
                    chain.seams[seamIndex].status = .ready
                }
                try persistVideoChain(chain, for: project)
            }

            try await stitchReadyVideoChain(&chain, project: project, job: job)
            job = chain.jobs.last ?? job
            chain.status = .ready
            job.status = .ready
            job.stage = "ready"
            job.message = "Video Chain ready"
            job.progressCompleted = generationIndices.count
            job.progressTotal = generationIndices.count
            job.updatedAt = DateFormats.now()
            chain.jobs[chain.jobs.count - 1] = job
            try persistVideoChain(chain, for: project)
            await exportVideoChainManifest(chain)
            videoChainStatus = "Video Chain ready"
            logGeneration(
                kind: "video.completed",
                message: "Video Chain ready chain=\(chain.chainId) clips=\(generationIndices.count)"
            )
        } catch {
            chain.status = .failed
            if !(Task.isCancelled || isCancellationLikeError(error)) {
                logGeneration(
                    kind: "video.error",
                    message: "Video Chain failed chain=\(chain.chainId): \(shortSummaryText(error.localizedDescription, limit: 200))"
                )
            }
            if !chain.jobs.isEmpty {
                let failedSegmentId = chain.jobs[chain.jobs.count - 1].segmentId
                chain.jobs[chain.jobs.count - 1].status = .failed
                chain.jobs[chain.jobs.count - 1].message = error.localizedDescription
                chain.jobs[chain.jobs.count - 1].updatedAt = DateFormats.now()
                if let failedIndex = chain.segments.firstIndex(where: { $0.segmentId == failedSegmentId }) {
                    if var failedVersion = pendingVersionsBySegmentId[failedSegmentId] {
                        failedVersion.status = .failed
                        failedVersion.errorMessage = error.localizedDescription
                        failedVersion.updatedAt = DateFormats.now()
                        chain.segments[failedIndex].upsertVersion(failedVersion, activate: chain.segments[failedIndex].activeVersion == nil)
                    }
                    chain.segments[failedIndex].status = .failed
                    chain.segments[failedIndex].updatedAt = DateFormats.now()
                }
            }
            try? persistVideoChain(chain, for: project)
            lastError = error.localizedDescription
            videoChainStatus = "Video Chain failed"
        }
    }

    func setStoryAudioDirection(_ value: String) {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }

        do {
            var collection = storyAudioTracks
            if collection.projectId.isEmpty {
                collection.projectId = project.projectId
            }
            let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
            collection.operatorDirection = trimmed.isEmpty ? nil : trimmed
            collection.updatedAt = DateFormats.now()
            try contextStore.saveStoryAudioTracks(collection, for: project)
            storyAudioTracks = collection
            storyAudioTrack = collection.activeTrack
        } catch {
            lastError = error.localizedDescription
        }
    }

    func updateStoryAudioDraft(
        trackId: String,
        title: String,
        voiceText: String,
        beatPrompt: String,
        mixNotes: String,
        tagsText: String
    ) {
        guard let project = currentProject else { return }
        guard var track = storyAudioTracks.tracks.first(where: { $0.trackId == trackId }) else { return }
        guard track.isEditableDraft else { return }

        track.title = title.trimmingCharacters(in: .whitespacesAndNewlines)
        track.voiceText = voiceText.trimmingCharacters(in: .whitespacesAndNewlines)
        track.beatPrompt = beatPrompt.trimmingCharacters(in: .whitespacesAndNewlines)
        track.mixNotes = mixNotes.trimmingCharacters(in: .whitespacesAndNewlines)
        track.tags = tagsText
            .split { character in
                character == "," || character == "\n" || character == ";"
            }
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        track.updatedAt = DateFormats.now()

        do {
            try persistStoryAudioTrack(track, for: project, activate: storyAudioTracks.activeTrackId == trackId)
        } catch {
            lastError = error.localizedDescription
        }
    }

