    func draftStoryAudioTrackText() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        guard !isDraftingStoryAudioTrack, !isGeneratingStoryAudioTrack, !isRemixingStoryAudioTrack else { return }

        let scopedItems = currentStoryScopeItems
        guard !scopedItems.isEmpty else {
            storyStatus = "No enabled media"
            return
        }

        isDraftingStoryAudioTrack = true
        defer { isDraftingStoryAudioTrack = false }
        lastError = ""
        storyStatus = "Drafting Story Audio text"

        do {
            let now = DateFormats.now()
            let trackId = "story_audio_track_\(shortHash("\(project.projectId):\(now)", length: 12))"
            let openAIClient = try OpenAIClient.fromEnvironment()
            let direction = storyAudioDirection.trimmingCharacters(in: .whitespacesAndNewlines)
            let sourceBeatIds = storyBeatBoard.hasBeats
                ? storyBeatBoard.visibleBeats.map(\.beatId)
                : []
            let context = StoryAudioTrackGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                trackId: trackId,
                targetBeatId: "",
                sourceBeatIds: sourceBeatIds,
                durationSeconds: 7,
                voiceDurationRange: "3-5 seconds",
                mediaScopeSummary: storyMediaScopeSummary(items: scopedItems),
                storyWorldSummary: storyWorld.summary,
                storyGenre: storyWorld.genre,
                storyStyle: storyWorld.style,
                sourceContextSummary: sourceContextSummary(),
                aestheticJSON: currentAestheticJSON(),
                goalBriefSummary: goalBriefSummary(),
                operatorDirection: direction,
                beatBoardJSON: encodedActiveBeatBoard(),
                generatedAt: now
            )
            let result = try await openAIClient.draftStoryAudioTrack(context: context)
            guard currentProject?.projectId == project.projectId else { return }

            var draft = result.draft
            draft.projectId = project.projectId
            draft.trackId = trackId
            draft.title = draft.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Punchy Audio Track" : draft.title
            draft.voiceText = draft.voiceText.trimmingCharacters(in: .whitespacesAndNewlines)
            draft.beatPrompt = draft.beatPrompt.trimmingCharacters(in: .whitespacesAndNewlines)
            draft.mixNotes = draft.mixNotes.trimmingCharacters(in: .whitespacesAndNewlines)
            draft.tags = draft.tags.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
            draft.targetBeatId = draft.targetBeatId?.trimmingCharacters(in: .whitespacesAndNewlines)
            draft.sourceBeatIds = (draft.sourceBeatIds ?? sourceBeatIds)
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
            draft.generatedAt = now
            draft.updatedAt = now
            guard !draft.voiceText.isEmpty else {
                throw ScreenGraphError.openAI("Story Audio Track response did not include voice_text.")
            }
            guard !draft.beatPrompt.isEmpty else {
                throw ScreenGraphError.openAI("Story Audio Track response did not include beat_prompt.")
            }

            var track = StoryAudioTrackDocument.document(
                from: draft,
                durationSeconds: 7,
                operatorDirection: direction
            )
            let defaultVoice = StoryAudioVoiceCatalog.defaultOption(
                customVoiceId: ElevenLabsSettingsStore.resolvedCustomVoiceId()
            )
            track.voicePresetId = defaultVoice.id
            track.voiceName = defaultVoice.name
            track.voiceDescription = defaultVoice.descriptor
            track.voiceId = defaultVoice.voiceId ?? ""
            track.voiceSpeed = StoryAudioVoiceCatalog.defaultSpeed
            track.draftProvider = "openai"
            track.draftModelId = result.model
            track.draftResponseId = result.responseId
            track.sourceProjectStoryId = projectStory.acceptedStoryId
            track.sourceBeatBoardId = storyBeatBoard.beatBoardId
            track.sourceBoardFingerprint = storyBeatBoard.hasBeats ? storyBeatBoard.inputFingerprint.stableId : ""
            track.scope = sourceBeatIds.isEmpty ? "global_project_audio" : "beat_aware_audio"
            track.status = "drafted"
            track.errorMessage = ""
            track.generatedAt = now
            track.updatedAt = DateFormats.now()

            try persistStoryAudioTrack(track, for: project, activate: true)

            var workspace = storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.currentStep = .audio
            workspace.status = "Story Audio draft ready"
            workspace.updatedAt = DateFormats.now()

            try contextStore.saveStoryWorkspace(workspace, for: project)
            storyWorkspace = workspace
            storyStatus = "Story Audio draft ready"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Story Audio draft failed"
        }
    }

    func generateStoryAudioTrack() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !isGeneratingStoryAudioTrack, !isDraftingStoryAudioTrack, !isRemixingStoryAudioTrack else { return }
        guard storyAudioTrack.isEditableDraft else {
            storyStatus = "Draft Story Audio text first"
            return
        }

        var track = storyAudioTrack
        track.title = track.title.trimmingCharacters(in: .whitespacesAndNewlines)
        track.voiceText = track.voiceText.trimmingCharacters(in: .whitespacesAndNewlines)
        track.beatPrompt = track.beatPrompt.trimmingCharacters(in: .whitespacesAndNewlines)
        track.mixNotes = track.mixNotes.trimmingCharacters(in: .whitespacesAndNewlines)
        track.tags = track.tags.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        guard !track.voiceText.isEmpty else {
            storyStatus = "Add speech text before generating audio"
            return
        }
        guard !track.beatPrompt.isEmpty else {
            storyStatus = "Add a beat prompt before generating audio"
            return
        }

        isGeneratingStoryAudioTrack = true
        defer { isGeneratingStoryAudioTrack = false }
        lastError = ""
        storyStatus = "Generating Story Audio"
        var pendingTrack: StoryAudioTrackDocument?

        do {
            let now = DateFormats.now()
            let elevenAPIKey = try ElevenLabsSettingsStore.resolvedAPIKeyOrThrow()
            let elevenClient = ElevenLabsClient(apiKey: elevenAPIKey)
            let voiceOption = StoryAudioVoiceCatalog.option(
                for: track.voicePresetId,
                customVoiceId: ElevenLabsSettingsStore.resolvedCustomVoiceId()
            )
            let resolvedVoiceId = (voiceOption.voiceId ?? track.voiceId)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard !resolvedVoiceId.isEmpty else {
                throw ScreenGraphError.credentials("Select Archer/Lucy or configure Custom Voice ID before generating Story Audio.")
            }
            if track.projectId.isEmpty {
                track.projectId = project.projectId
            }
            if track.title.isEmpty {
                track.title = "Punchy Audio Track"
            }
            if track.generatedAt.isEmpty {
                track.generatedAt = now
            }
            track.status = "generating"
            track.errorMessage = ""
            track.voicePresetId = voiceOption.id
            track.voiceName = voiceOption.name
            track.voiceDescription = voiceOption.descriptor
            track.voiceId = resolvedVoiceId
            track.voiceModelId = ElevenLabsSpeechModels.defaultModelId
            track.voiceSpeed = StoryAudioVoiceCatalog.clampedSpeed(track.voiceSpeed)
            track.generatedVoiceSpeed = StoryAudioVoiceCatalog.clampedProviderSpeed(track.voiceSpeed)
            track.isBeatEnabled = track.isBeatEnabled ?? true
            track.voiceAsset = nil
            track.beatAsset = nil
            track.mixAsset = nil
            track.updatedAt = DateFormats.now()
            pendingTrack = track
            try persistStoryAudioTrack(track, for: project, activate: true)

            let audioDir = contextStore.storyAudioDirectory(for: project)
            try ensureDirectory(audioDir)
            let voiceURL = audioDir.appendingPathComponent("\(track.trackId)__voice.mp3")
            let beatURL = audioDir.appendingPathComponent("\(track.trackId)__beat.mp3")
            let mixURL = audioDir.appendingPathComponent("\(track.trackId)__mix.m4a")

            storyStatus = "Generating voice"
            let voiceResponse = try await elevenClient.createSpeech(
                voiceId: resolvedVoiceId,
                text: track.voiceText,
                modelId: track.voiceModelId,
                outputFormat: track.outputFormat,
                voiceSettings: ElevenLabsVoiceSettings(speed: track.effectiveGeneratedVoiceSpeed),
                projectId: project.projectId,
                runId: track.trackId
            )
            guard currentProject?.projectId == project.projectId else { return }
            recordSpend(SpendLedgerEntry(
                kind: "story_audio_tts",
                provider: track.voiceProvider,
                model: track.voiceModelId,
                requestId: voiceResponse.requestId,
                contextLabel: track.title,
                unit: "characters",
                unitCount: Double(voiceResponse.characterCount) ?? 0,
                estimatedCredits: Double(voiceResponse.characterCost),
                pricingNote: "elevenlabs character-cost header"
            ))
            try voiceResponse.data.write(to: voiceURL, options: [.atomic])
            track.voiceAsset = storyAudioAsset(
                kind: "voice",
                url: voiceURL,
                project: project,
                data: voiceResponse.data,
                provider: track.voiceProvider,
                modelId: track.voiceModelId,
                outputFormat: track.outputFormat,
                response: voiceResponse
            )
            track.updatedAt = DateFormats.now()
            pendingTrack = track
            try persistStoryAudioTrack(track, for: project, activate: true)

            storyStatus = "Generating beat bed"
            let beatResponse = try await elevenClient.createSoundEffect(
                text: track.beatPrompt,
                durationSeconds: track.durationSeconds,
                loop: track.loop,
                promptInfluence: track.promptInfluence,
                modelId: track.beatModelId,
                outputFormat: track.outputFormat,
                projectId: project.projectId,
                runId: track.trackId
            )
            guard currentProject?.projectId == project.projectId else { return }
            recordSpend(SpendLedgerEntry(
                kind: "sound_effect",
                provider: track.beatProvider,
                model: track.beatModelId,
                requestId: beatResponse.requestId,
                contextLabel: track.title,
                unit: "characters",
                unitCount: Double(beatResponse.characterCount) ?? 0,
                estimatedCredits: Double(beatResponse.characterCost),
                pricingNote: "elevenlabs character-cost header"
            ))
            try beatResponse.data.write(to: beatURL, options: [.atomic])
            track.beatAsset = storyAudioAsset(
                kind: "beat",
                url: beatURL,
                project: project,
                data: beatResponse.data,
                provider: track.beatProvider,
                modelId: track.beatModelId,
                outputFormat: track.outputFormat,
                response: beatResponse
            )
            track.updatedAt = DateFormats.now()
            pendingTrack = track
            try persistStoryAudioTrack(track, for: project, activate: true)

            storyStatus = "Mixing Story Audio"
            try await StoryAudioMixer.mixVoiceOverBeat(
                voiceURL: voiceURL,
                beatURL: beatURL,
                outputURL: mixURL,
                durationSeconds: track.durationSeconds,
                voiceStartSeconds: track.voiceStartSeconds,
                beatVolume: track.effectiveBeatVolume,
                voiceVolume: track.timeline.first(where: { $0.kind == "voice" })?.volume ?? 1.0,
                voicePlaybackRate: track.localVoiceSpeedRatio
            )
            guard currentProject?.projectId == project.projectId else { return }
            let mixData = try Data(contentsOf: mixURL)
            track.mixAsset = storyAudioAsset(
                kind: "mix",
                url: mixURL,
                project: project,
                data: mixData,
                provider: "local_avfoundation",
                modelId: "avmutablecomposition",
                outputFormat: "m4a_aac",
                response: nil
            )
            track.status = "ready"
            track.errorMessage = ""
            track.updatedAt = DateFormats.now()

            var workspace = storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.currentStep = .audio
            workspace.status = "Story Audio ready"
            workspace.updatedAt = DateFormats.now()

            try persistStoryAudioTrack(track, for: project, activate: true)
            try contextStore.saveStoryWorkspace(workspace, for: project)
            storyWorkspace = workspace
            storyStatus = "Story Audio ready"
            touchCurrentProject()
        } catch {
            if var failedTrack = pendingTrack, currentProject?.projectId == project.projectId {
                failedTrack.status = "failed"
                failedTrack.errorMessage = error.localizedDescription
                failedTrack.updatedAt = DateFormats.now()
                try? persistStoryAudioTrack(failedTrack, for: project, activate: true)
            }
            lastError = error.localizedDescription
            storyStatus = "Story Audio failed"
        }
    }

    func repairStoryAudioTrackMix(trackId: String) async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !isGeneratingStoryAudioTrack, !isDraftingStoryAudioTrack, !isRemixingStoryAudioTrack else { return }
        guard var track = storyAudioTracks.tracks.first(where: { $0.trackId == trackId }) else { return }
        guard track.canBuildLocalMix else {
            storyStatus = "Missing local voice or beat asset"
            return
        }

        isRemixingStoryAudioTrack = true
        defer { isRemixingStoryAudioTrack = false }
        lastError = ""
        storyStatus = "Finishing Story Audio mix"

        let previousTrack = track
        do {
            track = try await buildLocalStoryAudioMix(
                track: track,
                project: project,
                targetSpeed: track.effectiveVoiceSpeed
            )
            guard currentProject?.projectId == project.projectId else { return }
            try persistStoryAudioTrack(track, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            storyStatus = "Story Audio mix ready"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            var failedTrack = previousTrack
            failedTrack.errorMessage = error.localizedDescription
            failedTrack.updatedAt = DateFormats.now()
            try? persistStoryAudioTrack(failedTrack, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            lastError = error.localizedDescription
            storyStatus = "Story Audio mix repair failed"
        }
    }

    func remixStoryAudioTrackSpeed(trackId: String, voiceSpeed: Double) async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !isGeneratingStoryAudioTrack, !isDraftingStoryAudioTrack, !isRemixingStoryAudioTrack else { return }
        guard var track = storyAudioTracks.tracks.first(where: { $0.trackId == trackId }) else { return }
        guard track.status == "ready", track.canBuildLocalMix else {
            storyStatus = "Generate audio before remixing speed"
            return
        }

        let targetSpeed = StoryAudioVoiceCatalog.clampedSpeed(voiceSpeed)
        guard abs(track.effectiveVoiceSpeed - targetSpeed) > 0.001 else { return }

        isRemixingStoryAudioTrack = true
        defer { isRemixingStoryAudioTrack = false }
        lastError = ""
        storyStatus = "Remixing Story Audio speed"

        let previousTrack = track
        do {
            track = try await buildLocalStoryAudioMix(
                track: track,
                project: project,
                targetSpeed: targetSpeed
            )
            guard currentProject?.projectId == project.projectId else { return }
            try persistStoryAudioTrack(track, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            storyStatus = "Story Audio speed remixed"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            try? persistStoryAudioTrack(previousTrack, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            lastError = error.localizedDescription
            storyStatus = "Story Audio speed remix failed"
        }
    }

    func setStoryAudioTrackBeatEnabled(trackId: String, isEnabled: Bool) async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !isGeneratingStoryAudioTrack, !isDraftingStoryAudioTrack, !isRemixingStoryAudioTrack else { return }
        guard var track = storyAudioTracks.tracks.first(where: { $0.trackId == trackId }) else { return }
        guard track.canBuildLocalMix else {
            storyStatus = "Generate audio before changing Beat Bed"
            return
        }

        guard track.effectiveBeatEnabled != isEnabled else { return }

        isRemixingStoryAudioTrack = true
        defer { isRemixingStoryAudioTrack = false }
        lastError = ""
        storyStatus = isEnabled ? "Enabling Beat Bed" : "Disabling Beat Bed"

        let previousTrack = track
        do {
            track = try await buildLocalStoryAudioMix(
                track: track,
                project: project,
                targetSpeed: track.effectiveVoiceSpeed,
                beatEnabled: isEnabled
            )
            guard currentProject?.projectId == project.projectId else { return }
            try persistStoryAudioTrack(track, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            storyStatus = isEnabled ? "Beat Bed enabled" : "Beat Bed disabled"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            try? persistStoryAudioTrack(previousTrack, for: project, activate: storyAudioTracks.activeTrackId == trackId)
            lastError = error.localizedDescription
            storyStatus = "Beat Bed update failed"
        }
    }

    private func buildLocalStoryAudioMix(
        track: StoryAudioTrackDocument,
        project: ProjectRecord,
        targetSpeed: Double,
        beatEnabled: Bool? = nil
    ) async throws -> StoryAudioTrackDocument {
        guard let voiceAsset = track.voiceAsset, let beatAsset = track.beatAsset else {
            throw ScreenGraphError.capture("Missing local voice or beat asset.")
        }

        let voiceURL = URL(fileURLWithPath: voiceAsset.path)
        let beatURL = URL(fileURLWithPath: beatAsset.path)
        guard FileManager.default.fileExists(atPath: voiceURL.path),
              FileManager.default.fileExists(atPath: beatURL.path) else {
            throw ScreenGraphError.capture("Missing local voice or beat asset.")
        }

        var mixTrack = track
        if let beatEnabled {
            mixTrack.isBeatEnabled = beatEnabled
        }

        let audioDir = contextStore.storyAudioDirectory(for: project)
        let mixURL = mixTrack.mixAsset.flatMap { asset -> URL? in
            let trimmed = asset.path.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : URL(fileURLWithPath: trimmed)
        } ?? audioDir.appendingPathComponent("\(mixTrack.trackId)__mix.m4a")
        let generatedSpeed = mixTrack.effectiveGeneratedVoiceSpeed
        let tempURL = mixURL
            .deletingLastPathComponent()
            .appendingPathComponent("\(mixTrack.trackId)__mix_speed_tmp.m4a")

        do {
            if FileManager.default.fileExists(atPath: tempURL.path) {
                try FileManager.default.removeItem(at: tempURL)
            }
            try await StoryAudioMixer.mixVoiceOverBeat(
                voiceURL: voiceURL,
                beatURL: beatURL,
                outputURL: tempURL,
                durationSeconds: mixTrack.durationSeconds,
                voiceStartSeconds: mixTrack.voiceStartSeconds,
                beatVolume: mixTrack.effectiveBeatVolume,
                voiceVolume: mixTrack.timeline.first(where: { $0.kind == "voice" })?.volume ?? 1.0,
                voicePlaybackRate: targetSpeed / max(generatedSpeed, 0.01)
            )
            guard currentProject?.projectId == project.projectId else {
                if FileManager.default.fileExists(atPath: tempURL.path) {
                    try? FileManager.default.removeItem(at: tempURL)
                }
                throw ScreenGraphError.capture("Story Audio project changed before mix finished.")
            }

            if FileManager.default.fileExists(atPath: mixURL.path) {
                _ = try FileManager.default.replaceItemAt(
                    mixURL,
                    withItemAt: tempURL,
                    backupItemName: nil,
                    options: []
                )
            } else {
                try FileManager.default.moveItem(at: tempURL, to: mixURL)
            }

            let mixData = try Data(contentsOf: mixURL)
            var updatedTrack = mixTrack
            updatedTrack.voiceSpeed = targetSpeed
            updatedTrack.generatedVoiceSpeed = generatedSpeed
            updatedTrack.mixAsset = storyAudioAsset(
                kind: "mix",
                url: mixURL,
                project: project,
                data: mixData,
                provider: "local_avfoundation",
                modelId: "avmutablecomposition",
                outputFormat: "m4a_aac",
                response: nil
            )
            updatedTrack.status = "ready"
            updatedTrack.errorMessage = ""
            updatedTrack.updatedAt = DateFormats.now()
            return updatedTrack
        } catch {
            if FileManager.default.fileExists(atPath: tempURL.path) {
                try? FileManager.default.removeItem(at: tempURL)
            }
            throw error
        }
    }

    func activateStoryAudioTrack(trackId: String) {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
