            try contextStore.saveStoryAudioTracks(updated, for: project)
            try contextStore.saveStoryAudioTrack(updated.activeTrack, for: project)
            storyAudioTracks = updated
            storyAudioTrack = updated.activeTrack
            storyStatus = "Story Audio selected"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Story Audio selection failed"
        }
    }

    func draftStoryBeats() async {
        guard let project = currentProject else {
            storyStatus = "Create or select a project first"
            return
        }
        guard !readyLenses.isEmpty else {
            storyStatus = "Enable the Scene Plan"
            return
        }
        guard hasCurrentStorySignals else {
            storyStatus = "Build Story Signals first"
            return
        }
        guard !isDraftingStoryBeats else { return }

        let scopedItems = currentStoryScopeItems
        guard !scopedItems.isEmpty else {
            storyStatus = "No enabled media"
            return
        }

        isDraftingStoryBeats = true
        lastError = ""
        storyStatus = "Drafting Story Beats"

        do {
            let client = try OpenAIClient.fromEnvironment()
            let now = DateFormats.now()
            let context = StoryBeatGenerationContext(
                projectId: project.projectId,
                projectName: project.name,
                scope: .enabledMedia,
                mediaScopeSummary: storyMediaScopeSummary(items: scopedItems),
                storyWorldSummary: storyWorld.summary,
                storyGenre: storyWorld.genre,
                storyStyle: storyWorld.style,
                sourceContextSummary: sourceContextSummary(),
                aestheticJSON: currentAestheticJSON(),
                archiveMeaningJSON: currentArchiveMeaningJSON(),
                generatedAt: now
            )
            let result = try await client.draftStoryBeats(context: context)
            guard currentProject?.projectId == project.projectId else {
                isDraftingStoryBeats = false
                return
            }
            var sheet = result.beatSheet
            sheet.projectId = project.projectId
            sheet.scope = .enabledMedia
            sheet.beatSheetId = sheet.beatSheetId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? "story_beat_sheet_\(shortHash("\(project.projectId):\(now)", length: 12))"
                : sheet.beatSheetId
            sheet.beats = sheet.beats
                .sorted { $0.order < $1.order }
                .enumerated()
                .map { index, beat in
                    var updated = beat
                    updated.order = index + 1
                    if updated.beatId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                        updated.beatId = "beat_\(index + 1)"
                    }
                    return updated
                }
            sheet.generatedAt = sheet.generatedAt.isEmpty ? now : sheet.generatedAt
            sheet.updatedAt = DateFormats.now()

            var workspace = storyWorkspace
            if workspace.projectId.isEmpty {
                workspace.projectId = project.projectId
            }
            workspace.currentStep = .beats
            workspace.status = "Story Beats ready"
            workspace.updatedAt = DateFormats.now()

            try contextStore.saveStoryBeatSheet(sheet, for: project)
            try contextStore.saveStoryWorkspace(workspace, for: project)
            storyBeatSheet = sheet
            storyWorkspace = workspace
            storyStatus = "Story Beats ready"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            storyStatus = "Story Beats failed"
        }

        isDraftingStoryBeats = false
    }

    func clearError() {
        lastError = ""
    }

    private func extractFrames(from video: MediaItemRecord, source: MediaSourceRecord?, project: ProjectRecord) async {
        do {
            let frames = try await store.extractFrames(from: video, source: source, for: project) { [weak self] progress in
                guard let self, self.currentProject?.projectId == project.projectId else { return }
                self.frameExtractionByVideoId[progress.videoMediaId] = VideoFrameExtractionState(
                    isExtracting: progress.isExtracting,
                    completedCount: progress.completedCount,
                    totalCount: progress.totalCount,
                    status: progress.status
                )
                if progress.isExtracting {
                    self.scanStatus = "\(progress.status) - \(progress.completedCount)/\(progress.totalCount)"
                }
            }
            guard currentProject?.projectId == project.projectId else { return }

            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            for frame in frames {
                updatedItemsById[frame.mediaId] = frame
            }
            let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
            try store.saveInventory(updatedItems, for: project)

            var updatedCuration = curationById
            for frame in frames where updatedCuration[frame.mediaId] == nil {
                updatedCuration[frame.mediaId] = MediaCurationRecord(mediaId: frame.mediaId, rejected: true)
            }
            try store.saveCuration(updatedCuration, for: project)

            items = updatedItems
            curationById = updatedCuration
            frameExtractionByVideoId[video.mediaId] = VideoFrameExtractionState(
                isExtracting: false,
                completedCount: frames.count,
                totalCount: frames.count,
                status: "Frames ready"
            )
            scanStatus = "Extracted \(frames.count) frame\(frames.count == 1 ? "" : "s") from \(video.filename)"
            touchCurrentProject()
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            frameExtractionByVideoId[video.mediaId] = VideoFrameExtractionState(
                isExtracting: false,
                completedCount: 0,
                totalCount: 0,
                status: "Frame extraction failed",
                errorMessage: error.localizedDescription
            )
            lastError = error.localizedDescription
            scanStatus = "Frame extraction failed"
        }
    }

