    func refreshSoundSceneTimeline() async {
        guard let project = currentProject else {
            soundSceneAssets = []
            selectedSoundSceneAssetId = ""
            soundScenePlans = []
            soundSceneTimelineStatus = "Create or select a project first"
            return
        }

        let projectId = project.projectId
        isLoadingSoundSceneTimeline = true
        soundSceneTimelineStatus = "Scanning sounds"
        defer {
            if currentProject?.projectId == projectId {
                isLoadingSoundSceneTimeline = false
            }
        }

        do {
            let assets = try await SoundSceneTimelineStore.shared.refreshDefaultSoundAssets(project: project)
            guard currentProject?.projectId == projectId else { return }

            soundSceneAssets = assets
            let arrangements = try await SoundSceneTimelineStore.shared.loadSceneSoundArrangements(project: project)
            guard currentProject?.projectId == projectId else { return }
            sceneSoundArrangements = arrangements
            if selectedSceneSoundArrangementId.isEmpty
                || !arrangements.contains(where: { $0.arrangementId == selectedSceneSoundArrangementId }) {
                selectedSceneSoundArrangementId = arrangements.first?.arrangementId ?? ""
            }
            sceneSoundArrangementStatus = arrangements.isEmpty
                ? "No sound arrangements yet"
                : "\(arrangements.count) sound arrangement\(arrangements.count == 1 ? "" : "s")"
            if selectedSoundSceneAssetId.isEmpty || !assets.contains(where: { $0.soundId == selectedSoundSceneAssetId }) {
                selectedSoundSceneAssetId = assets.first?.soundId ?? ""
            }

            guard !selectedSoundSceneAssetId.isEmpty else {
                soundScenePlans = []
                soundSceneTimelineStatus = "No sound files found"
                return
            }

            let plans = try await SoundSceneTimelineStore.shared.loadSoundScenePlans(
                project: project,
                soundId: selectedSoundSceneAssetId
            )
            guard currentProject?.projectId == projectId else { return }
            soundScenePlans = plans
            soundSceneTimelineStatus = "\(assets.count) sound\(assets.count == 1 ? "" : "s") · \(plans.count) scene card\(plans.count == 1 ? "" : "s")"
        } catch {
            guard currentProject?.projectId == projectId else { return }
            soundSceneTimelineStatus = error.localizedDescription
        }
    }

    func selectSoundSceneAsset(soundId: String) {
        guard selectedSoundSceneAssetId != soundId else { return }
        selectedSoundSceneAssetId = soundId
        soundScenePlans = []
        soundSceneTimelineStatus = "Loading scene cards"
        Task {
            await loadSoundScenePlansForSelectedSound()
        }
    }

    func addSoundScenePlanAtPlayhead(_ seconds: Double) async {
        guard let project = currentProject else {
            soundSceneTimelineStatus = "Create or select a project first"
            return
        }
        guard let sound = selectedSoundSceneAsset else {
            soundSceneTimelineStatus = "Select a sound file first"
            return
        }

        let start = min(max(seconds, 0), max(sound.durationSeconds - 1, 0))
        if soundScenePlans.contains(where: { start >= $0.startSeconds && start < $0.endSeconds }) {
            soundSceneTimelineStatus = "Move playhead to an open gap"
            return
        }
        let nextStart = soundScenePlans
            .filter { $0.startSeconds > start }
            .map(\.startSeconds)
            .min() ?? sound.durationSeconds
        let availableDuration = min(max(sound.durationSeconds - start, 0), max(nextStart - start, 0))
        guard availableDuration > 0 else {
            soundSceneTimelineStatus = "No room for a scene card at playhead"
            return
        }

        let plan = SoundScenePlan.draft(
            projectId: project.projectId,
            soundId: sound.soundId,
            startSeconds: start,
            durationSeconds: min(15, max(1, availableDuration))
        )
        await saveSoundScenePlan(plan)
    }

    func saveSoundScenePlan(_ plan: SoundScenePlan) async {
        guard let project = currentProject else {
            soundSceneTimelineStatus = "Create or select a project first"
            return
        }
        guard let sound = selectedSoundSceneAsset else {
            soundSceneTimelineStatus = "Select a sound file first"
            return
        }

        do {
            var normalized = plan
            normalized.projectId = project.projectId
            normalized.soundId = sound.soundId
            let saved = try await SoundSceneTimelineStore.shared.upsertSoundScenePlan(
                normalized,
                project: project,
                soundDurationSeconds: sound.durationSeconds
            )
            guard currentProject?.projectId == project.projectId else { return }
            mergeSoundScenePlan(saved)
            soundSceneTimelineStatus = "Saved \(saved.title)"
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            soundSceneTimelineStatus = error.localizedDescription
        }
    }

    func deleteSoundScenePlan(planId: String) async {
        guard !planId.trimmed.isEmpty else { return }
        guard let project = currentProject else {
            soundSceneTimelineStatus = "Create or select a project first"
            return
        }
        do {
            try await SoundSceneTimelineStore.shared.deleteSoundScenePlan(project: project, planId: planId)
            soundScenePlans.removeAll { $0.planId == planId }
            soundSceneTimelineStatus = "Deleted scene card"
        } catch {
            soundSceneTimelineStatus = error.localizedDescription
        }
    }

    private func loadSoundScenePlansForSelectedSound() async {
        guard let project = currentProject else { return }
        guard !selectedSoundSceneAssetId.isEmpty else {
            soundScenePlans = []
            return
        }
        let projectId = project.projectId
        let soundId = selectedSoundSceneAssetId
        do {
            let plans = try await SoundSceneTimelineStore.shared.loadSoundScenePlans(project: project, soundId: soundId)
            guard currentProject?.projectId == projectId, selectedSoundSceneAssetId == soundId else { return }
            soundScenePlans = plans
            soundSceneTimelineStatus = "\(plans.count) scene card\(plans.count == 1 ? "" : "s")"
        } catch {
            guard currentProject?.projectId == projectId, selectedSoundSceneAssetId == soundId else { return }
            soundSceneTimelineStatus = error.localizedDescription
        }
    }

    private func mergeSoundScenePlan(_ plan: SoundScenePlan) {
        soundScenePlans.removeAll { $0.planId == plan.planId }
        soundScenePlans.append(plan)
        soundScenePlans.sort {
            if $0.startSeconds == $1.startSeconds {
                return $0.title.localizedStandardCompare($1.title) == .orderedAscending
            }
            return $0.startSeconds < $1.startSeconds
        }
    }

    private func mergeSceneSoundArrangement(_ arrangement: SceneSoundArrangement) {
        sceneSoundArrangements.removeAll { $0.arrangementId == arrangement.arrangementId }
        sceneSoundArrangements.append(arrangement)
        sceneSoundArrangements.sort {
            if $0.updatedAt == $1.updatedAt {
                return $0.title.localizedStandardCompare($1.title) == .orderedAscending
            }
            return $0.updatedAt > $1.updatedAt
        }
    }

    private func addMedia(_ urls: [URL], project: ProjectRecord) async {
        guard !urls.isEmpty, !isScanning else { return }

        let baselineSources = sources
        let baselineItems = items
        let existingOrigins = Set(baselineSources.flatMap { [$0.path, $0.resolvedOriginalPath] })
        var seenPaths = Set<String>()
        let newURLs = urls.map(\.standardizedFileURL).filter { url in
            guard !existingOrigins.contains(url.path), !seenPaths.contains(url.path) else { return false }
            seenPaths.insert(url.path)
            return true
        }
        guard !newURLs.isEmpty else {
            scanStatus = "Selected media already added"
            return
        }

        let preflight = store.managedStoragePreflight(for: newURLs, project: project)
        let fallbackDecision: ManagedMediaFallbackDecision
        if preflight.copyRequiredURLs.isEmpty {
            fallbackDecision = .copy
        } else {
            fallbackDecision = managedMediaFallbackDecision(
                preflight: preflight,
                title: "Some media cannot use space-saving storage",
                linkExplanation: "Link in Place adds those files without copying them. Moving or deleting them later will make the media unavailable."
            )
        }
        guard fallbackDecision != .cancel else {
            scanStatus = "Add Media canceled"
            return
        }

        let clonePaths = Set(preflight.cloneURLs.map(\.path))
        let copyPaths = fallbackDecision == .copy
            ? Set(preflight.copyRequiredURLs.map(\.path))
            : Set<String>()
        isScanning = true
        lastError = ""
        scanStatus = "Adding \(newURLs.count) media file\(newURLs.count == 1 ? "" : "s")"
        var preparations: [ManagedMediaPreparation] = []
        let baselineCachePaths = Set(baselineItems.flatMap(mediaCachePaths))
        var stagedCachePaths = Set<String>()
        var didPersist = false
        defer {
            isScanning = false
            if !didPersist {
                preparations.forEach(store.discardManagedPreparation)
                discardUnpersistedCachePaths(stagedCachePaths)
            }
        }

        do {
            var importedSources: [MediaSourceRecord] = []
            var importedItems: [MediaItemRecord] = []
            var managedCount = 0
            var linkedCount = 0

            for (index, originalURL) in newURLs.enumerated() {
                scanStatus = "Adding \(originalURL.lastPathComponent) (\(index + 1)/\(newURLs.count))"
                let source: MediaSourceRecord
                if clonePaths.contains(originalURL.path) || copyPaths.contains(originalURL.path) {
                    let transferMode: ManagedMediaTransferMode = clonePaths.contains(originalURL.path) ? .clone : .copy
                    let choice = try await prepareManagedMedia(
                        from: originalURL,
                        for: project,
                        initialMode: transferMode,
                        runtimeFallbackTitle: "This file could not use space-saving storage",
                        linkExplanation: "Link in Place adds this file without copying it. Moving or deleting it later will make the media unavailable."
                    )
                    switch choice {
                    case let .managed(preparation):
                        preparations.append(preparation)
                        source = preparation.source
                        managedCount += 1
                    case .linked:
                        source = store.makeSource(
                            from: originalURL,
                            kind: .file,
                            storageMode: .linked,
                            originalURL: originalURL
                        )
                        linkedCount += 1
                    case .canceled:
                        throw CancellationError()
                    }
                } else {
                    source = store.makeSource(
                        from: originalURL,
                        kind: .file,
                        storageMode: .linked,
                        originalURL: originalURL
                    )
                    linkedCount += 1
                }

                let result = await store.scan(source: source, for: project) { [weak self] progress in
                    guard let self, progress.isScanning else { return }
                    self.scanStatus = "Indexing \(progress.currentFile.isEmpty ? originalURL.lastPathComponent : progress.currentFile)"
                }
                stagedCachePaths.formUnion(
                    result.items.flatMap(mediaCachePaths).filter { !baselineCachePaths.contains($0) }
                )
                guard let scannedItem = result.items.first,
                      scannedItem.scanError?.trimmed.nilIfEmpty == nil else {
                    throw ScreenGraphError.capture(
                        result.items.first?.scanError?.trimmed.nilIfEmpty
                            ?? "\(originalURL.lastPathComponent) could not be indexed."
                    )
                }
                var importedItem = scannedItem
                importedItem.filename = originalURL.lastPathComponent
                importedSources.append(result.source)
                importedItems.append(importedItem)
            }

            let importedSourceIds = Set(importedSources.map(\.sourceId))
            let updatedSources = baselineSources.filter { !importedSourceIds.contains($0.sourceId) } + importedSources
            let updatedItems = sortedMediaItems(deduplicatedMediaItems(
                baselineItems.filter { !importedSourceIds.contains($0.sourceId) } + importedItems
            ))
            try store.saveLibrary(sources: updatedSources, items: updatedItems, for: project)
            didPersist = true

            guard currentProject?.projectId == project.projectId else { return }
            sources = updatedSources
            items = updatedItems
            selectedItemId = importedItems.first?.mediaId
            scanStatus = managedCount == importedItems.count
                ? "Added \(managedCount) managed media file\(managedCount == 1 ? "" : "s")"
                : "Added \(managedCount) managed and \(linkedCount) linked media file\(linkedCount == 1 ? "" : "s")"
            if importedItems.count == 1, importedItems[0].kind == .video {
                studioAutoOpenVideo = importedItems[0]
            }
            touchCurrentProject()
        } catch is CancellationError {
            scanStatus = "Add Media canceled"
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not add media"
        }
    }

    private func beginManagedConsolidation(sources selectedSources: [MediaSourceRecord]) {
        guard let project = currentProject, !isScanning else { return }
        let urls = selectedSources.map { URL(fileURLWithPath: $0.path).standardizedFileURL }
        let preflight = store.managedStoragePreflight(for: urls, project: project)
        let fallbackDecision: ManagedMediaFallbackDecision
        if preflight.copyRequiredURLs.isEmpty {
            fallbackDecision = .copy
        } else {
            fallbackDecision = managedMediaFallbackDecision(
                preflight: preflight,
                title: "Some linked media requires a full copy",
                linkExplanation: "Keep Linked leaves those files in place while any clone-compatible files become managed."
            )
        }
        guard fallbackDecision != .cancel else {
            scanStatus = "Consolidation canceled"
            return
        }

        let clonePaths = Set(preflight.cloneURLs.map(\.path))
        let copyPaths = fallbackDecision == .copy
            ? Set(preflight.copyRequiredURLs.map(\.path))
            : Set<String>()
        let sourcesToManage = selectedSources.filter {
            clonePaths.contains(URL(fileURLWithPath: $0.path).standardizedFileURL.path)
                || copyPaths.contains(URL(fileURLWithPath: $0.path).standardizedFileURL.path)
        }
        guard !sourcesToManage.isEmpty else {
            scanStatus = "Media remains linked"
            return
        }

        Task { [weak self] in
            await self?.consolidateMediaSources(
                sourcesToManage,
                clonePaths: clonePaths,
                project: project
            )
        }
    }

    private func consolidateMediaSources(
        _ selectedSources: [MediaSourceRecord],
        clonePaths: Set<String>,
        project: ProjectRecord
    ) async {
        guard !isScanning else { return }
        isScanning = true
        lastError = ""
        let baselineSources = sources
        let baselineItems = items
        var preparations: [ManagedMediaPreparation] = []
        var didPersist = false
        defer {
            isScanning = false
            if !didPersist {
                preparations.forEach(store.discardManagedPreparation)
            }
        }

        do {
            var updatedSources = baselineSources
            var updatedItems = baselineItems
            let projectDirectory = projectLibrary.projectDirectory(for: project)
            var relocatedAudioPaths: [String: String] = [:]
            var managedSourceCount = 0
            for (index, source) in selectedSources.enumerated() {
                scanStatus = "Making \(source.displayName) managed (\(index + 1)/\(selectedSources.count))"
                let originalURL = URL(fileURLWithPath: source.path).standardizedFileURL
                let choice = try await prepareManagedMedia(
                    from: originalURL,
                    for: project,
                    initialMode: clonePaths.contains(originalURL.path) ? .clone : .copy,
                    runtimeFallbackTitle: "\(source.displayName) requires a full copy",
                    linkExplanation: "Link in Place leaves this source linked while consolidation continues with the remaining files."
                )
                guard case let .managed(preparation) = choice else {
                    if case .canceled = choice { throw CancellationError() }
                    continue
                }
                preparations.append(preparation)
                managedSourceCount += 1

                var managedSource = preparation.source
                managedSource.sourceId = source.sourceId
                managedSource.displayName = source.displayName
                managedSource.addedAt = source.addedAt
                managedSource.lastScannedAt = source.lastScannedAt
                if let sourceIndex = updatedSources.firstIndex(where: { $0.sourceId == source.sourceId }) {
                    updatedSources[sourceIndex] = managedSource
                }
                for itemIndex in updatedItems.indices
                where updatedItems[itemIndex].sourceId == source.sourceId
                    && updatedItems[itemIndex].derivativeKind?.trimmed.nilIfEmpty == nil {
                    updatedItems[itemIndex].path = preparation.managedURL.path
                    updatedItems[itemIndex].relativePath = preparation.managedURL.relativePath(from: projectDirectory)
                    if updatedItems[itemIndex].kind == .audio {
                        relocatedAudioPaths[updatedItems[itemIndex].mediaId] = preparation.managedURL.path
                    }
                }
            }

            guard managedSourceCount > 0 else {
                scanStatus = "Media remains linked"
                return
            }

            try store.saveLibrary(sources: updatedSources, items: updatedItems, for: project)
            didPersist = true
            guard currentProject?.projectId == project.projectId else { return }
            sources = updatedSources
            items = updatedItems
            relocateShotAudioMediaPaths(relocatedAudioPaths, project: project)
            scanStatus = "Made \(managedSourceCount) media source\(managedSourceCount == 1 ? "" : "s") managed"
            touchCurrentProject()
        } catch is CancellationError {
            scanStatus = "Consolidation canceled"
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not consolidate media"
        }
    }

    private func relinkMedia(
        _ item: MediaItemRecord,
        source: MediaSourceRecord,
        to url: URL,
        project: ProjectRecord
    ) async {
        guard !isScanning else { return }
        isScanning = true
        lastError = ""
        scanStatus = "Relinking \(item.filename)"
        let baselineCachePaths = Set(items.flatMap(mediaCachePaths))
        var stagedCachePaths = Set<String>()
        var didPersist = false
        defer {
            isScanning = false
            if !didPersist {
                discardUnpersistedCachePaths(stagedCachePaths)
            }
        }

        do {
            let replacementURL = url.standardizedFileURL
            var replacementSource = store.makeSource(
                from: replacementURL,
                kind: .file,
                storageMode: .linked,
                originalURL: replacementURL
            )
            replacementSource.sourceId = source.sourceId
            replacementSource.addedAt = source.addedAt
            let result = await store.scan(source: replacementSource, for: project) { [weak self] progress in
                guard let self, progress.isScanning else { return }
                self.scanStatus = "Indexing \(progress.currentFile.isEmpty ? replacementURL.lastPathComponent : progress.currentFile)"
            }
            stagedCachePaths.formUnion(
                result.items.flatMap(mediaCachePaths).filter { !baselineCachePaths.contains($0) }
            )
            guard var replacementItem = result.items.first,
                  replacementItem.kind == item.kind,
                  replacementItem.scanError?.trimmed.nilIfEmpty == nil else {
                throw ScreenGraphError.capture("The selected file is not a usable \(item.kind.rawValue).")
            }
            replacementItem.mediaId = item.mediaId
            replacementItem.sourceId = source.sourceId
            replacementItem.filename = replacementURL.lastPathComponent

            var updatedSources = sources
            if let index = updatedSources.firstIndex(where: { $0.sourceId == source.sourceId }) {
                updatedSources[index] = result.source
            }
            var updatedItems = items
            if let index = updatedItems.firstIndex(where: { $0.mediaId == item.mediaId }) {
                updatedItems[index] = replacementItem
            }
            try store.saveLibrary(sources: updatedSources, items: updatedItems, for: project)
            didPersist = true
            guard currentProject?.projectId == project.projectId else { return }
            sources = updatedSources
            items = sortedMediaItems(updatedItems)
            if replacementItem.kind == .audio {
                relocateShotAudioMediaPaths(
                    [replacementItem.mediaId: replacementItem.path],
                    project: project
                )
            }
            selectedItemId = item.mediaId
            scanStatus = "Relinked \(replacementURL.lastPathComponent) — linked in place"
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not relink media"
        }
    }

    private func managedMediaFallbackDecision(
        preflight: ManagedMediaStoragePreflight,
        title: String,
        linkExplanation: String
    ) -> ManagedMediaFallbackDecision {
        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = title
        let required = ByteCountFormatter.string(
            fromByteCount: preflight.copyRequiredByteCount,
            countStyle: .file
        )
        let available = preflight.availableByteCount.map {
            ByteCountFormatter.string(fromByteCount: $0, countStyle: .file)
        } ?? "unknown"
        alert.informativeText = "\(preflight.copyRequiredURLs.count) selected file\(preflight.copyRequiredURLs.count == 1 ? "" : "s") (\(required)) cannot be cloned into this project. A full copy would use that disk space. Available space: \(available). LitScenes preserves a 1 GB safety reserve. \(linkExplanation) The originals are never moved or deleted."
        let copyButton = alert.addButton(withTitle: "Copy into Project")
        alert.addButton(withTitle: "Link in Place")
        alert.addButton(withTitle: "Cancel")
        copyButton.isEnabled = preflight.canSafelyCopy
        switch alert.runModal() {
        case .alertFirstButtonReturn:
            return .copy
        case .alertSecondButtonReturn:
            return .link
        default:
            return .cancel
        }
    }

    private func prepareManagedMedia(
        from originalURL: URL,
        for project: ProjectRecord,
        initialMode: ManagedMediaTransferMode,
        runtimeFallbackTitle: String,
        linkExplanation: String
    ) async throws -> ManagedMediaPreparationChoice {
        do {
            return .managed(try await store.prepareManagedSource(
                from: originalURL,
                for: project,
                transferMode: initialMode
            ))
        } catch ManagedMediaStoreError.cloningUnavailable where initialMode == .clone {
            let preflight = store.copyStoragePreflight(for: [originalURL], project: project)
            switch managedMediaFallbackDecision(
                preflight: preflight,
                title: runtimeFallbackTitle,
                linkExplanation: linkExplanation
            ) {
            case .copy:
                return .managed(try await store.prepareManagedSource(
                    from: originalURL,
                    for: project,
                    transferMode: .copy
                ))
            case .link:
                return .linked
            case .cancel:
                return .canceled
            }
        }
    }

    private func relocateShotAudioMediaPaths(
        _ pathsByMediaId: [String: String],
        project: ProjectRecord
    ) {
        guard !pathsByMediaId.isEmpty else { return }
        var document = shotTimeline
        var changed = false
        let now = DateFormats.now()
        for shotIndex in document.shots.indices {
            var shotChanged = false
            for laneIndex in document.shots[shotIndex].audioMix.lanes.indices {
                let mediaId = document.shots[shotIndex].audioMix.lanes[laneIndex].clipMediaId ?? ""
                guard let path = pathsByMediaId[mediaId] else { continue }
                document.shots[shotIndex].audioMix.lanes[laneIndex].clipPath = path
                shotChanged = true
            }
            for regionIndex in document.shots[shotIndex].audioRegions.indices {
                let mediaId = document.shots[shotIndex].audioRegions[regionIndex].mediaId
                guard let path = pathsByMediaId[mediaId] else { continue }
                document.shots[shotIndex].audioRegions[regionIndex].path = path
                shotChanged = true
            }
            if shotChanged {
                document.shots[shotIndex].updatedAt = now
                changed = true
            }
        }
        guard changed else { return }
        document.updatedAt = now
        persistShotTimeline(document, for: project)
    }

    private func mediaCachePaths(for item: MediaItemRecord) -> [String] {
        [item.thumbnailPath, item.videoStripPath ?? ""]
            .map(\.trimmed)
            .filter { !$0.isEmpty }
    }

    private func discardUnpersistedCachePaths(_ paths: Set<String>) {
        for path in paths where FileManager.default.fileExists(atPath: path) {
            try? FileManager.default.removeItem(atPath: path)
        }
    }

    /// Where an image-file import reports its status: the Goal chat's line or
    /// the general aesthetic line (Frame Creator uploads).
    enum MediaImportStatusTarget {
        case goal
        case aesthetic
        case character
    }

    private func importGoalChatImageFiles(
        _ urls: [URL],
        project: ProjectRecord,
        statusTarget: MediaImportStatusTarget = .goal
    ) async -> [MediaItemRecord] {
        func report(_ message: String) {
            switch statusTarget {
            case .goal: goalStatus = message
            case .aesthetic: aestheticStatus = message
            case .character: characterChatStatus = message
            }
        }
        let imageURLs = urls.filter { url in
            guard let type = UTType(filenameExtension: url.pathExtension) else { return false }
            return type.conforms(to: .image)
        }
        guard !imageURLs.isEmpty else {
            report("Paste or upload image files")
            return []
        }

        do {
            let existingByPath = Dictionary(grouping: items, by: { URL(fileURLWithPath: $0.path).standardizedFileURL.path })
            var attachedItems: [MediaItemRecord] = []
            var updatedSources = sources
            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            var sourceChanged = false

            for url in imageURLs {
                let standardizedURL = url.standardizedFileURL
                let path = standardizedURL.path
                if let existing = existingByPath[path]?.first(where: { $0.kind == .image }) {
                    attachedItems.append(existing)
                    continue
                }

                let source = store.makeSource(from: standardizedURL, kind: .file)
                let scanResult = await store.scan(source: source, for: project) { [weak self] progress in
                    guard let self else { return }
                    if progress.isScanning {
                        switch statusTarget {
                        case .goal:
                            self.goalStatus = "Attaching \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
                        case .aesthetic:
                            self.aestheticStatus = "Importing \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
                        case .character:
                            self.characterChatStatus = "Attaching \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
                        }
                    }
                }
                updatedSources.removeAll { $0.sourceId == scanResult.source.sourceId || $0.path == scanResult.source.path }
                updatedSources.append(scanResult.source)
                sourceChanged = true

                for item in scanResult.items where item.kind == .image && item.scanError == nil {
                    updatedItemsById[item.mediaId] = item
                    attachedItems.append(item)
                }
            }

            let refreshedItems = sortedMediaItems(Array(updatedItemsById.values))
            if sourceChanged {
                try store.saveSources(updatedSources, for: project)
                sources = updatedSources
            }
            try store.saveInventory(refreshedItems, for: project)
            items = refreshedItems
            if attachedItems.isEmpty {
                report("No image attachments added")
            } else {
                report("Attached \(attachedItems.count) image\(attachedItems.count == 1 ? "" : "s")")
                touchCurrentProject()
            }
            return attachedItems
        } catch {
            lastError = error.localizedDescription
            report("Could not attach image")
            return []
        }
    }

    private func goalChatAttachmentMediaId(project: ProjectRecord, sha256: String) -> String {
        "goalchat_\(shortHash("\(project.projectId):\(sha256)", length: 20))"
    }

    private func startScreenAreaRecording(selection: ScreenAreaSelection, project: ProjectRecord) async {
        guard currentProject?.projectId == project.projectId else {
            resetScreenAreaRecordingState()
            return
        }

        do {
            screenAreaRecordingPhase = .starting
            screenAreaRecordingStatus = "Starting screen recording"
            scanStatus = "Starting screen recording"
            let outputDirectory = store.screenRecordingsDirectory(for: project)
            try ensureDirectory(outputDirectory)
            let outputURL = outputDirectory.appendingPathComponent("\(screenRecordingFilename()).mp4")
            try await screenAreaRecorder.startRecording(selection: selection, outputURL: outputURL)
            guard currentProject?.projectId == project.projectId else {
                await screenAreaRecorder.cancelRecording()
                resetScreenAreaRecordingState()
                return
            }
            screenAreaRecordingStartedAt = Date()
            screenAreaRecordingPhase = .recording
            screenAreaRecordingStatus = "Recording screen area"
            scanStatus = "Recording screen area"
            screenAreaAutoStopTask?.cancel()
            screenAreaAutoStopTask = Task { [weak self] in
                try? await Task.sleep(nanoseconds: 600_000_000_000)
                self?.stopScreenAreaRecording()
            }
        } catch {
            failScreenAreaRecording(error)
        }
    }

    private func importScreenAreaRecording(_ result: ScreenAreaRecordingResult) async {
        guard let project = currentProject else {
            failScreenAreaRecording(ScreenGraphError.capture("Create or select a project first."))
            return
        }

        isScanning = true
        screenAreaRecordingPhase = .finalizing
        screenAreaRecordingStatus = "Indexing screen recording"
        scanStatus = "Indexing screen recording"

        let source = store.makeSource(from: result.url, kind: .file, storageMode: .managed)
        let scanResult = await store.scan(source: source, for: project) { [weak self] progress in
            guard let self else { return }
            if progress.isScanning {
                self.scanStatus = "Indexing \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
            } else {
                self.scanStatus = "Finished \(source.displayName)"
            }
        }

        do {
            guard let recordedItem = scanResult.items.first(where: { $0.kind == .video }) else {
                throw ScreenGraphError.capture("The screen recording could not be indexed as a video.")
            }

            var updatedSources = sources.filter { existing in
                existing.sourceId != scanResult.source.sourceId && existing.path != scanResult.source.path
            }
            updatedSources.append(scanResult.source)

            let existingItems = items.filter { item in
                item.sourceId != scanResult.source.sourceId
            }
            let refreshedItems = sortedMediaItems(deduplicatedMediaItems(existingItems + scanResult.items))

            try store.saveSources(updatedSources, for: project)
            try store.saveInventory(refreshedItems, for: project)

            sources = updatedSources
            items = refreshedItems
            selectedItemId = recordedItem.mediaId
            isScanning = false
            screenAreaRecordingPhase = .idle
            screenAreaRecordingStartedAt = nil
            let duration = result.durationSeconds > 0 ? " \(durationLabel(result.durationSeconds))" : ""
            screenAreaRecordingStatus = "Added screen recording\(duration)"
            scanStatus = "Added screen recording to Media"
            touchCurrentProject()
        } catch {
            isScanning = false
            failScreenAreaRecording(error)
        }
    }

    private func importCameraRecording(_ result: CameraRecordingResult, expectedProjectId: String?) async {
        guard let project = currentProject else {
            failCameraRecording(ScreenGraphError.capture("Create or select a project first."))
            return
        }
        guard expectedProjectId == nil || project.projectId == expectedProjectId else {
            cameraRecordingProjectId = nil
            isScanning = false
            cameraRecordingPhase = .failed
            cameraRecordingStartedAt = nil
            cameraRecordingStatus = "Camera recording was saved, but the active project changed before import. Return to the original project and add the saved file if needed."
            scanStatus = "Camera recording not imported"
            return
        }

        isScanning = true
        cameraRecordingPhase = .finalizing
        cameraRecordingStatus = "Indexing camera recording"
        scanStatus = "Indexing camera recording"

        let source = store.makeSource(from: result.url, kind: .file, storageMode: .managed)
        let scanResult = await store.scan(source: source, for: project) { [weak self] progress in
            guard let self else { return }
            if progress.isScanning {
                self.scanStatus = "Indexing \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
            } else {
                self.scanStatus = "Finished \(source.displayName)"
            }
        }

        do {
            guard let recordedItem = scanResult.items.first(where: { $0.kind == .video }) else {
                throw ScreenGraphError.capture("The camera recording could not be indexed as a video.")
            }

            var updatedSources = sources.filter { existing in
                existing.sourceId != scanResult.source.sourceId && existing.path != scanResult.source.path
            }
            updatedSources.append(scanResult.source)

            let existingItems = items.filter { item in
                item.sourceId != scanResult.source.sourceId
            }
            let refreshedItems = sortedMediaItems(deduplicatedMediaItems(existingItems + scanResult.items))

            try store.saveSources(updatedSources, for: project)
            try store.saveInventory(refreshedItems, for: project)

            sources = updatedSources
            items = refreshedItems
            selectedItemId = recordedItem.mediaId

            var finalStatus = "Added camera recording"
            if result.settings.captureFrames {
                do {
                    let frameCount = try await importCameraFrames(
                        from: recordedItem,
                        source: scanResult.source,
                        project: project,
                        settings: result.settings
                    )
                    finalStatus = "Added camera recording and \(frameCount) disabled still\(frameCount == 1 ? "" : "s")"
                } catch {
                    guard currentProject?.projectId == project.projectId else { return }
                    lastError = error.localizedDescription
                    finalStatus = "Added camera recording; still capture failed"
                    frameExtractionByVideoId[recordedItem.mediaId] = VideoFrameExtractionState(
                        isExtracting: false,
                        completedCount: 0,
                        totalCount: 0,
                        status: "Frame capture failed",
                        errorMessage: error.localizedDescription
                    )
                }
            }

            guard currentProject?.projectId == project.projectId else { return }
            isScanning = false
            cameraRecordingPhase = .ready
            cameraRecordingProjectId = nil
            cameraRecordingStartedAt = nil
            cameraRecordingStatus = finalStatus
            scanStatus = finalStatus
            touchCurrentProject()
        } catch {
            cameraRecordingProjectId = nil
            isScanning = false
            failCameraRecording(error)
        }
    }

    private func importCameraFrames(
        from video: MediaItemRecord,
        source: MediaSourceRecord,
        project: ProjectRecord,
        settings: CameraRecordingSettings
    ) async throws -> Int {
        cameraRecordingStatus = "Saving still frames"
        scanStatus = "Saving camera still frames"
        let frames = try await store.extractFramesAtRate(
            from: video,
            source: source,
            for: project,
            framesPerSecond: settings.framesPerSecond,
            capSeconds: settings.frameCapSeconds,
            maxFrames: 300
        ) { [weak self] progress in
            guard let self, self.currentProject?.projectId == project.projectId else { return }
            self.frameExtractionByVideoId[progress.videoMediaId] = VideoFrameExtractionState(
                isExtracting: progress.isExtracting,
                completedCount: progress.completedCount,
                totalCount: progress.totalCount,
                status: progress.status
            )
            if progress.isExtracting {
                self.cameraRecordingStatus = "Saving still frames \(progress.completedCount)/\(progress.totalCount)"
                self.scanStatus = "Saving camera still frames \(progress.completedCount)/\(progress.totalCount)"
            }
        }
        guard currentProject?.projectId == project.projectId else { return 0 }

        var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
        for frame in frames {
            updatedItemsById[frame.mediaId] = frame
        }
        let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
        try store.saveInventory(updatedItems, for: project)

        var updatedCuration = curationById
        for frame in frames {
            updatedCuration[frame.mediaId] = MediaCurationRecord(mediaId: frame.mediaId, rejected: true)
        }
        try store.saveCuration(updatedCuration, for: project)

        items = updatedItems
        curationById = updatedCuration
        frameExtractionByVideoId[video.mediaId] = VideoFrameExtractionState(
            isExtracting: false,
            completedCount: frames.count,
            totalCount: frames.count,
            status: "Frames ready"
        )
        return frames.count
    }

    private func cancelScreenAreaRecordingSelection() {
        resetScreenAreaRecordingState()
        scanStatus = items.isEmpty ? "Add media or rescan" : "\(items.count) media item\(items.count == 1 ? "" : "s") indexed"
    }

    private func failScreenAreaRecording(_ error: Error) {
        if isScreenRecordingPermissionError(error) {
            presentScreenRecordingPermissionRequired()
            return
        }
        screenAreaAutoStopTask?.cancel()
        screenAreaAutoStopTask = nil
        isScanning = false
        screenAreaRecordingPhase = .failed
        screenAreaRecordingStartedAt = nil
        screenAreaRecordingStatus = error.localizedDescription
        scanStatus = "Screen recording failed"
        lastError = error.localizedDescription
    }

    private func failCameraRecording(_ error: Error) {
        isScanning = false
        cameraRecordingPhase = .failed
        cameraRecordingProjectId = nil
        cameraRecordingStartedAt = nil
        cameraRecordingStatus = error.localizedDescription
        scanStatus = "Camera recording failed"
        lastError = error.localizedDescription
    }

    private func refreshCameraDevices() {
        cameraVideoDevices = CameraRecorder.videoDevices()
        cameraAudioDevices = CameraRecorder.audioDevices()
        if cameraSelectedVideoDeviceId.isEmpty || !cameraVideoDevices.contains(where: { $0.id == cameraSelectedVideoDeviceId }) {
            cameraSelectedVideoDeviceId = cameraVideoDevices.first?.id ?? ""
        }
        if cameraSelectedAudioDeviceId.isEmpty || !cameraAudioDevices.contains(where: { $0.id == cameraSelectedAudioDeviceId }) {
            cameraSelectedAudioDeviceId = CaptureAudioInputPreference.resolvedDeviceId(in: cameraAudioDevices)
        }
    }

    private func currentCameraRecordingSettings() -> CameraRecordingSettings {
        CameraRecordingSettings(
            videoDeviceId: cameraSelectedVideoDeviceId,
            audioDeviceId: cameraSelectedAudioDeviceId,
            includeMicrophone: cameraIncludeMicrophone,
            captureFrames: cameraCaptureFrames,
            framesPerSecond: min(max(cameraFrameRate, 1), 10),
            frameCapSeconds: min(max(cameraFrameCapSeconds, 1), 30)
        )
    }

    private func resetCameraRecordingState() {
        cameraRecorder.stopPreview()
        cameraRecordingPhase = .idle
        cameraRecordingProjectId = nil
        cameraRecordingStatus = ""
        cameraRecordingStartedAt = nil
        cameraPreviewSession = nil
    }

    private func cameraRecordingFilename() -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd'T'HHmmss"
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        return "camera_recording_\(formatter.string(from: Date()))_\(UUID().uuidString.prefix(8).lowercased())"
    }

    private func requestScreenRecordingPermissionIfNeeded() -> Bool {
        if CGPreflightScreenCaptureAccess() {
            return true
        }

        let granted = CGRequestScreenCaptureAccess()
        if granted {
            return true
        }

        presentScreenRecordingPermissionRequired()
        return false
    }

    private func presentScreenRecordingPermissionRequired() {
        screenAreaAutoStopTask?.cancel()
        screenAreaAutoStopTask = nil
        isScanning = false
        screenAreaRecordingPhase = .needsPermission
        screenAreaRecordingStartedAt = nil
        screenAreaRecordingStatus = "macOS has not granted Screen Recording to this running copy of LitScenes. Turn LitScenes on in System Settings, then quit and reopen the app. If it is already on, quit and reopen; if it still fails, remove stale duplicate LitScenes entries and add the current app again."
        scanStatus = "Screen Recording permission required"
        lastError = ""
    }

    private func isScreenRecordingPermissionError(_ error: Error) -> Bool {
        let text = error.localizedDescription.lowercased()
        return text.contains("tcc")
            || text.contains("declined")
            || text.contains("not authorized")
            || text.contains("privacy")
            || text.contains("screen recording")
            || text.contains("screen capture")
    }

    private func resetScreenAreaRecordingState() {
        screenAreaAutoStopTask?.cancel()
        screenAreaAutoStopTask = nil
        screenAreaRecordingPhase = .idle
        screenAreaRecordingStatus = ""
        screenAreaRecordingStartedAt = nil
    }

    private func screenRecordingFilename() -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd'T'HHmmss"
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        return "screen_recording_\(formatter.string(from: Date()))_\(UUID().uuidString.prefix(8).lowercased())"
    }

    private var goalStyleRefsAuthoringAttempts: Set<String> = []
    private var goalCastArticulationAttempts: Set<String> = []
    private var goalCastArticulationTask: Task<Void, Never>?
    private var initialStoryGenerationTask: Task<Void, Never>?

    private func goalBriefV2StyleSummary(_ brief: ProjectGoalBriefV2) -> String {
        var lines: [String] = []
        if let contentType = brief.contentType {
            lines.append("- content_type: \(contentType.rawValue)")
        }
        if !brief.goal.trimmed.isEmpty {
            lines.append("- goal: \(brief.goal)")
        }
        if !brief.audience.trimmed.isEmpty {
            lines.append("- audience: \(brief.audience)")
        }
        if !brief.desiredResponse.trimmed.isEmpty {
            lines.append("- desired_response: \(brief.desiredResponse)")
        }
        if !brief.viewerExperience.trimmed.isEmpty {
            lines.append("- viewer_experience: \(brief.viewerExperience)")
        }
        if !brief.moodboardArticulation.trimmed.isEmpty {
            lines.append("- moodboard_articulation: \(brief.moodboardArticulation)")
        }
        if !brief.successCriteria.isEmpty {
            lines.append("- success_criteria: \(brief.successCriteria.joined(separator: "; "))")
        }
        if !brief.constraints.isEmpty {
            lines.append("- constraints: \(brief.constraints.joined(separator: "; "))")
        }
        if !brief.lensSeedSummary.trimmed.isEmpty {
            lines.append("- lens_seed_summary: \(brief.lensSeedSummary)")
        }
        if !brief.lensSeedTerms.isEmpty {
            lines.append("- lens_seed_terms: \(brief.lensSeedTerms.joined(separator: ", "))")
        }
        let meaningNames = brief.meaningNodeRefs.map(\.name).filter { !$0.trimmed.isEmpty }
        if !meaningNames.isEmpty {
            lines.append("- meaning_refs: \(meaningNames.joined(separator: ", "))")
        }
        return lines.joined(separator: "\n")
    }

    /// Authors LLM style-taxonomy refs for the active Goal when it has none, committing a new
    /// Goal version on success (which re-queues Frame Context retrieval with the refs included).
    /// Returns true when a new version was committed.
    @discardableResult
    private func ensureGoalStyleTaxonomyRefs() async -> Bool {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion,
              version.brief.isReady,
              version.brief.styleTermRefs.isEmpty else {
            return false
        }
        let attemptKey = "\(project.projectId):\(version.versionId)"
        guard !goalStyleRefsAuthoringAttempts.contains(attemptKey) else {
            return false
        }
        goalStyleRefsAuthoringAttempts.insert(attemptKey)
        do {
            let catalog = try await StyleBrowseCatalogRuntime.shared.loadCatalog()
            guard catalog.isUsable else {
                print("[goal_style_refs] skipped: style browse catalog unavailable")
                return false
            }
            var moods: Set<String> = []
            var hues: Set<String> = []
            var mediums: Set<String> = []
            for style in catalog.styles {
                moods.formUnion(style.moods)
                if !style.hueName.trimmed.isEmpty {
                    hues.insert(style.hueName)
                }
                if !style.medium.trimmed.isEmpty {
                    mediums.insert(style.medium)
                }
            }
            let client = try OpenAIClient.fromEnvironment()
            let result = try await client.authorGoalStyleTaxonomyRefs(
                context: GoalStyleTaxonomyRefsContext(
                    projectId: project.projectId,
                    goalSummary: goalBriefV2StyleSummary(version.brief),
                    moods: moods.sorted(),
                    hues: hues.sorted(),
                    collections: catalog.displayCollections,
                    mediums: mediums.sorted()
                )
            )
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId,
                  projectGoalV2.activeVersion?.versionId == version.versionId else {
                return false
            }
            guard !result.refs.isEmpty else {
                print("[goal_style_refs] model returned no refs project_id=\(project.projectId)")
                return false
            }
            var brief = version.brief
            brief.styleTermRefs = result.refs
            print("[goal_style_refs] authored count=\(result.refs.count) project_id=\(project.projectId) goal_version_id=\(version.versionId)")
            return commitGoalV2Brief(
                brief,
                changeSummary: "Mapped the Goal onto the style taxonomy.",
                model: result.model
            )
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return false
            }
            print("[goal_style_refs] failed: \(error.localizedDescription)")
            return false
        }
    }

    // MARK: - Goal cast

    /// One-line story-identity gist for a roster character linked to a goal-cast member
    /// (by characterId, else case-insensitive name). nil keeps composition roster lines
    /// byte-identical to the pre-cast format.
    func goalCastIdentityGist(forCharacter character: ProjectCharacter) -> String? {
        goalCastMember(forCharacterId: character.characterId, name: character.name)?.activeIdentity.gist
    }

    /// Roster-side lookup for the STORY IDENTITY mirror.
    func goalCastMember(forCharacterId characterId: String, name: String) -> GoalCastMember? {
        let byId = goalCast.members.first { !$0.characterId.isEmpty && $0.characterId == characterId }
        return byId ?? goalCast.member(named: name)
    }

    /// Story Input photos that show people, newest first, capped — the evidence
    /// the media-first casting law anchors to.
    private func goalCastPeoplePhotoEntries(limit: Int = 8) -> [(mediaId: String, observation: ImageObservationResult)] {
        Array(
            enabledContentItems
                .filter { $0.kind == .image }
                .compactMap { item -> (mediaId: String, observation: ImageObservationResult)? in
                    guard let observation = mediaObservationsById[item.mediaId], observation.peopleVisible else { return nil }
                    return (item.mediaId, observation)
                }
                .prefix(limit)
        )
    }

    private func goalCastArticulationContext(
        project: ProjectRecord,
        brief: ProjectGoalBriefV2,
        desiredCount: Int?,
        excludeNames: [String],
        peoplePhotoLines: [String] = []
    ) -> GoalCastArticulationContext {
        GoalCastArticulationContext(
            projectId: project.projectId,
            goalSummary: goalBriefV2StyleSummary(brief),
            requiredEntityLines: brief.requiredEntities.map { entity in
                var line = "- \(entity.name)"
                if !entity.role.isEmpty { line += " (\(entity.role))" }
                return line + " [required]"
            },
            rosterCharacterLines: projectCharacters.characters.map { character in
                character.descriptionPrompt.isEmpty
                    ? "- \(character.name)"
                    : "- \(character.name) — \(character.descriptionPrompt)"
            },
            existingMemberSummaries: goalCast.members.map(\.contextSummaryLine),
            excludeNames: excludeNames,
            desiredCount: desiredCount,
            peoplePhotoLines: peoplePhotoLines,
            castCap: GoalCastDocument.automaticCastCap
        )
    }

    private func mintedGoalCastMember(name: String, brief: ProjectGoalBriefV2, projectId: String, now: String) -> GoalCastMember {
        GoalCastMember(
            memberId: "castmember_\(shortHash("\(projectId):\(name):\(now)", length: 12))",
            name: name,
            roleLabel: brief.requiredEntities.first { $0.name.trimmed.lowercased() == name.lowercased() }?.role ?? "",
            updatedAt: now
        )
    }

    /// Articulates the initial ensemble once per project (auto, in the background, at the
    /// same hook as the style-taxonomy mapping). Gate is articulatedAt, not members.isEmpty:
    /// chat may add members before first articulation, and articulation completes the
    /// ensemble around them via excludeNames.
    func ensureGoalCastArticulation() async {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion,
              version.brief.isReady,
              goalCast.articulatedAt.isEmpty,
              !isArticulatingGoalCast else {
            return
        }
        let attemptKey = "\(project.projectId):\(version.versionId)"
        guard !goalCastArticulationAttempts.contains(attemptKey) else { return }
        goalCastArticulationAttempts.insert(attemptKey)
        isArticulatingGoalCast = true
        defer { isArticulatingGoalCast = false }
        // MEDIA FIRST needs the photos observed: wait (bounded) for a running
        // analysis pass, or the model invents people the photos already show.
        var waitedSeconds = 0
        while isAnalyzingMedia, waitedSeconds < 90 {
            try? await Task.sleep(nanoseconds: 1_000_000_000)
            waitedSeconds += 1
        }
        guard currentProject?.projectId == project.projectId, goalCast.articulatedAt.isEmpty else { return }
        do {
            let client = try OpenAIClient.fromEnvironment()
            let photoEntries = goalCastPeoplePhotoEntries()
            let photoIds = photoEntries.map(\.mediaId)
            let context = goalCastArticulationContext(
                project: project,
                brief: version.brief,
                desiredCount: nil,
                excludeNames: goalCast.members.map(\.name),
                peoplePhotoLines: goalCastPeoplePhotoLines(photoEntries)
            )
            let visionInputs = (try? goalVisionInputs(mediaIds: Array(photoIds.prefix(4)), limit: 4)) ?? []
            let result = try await client.articulateGoalCast(context: context, visionInputs: visionInputs)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            var document = goalCast
            document.projectId = project.projectId
            let now = DateFormats.now()
            var syncIds: [String] = []
            var referenceIdsByMemberId: [String: [String]] = [:]
            // New members lead the STORY cast list; the ensemble keeps its own order.
            var newMembers: [GoalCastMember] = []
            var unanchored: [GoalCastArticulatedMember] = []
            // THE CAST CAP: automatic casting stops at two members in total.
            let budget = max(0, GoalCastDocument.automaticCastCap - document.members.count)
            let knownImageMediaIds = Set(items.filter { $0.kind == .image }.map(\.mediaId))
            func mint(_ emitted: GoalCastArticulatedMember, refs: [String]) {
                var member = mintedGoalCastMember(name: emitted.name.trimmed, brief: version.brief, projectId: project.projectId, now: now)
                member.appendTake(GoalCastTake.minted(origin: "initial", identity: emitted.identity, now: now), now: now)
                newMembers.append(member)
                syncIds.append(member.memberId)
                if !refs.isEmpty { referenceIdsByMemberId[member.memberId] = refs }
            }
            // Valid emitted members with their sanitized photos, then THE
            // ONE-PHOTO-ONE-CHARACTER LAW before anything is minted.
            var candidates: [(emitted: GoalCastArticulatedMember, refs: [String])] = []
            for emitted in result.members {
                let name = emitted.name.trimmed
                guard !name.isEmpty,
                      document.member(named: name) == nil,
                      candidates.contains(where: { $0.emitted.name.trimmed.lowercased() == name.lowercased() }) == false else { continue }
                candidates.append((emitted, sanitizedGoalCastReferenceMediaIds(emitted.referenceMediaIds, knownImageMediaIds: knownImageMediaIds)))
            }
            let allocated = allocatedGoalCastReferenceMediaIds(
                candidates.map(\.refs),
                alreadyClaimed: claimedSourceMediaIds(excludingCharacterId: "")
            )
            for (index, candidate) in candidates.enumerated() {
                guard newMembers.count < budget else { break }
                let refs = allocated[index]
                if !photoIds.isEmpty, refs.isEmpty {
                    // MEDIA FIRST: with people photos on file, an unanchored member is an invention.
                    unanchored.append(candidate.emitted)
                    continue
                }
                mint(candidate.emitted, refs: refs)
            }
            if newMembers.isEmpty, budget > 0, let first = unanchored.first {
                // The model anchored nobody: a cast beats an empty, never-retried articulation.
                print("[goal_cast] no member anchored to a people photo — keeping the first unanchored member project_id=\(project.projectId)")
                mint(first, refs: [])
            }
            document.members.insert(contentsOf: newMembers, at: 0)
            document.articulatedAt = now
            document.goalVersionId = version.versionId
            syncGoalCastMembersToRoster(syncIds, in: &document, for: project, referenceMediaIdsByMemberId: referenceIdsByMemberId)
            let status = syncIds.isEmpty
                ? (result.castingNote.isEmpty ? "No cast articulated." : "No cast needed: \(result.castingNote)")
                : "Articulated \(syncIds.count) cast member\(syncIds.count == 1 ? "" : "s")."
            saveGoalCast(document, for: project, status: status)
            print("[goal_cast] articulated count=\(syncIds.count) project_id=\(project.projectId) goal_version_id=\(version.versionId)")
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) { return }
            print("[goal_cast] articulation failed: \(error.localizedDescription)")
            guard currentProject?.projectId == project.projectId else { return }
            goalCastStatus = "Cast articulation failed — Re-articulate to retry"
        }
    }

    /// Explicit re-articulation from the current Goal. Name-matched members receive a
    /// merged take (pins survive structurally; allowed = everything not pinned), new
    /// names join the cast, and members absent from the response are KEPT — removal
    /// stays a user decision.
    func rearticulateGoalCast() async {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion,
              version.brief.isReady,
              !isArticulatingGoalCast else {
            return
        }
        isArticulatingGoalCast = true
        defer { isArticulatingGoalCast = false }
        do {
            let client = try OpenAIClient.fromEnvironment()
            let photoEntries = goalCastPeoplePhotoEntries()
            let context = goalCastArticulationContext(
                project: project,
                brief: version.brief,
                desiredCount: nil,
                excludeNames: [],
                peoplePhotoLines: goalCastPeoplePhotoLines(photoEntries)
            )
            let visionInputs = (try? goalVisionInputs(mediaIds: Array(photoEntries.map(\.mediaId).prefix(4)), limit: 4)) ?? []
            let result = try await client.articulateGoalCast(context: context, visionInputs: visionInputs)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            var document = goalCast
            document.projectId = project.projectId
            let now = DateFormats.now()
            var syncIds: [String] = []
            var referenceIdsByMemberId: [String: [String]] = [:]
            let allDimensions = Set(GoalCastDimension.allCases)
            // THE CAST CAP governs additions; name-matched merges cannot grow the cast.
            let additionBudget = max(0, GoalCastDocument.automaticCastCap - document.members.count)
            var additions = 0
            let knownImageMediaIds = Set(items.filter { $0.kind == .image }.map(\.mediaId))
            for emitted in result.members {
                let name = emitted.name.trimmed
                guard !name.isEmpty else { continue }
                if let index = document.members.firstIndex(where: { $0.name.trimmed.lowercased() == name.lowercased() }) {
                    var member = document.members[index]
                    let merged = mergedGoalCastIdentity(
                        prior: member.activeIdentity,
                        emitted: emitted.identity,
                        allowed: allDimensions,
                        pinned: member.pinnedDimensionSet
                    )
                    guard merged != member.activeIdentity else { continue }
                    member.appendTake(GoalCastTake.minted(origin: "re-articulated", identity: merged, now: now), now: now)
                    document.members[index] = member
                    syncIds.append(member.memberId)
                } else if additions < additionBudget {
                    var member = mintedGoalCastMember(name: name, brief: version.brief, projectId: project.projectId, now: now)
                    member.appendTake(GoalCastTake.minted(origin: "initial", identity: emitted.identity, now: now), now: now)
                    // Newest first in the STORY cast list.
                    document.members.insert(member, at: 0)
                    syncIds.append(member.memberId)
                    additions += 1
                    let refs = sanitizedGoalCastReferenceMediaIds(emitted.referenceMediaIds, knownImageMediaIds: knownImageMediaIds)
                    if !refs.isEmpty { referenceIdsByMemberId[member.memberId] = refs }
                }
            }
            document.articulatedAt = now
            document.goalVersionId = version.versionId
            // THE ONE-PHOTO-ONE-CHARACTER LAW across the new members and the roster.
            let newMemberIds = referenceIdsByMemberId.keys.sorted()
            let allocated = allocatedGoalCastReferenceMediaIds(
                newMemberIds.map { referenceIdsByMemberId[$0] ?? [] },
                alreadyClaimed: claimedSourceMediaIds(excludingCharacterId: "")
            )
            referenceIdsByMemberId = Dictionary(uniqueKeysWithValues: zip(newMemberIds, allocated).filter { !$0.1.isEmpty })
            syncGoalCastMembersToRoster(syncIds, in: &document, for: project, referenceMediaIdsByMemberId: referenceIdsByMemberId)
            saveGoalCast(document, for: project, status: result.castingNote.isEmpty ? "Re-articulated the cast." : result.castingNote)
            print("[goal_cast] re-articulated changed=\(syncIds.count) project_id=\(project.projectId)")
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) { return }
            guard currentProject?.projectId == project.projectId else { return }
            goalCastStatus = "Re-articulation failed — try again"
            print("[goal_cast] re-articulation failed: \(error.localizedDescription)")
        }
    }

    /// "+ Add" — asks for exactly one new member beyond the current names.
    func addGoalCastMember() async {
        guard let project = currentProject,
              let version = projectGoalV2.activeVersion,
              version.brief.isReady,
              !isArticulatingGoalCast,
              goalCast.members.count < GoalCastDocument.maximumMembers else {
            return
        }
        isArticulatingGoalCast = true
        defer { isArticulatingGoalCast = false }
        do {
            let client = try OpenAIClient.fromEnvironment()
            let photoEntries = goalCastPeoplePhotoEntries()
            let context = goalCastArticulationContext(
                project: project,
                brief: version.brief,
                desiredCount: 1,
                excludeNames: goalCast.members.map(\.name),
                peoplePhotoLines: goalCastPeoplePhotoLines(photoEntries)
            )
            let visionInputs = (try? goalVisionInputs(mediaIds: Array(photoEntries.map(\.mediaId).prefix(4)), limit: 4)) ?? []
            let result = try await client.articulateGoalCast(context: context, visionInputs: visionInputs)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            guard let emitted = result.members.first, !emitted.name.trimmed.isEmpty else {
                goalCastStatus = "The model returned no new character — try again"
                return
            }
            let name = emitted.name.trimmed
            guard goalCast.member(named: name) == nil else {
                goalCastStatus = "Model returned an existing character — try again"
                return
            }
            var document = goalCast
            document.projectId = project.projectId
            let now = DateFormats.now()
            var member = mintedGoalCastMember(name: name, brief: version.brief, projectId: project.projectId, now: now)
            member.appendTake(GoalCastTake.minted(origin: "initial", identity: emitted.identity, now: now), now: now)
            // Newest first in the STORY cast list.
            document.members.insert(member, at: 0)
            let refs = allocatedGoalCastReferenceMediaIds(
                [sanitizedGoalCastReferenceMediaIds(
                    emitted.referenceMediaIds,
                    knownImageMediaIds: Set(items.filter { $0.kind == .image }.map(\.mediaId))
                )],
                alreadyClaimed: claimedSourceMediaIds(excludingCharacterId: "")
            ).first ?? []
            syncGoalCastMembersToRoster(
                [member.memberId],
                in: &document,
                for: project,
                referenceMediaIdsByMemberId: refs.isEmpty ? [:] : [member.memberId: refs]
            )
            saveGoalCast(document, for: project, status: "Added \(name) to the cast.")
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) { return }
            guard currentProject?.projectId == project.projectId else { return }
            goalCastStatus = "Add character failed — try again"
            print("[goal_cast] add failed: \(error.localizedDescription)")
        }
    }

    /// One steer gesture = one new take, built by the field-wise merge so the model can
    /// only touch the gesture's allowed dimensions (feedback: its changed_fields minus
    /// pins). Per-member in-flight state keeps the other cards interactive.
    func steerGoalCastMember(memberId: String, gesture: GoalCastSteerGesture) async {
        guard let project = currentProject,
              let member = goalCast.member(withId: memberId),
              !steeringGoalCastMemberIds.contains(memberId) else {
            return
        }
        if case .tamer = gesture, member.activeIdentity.strangeness <= 0.0001 {
            goalCastStatus = "\(member.name) is already plain"
            return
        }
        if case .feedback(let text) = gesture, text.trimmed.isEmpty { return }
        steeringGoalCastMemberIds.insert(memberId)
        defer { steeringGoalCastMemberIds.remove(memberId) }
        do {
            let client = try OpenAIClient.fromEnvironment()
            let identityJSON = String(
                data: try JSONCoding.encoder.encode(member.activeIdentity),
                encoding: .utf8
            ) ?? ""
            let rosterAppearance = projectCharacters.characters.first {
                (!member.characterId.isEmpty && $0.characterId == member.characterId)
                    || $0.name.trimmed.lowercased() == member.name.trimmed.lowercased()
            }?.descriptionPrompt ?? ""
            var feedbackText = ""
            if case .feedback(let text) = gesture { feedbackText = text.trimmed }
            let context = GoalCastSteerContext(
                projectId: project.projectId,
                goalSummary: projectGoalV2.activeVersion.map { goalBriefV2StyleSummary($0.brief) } ?? "",
                memberName: member.name,
                currentIdentityJSON: identityJSON,
                priorTakeEssences: member.takes.dropLast().suffix(4).map(\.identity.essence).filter { !$0.isEmpty },
                gesture: gesture.promptKeyword,
                feedbackText: feedbackText,
                pinnedDimensions: member.pinnedDimensions,
                rosterAppearanceLine: rosterAppearance
            )
            let result = try await client.steerGoalCastMember(context: context)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            // Re-fetch — the member may have been removed mid-flight.
            guard let index = goalCast.members.firstIndex(where: { $0.memberId == memberId }),
                  let emitted = result.members.first else {
                return
            }
            var document = goalCast
            var current = document.members[index]
            let pinned = current.pinnedDimensionSet
            let allowed = gesture.allowedDimensions ?? emitted.changedDimensions.subtracting(pinned)
            let merged = mergedGoalCastIdentity(
                prior: current.activeIdentity,
                emitted: emitted.identity,
                allowed: allowed,
                pinned: pinned
            )
            let now = DateFormats.now()
            current.appendTake(GoalCastTake.minted(origin: gesture.originLabel, identity: merged, now: now), now: now)
            document.members[index] = current
            syncGoalCastMembersToRoster([memberId], in: &document, for: project)
            saveGoalCast(document, for: project)
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) { return }
            guard currentProject?.projectId == project.projectId else { return }
            goalCastStatus = "Steer failed for \(member.name) — try again"
            print("[goal_cast] steer failed member=\(member.name): \(error.localizedDescription)")
        }
    }

    /// Non-destructive take flip; the activated take's identity syncs to the roster.
    func activateGoalCastTake(memberId: String, takeId: String) {
        guard let project = currentProject,
              let index = goalCast.members.firstIndex(where: { $0.memberId == memberId }),
              goalCast.members[index].takes.contains(where: { $0.takeId == takeId }),
              goalCast.members[index].activeTakeId != takeId else {
            return
        }
        var document = goalCast
        document.members[index].activeTakeId = takeId
        document.members[index].updatedAt = DateFormats.now()
        syncGoalCastMembersToRoster([memberId], in: &document, for: project)
        saveGoalCast(document, for: project)
    }

    /// Drops the member. The roster character is never deleted or modified — it may own
    /// reference media and renders; only the cast link ends here.
    func removeGoalCastMember(memberId: String) {
        guard let project = currentProject,
              let member = goalCast.member(withId: memberId) else { return }
        var document = goalCast
        document.members.removeAll { $0.memberId == memberId }
        saveGoalCast(document, for: project, status: "Removed \(member.name) from the cast — roster character kept.")
    }

    /// Pin/unpin one dimension as a keep-exactly constraint. No LLM call, no roster sync.
    func toggleGoalCastPin(memberId: String, dimension: GoalCastDimension) {
        guard let project = currentProject,
              let index = goalCast.members.firstIndex(where: { $0.memberId == memberId }) else { return }
        var document = goalCast
        var pins = document.members[index].pinnedDimensions
        if pins.contains(dimension.rawValue) {
            pins.removeAll { $0 == dimension.rawValue }
        } else {
            pins.append(dimension.rawValue)
        }
        document.members[index].pinnedDimensions = normalizedGoalCastPinKeys(pins)
        document.members[index].updatedAt = DateFormats.now()
        saveGoalCast(document, for: project)
    }

    /// Applies the interview's sanitized cast_updates delta as takes. Synchronous (no
    /// awaits) so the cast document persists before saveGoalV2 queues the refresh chain.
    private func applyChatCastUpdates(
        _ updates: [ProjectGoalCastUpdate],
        latestUserMessage: String,
        turnMediaIds: [String] = [],
        for project: ProjectRecord
    ) {
        guard !updates.isEmpty else { return }
        let sanitized = sanitizeGoalCastChatUpdates(
            updates,
            currentCast: goalCast,
            latestUserMessage: latestUserMessage,
            knownImageMediaIds: Set(items.filter { $0.kind == .image }.map(\.mediaId))
        )
        for warning in sanitized.warnings {
            print("[goal_cast_chat] \(warning)")
        }
        guard !sanitized.updates.isEmpty else {
            if let warning = sanitized.warnings.first {
                goalCastStatus = warning
            }
            return
        }
        let application = appliedGoalCastChatUpdates(document: goalCast, updates: sanitized.updates, now: DateFormats.now())
        for warning in application.warnings {
            print("[goal_cast_chat] \(warning)")
        }
        var document = application.document
        document.projectId = project.projectId
        // Media the turn tied to a character travels with the roster sync: the model's
        // listed ids first, the turn's own attachments for a brand-new character.
        var referenceMediaIdsByMemberId: [String: [String]] = [:]
        for update in sanitized.updates {
            let ids = castUpdateReferenceMediaIds(update: update, turnMediaIds: turnMediaIds)
            guard !ids.isEmpty, let member = document.member(named: update.targetName) else { continue }
            referenceMediaIdsByMemberId[member.memberId] = ids
        }
        syncGoalCastMembersToRoster(
            application.syncMemberIds,
            in: &document,
            for: project,
            referenceMediaIdsByMemberId: referenceMediaIdsByMemberId
        )
        let touched = sanitized.updates.map(\.targetName).joined(separator: ", ")
        saveGoalCast(document, for: project, status: "Chat updated the cast: \(touched)")
    }

    /// Writes each member's ACTIVE identity to its roster character — reuse by
    /// characterId, else case-insensitive name (lensCastMembersFromComposition
    /// semantics), else create — and stamps characterId back on the member. Mutates the
    /// passed document; the caller persists it. Fires only from explicit gestures and
    /// creation, never from background loads.
    private func syncGoalCastMembersToRoster(
        _ memberIds: [String],
        in document: inout GoalCastDocument,
        for project: ProjectRecord,
        referenceMediaIdsByMemberId: [String: [String]] = [:]
    ) {
        guard !memberIds.isEmpty else { return }
        let knownMediaIds = Set(items.map(\.mediaId))
        var roster = projectCharacters
        if roster.projectId.isEmpty { roster.projectId = project.projectId }
        let now = DateFormats.now()
        var syncedNames: [String] = []
        for memberId in memberIds {
            guard let index = document.members.firstIndex(where: { $0.memberId == memberId }) else { continue }
            var member = document.members[index]
            let identity = member.activeIdentity
            let characterIndex: Int
            if !member.characterId.isEmpty,
               let existing = roster.characters.firstIndex(where: { $0.characterId == member.characterId }) {
                characterIndex = existing
            } else if let existing = roster.characters.firstIndex(where: { $0.name.trimmed.lowercased() == member.name.trimmed.lowercased() }) {
                characterIndex = existing
            } else {
                let character = ProjectCharacter(
                    characterId: "character_\(shortHash("\(project.projectId):\(member.name):\(now)", length: 12))",
                    name: member.name,
                    updatedAt: now
                ).normalized()
                // Newest first, matching the STORY cast list the sync mirrors.
                roster.characters.insert(character, at: 0)
                characterIndex = 0
            }
            if !identity.visualDescription.isEmpty {
                roster.characters[characterIndex].descriptionPrompt = identity.visualDescription
            }
            if !identity.signature.isEmpty {
                roster.characters[characterIndex].signatureProps = [identity.signature]
            }
            if let mediaIds = referenceMediaIdsByMemberId[memberId] {
                let additions = mediaIds.filter { knownMediaIds.contains($0) }
                if !additions.isEmpty {
                    roster.characters[characterIndex].referenceMediaIds = uniqueNonEmpty(
                        roster.characters[characterIndex].referenceMediaIds + additions
                    )
                }
            }
            roster.characters[characterIndex].updatedAt = now
            roster.updatedAt = now
            member.characterId = roster.characters[characterIndex].characterId
            document.members[index] = member
            syncedNames.append(member.name)
        }
        guard !syncedNames.isEmpty else { return }
        saveProjectCharacters(roster, for: project, status: "Updated roster from goal cast: \(syncedNames.joined(separator: ", "))")
    }

    @discardableResult
    private func saveGoalCast(_ document: GoalCastDocument, for project: ProjectRecord, status: String = "") -> Bool {
        do {
            var updated = document
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            updated.updatedAt = DateFormats.now()
            let normalized = updated.normalized()
            try contextStore.saveGoalCast(normalized, for: project)
            goalCast = normalized
            if !status.isEmpty {
                goalCastStatus = status
            }
            queueInitialStoryGenerationIfEligible()
            return true
        } catch {
            lastError = error.localizedDescription
            goalCastStatus = "Could not save cast"
            return false
        }
    }

    private func saveGoalV2(_ goal: ProjectGoalDocumentV2, for project: ProjectRecord, status: String) {
        do {
            var updated = goal
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            try contextStore.saveProjectGoalV2(updated, for: project)
            projectGoalV2 = updated
            goalStatus = status
            creativeSchemaState = contextStore.creativeSchemaState(for: project)
            touchCurrentProject()
            queueLensContextRetrievalAfterGoalSave(updated, for: project)
            queueInitialStoryGenerationIfEligible()
        } catch {
            lastError = error.localizedDescription
            goalStatus = "Could not save Goal"
        }
    }

    private func queueLensContextRetrievalAfterGoalSave(_ goal: ProjectGoalDocumentV2, for project: ProjectRecord) {
        guard let version = goal.activeVersion, version.brief.isReady else {
            lensContextRetrievalTask?.cancel()
            lensContextRetrievalTask = nil
            activeLensContextRetrievalKey = ""
            lensContext = .empty(projectId: project.projectId)
            syncLensContextStatus()
            return
        }

        let fingerprint = lensContextFingerprint(projectId: project.projectId, version: version)
        let now = DateFormats.now()
        let pending = ProjectLensContextDocument(
            projectId: project.projectId,
            goalVersionId: version.versionId,
            goalFingerprint: fingerprint,
            status: .missing,
            updatedAt: now
        )
        do {
            try contextStore.saveLensContext(pending, for: project)
        } catch {
            lastError = error.localizedDescription
        }
        lensContext = pending
        lensContextStatus = "Frame Context queued"
        lensContextRetrievalTask?.cancel()
        lensContextRetrievalTask = Task {
            await refreshLensContextForActiveGoal()
        }
    }

    /// After every successful Frame Context retrieval: the first plan when none exists,
    /// otherwise a Story-driven refresh when the plan is stale and still holds
    /// never-started suggestions. Fully rendered plans are never re-planned on their
    /// own; the stage offers to plan more instead.
    private func queueFramePlanningAfterLensContext(projectId: String, goalVersionId: String) {
        Task {
            await Task.yield()
            guard currentProject?.projectId == projectId,
                  projectGoalV2.activeVersion?.versionId == goalVersionId,
                  hasFreshLensContextForActiveGoal,
                  !isRetrievingLensContext,
                  !isGeneratingInitialDraftLenses,
                  !isReplanningLensFromStory else {
                return
            }
            if projectLenses.lenses.isEmpty {
                if await planLens() {
                    print("[frame_plan] completed initial project_id=\(projectId) goal_version_id=\(goalVersionId)")
                }
                return
            }
            guard currentFramePlanRefreshDecision == .autoReplan else { return }
            if await replanLensFromStory(trigger: .storyChanged) {
                print("[frame_plan] refreshed after story change project_id=\(projectId) goal_version_id=\(goalVersionId)")
            }
        }
    }

    // MARK: - Frame Forms (story-route Form options from the knowledge graph)

    private func queueInitialFrameFormsAfterLensContext(projectId: String, goalVersionId: String, goalFingerprint: String) {
        Task {
            await Task.yield()
            await generateInitialFrameForms(projectId: projectId, goalVersionId: goalVersionId, goalFingerprint: goalFingerprint)
        }
    }

    /// Mode A: the GOAL-time initial trio. Fire-and-forget beside initial frame
    /// planning; failures never block the GOAL flow.
    func generateInitialFrameForms(projectId: String, goalVersionId: String, goalFingerprint: String) async {
        guard let project = currentProject, project.projectId == projectId,
              let version = projectGoalV2.activeVersion, version.versionId == goalVersionId else {
            return
        }
        if frameForms.goalFingerprint == goalFingerprint, frameForms.hasInitialGeneration {
            return
        }
        guard !version.brief.meaningNodeRefs.isEmpty else {
            print("[frame_forms] skipped initial: no meaning node refs project_id=\(projectId)")
            return
        }
        let request = FrameFormsGenerateRequest(
            projectId: projectId,
            goalFingerprint: goalFingerprint,
            goalSummary: goalBriefV2StyleSummary(version.brief),
            styleFitLine: await frameFormStyleFitLine(),
            meaningNodeRefs: version.brief.meaningNodeRefs
        )
        do {
            let client = try StoryInferenceService.fromEnvironment()
            let response = try await client.generateFrameForms(request)
            try Task.checkCancellation()
            guard currentProject?.projectId == projectId,
                  projectGoalV2.activeVersion?.versionId == goalVersionId else {
                return
            }
            var document = ProjectFrameFormsDocument(
                projectId: projectId,
                goalFingerprint: goalFingerprint,
                status: "ready",
                updatedAt: DateFormats.now()
            )
            document.generations = [frameFormGeneration(mode: "initial", parentOptionId: "", options: response.options)]
            guard document.hasInitialGeneration else {
                print("[frame_forms] initial returned no options project_id=\(projectId)")
                return
            }
            try contextStore.saveFrameForms(document, for: project)
            frameForms = document
            recordFrameFormsSpend(response, contextLabel: "Frame Forms (initial)")
            print("[frame_forms] initial completed project_id=\(projectId) options=\(response.options.count) warnings=\(response.warnings.count)")
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                return
            }
            guard currentProject?.projectId == projectId else { return }
            var document = frameForms.projectId == projectId ? frameForms : .empty(projectId: projectId)
            document.projectId = projectId
            document.goalFingerprint = goalFingerprint
            document.status = "failed"
            document.updatedAt = DateFormats.now()
            try? contextStore.saveFrameForms(document, for: project)
            frameForms = document
            print("[frame_forms] initial error: \(error.localizedDescription) project_id=\(projectId)")
        }
    }

    /// Mode B: expand the route from a selected Form. The lambda walks the
    /// meaning graph's edges from the option's node and returns a branching trio.
    /// One expansion per option; returns [] on any failure so the UI degrades
    /// silently.
    func expandFrameForms(from option: LensFrameFormOption, styleFitLine: String?) async -> [LensFrameFormOption] {
        guard let project = currentProject, let version = projectGoalV2.activeVersion else { return [] }
        let selectedId = option.id
        guard !selectedId.isEmpty, !option.meaningSlug.isEmpty else { return [] }
        guard !frameForms.hasExpansion(fromOptionId: selectedId) else { return [] }

        let gist = String(option.prompt.prefix(600)).trimmed
        let priorGists = frameForms.allOptions.suffix(12).map { String($0.prompt.prefix(600)).trimmed }
        let request = FrameFormsGenerateRequest(
            projectId: project.projectId,
            goalFingerprint: frameForms.goalFingerprint.trimmed.nilIfEmpty ?? currentLensContextGoalFingerprint,
            goalSummary: goalBriefV2StyleSummary(version.brief),
            styleFitLine: styleFitLine?.trimmed ?? "",
            meaningNodeRefs: version.brief.meaningNodeRefs,
            selectedForm: FrameFormsSelectedForm(
                meaningSlug: option.meaningSlug,
                pole: option.pole,
                title: option.title,
                promptGist: gist
            ),
            priorFormGists: Array(priorGists)
        )
        do {
            let client = try StoryInferenceService.fromEnvironment()
            let response = try await client.generateFrameForms(request)
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId, !response.options.isEmpty else { return [] }
            guard !frameForms.hasExpansion(fromOptionId: selectedId) else { return [] }
            let generation = frameFormGeneration(mode: "expansion", parentOptionId: selectedId, options: response.options)
            var document = frameForms
            document.projectId = project.projectId
            document.status = "ready"
            document.generations.append(generation)
            document.updatedAt = DateFormats.now()
            try contextStore.saveFrameForms(document, for: project)
            frameForms = document
            recordFrameFormsSpend(response, contextLabel: "Frame Forms (expansion)")
            print("[frame_forms] expansion completed project_id=\(project.projectId) parent=\(selectedId) options=\(generation.options.count)")
            return generation.options
        } catch {
            print("[frame_forms] expansion error: \(error.localizedDescription) project_id=\(project.projectId)")
            return []
        }
    }

    /// Frame Forms fire automatically after Frame Context, so their spend must
    /// ledger without an operator gesture. Usage arrives only when the
    /// generator reports it (direct mode does).
    private func recordFrameFormsSpend(_ response: FrameFormsGenerateResponse, contextLabel: String) {
        let tokens = response.usageInputTokens + response.usageOutputTokens
        guard tokens > 0 else { return }
        recordSpend(SpendLedgerEntry(
            kind: "story_inference",
            provider: "openai",
            model: response.model,
            requestId: response.requestId,
            contextLabel: contextLabel,
            unit: "tokens",
            unitCount: Double(tokens),
            pricingNote: StoryInferenceMode.resolved() == .direct
                ? "Billed by your OpenAI-compatible provider."
                : "Billed through LitScenes Hosted at the published markup.",
            status: "completed"
        ))
    }

    private func frameFormGeneration(mode: String, parentOptionId: String, options: [LensFrameFormOption]) -> LensFrameFormGeneration {
        let now = DateFormats.now()
        let stamped = options.map { option -> LensFrameFormOption in
            var value = option.normalized()
            value.optionId = "form_\(shortHash("\(value.meaningSlug):\(value.pole):\(value.title):\(now):\(UUID().uuidString)", length: 12))"
            return value
        }
        return LensFrameFormGeneration(
            generationId: "formgen_\(shortHash("\(mode):\(parentOptionId):\(now):\(UUID().uuidString)", length: 12))",
            mode: mode,
            parentOptionId: parentOptionId,
            options: stamped,
            generatedAt: now
        )
    }

    // MARK: - Shot timeline (the flat ordered workspace)

    func renameShot(shotId: String, name: String) {
        guard let project = currentProject else { return }
        let now = DateFormats.now()
        persistShotTimeline(shotTimeline.renamingShot(shotId: shotId, name: name, now: now), for: project)
    }

    /// The rendered-cut immutability law, enforced where mutations actually
    /// happen (the strip's UI lock alone left the Jovilabe, the Clip
    /// Inspector, and late async appends as silent side doors): a cut that is
    /// rendering or owns a ready render refuses STRUCTURE edits — inserts,
    /// removes, reorders, replacements, extensions, seam styles — because an
    /// editable timeline under a finished video silently lies. Iterate via
    /// NEW VERSION. Razor cuts and entry skips stay live (the non-destructive
    /// layer over the rendered file); a failed-only render does not freeze.
    func isCutStructureFrozen(shotId: String) -> Bool {
        if activeShotRenderId == shotId { return true }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return false }
        return shot.renderArtifact?.status == "generating" || !shot.browsableRenderVersions.isEmpty
    }

    private func refuseFrozenCutEdit() {
        aestheticStatus = "This cut is rendered — its strip stays true to the video. Use NEW VERSION to edit the structure"
    }

    private func refuseNonTailCutEdit() {
        aestheticStatus = "Only material after the rendered tail can change — the earlier strip stays true to the video. Use NEW VERSION to edit everything"
    }

    /// The suffix tail of a rendered cut, or nil while unlocked-irrelevant,
    /// actively rendering, or on a watermark-less legacy version (those keep
    /// the full freeze).
    func cutSuffixTailStartIndex(shotId: String) -> Int? {
        guard activeShotRenderId != shotId,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              shot.renderArtifact?.status != "generating" else { return nil }
        return shotSuffixTailStartIndex(shot: shot)
    }

    /// The freeze law with the suffix carve-out: a frozen cut permits a
    /// mutation only when it lands wholly inside the watermark tail. Emits the
    /// honest refusal and returns false otherwise.
    private func frozenCutPermits(shotId: String, tailPredicate: (Int) -> Bool) -> Bool {
        guard isCutStructureFrozen(shotId: shotId) else { return true }
        guard let tail = cutSuffixTailStartIndex(shotId: shotId) else {
            refuseFrozenCutEdit()
            return false
        }
        guard tailPredicate(tail) else {
            refuseNonTailCutEdit()
            return false
        }
        return true
    }

    @discardableResult
    func insertShotFrame(shotId: String, frameImageId: String, at index: Int) -> Bool {
        guard let project = currentProject else { return false }
        guard frozenCutPermits(shotId: shotId, tailPredicate: { index >= $0 }) else { return false }
        guard let before = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return false }
        let now = DateFormats.now()
        let updated = shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.insertingEntry(frameImageId: frameImageId, at: index, now: now)
            }
        guard updated != shotTimeline else { return false }
        persistShotTimeline(updated, for: project)
        guard let after = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return false }
        return after.entries.count == before.entries.count + 1
            && after.entries.contains { $0.frameImageId == frameImageId }
    }

    /// Drops real footage (a source video or Studio trim) into a shot row.
    func insertShotClip(shotId: String, mediaId: String, at index: Int) {
        guard let project = currentProject else { return }
        guard frozenCutPermits(shotId: shotId, tailPredicate: { index >= $0 }) else { return }
        guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video else {
            aestheticStatus = "Only videos can be placed as footage"
            return
        }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.insertingClipEntry(clipMediaId: media.mediaId, at: index, now: now)
            },
            for: project
        )
        aestheticStatus = "Placed footage \(media.filename) in the shot"
    }

    /// One media drop from the Scenes panel onto a shot row. Media drags
    /// arrive as CLIP drags (the alias decode), so this branches on the
    /// RESOLVED media kind: videos place as footage, images adopt-or-reuse a
    /// Frame for this lens (idempotent by source_photo provenance) and place
    /// that. Returns what was placed so the caller can gather the stage
    /// palette honestly; nil = refusal with the status already set.
    @discardableResult
    func insertShotMedia(
        shotId: String,
        mediaId: String,
        at index: Int,
        lensId: String
    ) -> ShotMediaPlacement? {
        guard currentProject != nil else { return nil }
        // Permits BEFORE any side effect: a frozen-cut refusal must never
        // mint an orphan Frame.
        guard frozenCutPermits(shotId: shotId, tailPredicate: { index >= $0 }) else { return nil }
        let media = items.first { $0.mediaId == mediaId }
        let plan = shotMediaInsertPlan(
            media: media,
            adoptedFrameImageId: adoptedPhotoFrame(lensId: lensId, mediaId: mediaId)?.imageId
        )
        switch plan {
        case .refuse(let reason):
            aestheticStatus = reason
            return nil
        case .placeClip(let clipMediaId):
            insertShotClip(shotId: shotId, mediaId: clipMediaId, at: index)
            return .clip(mediaId: clipMediaId)
        case .placeFrame(let frameImageId):
            insertShotFrame(shotId: shotId, frameImageId: frameImageId, at: index)
            aestheticStatus = "Placed Frame \(media?.filename ?? "") in the shot"
            return .frame(frameImageId: frameImageId)
        case .adoptImageAsFrame:
            guard let media,
                  addMediaImageAsFrame(media, lensId: lensId),
                  let adopted = adoptedPhotoFrame(lensId: lensId, mediaId: mediaId) else {
                // addMediaImageAsFrame already set the honest failure status.
                return nil
            }
            insertShotFrame(shotId: shotId, frameImageId: adopted.imageId, at: index)
            aestheticStatus = "Added \(media.filename) as a Frame and placed it in the shot"
            return .frame(frameImageId: adopted.imageId)
        }
    }

    /// Sets how an entry JOINS its predecessor: bridge (generated transition)
    /// or cut (hard join). Stale prompt overrides for a dissolved bridge
    /// simply stop matching — they return if the seam is bridged again.
    /// THE PICTURE SNAPSHOT LAW's choke point: one committed picture gesture
    /// = one persisted Shot transaction returning whole before/after picture
    /// snapshots, so the caller can register a single symmetric Undo action.
    /// nil = refusal or a persisted no-op (normalization can swallow a
    /// caller-visible change); nothing persists and nothing registers.
    private func commitShotPictureEdit(
        shotId: String,
        status: String?,
        _ transform: (ProjectShot, String) -> ProjectShot?
    ) -> ShotPictureStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        guard let updated = transform(shot, now) else { return nil }
        let edit = ShotPictureStateEdit(
            before: shot.pictureStateSnapshot(),
            after: updated.pictureStateSnapshot()
        )
        guard edit.before != edit.after else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        if let status { aestheticStatus = status }
        return edit
    }

    /// Compound picture undo primitive: entries, boundaries, the cut layer,
    /// and the audio state razor edits rippled, in one project-document
    /// write. Deliberately NOT guarded by `frozenCutPermits` — the snapshot
    /// came from a state that passed, and an undo must not refuse. Mirrors
    /// `setShotCutReversed`'s proxy side effects when the restore flips
    /// `isReversed`, or a restored reversed CUT would never bake.
    func restoreShotPictureState(shotId: String, snapshot: ShotPictureStateSnapshot) {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return }
        let wasReversed = shot.cutList.isReversed
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                current.restoringPictureState(snapshot, now: now)
            },
            for: project
        )
        let isReversed = snapshot.cutList.normalized().isReversed
        if isReversed != wasReversed {
            if isReversed {
                Task { await ensureReverseProxies(shotId: shotId) }
            } else {
                cancelReverseBakes(shotId: shotId)
            }
        }
        aestheticStatus = "Picture state restored"
    }

    @discardableResult
    func setShotSeamStyle(
        shotId: String,
        entryId: String,
        style: ShotSeamStyle,
        intent: ShotSeamEditIntent = .explicit
    ) -> ShotPictureStateEdit? {
        // A tail entry's IN seam joins new material — editable; seams between
        // rendered entries stay part of the finished video.
        guard frozenCutPermits(shotId: shotId, tailPredicate: { tail in
            (shotTimeline.shots.first { $0.shotId == shotId }?
                .entries.firstIndex { $0.entryId == entryId }).map { $0 >= tail } ?? false
        }) else { return nil }
        let edit = commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            shot.settingSeamStyle(entryId: entryId, style: style, intent: intent, now: now)
        }
        if edit != nil {
            aestheticStatus = intent == .restoreSkipped
                ? "Seam restored"
                : (style == .cut ? "Seam set to hard cut" : "Seam set to generated bridge")
        }
        return edit
    }

    /// Skips or restores one strip entry. A skip is free: the plan drops the
    /// entry, its seams heal to hard cuts, and the player re-assembles from
    /// the saved clips — no file is touched and nothing renders.
    @discardableResult
    func setShotEntrySkipped(shotId: String, entryId: String, skipped: Bool) -> ShotPictureStateEdit? {
        // Honesty nudge: arranged copies survive their source's skip on
        // purpose (THE REPLACE PATTERN) — say so, or the surviving loop
        // reads as "I deleted it, why is it still there?".
        var status = skipped
            ? "Segment skipped — seams heal to hard cuts"
            : "Segment restored"
        if skipped, let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) {
            let dependentCopies = shot.pictureInsertions.filter { insertion in
                shotSegmentKeyLeftEntryId(insertion.sourceSegmentKey) == entryId
                    || shotSegmentKeyRightEntryId(insertion.sourceSegmentKey) == entryId
            }.count
            if dependentCopies > 0 {
                status += " · \(dependentCopies) arranged cop\(dependentCopies == 1 ? "y" : "ies") of it still play\(dependentCopies == 1 ? "s" : "")"
            }
        }
        return commitShotPictureEdit(shotId: shotId, status: status) { shot, now in
            shot.settingEntrySkipped(entryId: entryId, skipped: skipped, now: now)
        }
    }

    /// Replaces the shot's cut layer (in/out trim + razor ranges). Free and
    /// non-destructive: applied at playback and export as a composition, never
    /// baked into rendered files.
    @discardableResult
    func setShotCutList(shotId: String, cutList: ShotCutList) -> ShotPictureStateEdit? {
        commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            shot.settingCutList(cutList, now: now)
        }
    }

    // MARK: - Picture insertions (paste / loop / rate / mute / re-copy)

    /// One arrangement mutation = one whole-picture transaction, with the
    /// audio-overlay ripple the join-repair ops established: when the output
    /// timeline changes length, overlays at/after the first diverging span
    /// shift by the delta, in OUTPUT seconds off the visible assembly.
    /// Deliberately NOT `frozenCutPermits`-gated: insertions never alter cut
    /// structure or the render plan, so they are legal mid-render.
    private func shotMutatingPictureInsertions(
        _ shot: ProjectShot,
        shotId: String,
        now: String,
        mutate: (inout [ShotPictureInsertion]) -> Void
    ) -> ProjectShot? {
        let oldAssembly = shotJoinAssembly(shot: shot, shotId: shotId)
        var updated = shot
        mutate(&updated.pictureInsertions)
        guard updated.pictureInsertions != shot.pictureInsertions else { return nil }
        updated.updatedAt = now
        let newAssembly = shotJoinAssembly(shot: updated, shotId: shotId)
        let delta = newAssembly.outputSeconds - oldAssembly.outputSeconds
        if abs(delta) > 0.000_1 {
            var rippleStart = min(oldAssembly.outputSeconds, newAssembly.outputSeconds)
            let shared = min(oldAssembly.playbackItems.count, newAssembly.playbackItems.count)
            for index in 0..<shared {
                let old = oldAssembly.playbackItems[index]
                let new = newAssembly.playbackItems[index]
                if old.itemId != new.itemId
                    || abs(old.durationSeconds - new.durationSeconds) > 0.000_1 {
                    rippleStart = min(old.outputStartSeconds, new.outputStartSeconds)
                    break
                }
            }
            updated = updated.settingAudioMix(
                shot.audioMix.ripplingPlacements(atOrAfter: rippleStart, by: delta),
                now: now
            )
            updated = updated.ripplingAudioRegions(atOrAfter: rippleStart, by: delta, now: now)
        }
        return updated
    }

    /// Pastes arranged copies (one gesture — a paste, a ⌘D, a Loop ×N batch —
    /// lands as ONE undoable edit). The caller mints the insertions from its
    /// clipboard payload / selection; this op stamps and appends them.
    @discardableResult
    func pasteShotPictureSegments(
        shotId: String,
        insertions rawInsertions: [ShotPictureInsertion],
        status: String? = nil
    ) -> ShotPictureStateEdit? {
        let minted = rawInsertions.map { $0.normalized() }
            .filter { !$0.insertionId.isEmpty && $0.sourceSeconds >= ShotCutList.minimumRangeSeconds }
        guard !minted.isEmpty else { return nil }
        return commitShotPictureEdit(shotId: shotId, status: status) { shot, now in
            self.shotMutatingPictureInsertions(shot, shotId: shotId, now: now) { list in
                list.append(contentsOf: minted.map { insertion in
                    var value = insertion
                    value.updatedAt = now
                    return value
                })
            }
        }
    }

    @discardableResult
    func removeShotPictureInsertions(
        shotId: String,
        insertionIds: Set<String>
    ) -> ShotPictureStateEdit? {
        guard !insertionIds.isEmpty,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let liveCutIds = Set(shot.cutList.segmentCuts.map(\.id))
        let linked = Set(
            shot.pictureInsertions
                .filter { insertionIds.contains($0.insertionId) }
                .flatMap(\.replacesRazorCutIds)
        ).intersection(liveCutIds)
        guard !linked.isEmpty else {
            return commitShotPictureEdit(
                shotId: shotId,
                status: insertionIds.count == 1 ? "Copy removed" : "\(insertionIds.count) copies removed"
            ) { shot, now in
                self.shotMutatingPictureInsertions(shot, shotId: shotId, now: now) { list in
                    list.removeAll { insertionIds.contains($0.insertionId) }
                }
            }
        }
        // R1 of THE SPEED SECTION LINK LAW: deleting a carrier restores its
        // razored material — the section returns to 1×, exactly once. Ripple
        // is the targeted honest form (the generic scan misplaces the start
        // when a razor merge moves item boundaries).
        return commitShotPictureEdit(
            shotId: shotId,
            status: "Speed section removed — the material plays at 1× again"
        ) { current, now in
            let oldVisible = self.shotJoinAssembly(shot: current, shotId: shotId)
            let rippleStart = oldVisible.insertionCells
                .filter { insertionIds.contains($0.insertion.insertionId) }
                .map(\.outputStartSeconds)
                .min() ?? 0
            guard let result = shotRemovingSectionSpeed(current, insertionIds: insertionIds, now: now) else {
                return nil
            }
            let newVisible = self.shotJoinAssembly(shot: result.shot, shotId: shotId)
            return self.shotRipplingOverlays(
                result.shot,
                rippleStart: rippleStart,
                delta: newVisible.outputSeconds - oldVisible.outputSeconds,
                now: now
            )
        }
    }

    @discardableResult
    func setShotPictureInsertionRate(
        shotId: String,
        insertionIds: Set<String>,
        rate: Double
    ) -> ShotPictureStateEdit? {
        let clamped = min(max(rate, ShotPictureInsertion.minimumRate), ShotPictureInsertion.maximumRate)
        // THE 2-FRAME OUTPUT LAW guards every rate change (previously a copy
        // near the minimum span could be driven sub-frame).
        if let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) {
            for insertion in shot.pictureInsertions
                where insertionIds.contains(insertion.insertionId)
                    && insertion.sourceSeconds / clamped < 2 * ShotAudioTiming.frameSeconds {
                aestheticStatus = "\(shotInsertionRateLabel(clamped)) would leave less than two frames of this copy — choose a gentler speed"
                return nil
            }
        }
        return commitShotPictureEdit(
            shotId: shotId,
            status: "Copy speed \(shotInsertionRateLabel(clamped))"
        ) { shot, now in
            self.shotMutatingPictureInsertions(shot, shotId: shotId, now: now) { list in
                for index in list.indices where insertionIds.contains(list[index].insertionId) {
                    list[index].playbackRate = clamped
                    list[index].updatedAt = now
                }
            }
        }
    }

    @discardableResult
    func setShotPictureInsertionMuted(
        shotId: String,
        insertionIds: Set<String>,
        muted: Bool
    ) -> ShotPictureStateEdit? {
        commitShotPictureEdit(
            shotId: shotId,
            status: muted ? "Copy sound muted" : "Copy sound restored"
        ) { shot, now in
            self.shotMutatingPictureInsertions(shot, shotId: shotId, now: now) { list in
                for index in list.indices where insertionIds.contains(list[index].insertionId) {
                    list[index].muteSourceAudio = muted
                    list[index].updatedAt = now
                }
            }
        }
    }

    /// RE-COPY: re-establishes an inert copy on the segment's CURRENT take at
    /// the same clip-local seconds (clamped at play time). The one deliberate
    /// pixel swap in the freshness ladder — explicit, undoable, never silent.
    @discardableResult
    func recopyShotPictureInsertion(shotId: String, insertionId: String) -> ShotPictureStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let insertion = shot.pictureInsertions.first(where: { $0.insertionId == insertionId }),
              !insertion.isFootageSource else { return nil }
        // THE ACTIVE TAKE AUTHORITY (version clips, else seeds) — the same
        // referee the splice's freshness uses, so Re-copy can always reach
        // whatever the segment actually plays, seeded combined CUTs included.
        let activePath = shotActiveTakePathsBySegmentKey(shot: shot)[insertion.sourceSegmentKey]?
            .trimmed ?? ""
        guard !activePath.isEmpty else {
            aestheticStatus = "No current take to re-copy from — render the segment first"
            return nil
        }
        guard activePath != insertion.sourceClipPath else { return nil }
        let isCarrier = !insertion.replacesRazorCutIds.isEmpty
        return commitShotPictureEdit(
            shotId: shotId,
            status: isCarrier
                ? "Speed section re-established on the current take"
                : "Copy re-established on the current take"
        ) { current, now in
            guard isCarrier else {
                return self.shotMutatingPictureInsertions(current, shotId: shotId, now: now) { list in
                    for index in list.indices where list[index].insertionId == insertionId {
                        list[index].sourceClipPath = activePath
                        list[index].updatedAt = now
                    }
                }
            }
            // R3 of THE SPEED SECTION LINK LAW: the razors re-pin with the
            // copy, or the section would play twice (fresh copy over a dead
            // razor). In the old state the razors are dead, so the inert
            // carrier's cell start IS where the 1× material begins.
            let oldVisible = self.shotJoinAssembly(shot: current, shotId: shotId)
            let rippleStart = oldVisible.insertionCells
                .first { $0.insertion.insertionId == insertionId }?
                .outputStartSeconds ?? 0
            guard let updated = shotRecopyingSectionInsertion(
                current,
                insertionId: insertionId,
                activePath: activePath,
                now: now
            ) else { return nil }
            let newVisible = self.shotJoinAssembly(shot: updated, shotId: shotId)
            return self.shotRipplingOverlays(
                updated,
                rippleStart: rippleStart,
                delta: newVisible.outputSeconds - oldVisible.outputSeconds,
                now: now
            )
        }
    }

    /// One ripple, shared by every section-speed op: overlays at/after the
    /// section shift by the honest whole-timeline delta — never Σ span/rate
    /// (sliver absorption and dissolve-zeroing move the real total).
    private func shotRipplingOverlays(
        _ shot: ProjectShot,
        rippleStart: Double,
        delta: Double,
        now: String
    ) -> ProjectShot {
        guard abs(delta) > 0.000_1 else { return shot }
        var updated = shot.settingAudioMix(
            shot.audioMix.ripplingPlacements(atOrAfter: rippleStart, by: delta),
            now: now
        )
        updated = updated.ripplingAudioRegions(atOrAfter: rippleStart, by: delta, now: now)
        return updated
    }

    /// THE SECTION SPEED GESTURE: slows/speeds the drag-selected material in
    /// place — one razor per kept span hiding the base material + one
    /// born-muted carrier playing it at `rate` in the gap (THE REPLACE
    /// PATTERN), linked by THE SPEED SECTION LINK LAW, one undoable edit.
    /// Free by construction. Deliberately NOT freeze-gated (razors and
    /// insertions are both the live non-destructive layer over a rendered
    /// cut) and NOT routed through the cut-list funnel (which would misname
    /// the undo and cannot carry the carriers).
    @discardableResult
    func setShotSectionRate(
        shotId: String,
        materialStart: Double,
        materialEnd: Double,
        rate: Double
    ) -> ShotPictureStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let clamped = min(max(rate, ShotPictureInsertion.minimumRate), ShotPictureInsertion.maximumRate)
        guard abs(clamped - 1) >= 0.001 else {
            aestheticStatus = "1× is no change — pick a slower or faster speed"
            return nil
        }
        let forward = shotForwardAssembly(shot)
        let spans = shotCopiedSpans(
            assembly: forward,
            materialStart: materialStart,
            materialEnd: materialEnd
        )
        guard !spans.isEmpty else {
            aestheticStatus = "The selection holds no playable picture"
            return nil
        }
        if let shortSeconds = shotSectionRateSubFrameSpanSeconds(spans: spans, rate: clamped) {
            aestheticStatus = "\(shotInsertionRateLabel(clamped)) would leave less than two frames of a \(String(format: "%.1f", shortSeconds))s span — select more or choose a gentler speed"
            return nil
        }
        // Partial overlap with an existing section would invert material
        // play order (the run-advance law) — refuse it honestly.
        let low = min(materialStart, materialEnd)
        let high = max(materialStart, materialEnd)
        let carrierCutIds = Set(shot.pictureInsertions.flatMap(\.replacesRazorCutIds))
        for cut in shot.cutList.segmentCuts where carrierCutIds.contains(cut.id) {
            if let range = shotRazorCutMaterialRange(cut: cut, assembly: forward),
               range.upperBound > low, range.lowerBound < high {
                aestheticStatus = "That selection overlaps an existing speed section — delete its ⟳ cell first"
                return nil
            }
        }
        return commitShotPictureEdit(
            shotId: shotId,
            status: "Section plays at \(shotInsertionRateLabel(clamped)), born muted — ♪ restores its stretched sound; Delete the ⟳ cell to return to 1×"
        ) { current, now in
            let oldVisible = self.shotJoinAssembly(shot: current, shotId: shotId)
            let rippleStart = shotSectionRippleStart(
                assembly: oldVisible,
                materialLow: low,
                materialHigh: high
            )
            guard let sectioned = shotApplyingSectionRate(
                current,
                spans: spans,
                rate: clamped,
                now: now
            ) else { return nil }
            let newVisible = self.shotJoinAssembly(shot: sectioned, shotId: shotId)
            return self.shotRipplingOverlays(
                sectioned,
                rippleStart: rippleStart,
                delta: newVisible.outputSeconds - oldVisible.outputSeconds,
                now: now
            )
        }
    }

    /// THE STRUCTURAL PASTE: copied segment cards land in this CUT as
    /// first-class material (pair entries + re-keyed overrides + seed take —
    /// see `shotAppendingSegmentCards`). Rides the same freeze law as every
    /// entry insertion: an append lands in a locked cut's suffix tail;
    /// anything else on a locked cut refuses honestly. Undo note: the picture
    /// snapshot restores the entries; the re-keyed override/seed rows go
    /// dormant when their placement vanishes (overrides prune on the next
    /// normalize) — the carried take's file is never touched either way.
    @discardableResult
    func pasteShotSegmentCards(
        shotId: String,
        cards: [ShotPictureSegmentSpanRef],
        afterEntryId: String? = nil
    ) -> ShotPictureStateEdit? {
        let structural = cards.filter(\.isSegmentCard)
        guard !structural.isEmpty else { return nil }
        guard let lens = projectLenses.lenses.first else { return nil }
        let frameIds = Set(lens.sortedHeroImages.map(\.imageId))
        guard structural.allSatisfy({
            frameIds.contains($0.startFrameImageId.trimmed)
                && frameIds.contains($0.endFrameImageId.trimmed)
        }) else {
            aestheticStatus = "Those keyframes aren't in this project — segments paste within their own project"
            return nil
        }
        guard frozenCutPermits(shotId: shotId, tailPredicate: { tail in
            guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return false }
            let index = afterEntryId
                .flatMap { id in shot.entries.firstIndex { $0.entryId == id }.map { $0 + 1 } }
                ?? shot.entries.count
            return index >= tail
        }) else { return nil }
        var carriedNarrationCount = 0
        let edit = commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            let oldVisible = self.shotJoinAssembly(shot: shot, shotId: shotId)
            guard var pasted = shotAppendingSegmentCards(
                shot,
                cards: structural,
                afterEntryId: afterEntryId,
                fileExists: { FileManager.default.fileExists(atPath: $0) },
                now: now
            ) else { return nil }
            // The kernel's block contract: two entries per card, in card
            // order, at the insert index — re-derive the pasted pairs' keys
            // from the updated entries.
            let insertIndex = afterEntryId
                .flatMap { id in shot.entries.firstIndex { $0.entryId == id }.map { $0 + 1 } }
                ?? shot.entries.count
            let pastedKeys: [(card: ShotPictureSegmentSpanRef, key: String)] = structural.enumerated().compactMap { offset, card in
                let startIndex = insertIndex + offset * 2
                guard pasted.entries.indices.contains(startIndex + 1) else { return nil }
                return (card, shotPlacementSegmentKey(
                    startEntryId: pasted.entries[startIndex].entryId,
                    endEntryId: pasted.entries[startIndex + 1].entryId,
                    legacyStartId: card.startFrameImageId.trimmed,
                    legacyEndId: card.endFrameImageId.trimmed
                ))
            }
            let newVisible = self.shotJoinAssembly(shot: pasted, shotId: shotId)
            let keySet = Set(pastedKeys.map(\.key))
            let pastedItems = newVisible.playbackItems.filter {
                keySet.contains($0.segmentKey) && !$0.isBridge && $0.durationSeconds > 0
            }
            // MID-SHOT RIPPLE: material before the pasted block is identical
            // in both assemblies, so everything at or after the block's
            // output start shifts by the honest whole-assembly delta. A pure
            // append starts at the old end — nothing to move.
            if let rippleStart = pastedItems.map(\.outputStartSeconds).min() {
                let delta = newVisible.outputSeconds - oldVisible.outputSeconds
                if delta > 0.001, rippleStart < oldVisible.outputSeconds - 0.001 {
                    pasted = self.shotRipplingOverlays(
                        pasted,
                        rippleStart: rippleStart,
                        delta: delta,
                        now: now
                    )
                }
            }
            // NARRATION CARRY: land each carried slice as a born-audible
            // CLIP-lane region at its pasted segment's output position.
            // Regionize first — appending a region flips the precedence law,
            // and the target's own legacy narration must keep playing.
            let carried: [ShotAudioRegion] = pastedKeys.compactMap { card, key in
                guard card.carriesNarration,
                      FileManager.default.fileExists(atPath: card.narrationPath),
                      let outputStart = newVisible.playbackItems
                          .filter({ $0.segmentKey == key && !$0.isBridge && $0.durationSeconds > 0 })
                          .map(\.outputStartSeconds)
                          .min() else {
                    return nil
                }
                return shotCarriedNarrationRegion(
                    card: card,
                    targetSegmentOutputStartSeconds: outputStart,
                    sourceCutId: card.seedClip?.sourceCutId ?? "",
                    regionId: "audio_region_\(UUID().uuidString.lowercased())"
                )
            }
            if !carried.isEmpty {
                carriedNarrationCount = carried.count
                let regionized = self.regionizedForAudioEdit(pasted, now: now)
                pasted = regionized.settingAudioRegions(regionized.audioRegions + carried, now: now)
            }
            return pasted
        }
        if edit != nil {
            let seeded = structural.contains { card in
                guard let seed = card.seedClip, !seed.clipPath.trimmed.isEmpty else { return false }
                return FileManager.default.fileExists(atPath: seed.clipPath)
            }
            let narrationTail = carriedNarrationCount > 0
                ? " Its narration slice rides the Clip lane, audible."
                : ""
            aestheticStatus = (seeded
                ? "Segment pasted — its rendered take plays here at $0; boundary seams are hard cuts (toggle ≈ to bridge)"
                : "Segment pasted unrendered — its frames and prompt are ready to render here; boundary seams are hard cuts")
                + narrationTail
        }
        return edit
    }

    // MARK: - Reverse

    /// Plays the whole CUT backwards, or forwards again.
    ///
    /// The same deterministic view state as the in/out trim — it never rewrites
    /// a saved clip. Turning it on enqueues a reversed proxy for every span;
    /// playback stays forward until they are ALL ready, because a half-reversed
    /// cut is a lie about what the operator asked for.
    @discardableResult
    func setShotCutReversed(shotId: String, reversed: Bool) -> ShotPictureStateEdit? {
        let edit = commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            guard shot.cutList.isReversed != reversed else { return nil }
            var list = shot.cutList
            list.isReversed = reversed
            return shot.settingCutList(list, now: now)
        }
        guard edit != nil else { return nil }
        if reversed {
            aestheticStatus = "Reversing — baking a backwards copy of every clip"
            Task { await ensureReverseProxies(shotId: shotId) }
        } else {
            // Finished proxies stay on disk. They are content-addressed, so
            // turning reverse back on is instant.
            cancelReverseBakes(shotId: shotId)
            aestheticStatus = "CUT plays forward"
        }
        return edit
    }

    /// The forward assembly for a shot, resolved against the live lens frames
    /// and media. The lookups are rebuilt here rather than threaded through
    /// because every caller starts from a shotId.
    private func shotForwardAssembly(_ shot: ProjectShot) -> ShotCutAssembly {
        let frameLookup = Dictionary(
            (projectLenses.lenses.first?.sortedHeroImages ?? []).map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let mediaLookup = Dictionary(
            items.map { ($0.mediaId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let plan = shotRenderSegmentPlan(
            shot: shot,
            frameLookup: frameLookup,
            mediaLookup: mediaLookup,
            meaningNodes: []
        )
        return shotCutAssembly(shot: shot, planSegments: plan.segments, clipDurationsByPath: [:])
    }

    /// Every distinct source file a reversed playback of this shot would need.
    /// Generated bridges are included: they are ordinary clips in the span list
    /// and would otherwise play forward inside a backwards cut.
    private func reverseProxySourcePaths(for shot: ProjectShot) -> [String] {
        var seen = Set<String>()
        var ordered: [String] = []
        // Enumerated in PLAY order, so the cut becomes correct from its head
        // outward as bakes land.
        for item in shotForwardAssembly(shot).playbackItems.reversed() {
            let path = item.url.path
            guard !path.isEmpty,
                  FileManager.default.fileExists(atPath: path),
                  seen.insert(path).inserted else { continue }
            ordered.append(path)
        }
        return ordered
    }

    /// Adopts any proxy already on disk and queues a bake for the rest.
    func ensureReverseProxies(shotId: String) async {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              shot.cutList.isReversed else { return }

        let directory = contextStore.reverseProxyDirectory(for: project)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        var pending: [String] = []
        for path in reverseProxySourcePaths(for: shot) {
            guard let key = try? ReverseProxyBaker.cacheKey(sourcePath: path) else { continue }
            if let existing = shot.reverseProxy(forSourcePath: path),
               existing.proxyId == key,
               existing.isReady,
               FileManager.default.fileExists(atPath: existing.proxyPath) {
                continue
            }
            // Another shot may already have baked this exact file.
            if let adopted = loadReverseProxySidecar(proxyId: key, in: directory),
               adopted.bakerVersion == ReverseProxyBaker.bakerVersion,
               FileManager.default.fileExists(atPath: adopted.proxyPath) {
                persistReverseProxy(adopted, shotId: shotId)
                continue
            }
            pending.append(path)
        }

        guard !pending.isEmpty else {
            refreshReverseBakeState(shotId: shotId)
            return
        }
        for path in pending where !pendingReverseBakes.contains(where: {
            $0.shotId == shotId && $0.sourcePath == path
        }) {
            pendingReverseBakes.append((shotId: shotId, sourcePath: path))
        }
        activeReverseBakeShotIds.insert(shotId)
        refreshReverseBakeState(shotId: shotId)
        pumpReverseBakes()
    }

    /// The only door into the reverse-bake lane. Keyed by content address, so a
    /// second shot wanting the same take joins the running bake instead of
    /// starting a duplicate encode.
    private func spawnReverseBakeLaneTask(
        proxyId: String,
        shotId: String,
        operation: @escaping () async -> Void
    ) {
        let token = UUID()
        let task = Task { [weak self] in
            await operation()
            // Only the current owner frees the slot: after a teardown and
            // respawn under the same id, the stale task's token no longer
            // matches and its cleanup must be a no-op.
            guard let self, self.reverseBakeTasks[proxyId]?.token == token else { return }
            self.reverseBakeTasks[proxyId] = nil
            // Republish AFTER deregistering, and name the shot rather than
            // relying on it still being in the active set — this is the moment
            // a shot stops having work in flight, and the moment its progress
            // must stop disabling the control.
            self.refreshReverseBakeState(shotId: shotId)
            self.pumpReverseBakes()
        }
        reverseBakeTasks[proxyId] = (token, task)
    }

    private func pumpReverseBakes() {
        while !reverseBakeLaneIsFull, !pendingReverseBakes.isEmpty {
            let next = pendingReverseBakes.removeFirst()
            guard let key = try? ReverseProxyBaker.cacheKey(sourcePath: next.sourcePath),
                  reverseBakeTasks[key] == nil else { continue }
            spawnReverseBakeLaneTask(proxyId: key, shotId: next.shotId) { [weak self] in
                await self?.runReverseBake(shotId: next.shotId, sourcePath: next.sourcePath, proxyId: key)
            }
        }
        if pendingReverseBakes.isEmpty, reverseBakeTasks.isEmpty {
            for shotId in Array(activeReverseBakeShotIds) { refreshReverseBakeState(shotId: shotId) }
        }
    }

    private func runReverseBake(shotId: String, sourcePath: String, proxyId: String) async {
        guard let project = currentProject else { return }
        let directory = contextStore.reverseProxyDirectory(for: project)
        let outputURL = directory.appendingPathComponent("\(proxyId).mp4")
        let now = DateFormats.now()

        var artifact = ShotReverseProxyArtifact(
            proxyId: proxyId,
            sourcePath: sourcePath,
            proxyPath: outputURL.path,
            bakerVersion: ReverseProxyBaker.bakerVersion,
            status: "baking",
            startedAt: now,
            updatedAt: now
        )
        if let attributes = try? FileManager.default.attributesOfItem(atPath: sourcePath) {
            artifact.sourceByteCount = (attributes[.size] as? NSNumber)?.int64Value ?? 0
            if let modified = attributes[.modificationDate] as? Date {
                artifact.sourceModifiedAt = DateFormats.string(from: modified)
            }
        }
        persistReverseProxy(artifact, shotId: shotId)

        do {
            let source = mediaSource(forVideoPath: sourcePath)
            let result = try await store.withSourceAccess(source) {
                try await ReverseProxyBaker.bake(
                    sourceURL: URL(fileURLWithPath: sourcePath),
                    outputURL: outputURL,
                    progress: { [weak self] state in
                        self?.noteReverseBakeProgress(shotId: shotId, proxyId: proxyId, state: state)
                    }
                )
            }
            artifact.sourceDurationSeconds = result.sourceDurationSeconds
            artifact.proxyDurationSeconds = result.proxyDurationSeconds
            artifact.frameCount = result.frameCount
            artifact.hasReversedAudio = result.hasReversedAudio
            artifact.status = "ready"
            artifact.errorMessage = ""
            artifact.updatedAt = DateFormats.now()
            persistReverseProxy(artifact, shotId: shotId)
            saveReverseProxySidecar(artifact, in: directory)
            if result.usedSoftwareEncoder {
                logGeneration(
                    kind: "reverse.bake",
                    message: "[encoder_fallback] hardware encoder stalled; proxy \(proxyId) baked on the software encoder"
                )
                aestheticStatus = "Reverse bake finished on the software encoder — the hardware encoder was busy (a screen recording, usually)"
            }
        } catch {
            guard !isCancellationLikeError(error) else { return }
            artifact.status = "failed"
            artifact.errorMessage = error.localizedDescription
            artifact.updatedAt = DateFormats.now()
            persistReverseProxy(artifact, shotId: shotId)
            lastError = error.localizedDescription
            aestheticStatus = "Reverse bake failed — the CUT keeps playing forward"
        }
        refreshReverseBakeState(shotId: shotId)
    }

    private func noteReverseBakeProgress(
        shotId: String,
        proxyId: String,
        state: ReverseProxyBakeProgress
    ) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return }
        let paths = reverseProxySourcePaths(for: shot)
        let resolved = shot.readyReverseProxiesBySourcePath {
            FileManager.default.fileExists(atPath: $0)
        }
        let ready = paths.filter { resolved[$0] != nil }.count
        // The in-flight proxy contributes its own fraction of one slot.
        let fraction = (Double(ready) + state.fraction) / Double(max(paths.count, 1))
        reverseBakeProgress[shotId] = min(max(fraction, 0), 1)
    }

    /// Whether this shot has a reverse bake queued or running RIGHT NOW.
    ///
    /// Distinct from having work outstanding, and the distinction is the whole
    /// point: progress that outlives its task disables the control with nothing
    /// behind it.
    private func reverseBakeWorkIsInFlight(for shot: ProjectShot) -> Bool {
        if pendingReverseBakes.contains(where: { $0.shotId == shot.shotId }) { return true }
        let keys = Set(
            reverseProxySourcePaths(for: shot)
                .compactMap { try? ReverseProxyBaker.cacheKey(sourcePath: $0) }
        )
        return reverseBakeTasks.keys.contains { keys.contains($0) }
    }

    /// Republishes a shot's reverse progress.
    ///
    /// Progress reports WORK IN FLIGHT, never work remaining. A failed or
    /// abandoned bake leaves proxies outstanding forever, and reporting that as
    /// progress left the Reverse button stuck at a percentage with no task
    /// behind it and no way for the operator to retry.
    private func refreshReverseBakeState(shotId: String) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else {
            activeReverseBakeShotIds.remove(shotId)
            reverseBakeProgress[shotId] = nil
            return
        }
        let needed = reverseProxySourcePaths(for: shot)
        let ready = shot.readyReverseProxiesBySourcePath {
            FileManager.default.fileExists(atPath: $0)
        }
        let outstanding = needed.filter { ready[$0] == nil }

        guard shot.cutList.isReversed, !outstanding.isEmpty else {
            activeReverseBakeShotIds.remove(shotId)
            reverseBakeProgress[shotId] = nil
            if outstanding.isEmpty, shot.cutList.isReversed {
                aestheticStatus = "CUT plays in reverse"
            }
            return
        }
        guard reverseBakeWorkIsInFlight(for: shot) else {
            // Requested, not achieved, nothing running. The cut keeps playing
            // forward and the strip says so; the control must stay live so the
            // operator can turn it off or try again.
            activeReverseBakeShotIds.remove(shotId)
            reverseBakeProgress[shotId] = nil
            return
        }
        activeReverseBakeShotIds.insert(shotId)
        reverseBakeProgress[shotId] = Double(needed.count - outstanding.count) / Double(needed.count)
    }

    private func cancelReverseBakes(shotId: String) {
        pendingReverseBakes.removeAll { $0.shotId == shotId }
        // Bakes are shared by content address, so only tear down tasks no other
        // reversed shot still wants.
        let wanted = Set(
            shotTimeline.shots
                .filter { $0.shotId != shotId && $0.cutList.isReversed }
                .flatMap { reverseProxySourcePaths(for: $0) }
                .compactMap { try? ReverseProxyBaker.cacheKey(sourcePath: $0) }
        )
        for (proxyId, entry) in reverseBakeTasks where !wanted.contains(proxyId) {
            entry.task.cancel()
            reverseBakeTasks[proxyId] = nil
        }
        activeReverseBakeShotIds.remove(shotId)
        reverseBakeProgress[shotId] = nil
    }

    // MARK: Reverse proxy lifecycle

    /// Collects reversed proxies nothing can play any more.
    ///
    /// Proxies are content-addressed, so a re-render never leaves a STALE one
    /// playable — its new clip paths simply stop matching. What it does leave is
    /// orphans, and this is what collects them: proxies whose source is gone,
    /// that no live clip references, or that a newer baker would rewrite.
    private func sweepStaleReverseProxies(for project: ProjectRecord) {
        let directory = contextStore.reverseProxyDirectory(for: project)
        guard let names = try? FileManager.default.contentsOfDirectory(atPath: directory.path) else { return }

        var wanted = Set<String>()
        for shot in shotTimeline.shots {
            for path in reverseProxySourcePaths(for: shot) {
                if let key = try? ReverseProxyBaker.cacheKey(sourcePath: path) { wanted.insert(key) }
            }
        }

        var removedIds = Set<String>()
        for name in names {
            let url = directory.appendingPathComponent(name)
            let proxyId = (name as NSString).deletingPathExtension
            let sidecar = loadReverseProxySidecar(proxyId: proxyId, in: directory)
            let sourceGone = sidecar.map { !FileManager.default.fileExists(atPath: $0.sourcePath) } ?? false
            let outdated = sidecar.map { $0.bakerVersion != ReverseProxyBaker.bakerVersion } ?? false
            // A media file with no sidecar was never finished — the sidecar is
            // written only on success — so it is a crash leftover, unless a bake
            // is writing it right now.
            let unfinished = url.pathExtension == "mp4"
                && sidecar == nil
                && reverseBakeTasks[proxyId] == nil
            guard !wanted.contains(proxyId) || sourceGone || outdated || unfinished else { continue }
            try? FileManager.default.removeItem(at: url)
            removedIds.insert(proxyId)
        }
        guard !removedIds.isEmpty else { return }

        // Drop the matching rows in one persisted transaction.
        let now = DateFormats.now()
        var document = shotTimeline
        for shot in document.shots where shot.reverseProxies.contains(where: { removedIds.contains($0.proxyId) }) {
            document = document.updatingShot(shotId: shot.shotId, now: now) { value in
                var updated = value
                updated.reverseProxies.removeAll { removedIds.contains($0.proxyId) }
                return updated
            }
        }
        persistShotTimeline(document, for: project)
    }

    /// A bake killed by a relaunch has no remote job to resume — only a dead
    /// local encode — so this simply re-enqueues everything a reversed shot is
    /// still missing. Far simpler than the paid-job reconciles it sits beside.
    private func reconcileInterruptedReverseProxies(for project: ProjectRecord) {
        sweepStaleReverseProxies(for: project)
        for shot in shotTimeline.shots where shot.cutList.isReversed {
            Task { [shotId = shot.shotId] in await ensureReverseProxies(shotId: shotId) }
        }
    }

    private func persistReverseProxy(_ artifact: ShotReverseProxyArtifact, shotId: String) {
        guard let project = currentProject else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.upsertingReverseProxy(artifact, now: now)
            },
            for: project
        )
    }

    /// The sidecar is what lets one bake serve every shot: the directory
    /// describes itself, so adoption and the stale sweep never need to open a
    /// shot document.
    private func saveReverseProxySidecar(_ artifact: ShotReverseProxyArtifact, in directory: URL) {
        let url = directory.appendingPathComponent("\(artifact.proxyId).json")
        guard let data = try? JSONEncoder().encode(artifact) else { return }
        try? data.write(to: url, options: .atomic)
    }

    private func loadReverseProxySidecar(proxyId: String, in directory: URL) -> ShotReverseProxyArtifact? {
        let url = directory.appendingPathComponent("\(proxyId).json")
        guard let data = try? Data(contentsOf: url),
              let artifact = try? JSONDecoder().decode(ShotReverseProxyArtifact.self, from: data),
              artifact.isReady else { return nil }
        return artifact
    }

    /// The external source behind a placed clip, when there is one. Generated
    /// clips live inside the project and need no security scope.
    private func mediaSource(forVideoPath path: String) -> MediaSourceRecord? {
        guard let item = items.first(where: { $0.path == path }) else { return nil }
        return sources.first { $0.sourceId == item.sourceId }
    }

    /// Changes only the selected razor join. Generated duration is an
    /// insertion edit, so later output-time voice placements ripple by the
    /// exact active-duration delta in the same persisted Shot transaction.
    @discardableResult
    func setShotRazorJoinRepair(
        shotId: String,
        cutId: String,
        repair: ShotRazorJoinRepair
    ) -> ShotPictureStateEdit? {
        let edit = commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            guard shot.cutList.segmentCuts.contains(where: { $0.id == cutId }) else { return nil }
            return self.shotSettingJoinRepair(
                shot,
                shotId: shotId,
                cutId: cutId,
                repair: repair,
                now: now
            )
        }
        guard edit != nil else { return nil }
        switch repair.mode {
        case .hardCut: aestheticStatus = "Join set to hard cut"
        case .dissolve: aestheticStatus = "Local dissolve applied"
        case .generatedBridge: aestheticStatus = "Generated bridge selected"
        }
        return edit
    }

    /// Restores the hidden source range and deactivates the join while keeping
    /// all paid bridge versions on the Shot for provenance.
    ///
    /// THE RAZOR BLOCK LAW: overlapping/abutting cuts draw as one bite, so
    /// restore clears the WHOLE connected block in one transaction — before
    /// this, RESTORE removed one cutId and an invisible survivor kept biting,
    /// which read as "restore lost a little video".
    @discardableResult
    func restoreShotRazorCut(shotId: String, cutId: String) -> ShotPictureStateEdit? {
        var blockCount = 0
        var carrierFell = false
        let edit = commitShotPictureEdit(shotId: shotId, status: nil) { shot, now in
            let block = shotRazorCutIdsInSameBlock(cutList: shot.cutList, cutId: cutId)
            guard !block.isEmpty else { return nil }
            blockCount = block.count
            carrierFell = block.contains { id in
                !shotSectionCarrierIds(insertions: shot.pictureInsertions, cutId: id).isEmpty
            }
            var updated = shot
            for id in block {
                if let next = self.shotRemovingRazorCut(updated, shotId: shotId, cutId: id, now: now) {
                    updated = next
                }
            }
            return updated
        }
        guard edit != nil else { return nil }
        if carrierFell {
            aestheticStatus = "Razor material restored — its speed copy went with it (1×)"
        } else {
            aestheticStatus = blockCount > 1
                ? "Razor material restored (\(blockCount) cuts)"
                : "Razor material restored"
        }
        return edit
    }

    /// Generates a native 1–3 second exact-boundary bridge. The current join
    /// continues playing until a ready artifact persists; only then does the
    /// new version activate and ripple later audio.
    @discardableResult
    func renderShotRazorJoinBridge(
        shotId: String,
        cutId: String,
        provider: ShotJoinBridgeProvider,
        durationSeconds: Int,
        prompt: String
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard activeShotJoinRenderId.isEmpty, activeShotRenderId.isEmpty, activeShotRestyleId.isEmpty else {
            aestheticStatus = "Another video render is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard videoCredentialStore.credentialStatus(for: .fal).isConfigured else {
            aestheticStatus = "Add a FAL API key in App Settings to render this join"
            return false
        }
        guard provider.supportedDurations.contains(durationSeconds) else {
            aestheticStatus = "That duration is not supported by \(provider.label)"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let cut = shot.cutList.segmentCuts.first(where: { $0.id == cutId }),
              let sourceClip = shotJoinSourceClip(shot: shot, cut: cut),
              FileManager.default.fileExists(atPath: sourceClip.clipPath) else {
            aestheticStatus = "The razor source take is no longer available"
            return false
        }

        activeShotJoinRenderId = cutId
        defer { activeShotJoinRenderId = "" }
        let now = DateFormats.now()
        let versionId = "joinbridge_\(shortHash("\(project.projectId):\(shotId):\(cutId):\(now):\(UUID().uuidString)", length: 16))"
        let proofDirectory = contextStore.aestheticProofDirectory(for: project)
        let outgoingPath = proofDirectory.appendingPathComponent("\(versionId)_out.png")
        let incomingPath = proofDirectory.appendingPathComponent("\(versionId)_in.png")
        let outputURL = proofDirectory.appendingPathComponent("\(versionId).mp4")
        let sourceAttributes = (try? FileManager.default.attributesOfItem(atPath: sourceClip.clipPath)) ?? [:]
        let boundaryFingerprint = shortHash(
            "\(sourceClip.clipPath)|\(sourceAttributes[.size] ?? 0)|\(sourceAttributes[.modificationDate] ?? "")|\(String(format: "%.3f", cut.startSeconds))|\(String(format: "%.3f", cut.endSeconds))",
            length: 20
        )
        let promptUsed = prompt.trimmed.nilIfEmpty ?? ShotJoinBridgePrompt.defaultText
        var artifact = ShotJoinBridgeArtifact(
            versionId: versionId,
            cutId: cut.id,
            sourceSegmentKey: cut.segmentKey,
            sourceClipPath: sourceClip.clipPath,
            cutStartSeconds: cut.startSeconds,
            cutEndSeconds: cut.endSeconds,
            boundaryFingerprint: boundaryFingerprint,
            provider: provider.rawValue,
            model: provider.modelId,
            durationSeconds: Double(durationSeconds),
            prompt: promptUsed,
            resolution: "1080p",
            status: "generating",
            videoPath: outputURL.path,
            outgoingFramePath: outgoingPath.path,
            incomingFramePath: incomingPath.path,
            generatedAt: now,
            updatedAt: now
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.upsertingJoinBridgeVersion(artifact, now: now)
            },
            for: project
        )
        aestheticStatus = "Rendering \(durationSeconds)s join with \(provider.label)"
        logGeneration(
            kind: "video.start",
            message: "Shot join bridge starting shot_id=\(shotId) cut_id=\(cutId) model=\(provider.modelId) duration_s=\(durationSeconds)"
        )

        let startedAt = Date()
        do {
            try ensureDirectory(proofDirectory)
            let scratchDirectory = FileManager.default.temporaryDirectory
                .appendingPathComponent("shot_join_\(safeIdentifier(versionId))", isDirectory: true)
            try ensureDirectory(scratchDirectory)
            let outgoingRaw = scratchDirectory.appendingPathComponent("outgoing.png")
            let incomingRaw = scratchDirectory.appendingPathComponent("incoming.png")
            _ = try await VideoChainMedia.extractFrameStill(
                videoURL: URL(fileURLWithPath: sourceClip.clipPath),
                atSeconds: max(cut.startSeconds - ShotAudioTiming.frameSeconds, 0),
                outputURL: outgoingRaw
            )
            _ = try await VideoChainMedia.extractFrameStill(
                videoURL: URL(fileURLWithPath: sourceClip.clipPath),
                atSeconds: cut.endSeconds,
                outputURL: incomingRaw
            )
            let profile = VideoOutputProfile.standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
            _ = try VideoChainMedia.normalizeImageFrame(
                sourceURL: outgoingRaw,
                outputURL: outgoingPath,
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            _ = try VideoChainMedia.normalizeImageFrame(
                sourceURL: incomingRaw,
                outputURL: incomingPath,
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            let result = try await FALVideoClient(credentialStore: videoCredentialStore).generateJoinBridge(
                from: FALJoinBridgeRequest(
                    projectId: project.projectId,
                    shotId: shotId,
                    artifactId: versionId,
                    provider: provider,
                    durationSeconds: durationSeconds,
                    prompt: promptUsed,
                    resolution: "1080p",
                    outgoingFrameURL: outgoingPath,
                    incomingFrameURL: incomingPath,
                    outputURL: outputURL
                )
            )
            artifact.status = "ready"
            artifact.videoPath = result.outputURL.path
            artifact.durationSeconds = (try? await VideoChainMedia.videoDurationSeconds(videoURL: result.outputURL))
                ?? Double(durationSeconds)
            artifact.requestId = result.requestId
            artifact.errorMessage = ""
            artifact.updatedAt = DateFormats.now()
            guard currentProject?.projectId == project.projectId,
                  let currentShot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else {
                return false
            }
            var updated = currentShot.upsertingJoinBridgeVersion(artifact, now: artifact.updatedAt)
            if let currentCut = updated.cutList.segmentCuts.first(where: { $0.id == cutId }),
               currentCut.segmentKey == cut.segmentKey,
               abs(currentCut.startSeconds - cut.startSeconds) < 0.000_1,
               abs(currentCut.endSeconds - cut.endSeconds) < 0.000_1,
               let activated = shotSettingJoinRepair(
                   updated,
                   shotId: shotId,
                   cutId: cutId,
                   repair: ShotRazorJoinRepair(
                       mode: .generatedBridge,
                       activeBridgeVersionId: artifact.versionId
                   ),
                   now: artifact.updatedAt
               ) {
                updated = activated
            }
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: artifact.updatedAt) { _ in updated },
                for: project
            )
            let durationMs = Int(Date().timeIntervalSince(startedAt) * 1_000)
            logGeneration(
                kind: "video.completed",
                message: "Shot join bridge completed shot_id=\(shotId) cut_id=\(cutId) request_id=\(result.requestId) duration_ms=\(durationMs)"
            )
            // No reachable rate for bridge endpoints — honestly unpriced.
            recordSpend(SpendLedgerEntry(
                kind: "join_bridge",
                provider: provider.rawValue,
                model: provider.modelId,
                requestId: result.requestId,
                contextLabel: spendContextLabel(shotId: shotId),
                shotId: shotId,
                unit: "seconds",
                unitCount: Double(durationSeconds)
            ))
            aestheticStatus = "Join bridge ready"
            return true
        } catch {
            if let falFailure = error as? FALWorkflowFailure {
                artifact.requestId = falFailure.jobId
            }
            artifact.status = "failed"
            artifact.errorMessage = shortSummaryText(error.localizedDescription, limit: 500)
            artifact.updatedAt = DateFormats.now()
            if currentProject?.projectId == project.projectId,
               shotTimeline.shots.contains(where: { $0.shotId == shotId }) {
                persistShotTimeline(
                    shotTimeline.updatingShot(shotId: shotId, now: artifact.updatedAt) {
                        $0.upsertingJoinBridgeVersion(artifact, now: artifact.updatedAt)
                    },
                    for: project
                )
            }
            let durationMs = Int(Date().timeIntervalSince(startedAt) * 1_000)
            logGeneration(
                kind: "video.error",
                message: "Shot join bridge error shot_id=\(shotId) cut_id=\(cutId) request_id=\(artifact.requestId.nilIfEmpty ?? "-") duration_ms=\(durationMs) error=\(artifact.errorMessage)"
            )
            if !(Task.isCancelled || isCancellationLikeError(error)) {
                recordSpend(SpendLedgerEntry(
                    kind: "join_bridge",
                    provider: provider.rawValue,
                    model: provider.modelId,
                    requestId: artifact.requestId,
                    contextLabel: spendContextLabel(shotId: shotId),
                    shotId: shotId,
                    status: "failed_unknown_charge"
                ))
            }
            aestheticStatus = "Join bridge failed — current edit preserved"
            lastError = error.localizedDescription
            return false
        }
    }

    private func shotJoinSourceClip(
        shot: ProjectShot,
        cut: ShotSegmentCutRange
    ) -> ShotRenderSegmentClip? {
        if let exact = (shot.activeRenderVersion?.segmentClips ?? [])
            .first(where: { $0.placementKey == cut.segmentKey })
            ?? shot.seedSegmentClips.first(where: { $0.placementKey == cut.segmentKey }) {
            if !cut.clipPath.isEmpty, exact.clipPath != cut.clipPath { return nil }
            return exact
        }
        let parts = cut.segmentKey.split(separator: ">", maxSplits: 1, omittingEmptySubsequences: false)
        guard let first = parts.first else { return nil }
        let end = parts.count > 1 ? String(parts[1]) : ""
        let saved = shot.activeRenderVersion?.segmentClip(forStart: String(first), end: end)
        guard let saved else { return nil }
        if !cut.clipPath.isEmpty, saved.clipPath != cut.clipPath { return nil }
        return saved
    }

    /// Exact, free preflight frames for the reviewed join-render surface.
    /// Cached by source file identity + cut bounds; no provider call occurs.
    func prepareShotRazorJoinFrames(shotId: String, cutId: String) async -> ShotJoinBoundaryPreview? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let cut = shot.cutList.segmentCuts.first(where: { $0.id == cutId }),
              let sourceClip = shotJoinSourceClip(shot: shot, cut: cut),
              FileManager.default.fileExists(atPath: sourceClip.clipPath) else { return nil }
        let attributes = (try? FileManager.default.attributesOfItem(atPath: sourceClip.clipPath)) ?? [:]
        let fingerprint = shortHash(
            "\(sourceClip.clipPath)|\(attributes[.size] ?? 0)|\(attributes[.modificationDate] ?? "")|\(String(format: "%.3f", cut.startSeconds))|\(String(format: "%.3f", cut.endSeconds))",
            length: 20
        )
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("shot_join_previews", isDirectory: true)
        let outgoingURL = directory.appendingPathComponent("\(fingerprint)_out.png")
        let incomingURL = directory.appendingPathComponent("\(fingerprint)_in.png")
        if FileManager.default.fileExists(atPath: outgoingURL.path),
           FileManager.default.fileExists(atPath: incomingURL.path) {
            return ShotJoinBoundaryPreview(
                outgoingURL: outgoingURL,
                incomingURL: incomingURL,
                fingerprint: fingerprint
            )
        }
        do {
            try ensureDirectory(directory)
            let outgoingRaw = directory.appendingPathComponent("\(fingerprint)_out_raw.png")
            let incomingRaw = directory.appendingPathComponent("\(fingerprint)_in_raw.png")
            _ = try await VideoChainMedia.extractFrameStill(
                videoURL: URL(fileURLWithPath: sourceClip.clipPath),
                atSeconds: max(cut.startSeconds - ShotAudioTiming.frameSeconds, 0),
                outputURL: outgoingRaw
            )
            _ = try await VideoChainMedia.extractFrameStill(
                videoURL: URL(fileURLWithPath: sourceClip.clipPath),
                atSeconds: cut.endSeconds,
                outputURL: incomingRaw
            )
            let profile = VideoOutputProfile.standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
            _ = try VideoChainMedia.normalizeImageFrame(
                sourceURL: outgoingRaw,
                outputURL: outgoingURL,
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            _ = try VideoChainMedia.normalizeImageFrame(
                sourceURL: incomingRaw,
                outputURL: incomingURL,
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            return ShotJoinBoundaryPreview(
                outgoingURL: outgoingURL,
                incomingURL: incomingURL,
                fingerprint: fingerprint
            )
        } catch {
            lastError = error.localizedDescription
            return nil
        }
    }

    /// The VISIBLE assembly, which serves both of this function's consumers.
    /// `joinMaterialStart` reads `planClips`, and material space is never
    /// mirrored, so it stays in authoring coordinates either way; the audio
    /// ripple in `shotSettingJoinRepair` positions overlays in OUTPUT seconds,
    /// which is exactly the space reverse changes.
    ///
    /// The whole-output loop is EXCLUDED: overlays persist at BASE output
    /// seconds (pass replication is mix-time), so ripple deltas computed from
    /// an N×-long assembly would shift them N times too far.
    private func shotJoinAssembly(shot: ProjectShot, shotId: String) -> ShotCutAssembly {
        let plan = shotRenderPromptPlan(shotId: shotId)
        return shotVisibleCutAssembly(
            shot: shot,
            planSegments: plan?.segments ?? [],
            clipDurationsByPath: [:],
            includeOutputLoop: false
        )
    }

    private func joinMaterialStart(cut: ShotSegmentCutRange, assembly: ShotCutAssembly) -> Double {
        guard let clip = assembly.planClips.first(where: {
            $0.segmentKey == cut.segmentKey && (cut.clipPath.isEmpty || $0.clipPath == cut.clipPath)
        }) else { return 0 }
        return clip.materialStartSeconds + max(cut.startSeconds - clip.headSeconds, 0)
    }

    private func shotSettingJoinRepair(
        _ shot: ProjectShot,
        shotId: String,
        cutId: String,
        repair: ShotRazorJoinRepair,
        now: String
    ) -> ProjectShot? {
        guard let cut = shot.cutList.segmentCuts.first(where: { $0.id == cutId }) else { return nil }
        if repair.mode == .generatedBridge {
            guard let artifact = shot.joinBridgeVersion(repair.activeBridgeVersionId),
                  artifact.isReady,
                  artifact.cutId == cutId else { return nil }
        }
        let oldAssembly = shotJoinAssembly(shot: shot, shotId: shotId)
        let oldBridge = oldAssembly.playbackItems.first { $0.cutId == cutId }
        let rippleStart = oldBridge?.outputStartSeconds
            ?? oldAssembly.outputSeconds(forMaterialSeconds: joinMaterialStart(cut: cut, assembly: oldAssembly))
        var list = shot.cutList
        guard let index = list.segmentCuts.firstIndex(where: { $0.id == cutId }) else { return nil }
        list.segmentCuts[index].joinRepair = repair.normalized()
        list.segmentCuts[index].updatedAt = now
        var updated = shot.settingCutList(list, now: now)
        let newAssembly = shotJoinAssembly(shot: updated, shotId: shotId)
        let newBridge = newAssembly.playbackItems.first { $0.cutId == cutId }
        let delta = (newBridge?.durationSeconds ?? 0) - (oldBridge?.durationSeconds ?? 0)
        if abs(delta) > 0.000_1 {
            updated = updated.settingAudioMix(
                shot.audioMix.ripplingPlacements(atOrAfter: rippleStart, by: delta),
                now: now
            )
            updated = updated.ripplingAudioRegions(
                atOrAfter: rippleStart,
                by: delta,
                now: now
            )
        }
        return updated
    }

    private func shotRemovingRazorCut(
        _ shot: ProjectShot,
        shotId: String,
        cutId: String,
        now: String
    ) -> ProjectShot? {
        guard let cut = shot.cutList.segmentCuts.first(where: { $0.id == cutId }) else { return nil }
        let assembly = shotJoinAssembly(shot: shot, shotId: shotId)
        // R2 of THE SPEED SECTION LINK LAW: restoring a carrier razor takes
        // its speed copy with it — the material returns at 1×, exactly once.
        // This chokepoint covers the popover RESTORE (incl. the razor-block
        // fold), the pin sweep, and the clip-range shed; the sweep's own
        // stale-insertion pass then finds nothing left (set-based, idempotent).
        let carriers = shotSectionCarrierIds(insertions: shot.pictureInsertions, cutId: cutId)
        if !carriers.isEmpty {
            let rippleStart = assembly.insertionCells
                .filter { carriers.contains($0.insertion.insertionId) }
                .map(\.outputStartSeconds)
                .min()
                ?? assembly.outputSeconds(forMaterialSeconds: joinMaterialStart(cut: cut, assembly: assembly))
            var list = shot.cutList
            list.segmentCuts.removeAll { $0.id == cutId }
            var updated = shot.settingCutList(list, now: now)
            updated.pictureInsertions.removeAll { carriers.contains($0.insertionId) }
            updated.updatedAt = now
            let newVisible = shotJoinAssembly(shot: updated, shotId: shotId)
            return shotRipplingOverlays(
                updated,
                rippleStart: rippleStart,
                delta: newVisible.outputSeconds - assembly.outputSeconds,
                now: now
            )
        }
        let bridgeItem = assembly.playbackItems.first { $0.cutId == cutId }
        let recordedBridgeDuration: Double = {
            guard cut.joinRepair.mode == .generatedBridge,
                  let artifact = shot.joinBridgeVersion(cut.joinRepair.activeBridgeVersionId),
                  artifact.isReady else { return 0 }
            return artifact.durationSeconds
        }()
        let rippleStart = bridgeItem?.outputStartSeconds
            ?? assembly.outputSeconds(forMaterialSeconds: joinMaterialStart(cut: cut, assembly: assembly))
        var list = shot.cutList
        list.segmentCuts.removeAll { $0.id == cutId }
        var updated = shot.settingCutList(list, now: now)
        let removedDuration = bridgeItem?.durationSeconds ?? recordedBridgeDuration
        if removedDuration > 0 {
            updated = updated.settingAudioMix(
                shot.audioMix.ripplingPlacements(
                    atOrAfter: rippleStart,
                    by: -removedDuration
                ),
                now: now
            )
            updated = updated.ripplingAudioRegions(
                atOrAfter: rippleStart,
                by: -removedDuration,
                now: now
            )
        }
        return updated
    }

    /// One mix-only edit = one persisted transaction returning a whole-state
    /// edit so the caller can register a symmetric Undo action. Deliberately
    /// does NOT regionize: lane controls exist on legacy and regionized shots
    /// alike, and a header mute must never trigger the irreversible region
    /// migration as a side effect.
    private func commitShotAudioMixEdit(
        shotId: String,
        status: String?,
        _ transform: (ShotAudioMix) -> ShotAudioMix
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let updated = shot.settingAudioMix(transform(shot.audioMix), now: now)
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(shot),
            after: shotAudioStateSnapshot(updated),
            affectedRegionId: ""
        )
        guard edit.before != edit.after else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        if let status { aestheticStatus = status }
        return edit
    }

    @discardableResult
    func setShotAudioLaneEnabled(shotId: String, laneId: String, enabled: Bool) -> ShotAudioStateEdit? {
        commitShotAudioMixEdit(shotId: shotId, status: nil) {
            $0.settingLaneEnabled(laneId, enabled: enabled)
        }
    }

    @discardableResult
    func setShotAudioLaneVolume(shotId: String, laneId: String, volume: Double) -> ShotAudioStateEdit? {
        commitShotAudioMixEdit(shotId: shotId, status: nil) {
            $0.settingLaneVolume(laneId, volume: volume)
        }
    }

    /// Adds an empty extra row of a kind (clip, ambient, or microphone).
    @discardableResult
    func addShotAudioLane(shotId: String, kind: String) -> ShotAudioStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let added = shot.audioMix.addingLane(kind: kind) else { return nil }
        return commitShotAudioMixEdit(
            shotId: shotId,
            status: "Added a \(ShotAudioLane.canonical(added.laneId).label) row"
        ) {
            $0.addingLane(kind: kind)?.mix ?? $0
        }
    }

    /// Removes an extra row, and ONLY when it is empty. Removal is never a way
    /// to delete audio: a row with regions offers "move its regions first"
    /// instead, so no gesture here can silently discard a placement.
    @discardableResult
    func removeShotAudioLane(shotId: String, laneId: String) -> ShotAudioStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        guard shot.audioRegions.allSatisfy({ $0.laneId != laneId }) else {
            aestheticStatus = "Move this row's audio to another row before removing it"
            return nil
        }
        guard shot.audioMix.removingLane(laneId) != nil else { return nil }
        let label = shot.audioMix.lane(laneId).label
        return commitShotAudioMixEdit(shotId: shotId, status: "Removed the \(label) row") {
            $0.removingLane(laneId) ?? $0
        }
    }

    /// Moves one region to a sibling row. Its own op because
    /// `setShotAudioRegion` deliberately refuses lane changes — region identity
    /// belongs to the replace/move ops, not to a geometry write. Returns the
    /// pre-move snapshot for undo.
    @discardableResult
    func moveShotAudioRegionToLane(
        shotId: String,
        regionId: String,
        laneId: String
    ) -> ShotAudioRegion? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let existing = base.audioRegions.first(where: { $0.regionId == regionId }),
              existing.laneId != ShotAudioLaneId.source,
              existing.laneId != laneId,
              laneId != ShotAudioLaneId.source,
              // Rows of a different kind hold different media and different
              // behavior; moving across kinds would be a replace, not a move.
              ShotAudioLaneId.kind(ofLaneId: laneId)
                  == ShotAudioLaneId.kind(ofLaneId: existing.laneId) else {
            return nil
        }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                regionizedForAudioEdit(current, now: now)
                    .updatingAudioRegion(regionId: regionId, now: now) { $0.laneId = laneId }
            },
            for: project
        )
        aestheticStatus = "Moved to the \(shot.audioMix.lane(laneId).label) row"
        return existing
    }

    /// Activating a take is an audible state change (it swaps which take
    /// region plays), so it returns a whole-state edit for symmetric Undo.
    @discardableResult
    func activateShotMicrophoneTake(shotId: String, takeId: String) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        var next = shot.settingAudioMix(
            shot.audioMix.activatingMicrophoneTake(takeId),
            now: now
        )
        // Regionized shots: activation = swapping which take REGION
        // is audible (the pointer above is an inert mirror there).
        if !next.audioRegions.isEmpty,
           next.audioRegions.contains(where: {
               $0.laneId == ShotAudioLaneId.microphone && $0.sourceArtifactId == takeId
           }) {
            var regions = next.audioRegions
            for index in regions.indices
                where regions[index].laneId == ShotAudioLaneId.microphone
                    && ["microphone_take", "active_microphone_take"].contains(regions[index].provenance) {
                regions[index].isMuted = regions[index].sourceArtifactId != takeId
            }
            next = next.settingAudioRegions(regions, now: now)
        }
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(shot),
            after: shotAudioStateSnapshot(next),
            affectedRegionId: ""
        )
        guard edit.before != edit.after else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in next },
            for: project
        )
        aestheticStatus = "Microphone take selected"
        return edit
    }

    /// Moves a finished scratch recording into the project and only then
    /// publishes it in shot state. A failed document save restores the scratch
    /// file, so persistence never points at a missing take.
    func commitShotMicrophoneTake(
        shotId: String,
        recording: ShotMicrophoneRecordingResult,
        startSeconds: Double
    ) async -> ShotMicrophoneTake? {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }),
              FileManager.default.fileExists(atPath: recording.url.path) else {
            aestheticStatus = "The microphone take could not be saved"
            return nil
        }

        let asset = AVURLAsset(url: recording.url)
        let assetDuration = (try? await asset.load(.duration).seconds) ?? recording.durationSeconds
        let duration = max(assetDuration.isFinite ? assetDuration : recording.durationSeconds, 0)
        guard duration >= 0.2,
              currentProject?.projectId == project.projectId,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else {
            aestheticStatus = "The microphone take was too short to keep"
            return nil
        }

        let now = DateFormats.now()
        let takeId = "mic_\(shortHash("\(project.projectId):\(shotId):\(now):\(UUID().uuidString)", length: 16))"
        let directory = contextStore.shotAudioDirectory(for: project, shotId: shotId)
        let destination = directory.appendingPathComponent("\(takeId).m4a")
        let capturedStart = ShotAudioTiming.normalizedStart(
            startSeconds,
            timelineDuration: shotDurationSeconds(shotId: shotId)
        )
        let take = ShotMicrophoneTake(
            takeId: takeId,
            path: destination.path,
            startSeconds: capturedStart,
            recordedStartSeconds: capturedStart,
            durationSeconds: duration,
            inputDeviceId: recording.inputDeviceId,
            inputDeviceName: recording.inputDeviceName,
            createdAt: now
        ).normalized()
        let updated = shotTimeline.updatingShot(shotId: shotId, now: now) { shot in
            var next = shot.settingAudioMix(shot.audioMix.appendingMicrophoneTake(take), now: now)
            // On a regionized shot the take record is history; playback truth
            // is the region. The new take arrives audible and other take
            // regions mute, mirroring the legacy "newest take is active" law.
            if !next.audioRegions.isEmpty {
                var regions = next.audioRegions
                for index in regions.indices
                    where regions[index].laneId == ShotAudioLaneId.microphone
                        && ["microphone_take", "active_microphone_take"].contains(regions[index].provenance) {
                    regions[index].isMuted = true
                }
                regions.append(ShotAudioRegion(
                    regionId: "audio_region_\(shortHash("regionize:\(shotId):\(ShotAudioLaneId.microphone):\(take.takeId)", length: 12))",
                    laneId: ShotAudioLaneId.microphone,
                    label: "Mic take",
                    path: take.path,
                    sourceCutId: shotId,
                    sourceArtifactId: take.takeId,
                    provenance: "microphone_take",
                    startSeconds: take.startSeconds,
                    durationSeconds: take.durationSeconds,
                    sourceDurationSeconds: take.durationSeconds,
                    gain: next.audioMix.lane(ShotAudioLaneId.microphone).volume
                ).normalized())
                next = next.settingAudioRegions(regions, now: now)
            }
            return next
        }

        do {
            try ensureDirectory(directory)
            try FileManager.default.moveItem(at: recording.url, to: destination)
            do {
                try contextStore.saveShotTimeline(updated, for: project)
                shotTimeline = updated
                aestheticStatus = "Microphone take recorded"
                return take
            } catch {
                try? FileManager.default.moveItem(at: destination, to: recording.url)
                throw error
            }
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "The microphone take could not be saved"
            return nil
        }
    }

    /// Sends the audio file to the macOS Trash, then removes its take record.
    /// If shot persistence fails, the trashed item is restored when possible.
    @discardableResult
    func deleteShotMicrophoneTake(shotId: String, takeId: String) -> Bool {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let take = shot.audioMix.lane(ShotAudioLaneId.microphone).microphoneTakes
                .first(where: { $0.takeId == takeId }) else {
            return false
        }
        let sourceURL = URL(fileURLWithPath: take.path)
        var trashedURL: NSURL?
        do {
            if FileManager.default.fileExists(atPath: sourceURL.path) {
                try FileManager.default.trashItem(at: sourceURL, resultingItemURL: &trashedURL)
            }
            let now = DateFormats.now()
            let updated = shotTimeline.updatingShot(shotId: shotId, now: now) { shot in
                var next = shot.settingAudioMix(shot.audioMix.removingMicrophoneTake(takeId), now: now)
                // The audio file is in the Trash: a region still pointing at
                // it would be a silent lie, so take regions leave with it.
                if !next.audioRegions.isEmpty {
                    next.audioRegions.removeAll {
                        $0.laneId == ShotAudioLaneId.microphone && $0.sourceArtifactId == takeId
                    }
                }
                return next
            }
            do {
                try contextStore.saveShotTimeline(updated, for: project)
                shotTimeline = updated
                aestheticStatus = "Microphone take moved to Trash"
                return true
            } catch {
                if let trashedURL,
                   !FileManager.default.fileExists(atPath: sourceURL.path) {
                    try? FileManager.default.moveItem(at: trashedURL as URL, to: sourceURL)
                }
                throw error
            }
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "The microphone take could not be deleted"
            return false
        }
    }

    // MARK: - Ambient beds

    private func ambientBedFileURL(_ record: AmbientBedRecord, project: ProjectRecord) -> URL {
        let fileName = record.fileName.trimmed.isEmpty
            ? ambientBedFileName(bedId: record.bedId, format: .m4a)
            : record.fileName.trimmed
        return contextStore.ambientBedDirectory(for: project).appendingPathComponent(fileName)
    }

    /// Bakes the spec locally (no provider call), promotes the file into
    /// story/ambient/, and upserts the library record. The bedId is the
    /// normalized-spec hash, so re-baking an identical spec replaces the same
    /// bed and file instead of stacking a duplicate.
    @discardableResult
    func saveAmbientBed(spec: AmbientBedSpec) async -> AmbientBedRecord? {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return nil
        }
        guard !isBakingAmbientBed else { return nil }
        isBakingAmbientBed = true
        // This flag disables the only control that can clear it (the
        // saveVideoTrim law): any exit that skips the reset strands BAKE
        // until relaunch.
        defer { isBakingAmbientBed = false }
        lastError = ""
        let normalizedSpec = spec.normalized()
        let bedId = ambientBedId(spec: normalizedSpec)
        aestheticStatus = "Baking ambient bed"
        do {
            let baked = try await AmbientBedBaker.bake(spec: normalizedSpec)
            let scratchDirectory = baked.fileURL.deletingLastPathComponent()
            defer { try? FileManager.default.removeItem(at: scratchDirectory) }
            guard currentProject?.projectId == project.projectId else { return nil }

            let directory = contextStore.ambientBedDirectory(for: project)
            try ensureDirectory(directory)
            let fileName = ambientBedFileName(bedId: bedId, format: baked.format)
            let destination = directory.appendingPathComponent(fileName)
            let replacesExistingFile = FileManager.default.fileExists(atPath: destination.path)
            if replacesExistingFile {
                _ = try FileManager.default.replaceItemAt(destination, withItemAt: baked.fileURL)
            } else {
                try FileManager.default.moveItem(at: baked.fileURL, to: destination)
            }
            // A re-bake that changed container format must not leave the
            // other-extension sibling behind as a stale twin.
            let otherFormat: AmbientBedBakeFormat = baked.format == .m4a ? .caf : .m4a
            try? FileManager.default.removeItem(
                at: directory.appendingPathComponent(ambientBedFileName(bedId: bedId, format: otherFormat))
            )

            let now = DateFormats.now()
            let existing = ambientBedLibrary.bed(bedId)
            let inheritedName = (existing?.displayName.trimmed).flatMap { $0.isEmpty ? nil : $0 }
            let record = AmbientBedRecord(
                bedId: bedId,
                displayName: inheritedName ?? ambientBedAutoName(spec: normalizedSpec),
                spec: normalizedSpec,
                fileName: fileName,
                durationSeconds: baked.durationSeconds,
                createdAt: existing?.createdAt ?? now,
                updatedAt: now
            )
            let updated = ambientBedLibrary.upserting(record)
            do {
                try contextStore.saveAmbientBedLibrary(updated, for: project)
                ambientBedLibrary = updated
            } catch {
                // No record without file, no file without record (mic-take
                // rollback law) — unless this bake merely replaced an existing
                // bed's file, in which case the surviving record still points
                // at a valid file.
                if existing == nil, !replacesExistingFile {
                    try? FileManager.default.removeItem(at: destination)
                }
                throw error
            }
            aestheticStatus = "Ambient bed baked"
            touchCurrentProject()
            return updated.bed(bedId)
        } catch is CancellationError {
            aestheticStatus = "Ambient bake cancelled"
            return nil
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "The ambient bed could not be baked"
            return nil
        }
    }

    /// Attaches a library bed to the shot's ambient lane (nil detaches). The
    /// absolute file path is recomputed here, so re-picking a bed after a
    /// project relocation heals the lane.
    func setShotAmbientBed(shotId: String, bedId: String?) {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else { return }
        let cleanedBedId = (bedId ?? "").trimmed
        let record = cleanedBedId.isEmpty ? nil : ambientBedLibrary.bed(cleanedBedId)
        if !cleanedBedId.isEmpty, record == nil {
            aestheticStatus = "That ambient bed is no longer in the library"
            return
        }
        let path = record.map { ambientBedFileURL($0, project: project).path }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.settingAudioMix($0.audioMix.settingAmbientBed(bedId: record?.bedId, path: path), now: now)
            },
            for: project
        )
        aestheticStatus = record == nil ? "Ambient bed detached" : "Ambient bed attached"
    }

    /// Attaches an imported audio file to a shot, or detaches with nil.
    /// Mirrors `setShotAmbientBed`: the path is resolved from the media item at
    /// attach time so playback never depends on a live lookup, and a clip that
    /// has left the project refuses rather than attaching a dead pointer.
    func setShotAudioClip(shotId: String, mediaId: String?) {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else { return }
        let cleanedMediaId = (mediaId ?? "").trimmed
        let item = cleanedMediaId.isEmpty
            ? nil
            : items.first { $0.mediaId == cleanedMediaId && $0.kind == .audio }
        if !cleanedMediaId.isEmpty, item == nil {
            aestheticStatus = "That audio clip is no longer in this project"
            return
        }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.settingAudioMix(
                    $0.audioMix.settingAudioClip(mediaId: item?.mediaId, path: item?.path),
                    now: now
                )
            },
            for: project
        )
        aestheticStatus = item == nil ? "Audio clip detached" : "Attached \(item!.filename)"
    }

    /// Migrate-on-write: every region op regionizes a legacy shot first, so
    /// multi-region audio is legal on EVERY cut. Regionization is pure and
    /// deterministic (stable ids), so the lane UI's `legacyAudioRegionPreview`
    /// regions resolve to real persisted regions on the first edit.
    private func regionizedForAudioEdit(_ shot: ProjectShot, now: String) -> ProjectShot {
        shot.regionizingLegacyAudio(
            now: now,
            timelineSeconds: shotDurationSeconds(shotId: shot.shotId),
            ambientBedDurationSeconds: shot.audioMix.lane(ShotAudioLaneId.ambient).ambientBedId
                .flatMap { ambientBedLibrary.bed($0)?.durationSeconds },
            clipMediaDurationSeconds: shot.audioMix.lane(ShotAudioLaneId.clip).clipMediaId
                .flatMap { id in items.first { $0.mediaId == id }?.durationSeconds }
        )
    }

    private func shotAudioStateSnapshot(_ shot: ProjectShot) -> ShotAudioStateSnapshot {
        ShotAudioStateSnapshot(
            audioMix: shot.audioMix.normalized(),
            audioRegions: shot.audioRegions.map { $0.normalized() }
        )
    }

    /// One committed region edit = one persisted transaction, returning the
    /// PRE-edit snapshot so the caller can register a single UndoManager
    /// action. The source lane refuses: its regions are picture-locked gain
    /// windows over the composition tracks.
    private func commitShotAudioRegionEdit(
        shotId: String,
        regionId: String,
        status: String,
        _ transform: (ShotAudioRegion, Double) -> ShotAudioRegion
    ) -> ShotAudioRegion? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let existing = base.audioRegions.first(where: { $0.regionId == regionId }),
              existing.laneId != ShotAudioLaneId.source else { return nil }
        let updated = transform(existing, shotDurationSeconds(shotId: shotId)).normalized()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                regionizedForAudioEdit(current, now: now)
                    .updatingAudioRegion(regionId: regionId, now: now) { $0 = updated }
            },
            for: project
        )
        aestheticStatus = status
        return existing
    }

    /// Adds media on the next numbered row of an extendable lane kind. The
    /// row does not need a separate write: `addShotAudioRegion` prepares an
    /// unknown lane and places its first region in the same state transaction,
    /// so Undo removes both rather than leaving an empty row behind.
    @discardableResult
    func addShotAudioTrack(
        shotId: String,
        kind: String,
        asset: ShotAudioAssetReference,
        startSeconds: Double
    ) -> ShotAudioStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let cleanedKind = kind.trimmed.lowercased()
        guard ShotAudioLaneId.extendable.contains(cleanedKind) else { return nil }
        let base = regionizedForAudioEdit(shot, now: DateFormats.now())
        let existingLaneIds = Set(base.audioMix.normalized().lanes.map(\.laneId))
            .union(base.audioRegions.map(\.laneId))
            .union([cleanedKind])
        let laneId = ShotAudioLaneId.nextLaneId(
            kind: cleanedKind,
            existing: existingLaneIds
        )
        return addShotAudioRegion(
            shotId: shotId,
            laneId: laneId,
            asset: asset,
            startSeconds: startSeconds
        )
    }

    /// Adds media to any CUT's audio lane at the given start without
    /// replacing other placements on that lane. Project Audio is legal on
    /// narration, mic, clip, and ambient; generated beds are ambient-only.
    /// Every placement prepares the lane for audible playback in the SAME
    /// transaction. The returned whole-state edit keeps that lane change and
    /// the region addition one symmetric Undo step.
    /// Resolves one asset into a placed, normalized region — the shared
    /// start/duration/provenance law behind the single add and the batch add.
    /// Refusal statuses live here so both paths report the same truth.
    private func builtShotAudioRegion(
        laneId: String,
        asset: ShotAudioAssetReference,
        startSeconds: Double,
        timelineSeconds: Double
    ) -> ShotAudioRegion? {
        guard let project = currentProject else { return nil }
        let start = timelineSeconds > 0
            ? ShotAudioTiming.normalizedStart(startSeconds, timelineDuration: timelineSeconds)
            : ShotAudioTiming.frameQuantizedStart(max(startSeconds, 0))
        // An unrendered cut has no timeline yet; the region then keeps its
        // media's own length and playback clamps at composition build time.
        let remainingSeconds = timelineSeconds > 0
            ? max(timelineSeconds - start, ShotAudioTiming.frameSeconds)
            : Double.infinity
        let region: ShotAudioRegion
        let kind = ShotAudioLaneId.kind(ofLaneId: laneId)
        switch asset {
        case .projectAudio(let mediaId):
            guard [
                ShotAudioLaneId.clip,
                ShotAudioLaneId.narration,
                ShotAudioLaneId.microphone,
                ShotAudioLaneId.ambient
            ].contains(kind) else {
                return nil
            }
            guard let item = items.first(where: {
                $0.mediaId == mediaId && $0.kind == .audio
            }) else {
                aestheticStatus = "That audio clip is no longer in this project"
                return nil
            }
            let assetSeconds = item.durationSeconds ?? (remainingSeconds.isFinite ? remainingSeconds : 0)
            let duration = kind == ShotAudioLaneId.ambient && remainingSeconds.isFinite
                ? remainingSeconds
                : min(max(assetSeconds, ShotAudioTiming.frameSeconds), remainingSeconds)
            guard duration.isFinite, duration > 0 else {
                aestheticStatus = "That audio clip has no readable duration yet"
                return nil
            }
            let provenance: String
            switch kind {
            case ShotAudioLaneId.narration: provenance = "imported_narration_audio"
            case ShotAudioLaneId.microphone: provenance = "imported_microphone_audio"
            case ShotAudioLaneId.ambient: provenance = "operator_ambient_audio"
            default: provenance = "operator_audio_clip"
            }
            region = ShotAudioRegion(
                regionId: "audio_region_\(UUID().uuidString.lowercased())",
                laneId: laneId,
                label: item.filename,
                path: item.path,
                mediaId: item.mediaId,
                provenance: provenance,
                startSeconds: start,
                durationSeconds: duration,
                sourceDurationSeconds: item.durationSeconds,
                gain: 1,
                isMuted: false,
                loops: kind == ShotAudioLaneId.ambient
            )
        case .ambientBed(let bedId):
            guard kind == ShotAudioLaneId.ambient else { return nil }
            guard let record = ambientBedLibrary.bed(bedId) else {
                aestheticStatus = "That ambient bed is no longer in the library"
                return nil
            }
            let duration = remainingSeconds.isFinite
                ? remainingSeconds
                : max(record.durationSeconds, 0)
            guard duration > 0 else {
                aestheticStatus = "Render the cut before laying an ambient bed"
                return nil
            }
            region = ShotAudioRegion(
                regionId: "audio_region_\(UUID().uuidString.lowercased())",
                laneId: laneId,
                label: record.displayName,
                path: ambientBedFileURL(record, project: project).path,
                mediaId: record.bedId,
                provenance: "operator_ambient_bed",
                startSeconds: start,
                durationSeconds: duration,
                sourceDurationSeconds: record.durationSeconds > 0 ? record.durationSeconds : nil,
                gain: 1,
                isMuted: false,
                loops: true
            )
        }
        return region.normalized()
    }

    @discardableResult
    func addShotAudioRegion(
        shotId: String,
        laneId: String,
        asset: ShotAudioAssetReference,
        startSeconds: Double
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let normalizedRegion = builtShotAudioRegion(
            laneId: laneId,
            asset: asset,
            startSeconds: startSeconds,
            timelineSeconds: shotDurationSeconds(shotId: shotId)
        ) else { return nil }
        let prepared = base.settingAudioMix(
            base.audioMix.preparingLaneForNewAudio(laneId),
            now: now
        ).settingAudioRegions(
            base.audioRegions + [normalizedRegion],
            now: now
        )
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(prepared),
            affectedRegionId: normalizedRegion.regionId
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in prepared },
            for: project
        )
        aestheticStatus = "Added \(normalizedRegion.label.trimmed.nilIfEmpty ?? "audio") to the \(ShotAudioLane.canonical(laneId).label) lane"
        return edit
    }

    /// Adds several assets to one lane in ONE persisted transaction and one
    /// whole-state edit, so a multi-file drop or import is a single Undo step.
    /// Non-ambient kinds place end-to-end from the drop point; AMBIENT layers
    /// every file at the same placement (its regions loop to the shot end, so
    /// a cursor would push later files off the timeline). The affected region
    /// is the last added, matching the old per-file selection behavior.
    @discardableResult
    func addShotAudioRegionBatch(
        shotId: String,
        laneId: String,
        assets: [ShotAudioAssetReference],
        startSeconds: Double
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              !assets.isEmpty else { return nil }
        let now = DateFormats.now()
        var working = regionizedForAudioEdit(shot, now: now)
        let before = shotAudioStateSnapshot(working)
        let timelineSeconds = shotDurationSeconds(shotId: shotId)
        let layersAtPlacement = ShotAudioLaneId.kind(ofLaneId: laneId) == ShotAudioLaneId.ambient
        var cursor = startSeconds
        var lastAddedId: String?
        var addedCount = 0
        for asset in assets {
            guard let region = builtShotAudioRegion(
                laneId: laneId,
                asset: asset,
                startSeconds: cursor,
                timelineSeconds: timelineSeconds
            ) else { continue }
            working = working.settingAudioRegions(working.audioRegions + [region], now: now)
            lastAddedId = region.regionId
            addedCount += 1
            if !layersAtPlacement { cursor = region.endSeconds }
        }
        guard let lastAddedId else { return nil }
        working = working.settingAudioMix(
            working.audioMix.preparingLaneForNewAudio(laneId),
            now: now
        )
        let edit = ShotAudioStateEdit(
            before: before,
            after: shotAudioStateSnapshot(working),
            affectedRegionId: lastAddedId
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in working },
            for: project
        )
        aestheticStatus = addedCount == 1
            ? "Added audio to the \(ShotAudioLane.canonical(laneId).label) lane"
            : "Added \(addedCount) audio files to the \(ShotAudioLane.canonical(laneId).label) lane"
        return edit
    }

    /// Lands a clipboard payload as a NEW region: fresh id, lane resolved by
    /// the three-rung paste law (`shotAudioPasteLaneId`), geometry re-clamped
    /// against THIS shot's timeline. Unlike `addShotAudioRegion` it does NOT
    /// resolve a library asset — a paste must preserve trim/gain/loops/rate/
    /// fades even when the media is absent from this project's library (the
    /// MISSING hatch + relink flow covers recovery). Lane prep + insert land
    /// in one transaction, matching Add.
    @discardableResult
    func pasteShotAudioRegion(
        shotId: String,
        payload: ShotAudioRegionClipboardPayload,
        preferredLaneId: String?,
        startSeconds: Double
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              payload.isPasteable else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let laneId = shotAudioPasteLaneId(
            payloadLaneId: payload.region.laneId,
            preferredLaneId: preferredLaneId,
            rows: shotAudioLaneRows(mix: base.audioMix, regions: base.audioRegions)
        ) else { return nil }
        let pasted = payload.region.normalized().pastedCopy(
            regionId: "audio_region_\(UUID().uuidString.lowercased())",
            laneId: laneId,
            startSeconds: startSeconds,
            timelineSeconds: shotDurationSeconds(shotId: shotId)
        )
        let prepared = base.settingAudioMix(
            base.audioMix.preparingLaneForNewAudio(laneId),
            now: now
        ).settingAudioRegions(
            base.audioRegions + [pasted],
            now: now
        )
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(prepared),
            affectedRegionId: pasted.regionId
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in prepared },
            for: project
        )
        aestheticStatus = "Pasted \(pasted.label.trimmed.nilIfEmpty ?? "audio") onto the \(ShotAudioLane.canonical(laneId).label) lane"
        return edit
    }

    /// Duplicates a region in place: the copy butt-joins at the original's
    /// EXACT end — unquantized, the drag family, so the seam is sample-tight
    /// (playhead-family ops quantize; a duplicate has no playhead in it).
    @discardableResult
    func duplicateShotAudioRegion(shotId: String, regionId: String) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let region = base.audioRegions.first(where: { $0.regionId == regionId }),
              region.laneId != ShotAudioLaneId.source else { return nil }
        let copy = region.pastedCopy(
            regionId: "audio_region_\(UUID().uuidString.lowercased())",
            laneId: region.laneId,
            startSeconds: region.endSeconds,
            timelineSeconds: shotDurationSeconds(shotId: shotId)
        )
        let updated = base.settingAudioRegions(base.audioRegions + [copy], now: now)
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(updated),
            affectedRegionId: copy.regionId
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        aestheticStatus = "Audio region duplicated"
        return edit
    }

    /// Continuous drag-end move (NOT frame-quantized — drags are continuous;
    /// playhead placement quantizes at its call site). Returns the pre-edit
    /// snapshot for undo registration.
    @discardableResult
    func moveShotAudioRegion(
        shotId: String,
        regionId: String,
        startSeconds: Double
    ) -> ShotAudioRegion? {
        commitShotAudioRegionEdit(shotId: shotId, regionId: regionId, status: "Audio region moved") {
            $0.movedTo(startSeconds: startSeconds, timelineSeconds: $1)
        }
    }

    /// Single trim-in/trim-out/extend commit through the geometry law: a
    /// non-looping region clamps honestly at its media's natural length; a
    /// looping region tiles and only the timeline bounds it.
    @discardableResult
    func setShotAudioRegionGeometry(
        shotId: String,
        regionId: String,
        startSeconds: Double,
        sourceStartSeconds: Double,
        durationSeconds: Double
    ) -> ShotAudioRegion? {
        commitShotAudioRegionEdit(shotId: shotId, regionId: regionId, status: "Audio region trimmed") {
            $0.applyingGeometry(
                startSeconds: startSeconds,
                sourceStartSeconds: sourceStartSeconds,
                durationSeconds: durationSeconds,
                timelineSeconds: $1
            )
        }
    }

    /// Replaces one placement with two in a single project write. Returning a
    /// whole-state edit makes the split one symmetric Undo step rather than a
    /// trim plus an independently undoable add.
    @discardableResult
    func splitShotAudioRegion(
        shotId: String,
        regionId: String,
        atSeconds: Double
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let index = base.audioRegions.firstIndex(where: { $0.regionId == regionId }),
              base.audioRegions[index].laneId != ShotAudioLaneId.source,
              let split = base.audioRegions[index].splitting(
                  atSeconds: atSeconds,
                  rightRegionId: "audio_region_\(UUID().uuidString.lowercased())"
              ) else {
            return nil
        }

        var regions = base.audioRegions
        regions.replaceSubrange(index...index, with: [split.left, split.right])
        let updated = base.settingAudioRegions(regions, now: now)
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(updated),
            affectedRegionId: split.right.regionId
        )
        guard edit.before != edit.after else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        aestheticStatus = "Audio region split"
        return edit
    }

    /// Loop toggle. Turning loops off clamps the claimed duration back to the
    /// honest media remainder when the length is known.
    @discardableResult
    func setShotAudioRegionLoops(
        shotId: String,
        regionId: String,
        loops: Bool
    ) -> ShotAudioRegion? {
        commitShotAudioRegionEdit(
            shotId: shotId,
            regionId: regionId,
            status: loops ? "Region loops to fill" : "Region plays once"
        ) { region, _ in
            region.settingLoops(loops)
        }
    }

    /// Replace-media-in-place: keeps the region's placement (start, gain,
    /// mute, loops) and swaps the underlying file — also the relink path for
    /// a missing file (re-pick or re-import the asset and point here). The
    /// The typed asset decides resolution, so every ambient row can swap
    /// freely between Project Audio and generated beds without id guessing.
    @discardableResult
    func replaceShotAudioRegionMedia(
        shotId: String,
        regionId: String,
        asset: ShotAudioAssetReference
    ) -> ShotAudioRegion? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let existing = base.audioRegions.first(where: { $0.regionId == regionId }),
              existing.laneId != ShotAudioLaneId.source else { return nil }
        let path: String
        let mediaId: String
        let label: String
        let mediaSeconds: Double?
        let provenance: String
        let laneKind = ShotAudioLaneId.kind(ofLaneId: existing.laneId)
        switch asset {
        case .ambientBed(let bedId):
            guard laneKind == ShotAudioLaneId.ambient,
                  let record = ambientBedLibrary.bed(bedId) else {
                aestheticStatus = "That ambient bed is no longer in the library"
                return nil
            }
            path = ambientBedFileURL(record, project: project).path
            mediaId = record.bedId
            label = record.displayName
            mediaSeconds = record.durationSeconds > 0 ? record.durationSeconds : nil
            provenance = "operator_ambient_bed"
        case .projectAudio(let projectMediaId):
            guard [
                ShotAudioLaneId.clip,
                ShotAudioLaneId.narration,
                ShotAudioLaneId.microphone,
                ShotAudioLaneId.ambient
            ].contains(laneKind),
                  let item = items.first(where: {
                      $0.mediaId == projectMediaId && $0.kind == .audio
                  }) else {
                aestheticStatus = "That audio clip is no longer in this project"
                return nil
            }
            path = item.path
            mediaId = item.mediaId
            label = item.filename
            mediaSeconds = item.durationSeconds
            switch laneKind {
            case ShotAudioLaneId.narration: provenance = "imported_narration_audio"
            case ShotAudioLaneId.microphone: provenance = "imported_microphone_audio"
            case ShotAudioLaneId.ambient: provenance = "operator_ambient_audio"
            default: provenance = "operator_audio_clip"
            }
        }
        let updated = existing.replacingMedia(
            path: path,
            mediaId: mediaId,
            label: label,
            sourceDurationSeconds: mediaSeconds,
            provenance: provenance
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                regionizedForAudioEdit(current, now: now)
                    .updatingAudioRegion(regionId: regionId, now: now) { $0 = updated }
            },
            for: project
        )
        aestheticStatus = "Replaced with \(label)"
        return existing
    }

    /// Repairs control-state silence only. Missing media is a relink problem,
    /// not a volume problem, and intentional nonzero levels are preserved.
    @discardableResult
    func makeShotAudioRegionAudible(
        shotId: String,
        regionId: String
    ) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let existing = base.audioRegions.first(where: { $0.regionId == regionId }),
              existing.laneId != ShotAudioLaneId.source,
              FileManager.default.fileExists(atPath: existing.path) else { return nil }
        var audibleRegion = existing
        audibleRegion.isMuted = false
        if audibleRegion.gain <= 0.000_1 {
            audibleRegion.gain = 1
        }
        let updated = base.settingAudioMix(
            base.audioMix.preparingLaneForNewAudio(existing.laneId),
            now: now
        ).updatingAudioRegion(regionId: regionId, now: now) {
            $0 = audibleRegion.normalized()
        }
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(updated),
            affectedRegionId: regionId
        )
        guard edit.before != edit.after else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        aestheticStatus = "Audio made audible"
        return edit
    }

    /// Compound audio undo primitive: restores lane controls and the complete
    /// region roster in one project-document write.
    func restoreShotAudioState(
        shotId: String,
        snapshot: ShotAudioStateSnapshot
    ) {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                current.settingAudioMix(snapshot.audioMix, now: now)
                    .settingAudioRegions(snapshot.audioRegions, now: now)
            },
            for: project
        )
        aestheticStatus = "Audio state restored"
    }

    /// Persists operator-editable fields while retaining the region's source
    /// provenance and file identity. A missing id is reinserted so Undo
    /// Delete can restore the exact placement — this reinsert IS the undo
    /// restore primitive. Identity changes (path/mediaId/label/lane) are
    /// still refused here; `replaceShotAudioRegionMedia` owns identity.
    /// Returns the pre-edit snapshot (nil when reinserting).
    @discardableResult
    func setShotAudioRegion(shotId: String, region: ShotAudioRegion) -> ShotAudioRegion? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let normalized = region.normalized()
        guard !normalized.regionId.isEmpty,
              !normalized.laneId.isEmpty,
              normalized.laneId == ShotAudioLaneId.source || !normalized.path.isEmpty else {
            return nil
        }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        let snapshot = base.audioRegions.first { $0.regionId == normalized.regionId }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                let regionized = regionizedForAudioEdit(current, now: now)
                if regionized.audioRegions.contains(where: { $0.regionId == normalized.regionId }) {
                    return regionized.updatingAudioRegion(regionId: normalized.regionId, now: now) {
                        $0.startSeconds = normalized.startSeconds
                        $0.sourceStartSeconds = normalized.sourceStartSeconds
                        $0.durationSeconds = normalized.durationSeconds
                        $0.playbackRate = normalized.playbackRate
                        $0.pitchMode = normalized.pitchMode
                        $0.gain = normalized.gain
                        $0.isMuted = normalized.isMuted
                        $0.fadeInSeconds = normalized.fadeInSeconds
                        $0.fadeOutSeconds = normalized.fadeOutSeconds
                        $0 = $0.settingLoops(normalized.loops)
                    }
                }
                return regionized.settingAudioRegions(
                    regionized.audioRegions + [normalized],
                    now: now
                )
            },
            for: project
        )
        aestheticStatus = "Audio region updated"
        return snapshot
    }

    /// Returns the deleted snapshot so the caller can register undo
    /// (restore = `setShotAudioRegion`'s reinsert path).
    @discardableResult
    func deleteShotAudioRegion(shotId: String, regionId: String) -> ShotAudioRegion? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        guard let region = base.audioRegions.first(where: { $0.regionId == regionId }),
              region.laneId != ShotAudioLaneId.source else { return nil }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                regionizedForAudioEdit(current, now: now)
                    .removingAudioRegion(regionId: regionId, now: now)
            },
            for: project
        )
        aestheticStatus = "Audio region deleted"
        return region
    }

    /// Deletes several regions (the picker's Remove of every placement of one
    /// asset) in ONE persisted transaction and one whole-state edit, so a
    /// multi-region Remove is a single Undo step. Source-lane regions refuse
    /// as ever.
    @discardableResult
    func deleteShotAudioRegions(shotId: String, regionIds: [String]) -> ShotAudioStateEdit? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return nil }
        let now = DateFormats.now()
        let base = regionizedForAudioEdit(shot, now: now)
        let targetIds = Set(regionIds)
        let removableIds = Set(
            base.audioRegions
                .filter { targetIds.contains($0.regionId) && $0.laneId != ShotAudioLaneId.source }
                .map(\.regionId)
        )
        guard !removableIds.isEmpty else { return nil }
        let updated = base.settingAudioRegions(
            base.audioRegions.filter { !removableIds.contains($0.regionId) },
            now: now
        )
        let edit = ShotAudioStateEdit(
            before: shotAudioStateSnapshot(base),
            after: shotAudioStateSnapshot(updated),
            affectedRegionId: ""
        )
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
        aestheticStatus = removableIds.count == 1
            ? "Audio region deleted"
            : "\(removableIds.count) audio regions deleted"
        return edit
    }

    /// Undo infrastructure: reinstates a region EXACTLY as snapshotted —
    /// identity fields included — replacing any current region with that id,
    /// or reinserting a deleted one. This is the only op that may change a
    /// region's identity, and it exists so replace-media and delete
    /// round-trip perfectly through ⌘Z.
    func restoreShotAudioRegion(shotId: String, region: ShotAudioRegion) {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else { return }
        let normalized = region.normalized()
        guard !normalized.regionId.isEmpty, !normalized.laneId.isEmpty else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                let regionized = regionizedForAudioEdit(current, now: now)
                if regionized.audioRegions.contains(where: { $0.regionId == normalized.regionId }) {
                    return regionized.updatingAudioRegion(regionId: normalized.regionId, now: now) {
                        $0 = normalized
                    }
                }
                return regionized.settingAudioRegions(
                    regionized.audioRegions + [normalized],
                    now: now
                )
            },
            for: project
        )
        aestheticStatus = "Audio region restored"
    }

    // MARK: - Per-segment SOURCE audio

    /// Resolves the four durable identity fields for a segment key off the live
    /// render plan. The UI only ever holds the key; keeping the expansion here
    /// means one place decides what a segment's identity IS, matching the seed
    /// used by `shotCutAssembly` and by the render version's saved clips.
    private func shotSourceSegmentIdentity(
        shotId: String,
        segmentKey: String
    ) -> (startFrameImageId: String, endFrameImageId: String, startEntryId: String, endEntryId: String)? {
        guard !segmentKey.isEmpty,
              let plan = shotRenderPromptPlan(shotId: shotId) else { return nil }
        for segment in plan.segments {
            switch segment {
            case .footage(let footage):
                guard footage.placementKey == segmentKey else { continue }
                return (footage.clip.footageKey, "", footage.clip.entryId, "")
            case .generated(let item):
                guard item.pair.placementKey == segmentKey else { continue }
                return (
                    item.pair.start?.imageId ?? "",
                    item.pair.end?.imageId ?? "",
                    item.pair.startPlacementEntryId,
                    item.pair.endPlacementEntryId
                )
            // Never in plan-generator output (assembly-only fallback band).
            case .artifactFallback:
                continue
            }
        }
        return nil
    }

    /// Mutes or attenuates ONE segment's own generated audio, leaving every
    /// other segment untouched. Returns the pre-edit rows so the caller can
    /// register a single undo action via `restoreShotSourceSegmentAudio`.
    ///
    /// Deliberately does NOT call `regionizedForAudioEdit`: intent lives in its
    /// own field precisely so a two-click mute never triggers the irreversible
    /// whole-shot regionization that the precedence law would otherwise force
    /// (see `ShotAudioComposition.applyMix`).
    ///
    /// There is no separate "clear" op and none is needed: `gain: 1` with
    /// `isMuted: false` IS the absence of intent, and `settingSourceSegmentAudio`
    /// drops the row rather than persisting one that says nothing.
    @discardableResult
    func setShotSourceSegmentAudio(
        shotId: String,
        segmentKey: String,
        gain: Double,
        isMuted: Bool
    ) -> [ShotSourceSegmentAudio]? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let identity = shotSourceSegmentIdentity(shotId: shotId, segmentKey: segmentKey) else {
            return nil
        }
        let snapshot = shot.sourceSegmentAudio
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                current.settingSourceSegmentAudio(
                    segmentKey: segmentKey,
                    startFrameImageId: identity.startFrameImageId,
                    endFrameImageId: identity.endFrameImageId,
                    placementStartEntryId: identity.startEntryId,
                    placementEndEntryId: identity.endEntryId,
                    gain: gain,
                    isMuted: isMuted,
                    now: now
                )
            },
            for: project
        )
        aestheticStatus = isMuted ? "Segment audio muted" : "Segment audio updated"
        return snapshot
    }

    /// Lifts one segment's own audio OUT of the picture and onto the CLIP lane
    /// as ordinary editable regions, muting it at source in the SAME
    /// transaction. That is what turns "mute" into "move and transform": every
    /// existing region tool then applies to audio that was previously welded to
    /// its frames.
    ///
    /// One region PER RAZOR PIECE, never one spanning region — a single region
    /// across the whole segment would resurrect exactly the audio the razor
    /// removed. Unlike `addShotAudioRegion` these regions point at an `.mp4`
    /// with no backing media item, which is legal (the composition reads the
    /// file, not the library) but means `replaceShotAudioRegionMedia` cannot
    /// relink them — hence the missing-file guard below.
    @discardableResult
    func detachShotSourceSegmentAudio(
        shotId: String,
        segmentKey: String
    ) -> ShotSourceDetachSnapshot? {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let identity = shotSourceSegmentIdentity(shotId: shotId, segmentKey: segmentKey) else {
            return nil
        }
        // A reversed cut plays baked proxies whose output seconds and file
        // coordinates both differ from the forward assembly, and
        // `sweepStaleReverseProxies` may delete those files underneath a
        // region. Detaching there would write geometry that is wrong now and
        // unrelinkable later.
        guard !shot.cutList.isReversed else {
            aestheticStatus = "Play the CUT forward before detaching segment audio"
            return nil
        }
        let assembly = shotForwardAssembly(shot)
        let pieces = assembly.playbackItems.filter {
            $0.segmentKey == segmentKey && !$0.isBridge && $0.durationSeconds > 0
        }
        guard !pieces.isEmpty else {
            aestheticStatus = "Render this segment before detaching its audio"
            return nil
        }
        guard pieces.allSatisfy({ FileManager.default.fileExists(atPath: $0.url.path) }) else {
            aestheticStatus = "That segment's video file is missing"
            return nil
        }
        let ordinal = assembly.bands.first { $0.segmentKey == segmentKey }
            .map { $0.displayIndex + 1 }
        let baseLabel = ordinal.map { "Segment \($0) audio" } ?? "Segment audio"
        let regions = shotDetachedSourceRegions(
            pieces: pieces,
            baseLabel: baseLabel,
            regionId: { _ in "audio_region_\(UUID().uuidString.lowercased())" }
        )
        let snapshot = ShotSourceDetachSnapshot(
            sourceSegmentAudio: shot.sourceSegmentAudio,
            audioRegions: shot.audioRegions
        )
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                // Detach DOES regionize — it creates real regions, so the
                // precedence law applies. This is the one source-audio gesture
                // that migrates the shot, and the affordance says so.
                let regionized = regionizedForAudioEdit(current, now: now)
                return regionized
                    .settingAudioRegions(regionized.audioRegions + regions, now: now)
                    .settingSourceSegmentAudio(
                        segmentKey: segmentKey,
                        startFrameImageId: identity.startFrameImageId,
                        endFrameImageId: identity.endFrameImageId,
                        placementStartEntryId: identity.startEntryId,
                        placementEndEntryId: identity.endEntryId,
                        gain: 1,
                        isMuted: true,
                        now: now
                    )
            },
            for: project
        )
        aestheticStatus = pieces.count > 1
            ? "Detached \(pieces.count) spans to the Clip lane"
            : "Detached segment audio to the Clip lane"
        return snapshot
    }

    /// Undo primitive for `detachShotSourceSegmentAudio`: both halves at once.
    func restoreShotSourceDetach(shotId: String, snapshot: ShotSourceDetachSnapshot) {
        guard let project = currentProject,
              shotTimeline.shots.contains(where: { $0.shotId == shotId }) else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { current in
                current
                    .settingAudioRegions(snapshot.audioRegions, now: now)
                    .settingAllSourceSegmentAudio(snapshot.sourceSegmentAudio, now: now)
            },
            for: project
        )
        aestheticStatus = "Detach undone"
    }

    /// Lazily fills missing natural-media lengths on persisted regions
    /// (regions written before `sourceDurationSeconds` existed). One
    /// persisted write when anything resolves. Until then nil simply means
    /// "no media clamp" — playback honesty is held by the composition's
    /// insert-time clamps either way.
    func backfillShotAudioRegionSourceDurations(shotId: String) async {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return }
        let missing = shot.audioRegions.filter {
            $0.sourceDurationSeconds == nil
                && $0.laneId != ShotAudioLaneId.source
                && !$0.path.isEmpty
                && FileManager.default.fileExists(atPath: $0.path)
        }
        guard !missing.isEmpty else { return }
        var resolved: [String: Double] = [:]
        for region in missing {
            let asset = AVURLAsset(url: URL(fileURLWithPath: region.path))
            let seconds = (try? await asset.load(.duration).seconds) ?? 0
            if seconds.isFinite, seconds > 0 {
                resolved[region.regionId] = seconds
            }
        }
        guard !resolved.isEmpty,
              currentProject?.projectId == project.projectId,
              var updatedShot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return }
        let now = DateFormats.now()
        for (regionId, seconds) in resolved {
            updatedShot = updatedShot.updatingAudioRegion(regionId: regionId, now: now) {
                if $0.sourceDurationSeconds == nil {
                    $0.sourceDurationSeconds = seconds
                }
            }
        }
        let publishedShot = updatedShot
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in publishedShot },
            for: project
        )
    }

    /// Imports audio files as project media and returns their records so a
    /// lane drop can place regions immediately. Modeled on
    /// `importGoalChatImageFiles`: scan the exact URLs, publish sources and
    /// inventory together, report on the aesthetic line.
    func importAudioMediaFiles(_ urls: [URL]) async -> [MediaItemRecord] {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return []
        }
        let audioURLs = urls.filter { url in
            guard let type = UTType(filenameExtension: url.pathExtension) else { return false }
            return type.conforms(to: .audio)
        }
        guard !audioURLs.isEmpty else {
            aestheticStatus = "Choose audio files"
            return []
        }
        do {
            let existingByPath = Dictionary(
                grouping: items,
                by: { URL(fileURLWithPath: $0.path).standardizedFileURL.path }
            )
            var importedItems: [MediaItemRecord] = []
            var updatedSources = sources
            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            var sourceChanged = false

            for url in audioURLs {
                let standardizedURL = url.standardizedFileURL
                let path = standardizedURL.path
                if let existing = existingByPath[path]?.first(where: { $0.kind == .audio }) {
                    importedItems.append(existing)
                    continue
                }
                let source = store.makeSource(from: standardizedURL, kind: .file)
                let scanResult = await store.scan(source: source, for: project) { [weak self] progress in
                    guard let self, progress.isScanning else { return }
                    self.aestheticStatus = "Importing \(progress.currentFile.isEmpty ? source.displayName : progress.currentFile)"
                }
                updatedSources.removeAll {
                    $0.sourceId == scanResult.source.sourceId || $0.path == scanResult.source.path
                }
                updatedSources.append(scanResult.source)
                sourceChanged = true
                for item in scanResult.items where item.kind == .audio && item.scanError == nil {
                    updatedItemsById[item.mediaId] = item
                    importedItems.append(item)
                }
            }

            guard currentProject?.projectId == project.projectId else { return [] }
            let refreshedItems = sortedMediaItems(Array(updatedItemsById.values))
            if sourceChanged {
                try store.saveSources(updatedSources, for: project)
                sources = updatedSources
            }
            try store.saveInventory(refreshedItems, for: project)
            items = refreshedItems
            if importedItems.isEmpty {
                aestheticStatus = "No audio files imported"
            } else {
                aestheticStatus = "Imported \(importedItems.count) audio file\(importedItems.count == 1 ? "" : "s")"
                touchCurrentProject()
            }
            return importedItems
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not import audio"
            return []
        }
    }

    /// Trashes the baked file and removes the record, then detaches the bed
    /// from every shot referencing it. File restore mirrors
    /// deleteShotMicrophoneTake: when the library save fails, the trashed
    /// file comes back and nothing is removed.
    @discardableResult
    func deleteAmbientBed(bedId: String) -> Bool {
        guard let project = currentProject,
              let record = ambientBedLibrary.bed(bedId) else { return false }
        let sourceURL = ambientBedFileURL(record, project: project)
        var trashedURL: NSURL?
        do {
            if FileManager.default.fileExists(atPath: sourceURL.path) {
                try FileManager.default.trashItem(at: sourceURL, resultingItemURL: &trashedURL)
            }
            let updated = ambientBedLibrary.removing(bedId: bedId)
            do {
                try contextStore.saveAmbientBedLibrary(updated, for: project)
                ambientBedLibrary = updated
            } catch {
                if let trashedURL, !FileManager.default.fileExists(atPath: sourceURL.path) {
                    try? FileManager.default.moveItem(at: trashedURL as URL, to: sourceURL)
                }
                throw error
            }
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "The ambient bed could not be deleted"
            return false
        }
        // Sweep every shot still pointing at the bed — the singleton lane
        // pointer AND any ambient regions carrying it (the file is in the
        // Trash; a region pointing at it would be a silent lie). A sweep
        // failure is non-fatal: a dangling lane is only silently absent audio.
        let now = DateFormats.now()
        let referencingShotIds = shotTimeline.shots
            .filter { shot in
                shot.audioMix.lane(ShotAudioLaneId.ambient).ambientBedId == bedId
                    || shot.audioRegions.contains {
                        $0.laneId == ShotAudioLaneId.ambient && $0.mediaId == bedId
                    }
            }
            .map(\.shotId)
        if !referencingShotIds.isEmpty {
            var document = shotTimeline
            for shotId in referencingShotIds {
                document = document.updatingShot(shotId: shotId, now: now) { shot in
                    var next = shot.settingAudioMix(
                        shot.audioMix.settingAmbientBed(bedId: nil, path: nil),
                        now: now
                    )
                    if !next.audioRegions.isEmpty {
                        next.audioRegions.removeAll {
                            $0.laneId == ShotAudioLaneId.ambient && $0.mediaId == bedId
                        }
                    }
                    return next
                }
            }
            persistShotTimeline(document, for: project)
        }
        aestheticStatus = "Ambient bed moved to Trash"
        return true
    }

    func renameAmbientBed(bedId: String, displayName: String) {
        guard let project = currentProject, ambientBedLibrary.bed(bedId) != nil else { return }
        let updated = ambientBedLibrary.renaming(bedId: bedId, displayName: displayName, now: DateFormats.now())
        do {
            try contextStore.saveAmbientBedLibrary(updated, for: project)
            ambientBedLibrary = updated
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func shotDurationSeconds(shotId: String) -> Double {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return 0 }
        let plan = shotRenderPromptPlan(shotId: shotId)
        let assembly = shotCutAssembly(
            shot: shot,
            planSegments: plan?.segments ?? [],
            clipDurationsByPath: [:]
        )
        return assembly.outputSeconds > 0
            ? assembly.outputSeconds
            : Double(shot.activeRenderVersion?.totalSeconds ?? shot.renderArtifact?.totalSeconds ?? 0)
    }

    /// Razor cuts pinned to a take no RETAINED version carries are
    /// meaningless — after a render, drop those. THE PIN SWEEP LAW: the pin
    /// source is `playableRenderVersion`, which ranges over browsable
    /// versions, so comparing the ACTIVE version alone (the old rule) swept
    /// a razor made against the still-watched old take the moment an
    /// in-flight render completed. Footage cuts ("" pin) persist, and a pin
    /// that matches no band is already inert at plan time.
    private func sweepStalePinnedCuts(shotId: String, for project: ProjectRecord) {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else { return }
        let staleIds = shotStalePinnedCutIds(shot: shot)
        let staleInsertionIds = shotStalePictureInsertionIds(shot: shot)
        guard !staleIds.isEmpty || !staleInsertionIds.isEmpty else { return }
        let now = DateFormats.now()
        var updated = shot
        for cutId in staleIds {
            if let next = shotRemovingRazorCut(
                updated,
                shotId: shotId,
                cutId: cutId,
                now: now
            ) {
                updated = next
            }
        }
        // Arranged copies ride the same sweep — and unlike razors, their loss
        // is reported: a silently vanished loop reads as data loss.
        if !staleInsertionIds.isEmpty {
            if let next = shotMutatingPictureInsertions(updated, shotId: shotId, now: now, mutate: { list in
                list.removeAll { staleInsertionIds.contains($0.insertionId) }
            }) {
                updated = next
            }
            aestheticStatus = staleInsertionIds.count == 1
                ? "1 arranged copy removed — its source take is no longer retained"
                : "\(staleInsertionIds.count) arranged copies removed — their source takes are no longer retained"
        }
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) { _ in updated },
            for: project
        )
    }

    /// Non-destructive per-placement trim: narrows what THIS entry plays (and
    /// therefore where neighboring bridges anchor). The media asset is never
    /// touched; a changed range gets fresh handoff keys on the next render.
    @discardableResult
    func updateShotClipRange(
        shotId: String,
        entryId: String,
        startSeconds: Double?,
        endSeconds: Double?
    ) -> ShotPictureStateEdit? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let entry = shot.entries.first(where: { $0.entryId == entryId }),
              entry.isClip,
              let media = items.first(where: { $0.mediaId == entry.clipMediaId }) else {
            return nil
        }
        let assetDuration = max(media.durationSeconds ?? 0, 0)
        let updatedEntry = entry.settingClipRange(
            startSeconds: startSeconds,
            endSeconds: endSeconds,
            assetDurationSeconds: assetDuration
        )
        let resolvedStart = updatedEntry.clipStartSeconds ?? 0
        let resolvedEnd = updatedEntry.clipEndSeconds ?? assetDuration
        guard assetDuration <= 0 || resolvedEnd - resolvedStart >= VideoTrimRange.minimumTrimSeconds else {
            aestheticStatus = "Clip range must be at least \(String(format: "%.1f", VideoTrimRange.minimumTrimSeconds))s"
            return nil
        }
        // Shed keys come from the PRE-change entry: both the legacy footage
        // key AND the modern placement key — the old legacy-only match was
        // dead for modern razors, which then survived the range change and
        // bit at now-wrong clip-local seconds.
        let shedKeys = shotClipRangeShedKeys(entry: entry)
        // Shedding a carrier razor dissolves its speed section with it (R2
        // rides the chokepoint below) — the status should say so.
        let shedsCarrier = shot.cutList.segmentCuts.contains { cut in
            shedKeys.contains(cut.segmentKey)
                && !shotSectionCarrierIds(insertions: shot.pictureInsertions, cutId: cut.id).isEmpty
        }
        let rangeStatus = shedsCarrier
            ? "Clip range updated — its speed section went with it"
            : "Clip range updated"
        return commitShotPictureEdit(shotId: shotId, status: rangeStatus) { current, now in
            var updatedShot = current
            for cutId in current.cutList.segmentCuts
                .filter({ shedKeys.contains($0.segmentKey) })
                .map(\.id) {
                if let next = self.shotRemovingRazorCut(
                    updatedShot,
                    shotId: shotId,
                    cutId: cutId,
                    now: now
                ) {
                    updatedShot = next
                }
            }
            guard let updatedIndex = updatedShot.entries.firstIndex(where: { $0.entryId == entryId }) else {
                return nil
            }
            updatedShot.entries[updatedIndex] = updatedEntry
            updatedShot.updatedAt = now
            return updatedShot
        }
    }

    /// The Clip Inspector's handoff preview: frame-exact stills at a clip
    /// range's in/out, extracted under security scope and cached in scratch
    /// (same range = same files, no re-extraction).
    func extractClipAnchorStills(
        mediaId: String,
        startSeconds: Double?,
        endSeconds: Double?
    ) async -> (inStill: URL, outStill: URL)? {
        guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video else {
            return nil
        }
        let assetDuration = max(media.durationSeconds ?? 0, 0)
        let resolvedStart = min(max(startSeconds ?? 0, 0), assetDuration)
        let resolvedEnd = min(max(endSeconds ?? assetDuration, resolvedStart), assetDuration)
        let cacheDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("clip_anchor_stills", isDirectory: true)
        let cacheKey = shortHash(
            "\(mediaId)|\(String(format: "%.3f", resolvedStart))|\(String(format: "%.3f", resolvedEnd))",
            length: 16
        )
        let inURL = cacheDirectory.appendingPathComponent("in_\(cacheKey).png")
        let outURL = cacheDirectory.appendingPathComponent("out_\(cacheKey).png")
        if FileManager.default.fileExists(atPath: inURL.path),
           FileManager.default.fileExists(atPath: outURL.path) {
            return (inURL, outURL)
        }
        let source = sources.first { $0.sourceId == media.sourceId }
        let path = media.path
        let inSeconds = resolvedStart + 0.02
        let outSeconds = max(resolvedEnd - (1.0 / 24.0), resolvedStart)
        do {
            return try await store.withSourceAccess(source) {
                let inStill = try await VideoChainMedia.extractFrameStill(
                    videoURL: URL(fileURLWithPath: path),
                    atSeconds: inSeconds,
                    outputURL: inURL
                )
                let outStill = try await VideoChainMedia.extractFrameStill(
                    videoURL: URL(fileURLWithPath: path),
                    atSeconds: outSeconds,
                    outputURL: outURL
                )
                return (inStill, outStill)
            }
        } catch {
            return nil
        }
    }

    func moveShotEntry(shotId: String, entryId: String, toIndex index: Int) {
        guard let project = currentProject else { return }
        // Reordering is legal only wholly WITHIN the unrendered tail — the
        // terminal-gap drag between two appended cells must not hit a
        // confusing refusal, while rendered material stays untouchable.
        guard frozenCutPermits(shotId: shotId, tailPredicate: { tail in
            guard index >= tail,
                  let entryIndex = shotTimeline.shots.first(where: { $0.shotId == shotId })?
                      .entries.firstIndex(where: { $0.entryId == entryId }) else { return false }
            return entryIndex >= tail
        }) else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.movingEntry(entryId: entryId, toIndex: index, now: now)
            },
            for: project
        )
    }

    func removeShotEntry(shotId: String, entryId: String) {
        guard let project = currentProject else { return }
        // Removing an unrendered appended entry restores truth — the rendered
        // prefix stays untouchable.
        guard frozenCutPermits(shotId: shotId, tailPredicate: { tail in
            (shotTimeline.shots.first { $0.shotId == shotId }?
                .entries.firstIndex { $0.entryId == entryId }).map { $0 >= tail } ?? false
        }) else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.removingEntry(entryId: entryId, now: now)
            },
            for: project
        )
    }

    /// Fetches the ElevenLabs account's voices for the Voices tab and the
    /// narration voice menus. Requires only the API key; failures surface in
    /// aestheticStatus and leave the previous list intact.
    @discardableResult
    func loadElevenVoices(force: Bool = false) async -> Bool {
        guard ElevenLabsSettingsStore.hasResolvedAPIKey() else {
            aestheticStatus = "Add an ElevenLabs API key in App Settings to list voices"
            return false
        }
        guard !isLoadingAccountVoices else { return false }
        if !force, !accountVoiceOptions.isEmpty {
            return true
        }
        isLoadingAccountVoices = true
        defer { isLoadingAccountVoices = false }
        do {
            let client = ElevenLabsClient(apiKey: try ElevenLabsSettingsStore.resolvedAPIKeyOrThrow())
            let voices = try await client.listVoices(
                projectId: currentProject?.projectId ?? "",
                runId: "eleven_voices_\(shortHash(DateFormats.now(), length: 10))"
            )
            accountVoiceOptions = voices.map { voice in
                StoryAudioVoiceOption(
                    id: voice.voiceId,
                    name: voice.name.trimmed.nilIfEmpty ?? voice.voiceId,
                    descriptor: voice.category.trimmed.nilIfEmpty ?? "Account voice",
                    voiceId: voice.voiceId
                )
            }
            return true
        } catch {
            aestheticStatus = "Could not list ElevenLabs voices"
            lastError = error.localizedDescription
            return false
        }
    }

    /// The Frame Creator refine chat: rewrites the given form text per the
    /// directive (honoring earlier directives), preserving its sentiment.
    /// Ephemeral — nothing persists; the editor is the source of truth.
    func transformFormPrompt(
        prompt: String,
        directive: String,
        priorDirectives: [String]
    ) async -> LensFormPromptTransform? {
        let currentText = prompt.trimmed
        let direction = directive.trimmed
        guard !currentText.isEmpty, !direction.isEmpty else { return nil }
        do {
            let openAIClient = try OpenAIClient.fromEnvironment()
            let composed = FormRefineComposer.transformPrompt(
                current: currentText,
                directive: direction,
                priorDirectives: priorDirectives
            )
            let runId = "form_chat_\(shortHash("\(currentProject?.projectId ?? ""):\(direction):\(DateFormats.now())", length: 14))"
            let result = try await openAIClient.transformFormPrompt(
                prompt: composed,
                projectId: currentProject?.projectId ?? "",
                runId: runId
            )
            return LensFormPromptTransform(prompt: result.transformedPrompt, note: result.changeNote)
        } catch {
            aestheticStatus = "Form refine failed"
            lastError = error.localizedDescription
            return nil
        }
    }

    func noteVoiceDefaultSaveFailure(_ error: Error) {
        aestheticStatus = "Could not save the default voice"
        lastError = error.localizedDescription
    }

    func noteDefaultVoiceCannotHide() {
        aestheticStatus = "The default voice stays in the menus — make another voice the default first"
    }

    /// Shows or hides one voice in the render-time menus. Never touches which
    /// voice a narration resolves to — see THE VOICE CURATION LAW.
    func setNarrationVoiceHidden(voiceId: String, hidden: Bool) {
        let cleaned = voiceId.trimmed
        guard !cleaned.isEmpty else { return }
        var updated = hiddenNarrationVoiceIds
        if hidden { updated.insert(cleaned) } else { updated.remove(cleaned) }
        persistHiddenNarrationVoiceIds(updated, status: hidden ? "Voice hidden from render menus" : "Voice shown in render menus")
    }

    /// One click for the noise: ElevenLabs' ~21 stock `premade` voices leave
    /// the menus, every voice you made or saved stays.
    func hideStockNarrationVoices() {
        let stock = StoryAudioVoiceCatalog.stockVoiceIds(in: accountVoiceOptions)
        guard !stock.isEmpty else {
            aestheticStatus = "No stock voices to hide — refresh the account list first"
            return
        }
        persistHiddenNarrationVoiceIds(
            hiddenNarrationVoiceIds.union(stock),
            status: "\(stock.count) stock voices hidden from render menus"
        )
    }

    func showAllNarrationVoices() {
        guard !hiddenNarrationVoiceIds.isEmpty else { return }
        persistHiddenNarrationVoiceIds([], status: "All voices shown in render menus")
    }

    private func persistHiddenNarrationVoiceIds(_ ids: Set<String>, status: String) {
        do {
            try ElevenLabsSettingsStore.saveHiddenNarrationVoiceIds(ids)
            hiddenNarrationVoiceIds = ids
            aestheticStatus = status
        } catch {
            aestheticStatus = "Could not save the voice list"
            lastError = error.localizedDescription
        }
    }

    private func persistShotTimeline(
        _ document: ProjectShotTimelineDocument,
        for project: ProjectRecord,
        syncStages: Bool = true
    ) {
        // THE PROJECT IDENTITY LAW, engine half: refuse a document that names
        // another project BEFORE it can also replace the in-memory timeline —
        // the store's own guard would protect the disk but not `shotTimeline`.
        let documentProjectId = document.projectId.trimmed
        guard documentProjectId.isEmpty || documentProjectId == project.projectId else {
            lastError = "Refused a cross-project timeline write (\(documentProjectId) → \(project.projectId)) — a stale document raced a project switch; nothing was saved"
            return
        }
        // THE PROJECT IDENTITY LAW, currency half: a straggler completion from
        // a project the user just switched AWAY from carries a document and a
        // project that match each other, so the guard above passes — but
        // assigning `shotTimeline` would put the OLD project's document under
        // the freshly opened one, and every later save then refuses with the
        // cross-project message (a cross-project bleed report). The
        // write stays durable — the data belongs to its own project's store —
        // while in-memory state and the stage re-truth stay current-only.
        let isCurrentProject = currentProject?.projectId == project.projectId
        do {
            var stamped = document
            if stamped.projectId.trimmed.isEmpty {
                stamped.projectId = project.projectId
            }
            try contextStore.saveShotTimeline(stamped, for: project)
            if isCurrentProject {
                shotTimeline = stamped
            }
        } catch {
            lastError = error.localizedDescription
        }
        // `syncStages` remains in the private signature while legacy callers
        // are retired, but flat Shots never synthesize or reconcile a hidden
        // Stage hierarchy after a timeline write.
        _ = syncStages
    }

    private func persistShotTimelineAndOutputSequence(
        timeline: ProjectShotTimelineDocument,
        output: ProjectOutputSequenceDocument,
        for project: ProjectRecord
    ) {
        let timelineProjectId = timeline.projectId.trimmed
        let outputProjectId = output.projectId.trimmed
        guard (timelineProjectId.isEmpty || timelineProjectId == project.projectId),
              (outputProjectId.isEmpty || outputProjectId == project.projectId) else {
            lastError = "Refused a cross-project Shot/Output write; nothing was saved"
            return
        }
        do {
            var stampedTimeline = timeline
            var stampedOutput = output
            if stampedTimeline.projectId.trimmed.isEmpty { stampedTimeline.projectId = project.projectId }
            if stampedOutput.projectId.trimmed.isEmpty { stampedOutput.projectId = project.projectId }
            try contextStore.saveShotTimelineAndOutputSequence(
                timeline: stampedTimeline,
                outputSequence: stampedOutput,
                for: project
            )
            guard currentProject?.projectId == project.projectId else { return }
            shotTimeline = stampedTimeline.normalized()
            outputSequence = stampedOutput.normalized()
        } catch {
            lastError = error.localizedDescription
        }
    }

    // MARK: - Flat Shot organization migration

    /// Reads the legacy Stage document once, atomically promotes its useful
    /// order/group/trash state into the Shot timeline, and moves FINALS data
    /// to an Output-owned document. The legacy bytes are never overwritten.
    private func loadStageSet(for project: ProjectRecord) {
        let now = DateFormats.now()
        let legacy: ProjectStageSetDocument?
        switch contextStore.loadStageSet(for: project) {
        case .document(let loaded):
            stageSet = loaded
            legacy = loaded
        case .absent:
            stageSet = .empty(projectId: project.projectId)
            legacy = nil
        case .unreadable(let reason):
            stageSet = .empty(projectId: project.projectId)
            outputSequence = contextStore.loadOutputSequence(for: project)
                ?? .empty(projectId: project.projectId)
            lastError = "The legacy Stage document could not be read (\(reason)). Showing the canonical Shot order; the saved Stage bytes were left untouched for recovery."
            return
        }

        let existingOutput = contextStore.loadOutputSequence(for: project)
        guard shotTimeline.organizationVersion != ProjectShotTimelineDocument.flatOrganizationVersion else {
            outputSequence = existingOutput
                ?? ProjectOutputSequenceDocument.migrating(legacy: legacy, projectId: project.projectId, now: now)
            if existingOutput == nil {
                do {
                    try contextStore.saveOutputSequence(outputSequence, for: project)
                } catch {
                    lastError = error.localizedDescription
                }
            }
            return
        }

        let migratedTimeline = shotTimeline.flatteningLegacyOrganization(legacy, now: now)
        let migratedOutput = existingOutput
            ?? ProjectOutputSequenceDocument.migrating(legacy: legacy, projectId: project.projectId, now: now)
        do {
            try contextStore.saveFlatShotMigration(
                timeline: migratedTimeline,
                outputSequence: migratedOutput,
                for: project
            )
            shotTimeline = migratedTimeline
            outputSequence = migratedOutput
        } catch {
            // The in-memory view may still use the safe derived order, but the
            // marker remains unsaved so the next launch retries atomically.
            shotTimeline = migratedTimeline
            outputSequence = migratedOutput
            lastError = "The flat Shot migration could not be saved; the legacy Stage document is untouched and migration will retry. \(error.localizedDescription)"
        }
    }

    // MARK: - Flat Shot organization

    /// Creates one ordered Shot. Photos stay ordinary Media until this first
    /// use, when their pixels are adopted idempotently as a durable Frame.
    @discardableResult
    func createShot(
        lensId: String,
        withFrameImageId frameImageId: String? = nil,
        withMediaId mediaId: String? = nil
    ) -> String {
        guard let project = currentProject else { return "" }
        let now = DateFormats.now()
        var resolvedFrameId = frameImageId?.trimmed ?? ""
        var resolvedClipId = ""

        if let mediaId = mediaId?.trimmed.nilIfEmpty {
            let media = items.first { $0.mediaId == mediaId }
            let plan = shotMediaInsertPlan(
                media: media,
                adoptedFrameImageId: adoptedPhotoFrame(lensId: lensId, mediaId: mediaId)?.imageId
            )
            switch plan {
            case .refuse(let reason):
                aestheticStatus = reason
                return ""
            case .placeClip(let clipMediaId):
                resolvedClipId = clipMediaId
            case .placeFrame(let adoptedFrameId):
                resolvedFrameId = adoptedFrameId
            case .adoptImageAsFrame:
                guard let media,
                      addMediaImageAsFrame(media, lensId: lensId),
                      let adopted = adoptedPhotoFrame(lensId: lensId, mediaId: mediaId) else {
                    return ""
                }
                resolvedFrameId = adopted.imageId
            }
        }

        var timeline = shotTimeline.projectId == project.projectId
            ? shotTimeline
            : .empty(projectId: project.projectId)
        timeline.projectId = project.projectId
        let appended = timeline.appendingShot(name: "", now: now)
        timeline = appended.document
        if !resolvedFrameId.isEmpty {
            timeline = timeline.updatingShot(shotId: appended.shotId, now: now) {
                $0.insertingEntry(frameImageId: resolvedFrameId, at: 0, now: now)
            }
        } else if !resolvedClipId.isEmpty {
            timeline = timeline.updatingShot(shotId: appended.shotId, now: now) {
                $0.insertingClipEntry(clipMediaId: resolvedClipId, at: 0, now: now)
            }
        }
        persistShotTimeline(timeline, for: project)
        aestheticStatus = "Shot created"
        return appended.shotId
    }

    func moveShot(shotId: String, toVisibleIndex index: Int) {
        guard let project = currentProject else { return }
        let updated = shotTimeline.movingVisibleShot(
            shotId: shotId,
            toIndex: index,
            now: DateFormats.now()
        )
        guard updated != shotTimeline else { return }
        persistShotTimeline(updated, for: project)
    }

    func trashShot(shotId: String) {
        guard let project = currentProject else { return }
        guard !cutHasInFlightVideoOperation(cutId: shotId) else {
            aestheticStatus = "This Shot has active work — wait for it to finish before deleting"
            return
        }
        let now = DateFormats.now()
        let timeline = shotTimeline.trashingShot(shotId: shotId, now: now)
        guard timeline != shotTimeline else { return }
        let output = outputSequence.removingShot(shotId, now: now)
        persistShotTimelineAndOutputSequence(timeline: timeline, output: output, for: project)
        aestheticStatus = "Shot moved to DELETED SHOTS — restore any time"
    }

    func restoreShot(trashEntryId: String) {
        guard let project = currentProject else { return }
        let updated = shotTimeline.restoringShot(
            trashEntryId: trashEntryId,
            now: DateFormats.now()
        )
        guard updated != shotTimeline else { return }
        persistShotTimeline(updated, for: project)
        aestheticStatus = "Shot restored"
    }

    func combinedShotPreflight(sourceShotIds: [String]) -> CombinedCutPreflight {
        let visible = shotTimeline.visibleShots.map(\.shotId)
        guard sourceShotIds.count >= 2,
              let first = visible.firstIndex(of: sourceShotIds[0]),
              Array(visible.dropFirst(first).prefix(sourceShotIds.count)) == sourceShotIds else {
            return CombinedCutPreflight(
                sourceCutIds: sourceShotIds,
                hardFailures: ["Only adjacent visible Shots can be combined."]
            )
        }
        let sources = sourceShotIds.compactMap { shotId in
            shotTimeline.shots.first { $0.shotId == shotId }
        }
        guard sources.count == sourceShotIds.count else {
            return CombinedCutPreflight(
                sourceCutIds: sourceShotIds,
                hardFailures: ["One or more Shot records are missing."]
            )
        }
        var result = buildCombinedCut(
            sources: sources,
            frameLookup: projectWideFrameLookup,
            mediaLookup: Dictionary(items.map { ($0.mediaId, $0) }, uniquingKeysWith: { first, _ in first }),
            meaningNodes: lensContext.promptPacket().meaningNodes,
            now: DateFormats.now()
        ).preflight
        let activeSources = sourceShotIds.filter { shotId in
            cutHasInFlightVideoOperation(cutId: shotId)
                || activeShotNarrationId == shotId
                || activeShotNarrationSpeedId == shotId
                || activeShotChipsId == shotId
                || shotTimeline.shots.first(where: { $0.shotId == shotId })?.narrationArtifact?.status == "generating"
        }
        if !activeSources.isEmpty {
            result.hardFailures.append("Wait for active render, Look, narration, join, or recording work to finish.")
        }
        return result
    }

    @discardableResult
    func combineShots(sourceShotIds: [String]) -> String {
        guard let project = currentProject else { return "" }
        let preflight = combinedShotPreflight(sourceShotIds: sourceShotIds)
        guard preflight.canCombine else {
            aestheticStatus = preflight.hardFailures.first ?? "These Shots cannot be combined."
            return ""
        }
        let sources = sourceShotIds.compactMap { shotId in
            shotTimeline.shots.first { $0.shotId == shotId }
        }
        let now = DateFormats.now()
        let built = buildCombinedCut(
            sources: sources,
            frameLookup: projectWideFrameLookup,
            mediaLookup: Dictionary(items.map { ($0.mediaId, $0) }, uniquingKeysWith: { first, _ in first }),
            meaningNodes: lensContext.promptPacket().meaningNodes,
            now: now
        )
        guard built.preflight.hardFailures.isEmpty, !built.cut.shotId.isEmpty else {
            aestheticStatus = built.preflight.hardFailures.first ?? "Could not build the combined Shot."
            return ""
        }
        var timeline = shotTimeline
        timeline.shots.append(built.cut)
        timeline = timeline.groupingCombinedShot(
            parentShotId: built.cut.shotId,
            sourceShotIds: sourceShotIds,
            now: now
        )
        guard timeline.group(parentShotId: built.cut.shotId) != nil else {
            aestheticStatus = "The Shot order changed before combine could finish."
            return ""
        }
        // Sources leave the visible timeline, so their Ready Timeline picks
        // must leave the Output sequence with them (the trashShot cascade) —
        // otherwise the reel keeps baking scenes the band can no longer show.
        // The combined result is a new scene; readiness is a fresh decision.
        let readySources = sourceShotIds.filter { sourceId in
            outputSequence.shots.contains { $0.shotId == sourceId }
        }
        if readySources.isEmpty {
            persistShotTimeline(timeline, for: project)
        } else {
            var output = outputSequence
            for sourceId in readySources {
                output = output.removingShot(sourceId, now: now)
            }
            persistShotTimelineAndOutputSequence(timeline: timeline, output: output, for: project)
        }
        var status = built.preflight.missingSegmentCount == 0
            ? "Combined locally · $0 · all video reusable"
            : "Combined locally · $0 · \(built.preflight.missingSegmentCount) segment\(built.preflight.missingSegmentCount == 1 ? "" : "s") still need rendering"
        if !readySources.isEmpty {
            status += " · \(readySources.count) pick\(readySources.count == 1 ? "" : "s") left the Output sequence"
        }
        aestheticStatus = status
        return built.cut.shotId
    }

    func uncombineShot(parentShotId: String) {
        guard let project = currentProject else { return }
        guard !cutHasInFlightVideoOperation(cutId: parentShotId) else {
            aestheticStatus = "This combined Shot has active work — wait for it to finish before uncombining."
            return
        }
        let now = DateFormats.now()
        let updated = shotTimeline.ungroupingCombinedShot(
            parentShotId: parentShotId,
            now: now
        )
        guard updated != shotTimeline else { return }
        // The parent moves to DELETED SHOTS, so its Ready Timeline pick goes
        // with it (the trashShot cascade). Sources do not inherit readiness —
        // membership is a per-scene review decision.
        if outputSequence.shots.contains(where: { $0.shotId == parentShotId }) {
            let output = outputSequence.removingShot(parentShotId, now: now)
            persistShotTimelineAndOutputSequence(timeline: updated, output: output, for: project)
            aestheticStatus = "Source Shots restored; the combined Shot (and its Output-sequence pick) is in DELETED SHOTS."
        } else {
            persistShotTimeline(updated, for: project)
            aestheticStatus = "Source Shots restored; the combined Shot is in DELETED SHOTS."
        }
    }

    private func persistStageSet(_ document: ProjectStageSetDocument, for project: ProjectRecord) {
        do {
            try contextStore.saveStageSet(document, for: project)
            // Currency half of THE PROJECT IDENTITY LAW — same as
            // persistShotTimeline: a stale-project write stays durable but
            // must never replace the current project's in-memory stage set.
            if currentProject?.projectId == project.projectId {
                stageSet = document
            }
        } catch {
            lastError = error.localizedDescription
        }
    }

    @discardableResult
    func createStage(name: String = "") -> String {
        guard let project = currentProject else { return "" }
        let now = DateFormats.now()
        var document = stageSet.projectId == project.projectId ? stageSet : .empty(projectId: project.projectId)
        document.projectId = project.projectId
        let (appended, stageId) = document.appendingStage(name: name, now: now)
        persistStageSet(appended, for: project)
        return stageId
    }

    func renameStage(stageId: String, name: String) {
        guard let project = currentProject else { return }
        persistStageSet(stageSet.renamingStage(stageId: stageId, name: name, now: DateFormats.now()), for: project)
    }

    /// Deletes the stage; its cuts move to DELETED CUTS (soft-delete — their
    /// timeline rows and renders survive). Frames and footage referenced by
    /// its inputs are untouched — references only.
    func deleteStage(stageId: String) {
        guard let project = currentProject else { return }
        guard let stage = stageSet.stage(withId: stageId) else { return }
        if let rendering = stage.cutIds.first(where: { cutHasInFlightVideoOperation(cutId: $0) }) {
            let name = shotTimeline.shots.first { $0.shotId == rendering }?.name.trimmed.nilIfEmpty ?? "A cut"
            aestheticStatus = "\(name) is rendering — wait for it to finish (or cancel it) before deleting this stage"
            return
        }
        let now = DateFormats.now()
        var document = stageSet
        for cutId in stage.cutIds {
            document = document.trashingCut(cutId: cutId, now: now)
        }
        let (deleted, _) = document.deletingStage(stageId: stageId, now: now)
        persistStageSet(deleted, for: project)
    }

    func moveStage(stageId: String, toIndex index: Int) {
        guard let project = currentProject else { return }
        persistStageSet(stageSet.movingStage(stageId: stageId, toIndex: index, now: DateFormats.now()), for: project)
    }

    /// Re-arranges a cut's position in its stage, or re-homes it onto another
    /// stage at a position. `index` is an insertion point in the DESTINATION
    /// stage's VISIBLE order.
    ///
    /// Writes only `project_stage_set` — the shot timeline is never touched,
    /// so the orphan-adoption sweep in `syncStageSetWithTimeline` can never
    /// catch the cut unclaimed. Deliberately unguarded during a render, unlike
    /// `deleteStage`: a cut's position is presentational (it drives the rail
    /// numerals and COMBINE adjacency — never a rendered artifact), and an
    /// open combine review re-validates visible
    /// adjacency at commit and refuses honestly if the order moved underneath.
    func moveCut(cutId: String, toStage stageId: String, toVisibleIndex index: Int) {
        guard let project = currentProject else { return }
        let formerStageId = stageSet.stage(containingCut: cutId)?.stageId ?? ""
        let updated = stageSet.movingCut(
            cutId: cutId,
            toStage: stageId,
            toVisibleIndex: index,
            now: DateFormats.now()
        )
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
        // A cross-stage move teleports the row on an unbounded page; this line
        // is the only confirmation the operator gets.
        if formerStageId != stageId {
            let name = updated.stage(withId: stageId)?.name.trimmed.nilIfEmpty ?? "another stage"
            aestheticStatus = "Cut moved to \(name)"
        }
    }

    /// Gathers a frame into the stage's unordered palette. Re-gathering an
    /// asset the stage already holds is a friendly no-op.
    func addStageFrameInput(stageId: String, frameImageId: String) {
        guard let project = currentProject else { return }
        guard !frameImageId.trimmed.isEmpty else { return }
        let updated = stageSet.addingInput(stageId: stageId, frameImageId: frameImageId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
    }

    /// Gathers footage (source video or Studio trim) into the stage palette.
    func addStageClipInput(stageId: String, mediaId: String) {
        guard let project = currentProject else { return }
        guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video else {
            aestheticStatus = "Only videos can be gathered as footage"
            return
        }
        let updated = stageSet.addingInput(stageId: stageId, clipMediaId: media.mediaId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
        aestheticStatus = "Gathered footage \(media.filename)"
    }

    /// Gathers ANY media into a stage palette — the same kind-branching law
    /// as `insertShotMedia`: footage gathers as a clip reference, images
    /// gather as their adopted-or-minted Frame. No frozenCutPermits — the
    /// palette is not a cut edit, matching `addStageClipInput`.
    func addStageMediaInput(stageId: String, mediaId: String, lensId: String) {
        let media = items.first { $0.mediaId == mediaId }
        let plan = shotMediaInsertPlan(
            media: media,
            adoptedFrameImageId: adoptedPhotoFrame(lensId: lensId, mediaId: mediaId)?.imageId
        )
        switch plan {
        case .refuse(let reason):
            aestheticStatus = reason
        case .placeClip(let clipMediaId):
            addStageClipInput(stageId: stageId, mediaId: clipMediaId)
        case .placeFrame(let frameImageId):
            addStageFrameInput(stageId: stageId, frameImageId: frameImageId)
        case .adoptImageAsFrame:
            guard let media,
                  addMediaImageAsFrame(media, lensId: lensId),
                  let adopted = adoptedPhotoFrame(lensId: lensId, mediaId: mediaId) else {
                return
            }
            addStageFrameInput(stageId: stageId, frameImageId: adopted.imageId)
            aestheticStatus = "Added \(media.filename) as a Frame and gathered it onto the stage"
        }
    }

    /// Removes one palette reference. Never deletes the frame/footage itself,
    /// and never touches cut entries that use the same asset.
    func removeStageInput(stageId: String, inputId: String) {
        guard let project = currentProject else { return }
        let updated = stageSet.removingInput(stageId: stageId, inputId: inputId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
    }

    func moveStageInput(inputId: String, toStage stageId: String) {
        guard let project = currentProject else { return }
        let updated = stageSet.movingInput(inputId: inputId, toStage: stageId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
    }

    /// Creates a cut owned by the given stage — the ordered timeline that
    /// renders video. Optionally opens with a first frame or footage entry.
    @discardableResult
    func createCut(inStage stageId: String, withFrameImageId frameImageId: String? = nil, withClipMediaId mediaId: String? = nil) -> String {
        guard let project = currentProject else { return "" }
        guard stageSet.stage(withId: stageId) != nil else { return "" }
        let now = DateFormats.now()
        var timeline = shotTimeline.projectId == project.projectId ? shotTimeline : .empty(projectId: project.projectId)
        timeline.projectId = project.projectId
        let (appended, cutId) = timeline.appendingShot(name: "", now: now)
        timeline = appended
        if let frameImageId, !frameImageId.trimmed.isEmpty {
            timeline = timeline.updatingShot(shotId: cutId, now: now) {
                $0.insertingEntry(frameImageId: frameImageId, at: 0, now: now)
            }
        } else if let mediaId, !mediaId.trimmed.isEmpty {
            guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video else {
                aestheticStatus = "Only videos can be placed as footage"
                return ""
            }
            timeline = timeline.updatingShot(shotId: cutId, now: now) {
                $0.insertingClipEntry(clipMediaId: media.mediaId, at: 0, now: now)
            }
        }
        persistShotTimeline(timeline, for: project, syncStages: false)
        persistStageSet(stageSet.attachingCut(cutId: cutId, toStage: stageId, now: now), for: project)
        return cutId
    }

    func addCutToFinals(cutId: String) {
        guard let project = currentProject else { return }
        let updated = stageSet.addingFinal(cutId: cutId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
        aestheticStatus = "Cut added to FINALS"
    }

    func removeFinalsEntry(entryId: String) {
        guard let project = currentProject else { return }
        let updated = stageSet.removingFinal(entryId: entryId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
    }

    func moveFinalsEntry(entryId: String, toIndex index: Int) {
        guard let project = currentProject else { return }
        let updated = stageSet.movingFinal(entryId: entryId, toIndex: index, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
    }

    /// Soft-deletes a cut: it leaves its stage and FINALS for the DELETED CUTS
    /// shelf. The timeline row — and every render it paid for — is untouched.
    /// True when an in-flight paid video operation (shot render, razor-join
    /// bridge, or Shot Look) belongs to this cut. Trashing it would hide the
    /// running work while its lock still blocks every other cut — the canvas
    /// would say "Another cut is rendering" and point at nothing.
    func cutHasInFlightVideoOperation(cutId: String) -> Bool {
        if activeShotRenderId == cutId { return true }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == cutId }) else { return false }
        if !activeShotJoinRenderId.isEmpty,
           shot.cutList.segmentCuts.contains(where: { $0.cutId == activeShotJoinRenderId }) {
            return true
        }
        if !activeShotRestyleId.isEmpty,
           shot.lookVersions.contains(where: { $0.versionId == activeShotRestyleId }) {
            return true
        }
        return false
    }

    func trashCut(cutId: String) {
        guard let project = currentProject else { return }
        guard !cutHasInFlightVideoOperation(cutId: cutId) else {
            aestheticStatus = "This cut is rendering — wait for it to finish (or cancel it) before trashing"
            return
        }
        let updated = stageSet.trashingCut(cutId: cutId, now: DateFormats.now())
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
        aestheticStatus = "Cut moved to DELETED CUTS — restore any time"
    }

    /// Restores a trashed cut to its former stage (else the first stage; a
    /// project with no stages left gets one founded and named after the cut).
    func restoreCut(trashEntryId: String) {
        guard let project = currentProject else { return }
        let now = DateFormats.now()
        let (document, cutId, attachedStageId) = stageSet.restoringCut(trashEntryId: trashEntryId, now: now)
        guard !cutId.isEmpty else { return }
        persistStageSet(document, for: project)
        if attachedStageId == nil {
            let cutName = shotTimeline.shots.first { $0.shotId == cutId }?.name ?? ""
            let stageId = createStage(name: cutName)
            guard !stageId.isEmpty else { return }
            persistStageSet(stageSet.attachingCut(cutId: cutId, toStage: stageId, now: now), for: project)
        }
        aestheticStatus = "Cut restored"
    }

    func combinedCutPreflight(
        stageId: String,
        sourceCutIds: [String]
    ) -> CombinedCutPreflight {
        guard let stage = stageSet.stage(withId: stageId) else {
            return CombinedCutPreflight(hardFailures: ["Stage not found."])
        }
        let visible = stageSet.visibleCutIds(in: stage)
        guard sourceCutIds.count >= 2,
              let first = visible.firstIndex(of: sourceCutIds[0]),
              Array(visible.dropFirst(first).prefix(sourceCutIds.count)) == sourceCutIds else {
            return CombinedCutPreflight(
                sourceCutIds: sourceCutIds,
                hardFailures: ["Only adjacent visible CUTs can be combined."]
            )
        }
        let sources = sourceCutIds.compactMap { cutId in
            shotTimeline.shots.first { $0.shotId == cutId }
        }
        guard sources.count == sourceCutIds.count else {
            return CombinedCutPreflight(
                sourceCutIds: sourceCutIds,
                hardFailures: ["One or more source CUT records are missing."]
            )
        }
        var result = buildCombinedCut(
            sources: sources,
            frameLookup: projectWideFrameLookup,
            mediaLookup: Dictionary(items.map { ($0.mediaId, $0) }, uniquingKeysWith: { first, _ in first }),
            meaningNodes: lensContext.promptPacket().meaningNodes,
            now: DateFormats.now()
        ).preflight
        let activeSources = sourceCutIds.filter { cutId in
            cutHasInFlightVideoOperation(cutId: cutId)
                || activeShotNarrationId == cutId
                || activeShotNarrationSpeedId == cutId
                || activeShotChipsId == cutId
                || shotTimeline.shots.first(where: { $0.shotId == cutId })?.narrationArtifact?.status == "generating"
        }
        if !activeSources.isEmpty {
            result.hardFailures.append("Wait for active render, Look, narration, join, or recording work to finish.")
        }
        return result
    }

    /// Locally copies adjacent source timelines, then commits the new timeline
    /// and its Stage collapse through one SQLite transaction. In-memory state
    /// changes only after both canonical documents are durable.
    @discardableResult
    func combineCuts(
        stageId: String,
        sourceCutIds: [String]
    ) -> String {
        guard let project = currentProject else { return "" }
        let preflight = combinedCutPreflight(stageId: stageId, sourceCutIds: sourceCutIds)
        guard preflight.canCombine else {
            aestheticStatus = preflight.hardFailures.first ?? "These CUTs cannot be combined."
            return ""
        }
        let sources = sourceCutIds.compactMap { cutId in
            shotTimeline.shots.first { $0.shotId == cutId }
        }
        let now = DateFormats.now()
        let built = buildCombinedCut(
            sources: sources,
            frameLookup: projectWideFrameLookup,
            mediaLookup: Dictionary(items.map { ($0.mediaId, $0) }, uniquingKeysWith: { first, _ in first }),
            meaningNodes: lensContext.promptPacket().meaningNodes,
            now: now
        )
        guard built.preflight.hardFailures.isEmpty, !built.cut.shotId.isEmpty else {
            aestheticStatus = built.preflight.hardFailures.first ?? "Could not build the combined CUT."
            return ""
        }

        var timeline = shotTimeline
        let insertionIndex = sourceCutIds
            .compactMap { cutId in timeline.shots.firstIndex { $0.shotId == cutId } }
            .min() ?? timeline.shots.count
        timeline.shots.insert(built.cut, at: insertionIndex)
        timeline.updatedAt = now
        let groupedStageSet = stageSet.groupingCombinedCut(
            parentCutId: built.cut.shotId,
            sourceCutIds: sourceCutIds,
            inStage: stageId,
            now: now
        )
        guard groupedStageSet.group(parentCutId: built.cut.shotId) != nil else {
            aestheticStatus = "The Stage order changed before combine could finish."
            return ""
        }
        let canonicalTimeline = timeline.normalized()
        let canonicalStageSet = groupedStageSet.normalized()
        do {
            try contextStore.saveShotTimelineAndStageSet(
                timeline: canonicalTimeline,
                stageSet: canonicalStageSet,
                for: project
            )
            shotTimeline = canonicalTimeline
            stageSet = canonicalStageSet
            aestheticStatus = built.preflight.missingSegmentCount == 0
                ? "Combined locally · $0 · all video reusable"
                : "Combined locally · $0 · \(built.preflight.missingSegmentCount) segment\(built.preflight.missingSegmentCount == 1 ? "" : "s") still need rendering"
            return built.cut.shotId
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Combine was not saved; the source CUTs are unchanged."
            return ""
        }
    }

    func uncombineCut(parentCutId: String) {
        guard let project = currentProject else { return }
        guard !cutHasInFlightVideoOperation(cutId: parentCutId) else {
            aestheticStatus = "This combined CUT has active work — wait for it to finish before uncombining."
            return
        }
        let updated = stageSet.ungroupingCombinedCut(
            parentCutId: parentCutId,
            now: DateFormats.now()
        )
        guard updated != stageSet else { return }
        persistStageSet(updated, for: project)
        aestheticStatus = "Source CUTs restored; the combined CUT is in DELETED CUTS."
    }

    /// The NEW VERSION gesture on a rendered (locked) cut: a fresh, unrendered
    /// copy of the timeline seated right after the original on its stage.
    @discardableResult
    func duplicateCut(cutId: String) -> String {
        guard let project = currentProject else { return "" }
        guard let index = shotTimeline.shots.firstIndex(where: { $0.shotId == cutId }) else { return "" }
        let now = DateFormats.now()
        let copy = shotTimeline.shots[index].duplicated(now: now)
        var timeline = shotTimeline
        timeline.shots.insert(copy, at: min(index + 1, timeline.shots.count))
        timeline.updatedAt = now
        persistShotTimeline(timeline, for: project, syncStages: false)
        aestheticStatus = "New version created — edit and render it independently"
        return copy.shotId
    }

    /// Duplicates a ready frame as a fully independent row (its image file is
    /// copied on disk, so downstream flows that collapse by file never merge
    /// the two). The copy inherits the source's stage memberships — duplicate
    /// on a stage, then drag the copy wherever it's needed.
    func duplicateLensHeroImage(lensId: String, imageId: String) {
        guard let project = currentProject else { return }
        guard let lens = projectLenses.lenses.first(where: { $0.lensId == lensId }) else {
            aestheticStatus = "Scene Plan not found"
            return
        }
        var heroImages = lens.sortedHeroImages
        guard let source = heroImages.first(where: { $0.imageId == imageId })?.normalized() else {
            aestheticStatus = "Frame not found"
            return
        }
        guard source.status == "ready", !source.imagePath.trimmed.isEmpty,
              FileManager.default.fileExists(atPath: source.imagePath) else {
            aestheticStatus = "Only rendered frames can be duplicated"
            return
        }
        let now = DateFormats.now()
        let newImageId = "lens_hero_\(shortHash("\(project.projectId):\(lensId):\(imageId):dup:\(now):\(UUID().uuidString)", length: 14))"
        let sourceURL = URL(fileURLWithPath: source.imagePath)
        let destinationURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("dup_\(shortHash(newImageId, length: 12))_\(sourceURL.lastPathComponent)")
        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            try FileManager.default.copyItem(at: sourceURL, to: destinationURL)
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not copy the frame's image file"
            return
        }
        var duplicate = source
        duplicate.imageId = newImageId
        duplicate.imagePath = destinationURL.path
        duplicate.label = source.label.trimmed.isEmpty ? "copy" : "\(source.label) · copy"
        duplicate.imageIndex = (heroImages.map(\.imageIndex).max() ?? source.imageIndex) + 1
        duplicate.kept = nil
        duplicate.requestId = ""
        duplicate.traceId = ""
        duplicate.errorMessage = ""
        duplicate.generatedAt = now
        duplicate.updatedAt = now
        heroImages.append(duplicate.normalized())
        guard saveLensHeroImages(
            heroImages,
            lensId: lensId,
            project: project,
            status: "Frame duplicated",
            changeSummary: "Duplicated \(source.label.trimmed.isEmpty ? "a frame" : source.label)."
        ) else {
            try? FileManager.default.removeItem(at: destinationURL)
            return
        }
        inheritStageMembership(fromImageId: source.imageId, toImageId: newImageId)
        aestheticStatus = "Frame duplicated — drag the copy to another stage to reuse it"
    }

    // MARK: - Collect Frame (a playhead still from the shot player)

    @Published private(set) var isCollectingShotFrame = false

    /// Captures a still of the shot player's current playhead moment into the
    /// media library: extract from the SOURCE file (segment clip, bridge,
    /// Look, or stitched video — the player maps output time to file time),
    /// archive as a NON-rejected `collected_shot_frame` so it lands in Story
    /// Inputs, lists under Creations ▸ Shot Artifacts, and is immediately
    /// usable as a Frame Creator reference. Deterministic id: recapturing the
    /// same file moment replaces rather than duplicates.
    @discardableResult
    func collectShotFrameStill(
        shotId: String,
        sourceVideoPath: String,
        fileSeconds: Double,
        outputSeconds: Double
    ) async -> MediaItemRecord? {
        guard let project = currentProject,
              !sourceVideoPath.trimmed.isEmpty,
              FileManager.default.fileExists(atPath: sourceVideoPath) else {
            aestheticStatus = "There is no rendered video to collect from"
            return nil
        }
        guard !isCollectingShotFrame else { return nil }
        isCollectingShotFrame = true
        defer { isCollectingShotFrame = false }
        let shotName = shotTimeline.shots.first { $0.shotId == shotId }?.name.trimmed ?? ""
        let mediaId = "genmedia_\(shortHash("\(project.projectId):shot_frame:\(shotId):\(sourceVideoPath):\(String(format: "%.3f", fileSeconds))", length: 20))"
        let stillURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("shotframe_\(shortHash(mediaId, length: 12)).png")
        do {
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            _ = try await VideoChainMedia.extractFrameStill(
                videoURL: URL(fileURLWithPath: sourceVideoPath),
                atSeconds: max(fileSeconds, 0),
                outputURL: stillURL
            )
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not extract the frame"
            return nil
        }
        let timestampLabel = String(format: "%.1fs", outputSeconds)
        // Provenance only — a collected frame lists under Creations, not nested
        // in the source's stills tray, so this never has to resolve to be useful.
        let sourceMediaId = items.first { $0.path == sourceVideoPath }?.mediaId ?? ""
        let item = await archiveGeneratedMedia(
            fileURL: stillURL,
            project: project,
            mediaId: mediaId,
            derivativeKind: MediaItemRecord.collectedShotFrameDerivativeKind,
            sourceMediaId: sourceMediaId,
            sourceTimestampSeconds: outputSeconds,
            filename: "Shot \(shotName.isEmpty ? "frame" : shotName) @\(timestampLabel).png",
            tags: ["shot", "collected"],
            notes: "Collected from the shot player",
            rejectedByDefault: false
        )
        aestheticStatus = item == nil
            ? "Could not collect the frame"
            : "Frame collected to Media — it's a Story Input and a Frame Creator reference now"
        return item
    }

    // MARK: - FAL video pricing (render-plan strip cost estimates)

    private static let falPricingCacheMaxAge: TimeInterval = 86_400

    private var falPricingCacheURL: URL {
        litScenesApplicationSupportDirectory().appendingPathComponent("fal_video_pricing.json")
    }

    /// Every endpoint the app can bill through FAL: the video segment models and
    /// each FAL image stack's base and edit endpoints. One GET, one snapshot.
    private var falPricingEndpointIds: [String] {
        let video = [
            ShotRenderModel.falKlingV3Pro,
            ShotRenderModel.falSeedance20,
            ShotRenderModel.falSeedance25,
            ShotRenderModel.wan27,
            ShotRenderModel.falHailuo3,
            ShotRenderModel.falHailuo3Max,
            ShotRenderModel.falLTX23Narration
        ].map { ShotRenderStack.fallback.replacingModel($0).pairedModelSelection.providerModelId }
        return uniqueNonEmpty(video + FALImagePricing.endpointIds(stacks: RenderStackRegistry.shared.stacks()))
    }

    /// THE IMAGE PRICE LAW's stated note for a stack: the live FAL rate when the
    /// snapshot can read it, else the stack's own note, else "" (unpriced).
    func priceNote(for stack: RenderStack, attachesReferences: Bool) -> String {
        FALImagePricing.displayNote(stack: stack, attachesReferences: attachesReferences, snapshot: falPricing)
    }

    /// A finished image render's estimate from the endpoint that was actually
    /// called and the file's pixels; nil when the rate cannot be read.
    func estimatedImageUSD(endpointId: String, outputPath: String) -> Double? {
        guard !endpointId.trimmed.isEmpty else { return nil }
        let pixels = (try? Data(contentsOf: URL(fileURLWithPath: outputPath)))
            .flatMap(imagePixelSize(from:))
            .map { $0.width * $0.height }
        return FALImagePricing.renderedEstimateUSD(endpointId: endpointId, snapshot: falPricing, outputPixels: pixels)
    }

    /// The ledger's pricing note for a finished render: the live rate note for the
    /// endpoint that was called, else the recipe's provider note.
    func ledgerPricingNote(endpointId: String, fallback: String) -> String {
        if let price = falPricing?.prices[endpointId.trimmed], let note = FALImagePricing.rateNote(price: price) {
            return note
        }
        return fallback
    }

    /// Loads the cached snapshot (first call) and re-fetches when it is over
    /// ~a day old or missing endpoints. Failures keep whatever we had — the
    /// strip shows the snapshot's age, and rendering never waits on this.
    func refreshFALPricingIfStale(maxAge: TimeInterval = LibraryEngine.falPricingCacheMaxAge) async {
        if falPricing == nil,
           let data = try? Data(contentsOf: falPricingCacheURL),
           let cached = try? JSONDecoder().decode(FALPricingSnapshot.self, from: data) {
            falPricing = cached
        }
        let wantedIds = Set(falPricingEndpointIds)
        if let snapshot = falPricing,
           snapshot.ageSeconds < maxAge,
           wantedIds.isSubset(of: Set(snapshot.prices.keys)) {
            return
        }
        guard !isFetchingFALPricing else { return }
        let apiKey = videoCredentialStore.resolvedCredential(for: .fal).trimmed
        guard !apiKey.isEmpty else { return }
        isFetchingFALPricing = true
        defer { isFetchingFALPricing = false }
        do {
            let prices = try await FALPricingClient().fetchPrices(
                endpointIds: Array(wantedIds).sorted(),
                apiKey: apiKey
            )
            let snapshot = FALPricingSnapshot(
                fetchedAt: Date(),
                prices: Dictionary(prices.map { ($0.endpointId, $0) }, uniquingKeysWith: { first, _ in first })
            )
            falPricing = snapshot
            try? ensureDirectory(litScenesApplicationSupportDirectory())
            if let data = try? JSONEncoder().encode(snapshot) {
                try? data.write(to: falPricingCacheURL, options: .atomic)
            }
        } catch {
            // Stale-or-nothing is acceptable: the strip labels the age or
            // shows "rates unavailable"; never surface this as a hard error.
        }
    }

    /// Momentum rule: a frame derived from a staged frame (sibling, variation,
    /// reframe, zoom-out) joins the same stages as its source — new material
    /// lands where the attention already is, never in the backlot by accident.
    private func inheritStageMembership(fromImageId sourceImageId: String, toImageId newImageId: String) {
        guard let project = currentProject else { return }
        guard !sourceImageId.isEmpty, !newImageId.isEmpty, sourceImageId != newImageId else { return }
        let owningStages = stageSet.stages(containingFrame: sourceImageId)
        guard !owningStages.isEmpty else { return }
        var document = stageSet
        let now = DateFormats.now()
        for stage in owningStages {
            document = document.addingInput(stageId: stage.stageId, frameImageId: newImageId, now: now)
        }
        guard document != stageSet else { return }
        persistStageSet(document, for: project)
    }

    // MARK: - Shot rendering (keyframe-interpolated video per shot)

