    /// The per-segment plan the Re-render sheet shows — resolves the lens,
    /// media inventory, and meaning nodes exactly as `renderShot` does, so the
    /// sheet previews the very segments (and prompts) a render would produce.
    func shotRenderPromptPlan(shotId: String) -> (
        segments: [ShotRenderPlanSegment],
        skipped: [String],
        skippedPlaceholders: [ShotSkippedSegmentPlaceholder]
    )? {
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            return nil
        }
        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let mediaLookup = Dictionary(
            items.map { ($0.mediaId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let plan = shotRenderSegmentPlan(
            shot: shot,
            frameLookup: frameLookup,
            mediaLookup: mediaLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )
        return (plan.segments, plan.skipped, plan.skippedPlaceholders)
    }

    /// Upserts a render version on the shot and makes it the active one (the
    /// newest render is always the selected render; one render runs at a time).
    private func persistShotRenderVersion(_ version: ShotRenderArtifact, shotId: String, for project: ProjectRecord) {
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.upsertingRenderVersion(version, activate: true, now: now)
            },
            for: project
        )
    }

    /// The async LTX submit returns before polling. Persist its job id at that
    /// boundary so a quit, cancellation, or poll failure still leaves the
    /// paid remote interaction inspectable and retry-safe.
    private func persistSubmittedShotRenderJob(
        shotId: String,
        versionId: String,
        jobId: String,
        traceId: String,
        project: ProjectRecord
    ) {
        guard currentProject?.projectId == project.projectId,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              var version = shot.renderVersions.first(where: { $0.versionId == versionId }) else {
            return
        }
        if !jobId.trimmed.isEmpty, !version.requestIds.contains(jobId) {
            version.requestIds.append(jobId)
        }
        version.progressText = "LTX EXTEND SUBMITTED · \(jobId)"
        version.updatedAt = DateFormats.now()
        persistShotRenderVersion(version, shotId: shotId, for: project)
        logGeneration(
            kind: "video.submitted",
            message: "Shot native extend submitted shot_id=\(shotId) request_id=\(jobId) trace_id=\(traceId)"
        )
    }

    private func absorbingSubmittedShotRenderJobs(
        _ artifact: ShotRenderArtifact,
        shotId: String
    ) -> ShotRenderArtifact {
        guard let live = shotTimeline.shots
            .first(where: { $0.shotId == shotId })?
            .renderVersions
            .first(where: { $0.versionId == artifact.versionId }) else {
            return artifact
        }
        var value = artifact
        value.requestIds = uniqueNonEmpty(value.requestIds + live.requestIds)
        return value
    }

    /// Selects an existing render version as the shot's active render (the
    /// version browser's tap). Refused while that shot is rendering.
    func activateShotRenderVersion(shotId: String, versionId: String) {
        guard let project = currentProject else { return }
        guard activeShotRenderId != shotId else {
            aestheticStatus = "Wait for this shot's render to finish"
            return
        }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.activatingRenderVersion(versionId, now: now)
            },
            for: project
        )
    }

    // MARK: - Shot Looks (Lucy restyle finishing pass)

    func shotLookPromptSeed() -> String {
        guard let direction = projectAestheticBrief.chosenDirection else { return "" }
        var lines: [String] = []
        if !direction.visualSummary.trimmed.isEmpty {
            lines.append(direction.visualSummary.trimmed)
        }
        if !direction.treatmentNotes.isEmpty {
            lines.append("Treatment: \(direction.treatmentNotes.joined(separator: ", "))")
        }
        if !direction.paletteTerms.isEmpty {
            lines.append("Palette: \(direction.paletteTerms.joined(separator: ", "))")
        }
        if !direction.signatureTerms.isEmpty {
            lines.append("Visual signatures: \(direction.signatureTerms.joined(separator: ", "))")
        }
        if !direction.avoidTerms.isEmpty {
            lines.append("Avoid: \(direction.avoidTerms.joined(separator: ", "))")
        }
        return String(lines.joined(separator: ". ").prefix(1_500))
    }

    func activateShotLookVersion(shotId: String, versionId: String) {
        guard let project = currentProject else { return }
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.activatingLookVersion(versionId, now: now)
            },
            for: project
        )
    }

    func startShotLookRestyle(
        shotId: String,
        prompt: String,
        enhancePrompt: Bool,
        seed: Int,
        style: ShotLookStyleSelection? = nil,
        provider: ShotLookProvider = .fal
    ) {
        guard shotRestyleTask == nil,
              activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty else {
            aestheticStatus = "Another video operation is already running"
            return
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return
        }
        guard videoCredentialStore.credentialStatus(for: provider.credentialProvider).isConfigured else {
            aestheticStatus = "Add a \(provider == .fal ? "FAL" : "Decart") API key in App Settings to create a Look"
            return
        }
        let resolvedStyle = (style?.isUsable == true) ? style : nil
        let finalPrompt: String
        switch provider {
        case .fal:
            finalPrompt = String(
                shotLookComposedPrompt(styleSummary: resolvedStyle?.summary ?? "", userText: prompt).prefix(1_500)
            )
            guard !finalPrompt.isEmpty else {
                aestheticStatus = "Pick a style or describe the Look before rendering"
                return
            }
        case .decart:
            guard resolvedStyle?.hasUsableImageReference == true else {
                aestheticStatus = "Choose a verified catalog style for Decart image input"
                return
            }
            finalPrompt = ""
        }
        shotRestyleTask = Task { [weak self] in
            guard let self else { return }
            await self.performShotLookRestyle(
                shotId: shotId,
                prompt: finalPrompt,
                enhancePrompt: enhancePrompt,
                seed: max(seed, 0),
                style: resolvedStyle,
                provider: provider
            )
            self.shotRestyleTask = nil
        }
    }

    func cancelShotLookRestyle(shotId: String) {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let artifact = shot.lookVersions.first(where: { $0.versionId == activeShotRestyleId })
                ?? shot.lookVersions.last(where: { ["preparing", "uploading", "queued", "generating", "downloading"].contains($0.status) }) else {
            return
        }
        shotRestyleTask?.cancel()
        var canceled = artifact
        let remoteContinues = artifact.restyleProvider == .decart && !artifact.requestId.isEmpty
        canceled.status = remoteContinues ? "paused" : "canceled"
        if remoteContinues {
            canceled.errorMessage = "Stopped waiting locally. Decart may keep processing or charging; Resume Look checks this job without submitting again."
        } else if artifact.restyleProvider == .decart && artifact.status == "uploading" {
            canceled.errorMessage = "Stopped before Decart returned a job id. Remote acceptance is unknown; check Decart before retrying to avoid duplicate spend."
        } else {
            canceled.errorMessage = "Canceled by operator"
        }
        canceled.updatedAt = DateFormats.now()
        persistShotLookVersion(canceled, shotId: shotId, activate: false, for: project)
        activeShotRestyleId = ""
        aestheticStatus = remoteContinues ? "Stopped waiting for Decart Look" : "Look canceled"
        if remoteContinues, let request = try? decartRestyleRequest(for: artifact, project: project) {
            Task {
                await DecartVideoClient(credentialStore: videoCredentialStore)
                    .recordStopWaiting(request, jobId: artifact.requestId)
            }
        }
        guard artifact.restyleProvider == .fal, !artifact.requestId.isEmpty else { return }
        let request = falRestyleRequest(for: artifact, project: project)
        Task {
            await FALVideoClient(credentialStore: videoCredentialStore)
                .cancelRestyle(requestId: artifact.requestId, context: request)
        }
    }

    func retryShotLook(shotId: String, versionId: String) {
        guard shotRestyleTask == nil,
              activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty,
              let artifact = shotTimeline.shots.first(where: { $0.shotId == shotId })?
                .lookVersions.first(where: { $0.versionId == versionId }),
              ["failed", "paused", "queued", "generating", "downloading"].contains(artifact.status),
              !artifact.requestId.isEmpty else { return }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return
        }
        guard videoCredentialStore.credentialStatus(for: artifact.restyleProvider.credentialProvider).isConfigured else {
            aestheticStatus = "Add a \(artifact.restyleProvider == .fal ? "FAL" : "Decart") API key in App Settings to recover this Look"
            return
        }
        shotRestyleTask = Task { [weak self] in
            guard let self else { return }
            await self.resumeShotLook(artifact, shotId: shotId)
            self.shotRestyleTask = nil
        }
    }

    private func persistShotLookVersion(
        _ version: ShotRestyleArtifact,
        shotId: String,
        activate: Bool,
        for project: ProjectRecord
    ) {
        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.upsertingLookVersion(version, activate: activate, now: now)
            },
            for: project
        )
    }

    private func performShotLookRestyle(
        shotId: String,
        prompt: String,
        enhancePrompt: Bool,
        seed: Int,
        style: ShotLookStyleSelection?,
        provider: ShotLookProvider
    ) async {
        guard let project = currentProject,
              let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let promptPlan = shotRenderPromptPlan(shotId: shotId) else {
            aestheticStatus = "Shot Look source is unavailable"
            return
        }
        let assembly = await resolvedShotLookAssembly(
            shot: shot,
            planSegments: promptPlan.segments,
            reversed: shot.cutList.isReversed,
            // Restyle the BASE once: cost, the 600s source cap, and the
            // visual fingerprint all stay unlooped; playback tiles the Look.
            includeOutputLoop: false
        )
        guard !Task.isCancelled, currentProject?.projectId == project.projectId else { return }
        let now = DateFormats.now()
        let versionNumber = (shot.lookVersions.map(\.versionNumber).max() ?? 0) + 1
        let versionId = "shotlook_\(shortHash("\(project.projectId):\(shotId):\(now):\(UUID().uuidString)", length: 18))"
        var artifact = ShotRestyleArtifact(
            versionId: versionId,
            versionNumber: versionNumber,
            status: "preparing",
            sourceShotId: shotId,
            sourceRenderVersionId: shot.activeRenderVersionId,
            sourceVisualFingerprint: shotLookVisualFingerprint(shot: shot, assembly: assembly),
            sourceIsReversed: shot.cutList.isReversed,
            prompt: prompt,
            enhancePrompt: provider == .fal && enhancePrompt,
            seed: seed,
            provider: provider.rawValue,
            model: provider.modelId,
            inputMode: provider.inputMode,
            estimatedCostUSD: provider == .fal
                ? max(assembly.outputSeconds, Double(shot.activeRenderVersion?.totalSeconds ?? 0)) * 0.01
                : 0,
            estimatedCostCredits: provider == .decart
                ? max(assembly.outputSeconds, Double(shot.activeRenderVersion?.totalSeconds ?? 0))
                : 0,
            pricingUnit: provider == .fal ? "usd_per_source_second" : "credits_per_source_second",
            pricingRate: provider == .fal ? 0.01 : 1,
            styleId: style?.styleId ?? "",
            styleLabel: style?.label ?? "",
            styleCollection: style?.collection ?? "",
            styleHueHex: style?.hueHex ?? "",
            styleSummary: style?.summary ?? "",
            styleCatalogVersion: style?.catalogVersion ?? "",
            styleImageReference: style?.imageReference,
            generatedAt: now,
            updatedAt: now
        )
        activeShotRestyleId = versionId
        defer { activeShotRestyleId = "" }
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        logGeneration(
            kind: "video.start",
            message: "Shot Look preparing shot_id=\(shotId) look_id=\(versionId) provider=\(provider.rawValue) model=\(provider.modelId) style_id=\(style?.styleId.nilIfEmpty ?? "-")"
        )
        let startedAt = Date()

        do {
            let prepared = try await prepareShotLookSource(
                shot: shot,
                assembly: assembly,
                artifactId: versionId,
                project: project
            )
            guard currentProject?.projectId == project.projectId else { return }
            artifact.sourceVideoPath = prepared.url.path
            artifact.sourceVideoSHA256 = prepared.sha256
            artifact.sourceDurationSeconds = prepared.durationSeconds
            artifact.estimatedCostUSD = provider == .fal ? prepared.durationSeconds * 0.01 : 0
            artifact.estimatedCostCredits = provider == .decart ? prepared.durationSeconds : 0
            artifact.status = "uploading"
            artifact.updatedAt = DateFormats.now()
            persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)

            switch provider {
            case .fal:
                try await executeNewFALShotLook(
                    &artifact,
                    shotId: shotId,
                    project: project
                )
            case .decart:
                try await executeNewDecartShotLook(
                    &artifact,
                    shotId: shotId,
                    project: project
                )
            }
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            persistShotLookVersion(artifact, shotId: shotId, activate: true, for: project)
            aestheticStatus = "Look \(versionNumber) ready"
            logGeneration(
                kind: "video.completed",
                message: "Shot Look ready shot_id=\(shotId) look_id=\(versionId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(artifact.requestId)"
            )
            recordSpend(SpendLedgerEntry(
                kind: "shot_look",
                provider: provider.rawValue,
                model: provider.modelId,
                requestId: artifact.requestId,
                traceId: artifact.traceId,
                contextLabel: spendContextLabel(shotId: shotId),
                shotId: shotId,
                unit: "seconds",
                unitCount: artifact.sourceDurationSeconds,
                estimatedUSD: artifact.estimatedCostUSD > 0 ? artifact.estimatedCostUSD : nil,
                estimatedCredits: artifact.estimatedCostCredits > 0 ? artifact.estimatedCostCredits : nil,
                pricingNote: artifact.pricingUnit
            ))
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            if Task.isCancelled || isCancellationLikeError(error) {
                if let persisted = shotTimeline.shots.first(where: { $0.shotId == shotId })?
                    .lookVersions.first(where: { $0.versionId == versionId }), ["canceled", "paused"].contains(persisted.status) {
                    return
                }
                artifact.status = "canceled"
                artifact.errorMessage = "Canceled by operator"
            } else {
                let failurePhase = artifact.status
                artifact.status = "failed"
                artifact.errorMessage = shotRenderFailureSummary(error, phase: failurePhase, limit: 300)
                logGeneration(
                    kind: "video.error",
                    message: "Shot Look failed shot_id=\(shotId) look_id=\(versionId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(artifact.requestId.nilIfEmpty ?? "-"): \(shortSummaryText(error.localizedDescription, limit: 180))"
                )
                recordSpend(SpendLedgerEntry(
                    kind: "shot_look",
                    provider: provider.rawValue,
                    model: provider.modelId,
                    requestId: artifact.requestId,
                    traceId: artifact.traceId,
                    contextLabel: spendContextLabel(shotId: shotId),
                    shotId: shotId,
                    status: "failed_unknown_charge"
                ))
            }
            artifact.updatedAt = DateFormats.now()
            persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
            aestheticStatus = artifact.status == "canceled" ? "Look canceled" : "Look failed"
        }
    }

    private func executeNewFALShotLook(
        _ artifact: inout ShotRestyleArtifact,
        shotId: String,
        project: ProjectRecord
    ) async throws {
        let request = falRestyleRequest(for: artifact, project: project)
        let client = FALVideoClient(credentialStore: videoCredentialStore)
        let uploaded = try await client.uploadRestyleSource(request)
        artifact.inputRemoteURL = uploaded.url.absoluteString
        artifact.traceId = uploaded.traceId
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)

        let submission = try await client.submitRestyle(request, sourceRemoteURL: uploaded.url)
        artifact.requestId = submission.requestId
        artifact.traceId = submission.traceId.isEmpty ? artifact.traceId : submission.traceId
        artifact.status = "queued"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        logGeneration(
            kind: "video.submitted",
            message: "Shot Look submitted provider=fal shot_id=\(shotId) look_id=\(artifact.versionId) request_id=\(submission.requestId)"
        )

        artifact.status = "generating"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        let remote = try await client.waitForRestyle(request, requestId: submission.requestId)
        artifact.outputRemoteURL = remote.videoURL.absoluteString
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        try await finishShotLookDownload(&artifact, request: request, remoteURL: remote.videoURL, client: client)
    }

    private func executeNewDecartShotLook(
        _ artifact: inout ShotRestyleArtifact,
        shotId: String,
        project: ProjectRecord
    ) async throws {
        let request = try decartRestyleRequest(for: artifact, project: project)
        let client = DecartVideoClient(credentialStore: videoCredentialStore)
        let submission = try await client.submitRestyle(request)
        artifact.requestId = submission.jobId
        artifact.traceId = submission.traceId
        artifact.status = "queued"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        logGeneration(
            kind: "video.submitted",
            message: "Shot Look submitted provider=decart shot_id=\(shotId) look_id=\(artifact.versionId) request_id=\(submission.jobId)"
        )

        artifact.status = "generating"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        let remote = try await client.waitForRestyle(request, jobId: submission.jobId)
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        let contentTraceId = try await client.downloadRestyleOutput(request, jobId: submission.jobId)
        artifact.traceId = contentTraceId.isEmpty ? artifact.traceId : contentTraceId
        try await finishShotLookLocal(&artifact, outputURL: request.outputURL)
    }

    /// Cut planning must use visual-track durations, not provider estimates or
    /// a container duration that may be extended by audio. This matches the
    /// player and makes the local pre-spend export the exact visible Original.
    ///
    /// Direction is passed EXPLICITLY rather than read off the shot: a Look
    /// flattened from the forward edit must keep resolving forward even while
    /// the Original is being watched in reverse, or its picture and its audio
    /// would disagree about which way round the shot runs.
    ///
    /// The whole-output loop is passed explicitly for the same reason, but the
    /// split runs the other way: Look SOURCE prep excludes it (restyle the
    /// base once — cost, the 600s cap, and `sourceVisualFingerprint` all stay
    /// base), while the flatten includes it (bake what the operator watches).
    private func resolvedShotLookAssembly(
        shot: ProjectShot,
        planSegments: [ShotRenderPlanSegment],
        reversed: Bool,
        includeOutputLoop: Bool
    ) async -> ShotCutAssembly {
        var directed = shot
        directed.cutList.isReversed = reversed
        let estimated = shotVisibleCutAssembly(
            shot: directed,
            planSegments: planSegments,
            clipDurationsByPath: [:],
            includeOutputLoop: includeOutputLoop
        )
        let paths = Set(
            estimated.planClips.map(\.clipPath).filter { !$0.isEmpty }
                + estimated.playbackItems.map { $0.url.path }
        )
        var exactDurations: [String: Double] = [:]
        for path in paths {
            if Task.isCancelled { return estimated }
            if let duration = try? await VideoChainMedia.videoDurationSeconds(
                videoURL: URL(fileURLWithPath: path)
            ) {
                exactDurations[path] = duration
            }
        }
        return shotVisibleCutAssembly(
            shot: directed,
            planSegments: planSegments,
            clipDurationsByPath: exactDurations,
            includeOutputLoop: includeOutputLoop
        )
    }

    private func prepareShotLookSource(
        shot: ProjectShot,
        assembly: ShotCutAssembly,
        artifactId: String,
        project: ProjectRecord
    ) async throws -> (url: URL, durationSeconds: Double, sha256: String) {
        var specs = assembly.playableSpecs.map { spec in
            var visualOnly = spec
            visualOnly.includeAudio = false
            return visualOnly
        }
        if specs.isEmpty,
           let path = shot.activeRenderVersion?.videoPath.trimmed.nilIfEmpty
                ?? shot.renderArtifact?.videoPath.trimmed.nilIfEmpty,
           FileManager.default.fileExists(atPath: path) {
            specs = [VideoChainMedia.StitchClipSpec(url: URL(fileURLWithPath: path), includeAudio: false)]
        }
        guard !specs.isEmpty else {
            throw ScreenGraphError.capture("The current Original edit has no playable picture.")
        }
        let profile = VideoOutputProfile(
            aspectRatio: .landscape16x9,
            width: 1280,
            height: 720,
            fps: 24,
            fitPolicy: .fitWithBlurFill
        )
        let built = try await VideoChainMedia.buildStitchComposition(specs: specs, profile: profile)
        guard built.durationSeconds > 0 else {
            throw ScreenGraphError.capture("The current Original edit has no visual duration.")
        }
        guard built.durationSeconds <= 600.001 else {
            throw ScreenGraphError.capture("Lucy Look sources are currently limited to 10 minutes.")
        }
        let outputURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(artifactId)_source.mp4")
        try? FileManager.default.removeItem(at: outputURL)
        guard let session = AVAssetExportSession(
            asset: built.composition,
            presetName: AVAssetExportPresetHighestQuality
        ) else {
            throw ScreenGraphError.capture("The Look source exporter could not start.")
        }
        session.videoComposition = built.videoComposition
        session.timeRange = CMTimeRange(
            start: .zero,
            duration: CMTime(seconds: built.durationSeconds, preferredTimescale: 600)
        )
        session.shouldOptimizeForNetworkUse = true
        try await MediaExportGuard.export(session, to: outputURL, as: .mp4, operation: "Look source export")
        let measured = try await VideoChainMedia.videoDurationSeconds(videoURL: outputURL)
        guard measured > 0 else { throw ScreenGraphError.capture("The exported Look source is unreadable.") }
        let attributes = try FileManager.default.attributesOfItem(atPath: outputURL.path)
        let byteCount = (attributes[.size] as? NSNumber)?.int64Value ?? 0
        guard byteCount > 0 else { throw ScreenGraphError.capture("The exported Look source is empty.") }
        guard byteCount <= 200 * 1_024 * 1_024 else {
            throw ScreenGraphError.capture("The exported Look source exceeds Lucy's 200 MB input limit.")
        }
        let data = try Data(contentsOf: outputURL, options: [.mappedIfSafe])
        return (outputURL, measured, sha256Hex(data))
    }

    private func finishShotLookDownload(
        _ artifact: inout ShotRestyleArtifact,
        request: FALRestyleRequest,
        remoteURL: URL,
        client: FALVideoClient
    ) async throws {
        try await client.downloadRestyleOutput(request, remoteURL: remoteURL)
        try await finishShotLookLocal(&artifact, outputURL: request.outputURL)
    }

    private func finishShotLookLocal(
        _ artifact: inout ShotRestyleArtifact,
        outputURL: URL
    ) async throws {
        let duration = try await VideoChainMedia.videoDurationSeconds(videoURL: outputURL)
        guard duration > 0 else { throw ScreenGraphError.capture("The downloaded Lucy Look has no video track.") }
        artifact.status = "ready"
        artifact.videoPath = outputURL.path
        artifact.outputDurationSeconds = duration
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
    }

    private func resumeShotLook(_ savedArtifact: ShotRestyleArtifact, shotId: String) async {
        guard let project = currentProject, !savedArtifact.requestId.isEmpty else { return }
        var artifact = savedArtifact
        activeShotRestyleId = artifact.versionId
        defer { activeShotRestyleId = "" }
        do {
            switch artifact.restyleProvider {
            case .fal:
                try await resumeFALShotLook(&artifact, shotId: shotId, project: project)
            case .decart:
                try await resumeDecartShotLook(&artifact, shotId: shotId, project: project)
            }
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            persistShotLookVersion(artifact, shotId: shotId, activate: true, for: project)
            aestheticStatus = "Look \(artifact.versionNumber) ready"
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            if Task.isCancelled || isCancellationLikeError(error) { return }
            artifact.status = "failed"
            artifact.errorMessage = shotRenderFailureSummary(error, phase: "resume_\(savedArtifact.status)", limit: 300)
            artifact.updatedAt = DateFormats.now()
            persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
            aestheticStatus = "Look recovery needs attention"
        }
    }

    private func resumeFALShotLook(
        _ artifact: inout ShotRestyleArtifact,
        shotId: String,
        project: ProjectRecord
    ) async throws {
        let request = falRestyleRequest(for: artifact, project: project)
        let client = FALVideoClient(credentialStore: videoCredentialStore)
        let remoteURL: URL
        if let savedRemote = URL(string: artifact.outputRemoteURL), !artifact.outputRemoteURL.isEmpty {
            remoteURL = savedRemote
        } else {
            artifact.status = "generating"
            artifact.errorMessage = ""
            artifact.updatedAt = DateFormats.now()
            persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
            let remote = try await client.waitForRestyle(request, requestId: artifact.requestId)
            remoteURL = remote.videoURL
            artifact.outputRemoteURL = remote.videoURL.absoluteString
            artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        }
        artifact.status = "downloading"
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        try await finishShotLookDownload(&artifact, request: request, remoteURL: remoteURL, client: client)
    }

    private func resumeDecartShotLook(
        _ artifact: inout ShotRestyleArtifact,
        shotId: String,
        project: ProjectRecord
    ) async throws {
        let request = try decartRestyleRequest(for: artifact, project: project)
        let client = DecartVideoClient(credentialStore: videoCredentialStore)
        artifact.status = "generating"
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        let remote = try await client.waitForRestyle(request, jobId: artifact.requestId)
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistShotLookVersion(artifact, shotId: shotId, activate: false, for: project)
        let contentTraceId = try await client.downloadRestyleOutput(request, jobId: artifact.requestId)
        artifact.traceId = contentTraceId.isEmpty ? artifact.traceId : contentTraceId
        try await finishShotLookLocal(&artifact, outputURL: request.outputURL)
    }

    private func falRestyleRequest(for artifact: ShotRestyleArtifact, project: ProjectRecord) -> FALRestyleRequest {
        FALRestyleRequest(
            projectId: project.projectId,
            shotId: artifact.sourceShotId,
            artifactId: artifact.versionId,
            prompt: artifact.prompt,
            enhancePrompt: artifact.enhancePrompt,
            seed: artifact.seed,
            sourceURL: URL(fileURLWithPath: artifact.sourceVideoPath),
            outputURL: shotLookOutputURL(artifactId: artifact.versionId, project: project)
        )
    }

    private func decartRestyleRequest(
        for artifact: ShotRestyleArtifact,
        project: ProjectRecord
    ) throws -> DecartRestyleRequest {
        guard let styleReference = artifact.styleImageReference?.normalized(),
              !styleReference.url.isEmpty,
              !styleReference.sha256.isEmpty else {
            throw ScreenGraphError.capture("This Decart Look is missing its verified style image reference and cannot be submitted or resumed.")
        }
        return DecartRestyleRequest(
            projectId: project.projectId,
            shotId: artifact.sourceShotId,
            artifactId: artifact.versionId,
            seed: artifact.seed,
            sourceURL: URL(fileURLWithPath: artifact.sourceVideoPath),
            sourceSHA256: artifact.sourceVideoSHA256,
            styleReference: styleReference,
            outputURL: artifact.isClipLook
                ? clipLookOutputURL(artifactId: artifact.versionId, project: project)
                : shotLookOutputURL(artifactId: artifact.versionId, project: project),
            workflowName: artifact.isClipLook ? "clip_look_restyle" : "shot_look_restyle",
            artifactType: artifact.isClipLook ? "clip_restyle" : "shot_restyle",
            traceGroupId: artifact.isClipLook
                ? "clip_look_\(artifact.sourceClipMediaId)"
                : "shot_look_\(artifact.sourceShotId)"
        )
    }

    private func shotLookOutputURL(artifactId: String, project: ProjectRecord) -> URL {
        contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(safeIdentifier(artifactId)).mp4")
    }

    private func reconcileInterruptedShotRestyles(for project: ProjectRecord) {
        let preflight = restyleResumePreflight(document: shotTimeline, now: DateFormats.now())
        if preflight.changed { persistShotTimeline(preflight.document, for: project) }
        func credentialed(_ pending: (shotId: String, artifact: ShotRestyleArtifact)) -> Bool {
            videoCredentialStore.credentialStatus(
                for: pending.artifact.restyleProvider.credentialProvider
            ).isConfigured
        }
        // Clip Looks resume through the lane: known in-flight paid jobs fill
        // free slots immediately, the remainder waits in the pump (crash
        // recovery, not a user-facing queue — starts still refuse at cap).
        let clipLooks = preflight.clipLooks.filter(credentialed)
        if !clipLooks.isEmpty {
            let waiting = clipLooks
                .filter { pending in
                    clipLookTasks[pending.artifact.versionId] == nil
                        && !pendingClipLookResumes.contains { $0.artifact.versionId == pending.artifact.versionId }
                }
                .map { (home: ClipLookHome.shot(shotId: $0.shotId), artifact: $0.artifact) }
            pendingClipLookResumes.append(contentsOf: waiting)
            pumpClipLookResumes()
        }
        let shotLooks = preflight.shotLooks.filter(credentialed)
        guard !shotLooks.isEmpty, shotRestyleTask == nil else { return }
        shotRestyleTask = Task { [weak self] in
            guard let self else { return }
            for pending in shotLooks {
                guard self.currentProject?.projectId == project.projectId else { break }
                await self.resumeShotLook(pending.artifact, shotId: pending.shotId)
            }
            self.shotRestyleTask = nil
        }
    }

    @discardableResult
    func continueActiveShotLookAsNewShot(shotId: String) async -> String? {
        guard activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty else {
            aestheticStatus = "Wait for the current video operation to finish"
            return nil
        }
        guard let project = currentProject,
              let sourceIndex = shotTimeline.shots.firstIndex(where: { $0.shotId == shotId }),
              let look = shotTimeline.shots[sourceIndex].activeLookVersion,
              FileManager.default.fileExists(atPath: look.videoPath) else { return nil }
        let sourceShot = shotTimeline.shots[sourceIndex]
        let proofURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(safeIdentifier(look.versionId))_mix.mp4")
        do {
            try? FileManager.default.removeItem(at: proofURL)
            let originalAudioAsset: AVAsset?
            // Hoisted out of the branch: the same assembly whose specs laid the
            // original audio down must reach `buildLook`, or the per-segment
            // source gain windows land at the wrong seconds.
            var lookAssembly: ShotCutAssembly?
            if let promptPlan = shotRenderPromptPlan(shotId: shotId) {
                // Looped so the flattened new shot carries what the operator
                // watches — matching `flattenShotOutput`, which resolves its
                // assembly with `includeOutputLoop: true`.
                let assembly = loopedShotCutAssembly(
                    shotCutAssembly(
                        shot: sourceShot,
                        planSegments: promptPlan.segments,
                        clipDurationsByPath: [:]
                    ),
                    count: sourceShot.cutList.normalized().outputLoopCount
                )
                if assembly.hasPlayableClips {
                    let original = try await VideoChainMedia.buildStitchComposition(
                        specs: assembly.playableSpecs,
                        profile: VideoOutputProfile.standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
                    )
                    originalAudioAsset = original.composition
                    lookAssembly = assembly
                } else if let path = sourceShot.activeRenderVersion?.videoPath.trimmed.nilIfEmpty {
                    originalAudioAsset = AVURLAsset(url: URL(fileURLWithPath: path))
                } else {
                    originalAudioAsset = nil
                }
            } else {
                originalAudioAsset = nil
            }
            guard let mixed = await ShotAudioComposition.buildLook(
                videoURL: URL(fileURLWithPath: look.videoPath),
                originalAudioAsset: originalAudioAsset,
                sourceDurationSeconds: look.sourceDurationSeconds,
                shot: sourceShot,
                assembly: lookAssembly,
                loopCount: sourceShot.cutList.normalized().outputLoopCount
            ), let session = AVAssetExportSession(
                asset: mixed.composition,
                presetName: AVAssetExportPresetHighestQuality
            ) else {
                throw ScreenGraphError.capture("The active Look audio mix could not be prepared.")
            }
            session.audioMix = mixed.audioMix
            session.timeRange = CMTimeRange(start: .zero, duration: mixed.composition.duration)
            try await MediaExportGuard.export(session, to: proofURL, as: .mp4, operation: "Look flatten")
            let mediaId = "genmedia_\(shortHash("\(project.projectId):\(look.versionId):shot_look", length: 20))"
            guard let media = await archiveGeneratedMedia(
                fileURL: proofURL,
                project: project,
                mediaId: mediaId,
                derivativeKind: MediaItemRecord.shotLookDerivativeKind,
                sourceMediaId: shotId,
                filename: generatedMediaArchiveFilename(
                    base: "\(sourceShot.name.trimmed.nilIfEmpty ?? "Shot") Look \(look.versionNumber)",
                    path: proofURL.path,
                    fallbackExtension: "mp4"
                ),
                tags: ["generated", "shot", "look", "lucy-restyle"],
                notes: "Lucy Shot Look \(look.versionNumber), flattened with the source Shot's current audio mix.",
                rejectedByDefault: false
            ) else { return nil }
            guard currentProject?.projectId == project.projectId else { return nil }
            let now = DateFormats.now()
            let newShotId = "shot_\(shortHash("\(project.projectId):\(shotId):\(look.versionId):\(now)", length: 12))"
            let sourceName = sourceShot.name.trimmed.nilIfEmpty ?? "Shot \(sourceIndex + 1)"
            let newShot = ProjectShot(
                shotId: newShotId,
                name: "\(sourceName) · Look \(look.versionNumber)",
                createdAt: now,
                updatedAt: now
            ).insertingClipEntry(clipMediaId: media.mediaId, at: 0, now: now)
            var document = shotTimeline
            document.shots.insert(newShot, at: min(sourceIndex + 1, document.shots.count))
            document.updatedAt = now
            persistShotTimeline(document, for: project)
            aestheticStatus = "Look \(look.versionNumber) kept as a new CUT directly below \(sourceName) — "
                + "the Look also stays on the source"
            return newShotId
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not continue this Look as a new Shot"
            return nil
        }
    }

    // MARK: - Clip Looks (Lucy restyle of one placed footage range)

    private func persistClipLookVersion(
        _ version: ShotRestyleArtifact,
        home: ClipLookHome,
        for project: ProjectRecord
    ) {
        switch home {
        case .shot(let shotId):
            let now = DateFormats.now()
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: now) {
                    $0.upsertingClipLookVersion(version, now: now)
                },
                for: project
            )
        case .media:
            persistMediaLookVersion(version, for: project)
        }
    }

    /// The PERSISTED row for a look, wherever it lives — status rechecks must
    /// read this, never a captured snapshot.
    private func clipLookArtifact(home: ClipLookHome, versionId: String) -> ShotRestyleArtifact? {
        switch home {
        case .shot(let shotId):
            return shotTimeline.shots.first(where: { $0.shotId == shotId })?
                .clipLookVersions.first(where: { $0.versionId == versionId })
        case .media:
            return mediaGenerations.lookVersions.first(where: { $0.versionId == versionId })
        }
    }

    /// Status strings name the look now that several can interleave.
    private func clipLookDisplayName(_ artifact: ShotRestyleArtifact) -> String {
        artifact.styleLabel.trimmed.nilIfEmpty ?? "v\(artifact.versionNumber)"
    }

    /// The only door into the Clip Look lane: registers the operation under
    /// its versionId, mirrors membership into `activeClipLookIds`, and frees
    /// the slot (pumping any crash-recovery resumes) when it ends.
    private func spawnClipLookLaneTask(versionId: String, operation: @escaping () async -> Void) {
        let token = UUID()
        activeClipLookIds.insert(versionId)
        let task = Task { [weak self] in
            await operation()
            // Only the current owner may free the slot: after a teardown +
            // respawn under the same versionId, the stale task's token no
            // longer matches and its cleanup must be a no-op.
            guard let self, self.clipLookTasks[versionId]?.token == token else { return }
            self.clipLookTasks[versionId] = nil
            self.activeClipLookIds.remove(versionId)
            self.pumpClipLookResumes()
        }
        clipLookTasks[versionId] = (token, task)
    }

    /// Spawns waiting crash-recovery resumes while lane capacity remains —
    /// called after a relaunch reconcile and whenever a lane slot frees.
    private func pumpClipLookResumes() {
        while !clipLookLaneIsFull, !pendingClipLookResumes.isEmpty {
            let pending = pendingClipLookResumes.removeFirst()
            guard clipLookTasks[pending.artifact.versionId] == nil else { continue }
            // The queued snapshot was captured at reconcile time; the operator
            // may have canceled, retried, or watched the look finish while it
            // waited for a slot. Resume only a look whose PERSISTED status is
            // still in flight, and resume the fresh row — a terminal status
            // must never be rewritten by a stale snapshot.
            guard let current = clipLookArtifact(home: pending.home, versionId: pending.artifact.versionId),
                ["queued", "generating", "downloading"].contains(current.status) else { continue }
            spawnClipLookLaneTask(versionId: current.versionId) { [weak self] in
                await self?.resumeClipLook(current, home: pending.home)
            }
        }
    }

    /// Restyles ONE placed footage entry's committed range via Lucy — no shot
    /// render required. Tray-only landing: the finished Look is archived as a
    /// clip_look media item nested under its source clip; the shot itself is
    /// never changed. Runs in the Clip Look lane, OUTSIDE the video-operation
    /// lock: up to `clipLookLaneCap` looks run concurrently (same clip
    /// included), while shot renders / joins / Shot Looks keep their own
    /// single-flight lock untouched.
    func startClipLookRestyle(
        shotId: String,
        entryId: String,
        prompt: String,
        enhancePrompt: Bool,
        seed: Int,
        style: ShotLookStyleSelection? = nil,
        provider: ShotLookProvider = .fal
    ) {
        guard !clipLookLaneIsFull else {
            aestheticStatus = "\(clipLookLaneCap) Clip Looks are already running — wait for one to finish"
            return
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return
        }
        guard videoCredentialStore.credentialStatus(for: provider.credentialProvider).isConfigured else {
            aestheticStatus = "Add a \(provider == .fal ? "FAL" : "Decart") API key in App Settings to create a Clip Look"
            return
        }
        let resolvedStyle = (style?.isUsable == true) ? style : nil
        let finalPrompt: String
        switch provider {
        case .fal:
            finalPrompt = String(
                shotLookComposedPrompt(styleSummary: resolvedStyle?.summary ?? "", userText: prompt).prefix(1_500)
            )
            guard !finalPrompt.isEmpty else {
                aestheticStatus = "Pick a style or describe the Clip Look before rendering"
                return
            }
        case .decart:
            guard resolvedStyle?.hasUsableImageReference == true else {
                aestheticStatus = "Choose a verified catalog style for Decart image input"
                return
            }
            finalPrompt = ""
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let entry = shot.entries.first(where: { $0.entryId == entryId }), entry.isClip,
              let media = items.first(where: { $0.mediaId == entry.clipMediaId }), media.kind == .video,
              !media.path.trimmed.isEmpty else {
            aestheticStatus = "Clip Look source is unavailable"
            return
        }
        let assetDuration = max(media.durationSeconds ?? 0, 0)
        let range = VideoTrimRange.clamped(
            start: entry.clipStartSeconds ?? 0,
            end: entry.clipEndSeconds ?? assetDuration,
            videoDurationSeconds: assetDuration
        )
        guard range.isSaveable else {
            aestheticStatus = "This clip's range has no playable picture"
            return
        }
        // Minted here, not inside the perform, so the lane registry can key
        // the task before its first await.
        let versionId = "cliplook_\(shortHash("\(currentProject?.projectId ?? ""):\(media.mediaId):\(DateFormats.now()):\(UUID().uuidString)", length: 18))"
        spawnClipLookLaneTask(versionId: versionId) { [weak self] in
            await self?.performClipLookRestyle(
                versionId: versionId,
                home: .shot(shotId: shotId),
                media: media,
                range: range,
                prompt: finalPrompt,
                enhancePrompt: enhancePrompt,
                seed: max(seed, 0),
                style: resolvedStyle,
                provider: provider
            )
        }
    }

    /// Restyles a raw tray video's WHOLE asset via the same Lucy path — no
    /// shot, no entry: the media viewer's Restyle. Same lane, same cap, same
    /// guards; the artifact lives in the media-generations document
    /// (`ClipLookHome.media`) and the finished Look nests under its source in
    /// the tray exactly like a placed-clip Look.
    func startMediaLookRestyle(
        mediaId: String,
        prompt: String,
        enhancePrompt: Bool,
        seed: Int,
        style: ShotLookStyleSelection? = nil,
        provider: ShotLookProvider = .fal
    ) {
        guard !clipLookLaneIsFull else {
            aestheticStatus = "\(clipLookLaneCap) Clip Looks are already running — wait for one to finish"
            return
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return
        }
        guard videoCredentialStore.credentialStatus(for: provider.credentialProvider).isConfigured else {
            aestheticStatus = "Add a \(provider == .fal ? "FAL" : "Decart") API key in App Settings to restyle this video"
            return
        }
        let resolvedStyle = (style?.isUsable == true) ? style : nil
        let finalPrompt: String
        switch provider {
        case .fal:
            finalPrompt = String(
                shotLookComposedPrompt(styleSummary: resolvedStyle?.summary ?? "", userText: prompt).prefix(1_500)
            )
            guard !finalPrompt.isEmpty else {
                aestheticStatus = "Pick a style or describe the restyle before rendering"
                return
            }
        case .decart:
            guard resolvedStyle?.hasUsableImageReference == true else {
                aestheticStatus = "Choose a verified catalog style for Decart image input"
                return
            }
            finalPrompt = ""
        }
        guard let media = items.first(where: { $0.mediaId == mediaId }), media.kind == .video,
              !media.path.trimmed.isEmpty,
              FileManager.default.fileExists(atPath: media.path) else {
            aestheticStatus = "This video is unavailable to restyle"
            return
        }
        let assetDuration = max(media.durationSeconds ?? 0, 0)
        let range = VideoTrimRange.clamped(
            start: 0,
            end: assetDuration,
            videoDurationSeconds: assetDuration
        )
        guard range.isSaveable else {
            aestheticStatus = "This video has no playable picture to restyle"
            return
        }
        let versionId = "medialook_\(shortHash("\(currentProject?.projectId ?? ""):\(media.mediaId):\(DateFormats.now()):\(UUID().uuidString)", length: 18))"
        spawnClipLookLaneTask(versionId: versionId) { [weak self] in
            await self?.performClipLookRestyle(
                versionId: versionId,
                home: .media,
                media: media,
                range: range,
                prompt: finalPrompt,
                enhancePrompt: enhancePrompt,
                seed: max(seed, 0),
                style: resolvedStyle,
                provider: provider
            )
        }
    }

    /// Reconcile hook: a relaunch-recovered media-home look re-enters the
    /// lane through the same crash-recovery pump as shot-home looks.
    private func resumeMediaLook(_ artifact: ShotRestyleArtifact, for project: ProjectRecord) {
        guard videoCredentialStore.credentialStatus(
            for: artifact.restyleProvider.credentialProvider
        ).isConfigured else { return }
        guard clipLookTasks[artifact.versionId] == nil,
              !pendingClipLookResumes.contains(where: { $0.artifact.versionId == artifact.versionId }) else {
            return
        }
        pendingClipLookResumes.append((home: .media, artifact: artifact))
        pumpClipLookResumes()
    }

    // MARK: Start Video (image → motion clip)

    /// The only door into the media-motion lane — the clip-look spawn shape:
    /// registry keyed by jobId, token-guarded cleanup, membership mirrored
    /// into the published set.
    private func spawnMediaMotionLaneTask(jobId: String, operation: @escaping () async -> Void) {
        let token = UUID()
        activeMediaMotionJobIds.insert(jobId)
        let task = Task { [weak self] in
            await operation()
            guard let self, self.mediaMotionTasks[jobId]?.token == token else { return }
            self.mediaMotionTasks[jobId] = nil
            self.activeMediaMotionJobIds.remove(jobId)
        }
        mediaMotionTasks[jobId] = (token, task)
    }

    /// One canonical admission law for the viewer's paid Start Video action.
    /// The composer reads this exact reason and the submit function rechecks
    /// it, so a cached thumbnail can never masquerade as a provider-ready
    /// original and a click-time race cannot dismiss as success.
    func mediaMotionStartBlockReason(mediaId: String, model: ShotRenderModel) -> String? {
        guard currentProject != nil else { return "Create or select a project first" }
        if activeMediaMotionMediaIds.contains(mediaId) {
            return "This image is already rendering a video"
        }
        if mediaMotionLaneIsFull {
            return "\(mediaMotionLaneCap) motion renders are already running — wait for one to finish"
        }
        guard !isGenerationPaused else { return "Generation is paused — resume to continue" }
        guard mediaMotionSelectableModels().contains(model) else {
            return "\(model.label) needs an authored narration driver — pick another model"
        }
        guard videoCredentialStore.credentialStatus(for: .fal).isConfigured else {
            return "Add a FAL API key in App Settings to start a video"
        }
        guard let item = items.first(where: { $0.mediaId == mediaId }), item.kind == .image else {
            return "This image is no longer in Media"
        }
        guard !item.path.trimmed.isEmpty, FileManager.default.fileExists(atPath: item.path) else {
            return "The original image is unavailable. Restore or re-import it to start a video; the cached thumbnail is preview-only."
        }
        return nil
    }

    /// Renders a video FROM one Media image — the viewer's "Start Video".
    /// Standalone open-ended provider call (`renderNarrationDrivenShot`'s
    /// request shape minus the shot): no `renderShot` lens requirement, no
    /// exclusive video-operation lock. The result lands as a top-level
    /// `media_motion` tray asset.
    @discardableResult
    func startMediaMotionRender(
        mediaId: String,
        model: ShotRenderModel,
        durationSeconds: Int,
        motionPrompt: String,
        generateAudio: Bool
    ) -> Bool {
        if let blockReason = mediaMotionStartBlockReason(mediaId: mediaId, model: model) {
            aestheticStatus = blockReason
            return false
        }
        guard let project = currentProject,
              let item = items.first(where: { $0.mediaId == mediaId }) else {
            aestheticStatus = "This image is no longer in Media"
            return false
        }
        let recipe = ShotRenderStack.recipe(
            model: model,
            durationSeconds: durationSeconds,
            generateAudio: generateAudio
        )
        let now = DateFormats.now()
        let jobId = "mediamotion_\(shortHash("\(project.projectId):\(item.mediaId):\(now):\(UUID().uuidString)", length: 18))"
        spawnMediaMotionLaneTask(jobId: jobId) { [weak self] in
            await self?.performMediaMotionRender(
                jobId: jobId,
                media: item,
                recipe: recipe,
                motionPrompt: motionPrompt
            )
        }
        return true
    }

    func cancelMediaMotionRender(jobId: String) {
        guard let project = currentProject,
              let job = mediaGenerations.motionJobs.first(where: { $0.jobId == jobId }) else { return }
        guard mediaMotionTasks[jobId] != nil || job.isActive else { return }
        mediaMotionTasks[jobId]?.task.cancel()
        var canceled = job
        canceled.status = "canceled"
        canceled.errorMessage = job.requestId.isEmpty
            ? "Canceled by operator"
            : "Stopped waiting locally. The provider render may still complete and bill at FAL."
        canceled.updatedAt = DateFormats.now()
        persistMediaMotionJob(canceled, for: project)
        aestheticStatus = "Start Video canceled"
    }

    private func performMediaMotionRender(
        jobId: String,
        media: MediaItemRecord,
        recipe: ShotRenderStack,
        motionPrompt: String
    ) async {
        guard let project = currentProject else { return }
        let now = DateFormats.now()
        let sourceName = ((media.filename as NSString).deletingPathExtension).nilIfEmpty ?? "Image"
        let prompt = motionPrompt.trimmed.nilIfEmpty ?? mediaMotionDefaultPrompt()
        var job = MediaMotionJob(
            jobId: jobId,
            status: "preparing",
            sourceMediaId: media.mediaId,
            model: recipe.model.rawValue,
            durationSeconds: recipe.segmentSeconds,
            prompt: prompt,
            generateAudio: recipe.generateAudio,
            pricingNote: "fal_per_video_second",
            generatedAt: now,
            updatedAt: now
        )
        persistMediaMotionJob(job, for: project)
        aestheticStatus = "Starting a video from \(sourceName) — \(recipe.model.label)"
        logGeneration(
            kind: "video.start",
            message: "Media motion preparing media_id=\(media.mediaId) job_id=\(jobId) model=\(recipe.model.rawValue) duration_s=\(recipe.segmentSeconds)"
        )
        let startedAt = Date()
        let profile = VideoOutputProfile.standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
        let workDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("media_motion_\(safeIdentifier(jobId))", isDirectory: true)

        do {
            try ensureDirectory(workDirectory)
            let proofDirectory = contextStore.aestheticProofDirectory(for: project)
            try ensureDirectory(proofDirectory)
            let normalizedFrame = try VideoChainMedia.normalizeImageFrame(
                sourceURL: URL(fileURLWithPath: media.path),
                outputURL: workDirectory.appendingPathComponent("start_frame.png"),
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            job.status = "submitting"
            job.updatedAt = DateFormats.now()
            persistMediaMotionJob(job, for: project)
            let providerOutput = workDirectory.appendingPathComponent("provider_output.mp4")
            let result = try await VideoProviderRegistry(
                credentialStore: videoCredentialStore
            ).provider(for: recipe.model.providerSelection).generateClip(from: VideoClipRequest(
                chainId: "media_motion_\(media.mediaId)",
                segmentId: jobId,
                modelSelection: recipe.openEndedModelSelection,
                prompt: prompt,
                negativePrompt: "",
                durationSeconds: recipe.segmentSeconds,
                outputProfile: profile,
                startFrameURL: normalizedFrame,
                targetEndFrameURL: nil,
                outputURL: providerOutput,
                generateAudio: recipe.generateAudio,
                projectId: project.projectId,
                runId: jobId,
                traceGroupId: jobId,
                workflowName: "media_motion_render",
                artifactType: "media_motion",
                onProviderSubmitted: { [weak self] requestId, traceId in
                    guard let self, self.currentProject?.projectId == project.projectId,
                          var live = self.mediaGenerations.motionJobs.first(where: { $0.jobId == jobId })
                    else { return }
                    // The dedupe anchor: persisted the moment the provider
                    // accepts, so a crash after this point can name the job.
                    live.requestId = requestId
                    live.traceId = traceId.isEmpty ? live.traceId : traceId
                    live.status = "generating"
                    live.updatedAt = DateFormats.now()
                    self.persistMediaMotionJob(live, for: project)
                }
            ))
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            let requestId = result.providerJobId.trimmed.nilIfEmpty
                ?? result.providerVideoId.trimmed
            job = mediaGenerations.motionJobs.first(where: { $0.jobId == jobId }) ?? job
            if !requestId.isEmpty { job.requestId = requestId }
            job.traceId = result.traceId.isEmpty ? job.traceId : result.traceId
            job.status = "downloading"
            job.updatedAt = DateFormats.now()
            persistMediaMotionJob(job, for: project)
            recordSpend(SpendLedgerEntry(
                kind: "media_motion",
                provider: recipe.model.providerSelection.rawValue,
                model: recipe.openEndedModelSelection.providerModelId,
                requestId: job.requestId,
                traceId: job.traceId,
                contextLabel: "\(sourceName) motion",
                unit: "seconds",
                unitCount: Double(recipe.segmentSeconds),
                estimatedUSD: ShotRenderCostEstimate.segmentUSD(
                    stack: recipe,
                    pricing: falPricing
                ),
                pricingNote: job.pricingNote
            ))
            let durableURL = proofDirectory.appendingPathComponent("\(safeIdentifier(jobId)).mp4")
            try? FileManager.default.removeItem(at: durableURL)
            try FileManager.default.copyItem(at: result.outputURL, to: durableURL)
            guard let archived = await archiveGeneratedMedia(
                fileURL: durableURL,
                project: project,
                mediaId: "genmedia_\(shortHash("\(project.projectId):media_motion:\(jobId)", length: 20))",
                derivativeKind: MediaItemRecord.mediaMotionDerivativeKind,
                sourceMediaId: media.mediaId,
                filename: generatedMediaArchiveFilename(
                    base: "\(sourceName) Motion",
                    path: durableURL.path,
                    fallbackExtension: "mp4"
                ),
                tags: ["generated", "media-motion"],
                notes: "Video started from \(media.filename) in the media viewer — \(recipe.model.label), \(recipe.segmentSeconds)s.",
                rejectedByDefault: false
            ) else {
                throw ScreenGraphError.capture("The finished video could not be archived.")
            }
            job.outputMediaId = archived.mediaId
            job.status = "ready"
            job.errorMessage = ""
            job.updatedAt = DateFormats.now()
            persistMediaMotionJob(job, for: project)
            aestheticStatus = "\(sourceName) motion ready in Footage"
            logGeneration(
                kind: "video.completed",
                message: "Media motion ready media_id=\(media.mediaId) job_id=\(jobId) output_media_id=\(archived.mediaId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(job.requestId.nilIfEmpty ?? "-")"
            )
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            job = mediaGenerations.motionJobs.first(where: { $0.jobId == jobId }) ?? job
            if Task.isCancelled || isCancellationLikeError(error) {
                if job.status == "canceled" { return }
                job.status = "canceled"
                job.errorMessage = job.requestId.isEmpty
                    ? "Canceled by operator"
                    : "Stopped waiting locally. The provider render may still complete and bill at FAL."
            } else {
                let failurePhase = job.status
                job.status = "failed"
                job.errorMessage = shotRenderFailureSummary(error, phase: failurePhase, limit: 300)
                logGeneration(
                    kind: "video.error",
                    message: "Media motion failed media_id=\(media.mediaId) job_id=\(jobId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(job.requestId.nilIfEmpty ?? "-"): \(shortSummaryText(error.localizedDescription, limit: 180))"
                )
                recordSpend(SpendLedgerEntry(
                    kind: "media_motion",
                    provider: recipe.model.providerSelection.rawValue,
                    model: recipe.openEndedModelSelection.providerModelId,
                    requestId: job.requestId,
                    traceId: job.traceId,
                    contextLabel: "\(sourceName) motion",
                    status: "failed_unknown_charge"
                ))
            }
            job.updatedAt = DateFormats.now()
            persistMediaMotionJob(job, for: project)
            aestheticStatus = job.status == "canceled"
                ? "Start Video canceled"
                : "Start Video failed"
        }
    }

    func cancelClipLookRestyle(shotId: String, versionId: String) {
        cancelClipLook(home: .shot(shotId: shotId), versionId: versionId)
    }

    /// Media-home wrapper: cancels a viewer restyle of a raw tray video.
    func cancelMediaLookRestyle(versionId: String) {
        cancelClipLook(home: .media, versionId: versionId)
    }

    private func cancelClipLook(home: ClipLookHome, versionId: String) {
        guard let project = currentProject,
              let artifact = clipLookArtifact(home: home, versionId: versionId) else {
            return
        }
        // Only a look that is actually in flight can be canceled — a terminal
        // status reached between click and handler must not be rewritten.
        guard clipLookTasks[versionId] != nil
                || ["preparing", "uploading", "queued", "generating", "downloading"].contains(artifact.status) else {
            return
        }
        // A look still waiting for a lane slot has no task to cancel — but it
        // must also leave the resume queue, or the pump would resurrect it.
        pendingClipLookResumes.removeAll { $0.artifact.versionId == versionId }
        clipLookTasks[versionId]?.task.cancel()
        var canceled = artifact
        let remoteContinues = artifact.restyleProvider == .decart && !artifact.requestId.isEmpty
        canceled.status = remoteContinues ? "paused" : "canceled"
        if remoteContinues {
            canceled.errorMessage = "Stopped waiting locally. Decart may keep processing or charging; Resume Clip Look checks this job without submitting again."
        } else if artifact.restyleProvider == .decart && artifact.status == "uploading" {
            canceled.errorMessage = "Stopped before Decart returned a job id. Remote acceptance is unknown; check Decart before retrying to avoid duplicate spend."
        } else {
            canceled.errorMessage = "Canceled by operator"
        }
        canceled.updatedAt = DateFormats.now()
        persistClipLookVersion(canceled, home: home, for: project)
        aestheticStatus = remoteContinues
            ? "Stopped waiting for Decart Clip Look \(clipLookDisplayName(artifact))"
            : "Clip Look \(clipLookDisplayName(artifact)) canceled"
        if remoteContinues, let request = try? decartRestyleRequest(for: artifact, project: project) {
            Task {
                await DecartVideoClient(credentialStore: videoCredentialStore)
                    .recordStopWaiting(request, jobId: artifact.requestId)
            }
        }
        guard artifact.restyleProvider == .fal, !artifact.requestId.isEmpty else { return }
        let request = clipLookFALRequest(for: artifact, project: project)
        Task {
            await FALVideoClient(credentialStore: videoCredentialStore)
                .cancelRestyle(requestId: artifact.requestId, context: request)
        }
    }

    func retryClipLook(shotId: String, versionId: String) {
        retryClipLook(home: .shot(shotId: shotId), versionId: versionId)
    }

    /// Media-home wrapper: recovers a viewer restyle by its provider job id.
    func retryMediaLook(versionId: String) {
        retryClipLook(home: .media, versionId: versionId)
    }

    private func retryClipLook(home: ClipLookHome, versionId: String) {
        guard clipLookTasks[versionId] == nil,
              let artifact = clipLookArtifact(home: home, versionId: versionId),
              ["failed", "paused", "queued", "generating", "downloading"].contains(artifact.status),
              !artifact.requestId.isEmpty else { return }
        guard !clipLookLaneIsFull else {
            aestheticStatus = "\(clipLookLaneCap) Clip Looks are already running — wait for one to finish"
            return
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return
        }
        guard videoCredentialStore.credentialStatus(for: artifact.restyleProvider.credentialProvider).isConfigured else {
            aestheticStatus = "Add a \(artifact.restyleProvider == .fal ? "FAL" : "Decart") API key in App Settings to recover this Clip Look"
            return
        }
        // A user-driven resume supersedes any queued crash-recovery entry for
        // the same version — otherwise the pump would spawn a second resume
        // from its stale snapshot when this one frees the slot.
        pendingClipLookResumes.removeAll { $0.artifact.versionId == versionId }
        spawnClipLookLaneTask(versionId: versionId) { [weak self] in
            await self?.resumeClipLook(artifact, home: home)
        }
    }

    private func performClipLookRestyle(
        versionId: String,
        home: ClipLookHome,
        media: MediaItemRecord,
        range: VideoTrimRange,
        prompt: String,
        enhancePrompt: Bool,
        seed: Int,
        style: ShotLookStyleSelection?,
        provider: ShotLookProvider
    ) async {
        guard let project = currentProject else {
            aestheticStatus = "Clip Look source is unavailable"
            return
        }
        // No await separates these reads from the first persist below, so
        // concurrent lane tasks allocate distinct numbers on the main actor.
        let versionNumber: Int
        switch home {
        case .shot(let shotId):
            guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }) else {
                aestheticStatus = "Clip Look source is unavailable"
                return
            }
            versionNumber = (shot.clipLookVersions.map(\.versionNumber).max() ?? 0) + 1
        case .media:
            versionNumber = (mediaGenerations.lookVersions
                .filter { $0.sourceClipMediaId == media.mediaId }
                .map(\.versionNumber).max() ?? 0) + 1
        }
        guard !Task.isCancelled, currentProject?.projectId == project.projectId else { return }
        let now = DateFormats.now()
        let spendLabel: String
        switch home {
        case .shot(let shotId):
            spendLabel = spendContextLabel(shotId: shotId)
        case .media:
            spendLabel = media.filename.trimmed.nilIfEmpty ?? "Media video"
        }
        var artifact = ShotRestyleArtifact(
            versionId: versionId,
            versionNumber: versionNumber,
            status: "preparing",
            sourceShotId: home.shotId,
            prompt: prompt,
            enhancePrompt: provider == .fal && enhancePrompt,
            seed: seed,
            provider: provider.rawValue,
            model: provider.modelId,
            inputMode: provider.inputMode,
            estimatedCostUSD: provider == .fal ? range.durationSeconds * 0.01 : 0,
            estimatedCostCredits: provider == .decart ? range.durationSeconds : 0,
            pricingUnit: provider == .fal ? "usd_per_source_second" : "credits_per_source_second",
            pricingRate: provider == .fal ? 0.01 : 1,
            styleId: style?.styleId ?? "",
            styleLabel: style?.label ?? "",
            styleCollection: style?.collection ?? "",
            styleHueHex: style?.hueHex ?? "",
            styleSummary: style?.summary ?? "",
            styleCatalogVersion: style?.catalogVersion ?? "",
            styleImageReference: style?.imageReference,
            sourceClipMediaId: media.mediaId,
            sourceClipStartSeconds: range.startSeconds,
            sourceClipEndSeconds: range.endSeconds,
            generatedAt: now,
            updatedAt: now
        )
        persistClipLookVersion(artifact, home: home, for: project)
        logGeneration(
            kind: "video.start",
            message: "Clip Look preparing shot_id=\(home.shotId.nilIfEmpty ?? "-") clip_media_id=\(media.mediaId) look_id=\(versionId) provider=\(provider.rawValue) model=\(provider.modelId) style_id=\(style?.styleId.nilIfEmpty ?? "-")"
        )
        let startedAt = Date()

        do {
            let prepared = try await prepareClipLookSource(
                media: media,
                range: range,
                artifactId: versionId,
                project: project
            )
            guard currentProject?.projectId == project.projectId else { return }
            artifact.sourceVideoPath = prepared.uploadURL.path
            artifact.sourceVideoSHA256 = prepared.sha256
            artifact.sourceDurationSeconds = prepared.durationSeconds
            artifact.estimatedCostUSD = provider == .fal ? prepared.durationSeconds * 0.01 : 0
            artifact.estimatedCostCredits = provider == .decart ? prepared.durationSeconds : 0
            artifact.status = "uploading"
            artifact.updatedAt = DateFormats.now()
            persistClipLookVersion(artifact, home: home, for: project)

            switch provider {
            case .fal:
                try await executeNewFALClipLook(
                    &artifact,
                    home: home,
                    project: project
                )
            case .decart:
                try await executeNewDecartClipLook(
                    &artifact,
                    home: home,
                    project: project
                )
            }
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            persistClipLookVersion(artifact, home: home, for: project)
            aestheticStatus = "Clip Look \(clipLookDisplayName(artifact)) ready in Footage"
            logGeneration(
                kind: "video.completed",
                message: "Clip Look ready shot_id=\(home.shotId.nilIfEmpty ?? "-") look_id=\(versionId) media_id=\(artifact.outputMediaId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(artifact.requestId)"
            )
            recordSpend(SpendLedgerEntry(
                kind: "clip_look",
                provider: provider.rawValue,
                model: provider.modelId,
                requestId: artifact.requestId,
                traceId: artifact.traceId,
                contextLabel: spendLabel,
                shotId: home.shotId,
                unit: "seconds",
                unitCount: artifact.sourceDurationSeconds,
                estimatedUSD: artifact.estimatedCostUSD > 0 ? artifact.estimatedCostUSD : nil,
                estimatedCredits: artifact.estimatedCostCredits > 0 ? artifact.estimatedCostCredits : nil,
                pricingNote: artifact.pricingUnit
            ))
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            if Task.isCancelled || isCancellationLikeError(error) {
                if let persisted = clipLookArtifact(home: home, versionId: versionId),
                   ["canceled", "paused"].contains(persisted.status) {
                    return
                }
                artifact.status = "canceled"
                artifact.errorMessage = "Canceled by operator"
            } else {
                let failurePhase = artifact.status
                artifact.status = "failed"
                artifact.errorMessage = shotRenderFailureSummary(error, phase: failurePhase, limit: 300)
                logGeneration(
                    kind: "video.error",
                    message: "Clip Look failed shot_id=\(home.shotId.nilIfEmpty ?? "-") look_id=\(versionId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) request_id=\(artifact.requestId.nilIfEmpty ?? "-"): \(shortSummaryText(error.localizedDescription, limit: 180))"
                )
                recordSpend(SpendLedgerEntry(
                    kind: "clip_look",
                    provider: provider.rawValue,
                    model: provider.modelId,
                    requestId: artifact.requestId,
                    traceId: artifact.traceId,
                    contextLabel: spendLabel,
                    shotId: home.shotId,
                    status: "failed_unknown_charge"
                ))
            }
            artifact.updatedAt = DateFormats.now()
            persistClipLookVersion(artifact, home: home, for: project)
            aestheticStatus = artifact.status == "canceled"
                ? "Clip Look \(clipLookDisplayName(artifact)) canceled"
                : "Clip Look \(clipLookDisplayName(artifact)) failed"
        }
    }

    private func executeNewFALClipLook(
        _ artifact: inout ShotRestyleArtifact,
        home: ClipLookHome,
        project: ProjectRecord
    ) async throws {
        let request = clipLookFALRequest(for: artifact, project: project)
        let client = FALVideoClient(credentialStore: videoCredentialStore)
        let uploaded = try await client.uploadRestyleSource(request)
        artifact.inputRemoteURL = uploaded.url.absoluteString
        artifact.traceId = uploaded.traceId
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)

        let submission = try await client.submitRestyle(request, sourceRemoteURL: uploaded.url)
        artifact.requestId = submission.requestId
        artifact.traceId = submission.traceId.isEmpty ? artifact.traceId : submission.traceId
        artifact.status = "queued"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        logGeneration(
            kind: "video.submitted",
            message: "Clip Look submitted provider=fal shot_id=\(home.shotId.nilIfEmpty ?? "-") look_id=\(artifact.versionId) request_id=\(submission.requestId)"
        )

        artifact.status = "generating"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        let remote = try await client.waitForRestyle(request, requestId: submission.requestId)
        artifact.outputRemoteURL = remote.videoURL.absoluteString
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        try await finishClipLook(
            &artifact,
            request: request,
            remoteURL: remote.videoURL,
            client: client,
            project: project
        )
    }

    private func executeNewDecartClipLook(
        _ artifact: inout ShotRestyleArtifact,
        home: ClipLookHome,
        project: ProjectRecord
    ) async throws {
        let request = try decartRestyleRequest(for: artifact, project: project)
        let client = DecartVideoClient(credentialStore: videoCredentialStore)
        let submission = try await client.submitRestyle(request)
        artifact.requestId = submission.jobId
        artifact.traceId = submission.traceId
        artifact.status = "queued"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        logGeneration(
            kind: "video.submitted",
            message: "Clip Look submitted provider=decart shot_id=\(home.shotId.nilIfEmpty ?? "-") look_id=\(artifact.versionId) request_id=\(submission.jobId)"
        )

        artifact.status = "generating"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        let remote = try await client.waitForRestyle(request, jobId: submission.jobId)
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        let contentTraceId = try await client.downloadRestyleOutput(request, jobId: submission.jobId)
        artifact.traceId = contentTraceId.isEmpty ? artifact.traceId : contentTraceId
        try await finishClipLookLocal(&artifact, pictureURL: request.outputURL, project: project)
    }

    /// Two durable proof files per Clip Look:
    ///   <artifactId>_range.mp4  — the exact committed range WITH its own
    ///                             audio (extractTimeRange keeps it): the mux
    ///                             source at finish and the basis of the upload.
    ///   <artifactId>_source.mp4 — the picture-only normalized upload (the
    ///                             same 1280×720/24 blur-fill law as Shot
    ///                             Looks, so a portrait/HEVC/60fps clip
    ///                             restyles exactly as it appears in shots).
    private func prepareClipLookSource(
        media: MediaItemRecord,
        range: VideoTrimRange,
        artifactId: String,
        project: ProjectRecord
    ) async throws -> (rangeURL: URL, uploadURL: URL, durationSeconds: Double, sha256: String) {
        let proofDirectory = contextStore.aestheticProofDirectory(for: project)
        let rangeURL = proofDirectory.appendingPathComponent("\(safeIdentifier(artifactId))_range.mp4")
        let source = sources.first { $0.sourceId == media.sourceId }
        let mediaPath = media.path
        let rangeSeconds = range.durationSeconds
        let startSeconds = range.startSeconds
        try? FileManager.default.removeItem(at: rangeURL)
        _ = try await store.withSourceAccess(source) {
            try await VideoChainMedia.extractTimeRange(
                videoURL: URL(fileURLWithPath: mediaPath),
                outputURL: rangeURL,
                startSeconds: startSeconds,
                durationSeconds: rangeSeconds
            )
        }
        let specs = [VideoChainMedia.StitchClipSpec(url: rangeURL, includeAudio: false)]
        let profile = VideoOutputProfile(
            aspectRatio: .landscape16x9,
            width: 1280,
            height: 720,
            fps: 24,
            fitPolicy: .fitWithBlurFill
        )
        let built = try await VideoChainMedia.buildStitchComposition(specs: specs, profile: profile)
        guard built.durationSeconds > 0 else {
            throw ScreenGraphError.capture("The clip range has no visual duration.")
        }
        guard built.durationSeconds <= 600.001 else {
            throw ScreenGraphError.capture("Lucy Look sources are currently limited to 10 minutes.")
        }
        let uploadURL = proofDirectory.appendingPathComponent("\(safeIdentifier(artifactId))_source.mp4")
        try? FileManager.default.removeItem(at: uploadURL)
        guard let session = AVAssetExportSession(
            asset: built.composition,
            presetName: AVAssetExportPresetHighestQuality
        ) else {
            throw ScreenGraphError.capture("The Clip Look source exporter could not start.")
        }
        session.videoComposition = built.videoComposition
        session.timeRange = CMTimeRange(
            start: .zero,
            duration: CMTime(seconds: built.durationSeconds, preferredTimescale: 600)
        )
        session.shouldOptimizeForNetworkUse = true
        try await MediaExportGuard.export(session, to: uploadURL, as: .mp4, operation: "Clip Look source export")
        let measured = try await VideoChainMedia.videoDurationSeconds(videoURL: uploadURL)
        guard measured > 0 else { throw ScreenGraphError.capture("The exported Clip Look source is unreadable.") }
        let attributes = try FileManager.default.attributesOfItem(atPath: uploadURL.path)
        let byteCount = (attributes[.size] as? NSNumber)?.int64Value ?? 0
        guard byteCount > 0 else { throw ScreenGraphError.capture("The exported Clip Look source is empty.") }
        guard byteCount <= 200 * 1_024 * 1_024 else {
            throw ScreenGraphError.capture("The exported Clip Look source exceeds Lucy's 200 MB input limit.")
        }
        let data = try Data(contentsOf: uploadURL, options: [.mappedIfSafe])
        return (rangeURL, uploadURL, measured, sha256Hex(data))
    }

    /// Download → restore the original range's audio under the Lucy picture →
    /// archive as tray footage. The artifact never activates anything.
    private func finishClipLook(
        _ artifact: inout ShotRestyleArtifact,
        request: FALRestyleRequest,
        remoteURL: URL,
        client: FALVideoClient,
        project: ProjectRecord
    ) async throws {
        try await client.downloadRestyleOutput(request, remoteURL: remoteURL)
        try await finishClipLookLocal(&artifact, pictureURL: request.outputURL, project: project)
    }

    private func finishClipLookLocal(
        _ artifact: inout ShotRestyleArtifact,
        pictureURL: URL,
        project: ProjectRecord
    ) async throws {
        let duration = try await VideoChainMedia.videoDurationSeconds(videoURL: pictureURL)
        guard duration > 0 else { throw ScreenGraphError.capture("The downloaded Lucy Clip Look has no video track.") }

        let proofDirectory = contextStore.aestheticProofDirectory(for: project)
        let rangeURL = proofDirectory.appendingPathComponent("\(safeIdentifier(artifact.versionId))_range.mp4")
        if !FileManager.default.fileExists(atPath: rangeURL.path) {
            // Resume after the proof was cleaned up: re-extract the persisted
            // range from the source clip. Without the original audio there is
            // no honest archive (the file's own track IS the Source lane).
            guard artifact.clipRangeSeconds > 0,
                  let media = items.first(where: { $0.mediaId == artifact.sourceClipMediaId }),
                  FileManager.default.fileExists(atPath: media.path) else {
                throw ScreenGraphError.capture("The source clip for this Look is no longer available, so its audio cannot be restored.")
            }
            let source = sources.first { $0.sourceId == media.sourceId }
            let mediaPath = media.path
            let startSeconds = artifact.sourceClipStartSeconds
            let rangeSeconds = artifact.clipRangeSeconds
            _ = try await store.withSourceAccess(source) {
                try await VideoChainMedia.extractTimeRange(
                    videoURL: URL(fileURLWithPath: mediaPath),
                    outputURL: rangeURL,
                    startSeconds: startSeconds,
                    durationSeconds: rangeSeconds
                )
            }
        }
        let finalURL = proofDirectory.appendingPathComponent("\(safeIdentifier(artifact.versionId))_final.mp4")
        try? FileManager.default.removeItem(at: finalURL)
        guard let muxed = await ShotAudioComposition.buildBareLookOverOriginalAudio(
            videoURL: pictureURL,
            audioSourceURL: rangeURL,
            sourceDurationSeconds: artifact.sourceDurationSeconds
        ), let session = AVAssetExportSession(
            asset: muxed.composition,
            presetName: AVAssetExportPresetHighestQuality
        ) else {
            throw ScreenGraphError.capture("The Clip Look audio could not be restored onto the restyled picture.")
        }
        session.timeRange = CMTimeRange(start: .zero, duration: muxed.composition.duration)
        try await MediaExportGuard.export(session, to: finalURL, as: .mp4, operation: "Clip Look finish")

        let sourceItem = items.first { $0.mediaId == artifact.sourceClipMediaId }
        let sourceName = (sourceItem?.filename).flatMap {
            (($0 as NSString).deletingPathExtension).nilIfEmpty
        } ?? "Clip"
        let styleName = artifact.styleLabel.trimmed.nilIfEmpty ?? "Lucy"
        let rangeLabel = videoTrimDisplayLabel(
            range: VideoTrimRange(
                startSeconds: artifact.sourceClipStartSeconds,
                endSeconds: artifact.sourceClipEndSeconds
            )
        )
        let mediaId = "genmedia_\(shortHash("\(project.projectId):\(artifact.versionId):clip_look", length: 20))"
        guard let media = await archiveGeneratedMedia(
            fileURL: finalURL,
            project: project,
            mediaId: mediaId,
            derivativeKind: MediaItemRecord.clipLookDerivativeKind,
            sourceMediaId: artifact.sourceClipMediaId,
            sourceTimestampSeconds: artifact.sourceClipStartSeconds,
            filename: generatedMediaArchiveFilename(
                base: "\(sourceName) \(styleName) Look",
                path: finalURL.path,
                fallbackExtension: "mp4"
            ),
            tags: ["generated", "clip", "look", "lucy-restyle"],
            notes: "Lucy Clip Look (720p) of \(sourceName) \(rangeLabel), original range audio kept.",
            rejectedByDefault: false
        ) else {
            throw ScreenGraphError.capture("The finished Clip Look could not be archived.")
        }
        artifact.outputMediaId = media.mediaId
        artifact.status = "ready"
        artifact.videoPath = finalURL.path
        artifact.outputDurationSeconds = duration
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
    }

    private func resumeClipLook(_ savedArtifact: ShotRestyleArtifact, home: ClipLookHome) async {
        guard let project = currentProject, !savedArtifact.requestId.isEmpty else { return }
        var artifact = savedArtifact
        do {
            switch artifact.restyleProvider {
            case .fal:
                try await resumeFALClipLook(&artifact, home: home, project: project)
            case .decart:
                try await resumeDecartClipLook(&artifact, home: home, project: project)
            }
            try Task.checkCancellation()
            guard currentProject?.projectId == project.projectId else { return }
            persistClipLookVersion(artifact, home: home, for: project)
            aestheticStatus = "Clip Look \(clipLookDisplayName(artifact)) ready in Footage"
        } catch {
            guard currentProject?.projectId == project.projectId else { return }
            if Task.isCancelled || isCancellationLikeError(error) { return }
            artifact.status = "failed"
            artifact.errorMessage = shotRenderFailureSummary(error, phase: "resume_\(savedArtifact.status)", limit: 300)
            artifact.updatedAt = DateFormats.now()
            persistClipLookVersion(artifact, home: home, for: project)
            aestheticStatus = "Clip Look recovery needs attention"
        }
    }

    private func resumeFALClipLook(
        _ artifact: inout ShotRestyleArtifact,
        home: ClipLookHome,
        project: ProjectRecord
    ) async throws {
        let request = clipLookFALRequest(for: artifact, project: project)
        let client = FALVideoClient(credentialStore: videoCredentialStore)
        let remoteURL: URL
        if let savedRemote = URL(string: artifact.outputRemoteURL), !artifact.outputRemoteURL.isEmpty {
            remoteURL = savedRemote
        } else {
            artifact.status = "generating"
            artifact.errorMessage = ""
            artifact.updatedAt = DateFormats.now()
            persistClipLookVersion(artifact, home: home, for: project)
            let remote = try await client.waitForRestyle(request, requestId: artifact.requestId)
            remoteURL = remote.videoURL
            artifact.outputRemoteURL = remote.videoURL.absoluteString
            artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        }
        artifact.status = "downloading"
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        try await finishClipLook(
            &artifact,
            request: request,
            remoteURL: remoteURL,
            client: client,
            project: project
        )
    }

    private func resumeDecartClipLook(
        _ artifact: inout ShotRestyleArtifact,
        home: ClipLookHome,
        project: ProjectRecord
    ) async throws {
        let request = try decartRestyleRequest(for: artifact, project: project)
        let client = DecartVideoClient(credentialStore: videoCredentialStore)
        artifact.status = "generating"
        artifact.errorMessage = ""
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        let remote = try await client.waitForRestyle(request, jobId: artifact.requestId)
        artifact.traceId = remote.traceId.isEmpty ? artifact.traceId : remote.traceId
        artifact.status = "downloading"
        artifact.updatedAt = DateFormats.now()
        persistClipLookVersion(artifact, home: home, for: project)
        let contentTraceId = try await client.downloadRestyleOutput(request, jobId: artifact.requestId)
        artifact.traceId = contentTraceId.isEmpty ? artifact.traceId : contentTraceId
        try await finishClipLookLocal(&artifact, pictureURL: request.outputURL, project: project)
    }

    private func clipLookFALRequest(for artifact: ShotRestyleArtifact, project: ProjectRecord) -> FALRestyleRequest {
        FALRestyleRequest(
            projectId: project.projectId,
            shotId: artifact.sourceShotId,
            artifactId: artifact.versionId,
            prompt: artifact.prompt,
            enhancePrompt: artifact.enhancePrompt,
            seed: artifact.seed,
            sourceURL: URL(fileURLWithPath: artifact.sourceVideoPath),
            outputURL: clipLookOutputURL(artifactId: artifact.versionId, project: project),
            workflowName: "clip_look_restyle",
            artifactType: "clip_restyle",
            traceGroupId: "clip_look_\(artifact.sourceClipMediaId)"
        )
    }

    private func clipLookOutputURL(artifactId: String, project: ProjectRecord) -> URL {
        contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(safeIdentifier(artifactId))_lucy.mp4")
    }

    // MARK: - Send to Footage

    /// Flattens the shot's CURRENT output — the same cut-aware composition and
    /// live audio mix the player exports (preview==export law), including the
    /// active Look when one is selected — into a project-local mp4 archived as
    /// a top-level Footage tray item. No provider call, no shot mutation.
    @discardableResult
    /// THE PER-CUT FLATTEN LAW — bakes a shot's current output (cut layer +
    /// audio-lane mix + active Look) to one file. Extracted verbatim from
    /// `sendShotOutputToFootage` so Send to Footage and the Finals Reel bake
    /// cache flatten through ONE law; the `profile` parameter replaces two
    /// hardcoded 16:9 literals (and is the future Portrait Reframe's entry
    /// point). Returns false — with the status set — when the shot has no
    /// playable output; throws on export failure.
    private func flattenShotOutput(
        shot: ProjectShot,
        to exportURL: URL,
        profile: VideoOutputProfile = .standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
    ) async throws -> Bool {
        let promptPlan = shotRenderPromptPlan(shotId: shot.shotId)
        let assembly = await resolvedShotLookAssembly(
            shot: shot,
            planSegments: promptPlan?.segments ?? [],
            reversed: shot.activeLookVersion?.sourceIsReversed ?? shot.cutList.isReversed,
            includeOutputLoop: true
        )
        // BAKE HONESTY: refuse to flatten a mix whose document promises audio
        // from a file that cannot be read right now — a silent export would
        // otherwise be cached (reel bake) or shipped (Footage, YouTube) as if
        // it were the real mix. Live playback keeps its lenient skip; only
        // baked output refuses. The duration bounds the check so a region
        // stranded past the output's end never fails a bake it cannot be
        // heard in.
        func verifyAudibleAudio(outputDurationSeconds: Double) async throws {
            try await ShotAudioComposition.verifyExpectedAudibleFilesReadable(
                shotExpectedAudibleAudioFiles(
                    shot: shot,
                    outputDurationSeconds: outputDurationSeconds > 0
                        ? outputDurationSeconds
                        : .infinity
                )
            )
        }
        if let look = shot.activeLookVersion, FileManager.default.fileExists(atPath: look.videoPath) {
            try await verifyAudibleAudio(outputDurationSeconds: look.sourceDurationSeconds)
            let originalAudioAsset: AVAsset?
            if assembly.hasPlayableClips {
                let original = try await VideoChainMedia.buildStitchComposition(
                    specs: assembly.playableSpecs,
                    profile: profile
                )
                originalAudioAsset = original.composition
            } else if let path = shot.activeRenderVersion?.videoPath.trimmed.nilIfEmpty {
                originalAudioAsset = AVURLAsset(url: URL(fileURLWithPath: path))
            } else {
                originalAudioAsset = nil
            }
            guard let mixed = await ShotAudioComposition.buildLook(
                videoURL: URL(fileURLWithPath: look.videoPath),
                originalAudioAsset: originalAudioAsset,
                sourceDurationSeconds: look.sourceDurationSeconds,
                shot: shot,
                assembly: assembly.hasPlayableClips ? assembly : nil,
                loopCount: shot.cutList.normalized().outputLoopCount
            ), let session = AVAssetExportSession(
                asset: mixed.composition,
                presetName: AVAssetExportPresetHighestQuality
            ) else {
                throw ScreenGraphError.capture("The active Look audio mix could not be prepared.")
            }
            session.audioMix = mixed.audioMix
            session.timeRange = CMTimeRange(start: .zero, duration: mixed.composition.duration)
            try await MediaExportGuard.export(session, to: exportURL, as: .mp4, operation: "cut export")
        } else if assembly.hasPlayableClips {
            try await verifyAudibleAudio(outputDurationSeconds: assembly.baseOutputSeconds)
            let built = try await VideoChainMedia.buildStitchComposition(
                specs: assembly.playableSpecs,
                profile: profile
            )
            let audioMix = await ShotAudioComposition.applyMix(
                to: built.composition,
                shot: shot,
                assembly: assembly
            )
            guard let session = AVAssetExportSession(
                asset: built.composition,
                presetName: AVAssetExportPresetHighestQuality
            ) else {
                throw ScreenGraphError.capture("The shot export could not start.")
            }
            session.videoComposition = built.videoComposition
            session.audioMix = audioMix
            session.timeRange = CMTimeRange(
                start: .zero,
                duration: CMTime(seconds: built.durationSeconds, preferredTimescale: 600)
            )
            try await MediaExportGuard.export(session, to: exportURL, as: .mp4, operation: "cut export")
        } else if let path = (shot.activeRenderVersion?.videoPath.trimmed.nilIfEmpty
            ?? shot.renderArtifact?.videoPath.trimmed.nilIfEmpty),
            FileManager.default.fileExists(atPath: path) {
            let legacyDurationSeconds = (try? await VideoChainMedia.videoDurationSeconds(
                videoURL: URL(fileURLWithPath: path)
            )) ?? 0
            try await verifyAudibleAudio(outputDurationSeconds: legacyDurationSeconds)
            guard let mixed = await ShotAudioComposition.buildLegacy(
                videoURL: URL(fileURLWithPath: path),
                shot: shot
            ), let session = AVAssetExportSession(
                asset: mixed.composition,
                presetName: AVAssetExportPresetHighestQuality
            ) else {
                throw ScreenGraphError.capture("The shot audio mix could not be prepared.")
            }
            session.audioMix = mixed.audioMix
            try await MediaExportGuard.export(session, to: exportURL, as: .mp4, operation: "cut export")
        } else {
            aestheticStatus = "This shot has no playable output to send"
            return false
        }
        return true
    }

    func sendShotOutputToFootage(shotId: String) async -> Bool {
        guard activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty else {
            aestheticStatus = "Wait for the current video operation to finish"
            return false
        }
        guard let project = currentProject,
              let index = shotTimeline.shots.firstIndex(where: { $0.shotId == shotId }) else { return false }
        let shot = shotTimeline.shots[index]
        let now = DateFormats.now()
        let exportURL = contextStore.aestheticProofDirectory(for: project)
            .appendingPathComponent("\(safeIdentifier(shotId))_export_\(shortHash("\(now):\(UUID().uuidString)", length: 10)).mp4")
        do {
            try? FileManager.default.removeItem(at: exportURL)
            guard try await flattenShotOutput(shot: shot, to: exportURL) else { return false }
            let shotName = shot.name.trimmed.nilIfEmpty ?? "Shot \(index + 1)"
            let lookNote = shot.activeLookVersion.map { " · Look \($0.versionNumber)" } ?? ""
            // Once flattened this is ordinary FORWARD footage, so the tray item
            // has to say which way round it was made — and how many times over.
            let reverseNote = (shot.activeLookVersion?.sourceIsReversed ?? shot.cutList.isReversed)
                ? " · reversed"
                : ""
            let flattenLoopCount = shot.cutList.normalized().outputLoopCount
            let loopNote = flattenLoopCount > 1 ? " · loop ×\(flattenLoopCount)" : ""
            let mediaId = "genmedia_\(shortHash("\(project.projectId):\(shotId):shot_export:\(now)", length: 20))"
            guard await archiveGeneratedMedia(
                fileURL: exportURL,
                project: project,
                mediaId: mediaId,
                derivativeKind: MediaItemRecord.shotExportDerivativeKind,
                sourceMediaId: shotId,
                filename: generatedMediaArchiveFilename(
                    base: "\(shotName) Export",
                    path: exportURL.path,
                    fallbackExtension: "mp4"
                ),
                tags: ["generated", "shot", "export"],
                notes: "Flattened output of \(shotName)\(lookNote)\(reverseNote)\(loopNote) with its cut layer and audio-lane mix.",
                rejectedByDefault: false
            ) != nil else { return false }
            aestheticStatus = "\(shotName) sent to Footage"
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not send this shot to Footage"
            return false
        }
    }

    // MARK: - Export for YouTube (reel + shot)

    /// The whole Finals Reel, one click: YouTube copy → encode in temp
    /// staging → move into ~/Downloads/LitScenes-Finals → markdown second.
    /// The ordering makes an orphan .md impossible, and a failed encode never
    /// touches the destination (MediaExportGuard deletes its own partial).
    func exportFinalsReelForYouTube(
        plan: ReelCompositionPlan,
        musicRegions: [ShotAudioRegion]
    ) async {
        guard !isExportingForYouTube else { return }
        guard let project = currentProject else {
            youtubeExportStatus = "Create or select a project first"
            return
        }
        guard !plan.specs.isEmpty else {
            youtubeExportStatus = "Nothing to export — bake cuts on the board first"
            return
        }
        let subjectLines = YouTubePublishComposer.cutLines(
            cutIdsInReelOrder: plan.cutBands.map(\.cutId),
            shots: shotTimeline.shots
        )
        _ = await runYouTubeExport(
            kind: .reel,
            project: project,
            subjectLines: subjectLines,
            durationSeconds: plan.totalSeconds,
            fallbackCopyName: project.name,
            fallbackStem: stableSlug(project.name, fallback: "finals-reel")
        ) { staged in
            let result = try await FinalsReelComposer.buildReelComposition(
                plan: plan,
                musicRegions: musicRegions,
                profile: reelOutputProfile
            )
            guard let session = AVAssetExportSession(
                asset: result.composition,
                presetName: AVAssetExportPresetHighestQuality
            ) else {
                throw ScreenGraphError.capture("The reel export could not start.")
            }
            session.videoComposition = result.videoComposition
            session.audioMix = result.audioMix
            session.timeRange = CMTimeRange(
                start: .zero,
                duration: CMTime(seconds: result.durationSeconds, preferredTimescale: 600)
            )
            session.shouldOptimizeForNetworkUse = true
            try await MediaExportGuard.export(session, to: staged, as: .mp4, operation: "reel export")
            return true
        }
    }

    /// One cut's flattened output (cut layer, active Look, audio mix — the
    /// Send to Footage flatten law), landed beside its YouTube markdown.
    /// Returns the final status sentence for the shot player's footer.
    func exportShotOutputForYouTube(shotId: String) async -> String {
        guard !isExportingForYouTube else {
            return "A YouTube export is already running"
        }
        guard activeShotRenderId.isEmpty,
              activeShotJoinRenderId.isEmpty,
              activeShotRestyleId.isEmpty else {
            return "Wait for the current video operation to finish"
        }
        guard let project = currentProject,
              let index = shotTimeline.shots.firstIndex(where: { $0.shotId == shotId }) else {
            return "This cut could not be found"
        }
        let shot = shotTimeline.shots[index]
        let fallbackName = shot.name.trimmed.nilIfEmpty ?? "Shot \(index + 1)"
        return await runYouTubeExport(
            kind: .cut,
            project: project,
            subjectLines: YouTubePublishComposer.shotSubjectLines(shot: shot),
            durationSeconds: 0,
            fallbackCopyName: fallbackName,
            fallbackStem: stableSlug(fallbackName, fallback: "cut")
        ) { staged in
            try await self.flattenShotOutput(shot: shot, to: staged)
        }
    }

    /// The shared body behind both YouTube exports. `encode` writes the video
    /// into the staged URL and returns false to refuse (no playable output);
    /// everything else — copy phase with deterministic fallback, landing,
    /// pair naming, reveal, statuses — is identical across surfaces.
    private func runYouTubeExport(
        kind: YouTubePublishComposer.SubjectKind,
        project: ProjectRecord,
        subjectLines: [String],
        durationSeconds: Double,
        fallbackCopyName: String,
        fallbackStem: String,
        encode: (URL) async throws -> Bool
    ) async -> String {
        isExportingForYouTube = true
        defer { isExportingForYouTube = false }

        // Snapshot before the first await — the operator can switch projects
        // while the encode runs, and this flow must keep writing the story it
        // started from (it never touches project state, so a switch is safe).
        let story = projectStory
        let brief = projectGoalV2.activeBrief

        youtubeExportStatus = "Writing YouTube copy…"
        var title = ""
        var description = ""
        var copyFallbackReason = ""
        do {
            let client = try OpenAIClient.fromEnvironment()
            let prompt = YouTubePublishComposer.publishCopyPrompt(
                kind: kind,
                projectName: project.name,
                story: story,
                brief: brief,
                subjectLines: subjectLines,
                durationSeconds: durationSeconds
            )
            let runId = "youtube_copy_\(shortHash("\(project.projectId):\(DateFormats.now())", length: 14))"
            let result = try await client.draftYouTubePublishCopy(
                prompt: prompt,
                projectId: project.projectId,
                runId: runId
            )
            title = result.title
            description = result.descriptionMarkdown
        } catch {
            let fallback = YouTubePublishComposer.fallbackCopy(
                projectName: fallbackCopyName,
                story: story
            )
            title = fallback.title
            description = fallback.description
            copyFallbackReason = String(error.localizedDescription.prefix(80))
        }

        youtubeExportStatus = kind == .reel ? "Exporting reel video…" : "Exporting cut video…"
        let stagingDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("litscenes-youtube-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: stagingDirectory) }
        let stagedVideo = stagingDirectory.appendingPathComponent("export.mp4")
        do {
            try ensureDirectory(stagingDirectory)
            guard try await encode(stagedVideo) else {
                let status = "Nothing to export — this cut has no playable output"
                youtubeExportStatus = status
                return status
            }
        } catch {
            lastError = error.localizedDescription
            let status = "YouTube export failed: \(String(error.localizedDescription.prefix(160)))"
            youtubeExportStatus = status
            return status
        }

        let markdown = YouTubePublishComposer.publishMarkdown(title: title, description: description)
        let stem = FinalsReelPublishNaming.stem(fromTitle: title, fallback: fallbackStem)
        do {
            let landed = try await Task.detached(priority: .utility) { () -> (video: URL, markdown: URL, markdownFailure: String?) in
                let downloads = FileManager.default.urls(for: .downloadsDirectory, in: .userDomainMask).first
                    ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Downloads")
                let folder = downloads.appendingPathComponent(FinalsReelPublishNaming.folderName, isDirectory: true)
                try ensureDirectory(folder)
                // Resolved at move time, not earlier, so the stem an earlier
                // export claimed is seen before this pair picks its ordinal.
                let pair = FinalsReelPublishNaming.collisionSafePairURLs(in: folder, stem: stem) {
                    FileManager.default.fileExists(atPath: $0.path)
                }
                do {
                    try FileManager.default.moveItem(at: stagedVideo, to: pair.video)
                } catch {
                    // Cross-volume temp dirs can refuse a rename; fall back to copy.
                    try FileManager.default.copyItem(at: stagedVideo, to: pair.video)
                    try? FileManager.default.removeItem(at: stagedVideo)
                }
                do {
                    try markdown.write(to: pair.markdown, atomically: true, encoding: .utf8)
                    return (pair.video, pair.markdown, nil)
                } catch {
                    // The landed video is kept — a missing description is a
                    // partial worth having, an orphan .md never is.
                    return (pair.video, pair.markdown, error.localizedDescription)
                }
            }.value
            NSWorkspace.shared.activateFileViewerSelecting([landed.video])
            let status: String
            if let markdownFailure = landed.markdownFailure {
                status = "Exported \(landed.video.lastPathComponent), but the description file failed: \(String(markdownFailure.prefix(120)))"
            } else if copyFallbackReason.isEmpty {
                status = "Exported \(landed.video.lastPathComponent) + \(landed.markdown.lastPathComponent)"
            } else {
                status = "Exported \(landed.video.lastPathComponent) + \(landed.markdown.lastPathComponent) — YouTube copy fell back: \(copyFallbackReason)"
            }
            youtubeExportStatus = status
            return status
        } catch {
            lastError = error.localizedDescription
            let status = "YouTube export failed: \(String(error.localizedDescription.prefix(160)))"
            youtubeExportStatus = status
            return status
        }
    }

    // MARK: - Media generations (viewer Restyle / Start Video)

    private func persistMediaGenerations(_ document: ProjectMediaGenerationsDocument, for project: ProjectRecord) {
        do {
            try contextStore.saveMediaGenerations(document, for: project)
            mediaGenerations = document
        } catch {
            lastError = error.localizedDescription
        }
    }

    func persistMediaLookVersion(_ artifact: ShotRestyleArtifact, for project: ProjectRecord) {
        persistMediaGenerations(
            mediaGenerations.upsertingLookVersion(artifact, now: DateFormats.now()),
            for: project
        )
    }

    func persistMediaMotionJob(_ job: MediaMotionJob, for project: ProjectRecord) {
        persistMediaGenerations(
            mediaGenerations.upsertingMotionJob(job, now: DateFormats.now()),
            for: project
        )
    }

    /// Relaunch honesty for viewer generations: interrupted work is rewritten
    /// to `failed` with copy that says what is and is not known — motion jobs
    /// have NO paid resume (`generateClip` cannot re-attach), so theirs warns
    /// about possible duplicate spend and keeps the request id for a future
    /// resume lane.
    private func reconcileInterruptedMediaGenerations(for project: ProjectRecord) {
        let result = mediaGenerationsResumePreflight(
            document: mediaGenerations,
            now: DateFormats.now()
        )
        if result.changed {
            persistMediaGenerations(result.document, for: project)
        }
        for look in result.resumableLooks {
            resumeMediaLook(look, for: project)
        }
    }

    // MARK: - Spend ledger

    /// Records one paid event. MainActor, never throws, never blocks a
    /// render path: fast dedupe against the summary's recent-id window, pure
    /// fold into the published summary (badges and totals update
    /// immediately), then chained off-main persistence. A captured project
    /// record means a late write still lands in the right database after a
    /// project switch.
    ///
    /// Residual acceptance (by plan): a provider job re-observed AFTER its
    /// id left the 200-entry window double-folds the totals by one entry —
    /// resumes and retries resurface jobs within a session, so the window
    /// covers the real cases.
    func recordSpend(_ entry: SpendLedgerEntry) {
        guard let project = currentProject else { return }
        var record = entry
        if record.entryId.isEmpty {
            record.entryId = spendLedgerEntryId(kind: record.kind, requestId: record.requestId)
        }
        if record.at.isEmpty {
            record.at = DateFormats.now()
        }
        let alreadyKnown = spendLedgerSummary.recentEntryIds.contains(record.entryId)
        spendLedgerSummary = spendLedgerSummaryFolding(
            record,
            into: spendLedgerSummary,
            entryAlreadyExists: alreadyKnown,
            now: DateFormats.now()
        )
        let summarySnapshot = spendLedgerSummary
        let previous = spendLedgerWriteTask
        let store = contextStore
        spendLedgerWriteTask = Task(priority: .utility) { [weak self] in
            await previous?.value
            do {
                try store.saveSpendLedgerEntry(record, summary: summarySnapshot, for: project)
            } catch {
                let message = error.localizedDescription
                await MainActor.run { self?.lastError = message }
            }
        }
    }

    /// Open == ack (the notices law): the popover's appearance moves the
    /// watermark; a NEWER failure re-arms the rust dot.
    func acknowledgeSpendFailures() {
        guard let project = currentProject,
              evaluateSpendFailureAttention(spendLedgerSummary) else { return }
        let now = DateFormats.now()
        spendLedgerSummary.failuresAcknowledgedAt = now
        spendLedgerSummary.updatedAt = now
        let snapshot = spendLedgerSummary
        let previous = spendLedgerWriteTask
        let store = contextStore
        spendLedgerWriteTask = Task(priority: .utility) { [weak self] in
            await previous?.value
            do {
                try store.saveSpendLedgerSummary(snapshot, for: project)
            } catch {
                let message = error.localizedDescription
                await MainActor.run { self?.lastError = message }
            }
        }
    }

    /// The full ledger, for the plate. Newest-first.
    func loadSpendLedgerEntries() -> [SpendLedgerEntry] {
        guard let project = currentProject else { return [] }
        return contextStore.loadSpendLedgerEntries(for: project)
    }

    private func spendContextLabel(shotId: String) -> String {
        shotTimeline.shots.first { $0.shotId == shotId }?.name.trimmed.nilIfEmpty ?? "Cut"
    }

    // MARK: - Activity registry

    /// Plain-value gather of every in-flight lane for the pure registry law.
    var activityInput: LibraryActivityInput {
        var input = LibraryActivityInput()
        input.isGenerationPaused = isGenerationPaused
        input.shotRenderShotId = activeShotRenderId
        input.joinRenderCutId = activeShotJoinRenderId
        input.shotLookVersionId = activeShotRestyleId
        // Media-home looks share the clip-look lane registry but live in the
        // media-generations document — partition them into their own rows or
        // they would render as ownerless "Cut" clip looks with no cancel.
        let mediaLookIds = activeClipLookIds.filter { versionId in
            mediaGenerations.lookVersions.contains { $0.versionId == versionId }
        }
        input.clipLookVersionIds = Array(activeClipLookIds.subtracting(mediaLookIds))
        input.mediaLookVersionIds = Array(mediaLookIds)
        input.shotNarrationShotId = activeShotNarrationId
        input.lensHeroActive = isGeneratingLensHero
        input.lensHeroTakeOperationCount = activeLensHeroTakeImageIds.count
        input.reframeOperationCount = activeLensHeroReframeOperationIds.count
        input.characterRenderActive = isGeneratingCharacterRender
        input.initialDraftsActive = isGeneratingInitialDraftLenses
        input.sceneStoriesActive = isGeneratingSceneStories
        input.videoChainActive = isGeneratingVideoChain
        input.storyAudioGenerating = isGeneratingStoryAudioTrack
        input.storyAudioDrafting = isDraftingStoryAudioTrack
        input.storylineActive = isGeneratingStoryline
        input.storyDirectionsActive = isGeneratingStoryDirections
        input.storyBeatBoardActive = isGeneratingStoryBeatBoard
        input.storyBeatBoardLabel = activeStoryBeatBoardGenerationLabel
        input.storyBeatsDrafting = isDraftingStoryBeats
        input.storySignalsActive = isBuildingStorySignals
        input.storylineInterviewActive = isInterviewingStorylineCreation
        input.goalInterviewActive = isInterviewingGoal
        input.lensNarrationActive = isGeneratingLensNarration
        input.mediaAnalysisRunning = isAnalyzingMedia || mediaAnalysisRunState == .running
        for versionId in input.mediaLookVersionIds {
            guard let artifact = mediaGenerations.lookVersions
                .first(where: { $0.versionId == versionId }) else { continue }
            input.mediaLookLabelByVersionId[versionId] = items
                .first { $0.mediaId == artifact.sourceClipMediaId }?
                .filename ?? clipLookDisplayName(artifact)
        }
        input.mediaMotionJobIds = Array(activeMediaMotionJobIds)
        for jobId in activeMediaMotionJobIds {
            guard let job = mediaGenerations.motionJobs.first(where: { $0.jobId == jobId }) else { continue }
            input.mediaMotionLabelByJobId[jobId] = items
                .first { $0.mediaId == job.sourceMediaId }?
                .filename ?? ""
        }
        input.reverseBakeShotCount = activeReverseBakeShotIds.count
        input.reelBakeRunningCount = reelBakeStates.values.filter { state in
            if case .queued = state { return true }
            if case .baking = state { return true }
            return false
        }.count
        input.ambientBedBaking = isBakingAmbientBed
        input.narrationRetimeShotId = activeShotNarrationSpeedId
        input.storyAudioRemixActive = isRemixingStoryAudioTrack
        input.videoTrimSaving = isSavingVideoTrim
        input.youtubeExportActive = isExportingForYouTube
        input.shotNameById = Dictionary(
            shotTimeline.shots.map { ($0.shotId, $0.name) },
            uniquingKeysWith: { first, _ in first }
        )
        if !activeShotRestyleId.isEmpty,
           let owner = shotTimeline.shots.first(where: { shot in
               shot.lookVersions.contains { $0.versionId == activeShotRestyleId }
           }) {
            input.shotIdByLookVersionId[activeShotRestyleId] = owner.shotId
        }
        for versionId in activeClipLookIds {
            guard let owner = shotTimeline.shots.first(where: { shot in
                shot.clipLookVersions.contains { $0.versionId == versionId }
            }) else { continue }
            input.shotIdByClipLookVersionId[versionId] = owner.shotId
            if let artifact = owner.clipLookVersions.first(where: { $0.versionId == versionId }) {
                input.clipLookLabelByVersionId[versionId] = clipLookDisplayName(artifact)
            }
        }
        if !activeShotJoinRenderId.isEmpty,
           let owner = shotTimeline.shots.first(where: { shot in
               shot.cutList.segmentCuts.contains { $0.id == activeShotJoinRenderId }
           }) {
            input.shotIdByCutId[activeShotJoinRenderId] = owner.shotId
        }
        return input
    }

    var activitySnapshot: [ActivityRow] { libraryActivitySnapshot(activityInput) }
    var hasRunningActivity: Bool { !activitySnapshot.isEmpty }
    var runningPaidCount: Int { activitySnapshot.filter(\.isPaid).count }

    /// Routes a registry cancel value onto the engine's REAL cancel entry
    /// points — the only six that exist.
    func performActivityCancel(_ action: ActivityCancelAction) {
        switch action {
        case .none:
            break
        case .shotLook(let shotId):
            cancelShotLookRestyle(shotId: shotId)
        case .clipLook(let shotId, let versionId):
            cancelClipLookRestyle(shotId: shotId, versionId: versionId)
        case .mediaLook(let versionId):
            cancelMediaLookRestyle(versionId: versionId)
        case .mediaMotion(let jobId):
            cancelMediaMotionRender(jobId: jobId)
        case .reelBakes:
            cancelReelBakes()
        case .mediaAnalysis:
            armMediaAnalysisCancel()
        }
    }

    // MARK: - Finals Reel bake lane

    /// Brings the bake cache up to date with the FINALS shelf. Each pick's
    /// fingerprint is computed on ONE duration-resolved assembly snapshot —
    /// the same state the bake will flatten — publishes an honest named
    /// state per cut, sweeps cache pairs nothing wants, and drains the queue
    /// serially. A mid-queue edit to a cut simply means its NEXT ensure
    /// computes a fresh fingerprint and re-bakes: the cache self-heals.
    func ensureReelBakes() async {
        guard let project = currentProject else { return }
        let directory = contextStore.reelBakeDirectory(for: project)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let token = UUID()
        reelBakeRunToken = token
        reelBakeDrainTask?.cancel()
        reelBakeDrainTask = nil

        var wanted: Set<String> = []
        var pending: [(shot: ProjectShot, fingerprint: String)] = []
        var states: [String: ReelBakeState] = [:]
        for entry in outputFinals {
            guard let shot = shotTimeline.shots.first(where: { $0.shotId == entry.cutId }) else { continue }
            // The player's own notion of playable, not the rail's.
            let playable = shot.playableRenderVersion?.isReady == true
                || shot.activeLookVersion != nil
                || shot.renderArtifact?.videoPath.trimmed.nilIfEmpty != nil
            guard playable else {
                states[entry.cutId] = .skipped("Not rendered yet")
                continue
            }
            let plan = shotRenderPromptPlan(shotId: shot.shotId)
            let assembly = await resolvedShotLookAssembly(
                shot: shot,
                planSegments: plan?.segments ?? [],
                reversed: shot.activeLookVersion?.sourceIsReversed ?? shot.cutList.isReversed,
                includeOutputLoop: true
            )
            guard reelBakeRunToken == token,
                  currentProject?.projectId == project.projectId else { return }
            let fingerprint = shotReelBakeFingerprint(
                shot: shot,
                assembly: assembly,
                profile: reelOutputProfile
            )
            wanted.insert(fingerprint)
            let fileURL = directory.appendingPathComponent("\(fingerprint).mp4")
            let sidecarURL = directory.appendingPathComponent("\(fingerprint).json")
            if FileManager.default.fileExists(atPath: fileURL.path),
               let data = try? Data(contentsOf: sidecarURL),
               let sidecar = try? JSONDecoder().decode(ReelBakeSidecar.self, from: data),
               sidecar.durationSeconds > 0 {
                states[entry.cutId] = .ready(url: fileURL, durationSeconds: sidecar.durationSeconds)
            } else {
                states[entry.cutId] = .queued
                pending.append((shot, fingerprint))
            }
        }
        reelBakeStates = states
        sweepReelBakeDirectory(directory, keeping: wanted)
        guard !pending.isEmpty else { return }
        reelBakeDrainTask = Task { @MainActor [weak self] in
            for item in pending {
                guard let self,
                      !Task.isCancelled,
                      self.reelBakeRunToken == token else { return }
                await self.runReelBake(
                    shot: item.shot,
                    fingerprint: item.fingerprint,
                    directory: directory,
                    token: token
                )
            }
        }
    }

    /// Modal close. Queued claims clear and the drain task tears down; a
    /// finished bake stays ready (the cache is durable), and an in-flight
    /// export's partial file is deleted by the guard's failure path.
    func cancelReelBakes() {
        reelBakeRunToken = UUID()
        reelBakeDrainTask?.cancel()
        reelBakeDrainTask = nil
        for (cutId, state) in reelBakeStates {
            switch state {
            case .queued, .baking:
                reelBakeStates[cutId] = nil
            default:
                break
            }
        }
    }

    private func runReelBake(
        shot: ProjectShot,
        fingerprint: String,
        directory: URL,
        token: UUID
    ) async {
        guard currentProject != nil else { return }
        // Every state write is token-guarded: a superseding ensure owns the
        // board, and a stale drain finishing its in-flight export must not
        // clobber the new run's claims (its file still lands in the cache,
        // where the new run's own check will adopt or sweep it).
        func publish(_ state: ReelBakeState) {
            guard reelBakeRunToken == token else { return }
            reelBakeStates[shot.shotId] = state
        }
        publish(.baking)
        let fileURL = directory.appendingPathComponent("\(fingerprint).mp4")
        let sidecarURL = directory.appendingPathComponent("\(fingerprint).json")
        // Export to a per-run temp file and promote on success: a RETRY's
        // superseding drain can otherwise race a still-finishing old drain
        // onto the SAME cache path. Same-fingerprint bakes have identical
        // content, so promote-last-wins is harmless where two writers to one
        // path would corrupt.
        let partialURL = directory.appendingPathComponent(
            "\(fingerprint).partial-\(UUID().uuidString.prefix(8)).mp4"
        )
        do {
            guard try await flattenShotOutput(shot: shot, to: partialURL, profile: reelOutputProfile) else {
                publish(.skipped("No playable output"))
                return
            }
            // The sidecar records PROBED truth off the encoded file — the
            // composition plan never consumes the estimate the bake began
            // from.
            let probed = try await VideoChainMedia.videoDurationSeconds(videoURL: partialURL)
            guard probed > 0 else {
                throw ScreenGraphError.capture("The baked reel clip has no playable duration.")
            }
            try? FileManager.default.removeItem(at: fileURL)
            try FileManager.default.moveItem(at: partialURL, to: fileURL)
            let sidecar = ReelBakeSidecar(
                fingerprint: fingerprint,
                cutId: shot.shotId,
                durationSeconds: probed,
                bakedAt: DateFormats.now()
            )
            try JSONEncoder().encode(sidecar).write(to: sidecarURL, options: .atomic)
            publish(.ready(url: fileURL, durationSeconds: probed))
        } catch {
            try? FileManager.default.removeItem(at: partialURL)
            if !Task.isCancelled {
                publish(.failed(String(error.localizedDescription.prefix(200))))
            }
        }
    }

    // MARK: - Finals Reel state ops (seams + music bed)
    //
    // Every op is ONE persisted Output transaction returning the PRE-edit
    // whole-reel snapshot for symmetric Undo (nil = nothing changed).

    private func commitReelState(
        _ transform: (ProjectOutputSequenceDocument) -> ProjectOutputSequenceDocument
    ) -> ReelStateSnapshot? {
        guard let project = currentProject else { return nil }
        let before = ReelStateSnapshot(
            reelAudio: outputSequence.reelAudio,
            reelSeams: outputSequence.reelSeams,
            reelFadeInFrames: outputSequence.reelFadeInFrames,
            reelFadeOutFrames: outputSequence.reelFadeOutFrames
        )
        var updated = transform(outputSequence).normalized()
        guard updated != outputSequence else { return nil }
        updated.updatedAt = DateFormats.now()
        do {
            try contextStore.saveOutputSequence(updated, for: project)
            if currentProject?.projectId == project.projectId {
                outputSequence = updated
            }
        } catch {
            lastError = error.localizedDescription
            return nil
        }
        return before
    }

    // MARK: - Ready timeline (SCENES v2 marks → the Output sequence)
    //
    // "Ready" IS membership in the Output sequence — the same document the
    // Finals Reel plays, bakes, and exports. Writes ride commitReelState
    // (identity + currency guarded); the legacy stageSet FINALS path
    // (addCutToFinals) is deliberately not touched. The snapshot is discarded:
    // it covers only reelAudio/reelSeams, so it is not an undo for picks.

    /// The mark-ready gate: a current playable render exists and NO video
    /// work is in flight for the scene — shot render, razor-join bridge, or
    /// Shot Look all count (`cutHasInFlightVideoOperation`), matching the
    /// trash/uncombine guards.
    func sceneCanBeMarkedReady(shotId: String) -> Bool {
        guard !cutHasInFlightVideoOperation(cutId: shotId),
              let shot = shotTimeline.visibleShots.first(where: { $0.shotId == shotId }),
              shot.renderArtifact?.status != "generating"
        else { return false }
        return shot.playableRenderVersion?.isReady == true
    }

    /// True when the scene is in the Ready Timeline.
    func sceneIsMarkedReady(shotId: String) -> Bool {
        outputSequence.shots.contains { $0.shotId == shotId }
    }

    @discardableResult
    func markSceneReady(shotId: String) -> Bool {
        guard sceneCanBeMarkedReady(shotId: shotId) else {
            aestheticStatus = "Only rendered Scenes can be marked ready"
            return false
        }
        let changed = commitReelState { $0.appendingShot(shotId, now: DateFormats.now()) } != nil
        if changed {
            aestheticStatus = "Scene marked ready — it joined the Output sequence"
        }
        return changed
    }

    @discardableResult
    func unmarkSceneReady(shotId: String) -> Bool {
        let changed = commitReelState { $0.removingShot(shotId, now: DateFormats.now()) } != nil
        if changed {
            aestheticStatus = "Scene removed from the Output sequence"
        }
        return changed
    }

    func moveReadyScene(shotId: String, toIndex index: Int) {
        _ = commitReelState { $0.movingShot(shotId, toIndex: index, now: DateFormats.now()) }
    }

    /// Sets (or, with nil frames, clears back to a hard cut) the seam between
    /// two FINALS picks. Frames snap to the 6/12/24 presets; `kind` picks
    /// crossfade or dip-through-black (both consume the same frames).
    @discardableResult
    func setReelSeam(
        leftEntryId: String,
        rightEntryId: String,
        kind: ReelSeamKind = .crossfade,
        crossfadeFrames: Int?
    ) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            value.reelSeams.removeAll {
                $0.leftEntryId == leftEntryId && $0.rightEntryId == rightEntryId
            }
            if let crossfadeFrames {
                value.reelSeams.append(ReelSeamStyle(
                    leftEntryId: leftEntryId,
                    rightEntryId: rightEntryId,
                    kind: kind,
                    crossfadeFrames: crossfadeFrames,
                    updatedAt: DateFormats.now()
                ).normalized())
            }
            return value
        }
    }

    /// Sets the reel's head/tail fades (0 = off; values snap to the presets
    /// through the document's own normalize).
    @discardableResult
    func setReelFades(fadeInFrames: Int, fadeOutFrames: Int) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            value.reelFadeInFrames = fadeInFrames
            value.reelFadeOutFrames = fadeOutFrames
            return value
        }
    }

    /// Places music on the reel's one bed lane. Paths resolve at placement
    /// time (the shot-audio law), the region clamps into the reel when its
    /// length is known, and the lane never replaces silently — every call
    /// adds a fresh region.
    @discardableResult
    func addReelAudioRegion(
        asset: ShotAudioAssetReference,
        startSeconds: Double,
        reelDurationSeconds: Double
    ) -> ReelStateSnapshot? {
        let path: String
        let mediaId: String
        let label: String
        let mediaSeconds: Double?
        switch asset {
        case .projectAudio(let projectMediaId):
            guard let item = items.first(where: {
                $0.mediaId == projectMediaId && $0.kind == .audio
            }) else {
                aestheticStatus = "That audio clip is no longer in this project"
                return nil
            }
            path = item.path
            mediaId = item.mediaId
            label = item.filename
            mediaSeconds = item.durationSeconds
        case .ambientBed(let bedId):
            guard let project = currentProject,
                  let record = ambientBedLibrary.bed(bedId) else {
                aestheticStatus = "That ambient bed is no longer in the library"
                return nil
            }
            path = ambientBedFileURL(record, project: project).path
            mediaId = record.bedId
            label = record.displayName
            mediaSeconds = record.durationSeconds > 0 ? record.durationSeconds : nil
        }
        let start = ShotAudioTiming.frameQuantizedStart(max(startSeconds, 0))
        let remaining = reelDurationSeconds > 0
            ? max(reelDurationSeconds - start, ShotAudioTiming.frameSeconds)
            : (mediaSeconds ?? 0)
        let duration = min(max(mediaSeconds ?? remaining, ShotAudioTiming.frameSeconds), max(remaining, ShotAudioTiming.frameSeconds))
        guard duration.isFinite, duration > 0 else {
            aestheticStatus = "That audio has no readable duration yet"
            return nil
        }
        let region = ShotAudioRegion(
            regionId: "reel_region_\(UUID().uuidString.lowercased())",
            laneId: reelMusicLaneId,
            label: label,
            path: path,
            mediaId: mediaId,
            provenance: "reel_music",
            startSeconds: start,
            durationSeconds: duration,
            sourceDurationSeconds: mediaSeconds,
            gain: 1,
            isMuted: false,
            loops: false
        ).normalized()
        let snapshot = commitReelState { doc in
            var value = doc
            value.reelAudio.append(region)
            return value
        }
        if snapshot != nil {
            aestheticStatus = "Added \(label) to the reel's music bed"
        }
        return snapshot
    }

    /// Continuous drag-end move through the shared `movedTo` law.
    @discardableResult
    func moveReelAudioRegion(
        regionId: String,
        startSeconds: Double,
        reelDurationSeconds: Double
    ) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            guard let index = value.reelAudio.firstIndex(where: { $0.regionId == regionId }) else {
                return doc
            }
            value.reelAudio[index] = value.reelAudio[index].movedTo(
                startSeconds: startSeconds,
                timelineSeconds: reelDurationSeconds
            )
            return value
        }
    }

    /// Trim/extend through the shared geometry law (honest media-end clamp).
    @discardableResult
    func setReelAudioRegionGeometry(
        regionId: String,
        startSeconds: Double,
        sourceStartSeconds: Double,
        durationSeconds: Double,
        reelDurationSeconds: Double
    ) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            guard let index = value.reelAudio.firstIndex(where: { $0.regionId == regionId }) else {
                return doc
            }
            value.reelAudio[index] = value.reelAudio[index].applyingGeometry(
                startSeconds: startSeconds,
                sourceStartSeconds: sourceStartSeconds,
                durationSeconds: durationSeconds,
                timelineSeconds: reelDurationSeconds
            )
            return value
        }
    }

    /// Operator-editable fields (gain, mute, loops via the loop law) —
    /// identity stays with the region.
    @discardableResult
    func updateReelAudioRegion(_ region: ShotAudioRegion) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            guard let index = value.reelAudio.firstIndex(where: { $0.regionId == region.regionId }) else {
                return doc
            }
            var updated = value.reelAudio[index]
            updated.startSeconds = region.startSeconds
            updated.sourceStartSeconds = region.sourceStartSeconds
            updated.durationSeconds = region.durationSeconds
            updated.playbackRate = region.playbackRate
            updated.pitchMode = region.pitchMode
            updated.gain = region.gain
            updated.isMuted = region.isMuted
            updated = updated.settingLoops(region.loops)
            value.reelAudio[index] = updated.normalized()
            return value
        }
    }

    @discardableResult
    func deleteReelAudioRegion(regionId: String) -> ReelStateSnapshot? {
        commitReelState { doc in
            var value = doc
            value.reelAudio.removeAll { $0.regionId == regionId }
            return value
        }
    }

    /// The Undo primitive: reinstates seams, music, and fades wholesale.
    func restoreReelState(_ snapshot: ReelStateSnapshot) {
        _ = commitReelState { doc in
            var value = doc
            value.reelAudio = snapshot.reelAudio
            value.reelSeams = snapshot.reelSeams
            value.reelFadeInFrames = snapshot.reelFadeInFrames
            value.reelFadeOutFrames = snapshot.reelFadeOutFrames
            return value
        }
    }

    /// Deletes cache pairs no current fingerprint wants. Runs only from
    /// `ensureReelBakes` (never mid-export): everything still pending is in
    /// `keeping`, so an in-flight bake's output is never swept.
    private func sweepReelBakeDirectory(_ directory: URL, keeping wanted: Set<String>) {
        guard let contents = try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: nil
        ) else { return }
        for url in contents {
            let stem = url.deletingPathExtension().lastPathComponent
            guard !wanted.contains(stem) else { continue }
            try? FileManager.default.removeItem(at: url)
        }
    }

    /// One paid FAL request for the whole shot. The provider's embedded audio
    /// is discarded after download; the authored narration lane is mixed once
    /// by the existing player/export path.
    private func renderNarrationDrivenShot(
        project: ProjectRecord,
        shot: ProjectShot,
        frameLookup: [String: ProjectLensHeroImage],
        onlySegmentKeys: Set<String>?
    ) async -> Bool {
        guard onlySegmentKeys == nil else {
            aestheticStatus = "LTX 2.3 renders one narration-driven clip — re-render the whole shot"
            return false
        }
        guard let anchor = shotNarrationAnchorEntry(shot: shot, frameLookup: frameLookup) else {
            aestheticStatus = "LTX 2.3 needs a ready frame — add or render a frame first"
            return false
        }
        let anchorEntry = anchor.entry
        let anchorFrame = anchor.frame
        guard let narration = shot.narrationArtifact,
              narration.isReady,
              narration.provider == "elevenlabs_tts",
              FileManager.default.fileExists(atPath: narration.audioPath) else {
            aestheticStatus = "LTX 2.3 needs a ready ElevenLabs narration — open Narration to create one"
            return false
        }
        // THE LIP-SYNC ANCHOR LAW: refuse before any spend when the anchor
        // cannot carry a mouth. Detector failure fails open, and the
        // operator's per-entry vouch overrides the block (Vision misses
        // stylized faces).
        if shotAnchorFaceOverrideApplies(
            overrideEntryId: shot.narrationAnchorFaceOverrideEntryId,
            anchorEntryId: anchorEntry.entryId
        ) {
            aestheticStatus = "Face check overridden — rendering the picked anchor anyway"
        } else if let refusal = shotAnchorLipSyncRefusal(
            verdict: shotAnchorLipSyncVerdict(report: shotAnchorFaceReport(imagePath: anchorFrame.imagePath))
        ) {
            aestheticStatus = refusal
            return false
        }

        let profile = VideoOutputProfile.standard(
            .landscape16x9,
            fitPolicy: .fitWithBlurFill
        )
        let capability = VideoProviderCapability.capability(
            for: .falAudioToVideo,
            outputProfile: profile,
            durationSeconds: 5,
            credentialStore: videoCredentialStore
        )
        guard capability.canRender else {
            aestheticStatus = "Configure FAL in App Settings before rendering LTX 2.3"
            return false
        }

        activeShotRenderId = shot.shotId
        defer { activeShotRenderId = "" }
        let now = DateFormats.now()
        let versionId = "shotrender_\(shortHash("\(project.projectId):\(shot.shotId):\(now)", length: 14))"
        let workDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "shot_ltx_\(safeIdentifier(shot.shotId))_\(shortHash(now, length: 8))",
                isDirectory: true
            )
        var artifact = ShotRenderArtifact(
            versionId: versionId,
            versionNumber: (shot.renderVersions.map(\.versionNumber).max() ?? 0) + 1,
            stack: shot.renderStack.rawValue,
            provider: VideoProviderSelection.falAudioToVideo.rawValue,
            model: VideoModelSelection.falLTX23AudioToVideo.providerModelId,
            status: "generating",
            segmentCount: 1,
            progressText: "PREPARING NARRATION DRIVER",
            renderedEntryIds: shot.entries.map(\.entryId),
            sourceNarrationTraceId: narration.traceId,
            sourceEntryId: anchorEntry.entryId,
            generatedAt: now,
            updatedAt: now
        )
        persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)
        aestheticStatus = "Preparing one LTX 2.3 narration-driven clip"
        var failurePhase = "preparing_narration_driver"
        let renderStartedAt = Date()

        do {
            try ensureDirectory(workDirectory)
            let proofDirectory = contextStore.aestheticProofDirectory(for: project)
            try ensureDirectory(proofDirectory)
            let driver = try await ShotNarrationDriverBuilder.export(
                shot: shot,
                outputURL: workDirectory.appendingPathComponent("narration_driver.m4a")
            )
            artifact.sourceNarrationRegionId = driver.regionId
            artifact.sourceNarrationFingerprint = driver.fingerprint
            artifact.sourceNarrationDurationSeconds = driver.durationSeconds
            artifact.progressText = "PREPARING FIRST FRAME"
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)

            let normalizedFrame = try VideoChainMedia.normalizeImageFrame(
                sourceURL: URL(fileURLWithPath: anchorFrame.imagePath),
                outputURL: workDirectory.appendingPathComponent("first_frame.png"),
                profile: profile,
                fitPolicy: .fitWithBlurFill
            )
            let pair = ShotRenderPair(
                start: anchorFrame,
                end: nil,
                startPlacementEntryId: anchorEntry.entryId,
                endPlacementEntryId: ""
            )
            let promptUsed = shot.segmentPromptOverride(for: pair)
                ?? shotNarrationDrivenSegmentPrompt()
            let providerOutput = workDirectory.appendingPathComponent("provider_output.mp4")
            artifact.progressText = "SUBMITTING LTX 2.3"
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)
            failurePhase = "fal_ltx_audio_to_video"
            logGeneration(
                kind: "video.start",
                message: "[fal_ltx_audio_to_video] starting request_id=pending shot_id=\(shot.shotId) duration_s=\(String(format: "%.3f", driver.durationSeconds)) status_code=0"
            )
            let startedAt = Date()
            let result = try await VideoProviderRegistry(
                credentialStore: videoCredentialStore
            ).provider(for: .falAudioToVideo).generateClip(from: VideoClipRequest(
                chainId: "shot_render_\(shot.shotId)",
                segmentId: "\(versionId)_narration",
                modelSelection: .falLTX23AudioToVideo,
                prompt: promptUsed,
                negativePrompt: "",
                durationSeconds: Int(driver.durationSeconds.rounded()),
                outputProfile: profile,
                startFrameURL: normalizedFrame,
                targetEndFrameURL: nil,
                outputURL: providerOutput,
                generateAudio: false,
                projectId: project.projectId,
                runId: versionId,
                traceGroupId: versionId,
                workflowName: "shot_narration_video_render",
                artifactType: "shot_render",
                audioDriverURL: driver.url,
                audioDriverDurationSeconds: driver.durationSeconds,
                parentTraceId: driver.sourceTraceId,
                onProviderSubmitted: { [weak self] requestId, _ in
                    guard let self,
                          self.currentProject?.projectId == project.projectId,
                          let liveShot = self.shotTimeline.shots.first(where: {
                              $0.shotId == shot.shotId
                          }),
                          var liveArtifact = liveShot.renderVersions.first(where: {
                              $0.versionId == versionId
                          }) else { return }
                    if !liveArtifact.requestIds.contains(requestId) {
                        liveArtifact.requestIds.append(requestId)
                    }
                    liveArtifact.progressText = "LTX 2.3 GENERATING"
                    liveArtifact.updatedAt = DateFormats.now()
                    self.persistShotRenderVersion(
                        liveArtifact,
                        shotId: shot.shotId,
                        for: project
                    )
                }
            ))
            let requestId = result.providerJobId.trimmed.nilIfEmpty
                ?? result.providerVideoId.trimmed
            if !requestId.isEmpty, !artifact.requestIds.contains(requestId) {
                artifact.requestIds.append(requestId)
            }
            logGeneration(
                kind: "video.completed",
                message: "[fal_ltx_audio_to_video] completed request_id=\(requestId.isEmpty ? "-" : requestId) duration_ms=\(Int(Date().timeIntervalSince(startedAt) * 1000)) status_code=200"
            )
            recordSpend(SpendLedgerEntry(
                kind: "shot_render_narration_driven",
                provider: VideoProviderSelection.falAudioToVideo.rawValue,
                model: VideoModelSelection.falLTX23AudioToVideo.providerModelId,
                requestId: requestId,
                traceId: result.traceId,
                contextLabel: spendContextLabel(shotId: shot.shotId),
                shotId: shot.shotId,
                unit: "seconds",
                unitCount: driver.durationSeconds,
                estimatedUSD: ShotRenderCostEstimate.narrationDrivenUSD(
                    stack: shot.renderStack,
                    durationSeconds: driver.durationSeconds,
                    pricing: falPricing
                )
            ))
            failurePhase = "stripping_provider_audio"
            artifact.progressText = "FINALIZING SILENT PICTURE"
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)
            let durableURL = proofDirectory.appendingPathComponent(
                "shot_render_\(safeIdentifier(shot.shotId))_\(shortHash(now, length: 10)).mp4"
            )
            _ = try await VideoChainMedia.stripAudio(
                videoURL: result.outputURL,
                outputURL: durableURL
            )
            let visualSeconds = try await VideoChainMedia.videoDurationSeconds(
                videoURL: durableURL
            )
            artifact.status = "ready"
            artifact.videoPath = durableURL.path
            artifact.clipPaths = [durableURL.path]
            artifact.totalSeconds = Int(visualSeconds.rounded())
            artifact.progressText = "READY"
            artifact.errorMessage = ""
            artifact.upsertSegmentClip(ShotRenderSegmentClip(
                startFrameImageId: anchorFrame.imageId,
                endFrameImageId: "",
                placementStartEntryId: anchorEntry.entryId,
                placementEndEntryId: "",
                clipPath: durableURL.path,
                requestId: requestId,
                prompt: promptUsed,
                provider: VideoProviderSelection.falAudioToVideo.rawValue,
                model: VideoModelSelection.falLTX23AudioToVideo.providerModelId,
                traceId: result.traceId,
                generateAudio: false,
                resolution: result.providerNativeSize,
                requestedDurationSeconds: Int(driver.durationSeconds.rounded()),
                durationSeconds: visualSeconds,
                updatedAt: DateFormats.now()
            ))
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)
            sweepStalePinnedCuts(shotId: shot.shotId, for: project)
            aestheticStatus = "LTX 2.3 narration-driven Shot ready"
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            if let liveShot = shotTimeline.shots.first(where: { $0.shotId == shot.shotId }),
               let liveArtifact = liveShot.renderVersions.first(where: {
                   $0.versionId == artifact.versionId
               }) {
                artifact.requestIds = Array(
                    Set(artifact.requestIds + liveArtifact.requestIds)
                ).sorted()
            }
            artifact.status = "failed"
            artifact.progressText = ""
            artifact.errorMessage = shotRenderFailureSummary(
                error,
                phase: failurePhase,
                limit: 300
            )
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shot.shotId, for: project)
            let requestId = artifact.requestIds.last ?? "-"
            logGeneration(
                kind: "video.error",
                message: "[fal_ltx_audio_to_video] error: \(shortSummaryText(error.localizedDescription, limit: 180)) request_id=\(requestId) duration_ms=\(Int(Date().timeIntervalSince(renderStartedAt) * 1000)) status_code=0"
            )
            if !(Task.isCancelled || isCancellationLikeError(error)) {
                recordSpend(SpendLedgerEntry(
                    kind: "shot_render_narration_driven",
                    provider: VideoProviderSelection.falAudioToVideo.rawValue,
                    model: VideoModelSelection.falLTX23AudioToVideo.providerModelId,
                    requestId: (error as? FALWorkflowFailure)?.jobId
                        ?? artifact.requestIds.last ?? "",
                    contextLabel: spendContextLabel(shotId: shot.shotId),
                    shotId: shot.shotId,
                    status: "failed_unknown_charge"
                ))
            }
            aestheticStatus = Task.isCancelled
                ? "LTX 2.3 render cancelled"
                : artifact.errorMessage
            return false
        }
    }

    /// Renders a shot as keyframe-interpolated video: N ready frames → N−1
    /// segments (adjacent pairs as start+end keyframes; a single frame renders
    /// one open-ended clip), stitched into one mp4. Progress persists per
    /// segment; the artifact records exactly what ran, including durable
    /// per-segment clips. With `onlySegmentKeys` (placement keys for new
    /// records; legacy image-pair keys remain readable), only those segments generate; the rest reuse
    /// the active version's saved clips when available and render otherwise —
    /// the result is a new render version either way.
    @discardableResult
    func renderShot(shotId: String, onlySegmentKeys: Set<String>? = nil) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard activeShotRenderId.isEmpty, activeShotJoinRenderId.isEmpty, activeShotRestyleId.isEmpty else {
            aestheticStatus = "Another video render is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            aestheticStatus = "Shot not found"
            return false
        }
        let defaultStack = shot.renderStack

        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        if defaultStack.isNarrationDriven {
            return await renderNarrationDrivenShot(
                project: project,
                shot: shot,
                frameLookup: frameLookup,
                onlySegmentKeys: onlySegmentKeys
            )
        }
        let mediaLookup = Dictionary(
            items.map { ($0.mediaId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let plan = shotRenderSegmentPlan(
            shot: shot,
            frameLookup: frameLookup,
            mediaLookup: mediaLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )
        guard !plan.segments.isEmpty else {
            aestheticStatus = "This shot has no ready frames or footage to render"
            return false
        }
        let profile = VideoOutputProfile.standard(.landscape16x9, fitPolicy: .fitWithBlurFill)
        let planKeys: Set<String> = Set(plan.segments.compactMap { segment -> String? in
            switch segment {
            case .generated(let item): return item.pair.placementKey
            case .footage(let footage): return footage.placementKey
            // Never in plan-generator output (assembly-only fallback band).
            case .artifactFallback: return nil
            }
        })
        var acceptedPlanKeys = planKeys
        for segment in plan.segments {
            switch segment {
            case .generated(let item):
                acceptedPlanKeys.insert(item.pair.segmentKey)
            case .footage(let footage):
                acceptedPlanKeys.insert(footage.clip.footageKey)
            // Never in plan-generator output (assembly-only fallback band).
            case .artifactFallback:
                break
            }
        }
        if let filter = onlySegmentKeys {
            guard filter.contains(where: acceptedPlanKeys.contains) else {
                aestheticStatus = "That segment no longer exists — re-render the shot instead"
                return false
            }
        }

        var reuseArtifact = shot.activeRenderVersion ?? ShotRenderArtifact()
        for seed in shot.seedSegmentClips {
            reuseArtifact.upsertSegmentClip(seed)
        }
        let implicitCombinedFilter: Set<String>? = shot.seedSegmentClips.isEmpty
            ? nil
            : Set(planKeys.filter { key in
                !reuseArtifact.segmentClips.contains {
                    $0.placementKey == key
                        && FileManager.default.fileExists(atPath: $0.clipPath)
                }
            })
        let effectiveSegmentFilter = onlySegmentKeys ?? implicitCombinedFilter

        let decisions = shotSegmentRenderDecisions(
            items: plan.generatedItems,
            onlySegmentKeys: effectiveSegmentFilter,
            reuseSource: effectiveSegmentFilter == nil ? nil : reuseArtifact,
            fileExists: { FileManager.default.fileExists(atPath: $0) }
        )
        let stacksToGenerate = zip(plan.generatedItems, decisions).compactMap { item, decision in
            if case .generate = decision { return item.renderStack }
            return nil
        }
        // A lead-in on a stack with no tail-anchored model is refused HERE —
        // before the artifact exists and before any paid request — never
        // silently rendered with a substitute.
        let unrenderableLeadIns = zip(plan.generatedItems, decisions).filter { item, decision in
            guard case .generate = decision else { return false }
            return item.renderStack.modelSelection(for: item.pair) == nil
        }
        guard unrenderableLeadIns.isEmpty else {
            let labels = Set(unrenderableLeadIns.map(\.0.renderStack.model.label)).sorted().joined(separator: ", ")
            aestheticStatus = "\(labels) can't render an AI lead-in — it needs a model that accepts a tail frame alone"
            return false
        }
        // LTX 2.3 Narration is a WHOLE-SHOT model (one narration-driven clip;
        // the dispatch above routes it only when it is the Shot DEFAULT). A
        // per-segment override of it reaching this loop would hit the
        // provider with no narration driver and fail AFTER minting a
        // generating version — refuse it here instead, same law as lead-ins.
        let narrationDrivenOverrides = zip(plan.generatedItems, decisions).contains { item, decision in
            guard case .generate = decision else { return false }
            return item.renderStack.isNarrationDriven
        }
        guard !narrationDrivenOverrides else {
            aestheticStatus = "LTX 2.3 Narration renders one clip for the WHOLE shot — set it as the Shot default (with a ready ElevenLabs narration), not a per-segment override"
            return false
        }
        let invalidNativeExtends = zip(plan.generatedItems, decisions).filter { item, decision in
            guard case .generate = decision,
                  item.renderStack.isNativeFootageExtend else { return false }
            return !item.canUseNativeFootageExtend
        }
        guard invalidNativeExtends.isEmpty else {
            aestheticStatus = "LTX Native Extend needs an AI extension directly after at least 73 frames of placed footage — choose Out-frame or repair the source range"
            return false
        }
        let modelsToGenerate: [VideoModelSelection] = zip(plan.generatedItems, decisions).compactMap { item, decision in
            guard case .generate = decision else { return nil }
            return item.renderStack.modelSelection(for: item.pair)
        }

        // Preflight every provider used by the actual generation subset before
        // the first paid request. Reused clips carry their original provider
        // provenance and require no current credential.
        for stack in Set(stacksToGenerate) {
            if stack.isNativeFootageExtend {
                guard canExecuteShotRenderModel(.ltx23NativeExtend) else {
                    aestheticStatus = "Configure the LTX API key in App Settings before rendering Native Extend"
                    return false
                }
                continue
            }
            let capability = VideoProviderCapability.capability(
                for: stack.providerSelection,
                outputProfile: profile,
                durationSeconds: stack.segmentSeconds,
                credentialStore: videoCredentialStore
            )
            guard capability.canRender else {
                aestheticStatus = "Configure \(stack.model.label) in App Settings before rendering this Shot"
                return false
            }
        }
        let skippedNote = plan.skipped.isEmpty
            ? ""
            : " · skipped \(plan.skipped.count) not-ready item\(plan.skipped.count == 1 ? "" : "s")"

        activeShotRenderId = shotId
        defer { activeShotRenderId = "" }

        let now = DateFormats.now()
        var artifact = ShotRenderArtifact(
            versionId: "shotrender_\(shortHash("\(project.projectId):\(shotId):\(now)", length: 14))",
            versionNumber: (shot.renderVersions.map(\.versionNumber).max() ?? 0) + 1,
            stack: defaultStack.rawValue,
            provider: Set(stacksToGenerate.map(\.providerSelection)).count > 1
                ? "mixed"
                : (stacksToGenerate.first?.providerSelection.rawValue ?? "local"),
            model: Set(modelsToGenerate).count > 1
                ? "mixed"
                : (modelsToGenerate.first?.providerModelId ?? "local"),
            status: "generating",
            segmentCount: plan.segments.count,
            progressText: "PREPARING PLATES",
            // The suffix watermark: entries this render covers. Structure
            // edits are refused mid-flight, so start == end of render.
            renderedEntryIds: shot.entries.map(\.entryId),
            generatedAt: now,
            updatedAt: now
        )
        persistShotRenderVersion(artifact, shotId: shotId, for: project)
        aestheticStatus = "Rendering \(shot.name.trimmed.isEmpty ? "shot" : shot.name) with \(defaultStack.shortLabel) defaults"

        let workDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("shot_render_\(safeIdentifier(shotId))_\(shortHash(now, length: 8))", isDirectory: true)
        var failurePhase = "preparing"

        do {
            try ensureDirectory(workDirectory)
            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))

            // Footage boundary endpoints resolve to REAL stills extracted
            // from the placed clip; every other keyframe normalizes its own
            // imagePath as always.
            var footageByBoundaryId: [String: (clip: ShotFootageClip, seconds: Double)] = [:]
            for case .footage(let segment) in plan.segments {
                let clip = segment.clip
                let ids = clip.boundaryFrameIds
                footageByBoundaryId[ids.start] = (clip, clip.resolvedStartSeconds + 0.02)
                footageByBoundaryId[ids.end] = (
                    clip,
                    max(clip.resolvedEndSeconds - (1.0 / 24.0), clip.resolvedStartSeconds)
                )
            }

            // Normalize each distinct keyframe once.
            var normalizedByImageId: [String: URL] = [:]
            func normalizedFrame(_ frame: ProjectLensHeroImage) async throws -> URL {
                if let url = normalizedByImageId[frame.imageId] { return url }
                let sourceURL: URL
                if let boundary = footageByBoundaryId[frame.imageId] {
                    let stillURL = workDirectory.appendingPathComponent(
                        "footage_boundary_\(shortHash(frame.imageId, length: 16)).png"
                    )
                    let source = sources.first { $0.sourceId == boundary.clip.sourceId }
                    _ = try await store.withSourceAccess(source) {
                        try await VideoChainMedia.extractFrameStill(
                            videoURL: URL(fileURLWithPath: boundary.clip.path),
                            atSeconds: boundary.seconds,
                            outputURL: stillURL
                        )
                    }
                    sourceURL = stillURL
                } else {
                    sourceURL = URL(fileURLWithPath: frame.imagePath)
                }
                let url = try VideoChainMedia.normalizeImageFrame(
                    sourceURL: sourceURL,
                    outputURL: workDirectory.appendingPathComponent("keyframe_\(shortHash(frame.imageId, length: 16)).png"),
                    profile: profile,
                    fitPolicy: .fitWithBlurFill
                )
                normalizedByImageId[frame.imageId] = url
                return url
            }

            let registry = VideoProviderRegistry(credentialStore: videoCredentialStore)
            let proofDirectory = contextStore.aestheticProofDirectory(for: project)
            var clipURLs: [URL] = []
            /// Exact durable placed ranges keyed by entry id. A following
            /// Native Extend consumes this file, never the original asset or
            /// an unrelated clip placement.
            var durableFootageByEntryId: [String: URL] = [:]
            // Seam-aware duplicate-frame trims for the stitcher: generated
            // segments always start on an anchor their predecessor ended on
            // (3); footage keeps every real frame unless a bridge arrives on
            // its first frame (joinsPrevious). Index 0 is never trimmed.
            var clipTrimFrames: [Int] = []
            let totalSegmentCount = plan.segments.count

            for segment in plan.segments {
                try Task.checkCancellation()

                if case .footage(let footageSegment) = segment {
                    let clip = footageSegment.clip
                    let displayOrdinal = footageSegment.displayIndex + 1
                    failurePhase = "footage_segment_\(displayOrdinal)"

                    // Reuse only under a partial-render filter, mirroring
                    // generated segments: not-in-filter + saved clip on disk.
                    if let filter = effectiveSegmentFilter,
                       !filter.contains(footageSegment.placementKey),
                       !filter.contains(clip.footageKey),
                       let saved = reuseArtifact.segmentClip(
                           placementStartEntryId: clip.entryId,
                           placementEndEntryId: "",
                           forStart: clip.footageKey,
                           end: ""
                       ),
                       FileManager.default.fileExists(atPath: saved.clipPath) {
                        artifact.progressText = "REUSING FOOTAGE \(displayOrdinal) OF \(totalSegmentCount)"
                        artifact.updatedAt = DateFormats.now()
                        let savedURL = URL(fileURLWithPath: saved.clipPath)
                        clipURLs.append(savedURL)
                        durableFootageByEntryId[clip.entryId] = savedURL
                        clipTrimFrames.append(footageSegment.joinsPrevious ? 3 : 0)
                        artifact.clipPaths.append(saved.clipPath)
                        artifact.upsertSegmentClip(saved)
                        persistShotRenderVersion(artifact, shotId: shotId, for: project)
                        continue
                    }

                    artifact.progressText = "PLACING FOOTAGE \(displayOrdinal) OF \(totalSegmentCount)"
                    artifact.updatedAt = DateFormats.now()
                    persistShotRenderVersion(artifact, shotId: shotId, for: project)

                    guard FileManager.default.fileExists(atPath: clip.path) else {
                        throw ScreenGraphError.capture("Footage file is missing: \(clip.filename)")
                    }
                    let durableExtension = clip.hasSubRange
                        ? "mp4"
                        : (URL(fileURLWithPath: clip.path).pathExtension.trimmed.nilIfEmpty ?? "mp4")
                    let durableURL = proofDirectory.appendingPathComponent(
                        "shot_clip_\(safeIdentifier(shotId))_\(shortHash("\(clip.footageKey):\(now):\(footageSegment.displayIndex)", length: 10)).\(durableExtension)"
                    )
                    try? FileManager.default.removeItem(at: durableURL)
                    let source = sources.first { $0.sourceId == clip.sourceId }
                    if clip.hasSubRange {
                        _ = try await store.withSourceAccess(source) {
                            try await VideoChainMedia.extractTimeRange(
                                videoURL: URL(fileURLWithPath: clip.path),
                                outputURL: durableURL,
                                startSeconds: clip.resolvedStartSeconds,
                                durationSeconds: max(clip.resolvedDurationSeconds, 0.1)
                            )
                        }
                    } else {
                        try await store.withSourceAccess(source) {
                            try FileManager.default.copyItem(at: URL(fileURLWithPath: clip.path), to: durableURL)
                        }
                    }
                    logGeneration(
                        kind: "video.completed",
                        message: "Shot render footage segment \(displayOrdinal)/\(totalSegmentCount) shot_id=\(shotId) media_id=\(clip.mediaId) duration_s=\(String(format: "%.2f", clip.resolvedDurationSeconds))"
                    )
                    clipURLs.append(durableURL)
                    durableFootageByEntryId[clip.entryId] = durableURL
                    clipTrimFrames.append(footageSegment.joinsPrevious ? 3 : 0)
                    artifact.clipPaths.append(durableURL.path)
                    artifact.upsertSegmentClip(ShotRenderSegmentClip(
                        startFrameImageId: clip.footageKey,
                        endFrameImageId: "",
                        placementStartEntryId: clip.entryId,
                        placementEndEntryId: "",
                        clipPath: durableURL.path,
                        requestId: "",
                        prompt: "",
                        provider: "footage",
                        model: "source",
                        requestedDurationSeconds: 0,
                        durationSeconds: (try? await VideoChainMedia.videoDurationSeconds(videoURL: durableURL))
                            ?? clip.resolvedDurationSeconds,
                        updatedAt: DateFormats.now()
                    ))
                    persistShotRenderVersion(artifact, shotId: shotId, for: project)
                    continue
                }

                guard case .generated(let item) = segment else { continue }
                let index = item.index
                let displayOrdinal = item.displayIndex + 1
                let pair = item.pair
                let renderStack = item.renderStack
                failurePhase = "generated_segment_\(displayOrdinal)"

                if case .reuse(let clip) = decisions[index] {
                    artifact.progressText = "REUSING SEGMENT \(displayOrdinal) OF \(totalSegmentCount)"
                    artifact.updatedAt = DateFormats.now()
                    clipURLs.append(URL(fileURLWithPath: clip.clipPath))
                    let resetsHandoff = shot.sourceBoundaries.contains {
                        $0.rightEntryId == item.pair.startPlacementEntryId
                    }
                    clipTrimFrames.append(resetsHandoff ? 0 : 3)
                    artifact.clipPaths.append(clip.clipPath)
                    // The record travels verbatim: it describes when/how the
                    // clip was actually made. Its provider job stays off this
                    // version's requestIds.
                    artifact.upsertSegmentClip(clip)
                    persistShotRenderVersion(artifact, shotId: shotId, for: project)
                    continue
                }

                artifact.progressText = "SEGMENT \(displayOrdinal) OF \(totalSegmentCount)"
                artifact.updatedAt = DateFormats.now()
                persistShotRenderVersion(artifact, shotId: shotId, for: project)

                guard let modelSelection = renderStack.modelSelection(for: pair) else {
                    // Unreachable: the lead-in capability preflight refused
                    // before the artifact was created.
                    throw ScreenGraphError.capture("\(renderStack.model.label) has no model for this segment shape.")
                }
                let provider = registry.provider(for: renderStack.providerSelection)
                let clipURL = workDirectory.appendingPathComponent("clip_\(index).mp4")
                var startURL: URL?
                if !renderStack.isNativeFootageExtend, let startFrame = pair.start {
                    startURL = try await normalizedFrame(startFrame)
                }
                var endURL: URL?
                if !renderStack.isNativeFootageExtend, let endFrame = pair.end {
                    endURL = try await normalizedFrame(endFrame)
                }
                // The mode-flag law: a beats-mode plan renders its compiled
                // direction (flat override ignored); raw renders exactly the
                // classic override ?? generated path.
                let compiledDirection = item.compiledDirection
                let promptUsed = item.effectivePrompt
                logGeneration(
                    kind: "video.start",
                    message: "Shot render segment \(displayOrdinal)/\(totalSegmentCount) shot_id=\(shotId) stack=\(renderStack.rawValue) model=\(modelSelection.rawValue) duration_s=\(renderStack.segmentSeconds)\(compiledDirection.map { " direction=\($0.dialect)" } ?? "")"
                )
                let segmentStartedAt = Date()
                let result: VideoClipResult
                var nativeSourceClip: ShotFootageClip?
                do {
                    if renderStack.isNativeFootageExtend {
                        guard let sourceClip = item.nativeExtendSourceClip,
                              let sourceURL = durableFootageByEntryId[sourceClip.entryId],
                              let contextSeconds = item.nativeExtendContextSeconds,
                              let ltxProvider = provider as? LTXDirectVideoProvider else {
                            throw ScreenGraphError.capture(
                                "LTX Native Extend lost its placed footage source — choose Out-frame or reopen the extension review."
                            )
                        }
                        nativeSourceClip = sourceClip
                        let normalizedSourceURL = workDirectory.appendingPathComponent(
                            "native_extend_source_\(shortHash(item.pair.placementKey, length: 12)).mp4"
                        )
                        _ = try await VideoChainMedia.stitchClips(
                            clipURLs: [sourceURL],
                            outputURL: normalizedSourceURL,
                            workDirectory: workDirectory.appendingPathComponent(
                                "native_extend_normalize_\(shortHash(item.pair.placementKey, length: 10))",
                                isDirectory: true
                            ),
                            profile: profile,
                            trimDuplicateStartFrames: 0,
                            perClipTrimFrames: [0]
                        )
                        let providerOutputURL = workDirectory.appendingPathComponent("clip_\(index)_ltx_full.mp4")
                        let segmentId = "\(artifact.versionId)_seg_\(index)"
                        let renderVersionId = artifact.versionId
                        result = try await ltxProvider.generateExtension(
                            from: VideoClipExtendRequest(
                                chainId: "shot_render_\(shotId)",
                                segmentId: segmentId,
                                modelSelection: modelSelection,
                                prompt: promptUsed,
                                durationSeconds: renderStack.segmentSeconds,
                                contextSeconds: contextSeconds,
                                sourceVideoURL: normalizedSourceURL,
                                sourceKind: "shot_footage_range",
                                sourceMediaId: sourceClip.mediaId,
                                sourceStartSeconds: sourceClip.resolvedStartSeconds,
                                sourceEndSeconds: sourceClip.resolvedEndSeconds,
                                outputURL: providerOutputURL,
                                projectId: project.projectId,
                                runId: renderVersionId,
                                traceGroupId: renderVersionId,
                                workflowName: "shot_render",
                                artifactType: "shot_render_segment",
                                onProviderSubmitted: { [weak self] jobId, traceId in
                                    self?.persistSubmittedShotRenderJob(
                                        shotId: shotId,
                                        versionId: renderVersionId,
                                        jobId: jobId,
                                        traceId: traceId,
                                        project: project
                                    )
                                }
                            )
                        )
                        _ = try await VideoChainMedia.extractTailSegment(
                            videoURL: result.outputURL,
                            outputURL: clipURL,
                            durationSeconds: Double(renderStack.segmentSeconds)
                        )
                    } else {
                        result = try await provider.generateClip(from: VideoClipRequest(
                            chainId: "shot_render_\(shotId)",
                            segmentId: "\(artifact.versionId)_seg_\(index)",
                            modelSelection: modelSelection,
                            prompt: promptUsed,
                            negativePrompt: "text artifacts, captions, logos, extra limbs, warped anatomy, hard cuts, flicker, melting faces",
                            durationSeconds: renderStack.segmentSeconds,
                            multiShotPrompts: compiledDirection?.klingShots,
                            promptIsStructured: compiledDirection != nil,
                            outputProfile: profile,
                            startFrameURL: startURL,
                            targetEndFrameURL: endURL,
                            outputURL: clipURL,
                            generateAudio: renderStack.generateAudio,
                            projectId: project.projectId,
                            runId: artifact.versionId,
                            traceGroupId: artifact.versionId,
                            workflowName: "shot_render",
                            artifactType: "shot_render_segment"
                        ))
                    }
                } catch {
                    if !(Task.isCancelled || isCancellationLikeError(error)) {
                        logGeneration(
                            kind: "video.error",
                            message: "Shot render segment \(displayOrdinal)/\(totalSegmentCount) failed shot_id=\(shotId): \(shortSummaryText(error.localizedDescription, limit: 200))"
                        )
                        let submittedRequestId = (error as? FALWorkflowFailure)?.jobId.trimmed.nilIfEmpty
                            ?? shotTimeline.shots
                                .first(where: { $0.shotId == shotId })?
                                .renderVersions
                                .first(where: { $0.versionId == artifact.versionId })?
                                .requestIds.last
                            ?? ""
                        recordSpend(SpendLedgerEntry(
                            kind: "shot_render_segment",
                            provider: renderStack.providerSelection.rawValue,
                            model: modelSelection.providerModelId,
                            requestId: submittedRequestId,
                            contextLabel: spendContextLabel(shotId: shotId),
                            shotId: shotId,
                            unit: "seconds",
                            unitCount: Double(renderStack.segmentSeconds),
                            status: "failed_unknown_charge"
                        ))
                    }
                    throw error
                }
                let segmentDurationMs = Int(Date().timeIntervalSince(segmentStartedAt) * 1000)
                let segmentJobId = result.providerJobId.trimmed.nilIfEmpty ?? result.providerVideoId.trimmed
                logGeneration(
                    kind: "video.completed",
                    message: "Shot render segment \(displayOrdinal)/\(totalSegmentCount) shot_id=\(shotId) stack=\(renderStack.rawValue) audio=\(renderStack.generateAudio) duration_ms=\(segmentDurationMs) request_id=\(segmentJobId.isEmpty ? "-" : segmentJobId)"
                )
                recordSpend(SpendLedgerEntry(
                    kind: "shot_render_segment",
                    provider: result.providerId.rawValue,
                    model: modelSelection.providerModelId,
                    requestId: segmentJobId,
                    traceId: result.traceId,
                    contextLabel: spendContextLabel(shotId: shotId),
                    shotId: shotId,
                    unit: "seconds",
                    unitCount: Double(renderStack.segmentSeconds)
                        + (renderStack.isNativeFootageExtend ? (item.nativeExtendContextSeconds ?? 0) : 0),
                    estimatedUSD: ShotRenderCostEstimate.segmentUSD(item: item, pricing: falPricing)
                ))
                failurePhase = "persisting_segment_\(displayOrdinal)"

                // Keep the clip durable so a later render can reuse it. The
                // index disambiguates duplicate pairs (`now` is per-render).
                let durableURL = proofDirectory.appendingPathComponent(
                    "shot_clip_\(safeIdentifier(shotId))_\(shortHash("\(pair.placementKey):\(now):\(index)", length: 10)).mp4"
                )
                try? FileManager.default.removeItem(at: durableURL)
                let segmentOutputURL = renderStack.isNativeFootageExtend ? clipURL : result.outputURL
                try FileManager.default.copyItem(at: segmentOutputURL, to: durableURL)

                clipURLs.append(durableURL)
                let resetsHandoff = shot.sourceBoundaries.contains {
                    $0.rightEntryId == pair.startPlacementEntryId
                }
                clipTrimFrames.append(resetsHandoff ? 0 : 3)
                artifact.clipPaths.append(durableURL.path)
                let requestId = result.providerJobId.trimmed.nilIfEmpty ?? result.providerVideoId.trimmed
                if !requestId.isEmpty {
                    artifact.requestIds.append(requestId)
                }
                artifact.upsertSegmentClip(ShotRenderSegmentClip(
                    startFrameImageId: pair.start?.imageId ?? "",
                    endFrameImageId: pair.end?.imageId ?? "",
                    placementStartEntryId: pair.startPlacementEntryId,
                    placementEndEntryId: pair.endPlacementEntryId,
                    clipPath: durableURL.path,
                    requestId: requestId,
                    prompt: promptUsed,
                    provider: result.providerId.rawValue,
                    model: modelSelection.providerModelId,
                    providerOperation: result.providerOperation,
                    traceId: result.traceId,
                    generateAudio: renderStack.generateAudio,
                    resolution: renderStack.isNativeFootageExtend
                        ? "\(profile.width)x\(profile.height)"
                        : (result.responseSnapshot["resolution"] ?? ""),
                    requestedDurationSeconds: renderStack.segmentSeconds,
                    durationSeconds: (try? await VideoChainMedia.videoDurationSeconds(videoURL: durableURL))
                        ?? Double(renderStack.segmentSeconds),
                    sourceMediaId: nativeSourceClip?.mediaId ?? "",
                    sourceRangeStartSeconds: nativeSourceClip?.resolvedStartSeconds ?? 0,
                    sourceRangeEndSeconds: nativeSourceClip?.resolvedEndSeconds ?? 0,
                    sourceFingerprint: result.responseSnapshot["source_video_sha256"] ?? "",
                    directionPlan: compiledDirection != nil ? item.directionPlan?.plan : nil,
                    compiledMultiShots: compiledDirection?.klingShots,
                    compiledDialect: compiledDirection?.dialect ?? "",
                    compilerVersion: compiledDirection?.compilerVersion ?? 0,
                    updatedAt: DateFormats.now()
                ))
                // Persist the paid record NOW — without this, segment N's
                // clip only reached disk when segment N+1 started, and a
                // crash during final assembly lost the last paid segment.
                persistShotRenderVersion(artifact, shotId: shotId, for: project)
            }

            guard currentProject?.projectId == project.projectId else { return false }
            failurePhase = "final_assembly"

            let hasFootageSegments = plan.segments.contains { segment in
                if case .footage = segment { return true }
                return false
            }
            let finalURL: URL
            if clipURLs.count == 1 && !hasFootageSegments {
                // A single generated clip IS the shot video (already at the
                // output profile); copy it out of the temp dir. Footage always
                // stitches so it gets normalized to the profile.
                let destination = contextStore.aestheticProofDirectory(for: project)
                    .appendingPathComponent("shot_render_\(safeIdentifier(shotId))_\(shortHash(now, length: 10)).mp4")
                try? FileManager.default.removeItem(at: destination)
                try FileManager.default.copyItem(at: clipURLs[0], to: destination)
                finalURL = destination
            } else {
                finalURL = try await VideoChainMedia.stitchClips(
                    clipURLs: clipURLs,
                    outputURL: contextStore.aestheticProofDirectory(for: project)
                        .appendingPathComponent("shot_render_\(safeIdentifier(shotId))_\(shortHash(now, length: 10)).mp4"),
                    workDirectory: workDirectory,
                    profile: profile,
                    trimDuplicateStartFrames: 3,
                    perClipTrimFrames: clipTrimFrames
                )
            }
            failurePhase = "final_artifact"

            let footageSeconds = plan.segments.reduce(0.0) { total, segment in
                if case .footage(let footageSegment) = segment {
                    return total + footageSegment.clip.resolvedDurationSeconds
                }
                return total
            }
            artifact.status = "ready"
            artifact.videoPath = finalURL.path
            let footageKeys = Set(plan.segments.compactMap { segment -> String? in
                guard case .footage(let footageSegment) = segment else { return nil }
                return footageSegment.clip.footageKey
            })
            // Pair identity, rather than the new provider field, also excludes
            // footage clips reused from legacy artifacts that predate per-clip
            // provenance.
            let generatedClips = artifact.segmentClips.filter {
                !footageKeys.contains($0.startFrameImageId)
            }
            let providers = Set(generatedClips.map(\.provider).filter { !$0.isEmpty })
            let models = Set(generatedClips.map(\.model).filter { !$0.isEmpty })
            let hasUnknownProvider = generatedClips.contains { $0.provider.isEmpty }
            let hasUnknownModel = generatedClips.contains { $0.model.isEmpty }
            artifact.provider = providers.isEmpty
                ? (generatedClips.isEmpty ? "local" : "legacy")
                : ((providers.count > 1 || hasUnknownProvider) ? "mixed" : (providers.first ?? "local"))
            artifact.model = models.isEmpty
                ? (generatedClips.isEmpty ? "local" : "legacy")
                : ((models.count > 1 || hasUnknownModel) ? "mixed" : (models.first ?? "local"))
            artifact.totalSeconds = Int(
                ((try? await VideoChainMedia.videoDurationSeconds(videoURL: finalURL))
                    ?? (generatedClips.reduce(0) { $0 + $1.durationSeconds } + footageSeconds)).rounded()
            )
            artifact.progressText = "READY\(skippedNote.uppercased())"
            artifact.errorMessage = ""
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shotId, for: project)
            sweepStalePinnedCuts(shotId: shotId, for: project)
            // The new version wrote new clip paths, so the old proxies are
            // orphans and a reversed shot needs a fresh set.
            sweepStaleReverseProxies(for: project)
            if shotTimeline.shots.first(where: { $0.shotId == shotId })?.cutList.isReversed == true {
                Task { await ensureReverseProxies(shotId: shotId) }
            }
            aestheticStatus = "Shot render ready"
            logGeneration(
                kind: "video.completed",
                message: "Shot render ready shot_id=\(shotId) segments=\(plan.segments.count) stack=\(defaultStack.rawValue) provider=\(artifact.provider) model=\(artifact.model)"
            )
            return true
        } catch {
            if Task.isCancelled || isCancellationLikeError(error) {
                // A cancelled render still persists as failed WITH its
                // completed segment clips — RESUME renders only the rest.
                // (A project switch skips the persist: writing through the
                // @Published timeline after a switch would hit the wrong
                // project; the open-time reconcile covers that case.)
                if currentProject?.projectId == project.projectId {
                    artifact = absorbingSubmittedShotRenderJobs(artifact, shotId: shotId)
                    artifact.status = "failed"
                    artifact.errorMessage = "Cancelled before completion"
                    artifact.progressText = ""
                    artifact.updatedAt = DateFormats.now()
                    persistShotRenderVersion(artifact, shotId: shotId, for: project)
                    aestheticStatus = artifact.segmentClips.isEmpty
                        ? "Shot render cancelled"
                        : "Shot render cancelled — finished segments kept, RESUME renders only the rest"
                }
                return false
            }
            guard currentProject?.projectId == project.projectId else { return false }
            let persistedError = shotRenderFailureSummary(error, phase: failurePhase, limit: 300)
            artifact = absorbingSubmittedShotRenderJobs(artifact, shotId: shotId)
            artifact.status = "failed"
            artifact.errorMessage = persistedError
            artifact.progressText = ""
            artifact.updatedAt = DateFormats.now()
            persistShotRenderVersion(artifact, shotId: shotId, for: project)
            aestheticStatus = artifact.segmentClips.isEmpty
                ? "Shot render failed"
                : "Shot render failed — finished segments kept, RESUME renders only the rest"
            logGeneration(
                kind: "video.error",
                message: "Shot render failed shot_id=\(shotId): \(shotRenderFailureSummary(error, phase: failurePhase, limit: 240))"
            )
            return false
        }
    }

    /// Renders that were mid-flight when the app quit can never complete;
    /// reconcile them to an honest failed state at project open.
    private func reconcileInterruptedShotRenders(for project: ProjectRecord) {
        var document = shotTimeline
        var changed = false
        var interruptedRenderCount = 0
        let now = DateFormats.now()
        for (index, shot) in document.shots.enumerated() {
            var updated = shot
            let reconciled = shot.failingInFlightRenderVersions(now: now)
            if reconciled.changed {
                updated = reconciled.shot
                changed = true
                interruptedRenderCount += 1
            }
            if var narration = shot.narrationArtifact, narration.status == "generating" {
                narration.status = "failed"
                narration.errorMessage = "Interrupted before completion"
                narration.updatedAt = now
                updated = updated.settingNarrationArtifact(narration, now: now)
                changed = true
            }
            document.shots[index] = updated
        }
        if changed {
            persistShotTimeline(document, for: project)
        }
        // The reconcile used to be silent — the only trace was a rail flip to
        // RETRY with the reason buried in a tooltip. Say what was kept.
        if interruptedRenderCount > 0 {
            aestheticStatus = interruptedRenderCount == 1
                ? "1 render was interrupted — its finished segments are kept; RESUME on the cut rail renders only the rest"
                : "\(interruptedRenderCount) renders were interrupted — their finished segments are kept; RESUME on the cut rail renders only the rest"
        }
    }

    // MARK: - Shot narration (meaning-message chips + voiced script per shot)

    /// Drafts the 3–5 meaning-message chips a shot's narration can start from.
    /// Fresh chips (fingerprint matches the current frame strip) are kept
    /// unless `force`; stale chips stay usable and are only marked in the UI.
    @discardableResult
    func generateShotNarrationChips(shotId: String, force: Bool = false) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard activeShotChipsId.isEmpty else {
            aestheticStatus = "Shot messages are already drafting"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            aestheticStatus = "Shot not found"
            return false
        }
        guard !shot.entries.isEmpty else {
            aestheticStatus = "Add frames to draft this shot's messages"
            return false
        }
        let fingerprint = shotEntriesFingerprint(shot)
        if !force,
           let chips = shot.narrationChips,
           !chips.statements.isEmpty,
           chips.entriesFingerprint == fingerprint {
            return true
        }

        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let frameGists = shotNarrationFrameGists(shot: shot, frameLookup: frameLookup)
        guard !frameGists.isEmpty else {
            aestheticStatus = "This shot has no rendered frames to draw messages from"
            return false
        }
        let strands = deriveMeaningStrands(
            shots: [shot],
            frameLookup: frameLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )
        let strandLines = strands.map { strand in
            strand.detail.trimmed.isEmpty ? strand.label : "\(strand.label) — \(strand.detail.trimmed)"
        }
        let meaningNodeLines = lensContext.promptPacket().meaningNodes.prefix(10).map { node in
            node.definition.trimmed.isEmpty ? node.name : "\(node.name) — \(node.definition.trimmed)"
        }

        activeShotChipsId = shotId
        defer { activeShotChipsId = "" }
        aestheticStatus = "Drafting shot messages"
        let now = DateFormats.now()
        let runId = "shot_chips_\(shortHash("\(project.projectId):\(shotId):\(now)", length: 14))"
        do {
            let openAIClient = try OpenAIClient.fromEnvironment()
            let prompt = ShotNarrationComposer.chipsPrompt(
                shotName: shot.name,
                frameGists: frameGists,
                strandLines: strandLines,
                meaningNodeLines: Array(meaningNodeLines),
                brief: projectGoalV2.activeBrief
            )
            let draft = try await openAIClient.draftShotNarrationChips(
                prompt: prompt,
                projectId: project.projectId,
                runId: runId
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let persistedAt = DateFormats.now()
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: persistedAt) {
                    $0.settingNarrationChips(
                        ShotNarrationChipSet(
                            statements: draft.statements,
                            entriesFingerprint: fingerprint,
                            responseId: draft.responseId,
                            generatedAt: persistedAt
                        ),
                        now: persistedAt
                    )
                },
                for: project
            )
            aestheticStatus = "Shot messages ready"
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            aestheticStatus = "Shot messages failed"
            lastError = error.localizedDescription
            return false
        }
    }

    /// Drafts one segment's temporal direction plan with the LLM and persists
    /// it as an editable beats record (`source: "llm"`, pristine copy kept in
    /// `llmDraftPlan` for RESET). On-demand only; token-guarded per segment
    /// (cap 3, refuse-not-queue — the lens-take lane pattern); a fresh
    /// fingerprint short-circuits unless `force`. No pause gate and no spend
    /// ledger entry — OpenAI text calls are traced, not ledgered (the chips /
    /// form-transform precedent).
    @discardableResult
    func draftShotSegmentDirectionPlan(shotId: String, segmentKey: String, force: Bool = false) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        let laneKey = "\(shotId)|\(segmentKey)"
        guard !draftingDirectionSegmentKeys.contains(laneKey) else {
            aestheticStatus = "That segment's beats are already drafting"
            return false
        }
        guard draftingDirectionSegmentKeys.count < 3 else {
            aestheticStatus = "Three beat drafts are already running"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            aestheticStatus = "Shot not found"
            return false
        }
        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let mediaLookup = Dictionary(
            items.map { ($0.mediaId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let plan = shotRenderSegmentPlan(
            shot: shot,
            frameLookup: frameLookup,
            mediaLookup: mediaLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )
        guard let item = plan.generatedItems.first(where: {
            $0.pair.placementKey == segmentKey || $0.pair.segmentKey == segmentKey
        }) else {
            aestheticStatus = "Segment not found in this shot's plan"
            return false
        }
        let strandLines = plan.strands.map { strand in
            strand.detail.trimmed.isEmpty ? strand.label : "\(strand.label) — \(strand.detail.trimmed)"
        }
        let context = shotDirectionPlanDraftContext(
            shot: shot,
            pair: item.pair,
            segmentSeconds: item.renderStack.segmentSeconds,
            strandLines: strandLines
        )
        let fingerprint = shotDirectionPlanInputsFingerprint(context: context)
        if !force,
           let existing = item.directionPlan,
           existing.source == "llm",
           !existing.plan.isEmpty,
           existing.inputsFingerprint == fingerprint {
            return true
        }

        draftingDirectionSegmentKeys.insert(laneKey)
        directionDraftErrors[laneKey] = nil
        defer { draftingDirectionSegmentKeys.remove(laneKey) }
        aestheticStatus = "Drafting segment beats"
        let now = DateFormats.now()
        let runId = "shot_beats_\(shortHash("\(project.projectId):\(laneKey):\(now)", length: 14))"
        do {
            let openAIClient = try OpenAIClient.fromEnvironment()
            let draft = try await openAIClient.draftShotSegmentDirectionPlan(
                prompt: ShotDirectionPlanComposer.draftPrompt(context: context),
                projectId: project.projectId,
                runId: runId
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let draftedPlan = ShotTemporalDirectionPlan(
                shotMode: ShotTemporalShotMode(rawValue: draft.shotMode) ?? .continuous,
                beats: draft.beats.map {
                    ShotTemporalBeat(
                        durationWeight: Double($0.durationWeight),
                        action: $0.action,
                        camera: $0.camera
                    )
                }
            ).normalized()
            let persistedAt = DateFormats.now()
            let record = ShotSegmentDirectionPlanRecord(
                startFrameImageId: item.pair.start?.imageId ?? "",
                endFrameImageId: item.pair.end?.imageId ?? "",
                placementStartEntryId: item.pair.startPlacementEntryId,
                placementEndEntryId: item.pair.endPlacementEntryId,
                plan: draftedPlan,
                promptMode: ShotSegmentPromptMode.beats.rawValue,
                source: "llm",
                llmDraftPlan: draftedPlan,
                inputsFingerprint: fingerprint,
                responseId: draft.responseId,
                updatedAt: persistedAt
            )
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: persistedAt) { value in
                    value.settingSegmentDirectionPlans(
                        mergedAutosaveDirectionPlans(
                            existing: value.segmentDirectionPlans,
                            computed: [record]
                        ),
                        now: persistedAt
                    )
                },
                for: project
            )
            aestheticStatus = "Segment beats drafted"
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            aestheticStatus = "Beat drafting failed"
            lastError = error.localizedDescription
            directionDraftErrors[laneKey] = String(error.localizedDescription.prefix(160))
            return false
        }
    }

    /// Drafts beats for every generated segment of a shot, sequentially,
    /// skipping fresh plans. One batch at a time, refuse-not-queue. Returns
    /// the number of segments drafted.
    @discardableResult
    func draftAllShotSegmentDirectionPlans(shotId: String) async -> Int {
        guard activeDirectionDraftBatchShotId.isEmpty else {
            aestheticStatus = "A beat-draft batch is already running"
            return 0
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            aestheticStatus = "Shot not found"
            return 0
        }
        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let mediaLookup = Dictionary(
            items.map { ($0.mediaId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let plan = shotRenderSegmentPlan(
            shot: shot,
            frameLookup: frameLookup,
            mediaLookup: mediaLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )
        activeDirectionDraftBatchShotId = shotId
        defer { activeDirectionDraftBatchShotId = "" }
        var drafted = 0
        for item in plan.generatedItems {
            if await draftShotSegmentDirectionPlan(shotId: shotId, segmentKey: item.pair.placementKey) {
                drafted += 1
            }
        }
        return drafted
    }

    /// Voices a shot's narration: the SPOKEN text is the meaning-message title
    /// followed by a freshly drafted duration-scaled body (title alone when no
    /// OpenAI key or the draft fails), or the user's inline edit via
    /// `scriptOverride` verbatim. The drafted body is recorded in `bodyText`;
    /// every voiced script appends to `titleVersions`. Playback overlays the
    /// shot video non-destructively — the rendered mp4 is never touched.
    @discardableResult
    func startShotNarration(
        shotId: String,
        messagingText: String,
        voicePresetId: String,
        scriptOverride: String? = nil
    ) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard activeShotNarrationId.isEmpty, activeShotNarrationSpeedId.isEmpty else {
            aestheticStatus = "Shot narration is already running"
            return false
        }
        guard !isGenerationPaused else {
            aestheticStatus = "Generation is paused — resume to continue"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let lens = projectLenses.lenses.first else {
            aestheticStatus = "Shot not found"
            return false
        }
        guard !shot.entries.isEmpty else {
            aestheticStatus = "Add frames before narrating this shot"
            return false
        }
        let messaging = messagingText.trimmed
        guard !messaging.isEmpty else {
            aestheticStatus = "Pick a meaning message before narrating"
            return false
        }
        guard ElevenLabsSettingsStore.hasResolvedAPIKey() else {
            aestheticStatus = "Add an ElevenLabs API key in App Settings before narrating"
            lastError = aestheticStatus
            return false
        }
        let voiceOption = StoryAudioVoiceCatalog.option(
            for: voicePresetId,
            customVoiceId: ElevenLabsSettingsStore.resolvedCustomVoiceId(),
            extraVoices: accountVoiceOptions
        )
        guard let resolvedVoiceId = voiceOption.voiceId?.trimmed.nilIfEmpty else {
            aestheticStatus = "Select Archer/Lucy or configure Custom Voice ID before narrating"
            lastError = aestheticStatus
            return false
        }
        let speechModelId = ElevenLabsSpeechModels.defaultModelId
        let retainedVoiceSpeed = shot.narrationArtifact?.effectiveVoiceSpeed
            ?? StoryAudioVoiceCatalog.defaultSpeed

        let frameLookup = Dictionary(
            lens.sortedHeroImages.map { ($0.imageId, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        let frameGists = shotNarrationFrameGists(shot: shot, frameLookup: frameLookup)
        // Gists only feed the body draft — verbatim text (THE QUICK SUBMIT)
        // needs no frames, so footage-only and not-yet-framed shots can still
        // author the narration that drives an LTX render.
        if scriptOverride == nil {
            guard !frameGists.isEmpty else {
                aestheticStatus = "This shot has no rendered frames to narrate"
                return false
            }
        }
        let strands = deriveMeaningStrands(
            shots: [shot],
            frameLookup: frameLookup,
            meaningNodes: lensContext.promptPacket().meaningNodes
        )

        activeShotNarrationId = shotId
        defer { activeShotNarrationId = "" }

        let now = DateFormats.now()
        persistShotTimeline(
            shotTimeline.updatingShot(shotId: shotId, now: now) {
                $0.settingNarrationArtifact(
                    ShotNarrationArtifact(
                        model: speechModelId,
                        status: "generating",
                        messagingText: messaging,
                        audioPath: shot.narrationArtifact?.audioPath ?? "",
                        sourceAudioPath: shot.narrationArtifact?.sourceAudioPath ?? "",
                        script: shot.narrationArtifact?.script ?? "",
                        bodyText: shot.narrationArtifact?.bodyText ?? "",
                        titleVersions: shot.narrationArtifact?.titleVersions ?? [],
                        voicePresetId: voiceOption.id,
                        voiceName: voiceOption.name,
                        voiceId: resolvedVoiceId,
                        durationSeconds: shot.narrationArtifact?.durationSeconds ?? 0,
                        sourceDurationSeconds: shot.narrationArtifact?.sourceDurationSeconds ?? 0,
                        voiceSpeed: retainedVoiceSpeed,
                        audioProcessor: shot.narrationArtifact?.audioProcessor ?? "",
                        updatedAt: now
                    ),
                    now: now
                )
            },
            for: project
        )
        aestheticStatus = "Narrating shot"

        let runId = "shot_narration_\(shortHash("\(project.projectId):\(shotId):\(now)", length: 14))"
        do {
            // The spoken text is the thesis title followed by a body drafted
            // in THIS run (a stale body may serve a different chip's thesis);
            // a user edit via `scriptOverride` is voiced verbatim instead.
            var draftedBody = ""
            var bodyResponseId = ""
            var bodyTraceId = ""
            if scriptOverride == nil, let openAIClient = try? OpenAIClient.fromEnvironment() {
                // Body drafting is best-effort — no key or a failed draft
                // never blocks the voice; the title alone is spoken.
                let renderReady = shot.renderArtifact?.status == "ready"
                let bodyPrompt = ShotNarrationComposer.scriptPrompt(
                    messaging: messaging,
                    shotName: shot.name,
                    frameGists: frameGists,
                    strandLabels: strands.filter { $0.kind == .meaning }.map(\.label),
                    brief: projectGoalV2.activeBrief,
                    targetSeconds: renderReady ? (shot.renderArtifact?.totalSeconds ?? 0) : 0
                )
                aestheticStatus = "Writing narration body"
                if let draft = try? await openAIClient.draftShotNarration(
                    prompt: bodyPrompt,
                    projectId: project.projectId,
                    runId: runId
                ) {
                    draftedBody = draft.script
                    bodyResponseId = draft.responseId
                    bodyTraceId = draft.traceId
                }
                guard currentProject?.projectId == project.projectId else { return false }
            }
            let spokenText = scriptOverride?.trimmed.nilIfEmpty
                ?? ShotNarrationComposer.spokenScript(title: messaging, body: draftedBody)
            // An override is voiced verbatim; the prior drafted body and its
            // provenance stay on record untouched.
            let bodyText = scriptOverride == nil ? draftedBody : (shot.narrationArtifact?.bodyText ?? "")
            if scriptOverride != nil {
                bodyResponseId = shot.narrationArtifact?.scriptResponseId ?? ""
                bodyTraceId = shot.narrationArtifact?.traceId ?? ""
            }

            var titleVersions = (shot.narrationArtifact?.titleVersions ?? [])
                .map { $0.trimmed }
                .filter { !$0.isEmpty }
            if titleVersions.last != spokenText {
                titleVersions.append(spokenText)
            }

            aestheticStatus = "Voicing shot narration"
            let elevenClient = ElevenLabsClient(apiKey: try ElevenLabsSettingsStore.resolvedAPIKeyOrThrow())
            let speech = try await elevenClient.createSpeech(
                voiceId: resolvedVoiceId,
                text: spokenText,
                modelId: speechModelId,
                projectId: project.projectId,
                runId: runId
            )
            guard currentProject?.projectId == project.projectId else { return false }
            recordSpend(SpendLedgerEntry(
                kind: "narration_tts",
                provider: "elevenlabs_tts",
                model: speechModelId,
                requestId: speech.requestId,
                contextLabel: spendContextLabel(shotId: shotId),
                shotId: shotId,
                unit: "characters",
                unitCount: Double(speech.characterCount) ?? 0,
                estimatedCredits: Double(speech.characterCost),
                pricingNote: "elevenlabs character-cost header"
            ))

            try ensureDirectory(contextStore.aestheticProofDirectory(for: project))
            let audioURL = contextStore.aestheticProofDirectory(for: project)
                .appendingPathComponent("\(runId)_\(safeIdentifier(shotId))_narration.mp3")
            try speech.data.write(to: audioURL, options: [.atomic])
            let duration = await lensNarrationDuration(url: audioURL)

            let readyAt = DateFormats.now()
            var readyNarration = ShotNarrationArtifact(
                model: speechModelId,
                status: "ready",
                messagingText: messaging,
                audioPath: audioURL.path,
                sourceAudioPath: audioURL.path,
                script: spokenText,
                bodyText: bodyText,
                titleVersions: titleVersions,
                voicePresetId: voiceOption.id,
                voiceName: voiceOption.name,
                voiceId: resolvedVoiceId,
                durationSeconds: duration,
                sourceDurationSeconds: duration,
                voiceSpeed: StoryAudioVoiceCatalog.defaultSpeed,
                scriptResponseId: bodyResponseId,
                requestId: speech.requestId,
                traceId: bodyTraceId,
                errorMessage: "",
                generatedAt: readyAt,
                updatedAt: readyAt
            )
            if abs(retainedVoiceSpeed - StoryAudioVoiceCatalog.defaultSpeed) > 0.001 {
                readyNarration = try await applyingShotNarrationSpeed(
                    readyNarration,
                    targetSpeed: retainedVoiceSpeed,
                    projectId: project.projectId
                )
            }
            guard currentProject?.projectId == project.projectId else { return false }
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: readyAt) {
                    $0.settingNarrationArtifact(readyNarration, now: readyAt)
                },
                for: project
            )
            aestheticStatus = "Shot narration ready"
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            let failedAt = DateFormats.now()
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: failedAt) {
                    $0.settingNarrationArtifact(
                        ShotNarrationArtifact(
                            model: speechModelId,
                            status: "failed",
                            messagingText: messaging,
                            audioPath: shot.narrationArtifact?.audioPath ?? "",
                            sourceAudioPath: shot.narrationArtifact?.sourceAudioPath ?? "",
                            script: shot.narrationArtifact?.script ?? "",
                            bodyText: shot.narrationArtifact?.bodyText ?? "",
                            titleVersions: shot.narrationArtifact?.titleVersions ?? [],
                            voicePresetId: voiceOption.id,
                            voiceName: voiceOption.name,
                            voiceId: resolvedVoiceId,
                            durationSeconds: shot.narrationArtifact?.durationSeconds ?? 0,
                            sourceDurationSeconds: shot.narrationArtifact?.sourceDurationSeconds ?? 0,
                            voiceSpeed: retainedVoiceSpeed,
                            audioProcessor: shot.narrationArtifact?.audioProcessor ?? "",
                            errorMessage: error.localizedDescription,
                            updatedAt: failedAt
                        ),
                        now: failedAt
                    )
                },
                for: project
            )
            aestheticStatus = "Shot narration failed"
            lastError = error.localizedDescription
            return false
        }
    }

    @discardableResult
    func remixShotNarrationSpeed(shotId: String, voiceSpeed: Double) async -> Bool {
        guard let project = currentProject else {
            aestheticStatus = "Create or select a project first"
            return false
        }
        guard activeShotNarrationId.isEmpty, activeShotNarrationSpeedId.isEmpty else {
            aestheticStatus = "Shot narration is already running"
            return false
        }
        guard let shot = shotTimeline.shots.first(where: { $0.shotId == shotId }),
              let narration = shot.narrationArtifact,
              narration.isReady else {
            aestheticStatus = "Generate narration before changing speed"
            return false
        }

        let targetSpeed = StoryAudioVoiceCatalog.clampedSpeed(voiceSpeed)
        guard abs(narration.effectiveVoiceSpeed - targetSpeed) > 0.001 else { return true }

        activeShotNarrationSpeedId = shotId
        defer { activeShotNarrationSpeedId = "" }
        aestheticStatus = "Applying narration speed"
        lastError = ""

        do {
            var updated = try await applyingShotNarrationSpeed(
                narration,
                targetSpeed: targetSpeed,
                projectId: project.projectId
            )
            guard currentProject?.projectId == project.projectId else { return false }
            let now = DateFormats.now()
            updated.errorMessage = ""
            updated.updatedAt = now
            persistShotTimeline(
                shotTimeline.updatingShot(shotId: shotId, now: now) {
                    $0.settingNarrationArtifact(updated, now: now)
                },
                for: project
            )
            aestheticStatus = "Narration speed updated"
            touchCurrentProject()
            return true
        } catch {
            guard currentProject?.projectId == project.projectId else { return false }
            aestheticStatus = "Narration speed update failed"
            lastError = error.localizedDescription
            return false
        }
    }

    private func applyingShotNarrationSpeed(
        _ narration: ShotNarrationArtifact,
        targetSpeed: Double,
        projectId: String
    ) async throws -> ShotNarrationArtifact {
        let speed = StoryAudioVoiceCatalog.clampedSpeed(targetSpeed)
        let sourcePath = narration.effectiveSourceAudioPath
        guard !sourcePath.isEmpty, FileManager.default.fileExists(atPath: sourcePath) else {
            throw ScreenGraphError.capture("The original narration audio is missing.")
        }

        var updated = narration
        updated.sourceAudioPath = sourcePath
        updated.sourceDurationSeconds = narration.effectiveSourceDurationSeconds
        updated.voiceSpeed = speed

        if abs(speed - StoryAudioVoiceCatalog.defaultSpeed) <= 0.001 {
            updated.audioPath = sourcePath
            updated.durationSeconds = updated.sourceDurationSeconds
            updated.audioProcessor = ""
            return updated.normalized()
        }

        let sourceURL = URL(fileURLWithPath: sourcePath)
        let stem = sourceURL.deletingPathExtension().lastPathComponent
        let derivativeURL = sourceURL.deletingLastPathComponent()
            .appendingPathComponent("\(stem)__speed.m4a")
        let temporaryURL = sourceURL.deletingLastPathComponent()
            .appendingPathComponent("\(stem)__speed_tmp.m4a")

        do {
            let duration = try await LocalAudioRetime.export(
                sourceURL: sourceURL,
                outputURL: temporaryURL,
                playbackRate: speed
            )
            guard currentProject?.projectId == projectId else {
                if FileManager.default.fileExists(atPath: temporaryURL.path) {
                    try? FileManager.default.removeItem(at: temporaryURL)
                }
                throw ScreenGraphError.capture("Shot narration project changed before speed processing finished.")
            }
            if FileManager.default.fileExists(atPath: derivativeURL.path) {
                _ = try FileManager.default.replaceItemAt(
                    derivativeURL,
                    withItemAt: temporaryURL,
                    backupItemName: nil,
                    options: []
                )
            } else {
                try FileManager.default.moveItem(at: temporaryURL, to: derivativeURL)
            }
            updated.audioPath = derivativeURL.path
            updated.durationSeconds = duration
            updated.audioProcessor = LocalAudioRetime.processorId
            return updated.normalized()
        } catch {
            if FileManager.default.fileExists(atPath: temporaryURL.path) {
                try? FileManager.default.removeItem(at: temporaryURL)
            }
            throw error
        }
    }

