    private func syncLensContextStatus() {
        if isRetrievingLensContext {
            lensContextStatus = "Retrieving Frame Context"
            return
        }
        guard projectGoalV2.isReady, let version = projectGoalV2.activeVersion else {
            lensContextStatus = "Frame context missing"
            return
        }
        let fingerprint = currentLensContextGoalFingerprint
        if lensContext.isReady(forGoalVersionId: version.versionId, goalFingerprint: fingerprint),
           let stats = lensContext.response?.queryStats {
            lensContextStatus = "Frame Context ready: \(stats.resolvedMeaningNodeCount) nodes, \(stats.meaningEdgeNeighborCount) edges, \(stats.aestheticCandidateCount) aesthetic candidates"
            return
        }
        switch lensContext.status {
        case .failed:
            let message = lensContext.failureMessage.trimmed
            lensContextStatus = message.isEmpty ? "Frame Context retrieval failed" : "Frame Context failed: \(shortSummaryText(message, limit: 160))"
        case .ready:
            lensContextStatus = "Frame Context stale"
        case .missing:
            lensContextStatus = lensContext.goalVersionId == version.versionId ? "Frame Context queued" : "Frame Context missing"
        }
    }

    private func lensContextPromptJSON() -> String {
        guard hasFreshLensContextForActiveGoal else { return "" }
        return prettyJSONString(lensContext.promptPacket())
    }

    private func retrievedCandidatesWithLensContext(
        _ retrieved: [RetrievedAestheticDirectionCandidate],
        index: AestheticIndexPacket
    ) -> [RetrievedAestheticDirectionCandidate] {
        guard hasFreshLensContextForActiveGoal,
              let response = lensContext.response,
              !response.aestheticCandidates.isEmpty else {
            return retrieved
        }

        let itemsById = Dictionary(uniqueKeysWithValues: index.items.map { ($0.aestheticId, $0) })
        var candidatesById = Dictionary(uniqueKeysWithValues: retrieved.map { ($0.item.aestheticId, $0) })

        for (offset, candidate) in response.aestheticCandidates.enumerated() {
            guard let item = itemsById[candidate.aestheticId], item.defaultRankable else { continue }
            let goalMatches = LitScenes.uniqueNonEmpty(
                candidate.matchedTerms
                    .filter { $0.source == "goal" }
                    .map(\.displayName),
                limit: 8
            )
            let archiveMatches = LitScenes.uniqueNonEmpty(
                candidate.matchedTerms
                    .filter { $0.source == "media" }
                    .map(\.displayName),
                limit: 8
            )
            let boost = lensContextCandidateScoreBoost(candidate, rankOffset: offset)
            if var existing = candidatesById[candidate.aestheticId] {
                existing.score = roundedLensContextScore(max(existing.score, min(0.98, existing.score + boost)))
                existing.goalMatches = LitScenes.uniqueNonEmpty(existing.goalMatches + goalMatches, limit: 8)
                existing.archiveMatches = LitScenes.uniqueNonEmpty(existing.archiveMatches + archiveMatches, limit: 8)
                if existing.supportStatus == .exploratory && !goalMatches.isEmpty {
                    existing.supportStatus = archiveMatches.isEmpty ? .goalLedStretch : .archiveSupported
                }
                existing.supportNote = "Frame Context matched \(candidate.matchCount) term\(candidate.matchCount == 1 ? "" : "s") from the Goal graph retrieval."
                candidatesById[candidate.aestheticId] = existing
            } else {
                let score = roundedLensContextScore(min(0.94, 0.62 + boost))
                let supportStatus: AestheticDirectionSupportStatus = archiveMatches.isEmpty ? .goalLedStretch : .archiveSupported
                candidatesById[candidate.aestheticId] = RetrievedAestheticDirectionCandidate(
                    item: item,
                    score: score,
                    supportStatus: supportStatus,
                    goalMatches: goalMatches,
                    archiveMatches: archiveMatches,
                    conflictTerms: [],
                    supportNote: "Frame Context matched \(candidate.matchCount) term\(candidate.matchCount == 1 ? "" : "s") from the Goal graph retrieval."
                )
            }
        }

        return Array(candidatesById.values)
            .sorted {
                if $0.score == $1.score {
                    return $0.item.title.localizedStandardCompare($1.item.title) == .orderedAscending
                }
                return $0.score > $1.score
            }
            .prefix(max(retrieved.count, 40))
            .map { $0 }
    }

    private func lensContextCandidateScoreBoost(_ candidate: LensContextAestheticCandidate, rankOffset: Int) -> Double {
        let rankBoost = max(0, 0.18 - (Double(rankOffset) * 0.018))
        let matchBoost = min(0.16, Double(candidate.nonColorMatchCount) * 0.035)
        let goalBoost = min(0.12, Double(candidate.goalMatchCount) * 0.04)
        return rankBoost + matchBoost + goalBoost
    }

    private func roundedLensContextScore(_ value: Double) -> Double {
        (min(max(value, 0), 1) * 100).rounded() / 100
    }

    @discardableResult
    private func saveLensSet(_ lensSet: ProjectLensSetDocument, for project: ProjectRecord, status: String) -> Bool {
        do {
            var updated = lensSet.canonicalizedToSingleLens()
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            updated = lensSetWithRefreshedRelations(updated, for: project).canonicalizedToSingleLens()
            try contextStore.saveProjectLenses(updated, for: project)
            projectLenses = updated
            aestheticStatus = status
            lastError = ""
            creativeSchemaState = contextStore.creativeSchemaState(for: project)
            touchCurrentProject()
            queueInitialStoryGenerationIfEligible()
            // Every lens mutation (body edits, renders completing) lands here,
            // so an existing sheet set stays current without per-site hooks.
            refreshProjectSheetsIfPresent()
            return true
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save Frames"
            return false
        }
    }

    private func lensSetWithRefreshedRelations(
        _ lensSet: ProjectLensSetDocument,
        for project: ProjectRecord
    ) -> ProjectLensSetDocument {
        guard let activeVersion = lensSet.activeVersion else { return lensSet }
        let scan = LensRelationScanner(store: contextStore).scan(project: project, lensSet: lensSet)
        var updated = lensSet
        var refreshedVersion = activeVersion
        refreshedVersion.lenses = activeVersion.lenses.map { theme in
            var refreshed = theme
            refreshed.relationSummary = scan.summary(for: theme.lensId)
            return refreshed
        }
        if let versionIndex = updated.versions.firstIndex(where: { $0.versionId == activeVersion.versionId }) {
            updated.versions[versionIndex] = refreshedVersion
        }
        return updated
    }

    private func saveGoalAndMirrors(_ goal: ProjectGoalDocument, for project: ProjectRecord, status: String) {
        do {
            var updatedGoal = goal
            if updatedGoal.projectId.isEmpty {
                updatedGoal.projectId = project.projectId
            }
            let mirroredAesthetic = aestheticMirroringGoal(projectAesthetic, brief: updatedGoal.activeBrief)
            try contextStore.saveProjectGoal(updatedGoal, for: project)
            try contextStore.saveProjectAesthetic(mirroredAesthetic, for: project)
            projectGoal = updatedGoal
            projectAesthetic = mirroredAesthetic
            goalStatus = status
            aestheticStatus = mirroredAesthetic.readinessLabel
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            goalStatus = "Could not save Goal"
        }
    }

    private func aestheticMirroringGoal(
        _ aesthetic: ProjectAestheticDocument,
        brief: ProjectGoalBrief
    ) -> ProjectAestheticDocument {
        var updated = aesthetic
        if let currentProject, updated.projectId.isEmpty {
            updated.projectId = currentProject.projectId
        }
        let goal = brief.goal.trimmingCharacters(in: .whitespacesAndNewlines)
        if !goal.isEmpty {
            updated.endGoal = goal
        }
        if let contentType = brief.contentType {
            updated.projectIntent = contentType
        }
        if updated.locked && (updated.endGoal != aesthetic.endGoal || updated.projectIntent != aesthetic.projectIntent) {
            updated.locked = false
        }
        updated.updatedAt = DateFormats.now()
        return updated
    }

    private func normalizedExistingMediaIds(_ mediaIds: [String]) -> [String] {
        var seen = Set<String>()
        return mediaIds.filter { mediaId in
            guard !seen.contains(mediaId),
                  items.contains(where: { $0.mediaId == mediaId }) else {
                return false
            }
            seen.insert(mediaId)
            return true
        }
    }

