    private func styleContract(from brief: ProjectAestheticBriefDocument) -> String {
        var lines: [String] = []
        if let direction = brief.chosenDirection {
            lines.append("Chosen direction: \(direction.title)")
            lines.append("Core direction: \(direction.coreReference.title)")
            if !direction.flavorReferences.isEmpty {
                lines.append("Treatment: \(direction.flavorReferences.map(\.title).joined(separator: ", "))")
            }
            if !direction.ingredientControls.isEmpty {
                let controls = direction.ingredientControls.map { control in
                    "\(control.label) \(Int((control.value0To1 * 100).rounded()))%"
                }
                lines.append("Dial: \(controls.joined(separator: ", "))")
            }
            if !direction.avoidTerms.isEmpty {
                lines.append("Avoid: \(direction.avoidTerms.joined(separator: ", "))")
            }
        }
        let grouped = Dictionary(grouping: brief.selectedReferences) { $0.role }
        for role in AestheticBriefReferenceRole.allCases {
            let references = (grouped[role] ?? []).sorted { lhs, rhs in
                if lhs.weight == rhs.weight {
                    return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
                }
                return lhs.weight > rhs.weight
            }
            guard !references.isEmpty else { continue }
            let values = references.map { reference in
                let percentage = Int((reference.weight * 100).rounded())
                return "\(reference.title) \(percentage)%"
            }
            lines.append("\(role.label): \(values.joined(separator: ", "))")
        }
        let notes = brief.operatorNotes.trimmingCharacters(in: .whitespacesAndNewlines)
        if !notes.isEmpty {
            lines.append("Notes: \(notes)")
        }
        return lines.joined(separator: "\n")
    }

    private func goalMessagesSummary(from goal: ProjectGoalDocument) -> String {
        goal.messages.suffix(12).map { message in
            let media = message.mediaIds.isEmpty ? "" : " media_ids=\(message.mediaIds.joined(separator: ", "))"
            return "- \(message.role.rawValue): \(message.text)\(media)"
        }
        .joined(separator: "\n")
    }

    private func goalV2MessagesSummary(from goal: ProjectGoalDocumentV2) -> String {
        goal.messages.suffix(12).map { message in
            let media = message.mediaIds.isEmpty ? "" : " media_ids=\(message.mediaIds.joined(separator: ", "))"
            return "- \(message.role.rawValue): \(message.text)\(media)"
        }
        .joined(separator: "\n")
    }

    private func selectedGoalMediaSummary(mediaIds: [String], limit: Int = 8) -> String {
        let allSelectedItems = mediaItems(for: mediaIds)
        let selectedItems = Array(allSelectedItems.prefix(limit))
        guard !selectedItems.isEmpty else { return "" }
        var lines = selectedItems.map { item in
            let curation = curation(for: item)
            let tags = curation.tags.isEmpty ? "" : " tags=\(curation.tags.joined(separator: ", "))"
            let notes = curation.notes.trimmingCharacters(in: .whitespacesAndNewlines)
            let noteText = notes.isEmpty ? "" : " notes=\(shortSummaryText(notes, limit: 180))"
            return "- media_id=\(item.mediaId) file=\(item.relativePath) kind=\(item.kind.rawValue) size=\(item.width)x\(item.height)\(frameSourceSummary(for: item))\(tags)\(noteText)\(goalObservationSummary(for: item))"
        }
        if allSelectedItems.count > selectedItems.count {
            lines.append("- \(allSelectedItems.count - selectedItems.count) additional selected media item(s) omitted from this Goal interview packet.")
        }
        return lines.joined(separator: "\n")
    }

    private func goalVisionInputs(mediaIds: [String], limit: Int = 8) throws -> [OpenAIVisionImageInput] {
        try mediaItems(for: mediaIds)
            .filter { $0.kind == .image }
            .prefix(limit)
            .map { item in
                let sourceURL = URL(fileURLWithPath: item.path)
                let access = sourceURL.startAccessingSecurityScopedResource()
                defer {
                    if access {
                        sourceURL.stopAccessingSecurityScopedResource()
                    }
                }
                let normalized = try normalizedJPEGData(from: sourceURL)
                return OpenAIVisionImageInput(
                    mediaId: item.mediaId,
                    filename: item.filename,
                    mimeType: "image/jpeg",
                    data: normalized.data,
                    detail: "high"
                )
            }
    }

    private func goalBriefSummary() -> String {
        goalBriefSummary(for: projectGoal.activeBrief)
    }

    private func goalBriefSummary(for brief: ProjectGoalBrief) -> String {
        var lines: [String] = []
        if let contentType = brief.contentType {
            lines.append("- content_type: \(contentType.rawValue)")
        }
        if !brief.goal.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("- goal: \(brief.goal)")
        }
        if !brief.audience.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("- audience: \(brief.audience)")
        }
        if !brief.desiredAction.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("- desired_action: \(brief.desiredAction)")
        }
        if !brief.distributionContext.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("- distribution_context: \(brief.distributionContext)")
        }
        if !brief.storyPromise.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("- story_promise: \(brief.storyPromise)")
        }
        if !brief.successCriteria.isEmpty {
            lines.append("- success_criteria: \(brief.successCriteria.joined(separator: "; "))")
        }
        if !brief.constraints.isEmpty {
            lines.append("- constraints: \(brief.constraints.joined(separator: "; "))")
        }
        if !brief.openQuestions.isEmpty {
            lines.append("- open_questions: \(brief.openQuestions.joined(separator: "; "))")
        }
        return lines.joined(separator: "\n")
    }

    private func aestheticIntentSummary(_ seed: ProjectAestheticIntentSeed) -> String {
        var lines: [String] = []
        appendSummaryList("emotional_targets", seed.emotionalTargets, to: &lines)
        appendSummaryList("narrative_values", seed.narrativeValues, to: &lines)
        appendSummaryList("visual_mood", seed.visualMood, to: &lines)
        appendSummaryList("palette_hints", seed.paletteHints, to: &lines)
        appendSummaryList("motif_hints", seed.motifHints, to: &lines)
        appendSummaryList("era_hints", seed.eraHints, to: &lines)
        appendSummaryList("energy", seed.energy, to: &lines)
        appendSummaryList("avoid", seed.avoid, to: &lines)
        appendSummaryList("open_style_questions", seed.openStyleQuestions, to: &lines)
        if seed.confidence0To1 > 0 {
            lines.append("- confidence: \(Int((seed.confidence0To1 * 100).rounded()))%")
        }
        return lines.joined(separator: "\n")
    }

    private func appendSummaryList(_ key: String, _ values: [String], to lines: inout [String]) {
        let cleaned = uniqueCleanedSummaryValues(values, limit: 8)
        guard !cleaned.isEmpty else { return }
        lines.append("- \(key): \(cleaned.joined(separator: "; "))")
    }

    private func aestheticMediaSummaryLine(for item: MediaItemRecord) -> String {
        let curation = curation(for: item)
        var parts = [
            "media_id=\(item.mediaId)",
            "kind=\(item.kind.rawValue)",
            "file=\(item.relativePath)",
            "size=\(item.width)x\(item.height)"
        ]
        if let duration = item.durationSeconds {
            parts.append("duration=\(aestheticDurationLabel(duration))")
        }
        if !curation.tags.isEmpty {
            parts.append("tags=\(curation.tags.prefix(5).joined(separator: ", "))")
        }
        let notes = curation.notes.trimmingCharacters(in: .whitespacesAndNewlines)
        if !notes.isEmpty {
            parts.append("notes=\(shortSummaryText(notes, limit: 160))")
        }
        if let observation = mediaObservationsById[item.mediaId] {
            parts.append("caption=\(shortSummaryText(observation.plainCaption, limit: 180))")
            parts.append("mood=\(observation.mood.prefix(5).joined(separator: ", "))")
            parts.append("objects=\(observation.objects.prefix(8).joined(separator: ", "))")
            parts.append("meanings=\(observation.possibleMeanings.prefix(5).joined(separator: ", "))")
        }
        return parts.filter { !$0.hasSuffix("=") }.joined(separator: " | ")
    }

    private func aestheticDurationLabel(_ duration: Double) -> String {
        let seconds = Int(duration.rounded())
        let hours = seconds / 3_600
        let minutes = (seconds % 3_600) / 60
        let remainder = seconds % 60
        if hours > 0 {
            return String(format: "%d:%02d:%02d", hours, minutes, remainder)
        }
        return String(format: "%d:%02d", minutes, remainder)
    }

    private func aestheticMediaObservationPacket(
        for item: MediaItemRecord,
        observation: ImageObservationResult
    ) -> [String: CodableValue] {
        var packet: [String: CodableValue] = [
            "media_id": .string(item.mediaId),
            "kind": .string(item.kind.rawValue),
            "relative_path": .string(item.relativePath),
            "caption": .string(shortSummaryText(observation.plainCaption, limit: 220)),
            "literal": .string(shortSummaryText(observation.literalDescription, limit: 260)),
            "setting": .string(shortSummaryText(observation.setting, limit: 180)),
            "lighting": .string(shortSummaryText(observation.lighting, limit: 120)),
            "mood": codableSummaryStringArray(observation.mood, limit: 8),
            "palette_terms": codableSummaryStringArray(observation.paletteTerms, limit: 8),
            "place_cues": codableSummaryStringArray(observation.placeCues, limit: 8),
            "era_cues": codableSummaryStringArray(observation.eraCues, limit: 8),
            "motif_cues": codableSummaryStringArray(observation.motifCues, limit: 8),
            "energy_cues": codableSummaryStringArray(observation.energyCues, limit: 8),
            "composition_cues": codableSummaryStringArray(observation.compositionCues, limit: 8),
            "objects": codableSummaryStringArray(observation.objects, limit: 10),
            "activities": codableSummaryStringArray(observation.activities, limit: 8),
            "materials": codableSummaryStringArray(observation.materials, limit: 8),
            "visual_specificity": codableSummaryStringArray(observation.visualSpecificity, limit: 8),
            "possible_meanings": codableSummaryStringArray(observation.possibleMeanings, limit: 8),
            "negative_constraints": codableSummaryStringArray(observation.negativeConstraints, limit: 6),
            "domain_tags": codableSummaryStringArray(observation.domainTags, limit: 8),
            "story_tags": codableSummaryStringArray(observation.storyObservationTags, limit: 8),
            "media_role": .string(observation.mediaRole),
            "people_visible": .bool(observation.peopleVisible)
        ]
        if let peopleCount = observation.peopleCountEstimate {
            packet["people_count_estimate"] = .number(Double(peopleCount))
        }
        return packet
    }

    private func codableSummaryStringArray(_ values: [String], limit: Int) -> CodableValue {
        .array(uniqueCleanedSummaryValues(values, limit: limit).map { .string($0) })
    }

    private func uniqueCleanedSummaryValues(_ values: [String], limit: Int) -> [String] {
        var seen = Set<String>()
        var cleaned: [String] = []
        for raw in values {
            let value = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            let key = value.lowercased()
            guard !value.isEmpty, !seen.contains(key) else { continue }
            seen.insert(key)
            cleaned.append(value)
            if cleaned.count >= limit {
                break
            }
        }
        return cleaned
    }

    private func shortSummaryText(_ value: String, limit: Int) -> String {
        let compact = value
            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
        guard compact.count > limit else { return compact }
        return String(compact.prefix(max(0, limit - 1))) + "..."
    }

    /// Preserves the safe, actionable part of NSError provenance without
    /// persisting arbitrary userInfo values, which may contain local paths or
    /// request data. The message remains first for UI readability.
    private func shotRenderFailureSummary(_ error: Error, phase: String, limit: Int) -> String {
        let root = error as NSError
        var diagnostics = [
            "phase=\(shortSummaryText(phase, limit: 48))",
            "domain=\(shortSummaryText(root.domain, limit: 48))",
            "code=\(root.code)",
        ]
        var underlying = root.userInfo[NSUnderlyingErrorKey] as? NSError
        var depth = 0
        var seen = Set<String>()
        while let current = underlying, depth < 2 {
            let identity = "\(current.domain):\(current.code)"
            guard seen.insert(identity).inserted else { break }
            diagnostics.append(
                "underlying_\(depth + 1)=\(shortSummaryText(current.domain, limit: 48)):\(current.code)"
            )
            underlying = current.userInfo[NSUnderlyingErrorKey] as? NSError
            depth += 1
        }
        let diagnosticText = "[\(diagnostics.joined(separator: " "))]"
        let messageLimit = max(24, limit - diagnosticText.count - 1)
        let message = shortSummaryText(root.localizedDescription, limit: messageLimit)
        return shortSummaryText("\(message) \(diagnosticText)", limit: limit)
    }

    private func storyAudioAsset(
        kind: String,
        url: URL,
        project: ProjectRecord,
        data: Data,
        provider: String,
        modelId: String,
        outputFormat: String,
        response: ElevenLabsAudioResponse?
    ) -> StoryAudioAsset {
        StoryAudioAsset(
            kind: kind,
            path: url.path,
            relativePath: url.relativePath(from: projectLibrary.projectDirectory(for: project)),
            sha256: response?.responseBodySHA256 ?? sha256Hex(data),
            bytes: data.count,
            contentType: response?.contentType ?? (kind == "mix" ? "audio/mp4" : "audio/mpeg"),
            provider: provider,
            modelId: modelId,
            outputFormat: outputFormat,
            requestId: response?.requestId ?? "",
            characterCost: response?.characterCost ?? "",
            characterCount: response?.characterCount ?? "",
            generatedAt: DateFormats.now()
        )
    }

    private func persistStoryAudioTrack(
        _ track: StoryAudioTrackDocument,
        for project: ProjectRecord,
        activate: Bool
    ) throws {
        var collection = storyAudioTracks
        if collection.projectId.isEmpty {
            collection.projectId = project.projectId
        }
        collection = collection.appending(track, activate: activate)
        try contextStore.saveStoryAudioTracks(collection, for: project)
        try contextStore.saveStoryAudioTrack(collection.activeTrack, for: project)
        storyAudioTracks = collection
        storyAudioTrack = collection.activeTrack
    }

    private func updateStoryWorld(_ mutate: (inout StoryWorldDocument) -> Void) {
        guard let project = currentProject else { return }
        do {
            var updated = storyWorld
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            mutate(&updated)
            updated.updatedAt = DateFormats.now()
            try contextStore.saveStoryWorld(updated, for: project)
            storyWorld = updated
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func saveProjectAestheticEvidenceProfile(
        _ profile: ProjectAestheticEvidenceProfile,
        for project: ProjectRecord
    ) {
        do {
            var updated = profile
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            try contextStore.saveAestheticEvidenceProfile(updated, for: project)
            projectAestheticEvidenceProfile = updated
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
            aestheticStatus = "Could not save Aesthetic evidence profile"
        }
    }

    private func goalBriefForInitialLensGeneration(from brief: ProjectGoalBriefV2) -> ProjectGoalBrief {
        let normalized = brief.normalized()
        let seedTerms = uniqueNonEmpty([normalized.lensSeedSummary] + normalized.lensSeedTerms)
        let aestheticIntent = ProjectAestheticIntentSeed(
            emotionalTargets: LitScenes.uniqueNonEmpty([normalized.desiredResponse, normalized.viewerExperience], limit: 8),
            narrativeValues: LitScenes.uniqueNonEmpty(normalized.successCriteria, limit: 8),
            visualMood: seedTerms,
            paletteHints: seedTerms,
            motifHints: seedTerms,
            eraHints: [],
            energy: [],
            avoid: LitScenes.uniqueNonEmpty(lensLiteralVisualAvoidTerms(normalized.constraints), limit: 8),
            openStyleQuestions: LitScenes.uniqueNonEmpty(normalized.openQuestions, limit: 4),
            confidence0To1: 0
        )
        return ProjectGoalBrief(
            contentType: normalized.contentType,
            goal: normalized.goal,
            audience: normalized.audience,
            desiredAction: normalized.desiredResponse,
            distributionContext: "",
            successCriteria: normalized.successCriteria,
            storyPromise: normalized.viewerExperience,
            constraints: normalized.constraints,
            openQuestions: normalized.openQuestions,
            aestheticIntent: aestheticIntent.normalized(),
            storySetupSuggestions: .empty(),
            confidence0To1: 0
        )
    }

