    private func validatedAestheticDirectionShortlist(
        client: OpenAIClient,
        context: AestheticDirectionShortlistContext,
        retrieved: [RetrievedAestheticDirectionCandidate]
    ) async throws -> OpenAIAestheticDirectionShortlistResult {
        guard retrieved.count >= 3 else {
            throw ScreenGraphError.openAI("At least three Scene Plan seeds are required from the bundled catalog.")
        }
        let first = try await client.shortlistAestheticDirections(context: context)
        let normalized = normalizedAestheticDirectionShortlist(first.shortlist, retrieved: retrieved)
        if !normalized.unresolvedReferences.isEmpty || normalized.duplicateCount > 0 || normalized.filledCount > 0 {
            print("[aesthetic_direction_shortlist] normalized unresolved=\(normalized.unresolvedReferences.count) duplicates=\(normalized.duplicateCount) filled=\(normalized.filledCount)")
        }
        guard normalized.shortlist.candidates.count >= 3 else {
            throw ScreenGraphError.openAI("At least three usable Scene Plan seeds are required after normalizing the shortlist.")
        }
        return OpenAIAestheticDirectionShortlistResult(
            shortlist: normalized.shortlist,
            responseId: first.responseId,
            model: first.model,
            usage: first.usage,
            rawText: first.rawText
        )
    }

    private func normalizedAestheticDirectionShortlist(
        _ shortlist: AestheticDirectionShortlistResponse,
        retrieved: [RetrievedAestheticDirectionCandidate]
    ) -> (shortlist: AestheticDirectionShortlistResponse, unresolvedReferences: [String], duplicateCount: Int, filledCount: Int) {
        let targetCount = min(20, retrieved.count)
        let items = retrieved.map(\.item)
        var usedIds = Set<String>()
        var candidates: [AestheticDirectionShortlistChoice] = []
        var unresolved: [String] = []
        var duplicateCount = 0

        for choice in shortlist.candidates {
            guard let canonicalId = canonicalAestheticId(for: choice.aestheticId, items: items) else {
                unresolved.append(choice.aestheticId)
                continue
            }
            guard !usedIds.contains(canonicalId) else {
                duplicateCount += 1
                continue
            }
            usedIds.insert(canonicalId)
            candidates.append(AestheticDirectionShortlistChoice(
                aestheticId: canonicalId,
                rationale: choice.rationale
            ))
            if candidates.count >= targetCount { break }
        }

        let countBeforeFill = candidates.count
        if candidates.count < targetCount {
            for candidate in retrieved where !usedIds.contains(candidate.item.aestheticId) {
                usedIds.insert(candidate.item.aestheticId)
                candidates.append(AestheticDirectionShortlistChoice(
                    aestheticId: candidate.item.aestheticId,
                    rationale: "Filled from retrieved candidate after an unresolved or duplicate shortlist reference."
                ))
                if candidates.count >= targetCount { break }
            }
        }

        return (
            AestheticDirectionShortlistResponse(candidates: candidates),
            unresolved,
            duplicateCount,
            max(0, candidates.count - countBeforeFill)
        )
    }

    private func validatedAestheticDirectionRanking(
        client: OpenAIClient,
        context: AestheticDirectionRankContext,
        requestedPrimaryIds: [String],
        allowedIds: [String],
        index: AestheticIndexPacket
    ) async throws -> OpenAIAestheticDirectionRankResult {
        let first = try await client.rankAestheticDirections(context: context)
        let firstNormalized = normalizedAestheticDirectionRanking(
            first.ranking,
            requestedPrimaryIds: requestedPrimaryIds,
            allowedIds: allowedIds,
            index: index
        )
        if firstNormalized.correctedPrimaryCount > 0 || firstNormalized.droppedSupportingCount > 0 || firstNormalized.fallbackDirectionCount > 0 {
            print("[aesthetic_direction_rank] normalized primary_corrections=\(firstNormalized.correctedPrimaryCount) dropped_supports=\(firstNormalized.droppedSupportingCount) fallback_directions=\(firstNormalized.fallbackDirectionCount)")
        }
        if let validationError = validateAestheticDirectionRanking(
            firstNormalized.ranking,
            requestedPrimaryIds: requestedPrimaryIds,
            allowedIds: allowedIds
        ) {
            let retry = try await client.rankAestheticDirections(context: context, validationError: validationError)
            let retryNormalized = normalizedAestheticDirectionRanking(
                retry.ranking,
                requestedPrimaryIds: requestedPrimaryIds,
                allowedIds: allowedIds,
                index: index
            )
            if retryNormalized.correctedPrimaryCount > 0 || retryNormalized.droppedSupportingCount > 0 || retryNormalized.fallbackDirectionCount > 0 {
                print("[aesthetic_direction_rank] normalized_retry primary_corrections=\(retryNormalized.correctedPrimaryCount) dropped_supports=\(retryNormalized.droppedSupportingCount) fallback_directions=\(retryNormalized.fallbackDirectionCount)")
            }
            if let retryError = validateAestheticDirectionRanking(
                retryNormalized.ranking,
                requestedPrimaryIds: requestedPrimaryIds,
                allowedIds: allowedIds
            ) {
                throw ScreenGraphError.openAI(retryError)
            }
            return OpenAIAestheticDirectionRankResult(
                ranking: retryNormalized.ranking,
                responseId: retry.responseId,
                model: retry.model,
                usage: retry.usage,
                rawText: retry.rawText
            )
        }
        return OpenAIAestheticDirectionRankResult(
            ranking: firstNormalized.ranking,
            responseId: first.responseId,
            model: first.model,
            usage: first.usage,
            rawText: first.rawText
        )
    }

    private func normalizedAestheticDirectionRanking(
        _ ranking: AestheticDirectionRankResponse,
        requestedPrimaryIds: [String],
        allowedIds: [String],
        index: AestheticIndexPacket
    ) -> (ranking: AestheticDirectionRankResponse, correctedPrimaryCount: Int, droppedSupportingCount: Int, fallbackDirectionCount: Int) {
        let allowedIdSet = Set(allowedIds)
        let allowedItems = index.items.filter { allowedIdSet.contains($0.aestheticId) }
        var output: [AestheticDirectionRankedChoice] = []
        var usedSourceIndexes = Set<Int>()
        var correctedPrimaryCount = 0
        var droppedSupportingCount = 0
        var fallbackDirectionCount = 0

        for (offset, requestedPrimaryId) in requestedPrimaryIds.enumerated() {
            let matchingSource = ranking.directions.enumerated().first { index, direction in
                guard !usedSourceIndexes.contains(index) else { return false }
                return canonicalAestheticId(for: direction.primaryAestheticId, items: allowedItems) == requestedPrimaryId
            }
            let positionalSource: (offset: Int, element: AestheticDirectionRankedChoice)? = {
                guard offset < ranking.directions.count, !usedSourceIndexes.contains(offset) else { return nil }
                return (offset, ranking.directions[offset])
            }()
            let source = matchingSource ?? positionalSource
            if let source {
                usedSourceIndexes.insert(source.offset)
            } else {
                fallbackDirectionCount += 1
            }

            var direction = source?.element ?? AestheticDirectionRankedChoice(
                primaryAestheticId: requestedPrimaryId,
                supportStatus: .exploratory,
                supportNote: "Generated from the requested shortlist because the ranking response did not provide a usable row."
            )
            if direction.primaryAestheticId != requestedPrimaryId {
                correctedPrimaryCount += 1
            }
            direction.primaryAestheticId = requestedPrimaryId

            var supportingIds: [String] = []
            for rawSupportingId in direction.supportingAestheticIds {
                guard let canonicalId = canonicalAestheticId(for: rawSupportingId, items: allowedItems),
                      allowedIdSet.contains(canonicalId),
                      canonicalId != requestedPrimaryId,
                      !supportingIds.contains(canonicalId) else {
                    droppedSupportingCount += 1
                    continue
                }
                supportingIds.append(canonicalId)
                if supportingIds.count >= 3 { break }
            }
            direction.supportingAestheticIds = supportingIds
            output.append(direction)
        }

        return (
            AestheticDirectionRankResponse(directions: output),
            correctedPrimaryCount,
            droppedSupportingCount,
            fallbackDirectionCount
        )
    }

    private func canonicalAestheticId(for rawReference: String, items: [AestheticIndexItem]) -> String? {
        let trimmed = rawReference.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        var idsByKey: [String: Set<String>] = [:]
        for item in items {
            for value in aestheticReferenceKeys(for: item) {
                for key in [value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased(), aestheticReferenceLookupKey(value)] where !key.isEmpty {
                    idsByKey[key, default: []].insert(item.aestheticId)
                }
            }
        }

        for key in [trimmed.lowercased(), aestheticReferenceLookupKey(trimmed)] where !key.isEmpty {
            if let matches = idsByKey[key], matches.count == 1 {
                return matches.first
            }
        }

        let lowercased = trimmed.lowercased()
        if lowercased.count >= 8 {
            let prefixMatches = Set(items.map(\.aestheticId).filter { $0.lowercased().hasPrefix(lowercased) })
            if prefixMatches.count == 1 {
                return prefixMatches.first
            }
        }

        return nil
    }

    private func aestheticReferenceKeys(for item: AestheticIndexItem) -> [String] {
        [item.aestheticId, item.slug, item.title, safeIdentifier(item.title)] + item.aliases
    }

    private func aestheticReferenceLookupKey(_ value: String) -> String {
        value
            .lowercased()
            .split { !$0.isLetter && !$0.isNumber }
            .joined(separator: "-")
    }

    private func validateAestheticDirectionRanking(
        _ ranking: AestheticDirectionRankResponse,
        requestedPrimaryIds: [String],
        allowedIds: [String]
    ) -> String? {
        guard !requestedPrimaryIds.isEmpty else {
            return "No requested primary_aesthetic_id values were provided."
        }
        guard ranking.directions.count == requestedPrimaryIds.count else {
            return "Ranking must contain exactly \(requestedPrimaryIds.count) directions."
        }
        let allowedIds = Set(allowedIds)
        let primaryIds = ranking.directions.map(\.primaryAestheticId)
        guard primaryIds == requestedPrimaryIds else {
            return "Ranking primary_aesthetic_id values must exactly match the requested batch order: \(requestedPrimaryIds.joined(separator: ", "))."
        }
        guard Set(primaryIds).count == requestedPrimaryIds.count else {
            return "Ranking must use unique primary_aesthetic_id values."
        }
        let invalidPrimaryIds = primaryIds.filter { !allowedIds.contains($0) }
        guard invalidPrimaryIds.isEmpty else {
            return "Ranking returned primary_aesthetic_id values outside the shortlist: \(invalidPrimaryIds.joined(separator: ", "))."
        }
        for direction in ranking.directions {
            if direction.supportingAestheticIds.contains(direction.primaryAestheticId) {
                return "A direction included its own primary_aesthetic_id inside supporting_aesthetic_ids."
            }
            let invalidSupporting = direction.supportingAestheticIds.filter { !allowedIds.contains($0) }
            if !invalidSupporting.isEmpty {
                return "Ranking returned supporting_aesthetic_ids outside the shortlist: \(invalidSupporting.joined(separator: ", "))."
            }
        }
        return nil
    }

    private func aestheticDirectionSelectionDirections(
        project: ProjectRecord,
        index: AestheticIndexPacket,
        evidenceProfile: ProjectAestheticEvidenceProfile,
        ranking: AestheticDirectionRankResponse,
        rankStart: Int,
        priorFavoriteByRoute: [String: Bool]
    ) -> [AestheticDirectionSelectionDirection] {
        let itemsById = Dictionary(uniqueKeysWithValues: index.items.map { ($0.aestheticId, $0) })
        return ranking.directions.enumerated().map { offset, rankedChoice in
            let rank = rankStart + offset
            let routeKey = aestheticSelectionRouteKey(
                projectId: project.projectId,
                evidenceFingerprint: evidenceProfile.fingerprint,
                rank: rank,
                primaryAestheticId: rankedChoice.primaryAestheticId,
                supportingIds: rankedChoice.supportingAestheticIds
            )
            let core = itemsById[rankedChoice.primaryAestheticId]
            let flavorItems = rankedChoice.supportingAestheticIds.compactMap { itemsById[$0] }
            return AestheticDirectionSelectionDirection(
                routeKey: routeKey,
                rank: rank,
                primaryAestheticId: rankedChoice.primaryAestheticId,
                supportingAestheticIds: rankedChoice.supportingAestheticIds,
                directionLabel: core.map { visualDirectionLabel(core: $0, flavorItems: flavorItems) } ?? rankedChoice.primaryAestheticId,
                visualSummary: rankedChoice.visualSummary,
                treatmentNotes: rankedChoice.treatmentNotes,
                bestAppliedTo: rankedChoice.bestAppliedTo,
                fitReason: rankedChoice.fitReason,
                supportStatus: rankedChoice.supportStatus,
                supportNote: rankedChoice.supportNote,
                evidence: rankedChoice.evidence,
                gaps: rankedChoice.gaps,
                conflicts: rankedChoice.conflicts,
                isFavorite: priorFavoriteByRoute[routeKey] ?? false,
                updatedAt: DateFormats.now()
            )
        }
    }

    private func aestheticSelectionRouteKey(
        projectId: String,
        evidenceFingerprint: String,
        rank: Int,
        primaryAestheticId: String,
        supportingIds: [String]
    ) -> String {
        "selection_\(safeIdentifier(primaryAestheticId))_\(shortHash([projectId, evidenceFingerprint, "\(rank)", primaryAestheticId, supportingIds.sorted().joined(separator: ",")].joined(separator: "|"), length: 16))"
    }

    private func retrievedCandidatePromptSummary(_ retrieved: [RetrievedAestheticDirectionCandidate]) -> String {
        retrieved.map(\.promptSummary).joined(separator: "\n")
    }

    private func existingAestheticDirectionSummary(_ selection: AestheticDirectionSelectionDocument) -> String {
        selection.directions
            .sorted { $0.rank < $1.rank }
            .map { direction in
                "Rank \(direction.rank): \(direction.primaryAestheticId) · \(direction.directionLabel) · \(direction.visualSummary)"
            }
            .joined(separator: "\n")
    }

    private func shortlistedDetailPromptSummary(
        shortlistIds: [String],
        retrieved: [RetrievedAestheticDirectionCandidate],
        index: AestheticIndexPacket
    ) -> String {
        let retrievedById = Dictionary(uniqueKeysWithValues: retrieved.map { ($0.item.aestheticId, $0) })
        let itemsById = Dictionary(uniqueKeysWithValues: index.items.map { ($0.aestheticId, $0) })
        return shortlistIds.compactMap { aestheticId in
            guard let item = itemsById[aestheticId] else { return nil }
            let retrieved = retrievedById[aestheticId]
            let signals = uniqueCleanedSummaryValues(
                item.signatureTerms + item.treatmentTerms + item.semanticTags + item.paletteTerms,
                limit: 10
            )
            let key = item.slug.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? safeIdentifier(item.title).lowercased()
                : item.slug
            return [
                "key=\(key)",
                "id=\(item.aestheticId)",
                "title=\(item.title)",
                "score=\(String(format: "%.2f", retrieved?.score ?? 0))",
                "support=\(retrieved?.supportStatus.rawValue ?? AestheticDirectionSupportStatus.exploratory.rawValue)",
                "summary=\(shortSummaryText(item.displaySummary, limit: 180))",
                "signature=\(signals.joined(separator: ", "))",
                "goal_matches=\((retrieved?.goalMatches ?? []).joined(separator: ", "))",
                "archive_matches=\((retrieved?.archiveMatches ?? []).joined(separator: ", "))",
                "conflicts=\((retrieved?.conflictTerms ?? []).joined(separator: ", "))",
            ].joined(separator: " | ")
        }
        .joined(separator: "\n")
    }

    private func currentAestheticObservationSummary(limit: Int) -> String {
        prettyJSONString(aestheticMediaObservationPackets(limit: limit))
    }

    private func prettyJSONString<T: Encodable>(_ value: T) -> String {
        guard let data = try? JSONCoding.prettyEncoder.encode(value),
              let text = String(data: data, encoding: .utf8) else {
            return ""
        }
        return text
    }

    private func updateStoryWorkspace(_ mutate: (inout StoryWorkspaceDocument) -> Void) {
        guard let project = currentProject else { return }
        do {
            var updated = storyWorkspace
            if updated.projectId.isEmpty {
                updated.projectId = project.projectId
            }
            mutate(&updated)
            updated.updatedAt = DateFormats.now()
            try contextStore.saveStoryWorkspace(updated, for: project)
            storyWorkspace = updated
            touchCurrentProject()
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func setRawContext(_ url: URL) {
        guard let project = currentProject else { return }
        updateStoryWorld { storyWorld in
            storyWorld.rawContext.path = url.standardizedFileURL.path
            storyWorld.rawContext.sourceOfTruth = "context_folder"
        }
        addSourceContext(url, kind: .folder, project: project)
    }

    private func addSourceContext(_ url: URL, kind: SourceContextKind, project: ProjectRecord) {
        do {
            let path = url.standardizedFileURL.path
            guard !sourceContextRecords.contains(where: { $0.kind == kind && $0.path == path }) else {
                scanStatus = "Source context already added"
                return
            }
            var updated = sourceContextRecords
            updated.append(contextStore.makeSourceContext(from: url, kind: kind))
            try contextStore.saveSourceContext(updated, for: project)
            sourceContextRecords = updated
            touchCurrentProject()
            scanStatus = "Added \(url.lastPathComponent)"
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func sourceContextSummary() -> String {
        guard !sourceContextRecords.isEmpty else { return "" }
        return sourceContextRecords.prefix(12).map { source in
            let details = [
                source.kind.label,
                source.title,
                source.path,
                source.notes
            ]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: " | ")
            return "- \(details)"
        }
        .joined(separator: "\n")
    }

    private func loadStoryPatternIndex() -> StoryPatternIndexDocument {
        do {
            let url = try packagedResourceURL(named: "story_pattern_index", extension: "json")
            let data = try Data(contentsOf: url)
            return try StoryPatternIndexDocument.decode(from: data)
        } catch {
            return StoryPatternIndexDocument(version: StoryPatternIndexDocument.defaultVersion)
        }
    }

    private func storyGoalDigest() -> StoryGoalDigest {
        let brief = activeGoalBriefV2
        return StoryGoalDigest(
            summary: brief.goal.trimmed,
            mood: uniqueNonEmpty([brief.viewerExperience, brief.desiredResponse] + brief.lensSeedTerms),
            values: uniqueNonEmpty(brief.successCriteria),
            motifs: uniqueNonEmpty(brief.lensSeedTerms),
            avoid: uniqueNonEmpty(brief.constraints),
            desiredStoryResult: brief.viewerExperience.trimmed.isEmpty ? brief.desiredResponse : brief.viewerExperience
        )
    }

    private func storyAestheticCues() -> StoryAestheticCues {
        var narrativeValues: [String] = []
        narrativeValues.append(activeGoalBriefV2.viewerExperience)
        narrativeValues.append(activeGoalBriefV2.desiredResponse)
        narrativeValues.append(contentsOf: activeGoalBriefV2.lensSeedTerms)

        var presentationValues: [String] = []
        var paletteValues: [String] = []
        var avoidValues: [String] = activeGoalBriefV2.constraints

        for theme in readyLenses {
            let promptSafe = PromptSafeLensSnapshot.from(lens: theme)
            let resolved = promptSafe.resolvedVisualLanguage
            narrativeValues.append(promptSafe.claim)
            narrativeValues.append(contentsOf: promptSafe.mustPreserve)
            presentationValues.append(promptSafe.visualSummary)
            presentationValues.append(resolved.look)
            presentationValues.append(contentsOf: resolved.materials)
            presentationValues.append(contentsOf: resolved.productTreatment)
            presentationValues.append(contentsOf: resolved.motifs)
            presentationValues.append(contentsOf: resolved.composition)
            presentationValues.append(contentsOf: resolved.pacingEnergy)
            paletteValues.append(contentsOf: resolved.palette)
            avoidValues.append(contentsOf: promptSafe.mustAvoid)
            avoidValues.append(contentsOf: resolved.avoid)
        }

        let narrative = uniqueNonEmpty(narrativeValues)
        let presentation = uniqueNonEmpty(presentationValues)
        let palette = uniqueNonEmpty(paletteValues)
        let avoid = uniqueNonEmpty(avoidValues)
        return StoryAestheticCues(
            narrativeCues: narrative,
            presentationCues: presentation,
            paletteCues: palette,
            avoidCues: avoid
        )
    }

    private func storyPatternMatches() -> [StoryPatternMatch] {
        storyPatternMatches(setup: storySetup)
    }

    private func storyPatternMatches(setup: StorySetupDocument) -> [StoryPatternMatch] {
        let goal = storyGoalDigest()
        let cues = storyAestheticCues()
        let text = [
            goal.summary,
            goal.desiredStoryResult,
            goal.mood.joined(separator: " "),
            goal.values.joined(separator: " "),
            goal.motifs.joined(separator: " "),
            cues.narrativeCues.joined(separator: " "),
            cues.presentationCues.joined(separator: " "),
            setup.outputType.label,
            setup.effectivePOVLabel,
            setup.effectiveStoryEngineLabel,
            setup.effectiveEndingStyleLabel,
            setup.mustInclude,
            setup.avoid,
            storyMediaScopeSummary(items: currentStoryScopeItems)
        ].joined(separator: "\n")
        return StoryPatternMatcher.matches(index: storyPatternIndex, text: text, setup: setup)
    }

    private func storyPromptPacket(signals: StorySignalSet) -> StoryPromptPacket {
        storyPromptPacket(signals: signals, setup: storySetup)
    }

    private func storyPromptPacket(signals: StorySignalSet, setup: StorySetupDocument) -> StoryPromptPacket {
        let cues = storyAestheticCues()
        return StoryPromptPacket(
            goalDigest: storyGoalDigest(),
            aestheticNarrativeCues: cues.narrativeCues,
            aestheticPresentationCues: cues.presentationCues,
            paletteCues: cues.paletteCues,
            avoidCues: cues.avoidCues,
            storySetup: setup,
            storySignals: signals,
            sourceContext: sourceContextSummary(),
            enabledMediaDigest: storyMediaScopeSummary(items: currentStoryScopeItems),
            storyPatternMatches: storyPatternMatches(setup: setup)
        )
    }

    private func encodedStoryPromptPacket(_ packet: StoryPromptPacket) -> String {
        guard let data = try? JSONCoding.prettyEncoder.encode(packet),
              let text = String(data: data, encoding: .utf8) else {
            return "{}"
        }
        return text
    }

