    private func storylineCreationMessagesSummary(from creation: StorylineCreationDocument) -> String {
        creation.messages.suffix(12).map { message in
            let media = message.mediaIds.isEmpty ? "" : " media_ids=\(message.mediaIds.joined(separator: ", "))"
            return "- \(message.role.rawValue): \(message.text)\(media)"
