    private func normalizedSingleStoryDirection(
        _ direction: StoryDirectionCard,
        directionId: String,
        fingerprint: StoryInputFingerprint,
        projectId: String
    ) -> StoryDirectionCard {
        var updated = direction
        updated.directionId = directionId
        updated.enabled = true
        return normalizedDirections([updated], fingerprint: fingerprint, projectId: projectId).first ?? updated
    }

    private func localSingleStoryDirection(
        project: ProjectRecord,
        creation: StorylineCreationDocument,
        directionId: String,
        fingerprint: StoryInputFingerprint,
        generatedAt: String
    ) -> StoryDirectionCard {
        let localSet = StoryLocalDraftFactory.directionSet(
            projectId: project.projectId,
            projectName: project.name,
            fingerprint: fingerprint,
            setup: creation.draftSetup,
            goalDigest: storyGoalDigest(),
            aestheticCues: storyAestheticCues(),
            patternMatches: storyPatternMatches(setup: creation.draftSetup),
            generatedAt: generatedAt
        )
        let preferredLane: StoryDirectionLane = creation.draftSetup.commercialPressure == .none ? .recommended : .commercial
        var direction = localSet.directions.first { $0.lane == preferredLane }
            ?? localSet.directions.first { $0.lane == .recommended }
            ?? localSet.directions.first
            ?? StoryDirectionCard(
                directionId: directionId,
                lane: .recommended,
                title: "Untitled Storyline",
                premise: "A focused Storyline derived from the current Create Storyline draft.",
                storyEngine: creation.draftSetup.effectiveStoryEngineLabel,
                whatHappens: "The enabled media is arranged into a clear Story direction that follows the current Goal, Aesthetic, and Create Storyline draft.",
                whyItWorks: "It keeps the storyline prompt-ready while preserving the current project evidence.",
                aestheticUse: StoryAestheticUse(
                    narrative: storyAestheticCues().narrativeCues.prefix(4).joined(separator: ", "),
                    presentation: storyAestheticCues().presentationCues.prefix(4).joined(separator: ", ")
                ),
                inventedElements: [],
                risk: "Needs operator review before expanding into beats.",
                threeBeatPreview: ["Establish the visible world.", "Introduce the turn.", "Close on the storyline image."],
                meaningMoves: storyPatternMatches(setup: creation.draftSetup).prefix(5).map(\.friendlyLabel),
                commercialPressure: creation.draftSetup.commercialPressure.scalar,
                weirdness: 0.35,
                promptability: 0.66,
                scoreDebug: StoryDirectionScore(finalScore: 0.62)
        )
        let normalizedDraft = creation.draft.normalized()
        if !normalizedDraft.storylineTitle.isEmpty {
            direction.title = normalizedDraft.storylineTitle
        }
        if normalizedDraft.storylineIntent.split(whereSeparator: { $0.isWhitespace || $0.isNewline }).count >= 8 {
            direction.premise = normalizedDraft.storylineIntent
            direction.whatHappens = normalizedDraft.storylineIntent
        }
        direction.directionId = directionId
        direction.enabled = true
        direction.validationWarnings = StoryValidation.directionWarnings(direction)
        return normalizedSingleStoryDirection(
            direction,
            directionId: directionId,
            fingerprint: fingerprint,
            projectId: project.projectId
        )
    }

    private func persistGeneratedSingleStoryline(
        _ direction: StoryDirectionCard,
        directionSetId: String,
        fingerprint: StoryInputFingerprint,
        generatedAt: String,
        generator: String,
        model: String,
        responseId: String,
        packet: StoryPromptPacket,
        project: ProjectRecord,
        status: String
    ) throws {
        var set = StoryDirectionSet(
            projectId: project.projectId,
            directionSetId: directionSetId,
            inputFingerprint: fingerprint,
            storySetupSnapshot: storySetup,
            candidateDirections: [direction],
            directions: [direction],
            selectedDirectionId: direction.directionId,
            status: generator == "openai" ? "ready" : "local_draft",
            generatedAt: generatedAt,
            updatedAt: DateFormats.now(),
            generator: generator,
            model: model,
            responseId: responseId,
            artifactStatus: .fresh
        )
        set.directions = StoryDirectionSet.storylineDisplayOrder(set.directions)
        var merged = mergedStoryLensSet(set)
        if merged.directions.contains(where: { $0.directionId == direction.directionId }) {
            merged.selectedDirectionId = direction.directionId
        }
        try persistStoryDirectionSet(merged, project: project, status: status)
        if generator == "openai" {
            try recordStoryGenerationRun(
                artifactType: "story_single_storyline",
                artifactId: direction.directionId,
                model: model,
                responseId: responseId,
                schemaVersion: "litscenes.story_single_storyline_response.v0.1",
                inputFingerprint: fingerprint,
                promptPacket: packet,
                createdAt: generatedAt,
                for: project
            )
        }
        var reset = StorylineCreationDocument.empty(projectId: project.projectId, seedSetup: storySetup)
        reset.lastGeneratedDirectionId = direction.directionId
        reset.status = "Storyline generated"
        reset.updatedAt = DateFormats.now()
        try contextStore.saveStorylineCreation(reset, for: project)
        storylineCreation = reset
        touchCurrentProject()
    }

    private func localStorySignals(
        project: ProjectRecord,
        scopedItems: [MediaItemRecord],
        fingerprint: StoryInputFingerprint,
        generatedAt: String
    ) -> StorySignalSet {
        let matches = storyPatternMatches()
        let cues = storyAestheticCues()
        let chips = Array(matches.map(\.friendlyLabel).prefix(8))
        return StorySignalSet(
            projectId: project.projectId,
            signalSetId: "signals_local_\(shortHash("\(project.projectId):\(fingerprint.stableId):\(generatedAt)", length: 14))",
            scope: ProjectStoryScope.enabledMedia.rawValue,
            summary: "Local Story Signals from current Goal, accepted Aesthetic, enabled media summaries, and the bundled Story Pattern Index.",
            friendlyChips: chips,
            motifs: uniqueNonEmpty(storyGoalDigest().motifs + cues.presentationCues).prefixArray(12),
            tensions: uniqueNonEmpty(storyGoalDigest().values + cues.narrativeCues).prefixArray(12),
            moods: uniqueNonEmpty(storyGoalDigest().mood).prefixArray(12),
            sceneForces: matches.filter { $0.kind == "story_engine" }.map(\.friendlyLabel).prefixArray(12),
            constraints: uniqueNonEmpty(storyGoalDigest().avoid + cues.avoidCues).prefixArray(12),
            implications: [
                "Generate Storyline Cards before Beat Boards.",
                "Keep each beat concrete, visible, and prompt-ready.",
                "Do not use stale legacy arcade/co-op signals as current context."
            ],
            evidenceMediaIds: scopedItems.map(\.mediaId),
            confidence0To1: matches.isEmpty ? 0.35 : 0.58,
            inputFingerprint: fingerprint,
            generatedAt: generatedAt,
            updatedAt: generatedAt,
            artifactStatus: .fresh
        )
    }

    private func storyProviderFallbackStatus(_ baseStatus: String, after error: Error) -> String {
        let nsError = error as NSError
        let message = error.localizedDescription.lowercased()
        if nsError.domain == NSURLErrorDomain && nsError.code == NSURLErrorTimedOut || message.contains("timed out") {
            return "\(baseStatus) after OpenAI timed out"
        }
        if message.contains("api key") || message.contains("openai") {
            return "\(baseStatus) because OpenAI is unavailable"
        }
        return "\(baseStatus) using local fallback"
    }

    private func storySignalsForDirectionGeneration(
        project: ProjectRecord,
        scopedItems: [MediaItemRecord],
        fingerprint: StoryInputFingerprint,
        generatedAt: String
    ) throws -> StorySignalSet {
        if storySignals.freshness(against: fingerprint) == .fresh {
            return storySignals
        }

        let fallback = localStorySignals(
            project: project,
            scopedItems: scopedItems,
            fingerprint: fingerprint,
            generatedAt: generatedAt
        )
        try contextStore.saveStorySignals(fallback, for: project)
        storySignals = fallback
        return fallback
    }

    private func freshStorySignals(
        project: ProjectRecord,
        scopedItems: [MediaItemRecord],
        fingerprint: StoryInputFingerprint,
        client: OpenAIClient,
        generatedAt: String
    ) async throws -> StorySignalSet {
        if storySignals.freshness(against: fingerprint) == .fresh {
            return storySignals
        }

        let packet = storyPromptPacket(signals: StorySignalSet.empty(projectId: project.projectId))
        let context = StorySignalSetGenerationContext(
            projectId: project.projectId,
            projectName: project.name,
            signalSetId: "signals_\(shortHash("\(project.projectId):\(fingerprint.stableId):\(generatedAt)", length: 14))",
            scope: ProjectStoryScope.enabledMedia.rawValue,
            selectedMediaIds: scopedItems.map(\.mediaId),
            promptPacketJSON: encodedStoryPromptPacket(packet),
            inputFingerprint: fingerprint,
            generatedAt: generatedAt
        )
        let result = try await client.deriveStorySignalSet(context: context)
        var signals = result.signalSet
        signals.projectId = project.projectId
        signals.scope = ProjectStoryScope.enabledMedia.rawValue
        signals.evidenceMediaIds = signals.evidenceMediaIds.filter { mediaId in
            scopedItems.contains { $0.mediaId == mediaId }
        }
        signals.inputFingerprint = fingerprint
        signals.artifactStatus = .fresh
        signals.legacySourcePath = ""
        signals.legacyRawScope = ""
        signals.generatedAt = signals.generatedAt.isEmpty ? generatedAt : signals.generatedAt
        signals.updatedAt = DateFormats.now()
        try contextStore.saveStorySignals(signals, for: project)
        try recordStoryGenerationRun(
            artifactType: "story_signals",
            artifactId: signals.signalSetId,
            model: result.model,
            responseId: result.responseId,
            schemaVersion: signals.schemaVersion,
            inputFingerprint: fingerprint,
            promptPacket: packet,
            createdAt: generatedAt,
            for: project
        )
        storySignals = signals
        return signals
    }

    private func normalizedStoryDirectionSet(
        _ input: StoryDirectionSet,
        project: ProjectRecord,
        directionSetId: String,
        fingerprint: StoryInputFingerprint,
        setup: StorySetupDocument,
        generatedAt: String,
        generator: String,
        model: String,
        responseId: String
    ) -> StoryDirectionSet {
        var set = input
        set.projectId = project.projectId
        set.directionSetId = directionSetId
        set.inputFingerprint = fingerprint
        set.storySetupSnapshot = setup
        set.generatedAt = set.generatedAt.isEmpty ? generatedAt : set.generatedAt
        set.updatedAt = DateFormats.now()
        set.generator = generator
        set.model = model
        set.responseId = responseId
        set.artifactStatus = .fresh
        set.candidateDirections = normalizedDirections(
            set.candidateDirections.isEmpty ? set.directions : set.candidateDirections,
            fingerprint: fingerprint,
            projectId: project.projectId
        )
        set.directions = selectPublicDirections(
            from: set.directions.isEmpty ? set.candidateDirections : set.directions,
            fallbackCandidates: set.candidateDirections,
            project: project,
            fingerprint: fingerprint
        )
        set.directions = normalizedDirections(set.directions, fingerprint: fingerprint, projectId: project.projectId)
        if set.selectedDirectionId.isEmpty || !set.directions.contains(where: { $0.directionId == set.selectedDirectionId }) {
            set.selectedDirectionId = set.directions.first(where: { $0.lane == .recommended })?.directionId
                ?? set.directions.first?.directionId
                ?? ""
        }
        set.directions = StoryDirectionSet.storylineDisplayOrder(set.directions)
        set.status = generator == "openai" ? "ready" : "local_draft"
        let laneWarnings = StoryValidation.laneDifferentiationWarnings(set.directions)
        if !laneWarnings.isEmpty {
            set.status = "\(set.status): \(laneWarnings.joined(separator: "; "))"
        }
        return set
    }

    private func mergedStoryLensSet(_ generated: StoryDirectionSet) -> StoryDirectionSet {
        guard storyDirectionSet.hasDirections else {
            var fresh = generated
            fresh.directions = StoryDirectionSet.storylineDisplayOrder(fresh.directions)
            return fresh
        }

        var merged = storyDirectionSet
        let existingSelectedId = merged.selectedDirectionId
        let generatedDirectionIds = Set(generated.directions.map(\.directionId))
        let preservedDirections = merged.directions.filter { !generatedDirectionIds.contains($0.directionId) }
        merged.directions = StoryDirectionSet.storylineDisplayOrder(generated.directions + preservedDirections)
        merged.candidateDirections = uniqueStoryDirections(generated.candidateDirections + merged.candidateDirections)
        merged.inputFingerprint = generated.inputFingerprint
        merged.storySetupSnapshot = generated.storySetupSnapshot
        merged.generatedAt = generated.generatedAt
        merged.updatedAt = DateFormats.now()
        merged.generator = generated.generator
        merged.model = generated.model
        merged.responseId = generated.responseId
        merged.artifactStatus = generated.artifactStatus
        merged.status = generated.status

        if !existingSelectedId.isEmpty, merged.directions.contains(where: { $0.directionId == existingSelectedId }) {
            merged.selectedDirectionId = existingSelectedId
        } else {
            merged.selectedDirectionId = merged.directions.first(where: { $0.enabled && $0.lane == .recommended })?.directionId
                ?? merged.directions.first(where: { $0.enabled })?.directionId
                ?? merged.directions.first?.directionId
                ?? ""
        }
        return merged
    }

    private func uniqueStoryDirections(_ directions: [StoryDirectionCard]) -> [StoryDirectionCard] {
        var seen: Set<String> = []
        var result: [StoryDirectionCard] = []
        for direction in directions {
            let key = direction.directionId.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !key.isEmpty, !seen.contains(key) else { continue }
            seen.insert(key)
            result.append(direction)
        }
        return result
    }

    private func normalizedDirections(
        _ directions: [StoryDirectionCard],
        fingerprint: StoryInputFingerprint,
        projectId: String
    ) -> [StoryDirectionCard] {
        directions.enumerated().map { index, direction in
            var updated = direction
            let trimmedId = updated.directionId.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmedId.isEmpty || StoryDirectionLane.allCases.contains(where: { $0.rawValue == trimmedId }) {
                updated.directionId = "dir_\(shortHash("\(projectId):\(fingerprint.stableId):\(updated.lane.rawValue):\(index):\(updated.title)", length: 14))"
            }
            updated.commercialPressure = min(max(updated.commercialPressure, 0), 1)
            updated.weirdness = min(max(updated.weirdness, 0), 1)
            updated.promptability = min(max(updated.promptability, 0), 1)
            updated.validationWarnings = StoryValidation.directionWarnings(updated)
            return updated
        }
    }

    private func selectPublicDirections(
        from publicDirections: [StoryDirectionCard],
        fallbackCandidates: [StoryDirectionCard],
        project: ProjectRecord,
        fingerprint: StoryInputFingerprint
    ) -> [StoryDirectionCard] {
        let pool = publicDirections + fallbackCandidates
        var selected: [StoryDirectionCard] = []
        let sorted = pool.sorted(by: { $0.scoreDebug.finalScore > $1.scoreDebug.finalScore })
        func appendBest(_ predicate: (StoryDirectionCard) -> Bool) {
            guard selected.count < 3,
                  let best = sorted.first(where: { candidate in
                      predicate(candidate) && !selected.contains(where: { $0.directionId == candidate.directionId })
                  }) else {
                return
            }
            selected.append(best)
        }
        appendBest { $0.lane == .recommended }
        appendBest { $0.lane == .bolder }
        if storySetup.commercialPressure != .none {
            appendBest { $0.lane == .commercial }
        }
        appendBest { $0.lane == .wildcard }
        for card in sorted where selected.count < 3 && !selected.contains(where: { $0.directionId == card.directionId }) {
            if storySetup.commercialPressure == .none, card.lane == .commercial {
                continue
            }
            selected.append(card)
        }
        if selected.count == 3 {
            return selected.map { card in
                var updated = card
                updated.enabled = true
                return updated
            }
        }
        let fallback = StoryLocalDraftFactory.directionSet(
            projectId: project.projectId,
            projectName: project.name,
            fingerprint: fingerprint,
            setup: storySetup,
            goalDigest: storyGoalDigest(),
            aestheticCues: storyAestheticCues(),
            patternMatches: storyPatternMatches(),
            generatedAt: DateFormats.now()
        )
        for card in fallback.directions where selected.count < 3 && !selected.contains(where: { $0.directionId == card.directionId }) {
            selected.append(card)
        }
        return selected.prefix(3).map { card in
            var updated = card
            updated.enabled = true
            return updated
        }
    }

    private func normalizedStoryBeatBoard(
        _ input: StoryBeatBoard,
        project: ProjectRecord,
        boardId: String,
        direction: StoryDirectionCard,
        directionSetId: String,
        sourceDirectionIds: [String],
        fingerprint: StoryInputFingerprint,
        generatedAt: String,
        generator: String,
        model: String,
        responseId: String
    ) -> StoryBeatBoard {
        var board = input
        board.projectId = project.projectId
        board.beatBoardId = boardId
        board.parentDirectionSetId = directionSetId
        board.parentDirectionId = direction.directionId
        board.primaryDirectionId = direction.directionId
        board.sourceDirectionIds = uniqueNonEmpty(sourceDirectionIds).isEmpty
            ? [direction.directionId]
            : uniqueNonEmpty(sourceDirectionIds)
        board.storySetupHash = fingerprint.storySetupHash
        board.readyLensSetHash = readyLensSetHashValue
        board.lensRowSnapshots = readyLensRowSnapshots
        board.aestheticRecipeVersion = readyLensSetHashValue
        board.isActiveDraft = true
        board.inputFingerprint = fingerprint
        board.generatedAt = board.generatedAt.isEmpty ? generatedAt : board.generatedAt
        board.updatedAt = DateFormats.now()
        board.generator = generator
        board.model = model
        board.responseId = responseId
        board.artifactStatus = .fresh
        if board.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            board.title = direction.title
        }
        if board.logline.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            board.logline = direction.premise
        }
        if board.storyEngine.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            board.storyEngine = direction.storyEngine
        }
        board.beats = board.beats
            .sorted { $0.order < $1.order }
            .enumerated()
            .map { index, beat in
                var updated = beat
                updated.order = index + 1
                if updated.beatId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    updated.beatId = "beat_\(String(format: "%02d", index + 1))_\(shortHash("\(boardId):\(index):\(updated.title)", length: 8))"
                }
                if updated.lensRowSnapshots.isEmpty {
                    updated.lensRowSnapshots = board.lensRowSnapshots
                }
                updated.validationWarnings = StoryValidation.beatWarnings(updated)
                return updated
            }
        board.status = generator == "openai" ? "ready" : "local_draft"
        board.validationWarnings = StoryValidation.commercialWarnings(board: board, setup: storySetup)
            + StoryValidation.aestheticMismatchWarnings(board: board, cues: storyAestheticCues())
        return board
    }

    private func persistStoryDirectionSet(
        _ set: StoryDirectionSet,
        project: ProjectRecord,
        status: String
    ) throws {
        try contextStore.saveStoryDirectionSet(set, for: project)
        storyDirectionHistory = contextStore.loadStoryDirectionHistory(for: project)
        storyDirectionSet = storyDirectionHistory.activeSet
        var workspace = storyWorkspace
        if workspace.projectId.isEmpty {
            workspace.projectId = project.projectId
        }
        workspace.activeDirectionSetId = set.directionSetId
        workspace.activeDirectionId = set.selectedDirectionId
        workspace.previewDirectionId = set.selectedDirectionId
        workspace.currentStep = .directions
        workspace.status = status
        workspace.updatedAt = DateFormats.now()
        try contextStore.saveStoryWorkspace(workspace, for: project)
        storyWorkspace = workspace
        storyStatus = status
    }

    private func persistStoryBeatBoard(
        _ board: StoryBeatBoard,
        project: ProjectRecord,
        status: String
    ) throws {
        var updatedBoards = storyBeatBoards.map { existing -> StoryBeatBoard in
            var copy = existing.beatBoardId == board.beatBoardId ? board : existing
            copy.isActiveDraft = copy.beatBoardId == board.beatBoardId
            return copy
        }
        if !updatedBoards.contains(where: { $0.beatBoardId == board.beatBoardId }) {
            var activeBoard = board
            activeBoard.isActiveDraft = true
            updatedBoards.append(activeBoard)
        }
        for item in updatedBoards {
            try contextStore.saveStoryBeatBoard(item, for: project)
        }
        let activeBoard = updatedBoards.first(where: { $0.beatBoardId == board.beatBoardId }) ?? board
        let strip = StorySequenceStripDocument.fromBeatBoard(activeBoard, paletteTerms: storyAestheticCues().paletteCues)
        try contextStore.saveStorySequenceStrip(strip, for: project)
        var workspace = storyWorkspace
        if workspace.projectId.isEmpty {
            workspace.projectId = project.projectId
        }
        workspace.activeBeatBoardId = activeBoard.beatBoardId
        workspace.activeDirectionSetId = activeBoard.parentDirectionSetId
        workspace.activeDirectionId = activeBoard.primaryDirectionId.isEmpty ? activeBoard.parentDirectionId : activeBoard.primaryDirectionId
        workspace.currentStep = .beats
        workspace.status = status
        workspace.updatedAt = DateFormats.now()
        try contextStore.saveStoryWorkspace(workspace, for: project)
        storyBeatBoards = contextStore.loadStoryBeatBoards(for: project)
        storyBeatBoard = activeBoard
        storySequenceStrip = strip
        storyWorkspace = workspace
        storyStatus = status
    }

    private func recordStoryGenerationRun(
        artifactType: String,
        artifactId: String,
        model: String,
        responseId: String,
        schemaVersion: String,
        inputFingerprint: StoryInputFingerprint,
        promptPacket: StoryPromptPacket,
        createdAt: String,
        for project: ProjectRecord
    ) throws {
        let runId = "run_\(shortHash("\(project.projectId):\(artifactType):\(artifactId):\(createdAt)", length: 16))"
        let packetValue = compactPromptPacketValue(promptPacket)
        let run = StoryGenerationRunDocument(
            runId: runId,
            artifactType: artifactType,
            model: model,
            responseId: responseId,
            outputSchemaVersion: schemaVersion,
            inputFingerprint: inputFingerprint,
            compactPromptPacket: packetValue,
            artifactId: artifactId,
            createdAt: createdAt
        )
        try contextStore.saveStoryGenerationRun(run, for: project)
        storyGenerationRunIndex = contextStore.loadStoryGenerationRunIndex(for: project)
    }

    private func compactPromptPacketValue(_ packet: StoryPromptPacket) -> CodableValue {
        .object([
            "packet_hash": .string(stableHash(packet)),
            "goal_summary": .string(packet.goalDigest.summary),
            "desired_story_result": .string(packet.goalDigest.desiredStoryResult),
            "narrative_cues": .array(packet.aestheticNarrativeCues.prefix(12).map { .string($0) }),
            "presentation_cues": .array(packet.aestheticPresentationCues.prefix(12).map { .string($0) }),
            "pattern_matches": .array(packet.storyPatternMatches.prefix(12).map { .string($0.friendlyLabel) }),
            "enabled_media_digest_hash": .string(stableHash(packet.enabledMediaDigest)),
            "source_context_hash": .string(stableHash(packet.sourceContext))
        ])
    }

    private func pushStoryBeatUndo(_ board: StoryBeatBoard) {
        storyBeatUndoStack.append(board)
        if storyBeatUndoStack.count > 12 {
            storyBeatUndoStack.removeFirst(storyBeatUndoStack.count - 12)
        }
        storyBeatUndoDepth = storyBeatUndoStack.count
    }

