    private func mediaAnchor(for item: MediaItemRecord, role: StoryMediaAnchorRole) -> StoryMediaAnchor {
        StoryMediaAnchor(
            anchorId: StoryMediaAnchor.anchorId(mediaId: item.mediaId, role: role),
            mediaId: item.mediaId,
            frameId: item.isExtractedVideoFrame ? item.mediaId : "",
            timecode: item.sourceTimestampSeconds.map(mediaAnchorTimecode) ?? "",
            kind: item.isExtractedVideoFrame ? .videoFrame : .image,
            role: role,
            note: mediaAnchorSummary(for: item),
            thumbnailPath: item.thumbnailPath,
            createdBy: "user"
        )
    }

    private func mediaAnchorSummary(for item: MediaItemRecord) -> String {
        if let observation = mediaObservationsById[item.mediaId],
           !observation.plainCaption.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return shortSummaryText(observation.plainCaption, limit: 160)
        }
        let curation = curation(for: item)
        if !curation.notes.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return shortSummaryText(curation.notes, limit: 160)
        }
        return item.relativePath
    }

    private func mediaAnchorTimecode(_ seconds: Double) -> String {
        let totalMillis = max(0, Int((seconds * 1000).rounded()))
        let minutes = totalMillis / 60_000
        let secs = (totalMillis % 60_000) / 1000
        let millis = totalMillis % 1000
        return String(format: "00:%02d:%02d.%03d", minutes, secs, millis)
    }

    private func mediaIds(for anchors: [StoryMediaAnchor], role: StoryMediaAnchorRole) -> [String] {
        uniqueNonEmpty(anchors.filter { $0.role == role }.map(\.mediaId))
    }

    private func markSceneAssetsStale(beatIds: [String], sequenceChanged: Bool) {
        guard let project = currentProject, !sceneAssets.isEmpty else { return }
        let affectedBeatIds = Set(beatIds)
        var changed = false
        var updatedAssets = sceneAssets
        for index in updatedAssets.indices {
            let asset = updatedAssets[index]
            let isBeatAsset = !affectedBeatIds.isEmpty && affectedBeatIds.contains(asset.beatId)
            let isSequenceAsset = sequenceChanged && (asset.assetScope == .global || asset.assetScope == .multiBeat)
            guard isBeatAsset || isSequenceAsset else { continue }
            guard asset.status != .stale && asset.status != .global else { continue }
            updatedAssets[index].status = .stale
            updatedAssets[index].updatedAt = DateFormats.now()
            changed = true
            try? contextStore.saveSceneAsset(updatedAssets[index], for: project)
        }
        if changed {
            sceneAssets = updatedAssets
        }
    }

    private func currentSceneSourceContext() -> SceneSourceContext {
        let projectId = currentProject?.projectId ?? storyBeatBoard.projectId
        if !scenesUseDraftBoard,
           projectStory.hasAcceptedStory {
            let acceptedBoard = storyBeatBoards.first { $0.beatBoardId == projectStory.beatBoardId } ?? storyBeatBoard
            return SceneSourceContext(
                sourceArtifactType: .projectStory,
                sourceArtifactId: projectStory.acceptedStoryId,
                sourceProjectStoryId: projectStory.acceptedStoryId,
                board: acceptedBoard,
                beats: projectStory.beats.filter { !$0.isDeleted }.sorted { $0.order < $1.order }
            )
        }
        let board = storyBeatBoard.projectId.isEmpty
            ? StoryBeatBoard.empty(projectId: projectId)
            : storyBeatBoard
        return SceneSourceContext(
            sourceArtifactType: .beatBoard,
            sourceArtifactId: board.beatBoardId,
            sourceProjectStoryId: "",
            board: board,
            beats: board.visibleBeats
        )
    }

    private func preflightedVideoChain(_ input: VideoChainDocument) -> VideoChainDocument {
        var chain = input
        if chain.providerSelection == .localPromptExport {
            chain.providerSelection = .bestAvailable
            if chain.modelSelection == .promptManifest {
                chain.modelSelection = .auto
            }
        }
        let duration = chain.segments.first?.durationSeconds ?? chain.preset.durationSeconds
        let targetFramesReady = !chain.segments.isEmpty && chain.segments.allSatisfy { $0.targetEndFrameSource.hasFrame }
        let selectedProvider = VideoChainDocument.resolvedProvider(
            requested: chain.providerSelection,
            outputProfile: chain.outputProfile,
            durationSeconds: duration,
            segmentsHaveTargetFrames: targetFramesReady,
            credentialStore: videoCredentialStore
        )
        let capability = VideoProviderCapability.capability(
            for: selectedProvider,
            outputProfile: chain.outputProfile,
            durationSeconds: duration,
            credentialStore: videoCredentialStore
        )
        chain.selectedProviderId = selectedProvider
        chain.selectedModelId = VideoModelSelection.resolved(requested: chain.modelSelection, provider: selectedProvider)
        chain.continuityMode = capability.continuityMode
        var blockers = capability.blockers
        if capability.requiresStartFrame,
           let first = chain.segments.sorted(by: { $0.order < $1.order }).first,
           !first.startFrameSource.hasFrame {
            blockers.append("start_frame_missing_for_clip_1")
        }
        if capability.requiresEndFrame {
            let missing = chain.segments.filter { !$0.targetEndFrameSource.hasFrame }.count
            if missing > 0 {
                blockers.append("target_end_frames_missing:\(missing)")
            }
        }
        chain.preflightBlockers = blockers.uniqued()
        chain.preflightWarnings = capability.warnings
        for index in chain.segments.indices {
            let segment = chain.segments[index]
            if segment.status == .ready, !segment.activeVideoPath.isEmpty {
                continue
            }
            if capability.requiresStartFrame, segment.order == 1, !segment.startFrameSource.hasFrame {
                chain.segments[index].status = .needsStartFrame
            } else if capability.requiresEndFrame, !segment.targetEndFrameSource.hasFrame {
                chain.segments[index].status = .needsEndFrame
            } else {
                chain.segments[index].status = .readyForRender
            }
            chain.segments[index].updatedAt = DateFormats.now()
        }
        chain.renderPackets = chain.segments.map { segment in
            var packetBlockers = capability.blockers
            if capability.requiresStartFrame, segment.order == 1, !segment.startFrameSource.hasFrame {
                packetBlockers.append("start_frame_missing")
            }
            if capability.requiresEndFrame, !segment.targetEndFrameSource.hasFrame {
                packetBlockers.append("target_end_frame_missing")
            }
            return VideoRenderPacket(
                packetId: "vpacket_\(shortHash("\(chain.chainId):\(segment.segmentId):\(selectedProvider.rawValue)", length: 14))",
                chainId: chain.chainId,
                segmentId: segment.segmentId,
                providerId: selectedProvider,
                modelSelection: chain.selectedModelId,
                continuityMode: capability.continuityMode,
                promptText: segment.prompt,
                negativePrompt: segment.negativePrompt,
                startFramePath: segment.startFrameSource.normalizedFramePath.isEmpty ? segment.startFrameSource.framePath : segment.startFrameSource.normalizedFramePath,
                targetEndFramePath: segment.targetEndFrameSource.normalizedFramePath.isEmpty ? segment.targetEndFrameSource.framePath : segment.targetEndFrameSource.normalizedFramePath,
                outputProfile: chain.outputProfile,
                approvalStatus: "not_required",
                renderEligible: packetBlockers.isEmpty,
                renderBlockers: packetBlockers.uniqued()
            )
        }
        if selectedProvider == .bestAvailable || selectedProvider == .localPromptExport {
            chain.status = .readyForApproval
        } else if chain.missingTargetEndFrameCount > 0 {
            chain.status = .needsKeyframes
        } else if !chain.preflightBlockers.isEmpty {
            chain.status = .readyForApproval
        } else if chain.preflightBlockers.isEmpty {
            chain.status = .planned
        }
        chain.updatedAt = DateFormats.now()
        return chain
    }

    private func shouldGenerateVideoSegment(
        _ segment: VideoSegmentDocument,
        index: Int,
        regenerationIndex: Int?,
        rechainDownstream: Bool
    ) -> Bool {
        if let regenerationIndex {
            if rechainDownstream {
                if index < regenerationIndex {
                    return false
                }
                if index > regenerationIndex, segment.locked, hasUsableActiveVideo(segment) {
                    return false
                }
                return true
            }
            return index == regenerationIndex
        }
        return !hasUsableActiveVideo(segment) || segment.status != .ready
    }

    private func hasUsableActiveVideo(_ segment: VideoSegmentDocument) -> Bool {
        let path = segment.activeVideoPath.trimmingCharacters(in: .whitespacesAndNewlines)
        return !path.isEmpty && FileManager.default.fileExists(atPath: path)
    }

    private func nextVideoSegmentVersionNumber(_ segment: VideoSegmentDocument) -> Int {
        (segment.versions.map(\.versionNumber).max() ?? 0) + 1
    }

    private func nextVideoFrameVersionNumber(_ segment: VideoSegmentDocument, role: String) -> Int {
        (segment.frameVersions.filter { $0.role == role }.map(\.versionNumber).max() ?? 0) + 1
    }

    private func preservedVideoBoundarySource(for segment: VideoSegmentDocument, role: String) -> VideoFrameSourceDocument {
        let active = segment.activeVersion
        let activePath = role == "start" ? active?.startFramePath : active?.targetEndFramePath
        let fallbackPath: String
        if role == "start" {
            fallbackPath = segment.startFrameSource.normalizedFramePath.isEmpty
                ? segment.startFrameSource.framePath
                : segment.startFrameSource.normalizedFramePath
        } else {
            fallbackPath = segment.targetEndFrameSource.normalizedFramePath.isEmpty
                ? segment.targetEndFrameSource.framePath
                : segment.targetEndFrameSource.normalizedFramePath
        }
        let cleanedActivePath = activePath?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return VideoFrameSourceDocument(
            type: role == "start" ? .previousSegmentEnd : .actualSegmentEnd,
            framePath: cleanedActivePath.isEmpty ? fallbackPath : cleanedActivePath,
            note: role == "start" ? "Preserved active version start frame" : "Preserved active version target end frame"
        )
    }

    private func targetSourceForVideoGeneration(
        segment: VideoSegmentDocument,
        preserveBoundaries: Bool
    ) throws -> VideoFrameSourceDocument {
        guard preserveBoundaries else {
            return segment.targetEndFrameSource.hasFrame ? segment.targetEndFrameSource : .empty
        }
        if let target = segment.activeVersion?.targetEndFramePath.trimmingCharacters(in: .whitespacesAndNewlines),
           !target.isEmpty,
           FileManager.default.fileExists(atPath: target) {
            return VideoFrameSourceDocument(type: .actualSegmentEnd, framePath: target, note: "Preserved active target end frame")
        }
        if let actual = segment.activeVersion?.actualEndFramePath.trimmingCharacters(in: .whitespacesAndNewlines),
           !actual.isEmpty,
           FileManager.default.fileExists(atPath: actual) {
            return VideoFrameSourceDocument(type: .actualSegmentEnd, framePath: actual, note: "Preserved active actual end frame")
        }
        let configured = segment.targetEndFrameSource.normalizedFramePath.isEmpty
            ? segment.targetEndFrameSource.framePath
            : segment.targetEndFrameSource.normalizedFramePath
        if !configured.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
           FileManager.default.fileExists(atPath: configured) {
            return VideoFrameSourceDocument(type: .actualSegmentEnd, framePath: configured, note: "Preserved configured target end frame")
        }
        throw ScreenGraphError.capture("Clip \(segment.order) needs an existing end frame before boundary-preserving regeneration.")
    }

    private func archiveGeneratedVideoChainFrameVersion(
        _ version: inout VideoFrameVersionDocument,
        chain: VideoChainDocument,
        segment: VideoSegmentDocument,
        project: ProjectRecord
    ) async {
        guard (version.archivedMediaId ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let path = version.displayFramePath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !path.isEmpty else { return }
        let mediaId = generatedVideoChainMediaId(
            project: project,
            chainId: chain.chainId,
            segmentId: segment.segmentId,
            versionId: version.versionId,
            role: version.role,
            derivativeKind: MediaItemRecord.videoChainKeyframeDerivativeKind
        )
        let roleLabel = videoChainFrameRoleLabel(version.role)
        let filename = generatedMediaArchiveFilename(
            base: "\(chain.title) Clip \(segment.order) \(roleLabel) V\(version.versionNumber)",
            path: path,
            fallbackExtension: "png"
        )
        let notes = [
            "Generated \(roleLabel.lowercased()) for \(chain.title), Clip \(segment.order): \(segment.title).",
            version.sourceFilename.isEmpty ? "" : "Source: \(version.sourceFilename).",
            version.modelId.isEmpty ? "" : "Model: \(version.modelId)."
        ]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        if let item = await archiveGeneratedMedia(
            fileURL: URL(fileURLWithPath: path),
            project: project,
            mediaId: mediaId,
            derivativeKind: MediaItemRecord.videoChainKeyframeDerivativeKind,
            sourceMediaId: version.sourceMediaId,
            filename: filename,
            tags: ["generated", "scenes", "video-chain", "keyframe", version.role],
            notes: notes,
            rejectedByDefault: false
        ) {
            version.archivedMediaId = item.mediaId
        }
    }

