    @discardableResult
    private func archiveGeneratedMedia(
        fileURL: URL,
        project: ProjectRecord,
        mediaId: String,
        derivativeKind: String,
        sourceMediaId: String?,
        sourceTimestampSeconds: Double? = nil,
        filename: String,
        tags: [String],
        notes: String,
        rejectedByDefault: Bool
    ) async -> MediaItemRecord? {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return nil }
        do {
            let item = try await store.generatedMediaItem(
                for: fileURL,
                project: project,
                mediaId: mediaId,
                derivativeKind: derivativeKind,
                sourceMediaId: sourceMediaId,
                sourceTimestampSeconds: sourceTimestampSeconds,
                filename: filename
            )
            var updatedItemsById = Dictionary(uniqueKeysWithValues: items.map { ($0.mediaId, $0) })
            updatedItemsById[item.mediaId] = item
            let updatedItems = sortedMediaItems(Array(updatedItemsById.values))
            try store.saveInventory(updatedItems, for: project)

            var updatedCuration = curationById
            let hadCuration = updatedCuration[item.mediaId] != nil
            var curation = updatedCuration[item.mediaId] ?? MediaCurationRecord(mediaId: item.mediaId)
            if !hadCuration {
                curation.rejected = rejectedByDefault
            }
            curation.tags = uniqueNonEmpty(curation.tags + tags)
            if curation.notes.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                curation.notes = notes
            }
            curation.updatedAt = DateFormats.now()
            updatedCuration[item.mediaId] = curation
            try store.saveCuration(updatedCuration, for: project)

            items = updatedItems
            curationById = updatedCuration
            return item
        } catch {
            lastError = "Generated media archive failed: \(error.localizedDescription)"
            return nil
        }
    }

    private func generatedVideoChainMediaId(
        project: ProjectRecord,
        chainId: String,
        segmentId: String,
        versionId: String,
        role: String,
        derivativeKind: String
    ) -> String {
        "genmedia_\(shortHash("\(project.projectId):\(chainId):\(segmentId):\(versionId):\(role):\(derivativeKind)", length: 20))"
    }

    private func videoChainFrameRoleLabel(_ role: String) -> String {
        switch role {
        case "start":
            return "Start Frame"
        case "target_end":
            return "Target End Frame"
        default:
            return role.replacingOccurrences(of: "_", with: " ").capitalized
        }
    }

    private func generatedMediaArchiveFilename(base: String, path: String, fallbackExtension: String) -> String {
        let url = URL(fileURLWithPath: path)
        let ext = url.pathExtension.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? fallbackExtension
            : url.pathExtension
        return "\(stableSlug(base, fallback: "generated_media")).\(ext)"
    }

    private func pruneSegmentVersions(_ segment: inout VideoSegmentDocument, keepCount: Int = 5) {
        let sorted = segment.sortedVersions
        guard sorted.count > keepCount else { return }
        let removable = sorted
            .filter { $0.versionId != segment.activeVersionId }
            .prefix(max(0, sorted.count - keepCount))
        for version in removable {
            let archivedVideoPaths: Set<String> = version.archivedMediaId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? []
                : [version.videoOutputPath, version.normalizedVideoOutputPath]
            let archivedFramePaths: Set<String> = version.actualEndFrameMediaId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? []
                : [version.actualEndFramePath]
            for path in [
                version.videoOutputPath,
                version.normalizedVideoOutputPath,
                version.providerOutputPath,
                version.actualEndFramePath
            ] where !path.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && !archivedVideoPaths.contains(path)
                && !archivedFramePaths.contains(path) {
                try? FileManager.default.removeItem(atPath: path)
            }
            segment.versions.removeAll { $0.versionId == version.versionId }
        }
    }

    private func stitchReadyVideoChain(
        _ chain: inout VideoChainDocument,
        project: ProjectRecord,
        job: VideoGenerationJobDocument?
    ) async throws {
        let clipURLs = chain.segments
            .sorted { $0.order < $1.order }
            .map(\.activeVideoPath)
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .filter { FileManager.default.fileExists(atPath: $0) }
            .map { URL(fileURLWithPath: $0) }
        guard clipURLs.count == chain.segments.count, !clipURLs.isEmpty else { return }
        if var job {
            job.status = .stitching
            job.stage = "stitching"
            job.message = "Stitching final reel"
            job.updatedAt = DateFormats.now()
            if chain.jobs.isEmpty {
                chain.jobs.append(job)
            } else {
                chain.jobs[chain.jobs.count - 1] = job
            }
            try persistVideoChain(chain, for: project)
        }
        let outputURL = contextStore.videoChainStitchedOutputURL(for: project, chainId: chain.chainId)
        _ = try await VideoChainMedia.stitchClips(
            clipURLs: clipURLs,
            outputURL: outputURL,
            workDirectory: contextStore.videoChainExportsDirectory(for: project, chainId: chain.chainId).appendingPathComponent("work", isDirectory: true),
            profile: chain.outputProfile,
            trimDuplicateStartFrames: videoChainStitchTrimFrames(for: chain)
        )
        chain.stitchedOutputPath = outputURL.path
        await archiveGeneratedVideoChainReel(&chain, project: project)
        chain.status = .ready
        chain.updatedAt = DateFormats.now()
    }

    private func framePath(for source: VideoFrameSourceDocument) -> String {
        source.normalizedFramePath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? source.framePath
            : source.normalizedFramePath
    }

    private func videoClipPrompt(
        basePrompt: String,
        segment: VideoSegmentDocument,
        isDownstream: Bool,
        usesNativeExtend: Bool
    ) -> String {
        var lines = [basePrompt.trimmingCharacters(in: .whitespacesAndNewlines)]
        if usesNativeExtend {
            lines.append(
                """
                Continue directly from the supplied prior video. Treat the prior clip as temporal context, not as a scene to repeat. The new extension should move into this clip's described beat and visual setting while preserving subject and style continuity.
                """
            )
        } else if isDownstream {
            lines.append(
                """
                The supplied start frame is only a continuity handoff anchor from the previous clip. Do not linger on or repeat that prior composition; begin moving away from it immediately and reach this clip's described scene within the first second.
                """
            )
        }
        return lines
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: "\n\n")
    }

    private func ltxExtendContextSeconds(for segment: VideoSegmentDocument) -> Double {
        min(
            2.0,
            max(1.0, Double(segment.durationSeconds) * 0.15),
            505.0 / 24.0 - Double(segment.durationSeconds)
        )
    }

    private func ltxNativeExtendSource(for segment: VideoSegmentDocument) -> (path: String, kind: String) {
        if let providerOutputPath = segment.activeVersion?.providerOutputPath.trimmingCharacters(in: .whitespacesAndNewlines),
           !providerOutputPath.isEmpty,
           FileManager.default.fileExists(atPath: providerOutputPath) {
            return (providerOutputPath, "provider_output")
        }
        return (segment.activeVideoPath.trimmingCharacters(in: .whitespacesAndNewlines), "active_clip")
    }

    private func retakePrompt(basePrompt: String, instruction: String) -> String {
        [
            basePrompt.trimmingCharacters(in: .whitespacesAndNewlines),
            "Retake only the selected time range. Preserve the rest of the clip, subject identity, style, and story continuity.",
            instruction.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? "Improve motion clarity and keep the same intended beat."
                : "Operator retake instruction: \(instruction.trimmingCharacters(in: .whitespacesAndNewlines))"
        ]
        .filter { !$0.isEmpty }
        .joined(separator: "\n\n")
    }

    private func markVideoChainDownstreamStale(_ chain: inout VideoChainDocument, fromIndex index: Int) {
        guard index < chain.segments.count - 1 else { return }
        for downstreamIndex in chain.segments.indices where downstreamIndex > index && !chain.segments[downstreamIndex].locked {
            chain.segments[downstreamIndex].status = .stale
            chain.segments[downstreamIndex].downstreamStale = true
            chain.segments[downstreamIndex].updatedAt = DateFormats.now()
        }
        for seamIndex in chain.seams.indices {
            let fromIndex = chain.segments.firstIndex { $0.segmentId == chain.seams[seamIndex].fromSegmentId } ?? 0
            if fromIndex >= index {
                chain.seams[seamIndex].status = .needsRechain
            }
        }
    }

    private func videoChainStitchTrimFrames(for chain: VideoChainDocument) -> Int {
        if chain.selectedProviderId == .ltxDirect,
           chain.segments.dropFirst().contains(where: { $0.activeVersion?.providerOperation == "extend" }) {
            return 0
        }
        switch chain.selectedProviderId {
        case .ltxDirect:
            return 24
        case .civitaiWan:
            return 12
        case .klingImageToVideo, .falImageToVideo, .falAudioToVideo:
            return 3
        case .localExistingClip:
            return 0
        case .bestAvailable, .localPromptExport:
            return 3
        }
    }

    private func persistVideoChain(_ chain: VideoChainDocument, for project: ProjectRecord) throws {
        try contextStore.saveVideoChain(chain, for: project)
        videoChain = chain
        if let index = videoChains.firstIndex(where: { $0.chainId == chain.chainId }) {
            videoChains[index] = chain
        } else {
            videoChains.insert(chain, at: 0)
        }
        videoChains.sort { $0.updatedAt > $1.updatedAt }
        try persistActiveVideoChainSelection(chain.chainId, for: project)
    }

    private func persistActiveVideoChainSelection(_ chainId: String, for project: ProjectRecord) throws {
        let cleanedChainId = chainId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanedChainId.isEmpty else { return }
        var workspace = storyWorkspace
        if workspace.projectId.isEmpty {
            workspace.projectId = project.projectId
        }
        guard workspace.activeVideoChainId != cleanedChainId else { return }
        workspace.activeVideoChainId = cleanedChainId
        workspace.updatedAt = DateFormats.now()
        try contextStore.saveStoryWorkspace(workspace, for: project)
        storyWorkspace = workspace
        touchCurrentProject()
    }

    private func activeLoadedVideoChain(
        _ savedChainId: String?,
        loadedStoryWorkspace: inout StoryWorkspaceDocument,
        project: ProjectRecord
    ) -> VideoChainDocument {
        let savedChainId = savedChainId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !savedChainId.isEmpty,
           let savedChain = videoChains.first(where: { $0.chainId == savedChainId }) {
            return savedChain
        }

        let fallbackChain = videoChains.first(where: { chain in
            chain.status == .ready && videoChainHasExistingStitchedOutput(chain)
        }) ?? videoChains.first

        guard let fallbackChain = fallbackChain else {
            return .empty(projectId: project.projectId)
        }

        if loadedStoryWorkspace.activeVideoChainId != fallbackChain.chainId {
            loadedStoryWorkspace.activeVideoChainId = fallbackChain.chainId
            loadedStoryWorkspace.updatedAt = DateFormats.now()
            try? contextStore.saveStoryWorkspace(loadedStoryWorkspace, for: project)
        }
        return fallbackChain
    }

    private func videoChainHasExistingStitchedOutput(_ chain: VideoChainDocument) -> Bool {
        let path = chain.stitchedOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        return !path.isEmpty && FileManager.default.fileExists(atPath: path)
    }

    private func restoredVideoChainStatus(chain: VideoChainDocument, issueCount: Int) -> String {
        if chain.chainId.isEmpty {
            return issueCount > 0 ? "Video Chain load failed" : "Video Chain idle"
        }
        if issueCount > 0 {
            return "Loaded saved Video Chain with \(issueCount) load issue\(issueCount == 1 ? "" : "s")"
        }
        return chain.status == .ready ? "Loaded saved Video Chain" : "Loaded Video Chain"
    }

    private func refreshVideoChainAfterCredentialChange(status: String) {
        guard let project = currentProject, !videoChain.chainId.isEmpty else {
            videoChainStatus = status
            return
        }
        var chain = videoChain
        chain = preflightedVideoChain(chain)
        chain.updatedAt = DateFormats.now()
        do {
            try persistVideoChain(chain, for: project)
            videoChainStatus = status
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Provider settings changed, but the Video Chain could not be saved"
        }
    }

    private func updateVideoChainFrameSource(segmentId: String, role: String, source: VideoFrameSourceDocument) {
        guard let project = currentProject, !videoChain.chainId.isEmpty else { return }
        var chain = videoChain
        guard let index = chain.segments.firstIndex(where: { $0.segmentId == segmentId }) else { return }
        if role == "start" {
            chain.segments[index].startFrameSource = source
        } else {
            chain.segments[index].targetEndFrameSource = source
        }
        chain.segments[index].updatedAt = DateFormats.now()
        chain = preflightedVideoChain(chain)
        do {
            try persistVideoChain(chain, for: project)
            videoChainStatus = role == "start" ? "Start frame set" : "Target end frame set"
        } catch {
            lastError = error.localizedDescription
            videoChainStatus = "Could not save keyframe"
        }
    }

    private func videoChainFrameSourceKey(segmentId: String, role: String) -> String {
        "\(segmentId)|\(role)"
    }

    private func groupPriority(_ group: VideoFrameSourceCandidateGroup) -> Int {
        switch group {
        case .recommended: 0
        case .nearby: 1
        case .allEnabled: 2
        }
    }

    private func videoFrameSourceCandidate(
        for item: MediaItemRecord,
        group: VideoFrameSourceCandidateGroup,
        labels: [String]
    ) -> VideoFrameSourceCandidate {
        VideoFrameSourceCandidate(
            mediaId: item.mediaId,
            group: group,
            filename: item.filename,
            relativePath: item.relativePath,
            thumbnailPath: item.thumbnailPath,
            sourcePath: videoChainFrameSourceInputURL(for: item).path,
            kind: item.kind,
            width: item.width,
            height: item.height,
            sourceTimestampSeconds: item.sourceTimestampSeconds,
            provenanceLabels: uniqueNonEmpty(labels)
        )
    }

    private func sourceMediaLabelsById(
        for beats: [StoryBeatBoardBeat],
        prefix: String
    ) -> [String: [String]] {
        var labelsById: [String: [String]] = [:]
        func append(_ label: String, mediaId: String) {
            let cleaned = mediaId.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !cleaned.isEmpty else { return }
            labelsById[cleaned, default: []].append(label)
        }
        for beat in beats {
            let beatName = beat.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? "Beat \(beat.order)"
                : beat.title
            for anchor in beat.mediaAnchors {
                append("\(prefix) · \(anchor.role.label) · \(beatName)", mediaId: anchor.mediaId)
            }
            for mediaId in beat.sourceMediaIds {
                append("\(prefix) · Source · \(beatName)", mediaId: mediaId)
            }
            for mediaId in beat.referenceMediaIds {
                append("\(prefix) · Reference · \(beatName)", mediaId: mediaId)
            }
        }
        return labelsById.mapValues(uniqueNonEmpty)
    }

    private func allEnabledCandidateLabels(for item: MediaItemRecord) -> [String] {
        var labels = [item.isExtractedVideoFrame ? "Video frame" : "Enabled media"]
        if item.isExtractedVideoFrame,
           let sourceMediaId = item.sourceMediaId {
            let sourceName = items.first { $0.mediaId == sourceMediaId }?.filename ?? sourceMediaId
            let timestamp = item.sourceTimestampSeconds.map { " at \(durationLabel($0))" } ?? ""
            labels.append("\(sourceName)\(timestamp)")
        }
        return labels
    }

    private func videoChainFrameSourceInput(
        for item: MediaItemRecord,
        project: ProjectRecord,
        chainId: String,
        segmentId: String,
        role: String
    ) throws -> MediaObservationInput {
        let inputURL = videoChainFrameSourceInputURL(for: item)
        return try normalizedVideoChainOpenAIImageInput(
            sourceURL: inputURL,
            project: project,
            chainId: chainId,
            segmentId: segmentId,
            role: role,
            sourceId: item.mediaId,
            fallbackWidth: item.width,
            fallbackHeight: item.height
        )
    }

    private func videoChainFrameSourceInput(
        for url: URL,
        project: ProjectRecord,
        chainId: String,
        segmentId: String,
        role: String
    ) throws -> MediaObservationInput {
        try normalizedVideoChainOpenAIImageInput(
            sourceURL: url,
            project: project,
            chainId: chainId,
            segmentId: segmentId,
            role: role,
            sourceId: url.deletingPathExtension().lastPathComponent,
            fallbackWidth: 0,
            fallbackHeight: 0
        )
    }

    private func normalizedVideoChainOpenAIImageInput(
        sourceURL: URL,
        project: ProjectRecord,
        chainId: String,
        segmentId: String,
        role: String,
        sourceId: String,
        fallbackWidth: Int,
        fallbackHeight: Int
    ) throws -> MediaObservationInput {
        let normalized = try normalizedOpenAIImageEditJPEGData(sourceURL: sourceURL)
        let createdAt = DateFormats.now()
        let outputURL = try contextStore.saveNormalizedVideoChainOpenAIInput(
            data: normalized.data,
            for: project,
            chainId: chainId,
            segmentId: segmentId,
            role: role,
            sourceId: sourceId,
            createdAt: createdAt
        )
        return MediaObservationInput(
            data: normalized.data,
            url: outputURL,
            mimeType: "image/jpeg",
            sha256: sha256Hex(normalized.data),
            width: normalized.width == 0 ? fallbackWidth : normalized.width,
            height: normalized.height == 0 ? fallbackHeight : normalized.height
        )
    }

    private func normalizedOpenAIImageEditJPEGData(sourceURL: URL) throws -> (data: Data, width: Int, height: Int) {
        let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithURL(sourceURL as CFURL, sourceOptions) else {
            throw ScreenGraphError.capture("Could not load source image for OpenAI edit at \(sourceURL.path).")
        }
        let thumbnailOptions = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: 2048
        ] as CFDictionary
        guard let decoded = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions) else {
            throw ScreenGraphError.capture("Could not decode source image for OpenAI edit at \(sourceURL.path).")
        }
        let width = decoded.width
        let height = decoded.height
        guard width > 0, height > 0 else {
            throw ScreenGraphError.capture("Source image has invalid dimensions for OpenAI edit.")
        }
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB()
        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            throw ScreenGraphError.capture("Could not create OpenAI edit input normalization canvas.")
        }
        let rect = CGRect(x: 0, y: 0, width: width, height: height)
        context.setFillColor(NSColor.black.cgColor)
        context.fill(rect)
        context.interpolationQuality = .high
        context.draw(decoded, in: rect)
        guard let rendered = context.makeImage() else {
            throw ScreenGraphError.capture("Could not create normalized OpenAI edit input image.")
        }
        let data = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(data, UTType.jpeg.identifier as CFString, 1, nil) else {
            throw ScreenGraphError.invalidImageDestination
        }
        let options = [kCGImageDestinationLossyCompressionQuality: 0.90] as CFDictionary
        CGImageDestinationAddImage(destination, rendered, options)
        guard CGImageDestinationFinalize(destination) else {
            throw ScreenGraphError.invalidImageDestination
        }
        return (data as Data, width, height)
    }

    private func videoChainFrameSourceInputURL(for item: MediaItemRecord) -> URL {
        let sourceURL = URL(fileURLWithPath: item.path)
        let thumbnailURL = URL(fileURLWithPath: item.thumbnailPath)
        if item.kind == .image,
           isSupportedImageEditInput(sourceURL),
           FileManager.default.fileExists(atPath: sourceURL.path) {
            return sourceURL
        }
        if FileManager.default.fileExists(atPath: thumbnailURL.path) {
            return thumbnailURL
        }
        return sourceURL
    }

    private func isSupportedImageEditInput(_ url: URL) -> Bool {
        switch url.pathExtension.lowercased() {
        case "jpg", "jpeg", "png", "webp":
            return true
        default:
            return false
        }
    }

    private func videoChainFrameEditPrompt(
        segment: VideoSegmentDocument,
        role: String,
        sourceItem: MediaItemRecord
    ) -> String {
        let context = currentSceneSourceContext()
        let beats = context.beats.filter { segment.sourceBeatIds.contains($0.beatId) }
        let cues = storyAestheticCues()
        let roleLabel = role == "start" ? "opening start frame" : "target ending frame"
        let beatSummary = beats
            .map { beat in
                [
                    beat.title,
                    beat.event,
                    beat.visualMoment,
                    beat.emotionalTurn,
                    beat.meaningMove
                ]
                .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                .joined(separator: " | ")
            }
            .joined(separator: "\n")
        var lines: [String] = [
            "Create a single \(roleLabel) for a generated video clip.",
            "Use the supplied source image as concrete visual provenance, preserving recognizable subject matter where appropriate while composing a production-ready still.",
            "Clip title: \(segment.title)",
            "Clip prompt: \(shortTailText(segment.prompt, limit: 900))"
        ]
        if !segment.motionDirective.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Motion intent: \(segment.motionDirective)")
        }
        if !beatSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Story beats:\n\(shortTailText(beatSummary, limit: 900))")
        }
        if !projectAestheticBrief.styleContract.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Accepted aesthetic: \(shortTailText(projectAestheticBrief.styleContract, limit: 700))")
        }
        if !cues.presentationCues.isEmpty {
            lines.append("Visual treatment cues: \(cues.presentationCues.prefix(12).joined(separator: ", "))")
        }
        if !cues.paletteCues.isEmpty {
            lines.append("Palette cues: \(cues.paletteCues.prefix(10).joined(separator: ", "))")
        }
        if !cues.avoidCues.isEmpty || !segment.negativePrompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let avoid = uniqueNonEmpty(cues.avoidCues + [segment.negativePrompt])
            lines.append("Avoid: \(avoid.prefix(12).joined(separator: ", "))")
        }
        lines.append("Source media: \(sourceItem.filename)")
        lines.append("Do not add captions, subtitles, UI, watermarks, or text overlays.")
        lines.append("Make the image feel like a deliberate still frame from this clip, ready to be used as a video-generation keyframe.")
        return lines.joined(separator: "\n")
    }

    private func videoChainFrameAssistantPrompt(
        segment: VideoSegmentDocument,
        role: String,
        instruction: String,
        sourceNote: String
    ) -> String {
        let roleLabel = role == "start" ? "opening start frame" : "target ending frame"
        var lines = videoChainFrameContextLines(segment: segment, roleLabel: roleLabel)
        lines.insert("Regenerate a single \(roleLabel) from the supplied current frame.", at: 0)
        lines.append("Current frame note: \(sourceNote.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Existing generated frame" : sourceNote)")
        lines.append("Operator instruction: \(instruction)")
        lines.append("Use the current frame as visual provenance, but make a meaningfully new version that follows the operator instruction.")
        lines.append("Do not add captions, subtitles, UI, watermarks, or text overlays.")
        lines.append("Return one production-ready keyframe still.")
        return lines.joined(separator: "\n")
    }

    private func videoChainEndFrameFromStartPrompt(segment: VideoSegmentDocument) -> String {
        var lines = videoChainFrameContextLines(segment: segment, roleLabel: "target ending frame")
        lines.insert("Create a single target ending frame for this video clip using the supplied start frame as visual provenance.", at: 0)
        lines.append("The result should feel like the natural endpoint of the clip's story beat, not a duplicate of the opening frame.")
        lines.append("Preserve recognizable subject matter and style continuity from the start frame while changing pose, action, composition, or revealed story evidence to fit the ending moment.")
        lines.append("Do not add captions, subtitles, UI, watermarks, or text overlays.")
        lines.append("Return one production-ready target end keyframe still for WAN keyframed video generation.")
        return lines.joined(separator: "\n")
    }

    private func videoChainFrameContextLines(segment: VideoSegmentDocument, roleLabel: String) -> [String] {
        let context = currentSceneSourceContext()
        let beats = context.beats.filter { segment.sourceBeatIds.contains($0.beatId) }
        let cues = storyAestheticCues()
        let beatSummary = beats
            .map { beat in
                [
                    beat.title,
                    beat.event,
                    beat.visualMoment,
                    beat.emotionalTurn,
                    beat.meaningMove,
                    "Action: \(beat.generationBrief.action)",
                    "Setting: \(beat.generationBrief.setting)",
                    "Treatment: \(beat.generationBrief.aestheticTreatment)"
                ]
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
                .joined(separator: " | ")
            }
            .joined(separator: "\n")
        var lines: [String] = [
            "Frame role: \(roleLabel)",
            "Clip title: \(segment.title)",
            "Clip prompt: \(shortTailText(segment.prompt, limit: 900))"
        ]
        if !segment.motionDirective.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Motion intent: \(segment.motionDirective)")
        }
        if !beatSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Story beats:\n\(shortTailText(beatSummary, limit: 900))")
        }
        if !projectAestheticBrief.styleContract.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.append("Accepted aesthetic: \(shortTailText(projectAestheticBrief.styleContract, limit: 700))")
        }
        if !cues.presentationCues.isEmpty {
            lines.append("Visual treatment cues: \(cues.presentationCues.prefix(12).joined(separator: ", "))")
        }
        if !cues.paletteCues.isEmpty {
            lines.append("Palette cues: \(cues.paletteCues.prefix(10).joined(separator: ", "))")
        }
        if !cues.avoidCues.isEmpty || !segment.negativePrompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let avoid = uniqueNonEmpty(cues.avoidCues + [segment.negativePrompt])
            lines.append("Avoid: \(avoid.prefix(12).joined(separator: ", "))")
        }
        return lines
    }

    private func firstSourceMediaFrame(for segment: VideoSegmentDocument) -> VideoFrameSourceDocument? {
        let context = currentSceneSourceContext()
        let beats = context.beats.filter { segment.sourceBeatIds.contains($0.beatId) }
        let anchorIds = beats.flatMap { beat in
            beat.mediaAnchors.map(\.mediaId) + beat.sourceMediaIds + beat.referenceMediaIds
        }
        let candidates = mediaItems(for: anchorIds.uniqued())
        for item in candidates {
            let path: String
            if item.kind == .image, FileManager.default.fileExists(atPath: item.path) {
                path = item.path
            } else if FileManager.default.fileExists(atPath: item.thumbnailPath) {
                path = item.thumbnailPath
            } else {
                continue
            }
            return VideoFrameSourceDocument(
                type: .sourceMedia,
                mediaId: item.mediaId,
                framePath: path,
                note: item.filename
            )
        }
        return nil
    }

    private func normalizedFrameURL(
        for source: VideoFrameSourceDocument,
        chain: VideoChainDocument,
        segment: VideoSegmentDocument,
        role: String,
        project: ProjectRecord,
        versionId: String = ""
    ) throws -> URL {
        if !source.normalizedFramePath.isEmpty, FileManager.default.fileExists(atPath: source.normalizedFramePath) {
            return URL(fileURLWithPath: source.normalizedFramePath)
        }
        let rawPath = source.framePath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !rawPath.isEmpty, FileManager.default.fileExists(atPath: rawPath) else {
            throw ScreenGraphError.capture("\(role == "start" ? "Start" : "Target end") frame is missing for Clip \(segment.order).")
        }
        let outputDirectory = versionId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? contextStore.videoChainKeyframesDirectory(for: project, chainId: chain.chainId)
            : contextStore.videoChainVersionKeyframesDirectory(for: project, chainId: chain.chainId, segmentId: segment.segmentId)
        let filename = versionId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "\(safeIdentifier(segment.segmentId))_\(safeIdentifier(role))_normalized.png"
            : "\(safeIdentifier(segment.segmentId))_\(safeIdentifier(role))_\(safeIdentifier(versionId))_normalized.png"
        let outputURL = outputDirectory.appendingPathComponent(filename)
        return try VideoChainMedia.normalizeImageFrame(
            sourceURL: URL(fileURLWithPath: rawPath),
            outputURL: outputURL,
            profile: chain.outputProfile,
            fitPolicy: role == "start" ? chain.outputProfile.fitPolicy : .centerCrop
        )
    }

    private func videoChainMarkdown(_ chain: VideoChainDocument) -> String {
        var lines: [String] = [
            "# \(chain.title.isEmpty ? "Video Chain" : chain.title)",
            "",
            "- Chain ID: `\(chain.chainId)`",
            "- Source: `\(chain.sourceArtifactType.rawValue)` / `\(chain.sourceArtifactId)`",
            "- Provider: `\(chain.selectedProviderId.rawValue)`",
            "- Model: `\((chain.selectedModelId ?? chain.modelSelection ?? .auto).rawValue)`",
            "- Continuity: `\(chain.continuityMode.rawValue)`",
            "- Output: \(chain.outputProfile.label)",
            "- Status: `\(chain.status.rawValue)`",
            ""
        ]
        if !chain.preflightBlockers.isEmpty {
            lines.append("## Blockers")
            lines.append(contentsOf: chain.preflightBlockers.map { "- `\($0)`" })
            lines.append("")
        }
        lines.append("## Segments")
        for segment in chain.segments.sorted(by: { $0.order < $1.order }) {
            lines.append("### \(String(format: "%02d", segment.order)) \(segment.title)")
            lines.append("- Beats: \(segment.sourceBeatIds.joined(separator: ", "))")
            lines.append("- Duration: \(segment.durationSeconds)s")
            lines.append("- Status: `\(segment.status.rawValue)`")
            lines.append("- Start frame: \(segment.startFrameSource.framePath.isEmpty ? "missing" : segment.startFrameSource.framePath)")
            if chain.requiresTargetEndFrames || segment.targetEndFrameSource.hasFrame {
                lines.append("- Target end frame: \(segment.targetEndFrameSource.framePath.isEmpty ? "missing" : segment.targetEndFrameSource.framePath)")
            }
            if !segment.actualEndFramePath.isEmpty {
                lines.append("- Actual end frame: \(segment.actualEndFramePath)")
            }
            lines.append("")
            lines.append("```text")
            lines.append(segment.prompt)
            lines.append("```")
            lines.append("")
        }
        return lines.joined(separator: "\n")
    }

    private func setStoryBeatOperation(
        beatId: String,
        phase: StoryBeatOperationPhase,
        errorMessage: String = ""
    ) {
        let key = beatId.isEmpty ? storyBeatBoard.beatBoardId : beatId
        if phase == .idle {
            storyBeatOperationStatesByBeatId[key] = nil
            return
        }
        storyBeatOperationStatesByBeatId[key] = StoryBeatOperationState(
            beatId: key,
            phase: phase,
            startedAt: DateFormats.now(),
            errorMessage: errorMessage
        )
    }

    private func runStoryBeatBoardEdit(
        beatId: String,
        phase: StoryBeatOperationPhase,
        operation: String,
        intent: String,
        outputMode: StoryBeatEditOutputMode
    ) async {
        guard let project = currentProject else { return }
        setStoryBeatOperation(beatId: beatId, phase: phase)
        do {
            let outputBoardId: String
            switch outputMode {
            case .applyToActiveBoard:
                outputBoardId = storyBeatBoard.beatBoardId
            case .newBoardVersion:
                outputBoardId = "board_\(shortHash("\(project.projectId):\(operation):\(storyBeatBoard.beatBoardId):\(DateFormats.now())", length: 14))"
            }
            let editedBoard = try await storyBeatBoardEditResult(
                beatId: beatId,
                operation: operation,
                intent: intent,
                outputBeatBoardId: outputBoardId
            )
            pushStoryBeatUndo(storyBeatBoard)
            try persistStoryBeatBoard(
                editedBoard,
                project: project,
                status: outputMode == .newBoardVersion ? "Story Beat Board version ready" : "Story Beat Board edited"
            )
            let changedBeatIds = editedBoard.visibleBeats.map(\.beatId)
            markSceneAssetsStale(beatIds: changedBeatIds, sequenceChanged: outputMode == .newBoardVersion || operation.contains("split"))
            setStoryBeatOperation(beatId: beatId, phase: .idle)
        } catch {
            setStoryBeatOperation(beatId: beatId, phase: .failed, errorMessage: error.localizedDescription)
            lastError = error.localizedDescription
            storyStatus = "Story Beat edit failed"
        }
    }

    private func storyBeatBoardEditResult(
        beatId: String,
        operation: String,
        intent: String,
        outputBeatBoardId: String
    ) async throws -> StoryBeatBoard {
        guard let project = currentProject else {
            throw ScreenGraphError.capture("Create or select a project first.")
        }
        guard storyBeatBoard.hasBeats else {
            throw ScreenGraphError.capture("Generate a Beat Board first.")
        }
        if !beatId.isEmpty, let beat = storyBeatBoard.beats.first(where: { $0.beatId == beatId }), beat.locked {
            throw ScreenGraphError.capture("Locked beats cannot be edited.")
        }
        let packet = storyPromptPacket(signals: storySignalsFreshness == .fresh ? storySignals : StorySignalSet.empty(projectId: project.projectId))
        let sourceDirections = storyBeatBoard.sourceDirectionIds.compactMap { sourceId in
            storyDirectionSet.directions.first { $0.directionId == sourceId }
        }
        let context = StoryBeatBoardEditContext(
            projectId: project.projectId,
            projectName: project.name,
            operation: operation,
            intent: intent,
            selectedBeatId: beatId,
            outputBeatBoardId: outputBeatBoardId,
            generatedAt: DateFormats.now(),
            activeBoardJSON: encodedActiveBeatBoard(),
            sourceDirectionsJSON: sourceDirections.isEmpty ? "" : encodedStoryDirections(sourceDirections),
            promptPacketJSON: encodedStoryPromptPacket(packet)
        )
        let result = try await OpenAIClient.fromEnvironment().editStoryBeatBoard(context: context)
        var board = normalizedEditedStoryBeatBoard(
            result.beatBoard,
            sourceBoard: storyBeatBoard,
            outputBoardId: outputBeatBoardId,
            generatedAt: context.generatedAt,
            model: result.model,
            responseId: result.responseId
        )
        try validateEditedStoryBeatBoard(board)
        board.validationWarnings = StoryValidation.commercialWarnings(board: board, setup: storySetup)
            + StoryValidation.aestheticMismatchWarnings(board: board, cues: storyAestheticCues())
        return board
    }

    private func normalizedEditedStoryBeatBoard(
        _ input: StoryBeatBoard,
        sourceBoard: StoryBeatBoard,
        outputBoardId: String,
        generatedAt: String,
        model: String,
        responseId: String
    ) -> StoryBeatBoard {
        var board = input
        board.schemaVersion = "litscenes.story_beat_board.v0.3"
        board.projectId = sourceBoard.projectId
        board.beatBoardId = outputBoardId
        board.parentDirectionSetId = sourceBoard.parentDirectionSetId
        board.parentDirectionId = sourceBoard.parentDirectionId
        board.primaryDirectionId = sourceBoard.primaryDirectionId
        board.sourceDirectionIds = sourceBoard.sourceDirectionIds
        board.storySetupHash = sourceBoard.storySetupHash
        board.readyLensSetHash = sourceBoard.readyLensSetHash
        board.lensRowSnapshots = sourceBoard.lensRowSnapshots
        board.aestheticRecipeVersion = sourceBoard.aestheticRecipeVersion
        board.isActiveDraft = true
        board.inputFingerprint = sourceBoard.inputFingerprint
        board.generator = "openai"
        board.model = model
        board.responseId = responseId
        board.generatedAt = generatedAt
        board.updatedAt = DateFormats.now()
        board.artifactStatus = .fresh
        let lockedById = Dictionary(uniqueKeysWithValues: sourceBoard.beats.filter(\.locked).map { ($0.beatId, $0) })
        board.beats = board.beats
            .filter { !$0.beatId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .sorted { $0.order < $1.order }
            .enumerated()
            .map { index, beat in
                var updated = beat
                if let locked = lockedById[beat.beatId] {
                    updated = locked
                }
                updated.order = index + 1
                updated.validationWarnings = StoryValidation.beatWarnings(updated)
                if updated.sourceMediaIds.isEmpty {
                    updated.sourceMediaIds = mediaIds(for: updated.mediaAnchors, role: .source)
                }
                if updated.avoidMediaIds.isEmpty {
                    updated.avoidMediaIds = mediaIds(for: updated.mediaAnchors, role: .avoid)
                }
                if updated.referenceMediaIds.isEmpty {
                    updated.referenceMediaIds = mediaIds(for: updated.mediaAnchors, role: .reference)
                }
                if updated.lensRowSnapshots.isEmpty {
                    updated.lensRowSnapshots = sourceBoard.lensRowSnapshots
                }
                return updated
            }
        for locked in sourceBoard.beats where locked.locked && !board.beats.contains(where: { $0.beatId == locked.beatId }) {
            board.beats.append(locked)
        }
        board.beats = renumberStoryBeats(board.visibleBeats) + board.beats.filter(\.isDeleted)
        board.status = outputBoardId == sourceBoard.beatBoardId ? "edited" : "ready"
        return board
    }

    private func validateEditedStoryBeatBoard(_ board: StoryBeatBoard) throws {
        let visible = board.visibleBeats
        guard visible.count >= 1 else {
            throw ScreenGraphError.openAI("Edited Beat Board contains no visible beats.")
        }
        let failures = visible.flatMap { beat in
            StoryValidation.beatWarnings(beat).map { "\(beat.title): \($0)" }
        }
        guard failures.isEmpty else {
            throw ScreenGraphError.openAI("Edited Beat Board failed validation: \(failures.prefix(5).joined(separator: "; "))")
        }
    }

    private func refreshedSceneAsset(
        existing: SceneAssetDocument?,
        draft: SceneAssetDocument,
        refreshPrompts: Bool
    ) -> SceneAssetDocument {
        guard var existing else { return draft }
        existing.sourceArtifactType = draft.sourceArtifactType
        existing.sourceArtifactId = draft.sourceArtifactId
        existing.sourceProjectStoryId = draft.sourceProjectStoryId
        existing.sourceBeatBoardId = draft.sourceBeatBoardId
        existing.sourceBeatIds = draft.sourceBeatIds
        existing.sourceMediaIds = draft.sourceMediaIds
        existing.avoidMediaIds = draft.avoidMediaIds
        existing.referenceMediaIds = draft.referenceMediaIds
        existing.mediaAnchors = draft.mediaAnchors
        existing.sourceBeatFingerprint = draft.sourceBeatFingerprint
        existing.sourceBoardFingerprint = draft.sourceBoardFingerprint
        existing.sourceFingerprint = draft.sourceFingerprint
        existing.promptTemplateVersion = draft.promptTemplateVersion
        if refreshPrompts && !existing.isManuallyEdited {
            existing.prompt = draft.prompt
            existing.negativePrompt = draft.negativePrompt
            existing.textOverlay = draft.textOverlay
            existing.captionDraft = draft.captionDraft
            existing.lastAutoPrompt = draft.lastAutoPrompt
            existing.status = draft.status
        } else if existing.status == .missing {
            existing.status = draft.status
        }
        existing.updatedAt = DateFormats.now()
        return existing
    }

    private func audioDecoratedSceneAsset(_ asset: SceneAssetDocument, beat: StoryBeatBoardBeat) -> SceneAssetDocument {
        var updated = asset
        let matchingTracks = storyAudioTracks.tracks.filter { track in
            let ids = track.sourceBeatIds ?? []
            return ids.contains(beat.beatId) || track.targetBeatId == beat.beatId
        }
        guard let track = matchingTracks.first else {
            updated.status = .missing
            return updated
        }
        updated.prompt = track.beatPrompt.isEmpty ? updated.prompt : track.beatPrompt
        updated.textOverlay = track.voiceText
        updated.captionDraft = track.title
        updated.sourceBeatIds = track.sourceBeatIds ?? [beat.beatId]
        updated.targetBeatId = track.targetBeatId ?? beat.beatId
        updated.assetScope = updated.sourceBeatIds.count > 1 ? .multiBeat : .beat
        if let mixPath = track.mixAsset?.path, !mixPath.isEmpty {
            updated.outputPaths = [mixPath]
        }
        switch track.status {
        case "ready":
            updated.status = track.hasMix ? .ready : .draft
        case "failed":
            updated.status = .failed
        case "drafted":
            updated.status = .draft
        default:
            updated.status = .draft
        }
        return updated
    }

    private func scenePromptMarkdown(document: ScenePromptExportDocument, beats: [StoryBeatBoardBeat]) -> String {
        var lines: [String] = [
            "# Scene Prompts",
            "",
            "- project_id: \(document.projectId)",
            "- source_artifact_type: \(document.sourceArtifactType.rawValue)",
            "- source_artifact_id: \(document.sourceArtifactId)",
            "- source_project_story_id: \(document.sourceProjectStoryId)",
            "- source_beat_board_id: \(document.sourceBeatBoardId)",
            "- source_board_fingerprint: \(document.sourceBoardFingerprint)",
            "- exported_at: \(document.exportedAt)",
            ""
        ]
        for beat in beats {
            lines.append("## \(String(format: "%02d", beat.order)) \(beat.title)")
            lines.append("")
            lines.append("Function: \(beat.storyFunction)")
            lines.append("")
            for layer in document.layers.filter({ $0.beatId == beat.beatId }) {
                lines.append("### \(layer.layerType.label)")
                lines.append("")
                lines.append("- layer_id: \(layer.layerId)")
                lines.append("- status: \(layer.status.rawValue)")
                lines.append("- manually_edited: \(layer.isManuallyEdited)")
                lines.append("- prompt_template_version: \(layer.promptTemplateVersion)")
                lines.append("- source_beat_fingerprint: \(layer.sourceBeatFingerprint)")
                lines.append("")
                if !layer.prompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    lines.append("Prompt:")
                    lines.append("")
                    lines.append(layer.prompt)
                    lines.append("")
                }
                if !layer.negativePrompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    lines.append("Negative Prompt:")
                    lines.append("")
                    lines.append(layer.negativePrompt)
                    lines.append("")
                }
                if !layer.textOverlay.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    lines.append("Overlay: \(layer.textOverlay)")
                    lines.append("")
                }
                if !layer.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    lines.append("Caption: \(layer.captionDraft)")
                    lines.append("")
                }
            }
        }
        return lines.joined(separator: "\n")
    }

    private func uniqueNonEmpty(_ values: [String]) -> [String] {
        var seen: Set<String> = []
        var result: [String] = []
        for value in values {
            let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { continue }
            let key = trimmed.lowercased()
            guard !seen.contains(key) else { continue }
            seen.insert(key)
            result.append(trimmed)
        }
        return result
    }

    private func sortedContentItems(_ mediaItems: [MediaItemRecord]) -> [MediaItemRecord] {
        sortedMediaItems(mediaItems)
    }

    private func sortedMediaItems(_ mediaItems: [MediaItemRecord]) -> [MediaItemRecord] {
        mediaItems.sorted(by: mediaSortPrecedes)
    }

    private func sortedVideoSourceItems(_ mediaItems: [MediaItemRecord]) -> [MediaItemRecord] {
        let sourceIndexById = Dictionary(uniqueKeysWithValues: sources.enumerated().map { ($0.element.sourceId, $0.offset) })
        let sourceAddedAtById = Dictionary(uniqueKeysWithValues: sources.map { ($0.sourceId, $0.addedAt) })

        return mediaItems.sorted { lhs, rhs in
            let lhsAddedAt = sourceAddedAtById[lhs.sourceId] ?? ""
            let rhsAddedAt = sourceAddedAtById[rhs.sourceId] ?? ""
            if lhsAddedAt != rhsAddedAt {
                return lhsAddedAt > rhsAddedAt
            }

            let lhsSourceIndex = sourceIndexById[lhs.sourceId] ?? -1
            let rhsSourceIndex = sourceIndexById[rhs.sourceId] ?? -1
            if lhsSourceIndex != rhsSourceIndex {
                return lhsSourceIndex > rhsSourceIndex
            }

            return mediaSortPrecedes(lhs, rhs)
        }
    }

    private func deduplicatedMediaItems(_ mediaItems: [MediaItemRecord]) -> [MediaItemRecord] {
        var itemsById: [String: MediaItemRecord] = [:]
        for item in mediaItems {
            itemsById[item.mediaId] = item
        }
        return Array(itemsById.values)
    }

    private func sortedFrameItems(_ mediaItems: [MediaItemRecord]) -> [MediaItemRecord] {
        mediaItems.sorted { lhs, rhs in
            if lhs.sourceTimestampSeconds != rhs.sourceTimestampSeconds {
                return (lhs.sourceTimestampSeconds ?? 0) < (rhs.sourceTimestampSeconds ?? 0)
            }
            return (lhs.frameIndex ?? 0) < (rhs.frameIndex ?? 0)
        }
    }

    private func mediaSortPrecedes(_ lhs: MediaItemRecord, _ rhs: MediaItemRecord) -> Bool {
        if lhs.modifiedAt == rhs.modifiedAt {
            return lhs.filename.localizedStandardCompare(rhs.filename) == .orderedAscending
        }
        return lhs.modifiedAt > rhs.modifiedAt
    }

    private func enabledStoryItems() -> [MediaItemRecord] {
        sortedContentItems(items.filter { item in
            item.canBeEnabledContent && !curation(for: item).rejected
        })
    }

    private func storyMediaScopeSummary(items scopedItems: [MediaItemRecord]) -> String {
        guard !scopedItems.isEmpty else { return "" }
        return scopedItems.prefix(80).map { item in
            let curation = curation(for: item)
            let state = curation.rejected ? "disabled" : "enabled"
            let tags = curation.tags.isEmpty ? "" : " tags=\(curation.tags.prefix(6).joined(separator: ", "))"
            let notes = curation.notes.trimmingCharacters(in: .whitespacesAndNewlines)
            let noteText = notes.isEmpty ? "" : " notes=\(notes)"
            let duration = item.durationSeconds.map { " duration=\(durationLabel($0))" } ?? ""
            let frameSource = frameSourceSummary(for: item)
            let observation = observationSummary(for: item)
            return "- media_id=\(item.mediaId) kind=\(item.kind.rawValue) file=\(item.relativePath) size=\(item.width)x\(item.height)\(duration)\(frameSource) state=\(state)\(tags)\(noteText)\(observation)"
        }
        .joined(separator: "\n")
    }

    private func mediaArchiveSummary() -> String {
        guard !items.isEmpty else { return "" }
        let imageCount = items.filter { $0.kind == .image }.count
        let videoCount = items.filter { $0.kind == .video }.count
        let disabled = items.filter { curation(for: $0).rejected }.count
        let observed = items.filter { mediaObservationsById[$0.mediaId] != nil }.count
        let sampleItems = items.prefix(32).map { item in
            let curation = curation(for: item)
            var tags: [String] = []
            if curation.rejected { tags.append("disabled") }
            tags.append(contentsOf: curation.tags.prefix(4))
            let tagText = tags.isEmpty ? "" : " [\(tags.joined(separator: ", "))]"
            let duration = item.durationSeconds.map { " \(durationLabel($0))" } ?? ""
            return "- \(item.kind.rawValue): \(item.relativePath)\(duration)\(frameSourceSummary(for: item))\(tagText)\(observationSummary(for: item))"
        }
        .joined(separator: "\n")

        let notes = curationById.values
            .filter { !$0.notes.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .prefix(10)
            .map { "- \($0.notes.trimmingCharacters(in: .whitespacesAndNewlines))" }
            .joined(separator: "\n")

        return """
        Counts: \(imageCount) images, \(videoCount) videos, \(disabled) disabled, \(observed) analyzed.
        Sample media:
        \(sampleItems)
        \(notes.isEmpty ? "" : "\nCuration notes:\n\(notes)")
        """
    }

    /// The MOODBOARD analysis packet for the GOAL interview: one line per analyzed
    /// enabled asset carrying its meaning-bearing cues (mood, palette, motifs, place,
    /// era, possible meanings) so the agent can reason moodboard evidence against the
    /// meaning choice index when hydrating meaning_node_refs / aesthetic_term_refs.
    /// Compact by design: 16 assets, capped cue lists, omitted count on the tail.
    private func goalMoodboardAnalysisContext() -> String {
        let analyzed = enabledContentItems.compactMap { item -> (item: MediaItemRecord, observation: ImageObservationResult)? in
            guard let observation = mediaObservationsById[item.mediaId] else { return nil }
            return (item, observation)
        }
        guard !analyzed.isEmpty else { return "" }
        let limit = 16
        var lines = analyzed.prefix(limit).map { entry -> String in
            let observation = entry.observation
            var parts: [String] = []
            let caption = observation.plainCaption.trimmed
            if !caption.isEmpty {
                parts.append("caption=\(shortSummaryText(caption, limit: 140))")
            }
            if !observation.mood.isEmpty {
                parts.append("mood=\(observation.mood.prefix(3).joined(separator: ", "))")
            }
            if !observation.paletteTerms.isEmpty {
                parts.append("palette=\(observation.paletteTerms.prefix(4).joined(separator: ", "))")
            }
            if !observation.motifCues.isEmpty {
                parts.append("motifs=\(observation.motifCues.prefix(5).joined(separator: ", "))")
            }
            let setting = observation.setting.trimmed
            if !setting.isEmpty {
                parts.append("setting=\(shortSummaryText(setting, limit: 90))")
            }
            if !observation.placeCues.isEmpty {
                parts.append("place=\(observation.placeCues.prefix(3).joined(separator: ", "))")
            }
            if !observation.eraCues.isEmpty {
                parts.append("era=\(observation.eraCues.prefix(3).joined(separator: ", "))")
            }
            if !observation.energyCues.isEmpty {
                parts.append("energy=\(observation.energyCues.prefix(3).joined(separator: ", "))")
            }
            if !observation.possibleMeanings.isEmpty {
                parts.append("possible_meanings=\(observation.possibleMeanings.prefix(4).joined(separator: ", "))")
            }
            return "- \(entry.item.filename) (media_id=\(entry.item.mediaId)): \(parts.isEmpty ? "analyzed, no salient cues" : parts.joined(separator: " | "))"
        }
        if analyzed.count > limit {
            lines.append("- \(analyzed.count - limit) additional analyzed moodboard asset(s) omitted from this compact packet.")
        }
        return lines.joined(separator: "\n")
    }

    private func goalMediaArchiveSummary() -> String {
        guard !items.isEmpty else { return "" }
        let enabledItems = enabledContentItems
        let sampleSource = enabledItems.isEmpty ? sortedMediaItems(items) : enabledItems
        let imageCount = enabledItems.filter { $0.kind == .image }.count
        let videoCount = enabledItems.filter { $0.kind == .video }.count
        let observed = enabledItems.filter { mediaObservationsById[$0.mediaId] != nil }.count
        let sampleLimit = 12
        var sampleLines = sampleSource.prefix(sampleLimit).map(goalMediaArchiveLine(for:))
        if sampleSource.count > sampleLimit {
            sampleLines.append("- \(sampleSource.count - sampleLimit) additional media item(s) omitted from this compact Goal packet.")
        }
        let notes = curationById.values
            .map { $0.notes.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .prefix(4)
            .map { "- \(shortSummaryText($0, limit: 180))" }
            .joined(separator: "\n")

        return """
        Counts: \(imageCount) enabled images, \(videoCount) enabled videos, \(observed) analyzed.
        Compact sample media:
        \(sampleLines.joined(separator: "\n"))
        \(notes.isEmpty ? "" : "\nCuration notes:\n\(notes)")
        """
    }

    private func goalMediaArchiveLine(for item: MediaItemRecord) -> String {
        let curation = curation(for: item)
        var tags = Array(curation.tags.prefix(3))
        if curation.rejected {
            tags.insert("disabled", at: 0)
        }
        let tagText = tags.isEmpty ? "" : " [\(tags.joined(separator: ", "))]"
        let duration = item.durationSeconds.map { " \(durationLabel($0))" } ?? ""
        return "- \(item.kind.rawValue): \(item.relativePath) (media_id=\(item.mediaId))\(duration)\(frameSourceSummary(for: item))\(tagText)\(goalObservationSummary(for: item))"
    }

    private func observationSummary(for item: MediaItemRecord) -> String {
        guard let observation = mediaObservationsById[item.mediaId] else { return "" }
        var parts: [String] = []
        if !observation.plainCaption.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            parts.append("caption=\(observation.plainCaption)")
        }
        if !observation.literalDescription.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            parts.append("literal=\(observation.literalDescription)")
        }
        if !observation.objects.isEmpty {
            parts.append("objects=\(observation.objects.prefix(8).joined(separator: ", "))")
        }
        if !observation.activities.isEmpty {
            parts.append("activities=\(observation.activities.prefix(5).joined(separator: ", "))")
        }
        if !observation.setting.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            parts.append("setting=\(observation.setting)")
        }
        if !observation.possibleMeanings.isEmpty {
            parts.append("possible_meanings=\(observation.possibleMeanings.prefix(5).joined(separator: ", "))")
        }
        return parts.isEmpty ? " observed=true" : " observation{\(parts.joined(separator: " | "))}"
    }

    private func goalObservationSummary(for item: MediaItemRecord) -> String {
        guard let observation = mediaObservationsById[item.mediaId] else { return "" }
        var parts: [String] = []
        let caption = observation.plainCaption.trimmingCharacters(in: .whitespacesAndNewlines)
        if !caption.isEmpty {
            parts.append("caption=\(shortSummaryText(caption, limit: 140))")
        }
        let setting = observation.setting.trimmingCharacters(in: .whitespacesAndNewlines)
        if !setting.isEmpty {
            parts.append("setting=\(shortSummaryText(setting, limit: 90))")
        }
        if !observation.objects.isEmpty {
            parts.append("objects=\(observation.objects.prefix(5).joined(separator: ", "))")
        }
        if !observation.possibleMeanings.isEmpty {
            parts.append("meanings=\(observation.possibleMeanings.prefix(3).joined(separator: ", "))")
        }
        return parts.isEmpty ? " observed=true" : " observation{\(parts.joined(separator: " | "))}"
    }

    private func goalInterviewFailureStatus(for error: Error) -> String {
        goalInterviewDidTimeout(error) ? "Goal interview timed out" : "Goal interview failed"
    }

    private func goalInterviewFailureMessage(for error: Error) -> String {
        if goalInterviewDidTimeout(error) {
            return "Goal interview timed out while waiting for OpenAI. Try again; if it repeats, use a shorter message or fewer media references."
        }
        return error.localizedDescription
    }

    private func goalInterviewDidTimeout(_ error: Error) -> Bool {
        let nsError = error as NSError
        let message = error.localizedDescription.lowercased()
        return (nsError.domain == NSURLErrorDomain && nsError.code == NSURLErrorTimedOut)
            || message.contains("timed out")
    }

    private func appendMediaAnalysisLog(kind: String, message: String) {
        mediaAnalysisLogEntries.append(MediaAnalysisLogEntry(
            timestamp: DateFormats.now(),
            kind: kind,
            message: message
        ))
        let maximumTailEntries = 240
        if mediaAnalysisLogEntries.count > maximumTailEntries {
            mediaAnalysisLogEntries.removeFirst(mediaAnalysisLogEntries.count - maximumTailEntries)
        }
    }

    /// Records one image/video generation event to BOTH the `swift run`
    /// console and the in-app generation feed (Lens sidebar "Logs" tab). Kinds
    /// use a stable `domain.phase` shape (e.g. "video.completed", "image.error")
    /// so the UI can pick an icon/colour.
    func logGeneration(kind: String, message: String) {
        print("[generation] \(kind) \(message)")
        generationLogEntries.append(MediaAnalysisLogEntry(
            timestamp: DateFormats.now(),
            kind: kind,
            message: message
        ))
        let maximumTailEntries = 240
        if generationLogEntries.count > maximumTailEntries {
            generationLogEntries.removeFirst(generationLogEntries.count - maximumTailEntries)
        }
    }

    private func finishCancelledMediaAnalysis(
        analyzedCount: Int,
        skippedCount: Int,
        savedObservationCount: Int
    ) {
        if analyzedCount == 0 && skippedCount == 0 {
            mediaAnalysisStatus = "Media analysis cancelled before the next item"
        } else {
            mediaAnalysisStatus = "Media analysis cancelled after \(analyzedCount) saved\(skippedCount == 0 ? "" : ", \(skippedCount) skipped")"
        }
        appendMediaAnalysisLog(
            kind: "summary",
            message: "Summary before cancel: \(analyzedCount) analyzed, \(skippedCount) skipped, \(savedObservationCount) saved observation\(savedObservationCount == 1 ? "" : "s")."
        )
        appendMediaAnalysisLog(
            kind: "cancelled",
            message: "Media analysis cancelled. Already saved observations were preserved."
        )
        mediaAnalysisRunState = .cancelled
        if analyzedCount > 0 {
            touchCurrentProject()
        }
        isAnalyzingMedia = false
        resetMediaAnalysisCancelIntent()
    }

    private func resetMediaAnalysisCancelIntent() {
        mediaAnalysisCancelArmed = false
        mediaAnalysisCancelRequested = false
    }

    private func mediaAnalysisObservationSummary(_ observation: ImageObservationResult) -> String {
        var parts: [String] = []
        let caption = observation.plainCaption.trimmingCharacters(in: .whitespacesAndNewlines)
        if !caption.isEmpty {
            parts.append(shortTailText(caption, limit: 110))
        }
        let setting = observation.setting.trimmingCharacters(in: .whitespacesAndNewlines)
        if !setting.isEmpty {
            parts.append("setting: \(shortTailText(setting, limit: 72))")
        }
        if !observation.objects.isEmpty {
            parts.append("objects: \(observation.objects.prefix(5).joined(separator: ", "))")
        }
        if !observation.activities.isEmpty {
            parts.append("activities: \(observation.activities.prefix(4).joined(separator: ", "))")
        }
        if !observation.possibleMeanings.isEmpty {
            parts.append("meanings: \(observation.possibleMeanings.prefix(3).joined(separator: ", "))")
        }
        return parts.isEmpty ? "observation saved" : parts.joined(separator: " · ")
    }

    private func shortTailText(_ value: String, limit: Int) -> String {
        let compact = value
            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
        guard compact.count > limit else { return compact }
        let cutoff = compact.index(compact.startIndex, offsetBy: max(0, limit - 1))
        return String(compact[..<cutoff]) + "..."
    }

    private func frameSourceSummary(for item: MediaItemRecord) -> String {
        guard item.isExtractedVideoFrame || item.isCollectedShotFrame,
              let sourceMediaId = item.sourceMediaId,
              !sourceMediaId.isEmpty else {
            return ""
        }
        let sourceName = items.first { $0.mediaId == sourceMediaId }?.relativePath ?? sourceMediaId
        let seconds = item.sourceTimestampSeconds.map { " at \(durationLabel($0))" } ?? ""
        return " frame_from=\(sourceName)\(seconds)"
    }

    private func mediaObservationInput(for item: MediaItemRecord) throws -> MediaObservationInput {
        let thumbnailURL = URL(fileURLWithPath: item.thumbnailPath)
        let sourceURL = URL(fileURLWithPath: item.path)
        let inputURL = FileManager.default.fileExists(atPath: thumbnailURL.path) ? thumbnailURL : sourceURL
        let data = try Data(contentsOf: inputURL)
        let size = imagePixelSize(from: data)
        return MediaObservationInput(
            data: data,
            url: inputURL,
            mimeType: imageMimeType(for: inputURL),
            sha256: sha256Hex(data),
            width: size?.width ?? item.width,
            height: size?.height ?? item.height
        )
    }

    private func bootstrapMediaAnalysisMemory(with observationsById: [String: ImageObservationResult]) {
        guard observationsById.values.contains(where: \.isCurrentAestheticObservationVersion) else { return }
        do {
            _ = try mediaAnalysisMemoryStore.bootstrapNeutralObservations(observationsById)
        } catch {
            appendMediaAnalysisLog(
                kind: "cache_error",
                message: "Media analysis memory bootstrap failed: \(error.localizedDescription)"
            )
        }
    }

    private func bootstrapMediaAnalysisMemory(from projects: [ProjectRecord]) {
        for project in projects {
            bootstrapMediaAnalysisMemory(with: contextStore.loadMediaObservations(for: project))
        }
    }

    private func cachedMediaObservation(
        for key: MediaAnalysisMemoryKey,
        item: MediaItemRecord,
        index: Int,
        total: Int
    ) -> ImageObservationResult? {
        do {
            return try mediaAnalysisMemoryStore.loadObservation(for: key)
        } catch {
            appendMediaAnalysisLog(
                kind: "cache_error",
                message: "Cache lookup failed \(index + 1)/\(total) for \(item.filename): \(error.localizedDescription)"
            )
            return nil
        }
    }

    /// The second cache key: the original file's hash, so a copied source whose
    /// thumbnail re-encodes differently still reuses its analysis.
    private func cachedMediaObservation(
        sourceSha256: String,
        item: MediaItemRecord,
        index: Int,
        total: Int
    ) -> ImageObservationResult? {
        guard !sourceSha256.isEmpty else { return nil }
        do {
            return try mediaAnalysisMemoryStore.loadObservation(sourceSha256: sourceSha256)
        } catch {
            appendMediaAnalysisLog(
                kind: "cache_error",
                message: "Cache lookup by content hash failed \(index + 1)/\(total) for \(item.filename): \(error.localizedDescription)"
            )
            return nil
        }
    }

    private func saveObservationToMediaAnalysisMemory(
        _ observation: ImageObservationResult,
        key: MediaAnalysisMemoryKey,
        item: MediaItemRecord,
        sourceSha256: String = ""
    ) {
        do {
            try mediaAnalysisMemoryStore.saveObservation(observation, for: key, sourceSha256: sourceSha256)
        } catch {
            appendMediaAnalysisLog(
                kind: "cache_error",
                message: "Cache save failed for \(item.filename): \(error.localizedDescription)"
            )
        }
    }

    private func imageMimeType(for url: URL) -> String {
        switch url.pathExtension.lowercased() {
        case "jpg", "jpeg":
            return "image/jpeg"
        case "png":
            return "image/png"
        case "webp":
            return "image/webp"
        default:
            return "image/jpeg"
        }
    }

    private func stampedMediaObservation(
        _ observation: ImageObservationResult,
        item: MediaItemRecord,
        input: MediaObservationInput,
        model: String,
        generatedAt: String
    ) -> ImageObservationResult {
        var stamped = observation
        stamped.schemaVersion = MediaObservationConstants.schemaVersion
        stamped.mediaId = item.mediaId
        stamped.frameId = item.isExtractedVideoFrame ? item.mediaId : ""
        stamped.sourcePath = item.path
        stamped.imageHash = input.sha256
        stamped.observationProvider = "openai"
        stamped.model = model
        stamped.promptVersion = MediaObservationConstants.promptVersion
        stamped.createdAt = generatedAt
        stamped.sourceImagePath = item.path
        stamped.sourceImageSha256 = item.path == input.url.path ? input.sha256 : ""
        stamped.visionInputKind = "thumbnail_base"
        stamped.visionInputPath = input.url.path
        stamped.visionInputSha256 = input.sha256
        stamped.visionInputWidth = input.width
        stamped.visionInputHeight = input.height
        stamped.visionInputBytes = input.data.count
        stamped.visionThumbnailProfile = "base"
        stamped.fullresVisionAllowed = false
        stamped.thumbnailPolicyVersion = MediaObservationConstants.thumbnailPolicyVersion
        stamped.userProvidedContext = UserProvidedContext()
        stamped.detailPassUsed = false
        stamped.detailVisionInputKind = ""
        stamped.detailVisionInputPath = ""
        stamped.detailVisionInputSha256 = ""
        stamped.detailVisionInputWidth = 0
        stamped.detailVisionInputHeight = 0
        stamped.detailVisionInputBytes = 0
        stamped.detailVisionThumbnailProfile = ""
        stamped.objectDescriptionPassUsed = false
        return stamped
    }

    private func durationLabel(_ value: Double) -> String {
        let seconds = Int(value.rounded())
        let hours = seconds / 3600
        let minutes = (seconds % 3600) / 60
        let remainder = seconds % 60
        if hours > 0 {
            return String(format: "%d:%02d:%02d", hours, minutes, remainder)
        }
        return String(format: "%d:%02d", minutes, remainder)
    }

    private func currentAestheticJSON() -> String {
        let packet = promptSafeLensSetPacket(projectLenses, readyLensSetHash: readyLensSetHashValue)
        guard let data = try? JSONCoding.prettyEncoder.encode(packet),
              let text = String(data: data, encoding: .utf8) else {
            return ""
        }
        return text
    }

    private func currentArchiveMeaningJSON() -> String {
        guard projectArchiveMeaning.hasSignals,
              let data = try? projectArchiveMeaning.encoded(),
              let text = String(data: data, encoding: .utf8) else {
            return ""
        }
        return text
    }

    private func scan(
        project: ProjectRecord,
        projectId: String,
        sources: [MediaSourceRecord],
        autoOpenNewSingleVideo: Bool = false
    ) async {
        let preexistingIds = Set(items.map(\.mediaId))
        let preservedDerivedItems = items.filter { item in
            (item.isExtractedVideoFrame || item.isGeneratedMedia || item.isVideoTrim)
                && FileManager.default.fileExists(atPath: item.path)
        }
        var updatedSources: [MediaSourceRecord] = []
        var scannedItems: [MediaItemRecord] = []
        var totalErrors = 0

        for (index, source) in sources.enumerated() {
            scanStatus = "Scanning \(source.displayName) (\(index + 1)/\(sources.count))"
            let result = await store.scan(source: source, for: project) { [weak self] progress in
                guard let self else { return }
                if progress.isScanning {
                    let name = progress.currentFile.isEmpty ? source.displayName : progress.currentFile
                    self.scanStatus = "Scanning \(name) - \(progress.scannedCount) indexed"
                } else {
                    self.scanStatus = "Finished \(source.displayName)"
                }
            }
            updatedSources.append(result.source)
            scannedItems.append(contentsOf: result.items)
            totalErrors += result.progress.errorCount
        }

        do {
            let refreshedItems = sortedMediaItems(deduplicatedMediaItems(scannedItems + preservedDerivedItems))
            try store.saveSources(updatedSources, for: project)
            try store.saveInventory(refreshedItems, for: project)
            var updatedProject = project
            updatedProject.updatedAt = DateFormats.now()
            try projectLibrary.saveProject(updatedProject)
            reloadProjects(selecting: projectId)
            let count = refreshedItems.count
            scanStatus = totalErrors == 0
                ? "Indexed \(count) media item\(count == 1 ? "" : "s")"
                : "Indexed \(count) media item\(count == 1 ? "" : "s") with \(totalErrors) scan issue\(totalErrors == 1 ? "" : "s")"
            if autoOpenNewSingleVideo, currentProject?.projectId == projectId {
                let newItems = refreshedItems.filter {
                    !preexistingIds.contains($0.mediaId) && $0.scanError == nil
                }
                let newVideos = newItems.filter { $0.kind == .video }
                if newVideos.count == 1, newItems.allSatisfy({ $0.kind == .video }) {
                    studioAutoOpenVideo = newVideos[0]
                }
            }
        } catch {
            lastError = error.localizedDescription
            scanStatus = "Could not save library scan"
        }

        isScanning = false
    }

    private func scan(
        sources sourcesToScan: [MediaSourceRecord],
        project: ProjectRecord,
        autoOpenNewSingleVideo: Bool = false
    ) {
        guard !sourcesToScan.isEmpty else {
            scanStatus = "Add media first"
            return
        }
        guard !isScanning else { return }

        let projectId = project.projectId
        isScanning = true
        lastError = ""
        scanStatus = "Scanning \(sourcesToScan.count) source\(sourcesToScan.count == 1 ? "" : "s")"

        Task { [weak self] in
            guard let self else { return }
            await self.scan(
                project: project,
                projectId: projectId,
                sources: sourcesToScan,
                autoOpenNewSingleVideo: autoOpenNewSingleVideo
            )
        }
    }

    private func updateCuration(mediaId: String, mutate: (inout MediaCurationRecord) -> Void) {
        guard let project = currentProject else { return }
        do {
            var record = curationById[mediaId] ?? MediaCurationRecord(mediaId: mediaId)
            mutate(&record)
            record.updatedAt = DateFormats.now()
            var updated = curationById
            updated[mediaId] = record
            try store.saveCuration(updated, for: project)
            curationById = updated
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func touchCurrentProject() {
        guard var project = currentProject else { return }
        do {
            project.updatedAt = DateFormats.now()
            try projectLibrary.saveProject(project)
            currentProject = project
            if let index = projects.firstIndex(where: { $0.projectId == project.projectId }) {
                projects[index] = project
            }
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func reconcileSelectedItem() {
        let visibleItems = filteredItems
        if let selectedItemId, visibleItems.contains(where: { $0.mediaId == selectedItemId }) {
            if let playingMediaId, !visibleItems.contains(where: { $0.mediaId == playingMediaId }) {
                stopVideoPlayback()
            }
            return
        }
        selectedItemId = visibleItems.first?.mediaId
        stopVideoPlayback()
    }

    private func screenSessionCount(for project: ProjectRecord) -> Int {
        let sessionsURL = projectLibrary.sessionsDirectory(for: project)
        guard let children = try? FileManager.default.contentsOfDirectory(
            at: sessionsURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        ) else {
            return 0
        }
        return children.filter { url in
            (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true
        }.count
    }

    private func hydratedRecordCount(for project: ProjectRecord) -> Int {
        let sessionsURL = projectLibrary.sessionsDirectory(for: project)
        guard let children = try? FileManager.default.contentsOfDirectory(
            at: sessionsURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        ) else {
            return 0
        }

        return children.reduce(0) { total, sessionURL in
            let analysisURL = sessionURL.appendingPathComponent("analysis.jsonl")
            guard let text = try? String(contentsOf: analysisURL, encoding: .utf8) else { return total }
            return total + text.split(separator: "\n").count
        }
    }
}

/// A character the user can use as optional context for the reframe Viewpoint camera.
/// Identity-first grouping of a media version's character/object takes: the roster
/// identity (name, references, description) anchors the group and its render takes
/// hang off it. Produced by lensCharacterTakeGroups / lensObjectTakeGroups for the
/// workbench sidebar; never persisted.
struct LensIdentityTakeGroup: Identifiable {
    enum Membership {
        /// In the scene (selected on the media plan, or implied by the lens cast).
        case cast
        /// A roster character with takes here but not currently in the scene.
        case notCast
        /// Residual takes that cannot be attributed to any identity.
        case unlabeled
    }

    let id: String
    let displayName: String
    /// Roster character link when resolved; empty for objects and residual groups.
    let characterId: String
    /// Roster object link when resolved; empty for characters and residual groups.
    var objectId: String = ""
    let referenceMediaIds: [String]
    let descriptionPrompt: String
    let membership: Membership
    let takes: [ProjectLensHeroImage]

    /// The roster entry this group resolves to — character or object; empty for
    /// residual/unlabeled groups.
    var rosterId: String { characterId.isEmpty ? objectId : characterId }
}

/// One place of the scene and the scenery frames it owns — the Places sidebar row
/// and detail-panel unit. `placeId` is the roster link (empty for legacy areas not
/// yet rosterized, and for the residual group).
struct LensPlaceFrameGroup: Identifiable {
    let id: String
    let placeId: String
    let areaId: String
    let displayName: String
    let descriptionPrompt: String
    let referenceMediaIds: [String]
    let frames: [ProjectLensHeroImage]
}

struct LensReframeCastCandidate: Identifiable, Hashable, Sendable {
    var id: String
    var name: String
    var prompt: String
    var signatureProps: [String]
    var environmentAffinity: String

    /// The full description snapshot stored on the reframe spec, so the generation
    /// prompt keeps the character's props and belonging even if the roster changes.
    var compositePrompt: String {
        var parts = [prompt.trimmed]
        if !signatureProps.isEmpty {
            parts.append("Signature props: \(signatureProps.joined(separator: ", "))")
        }
        if !environmentAffinity.trimmed.isEmpty {
            parts.append("Visually belongs to: \(environmentAffinity.trimmed)")
        }
        return parts.filter { !$0.isEmpty }.joined(separator: ". ")
    }
}

/// Composes reframe generation text. The prompt body may be rewritten by enrichment,
/// so the coordinates and camera directive also live in the attachment descriptor,
/// which the runner appends to the final prompt verbatim after enrichment.
enum LensReframeComposer {
    static func percent(_ value: Double) -> Int {
        Int((min(1, max(0, value)) * 100).rounded())
    }

    static func rotationDegreesLabel(_ rotationDegrees: Double) -> Int {
        Int(abs(rotationDegrees).rounded())
    }

    static func rotationDirectionLabel(_ rotationDegrees: Double) -> String {
        rotationDegrees > 0 ? "clockwise" : "counterclockwise"
    }

    /// One law for tilted selections: the rectangle's top edge is the output's
    /// top. Empty when level so the token vanishes from rendered prompts.
    static func rotationClause(spec: LensReframeSpec) -> String {
        guard spec.rotationDegrees != 0 else { return "" }
        let degrees = rotationDegreesLabel(spec.rotationDegrees)
        let direction = rotationDirectionLabel(spec.rotationDegrees)
        if spec.isViewpoint {
            return "Roll the new camera \(degrees)° \(direction) relative to the source horizon — the tilted selection's top edge defines the new frame's up direction; the focus crop attachment is already presented in that orientation."
        }
        return "In the source frame the selected rectangle is tilted \(degrees)° \(direction) (a Dutch angle); the focus crop attachment already shows it straightened. Compose the new image level and right-side-up — the selection's top edge is the top of the new frame."
    }

    static func prompt(
        spec rawSpec: LensReframeSpec,
        parent: ProjectLensHeroImage,
        model: String = "",
        promptSettings: ProjectPromptSettingsDocument = .empty(),
        promptBody: String = ""
    ) -> String {
        let spec = rawSpec.normalized()
        let templateBody = promptBody.trimmed.isEmpty
            ? promptSettings.reframeTemplate(mode: spec.mode, model: model).body
            : promptBody
        return renderTemplate(templateBody, spec: spec, parent: parent)
    }

    static func renderDefaultPromptBody(
        spec rawSpec: LensReframeSpec,
        parent: ProjectLensHeroImage,
        model: String,
        promptSettings: ProjectPromptSettingsDocument
    ) -> String {
        let spec = rawSpec.normalized()
        let template = promptSettings.reframeTemplate(mode: spec.mode, model: model)
        let body = renderTemplate(template.body, spec: spec, parent: parent)
        // Zoom fidelity rides in the SEEDED body only (visible + editable);
        // the submit path never re-appends it over the user's edits.
        let fidelityLine = spec.isZoom ? spec.resolvedFidelity.promptLine : ""
        return fidelityLine.isEmpty ? body : body + "\n\n" + fidelityLine
    }

    private static func renderTemplate(
        _ template: String,
        spec: LensReframeSpec,
        parent: ProjectLensHeroImage
    ) -> String {
        let context = RosterMentionResolver.strippingMentionTokens(
            parent.sourcePrompt.isEmpty ? parent.prompt : parent.sourcePrompt
        )
        let characterContext: String
        if spec.characterName.isEmpty && spec.characterPrompt.isEmpty {
            characterContext = ""
        } else {
            let name = spec.characterName.isEmpty ? "Selected character" : spec.characterName
            let description = spec.characterPrompt.isEmpty ? "" : ": \(spec.characterPrompt)"
            characterContext = "\nUse optional character context only for camera height, embodiment, and plausible placement: \(name)\(description)."
        }
        let sourceRect = spec.zoomOutSourceRect
        let replacements = [
            "{{focus_x_percent}}": "\(percent(spec.centerX))",
            "{{focus_y_percent}}": "\(percent(spec.centerY))",
            "{{focus_width_percent}}": "\(percent(spec.normalizedWidth))",
            "{{focus_height_percent}}": "\(percent(spec.normalizedHeight))",
            "{{source_scale_percent}}": "\(percent(spec.zoomOutSourceScale))",
            "{{zoom_out_percent}}": "\(percent(spec.zoomOutAmount))",
            "{{margin_left_percent}}": "\(percent(sourceRect.minX))",
            "{{margin_right_percent}}": "\(percent(1 - sourceRect.maxX))",
            "{{margin_top_percent}}": "\(percent(sourceRect.minY))",
            "{{margin_bottom_percent}}": "\(percent(1 - sourceRect.maxY))",
            "{{view_direction}}": spec.resolvedViewDirection.promptPhrase,
            "{{character_name}}": spec.characterName,
            "{{character_prompt}}": spec.characterPrompt,
            "{{character_context}}": characterContext,
            "{{focus_rotation_degrees}}": "\(rotationDegreesLabel(spec.rotationDegrees))",
            "{{focus_rotation_clause}}": rotationClause(spec: spec),
            "{{original_scene_context}}": context.isEmpty ? "No original scene context saved." : context
        ]
        var rendered = template
        for (token, value) in replacements {
            rendered = rendered.replacingOccurrences(of: token, with: value)
        }
        return rendered
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
            .split(separator: "\n", omittingEmptySubsequences: false)
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .joined(separator: "\n")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func attachmentDescriptor(spec: LensReframeSpec) -> String {
        spec.isViewpoint || spec.isZoomOut
            ? fullFrameAttachmentDescriptor(spec: spec)
            : focusCropAttachmentDescriptor(spec: spec)
    }

    static func fullFrameAttachmentDescriptor(spec: LensReframeSpec) -> String {
        let cx = percent(spec.centerX)
        let cy = percent(spec.centerY)
        if spec.isZoomOut {
            let sourceRect = spec.zoomOutSourceRect
            return "REFRAME source frame / LOCKED source inset - preserve this image unchanged inside the wider result. It occupies \(percent(spec.zoomOutSourceScale))% of the output, centered \(cx)% from the left and \(cy)% from the top. Generate only the surrounding perimeter: \(percent(sourceRect.minX))% left, \(percent(1 - sourceRect.maxX))% right, \(percent(sourceRect.minY))% above, and \(percent(1 - sourceRect.maxY))% below. Continue perspective, geography, lighting, palette, materials, and style seamlessly."
        }
        if spec.isViewpoint {
            let character = spec.characterName.isEmpty ? "" : " Optional character context: \(spec.characterName)."
            let roll = spec.rotationDegrees == 0
                ? ""
                : " Roll the new camera \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)) relative to this frame's horizon."
            return "REFRAME source frame / full source frame - the original rendered scene. The new image places the camera at the point centered \(cx)% from the left and \(cy)% from the top of this image, looking \(spec.resolvedViewDirection.promptPhrase).\(roll) Preserve this world's geography, recurring subjects, palette, and rendering style. Do not copy the original camera's framing.\(character)"
        }
        let tilt = spec.rotationDegrees == 0
            ? ""
            : " The focus rectangle is tilted \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)) within this frame; the final image must be level, matching the straightened focus crop."
        return "REFRAME source frame / full source frame - the original rendered scene. Use this for broader world geography, recurring subjects, palette, and rendering style. The focus region is centered \(cx)% from the left and \(cy)% from the top.\(tilt)"
    }

    /// The selection occupies the central 1/contextScale of the padded crop
    /// attachment; telling the model that fraction is what makes the zoom
    /// magnitude exact instead of guessed.
    static func selectionPercentOfCrop(spec: LensReframeSpec) -> Int {
        let scale = max(1, spec.resolvedFidelity.contextScale)
        return max(1, min(100, Int((100.0 / scale).rounded())))
    }

    static func focusCropAttachmentDescriptor(spec: LensReframeSpec) -> String {
        let cx = percent(spec.centerX)
        let cy = percent(spec.centerY)
        if spec.isViewpoint {
            let straightened = spec.rotationDegrees == 0
                ? ""
                : " This crop is presented straightened from a selection tilted \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)) in the source; its orientation is the new frame's up direction."
            return "REFRAME source crop / focus crop - the clicked camera-origin region from the original rendered frame, centered \(cx)% from the left and \(cy)% from the top.\(straightened) Use it to understand the immediate starting point for a new view looking \(spec.resolvedViewDirection.promptPhrase), while preserving the full source frame's world geography."
        }
        let central = selectionPercentOfCrop(spec: spec)
        let straightened = spec.rotationDegrees == 0
            ? ""
            : " This crop is presented STRAIGHTENED: in the original frame the selection is tilted \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)), and this crop's edges are the selection's true edges — generate the image level, top edge up."
        return "REFRAME source crop / focus crop - a 16:9 region cropped from the original rendered frame around the selection, centered \(cx)% from the left and \(cy)% from the top of the full frame.\(straightened) This crop includes surrounding context for reference: the SELECTED region is its central \(central)% (by width). The new image is that selected region recomposed as the full frame — match its exact framing and magnification; keep geography, subjects, palette, and rendering style exactly; sharpen and extend detail, add nothing foreign."
    }

    static func cameraMapAttachmentDescriptor(spec: LensReframeSpec) -> String {
        let cx = percent(spec.centerX)
        return "REFRAME camera map / top-down schematic - a DIAGRAM stating the requested camera move, not a rendering of the scene: marker A at the bottom is the original camera with its view of the source frame (the rectangle); marker B is the requested new vantage point, placed \(cx)% across the frame at a depth read from the source (higher in the source frame = farther from A); the arrow at B is the new look direction (\(spec.resolvedViewDirection.promptPhrase), restated in plan space). Use it ONLY to understand the spatial relationship between the original camera and the requested one — take all visual content from the other reference images."
    }

    static func compositeAttachmentDescriptor(spec: LensReframeSpec) -> String {
        let cx = percent(spec.centerX)
        let cy = percent(spec.centerY)
        if spec.isViewpoint {
            let character = spec.characterName.isEmpty ? "" : " Optional character context: \(spec.characterName)."
            let roll = spec.rotationDegrees == 0
                ? ""
                : " Roll the new camera \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)) relative to the left panel's horizon; the crop panel is already presented in that orientation."
            if spec.includeCameraMap {
                return "REFRAME composite reference - left panel is the full original scene for world continuity; upper-right panel is the clicked camera-origin crop centered \(cx)% from the left and \(cy)% from the top; lower-right panel is a top-down CAMERA MAP schematic — a diagram of the requested move (A = original camera, B = requested vantage, arrow = B's look direction; higher in the source frame = farther from A), not scene content.\(roll) Generate a new view from point B looking \(spec.resolvedViewDirection.promptPhrase), while preserving the left panel's world geography and rendering style.\(character)"
            }
            return "REFRAME composite reference - left panel is the full original scene for world continuity; right panel is the clicked camera-origin crop centered \(cx)% from the left and \(cy)% from the top.\(roll) Generate a new view from that point looking \(spec.resolvedViewDirection.promptPhrase), while preserving the left panel's world geography and rendering style.\(character)"
        }
        let central = selectionPercentOfCrop(spec: spec)
        let straightened = spec.rotationDegrees == 0
            ? ""
            : " The right panel is presented STRAIGHTENED from a selection tilted \(rotationDegreesLabel(spec.rotationDegrees))° \(rotationDirectionLabel(spec.rotationDegrees)) in the left panel — generate the image level, matching the right panel's orientation."
        return "REFRAME composite reference - left panel is the full original scene for world continuity; right panel is a 16:9 focus crop centered \(cx)% from the left and \(cy)% from the top of the full frame, whose central \(central)% (by width) is the SELECTED region.\(straightened) Generate that selected region as a complete full-frame zoom at exactly that magnification, preserving the left panel's world geography and rendering style."
    }
}

/// Composes the OpenAI request that writes a Lens take's voice-over script.
enum LensNarrationComposer {
    static func scriptPrompt(lensTitle: String, subjectSummary: String, imagePrompt: String) -> String {
        var lines: [String] = []
        lines.append("Write a short spoken voice-over for a single rendered concept image from a visual world. The narration plays while the viewer looks at the image.")
        lines.append("")
        let title = lensTitle.trimmed
        if !title.isEmpty {
            lines.append("The world: \(title)")
        }
        let subject = subjectSummary.trimmed
        if !subject.isEmpty {
            lines.append("The subject of the image: \(subject)")
        }
        let prompt = imagePrompt.trimmed
        if !prompt.isEmpty {
            lines.append("What the image shows: \(prompt)")
        }
        lines.append("")
        lines.append("Rules:")
        lines.append("- 2 to 3 sentences, 25 to 45 words total — roughly ten to sixteen seconds spoken aloud.")
        lines.append("- Present tense, as an unseen narrator inside this world's mood; never address the viewer.")
        lines.append("- Evocative and concrete: name what is seen and what it implies. Add nothing the image contradicts.")
        lines.append("- Plain spoken prose only: no camera or art-direction words (image, render, style, shot, frame), no greetings, no title, no quotation marks.")
        return lines.joined(separator: "\n")
    }
}
